def _ma_context(sym: str, live_price) -> dict | None:
    """Build a moving-average / entry-helper context for a symbol from the finviz enrichment cache:
    price vs SMA20/50/200 (derive the absolute MA from live price + finviz %-from-price), RSI, RVOL,
    ATR%, plus a plain-English entry hint. VWAP is intraday-only (set when a snapshot has it)."""
    d = (_enrich_cache() or {}).get(str(sym or "").upper())
    if not isinstance(d, dict) or not d:
        return None

    def _f(k):
        try:
            v = d.get(k)
            return float(v) if v is not None else None
        except (TypeError, ValueError):
            return None

    try:
        px = float(live_price) if live_price else None
    except (TypeError, ValueError):
        px = None
    out: dict = {"rsi": _f("rsi"), "rvol": _f("rvol"), "atr": _f("atr"), "source": "finviz"}
    if px and out["atr"]:
        out["atr_pct"] = round(out["atr"] / px * 100, 2)
    mas = []
    for label, pk in (("SMA20", "sma20_pct"), ("SMA50", "sma50_pct"), ("SMA200", "sma200_pct")):
        pct = _f(pk)  # finviz: % the live price sits ABOVE the MA (price = ma*(1+pct/100))
        if pct is None:
            continue
        ma_price = round(px / (1 + pct / 100), 2) if (px and pct != -100) else None
        mas.append({"label": label, "pct_above": round(pct, 2), "price": ma_price, "above": pct >= 0})
    out["mas"] = mas
    # Intraday session VWAP (cached) — institutional entry anchor: longs prefer entries near/below VWAP.
    vw = (_vwap_cache() or {}).get(str(sym or "").upper())
    if isinstance(vw, dict) and vw.get("vwap"):
        out["vwap"] = vw.get("vwap")
        out["above_vwap"] = vw.get("above_vwap")
        out["vwap_dist_pct"] = vw.get("dist_pct")
        out["vwap_at"] = vw.get("computed_at")
    # Entry hint — trend posture from the stack + RSI extremes + VWAP location (advisory).
    above_ct = sum(1 for m in mas if m["above"])
    rsi = out["rsi"]
    if mas:
        if above_ct == len(mas):
            hint = "Above all MAs — uptrend; buy pullbacks toward SMA20"
        elif above_ct == 0:
            hint = "Below all MAs — downtrend; wait for reclaim of SMA20/50"
        else:
            hint = "Mixed MA stack — chop; wait for a clean SMA20/50 break"
        if out.get("vwap") is not None:
            hint += (
                " · below VWAP (better long entry)"
                if not out.get("above_vwap")
                else " · above VWAP (extended, wait for pullback)"
            )
        if rsi is not None and rsi >= 70:
            hint += " · RSI overbought, avoid chasing"
        elif rsi is not None and rsi <= 30:
            hint += " · RSI oversold, watch for reversal"
        out["entry_hint"] = hint
    return out


# Cache overridden symbols for 60s so we don't query DB on every page load
_override_cache = {"symbols": set(), "ts": 0}


def _get_stop_overrides() -> set:
    """Get symbols with HOLD_OVERRIDE (24h) or active snooze. Cached 60s."""
    import time as _t

    if _t.time() - _override_cache["ts"] < 60:
        return _override_cache["symbols"]
    try:
        rows = (
            _db_query(
                "SELECT DISTINCT symbol FROM stop_decisions WHERE decision='HOLD_OVERRIDE' AND decided_at > NOW() - INTERVAL '96 hours'"
            )
            or []
        )
        syms = {r["symbol"] for r in rows}
        sn = _db_query("SELECT symbol FROM stop_snooze WHERE snoozed_until > NOW()") or []
        syms.update(r["symbol"] for r in sn)
        _override_cache["symbols"] = syms
        _override_cache["ts"] = _t.time()
        return syms
    except Exception:
        return _override_cache["symbols"]


_STOP_READINESS_BUILD = "cc-v3 stop-lifecycle-close 2026-07-01"
_SCHWAB_VALIDATOR_CACHE = {"ts": 0.0, "result": None}


def _cached_schwab_validator():
    """validate_schwab_write_policy result, cached 5 min (the source scan is slow). READ-ONLY."""
    import time as _t
    import subprocess
    import re as _re
    import sys as _sys

    if _t.time() - _SCHWAB_VALIDATOR_CACHE["ts"] < 300 and _SCHWAB_VALIDATOR_CACHE["result"]:
        return _SCHWAB_VALIDATOR_CACHE["result"]
    res = {"pass": False, "summary": "unknown"}
    try:
        p = subprocess.run(
            [_sys.executable, str(PROJECT_ROOT / "scripts" / "validate_schwab_write_policy.py")],
            capture_output=True,
            text=True,
            timeout=90,
        )
        m = _re.search(r"(\d+)/(\d+) guards green", p.stdout)
        res = {
            "pass": bool(p.returncode == 0 and m and m.group(1) == m.group(2)),
            "summary": (m.group(0) if m else "no summary"),
            "returncode": p.returncode,
        }
    except Exception as e:
        res = {"pass": False, "summary": f"error: {str(e)[:60]}"}
    _SCHWAB_VALIDATOR_CACHE.update(ts=_t.time(), result=res)
    return res


def _stop_row_narrative(
    *,
    sym,
    is_fidelity,
    has_active_stop,
    broker_stop,
    planned_stop,
    current_price,
    qty,
    distance_pct,
    distance_atr,
    dollars_at_risk,
    is_trailing,
    trailing_should_be_active,
    trail_pct,
    trail_trigger,
    divergence,
    alert_level,
    naked,
    unrealized_dollars,
):
    """Plain-English 'what this means' + the single next action + a 2FA trade PROJECTION for one
    Stop Management row. Aligned to STOP_METHODOLOGY.md (real-account holdings are LONG; a protective
    stop is a SELL below price) and the Stop Monitoring Protocol alert tiers. Pure/deterministic —
    derives only from fields already computed for the row. Returns (narrative, next_action, projection)."""
    px = float(current_price or 0.0)
    q = float(qty or 0.0)
    dp = distance_pct if distance_pct is not None else None
    at_risk = max(float(dollars_at_risk or 0.0), 0.0)
    sell_qty = int(q) if q >= 1 else round(q, 4)
    money = lambda v: f"${abs(v):,.0f}" if v is not None else "$0"
    narrative = next_action = projection = None

    # 1) Broker stop LOOSER than advised — the one genuinely actionable divergence.
    if divergence == "broker looser than advised" and broker_stop and planned_stop and px:
        extra = (planned_stop - broker_stop) * q
        new_risk = max((px - planned_stop) * q, 0.0)
        narrative = (
            f"Your live stop ${broker_stop:.2f} sits below the advised ${planned_stop:.2f} — about "
            f"{money(extra)} MORE open risk than the methodology recommends ({dp:.1f}% below price)."
        )
        next_action = (
            f"Tighten to ${planned_stop:.2f} — cancel/modify the existing ${broker_stop:.2f} stop first "
            f"({'in ToS if placed manually' if not is_fidelity else 'in Fidelity'}), then place. "
            "A second stop is blocked to avoid a duplicate."
        )
        projection = (
            f"Move ${broker_stop:.2f}→${planned_stop:.2f} on {sell_qty} sh: open risk {money(at_risk)}→"
            f"{money(new_risk)} (−{money(extra)}); trigger tightens to {((px - planned_stop) / px * 100):.1f}% below price."
        )

    # 2) NAKED — advisor stop not placed at the broker.
    elif naked and planned_stop and px:
        if trailing_should_be_active and trail_pct:
            trig = trail_trigger or (px * (1 - trail_pct / 100.0))
            venue = "a Fidelity manual ticket (no broker API)" if is_fidelity else "🔒 Trail 2FA"
            narrative = (
                f"In profit and above trend, the methodology wants a {trail_pct:.0f}% TRAILING stop, but none is "
                f"at the broker — {money(unrealized_dollars)} of unrealized gain is unprotected."
            )
            next_action = f"Place the {trail_pct:.0f}% trailing stop via {venue}."
            projection = (
                f"SELL {sell_qty} {sym} TRAILING {trail_pct:.0f}%: initial trigger ≈${trig:.2f} "
                f"({(px - trig) / px * 100:.1f}% below), ratchets up with price; protects ≈{money(trig * q)} of position value."
            )
        else:
            venue = "a Fidelity manual ticket (no broker API)" if is_fidelity else "🔒 Set 2FA"
            risk = max((px - planned_stop) * q, 0.0)
            narrative = (
                f"Advised ${planned_stop:.2f} stop is NOT at the broker — this position is unprotected "
                f"(would sit {(px - planned_stop) / px * 100:.1f}% below price)."
            )
            next_action = f"Place the ${planned_stop:.2f} stop via {venue}."
            projection = (
                f"SELL {sell_qty} {sym} STOP ${planned_stop:.2f}: caps downside at {(px - planned_stop) / px * 100:.1f}% "
                f"({money(risk)} max loss from here); protects ≈{money(planned_stop * q)} of value."
            )

    # 3) LOCK-IN — live fixed stop, but trailing at the advised width locks a higher floor now.
    elif (
        has_active_stop
        and not is_trailing
        and trailing_should_be_active
        and trail_pct
        and broker_stop
        and px
        and trail_trigger
        and trail_trigger > broker_stop + 0.01
    ):
        venue = "a Fidelity manual ticket" if is_fidelity else "🔒 Trail 2FA"
        gap = trail_trigger - broker_stop
        narrative = (
            f"Fixed stop ${broker_stop:.2f} is live, but a {trail_pct:.0f}% trail at the current "
            f"price locks ${trail_trigger:.2f} — ${gap:.2f}/sh higher ({money(gap * q)} more protected "
            f"on {money(unrealized_dollars)} unrealized gain)."
        )
        next_action = f"Switch fixed→{trail_pct:.0f}% trailing via {venue}."
        projection = (
            f"SELL {sell_qty} {sym} TRAILING {trail_pct:.0f}%: initial trigger ≈${trail_trigger:.2f} "
            f"(vs fixed ${broker_stop:.2f}); ratchets up with price."
        )

    # 4) Active stop, price CLOSE to the trigger — protection is ON; just watch.
    elif has_active_stop and broker_stop and alert_level in ("amber", "yellow") and (dp is not None and dp <= 6.0):
        kind = "trailing" if is_trailing else "fixed"
        near = (
            "≤1 ATR"
            if (distance_atr is not None and distance_atr <= 1.0)
            else (f"{dp:.1f}%" if dp is not None else "close")
        )
        narrative = (
            f"Active {kind} stop ${broker_stop:.2f} is {near} below price — protection is ON and nearby; a normal "
            f"pullback could trigger it (only {money(at_risk)} at risk)."
        )
        next_action = (
            "Monitor — the trailing stop ratchets up automatically; no action."
            if is_trailing
            else "Monitor — stop is in place; widen only if you want more room."
        )

    # 5) Active stop, aligned/healthy.
    elif has_active_stop and broker_stop:
        kind = "trailing" if is_trailing else "fixed"
        narrative = f"Active {kind} stop ${broker_stop:.2f} matches the methodology — protection aligned."
        next_action = "None — monitored."

    return narrative, next_action, projection


def _live_policy_stop(symbol, price):
    """Deterministic family-floor stop vs live price.

    Same floor the protection advisor applies when 20d swing-low is too tight
    (`stop_policy.yaml` / holding_family). Used only when no recent LLM
    protection_advisory exists. Does not write research rows and is not an
    invented one-off dollar — it is the published band applied to the live quote.
    Returns None for cash/unstoppable funds or if the floor is not protective.
    """
    try:
        px = float(price)
    except (TypeError, ValueError):
        return None
    if px != px or px <= 0:
        return None
    sym = str(symbol or "").upper()
    if not sym:
        return None
    try:
        import holding_family as _hf

        if _hf.is_unstoppable_fund(sym) or _hf.is_mutual_fund(sym):
            return None
        fam, fam_src = _hf.classify_family(sym)
        try:
            regime = _hf.current_regime()
        except Exception:
            regime = None
        fb = _hf.protection_bounds(fam, regime=regime)
        smin = float(fb.get("stop_min_pct") or 0)
        if smin <= 0:
            return None
        stop = round(float(px) * (1.0 - smin / 100.0), 2)
        if stop <= 0 or stop >= float(px):
            return None
        smax = float(fb.get("stop_max_pct") or smin)
        label = fb.get("label") or fam
        return {
            "stop": stop,
            "stop_pct_below": smin,
            "family": fam,
            "family_source": fam_src,
            "family_floor_pct": smin,
            "family_floor": f"{label} floor {smin:g}%",
            "rec_model": "stop_policy.yaml",
            "rec_lane": "policy",
            "rationale": (
                f"No recent protection advisory. {label} band {smin:.0f}–{smax:.0f}% → "
                f"${stop:.2f} ({smin:.0f}% below live ${float(px):.2f}). Same floor the "
                f"advisor uses when swing-low is too tight."
            ),
            "evidence": [{"tag": "policy", "text": f"stop_policy.yaml {fam} floor {smin:g}% via {fam_src}"}],
            "data_i_doubt": "no recent LLM protection advisory; swing-low/ATR structure not applied",
        }
    except Exception:
        return None


def _stops_management_api(query=None):
    """GET /api/v2/stops/management — aggregation for the Portfolio → Stop Management tab. Joins broker-actual
    stops (stop_lifecycle) + holdings + advisor planned stops + portfolio heat into per-position rows with
    distance (R/ATR/$), alert level (yellow/amber/red), trailing-not-active, and broker/planned divergence.
    Read-only: no broker calls, no order placement. See docs/MOMENTUM_SCALP_STOP_MONITORING_PROTOCOL.md."""
    import time as _t

    q = query or {}
    _force = str(q.get("refresh") or "").lower() in ("1", "true", "yes")
    if not _force and _t.time() - _STOPS_MGMT_CACHE["ts"] < 90 and _STOPS_MGMT_CACHE["data"]:
        return {**_STOPS_MGMT_CACHE["data"], "cached": True}
    out = _stops_management_api_build(q)
    _STOPS_MGMT_CACHE.update(ts=_t.time(), data=out)
    return out


def _stops_management_api_build(query=None):
    q = query or {}
    HEAT_CAP = 5.0

    def _f(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return None

    # 1. broker-actual stops — LIVE Schwab/Alpaca protective stops (60s cache), same source the cards use,
    #    plus armed Fidelity software-monitored stops. (The stop_lifecycle snapshot lags and under-reports.)
    live_stops = {}
    # Was the live Schwab order read HEALTHY (not degraded/errored)? If so the broker is AUTHORITATIVE —
    # a confirmed/snapshot stop it does NOT show is STALE (order expired/cancelled) and must not be
    # resurrected as a phantom "active stop" (that hides an unprotected position AND triggers a false
    # "modify in ToS"). Only fall back to confirmations/snapshots for Schwab when the live read failed
    # (after-hours/degraded). Fidelity has no broker API, so its confirmations always stand.
    _live_read_ok = False
    _live_stops_meta = {"fetched_at": None, "live_read_ok": False, "error": None, "broker_count": 0}
    try:
        ls = _holdings_live_stops() or {}
        _read_status = ls.get("broker_stop_read_status") or {}
        _live_read_ok = bool(not ls.get("error") and ls.get("fetched_at") and not ls.get("degraded"))
        _live_stops_meta = {
            "fetched_at": ls.get("fetched_at"),
            "live_read_ok": _live_read_ok,
            "degraded": bool(ls.get("degraded")),
            "unverified_accounts": ls.get("unverified_accounts") or [],
            "read_ok_accounts": ls.get("broker_stop_read_ok_accounts") or [],
            "read_status": _read_status,
            "error": ls.get("error"),
            "broker_count": len(ls.get("by_key") or {}),
        }
        for _key, bs in (ls.get("by_key") or {}).items():
            sym = str(bs.get("symbol", "")).upper()
            acct = str(bs.get("account", ""))
            ot = str(bs.get("order_type") or "").upper()
            # A TRAILING stop carries no fixed stop_price (only a trail offset), so null price is
            # EXPECTED for trailing and must NOT drop the row — otherwise a live/manual trailing stop
            # (e.g. CSWC 5% placed on ToS) silently vanishes from the management table while the cards
            # show it. Matches the snapshot block below. Only skip a null-price NON-trailing entry.
            if bs.get("stop_price") is None and "TRAIL" not in ot:
                continue
            live_stops[(sym, acct)] = {
                "stop_price": bs.get("stop_price"),
                "order_type": ot,
                "is_trailing": "TRAIL" in ot,
                "trail_offset": bs.get("trail_offset"),
                "broker": "schwab" if acct.startswith("schwab") else ("alpaca" if "alpaca" in acct.lower() else ""),
                "status": bs.get("status"),
                "order_id": bs.get("order_id"),
                "stop_qty": _f(bs.get("qty")),  # order size (may lag held shares after size-up)
                "coverage": None,
                "stop_source": "broker",
            }
    except Exception:
        pass
    # Fidelity manual_broker_stops — belt-and-suspenders if live-stops overlay missed a row.
    try:
        from lib.fidelity_stop_sync import load_manual_protective_stops

        for (acct, sym), bs in (load_manual_protective_stops() or {}).items():
            if (sym, acct) in live_stops:
                continue
            ot = str(bs.get("order_type") or "STOP").upper()
            live_stops[(sym, acct)] = {
                "stop_price": bs.get("stop_price"),
                "order_type": ot,
                "is_trailing": "TRAIL" in ot,
                "trail_offset": bs.get("trail_offset"),
                "broker": "fidelity",
                "status": bs.get("status"),
                "order_id": bs.get("order_id"),
                "coverage": None,
                "stop_source": "fidelity_manual",
            }
    except Exception:
        pass
    # Persisted stop_lifecycle snapshot (DB only — never trigger a 60s+ broker rescan on this hot path).
    try:
        for s in _stops_lifecycle_db_snapshot().get("stops") or []:
            sym = str(s.get("symbol", "")).upper()
            acct = str(s.get("account", ""))
            sp = _f(s.get("stop_price"))
            ot = str(s.get("order_type") or "").upper()
            if (sym, acct) in live_stops:
                continue
            if acct.startswith("schwab") and _live_read_ok:
                continue  # broker authoritative — don't resurrect a stale snapshot it doesn't show
            if sp is None and "TRAIL" not in ot:
                continue
            live_stops[(sym, acct)] = {
                "stop_price": sp,
                "order_type": ot,
                "is_trailing": bool(s.get("is_trailing")) or "TRAIL" in ot,
                "broker": s.get("broker") or ("schwab" if acct.startswith("schwab") else ""),
                "coverage": s.get("coverage"),
                "lifecycle": s.get("lifecycle"),
                "health": s.get("health"),
                "flags": s.get("flags"),
                "stop_source": "broker_snapshot",
            }
    except Exception:
        pass
    # operator-confirmed live stops (stop_confirmations) — persists after-hours when the live Schwab read is
    # empty; the source the cards fall back to. Does not overwrite a fresher live-overlay entry.
    try:
        for cr in (
            _db_query(
                "SELECT symbol, account, stop_price_confirmed FROM stop_confirmations WHERE stop_confirmed = true"
            )
            or []
        ):
            sym = str(cr.get("symbol") or "").upper()
            acct = str(cr.get("account") or "")
            sp = _f(cr.get("stop_price_confirmed"))
            if sp is None or (sym, acct) in live_stops:
                continue
            if acct.startswith("schwab") and _live_read_ok:
                continue  # healthy broker read shows no such order → confirmation is stale (e.g. JEPI
                # $55 confirmed 2026-04-22 with 0 live orders); do not resurrect as a phantom
            live_stops[(sym, acct)] = {
                "stop_price": sp,
                "order_type": "STOP",
                "is_trailing": False,
                "broker": "schwab"
                if acct.startswith("schwab")
                else ("fidelity" if acct.startswith("fidelity") else ""),
                "coverage": None,
                "stop_source": "confirmed",
            }
    except Exception:
        pass
    try:
        fm = _fidelity_monitored_stops_list({"status": "armed"}) or {}
        for _key, ms in (fm.get("by_key") or {}).items():
            sym = str(ms.get("symbol", "")).upper()
            acct = str(ms.get("account", ""))
            if ms.get("stop_price") is None or (sym, acct) in live_stops:
                continue
            live_stops[(sym, acct)] = {
                "stop_price": ms.get("stop_price"),
                "order_type": "MONITORED",
                "is_trailing": False,
                "broker": "fidelity",
                "coverage": None,
                "stop_source": "monitored",
            }
    except Exception:
        pass
    # 2. holdings (all accounts)
    try:
        holds = (portfolio_holdings() or {}).get("holdings") or []
    except Exception:
        holds = []
    # 3. latest advisor planned stop per symbol (family band + swing-low anchor + atr)
    advised = {}
    try:
        for _row in (
            _db_query(
                "SELECT DISTINCT ON (symbol) symbol, evidence_json, model_used, created_at FROM hermes_research_intelligence "
                "WHERE research_type='protection_advisory' AND created_at > now()-interval '5 days' "
                "ORDER BY symbol, created_at DESC"
            )
            or []
        ):
            sym = _row.get("symbol")
            ev = _row.get("evidence_json")
            ev = ev if isinstance(ev, dict) else json.loads(ev or "{}")
            rec = ev.get("recommendation") or {}
            inp = ev.get("inputs") or {}
            _aep = _evidence_packet(rec if isinstance(rec, dict) else ev)
            advised[str(sym).upper()] = {
                "stop": _f(rec.get("stop_price")),
                "trail": rec.get("trail_recommended"),
                "trail_offset": _f(rec.get("trail_offset")),
                "stop_pct_below": _f(rec.get("stop_pct_below")),
                "atr": _f(inp.get("atr")),
                "family": ev.get("family"),
                "basis": _f(inp.get("basis_ps")),
                "sma50": _f(inp.get("sma50")),
                "rec_model": _row.get("model_used"),
                "rec_lane": ev.get("lane"),
                "rec_at": str(_row.get("created_at") or "") or None,
                "rationale": rec.get("rationale"),
                "evidence": _aep.get("evidence") or [],
                "data_i_doubt": _aep.get("data_i_doubt"),
            }
    except Exception:
        pass
    # 3a. Live policy-band suggestion when no 5-day LLM advisory exists (SCHD IRA had Plan —).
    try:
        _px_by_sym = {}
        for _h in holds:
            _s = str(_h.get("symbol") or "").upper()
            if not _s or _h.get("is_cash") or _s in ("CASH", "SPAXX", "VMFXX", "USD"):
                continue
            _px = _f(_h.get("current_price")) or _f(_h.get("price"))
            if _px and _px > 0:
                _px_by_sym[_s] = _px
        for _s, _px in _px_by_sym.items():
            if _f((advised.get(_s) or {}).get("stop")) is not None:
                continue
            _pol = _live_policy_stop(_s, _px)
            if not _pol:
                continue
            advised[_s] = {
                "stop": _pol["stop"],
                "trail": False,
                "trail_offset": None,
                "stop_pct_below": _pol["stop_pct_below"],
                "atr": None,
                "family": _pol["family"],
                "basis": None,
                "sma50": None,
                "rec_model": _pol["rec_model"],
                "rec_lane": _pol["rec_lane"],
                "rec_at": None,
                "rationale": _pol["rationale"],
                "evidence": _pol["evidence"],
                "data_i_doubt": _pol["data_i_doubt"],
            }
    except Exception:
        pass
    # 3b. Grok stop curation (external LLM R:R review on live stops)
    stop_curation = {}
    try:
        for _row in (
            _db_query(
                "SELECT DISTINCT ON (symbol) symbol, evidence_json, model_used, summary "
                "FROM hermes_research_intelligence "
                "WHERE research_type='stop_curation' AND created_at > now()-interval '14 days' "
                "ORDER BY symbol, created_at DESC"
            )
            or []
        ):
            sym = str(_row.get("symbol") or "").upper()
            ev = _row.get("evidence_json")
            ev = ev if isinstance(ev, dict) else json.loads(ev or "{}")
            _cep = _evidence_packet(ev)
            stop_curation[sym] = {
                "grade": ev.get("grade"),
                "recommendation": ev.get("recommendation"),
                "rr_assessment": ev.get("rr_assessment"),
                "suggested_action": ev.get("suggested_action"),
                "model": _row.get("model_used"),
                "summary": (_row.get("summary") or "")[:200],
                "evidence": _cep.get("evidence") or [],
                "data_i_doubt": _cep.get("data_i_doubt"),
            }
    except Exception:
        pass
    # 4. strategy/route per symbol
    route = {}
    try:
        for r in _db_query("SELECT symbol, strategy_type FROM ticker_strategy_classifications WHERE active=TRUE") or []:
            st = str(r.get("strategy_type") or "")
            route[str(r.get("symbol") or "").upper()] = (
                "Social+Momentum"
                if "social" in st.lower()
                else "Pure Momentum"
                if "momentum_scalp" in st
                else st or "core-hold"
            )
    except Exception:
        pass
    # 5. portfolio heat + regime
    heat_pct = total_risk = 0.0
    try:
        # Fail-closed: never invent a missing helper. Canonical source is risk_management.json
        # (same store other api_v2 risk surfaces read). Absent/unreadable → {}.
        rm = _load_json(STATE_DIR / "risk_management.json") or {}
        heat_pct = _f(rm.get("portfolio_heat_pct")) or 0.0
        total_risk = _f(rm.get("total_risk_dollars")) or 0.0
    except Exception:
        pass
    regime_now = "unknown"
    try:
        rr = _db_query(
            "SELECT regime_label, trend_state, confidence FROM market_regime_snapshots "
            "ORDER BY created_at DESC LIMIT 1",
            fetch="one",
        )
        if rr:
            _rl = str(rr.get("regime_label") or "unknown").replace("_", " ")
            _ts = str(rr.get("trend_state") or "").strip()
            _cf = rr.get("confidence")
            regime_now = _rl + (f" {_ts}" if _ts else "") + (f" {int(float(_cf) * 100)}%" if _cf is not None else "")
    except Exception:
        pass
    risk_off = any(w in regime_now.lower() for w in ("off", "bear", "defensive"))

    consensus_targets = {}
    try:
        import sys as _sysc

        _sysc.path.insert(0, str(PROJECT_ROOT / "scripts" / "lib"))
        from stop_consensus_check import (
            check_stop_over_consensus,
            load_consensus_targets,
            price_vs_consensus_pct,
            stop_vs_consensus_pct,
            vs_consensus_dollars,
        )

        consensus_targets = load_consensus_targets(project_root=PROJECT_ROOT)
    except Exception:
        check_stop_over_consensus = None  # type: ignore

    rows = []
    counts = {"yellow": 0, "amber": 0, "red": 0}
    stop_over_consensus_n = 0
    price_above_street_n = 0
    with_street_consensus_n = 0
    regime_shift_n = 0
    total_open_risk = 0.0
    trailing_not_active = 0
    _regime_cfg = {}
    _enrich_all = {}
    _regime_enabled = False
    try:
        import sys as _rsysc

        _rsysc.path.insert(0, str(PROJECT_ROOT / "scripts" / "lib"))
        from momentum_scalp_regime import build_context_from_enrich, detect_regime
        from momentum_scalp_regime import _load_yaml as _regime_load_yaml
        from stoplight_regime_thresholds import evaluate_regime_stoplight

        _regime_cfg = _regime_load_yaml()
        _enrich_all = _enrich_cache()
        _regime_enabled = True
    except Exception:
        build_context_from_enrich = None  # type: ignore
        detect_regime = None  # type: ignore
        evaluate_regime_stoplight = None  # type: ignore

    def _merge_alert_level(a, b):
        _rank = {"red": 3, "amber": 2, "yellow": 1, None: 0}
        return a if _rank.get(a, 0) >= _rank.get(b, 0) else b

    # Earnings proximity for held symbols — a stop can gap through an earnings print, so the
    # stop surface must warn (operator-approved 2026-07-03, mirrors the watchlist/proposal flags).
    earnings_by_sym = {}
    news_by_sym = {}
    _held_syms = []
    try:
        _held_syms = sorted({str(x.get("symbol") or "").upper() for x in holds if not x.get("is_cash")})
        if _held_syms:
            for _er in (
                _db_query(
                    "SELECT upper(symbol) AS s, next_earnings_date FROM symbol_profiles WHERE upper(symbol) = ANY(%s)",
                    (_held_syms,),
                )
                or []
            ):
                if _er.get("next_earnings_date"):
                    earnings_by_sym[_er["s"]] = str(_er["next_earnings_date"])
    except Exception:
        pass
    # Latest headline per held symbol (7d) — same source as the watchlist card's News line
    # (news_articles), so the stop surface carries identical context. Failure-tolerant batch
    # (DISTINCT ON — one cheap indexed pass), mirroring earnings_by_sym above.
    try:
        if _held_syms:
            for _nr in (
                _db_query(
                    """SELECT DISTINCT ON (upper(symbol)) upper(symbol) AS s, title, source,
                              COALESCE(published_at, created_at) AS at
                       FROM news_articles
                       WHERE upper(symbol) = ANY(%s)
                         AND created_at > NOW() - INTERVAL '7 days'
                         AND NOT COALESCE(is_duplicate, FALSE)
                       ORDER BY upper(symbol), COALESCE(published_at, created_at) DESC""",
                    (_held_syms,),
                )
                or []
            ):
                if _nr.get("title"):
                    news_by_sym[_nr["s"]] = {
                        "title": str(_nr["title"]),
                        "source": _nr.get("source"),
                        "at": _json_clean(_nr.get("at")),
                    }
    except Exception:
        pass

    for h in holds:
        sym = str(h.get("symbol", "")).upper()
        acct = str(h.get("account", ""))
        if h.get("is_cash") or not sym or sym in ("CASH", "SPAXX", "VMFXX", "USD"):
            continue
        px = _f(h.get("current_price")) or _f(h.get("price"))
        qty = _f(h.get("shares")) or 0.0
        if qty <= 0:
            continue
        adv = advised.get(sym, {})
        ls = live_stops.get((sym, acct)) or {}
        broker_stop = _f(ls.get("stop_price"))
        is_trailing = bool(ls.get("is_trailing"))
        broker_trail_off = _f(ls.get("trail_offset"))
        # A live/manual TRAILING broker stop carries no fixed stop_price — derive its CURRENT trigger from
        # the broker's trail % (px × (1 − trail%)) so it registers as an active stop (has_active_stop /
        # broker_stops_active count / not "naked") and gets a real distance, instead of vanishing.
        if broker_stop is None and is_trailing and broker_trail_off is not None and px is not None:
            broker_stop = round(px * (1 - broker_trail_off / 100.0), 2)
        planned_stop = adv.get("stop")
        stop = broker_stop if broker_stop is not None else planned_stop
        # Unprotected lots (no broker stop AND no 5-day advisory) MUST still appear as NO STOP.
        # Dropping them hid SCHD schwab_rollover_ira (~$351k) from the desk.
        missing_quote = px is None
        unprotected_no_advisory = broker_stop is None and planned_stop is None
        atr = adv.get("atr")
        _cb = _f(h.get("cost_basis"))
        basis = (_cb / qty) if (_cb and qty) else adv.get("basis")
        r_unit = (basis - planned_stop) if (basis and planned_stop and basis > planned_stop) else None
        # distance in $, %, ATR, R — null-safe; never invent a stop price.
        if stop is not None and px is not None:
            dist_dollars = round((px - stop) * qty, 2)
            dist_pct = round((px - stop) / px * 100, 2) if px else None
            dist_atr = round((px - stop) / atr, 2) if atr else None
            dist_r = round((px - stop) / r_unit, 2) if r_unit else None
        else:
            dist_dollars = dist_pct = dist_atr = dist_r = None
        unreal_dollars = round((px - basis) * qty, 2) if (basis and px is not None) else None
        unreal_r = round((px - basis) / r_unit, 2) if (basis and r_unit and px is not None) else None
        # Live P&L override (operator 2026-07-06): stale advisories miss intraday runners — re-check the
        # +9% / above-SMA rule against the current quote, not only trail_recommended from the last cron.
        should_trail = bool(adv.get("trail")) and not is_trailing
        if not should_trail and not is_trailing and px and basis and basis > 0:
            try:
                import holding_family as _hf

                _fam = str(adv.get("family") or _hf.DEFAULT_FAMILY)
                _pnl = (px - basis) / basis * 100
                _sma = adv.get("sma50")
                if _hf.trail_recommended_for_state(family=_fam, pnl_pct=_pnl, price=px, sma50=_sma):
                    should_trail = True
            except Exception:
                pass
        # A lot with no live stop and no advisory is NO STOP, not "trail upgrade of a
        # phantom fixed stop". Keep trail-eligible only when there is something to convert
        # (live stop) or an advisory to place (planned stop).
        if unprotected_no_advisory:
            should_trail = False
        if should_trail:
            trailing_not_active += 1
        is_fidelity = acct.startswith("fidelity")
        naked = broker_stop is None and planned_stop is not None
        # broker-aware wording: Fidelity has no trading API, so its stops are manual/monitored, not "at broker"
        naked_reason = (
            "manual/monitored stop not armed (Fidelity — no broker API)"
            if is_fidelity
            else "advised stop not placed at broker"
        )
        if unprotected_no_advisory:
            naked_reason = (
                "no live or recorded stop (Fidelity — no broker API)"
                if is_fidelity
                else "no broker stop and no advisory"
            )
        divergence = (
            "no stop on this lot"
            if unprotected_no_advisory
            else "planned only — no active stop"
            if naked
            else "broker looser than advised"
            if (broker_stop is not None and planned_stop is not None and broker_stop < planned_stop - 0.01)
            else None
        )
        stop_source = ls.get("stop_source") or ("planned" if planned_stop is not None else "none")
        heat_contrib = (
            round((max(dist_dollars, 0) / total_risk * heat_pct), 2)
            if (total_risk and dist_dollars is not None)
            else None
        )
        row_at_risk = (
            round(max(dist_dollars, 0), 2)
            if dist_dollars is not None
            else (round(px * qty, 2) if (unprotected_no_advisory and px is not None) else 0.0)
        )
        # Stop order qty vs shares held — GTC stops do NOT auto-resize after buys/trims.
        stop_qty = _f(ls.get("stop_qty") if ls.get("stop_qty") is not None else ls.get("qty"))
        _coverage = ls.get("coverage")
        if broker_stop is not None and stop_qty is not None and qty > 0:
            if stop_qty + 0.99 < qty:
                _coverage = "partial"
            elif stop_qty > qty + 0.99:
                _coverage = "oversized"
            else:
                _coverage = _coverage or "full"

        # ---- alert level: regime-aware stoplight (protocol v2.0) + hard safety overrides ----
        is_active_trade = route.get(sym, "core-hold") in ("Pure Momentum", "Social+Momentum")
        _direction = "short" if (qty or 0) < 0 else "long"
        reasons = []
        level = None
        _policy_suggestions = []
        _thresholds_used = None
        _regime_out = {}

        _monitored = stop_source == "monitored"
        _to = broker_trail_off if (is_trailing and broker_trail_off) else adv.get("trail_offset")
        if _to in (None, 0) and should_trail:
            _to = adv.get("stop_pct_below")
        _trail_pct = float(_to) if (_to not in (None, 0)) else None
        _trail_trigger = round(px * (1 - _trail_pct / 100.0), 2) if (_trail_pct and px) else None

        _cons_hit = None
        _stop_vs_cons = None
        _price_vs_cons = None
        _price_vs_cons_usd = None
        _cons = consensus_targets.get(sym) if consensus_targets else None
        _cons_mean = (_cons or {}).get("target_mean")
        if _cons_mean and px is not None:
            with_street_consensus_n += 1
            _price_vs_cons = price_vs_consensus_pct(px, _cons_mean)
            _price_vs_cons_usd = vs_consensus_dollars(px, _cons_mean)
            if _price_vs_cons is not None and _price_vs_cons > 0.5:
                price_above_street_n += 1
        if check_stop_over_consensus and _cons:
            _eff = broker_stop if broker_stop is not None else _trail_trigger
            if _eff is None and planned_stop is not None:
                _eff = planned_stop
            _stop_vs_cons = stop_vs_consensus_pct(_eff, _cons_mean)
            _cons_hit = check_stop_over_consensus(sym, _eff, px, _cons)
            if _cons_hit:
                stop_over_consensus_n += 1

        if _regime_enabled and detect_regime and evaluate_regime_stoplight:
            try:
                _enr = (_enrich_all or {}).get(sym) or {}
                _rctx = build_context_from_enrich(_enr, price=px, direction=_direction)
                _regime_out = detect_regime(sym, _rctx, project_root=PROJECT_ROOT, cfg=_regime_cfg)
                if _regime_out.get("regime_shift_detected"):
                    regime_shift_n += 1
                _eff_regime = "regime_shift" if _regime_out.get("regime_shift_detected") else _regime_out.get("regime")
                _sl = evaluate_regime_stoplight(
                    regime=_eff_regime or "trending",
                    regime_meta=_regime_out,
                    dist_r=dist_r,
                    dist_pct=dist_pct,
                    dist_atr=dist_atr,
                    modifiers={
                        "heat_contribution_pct": heat_contrib,
                        "price_vs_consensus_pct": _price_vs_cons,
                        "unrealized_r": unreal_r,
                        "trailing_should_be_active": should_trail,
                        "naked": naked,
                        "naked_reason": naked_reason,
                        "is_active_trade": is_active_trade,
                        "divergence": divergence,
                        "risk_off": risk_off,
                    },
                    cfg=_regime_cfg,
                )
                level = _sl.get("alert_level")
                reasons = list(_sl.get("alert_reasons") or [])
                _policy_suggestions = list(_sl.get("policy_suggestions") or [])
                _thresholds_used = _sl.get("thresholds_used")
            except Exception:
                pass

        # Hard safety overrides (never relaxed by regime — protocol §7 kill-switch / heat cap)
        if unprotected_no_advisory:
            reasons.append(naked_reason)
            if missing_quote:
                reasons.append("missing_quote")
            level = _merge_alert_level(level, "red")
            _policy_suggestions = list(_policy_suggestions or []) + [
                "Review and place a protective stop via 2FA (Schwab) — no stop price was invented."
            ]
        if naked and not is_active_trade:
            reasons.append(("core hold: " if not is_fidelity else "") + naked_reason)
            level = _merge_alert_level(level, "yellow")
        if _coverage == "partial" and stop_qty is not None:
            _gap = max(0.0, float(qty) - float(stop_qty))
            reasons.append(f"partial stop size: covers {stop_qty:g} of {qty:g} sh ({_gap:g} unprotected)")
            level = _merge_alert_level(level, "amber")
            _tgt = int(qty) if abs(qty - int(qty)) < 1e-6 else qty
            _policy_suggestions = list(_policy_suggestions or []) + [
                f"Replace stop to full {_tgt:g} sh via 2FA (same type/level)"
            ]
        if _coverage == "oversized" and stop_qty is not None:
            reasons.append(f"oversized stop: {stop_qty:g} sh stop vs {qty:g} held")
            level = _merge_alert_level(level, "red")
        if heat_pct > HEAT_CAP and (heat_contrib or 0) >= 1.5:
            reasons.append(f"portfolio heat {heat_pct:.1f}% > {HEAT_CAP}% cap")
            level = "red"

        if level:
            counts[level] += 1
        if dist_dollars is not None:
            total_open_risk += max(dist_dollars, 0)
        # Who recommended fixed vs trailing (the advisory is produced by an LLM lane; model_used says which).
        _rm = str(adv.get("rec_model") or "").lower()
        _rec_source = (
            "Grok · external LLM"
            if "grok" in _rm
            else "ChatGPT · external LLM"
            if ("gpt" in _rm or "chatgpt" in _rm)
            else "Claude · external LLM"
            if "claude" in _rm
            else "Stop policy · family floor"
            if "stop_policy" in _rm
            else "System · local advisor"
            if _rm
            else None
        )
        # Plain-English narrative + single next action + 2FA trade projection (STOP_METHODOLOGY.md-aligned).
        _narr, _next, _proj = _stop_row_narrative(
            sym=sym,
            is_fidelity=is_fidelity,
            has_active_stop=(broker_stop is not None),
            broker_stop=broker_stop,
            planned_stop=planned_stop,
            current_price=px,
            qty=qty,
            distance_pct=dist_pct,
            distance_atr=dist_atr,
            dollars_at_risk=row_at_risk,
            is_trailing=is_trailing,
            trailing_should_be_active=should_trail,
            trail_pct=_trail_pct,
            trail_trigger=_trail_trigger,
            divergence=divergence,
            alert_level=level,
            naked=naked,
            unrealized_dollars=unreal_dollars,
        )
        if unprotected_no_advisory and not _next:
            venue = "a Fidelity manual ticket (no broker API)" if is_fidelity else "🔒 Set 2FA"
            _mv = f"${row_at_risk:,.0f}" if row_at_risk else "this lot"
            _narr = f"No live broker stop and no recent protection advisory — {_mv} is unprotected."
            _next = f"Place a protective stop via {venue}. Desk listed the lot; no stop price was invented."
            _proj = None
        # Size mismatch overrides next_action — methodology "keep" is wrong when stop qty lags a size-up.
        if _coverage == "partial" and stop_qty is not None:
            _tgt = int(qty) if abs(qty - int(qty)) < 1e-6 else qty
            _next = (
                f"PARTIAL stop size — covers {stop_qty:g} of {qty:g} sh. "
                f"Replace (cancel + re-place) at {_tgt:g} sh via 2FA — same type/level."
            )
            _narr = (
                f"Live stop is working but undersized after a buy/size-up: "
                f"{stop_qty:g} sh protected, {max(0.0, float(qty) - float(stop_qty)):g} sh naked."
            )
        elif _coverage == "oversized" and stop_qty is not None:
            _tgt = int(qty) if abs(qty - int(qty)) < 1e-6 else max(1, int(qty))
            _next = (
                f"OVERSIZED stop — {stop_qty:g} sh stop vs {qty:g} held. "
                f"Replace at {_tgt:g} sh via 2FA to avoid short/reject on trigger."
            )
        rows.append(
            {
                "symbol": sym,
                "account": acct,
                "broker": ls.get("broker")
                or ("schwab" if acct.startswith("schwab") else ("fidelity" if is_fidelity else "")),
                "route": route.get(sym, "core-hold"),
                # Real-account holdings are long; short only if a negative position ever appears (momentum-scalp domain).
                "direction": "short" if (qty or 0) < 0 else "long",
                "narrative": _narr,
                "next_action": _next,
                "projection": _proj,
                "stop_type": (
                    ("TRAILING" if is_trailing else "MONITORED" if _monitored else "HARD")
                    if broker_stop is not None
                    else ("PLANNED" if planned_stop else "NONE")
                ),
                # Precise stop KIND — keeps the LIMIT distinction the coarse stop_type
                # above drops, so the UI can show fixed vs stop-limit vs trailing vs
                # trailing-limit as distinct pills. order_type is the raw broker type
                # (STOP / STOP_LIMIT / TRAILING_STOP / TRAILING_STOP_LIMIT).
                "order_type": (str((ls or {}).get("order_type") or "").upper() or None),
                "stop_kind": (
                    "NONE"
                    if (broker_stop is None and not planned_stop)
                    else "PLANNED"
                    if broker_stop is None
                    else "TRAILING_LIMIT"
                    if (is_trailing and "LIMIT" in str((ls or {}).get("order_type") or "").upper())
                    else "TRAILING"
                    if is_trailing
                    else "MONITORED"
                    if _monitored
                    else "STOP_LIMIT"
                    if "LIMIT" in str((ls or {}).get("order_type") or "").upper()
                    else "FIXED"
                ),
                "stop_source": stop_source,
                "has_active_stop": broker_stop is not None,
                "current_price": px,
                "qty": qty,
                "stop_qty": stop_qty,
                "coverage": _coverage,
                "broker_stop": broker_stop,
                "planned_stop": planned_stop,
                "stop": stop,
                "divergence": divergence,
                "distance_dollars": dist_dollars,
                "distance_pct": dist_pct,
                "distance_atr": dist_atr,
                "distance_r": dist_r,
                "dollars_at_risk": row_at_risk,
                "unrealized_dollars": unreal_dollars,
                "unrealized_r": unreal_r,
                # Realized P/L if this stop FILLS at its trigger — the outcome the
                # operator decides on (a near-trigger on a deep loser is capitulation;
                # on a winner it locks a gain). Derived from unrealized-now less the
                # move from current price down to the stop: qty x (current - stop).
                "pl_if_fired": (
                    round(unreal_dollars - (qty or 0) * (px - broker_stop), 2)
                    if (broker_stop is not None and unreal_dollars is not None and px is not None and qty)
                    else None
                ),
                "is_trailing": is_trailing,
                "trailing_should_be_active": should_trail,
                "trail_pct": _trail_pct,
                "trailing_trigger": _trail_trigger,
                "trail_recommended": bool(adv.get("trail")),
                "rec_source": _rec_source,
                "rec_model": adv.get("rec_model"),
                "rec_rationale": adv.get("rationale"),
                "rec_at": adv.get("rec_at"),
                "rec_evidence": adv.get("evidence") or [],
                "rec_data_i_doubt": adv.get("data_i_doubt"),
                "next_earnings_date": earnings_by_sym.get(sym),
                "news_title": (news_by_sym.get(sym) or {}).get("title"),
                "news_source": (news_by_sym.get(sym) or {}).get("source"),
                "news_at": (news_by_sym.get(sym) or {}).get("at"),
                "stop_curation": stop_curation.get(sym),
                "holdings_llm_health": h.get("llm_health"),
                "holdings_llm_at": _json_clean(h.get("llm_at")),
                "holdings_llm_evidence": h.get("llm_evidence") or [],
                "holdings_llm_data_i_doubt": h.get("llm_data_i_doubt"),
                "heat_contribution_pct": heat_contrib,
                "regime_now": regime_now,
                "alert_level": level,
                "alert_reasons": reasons,
                "consensus_target_mean": (_cons_hit or {}).get("consensus_target_mean") or _cons_mean,
                "consensus_target_high": (_cons or {}).get("target_high"),
                "consensus_target_low": (_cons or {}).get("target_low"),
                "consensus_analysts": (_cons_hit or {}).get("consensus_analysts") or (_cons or {}).get("n_analysts"),
                "consensus_stale": (_cons or {}).get("stale"),
                "price_vs_consensus_pct": _price_vs_cons,
                "price_vs_consensus_dollars": _price_vs_cons_usd,
                "price_above_consensus": (_price_vs_cons or 0) > 0.5,
                "stop_above_consensus": bool(_cons_hit),
                "consensus_gap_pct": (_cons_hit or {}).get("consensus_gap_pct"),
                "stop_vs_consensus_pct": _stop_vs_cons,
                "regime": (_regime_out or {}).get("regime"),
                "regime_label": (_regime_out or {}).get("regime_label"),
                "regime_short": (_regime_out or {}).get("regime_short"),
                "regime_confidence": (_regime_out or {}).get("confidence"),
                "regime_at_entry": (_regime_out or {}).get("regime_at_entry"),
                "regime_shift_detected": (_regime_out or {}).get("regime_shift_detected"),
                "regime_shift_direction": (_regime_out or {}).get("regime_shift_direction"),
                "regime_explanation": (_regime_out or {}).get("explanation"),
                "trail_tighten_atr_mult": (_regime_out or {}).get("trail_tighten_atr_mult"),
                "policy_suggestions": _policy_suggestions,
                "stoplight_thresholds_used": _thresholds_used,
                "lifecycle": ls.get("lifecycle"),
                "health": ls.get("health"),
                "flags": ls.get("flags"),
            }
        )

    order = {"red": 0, "amber": 1, "yellow": 2, None: 3}
    rows.sort(key=lambda r: (order.get(r["alert_level"], 3), -(r["dollars_at_risk"] or 0)))
    broker_active = sum(1 for r in rows if r.get("has_active_stop"))

    # Portfolio-level "next actionable thing in English": prioritize real risk reduction —
    # (1) naked / no live stop by $ at risk desc (a $351k uncovered IRA lot outranks tightening a
    #     $134 looser stop), then (2) broker-looser-than-advised, then (3) other next_actions.
    # Monitor-only rows are excluded. Top 8 surface at the tab header (UI slices the same).
    def _act_priority(r):
        dar = -(r.get("dollars_at_risk") or 0)
        if not r.get("has_active_stop"):
            return (0, dar)
        if r.get("divergence") == "broker looser than advised":
            return (1, dar)
        if r.get("next_action") and not str(r.get("next_action")).startswith(("Monitor", "None")):
            return (2, dar)
        return (9, 0)

    _actionable = [r for r in rows if _act_priority(r)[0] < 9]
    _actionable.sort(key=_act_priority)
    next_actions = [
        {
            "symbol": r["symbol"],
            "account": r["account"],
            "alert_level": r.get("alert_level"),
            "action": r.get("next_action"),
            "projection": r.get("projection"),
            "dollars_at_risk": r.get("dollars_at_risk"),
        }
        for r in _actionable[:8]
    ]
    _schwab_holdings = sum(1 for h in holds if str(h.get("account", "")).startswith("schwab") and not h.get("is_cash"))
    _non_cash = sum(
        1
        for h in holds
        if not h.get("is_cash")
        and str(h.get("symbol") or "").upper() not in ("", "CASH", "SPAXX", "VMFXX", "USD")
        and ((_f(h.get("shares")) or 0.0) > 0)
    )
    _broker_degraded = _schwab_holdings > 0 and (not _live_read_ok or bool(_live_stops_meta.get("degraded")))
    import datetime as _dt

    return {
        "generated_at": _dt.datetime.now(_dt.timezone.utc).isoformat(),
        "regime_now": regime_now,
        "broker_stops_meta": _live_stops_meta,
        "broker_stops_degraded": _broker_degraded,
        "cached": False,
        "summary": {
            "total_open_risk": round(total_open_risk, 2),
            "portfolio_heat_pct": heat_pct,
            "heat_cap": HEAT_CAP,
            "yellow": counts["yellow"],
            "amber": counts["amber"],
            "red": counts["red"],
            "trailing_not_active": trailing_not_active,
            "positions": len(rows),
            "non_cash_holdings": _non_cash,
            "omitted": max(0, _non_cash - len(rows)),
            "broker_stops_active": broker_active,
            "no_stop": len(rows) - broker_active,
            "stop_over_consensus": stop_over_consensus_n,
            "with_street_consensus": with_street_consensus_n,
            "price_above_street": price_above_street_n,
            "regime_shifts": regime_shift_n,
            "next_actions": next_actions,
        },
        "rows": [{k: _json_clean(v) for k, v in r.items()} for r in rows],
    }


def _stops_audit_api(query=None):
    """GET /api/v2/stops/audit — read-only audit trail of protective-stop actions: evidence-bound per-order
    2FA stop requests/approvals (Schwab) + operator confirmations / Fidelity manual tickets. No writes.
    Powers the Stop Management → Audit sub-tab. See docs/MOMENTUM_SCALP_STOP_MONITORING_PROTOCOL.md §4/§7."""
    q = query or {}
    sym_filter = (q.get("symbol") or [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol")
    sym_filter = str(sym_filter).upper() if sym_filter else None
    events = []
    # 1. evidence-bound per-order 2FA stop requests/approvals (the Schwab live-stop path)
    try:
        for r in (
            _db_query(
                "SELECT intent_id, operator_user, approval_channel, approved_at, used_at, status, "
                "evidence_hash, proposal_snapshot_json, operator_attestation_text, created_at "
                "FROM evidence_bound_approvals ORDER BY created_at DESC LIMIT 300"
            )
            or []
        ):
            snap = r.get("proposal_snapshot_json")
            if isinstance(snap, str):
                try:
                    snap = json.loads(snap)
                except Exception:
                    snap = {}
            snap = snap or {}
            ot = str(snap.get("order_type") or "")
            if "STOP" not in ot.upper():  # protective-stop actions only
                continue
            sym = str(snap.get("symbol") or "").upper()
            if sym_filter and sym != sym_filter:
                continue
            at = r.get("used_at") or r.get("approved_at") or r.get("created_at")
            events.append(
                {
                    "kind": "2fa_stop_request",
                    "symbol": sym,
                    "account": snap.get("account"),
                    "broker": snap.get("broker"),
                    "order_type": ot,
                    "stop_price": snap.get("stop_price"),
                    "trail_pct": snap.get("trail_pct"),
                    "qty": snap.get("qty"),
                    "status": r.get("status"),
                    "channel": r.get("approval_channel"),
                    "operator": r.get("operator_user"),
                    "evidence_hash": (r.get("evidence_hash") or "")[:12] or None,
                    "attestation": (r.get("operator_attestation_text") or "")[:160] or None,
                    "at": _json_clean(at),
                }
            )
    except Exception:
        pass
    # 2. operator-confirmed stops + Fidelity manual tickets + reminders
    try:
        for r in (
            _db_query(
                "SELECT symbol, account, stop_status, stop_confirmed, stop_price_confirmed, "
                "stop_confirmation_source, stop_confirmed_at, stop_exception_reason, reminder_count, updated_at "
                "FROM stop_confirmations ORDER BY COALESCE(stop_confirmed_at, updated_at) DESC LIMIT 200"
            )
            or []
        ):
            sym = str(r.get("symbol") or "").upper()
            if sym_filter and sym != sym_filter:
                continue
            # Route/label accurately: stop_confirmations tracks EVERY position's stop status (Schwab + Fidelity),
            # so "manual" is only correct for Fidelity (no trading API). Schwab positions are 2FA/API-eligible —
            # an unconfirmed Schwab row means "2FA stop not placed yet", NOT a manual ticket (e.g. SPCX).
            _acct = str(r.get("account") or "")
            _is_fid = _acct.startswith("fidelity")
            _confirmed = bool(r.get("stop_confirmed")) or (r.get("stop_status") == "confirmed")
            _route = "fidelity_manual" if _is_fid else "schwab_2fa"
            _ot = "CONFIRMED" if _confirmed else "MANUAL — not placed" if _is_fid else "SCHWAB 2FA — not placed"
            events.append(
                {
                    "kind": "confirmation",
                    "symbol": sym,
                    "account": r.get("account"),
                    "broker": ("fidelity" if _is_fid else "schwab" if _acct.startswith("schwab") else None),
                    "route": _route,
                    "confirmed": _confirmed,
                    "order_type": _ot,
                    "stop_price": _f_or_none(r.get("stop_price_confirmed")),
                    "status": (r.get("stop_status") or ("confirmed" if r.get("stop_confirmed") else "pending")),
                    "channel": r.get("stop_confirmation_source"),
                    "reason": (r.get("stop_exception_reason") or "")[:160] or None,
                    "reminder_count": r.get("reminder_count"),
                    "at": _json_clean(r.get("stop_confirmed_at") or r.get("updated_at")),
                }
            )
    except Exception:
        pass
    events.sort(key=lambda e: str(e.get("at") or ""), reverse=True)
    counts = {}
    for e in events:
        counts[e["kind"]] = counts.get(e["kind"], 0) + 1
    return {
        "events": [{k: _json_clean(v) for k, v in e.items()} for e in events],
        "counts": counts,
        "total": len(events),
        "note": "read-only: evidence-bound 2FA stop requests + operator confirmations / Fidelity manual tickets",
    }


def _build_reentry_decision_desk_api(query=None):
    """GET /api/v2/reentry/decision-desk — calls the deterministic Data Broker decision desk.
    All price/RSI/indicator values sourced from market_quotes + indicator_confluence_cache.
    No LLM on this path. Advisory only."""
    try:
        from lib.data_broker.reentry_decision_desk import build_decision_desk

        return build_decision_desk(_db_query)
    except Exception as e:
        return {"ok": False, "error": str(e)[:300], "advisory_only": True}


def _run_reentry_insights_api(body=None):
    """POST /api/v2/reentry/run-insights — runs DeepSeek Flash stop-out quality + thesis.
    Advisory only. Capped at 20 quality + 10 thesis calls.
    Stores results in ui_prefs under portfolio.reentry.llm_insights.v1."""
    try:
        from lib.data_broker.reentry_decision_desk import build_decision_desk
        from lib.reentry_llm_insight import run_reentry_insights, store_insights

        # Build decision desk to get rows with market data
        desk = build_decision_desk(_db_query)
        rows = desk.get("rows") or []

        if not rows:
            return {"ok": True, "insight_count": 0, "message": "No symbols to analyze"}

        results = run_reentry_insights(rows)
        from db_adapter import _execute

        stored = store_insights(_execute, results)

        quality_count = sum(1 for k in results if k.endswith(":quality") and results[k].success)
        thesis_count = sum(1 for k in results if k.endswith(":thesis") and results[k].success)
        total_cost = sum(r.cost_estimate for r in results.values())
        errors = [r.error for r in results.values() if not r.success]

        return {
            "ok": True,
            "advisory_only": True,
            "provider": "deepseek-v4-flash",
            "policy": "FAST",
            "quality_calls": quality_count,
            "thesis_calls": thesis_count,
            "total_calls": len(results),
            "total_estimated_cost_usd": round(total_cost, 6),
            "stored": stored,
            "errors": errors[:5] if errors else None,
        }
    except Exception as e:
        return {"ok": False, "error": str(e)[:300], "advisory_only": True}


def _stops_reentry_watch_api(query=None):
    """GET /api/v2/stops/reentry-watch — advisory stop-out reviews + re-entry watch rows from journal lifecycle.
    Powers Stop Management → Audit re-entry panel. Never routes orders."""
    q = query or {}
    account = (q.get("account") or [None])[0] if isinstance(q.get("account"), list) else q.get("account")
    days_raw = (q.get("days") or [365])[0] if isinstance(q.get("days"), list) else q.get("days")
    try:
        days = int(days_raw) if days_raw else 365
    except (TypeError, ValueError):
        days = 365
    try:
        from stop_out_reentry_watch import build_stop_out_reviews, build_reentry_watch
        from journal_ticker_lifecycle import aggregate_ticker_activity, load_from_db

        lifecycle = aggregate_ticker_activity(load_from_db(account, days))
        reviews = build_stop_out_reviews(lifecycle)

        # Build thesis map for stop-out symbols — prefer entry plans, fall back to
        # deterministic_thesis. The thesis field was previously blank on every watch row.
        stop_syms = sorted({r["symbol"] for r in reviews})
        thesis_map: dict[str, str] = {}
        if stop_syms:
            # Primary: entry plans from watchlist_entry_plans (LLM-generated with price context)
            plan_rows = (
                _db_query(
                    """SELECT DISTINCT ON (upper(symbol)) upper(symbol) AS sym, plan->>'entry_thesis' AS thesis
                   FROM watchlist_entry_plans
                   WHERE upper(symbol) = ANY(%s) AND plan->>'entry_thesis' IS NOT NULL
                   ORDER BY upper(symbol), created_at DESC""",
                    (stop_syms,),
                )
                or []
            )
            for row in plan_rows:
                if row.get("thesis"):
                    thesis_map[row["sym"]] = row["thesis"]

        watch = build_reentry_watch(reviews, thesis_map)
        return {
            "reviews": [{k: _json_clean(v) for k, v in r.items()} for r in reviews],
            "reentry_watch": [{k: _json_clean(v) for k, v in w.items()} for w in watch],
            "advisory_only": True,
            "account": account,
            "days": days,
            "total_reviews": len(reviews),
            "total_watch": len(watch),
            "thesis_populated": len(thesis_map),
        }
    except Exception as e:
        return {
            "reviews": [],
            "reentry_watch": [],
            "advisory_only": True,
            "account": account,
            "days": days,
            "error": str(e)[:200],
        }


def _f_or_none(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def _replace_order_id_from_body(body=None) -> str:
    return str((body or {}).get("replace_order_id") or "").strip()


# Holdings label accounts short (schwab_roth); broker_accounts uses the canonical key (schwab_roth_ira).
# Self-contained on purpose: the previous version imported brokers.protective_stop_pilot.resolve_account_key,
# which no longer exists — the import raised, the except returned the raw key unresolved, and every
# schwab_roth position falsely read as "not armed / ticket mode" even though the DB account IS armed.
_PROTECTIVE_ACCOUNT_ALIASES = {
    "schwab_roth": "schwab_roth_ira",
    "schwab_rollover": "schwab_rollover_ira",
}


def _resolve_protective_account_key(account_key: str) -> str:
    """Resolve a holdings account label to the canonical broker_accounts.account_key."""
    raw = (account_key or "").strip()
    return _PROTECTIVE_ACCOUNT_ALIASES.get(raw.lower(), raw)


def _one_symbol_canary_conflict(symbol, account):
    """One protective-stop canary per symbol at a time (any ticker). Returns the conflicting account if an
    active evidence-bound approval for this symbol exists on a DIFFERENT account, else None.
    Prevents simultaneous rollover+roth canaries on the same symbol. Read-only."""
    s = (symbol or "").upper()
    a = _resolve_protective_account_key(account or "")
    try:
        rows = (
            _db_query("""SELECT COALESCE(proposal_snapshot_json->>'symbol', readiness_snapshot_json->>'symbol') sym,
                                   COALESCE(proposal_snapshot_json->>'account', readiness_snapshot_json->>'account') acct
                            FROM evidence_bound_approvals
                            WHERE status='approved' AND used_at IS NULL
                              AND (expires_at IS NULL OR expires_at > NOW())""")
            or []
        )
        for r in rows:
            if str(r.get("sym") or "").upper() == s and str(r.get("acct") or "") and str(r.get("acct")) != a:
                return str(r.get("acct"))
    except Exception:
        pass
    return None


def _protective_stop_refresh_quote(body=None):
    """POST /api/v2/holdings/protective-stop/refresh-quote — fetch the LATEST available quote (read-only)
    from Schwab + Alpaca + Finviz (and DB fallback) for a live-stop readiness check.

    Ranking: real trade/quote event time first (not cache pull time). Broker prints (Schwab, Alpaca)
    outrank Finviz `last_fetched` (which is when we scraped, not when the tape printed). Ties broken by
    source trust: Schwab > Alpaca > market_provider > DB > Finviz cache.

    NEVER submits, modifies, or cancels a broker order (broker_request_sent=false)."""
    import datetime as _dt
    from brokers.quote_time import (
        parse_quote_ts,
        classify_session,
        to_iso,
        quote_age_seconds,
        fresh_max_age_for,
        is_fresh,
    )

    b = body or {}
    sym = str(b.get("symbol", "")).upper().strip()
    acct = str(b.get("account", "")).strip()
    if not sym:
        return {"ok": False, "error": "symbol required", "broker_request_sent": False}

    # (trust, event_ts, price, bid, ask, source, raw_ts, is_event_time)
    candidates = []
    sources_tried = []

    def _add(price, src, raw_ts, trust, bid=None, ask=None, is_event_time=True):
        try:
            if price is None:
                return
            p = parse_quote_ts(raw_ts)
            if p is None:
                sources_tried.append(
                    {
                        "source": src,
                        "ok": False,
                        "error": "unparseable_ts",
                        "raw_ts": str(raw_ts)[:80] if raw_ts else None,
                    }
                )
                return
            candidates.append((int(trust), p, float(price), bid, ask, src, raw_ts, bool(is_event_time)))
            sources_tried.append(
                {
                    "source": src,
                    "ok": True,
                    "price": float(price),
                    "ts": to_iso(raw_ts),
                    "event_time": bool(is_event_time),
                    "trust": int(trust),
                }
            )
        except Exception as e:
            sources_tried.append({"source": src, "ok": False, "error": str(e)[:80]})

    def _ms_ts(v):
        """Schwab quoteTime/tradeTime often arrives as epoch ms int."""
        if v is None:
            return None
        try:
            n = int(v)
            if n > 10_000_000_000:  # ms
                return _dt.datetime.fromtimestamp(n / 1000.0, tz=_dt.timezone.utc)
            if n > 1_000_000_000:  # s
                return _dt.datetime.fromtimestamp(n, tz=_dt.timezone.utc)
        except Exception:
            pass
        return v

    # ── 1) Schwab live API (extended-hours + overnight last) ─────────────────
    try:
        from schwab_transport import get_quotes as _schwab_quotes

        # Prefer account-keyed read when we have a Schwab holding account
        ak = acct if (acct or "").startswith("schwab") else None
        res = _schwab_quotes([sym], account_key=ak) or {}
        q = ((res.get("quotes") or {}).get(sym) if isinstance(res, dict) else None) or {}
        if q:
            price = q.get("last") or q.get("mark")
            if price is None and q.get("bid") is not None and q.get("ask") is not None:
                price = (float(q["bid"]) + float(q["ask"])) / 2.0
            sts = _ms_ts(q.get("updated") or q.get("quoteTime") or q.get("tradeTime"))
            _add(price, "schwab", sts, trust=50, bid=q.get("bid"), ask=q.get("ask"), is_event_time=True)
        else:
            sources_tried.append({"source": "schwab", "ok": False, "error": (res or {}).get("status") or "empty"})
    except Exception as e:
        sources_tried.append({"source": "schwab", "ok": False, "error": str(e)[:80]})

    # ── 2) Alpaca (IEX snapshot: last trade + bid/ask) ───────────────────────
    try:
        from market_quote_provider import fetch_alpaca_snapshot

        aq = fetch_alpaca_snapshot(sym) or {}
        if aq.get("last_price") is not None:
            _add(
                aq.get("last_price"),
                "alpaca",
                aq.get("quote_timestamp"),
                trust=40,
                bid=aq.get("bid"),
                ask=aq.get("ask"),
                is_event_time=True,
            )
        else:
            sources_tried.append({"source": "alpaca", "ok": False, "error": "no_last_price"})
    except Exception as e:
        sources_tried.append({"source": "alpaca", "ok": False, "error": str(e)[:80]})

    # ── 3) market_quote_provider fan-out (may hit Schwab/Alpaca/others again) ─
    try:
        from market_quote_provider import get_best_quote

        q = get_best_quote(sym) or {}
        if q.get("last_price") is not None:
            # Real-time broker providers carry event times; finviz_cache does not
            evt = str(q.get("provider") or "") in ("schwab", "alpaca", "polygon", "finnhub")
            _add(
                q.get("last_price"),
                f"mqp:{q.get('provider') or 'unknown'}",
                q.get("quote_timestamp"),
                trust=30 if evt else 10,
                bid=q.get("bid"),
                ask=q.get("ask"),
                is_event_time=evt,
            )
    except Exception as e:
        sources_tried.append({"source": "market_quote_provider", "ok": False, "error": str(e)[:80]})

    # ── 4) DB market_quotes (prior refresh / ingest) ─────────────────────────
    r = _db_query(
        "SELECT price, source, fetched_at FROM market_quotes WHERE symbol=%s "
        "AND source NOT LIKE 'refresh:%%' ORDER BY fetched_at DESC LIMIT 1",
        (sym,),
        fetch="one",
    )
    if r:
        # fetched_at is ingest time — lower trust, not a tape event
        _add(
            r.get("price"),
            f"db:{(r.get('source') or 'market_quotes')}",
            r.get("fetched_at"),
            trust=15,
            is_event_time=False,
        )

    # ── 5) Finviz Elite cache (price good; prefer last_updated trade-ish stamp) ─
    try:
        fv = (_load_json(STATE_DIR / "finviz_quote_cache.json") or {}).get(sym) or {}
        # Prefer last_updated (market data stamp) over last_fetched (scrape clock) so we
        # do not outrank Schwab/Alpaca solely because a cron re-pulled the cache.
        fv_ts = fv.get("last_updated") or fv.get("quote_time") or fv.get("last_fetched")
        _add(fv.get("price"), "finviz", fv_ts, trust=5, is_event_time=False)
    except Exception as e:
        sources_tried.append({"source": "finviz", "ok": False, "error": str(e)[:80]})

    # Rank: event-time quotes first, then freshest event_ts, then trust
    candidates.sort(key=lambda c: (1 if c[7] else 0, c[1], c[0]), reverse=True)
    if candidates:
        _, parsed, price, bid, ask, source, raw_ts, _evt = candidates[0]
        quote = {"price": price, "bid": bid, "ask": ask}
    else:
        quote = parsed = source = raw_ts = None
        bid = ask = None

    session = classify_session(raw_ts) if raw_ts is not None else "unknown"
    age = quote_age_seconds(raw_ts) if raw_ts is not None else None
    fresh = is_fresh(raw_ts) if raw_ts is not None else False
    # persist the refreshed quote (advisory record; never touches a broker order)
    if quote and parsed:
        try:
            _db_query(
                "INSERT INTO market_quotes (symbol, source, price, fetched_at) VALUES (%s,%s,%s,%s)",
                (sym, f"refresh:{source}", quote["price"], parsed.astimezone(_dt.timezone.utc)),
                fetch=None,
            )
        except Exception:
            pass
    blockers = []
    if quote is None:
        blockers.append("No quote available from Schwab, Alpaca, or Finviz.")
    elif not parsed:
        blockers.append("Quote timestamp could not be parsed.")
    elif not fresh:
        blockers.append(
            f"Quote is stale ({int(age) // 60}m old) — outside the {fresh_max_age_for(session) // 60}m "
            f"{session.replace('_', '-')} freshness window."
        )
    out = {
        "ok": quote is not None and parsed is not None,
        "symbol": sym,
        "account": acct,
        "broker_request_sent": False,
        "quote_price": quote["price"] if quote else None,
        "quote_bid": quote.get("bid") if quote else None,
        "quote_ask": quote.get("ask") if quote else None,
        "quote_source": source,
        "quote_time_raw": str(raw_ts) if raw_ts else None,
        "quote_time_normalized": to_iso(raw_ts) if raw_ts is not None else None,
        "quote_parse_ok": parsed is not None,
        "session": session,
        "quote_age_sec": int(age) if age is not None else None,
        "quote_fresh": fresh,
        "blockers": blockers,
        "sources_tried": sources_tried,
        "sources_available": sorted({s.get("source") for s in sources_tried if s.get("ok")}),
    }
    out["operator_readiness"] = "READY_FOR_OPERATOR" if (quote is not None and parsed and fresh) else "BLOCKED"
    if out["operator_readiness"] == "READY_FOR_OPERATOR" and session and session != "regular":
        out["note"] = f"GTC stop — valid 24/7 (source={source}); rests until triggered."
    return out


def _stop_live_readiness(query=None):
    """GET /api/v2/holdings/stop-readiness?symbol=&account= — READ-ONLY readiness snapshot for the Schwab
    live-stop canary panel. No broker calls, no evidence writes, no order placement, no preflight side effects."""
    import os as _os

    q = query or {}
    sym = str(q.get("symbol", "")).upper().strip()
    acct = _resolve_protective_account_key(str(q.get("account", "")).strip())
    out = {
        "build_marker": _STOP_READINESS_BUILD,
        "symbol": sym,
        "account": acct,
        "broker_submit": "disabled_until_2fa_approval",
        "broker_request_sent": False,
    }
    # execution state (read-only)
    try:
        import execution_state as _es

        st = _es.build_state()
        out["execution"] = {
            "operator_live_via_2fa_allowed": bool(st.get("operator_live_via_2fa_allowed")),
            "operator_approved_live_submit_possible": bool(st.get("operator_approved_live_submit_possible")),
            "autonomous_live_submit_allowed": bool(st.get("autonomous_live_submit_allowed")),
            "blockers": st.get("current_blockers") or [],
        }
    except Exception as e:
        out["execution"] = {"error": str(e)[:120]}
    out["oco_brackets_schwab_off"] = _os.environ.get("OCO_BRACKETS_SCHWAB") in (None, "", "0", "false", "False")
    # DB + evidence store availability
    try:
        r = _db_query("SELECT 1 AS ok", fetch="one")
        out["db_available"] = bool(r and r.get("ok") == 1)
    except Exception:
        out["db_available"] = False
    try:
        _db_query("SELECT 1 FROM evidence_bound_approvals LIMIT 1")
        out["evidence_store_available"] = True
    except Exception:
        out["evidence_store_available"] = False
    # Active approval lock (non-expired, non-used, approved) — symbol-filtered via the snapshot when possible
    try:
        rows = (
            _db_query("""SELECT id, intent_id, operator_user, expires_at,
                              COALESCE(proposal_snapshot_json->>'symbol', readiness_snapshot_json->>'symbol') AS sym
                            FROM evidence_bound_approvals
                            WHERE status='approved' AND used_at IS NULL
                              AND (expires_at IS NULL OR expires_at > NOW())""")
            or []
        )
        locks = [r for r in rows if (not sym or str(r.get("sym") or "").upper() == sym)]
        out["active_approval"] = (
            {
                "exists": True,
                "id": locks[0]["id"],
                "intent_id": locks[0].get("intent_id"),
                "operator": locks[0].get("operator_user"),
                "expires_at": str(locks[0].get("expires_at")),
            }
            if locks
            else {"exists": False}
        )
    except Exception as e:
        out["active_approval"] = {"error": str(e)[:80]}
    out["schwab_validator"] = _cached_schwab_validator()
    # Preflight has side effects (evidence write) → never auto-run from a GET. Report whether a valid approval
    # already exists for this symbol; otherwise the operator must run the dry-run preflight explicitly.
    out["preflight_status"] = "approval_present" if (out.get("active_approval") or {}).get("exists") else "not_run"
    # Quote freshness + session classification (ET-aware; the failing ' ET' shape now normalizes cleanly).
    try:
        from brokers.quote_time import parse_quote_ts, classify_session, to_iso, quote_age_seconds, is_fresh

        raw_q = q.get("quote_at")
        if not raw_q:
            raw_q = _holding_source_timestamp(sym, acct)
        out["quote_raw"] = raw_q
        parsed = parse_quote_ts(raw_q)
        out["quote_parse_ok"] = parsed is not None
        out["quote_normalized"] = to_iso(raw_q)
        out["quote_session"] = classify_session(raw_q)
        age = quote_age_seconds(raw_q)
        out["quote_fresh"] = is_fresh(raw_q)  # session-aware (regular 15m / extended 60m)
        out["quote_age_sec"] = int(age) if age is not None else None
    except Exception as e:
        out["quote_parse_ok"] = False
        out["quote_session"] = "unknown"
        out["quote_fresh"] = False
        out["quote_error"] = str(e)[:80]
    # System-side canary readiness. READY_FOR_OPERATOR never means "submit" — the operator must still click +
    # per-order 2FA, and the backend revalidates evidence at submit.
    ex = out.get("execution") or {}
    # Per-account live-write arming (broker_accounts.api_write_enabled). Holdings schwab_roth → schwab_roth_ira.
    out["account_api_write_enabled"] = _protective_account_api_write(acct) if acct.startswith("schwab") else False
    out["account_key_resolved"] = _resolve_protective_account_key(acct) if acct.startswith("schwab") else acct
    system_ready = bool(
        out.get("db_available")
        and out.get("evidence_store_available")
        and ex.get("operator_live_via_2fa_allowed")
        and ex.get("autonomous_live_submit_allowed") is False
        and out.get("oco_brackets_schwab_off")
        and (out.get("schwab_validator") or {}).get("pass")
        and out.get("account_api_write_enabled")
    )
    # GTC protective stops are valid 24/7 (rest until triggered). Session is informational only —
    # a fresh, parseable quote + clean backend gates → READY_FOR_OPERATOR any time.
    out["requires_after_hours_ack"] = False
    # One-V-canary discipline: a conflicting canary on another account blocks this one.
    conflict_acct = _one_symbol_canary_conflict(sym, acct)
    out["other_account_canary"] = conflict_acct
    if not out.get("quote_parse_ok"):
        out["canary_state"] = "BLOCKED"
        out["canary_blocker"] = "Quote timestamp could not be parsed; refresh quote."
    elif not out.get("quote_fresh"):
        out["canary_state"] = "BLOCKED"
        out["canary_blocker"] = "Quote is stale — refresh the latest price before requesting a live stop."
    elif conflict_acct:
        out["canary_state"] = "BLOCKED"
        out["canary_blocker"] = (
            f"Another {sym} canary is already active on {conflict_acct}. Only one {sym} "
            "canary may be armed at a time — complete or reject it first."
        )
    elif acct.startswith("schwab") and not out.get("account_api_write_enabled"):
        out["canary_state"] = "BLOCKED"
        out["canary_blocker"] = (
            f"{acct} is not armed for live API writes (ticket mode). "
            "Set broker_accounts.api_write_enabled=TRUE for this Schwab account."
        )
    elif not system_ready:
        out["canary_state"] = "BLOCKED"
        out["canary_blocker"] = "A backend readiness gate is not satisfied."
    else:
        out["canary_state"] = "READY_FOR_OPERATOR"
        if out.get("quote_session") and out.get("quote_session") != "regular":
            out["canary_note"] = "GTC stop — valid 24/7; rests until triggered."
    out["replace_mode"] = bool(str(q.get("replace_order_id") or q.get("replace_mode") or "").strip())
    out["broker_submit_requires"] = "operator click + per-order 2FA + evidence revalidation"
    return out


def _holding_source_timestamp(symbol: str, account: str):
    """Read a holding's price source_timestamp from canonical holdings.json (read-only) for session/freshness."""
    try:
        h = _load_json(STATE_DIR / "holdings.json") or {}
        s = (symbol or "").upper()
        a = account or ""
        # prefer the ET reprice time / per-holding ISO updated_at over the date-only as_of (which has no
        # time and would misclassify the session). The frontend normally passes the live quote_at directly.
        for r in h.get("holdings", []) or []:
            if str(r.get("symbol", "")).upper() == s and str(r.get("account", "")) == a:
                return h.get("last_repriced") or r.get("updated_at") or r.get("as_of")
        return h.get("last_repriced")
    except Exception:
        return None


def _protective_holding_truth(account_key: str, symbol: str):
    """Server truth for the gate-critical fields of a protective-stop request: (held_shares, current_price)
    for this symbol in this account, read from canonical holdings.json. Returns (None, None) if not held —
    the protective policy then fails closed on the qty/price checks. Never trusts the client for these."""
    try:
        h = _load_json(STATE_DIR / "holdings.json") or {}
        sym = (symbol or "").strip().upper()
        acct = (account_key or "").strip()
        for r in h.get("holdings", []) or []:
            if str(r.get("symbol", "")).upper() == sym and str(r.get("account", "")) == acct:
                sh = r.get("shares", r.get("qty"))
                px = r.get("current_price", r.get("price"))
                return (float(sh) if sh is not None else None, float(px) if px is not None else None)
    except Exception:
        pass
    return (None, None)


_STOP_LIFECYCLE_CACHE = {"ts": 0.0, "data": None}
_STOPS_MGMT_CACHE = {"ts": 0.0, "data": None}


def _stops_lifecycle_db_snapshot():
    """Persisted stop_lifecycle rows only — no broker scan (hot path for Stop Management tab)."""
    rows = (
        _db_query(
            "SELECT account,symbol,broker,order_id,order_type,status,stop_price,qty,held_qty,"
            "current_price,proximity_pct,coverage,lifecycle,health,flags,snapshot_at "
            "FROM stop_lifecycle ORDER BY health DESC, symbol"
        )
        or []
    )
    stops = []
    for r in rows:
        row = {k: _json_clean(v) for k, v in r.items()}
        ot = str(row.get("order_type") or "").upper()
        row["is_trailing"] = "TRAIL" in ot
        stops.append(row)
    return {"stops": stops, "source": "db_snapshot"}


def _stops_lifecycle_api():
    """GET /api/v2/stops/lifecycle — latest stop lifecycle/proximity/health scan (Schwab + Alpaca).
    Cached 45s (reads rate-limited broker order APIs); fail-soft to the persisted snapshot."""
    import time as _t

    if _t.time() - _STOP_LIFECYCLE_CACHE["ts"] < 45 and _STOP_LIFECYCLE_CACHE["data"]:
        return {"ok": True, "cached": True, **_STOP_LIFECYCLE_CACHE["data"]}
    try:
        import sys as _sys

        _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import stop_lifecycle_monitor as _slm

        data = _slm.scan(persist=True)
        _STOP_LIFECYCLE_CACHE.update(ts=_t.time(), data=data)
        return {"ok": True, "cached": False, **data}
    except Exception as e:
        # fall back to the last persisted snapshot
        rows = (
            _db_query(
                "SELECT account,symbol,broker,order_id,order_type,status,stop_price,qty,held_qty,"
                "current_price,proximity_pct,coverage,lifecycle,health,flags,snapshot_at "
                "FROM stop_lifecycle ORDER BY health DESC, symbol"
            )
            or []
        )
        return {
            "ok": True,
            "cached": True,
            "stops": [{k: _json_clean(v) for k, v in r.items()} for r in rows],
            "error": str(e)[:120],
        }


