def _reports_analytics(query=None):
    """GET /api/v2/reports/analytics?days=30 — Reports Desk v1 (WS-D): alert & message
    analytics over the archive corpora. Deterministic SQL rollups: daily volume,
    by-severity, top alert types, noisiest producers, channel parity (raw store counts
    vs portal-indexed). Read-only; drill-through happens client-side via the existing
    archive filters."""
    q = query or {}
    try:
        days = int((q.get("days") or [30])[0] if isinstance(q.get("days"), list) else q.get("days") or 30)
    except (TypeError, ValueError):
        days = 30
    days = max(1, min(days, 120))
    out: dict = {"ok": True, "days": days}
    out["by_day"] = [
        {k: _json_clean(v) for k, v in r.items()}
        for r in (
            _db_query(f"""
        SELECT d::date AS day,
               coalesce(a.n,0) AS alerts, coalesce(o.n,0) AS telegram, coalesce(nl.n,0) AS notifications
        FROM generate_series(CURRENT_DATE - {days - 1}, CURRENT_DATE, interval '1 day') d
        LEFT JOIN (SELECT created_at::date dd, count(*) n FROM alert_events
                   WHERE created_at > CURRENT_DATE - {days} GROUP BY 1) a ON a.dd = d::date
        LEFT JOIN (SELECT sent_at::date dd, count(*) n FROM telegram_outbox
                   WHERE sent_at > CURRENT_DATE - {days} GROUP BY 1) o ON o.dd = d::date
        LEFT JOIN (SELECT created_at::date dd, count(*) n FROM notification_log
                   WHERE created_at > CURRENT_DATE - {days} GROUP BY 1) nl ON nl.dd = d::date
        ORDER BY 1""")
            or []
        )
    ]
    out["by_severity"] = [
        {k: _json_clean(v) for k, v in r.items()}
        for r in (
            _db_query(f"""
        SELECT coalesce(severity,'info') AS severity, count(*) AS n
        FROM alert_events WHERE created_at > CURRENT_DATE - {days}
        GROUP BY 1 ORDER BY 2 DESC""")
            or []
        )
    ]
    out["top_types"] = [
        {k: _json_clean(v) for k, v in r.items()}
        for r in (
            _db_query(f"""
        SELECT coalesce(alert_type,'?') AS alert_type, count(*) AS n, max(created_at) AS last_seen,
               count(*) FILTER (WHERE acknowledged_at IS NOT NULL) AS acked
        FROM alert_events WHERE created_at > CURRENT_DATE - {days}
        GROUP BY 1 ORDER BY 2 DESC LIMIT 14""")
            or []
        )
    ]
    out["noisiest_sources"] = [
        {k: _json_clean(v) for k, v in r.items()}
        for r in (
            _db_query(f"""
        SELECT coalesce(source_script,'?') AS source, count(*) AS n
        FROM alert_events WHERE created_at > CURRENT_DATE - {days}
        GROUP BY 1 ORDER BY 2 DESC LIMIT 10""")
            or []
        )
    ]
    # WS-E1 (v3): normalize table/script/logfile strings through the producer registry —
    # unmapped producers keep the raw string and get kind='raw' (visible debt, not mystery).
    try:
        import json as _pjson

        _preg = (
            _pjson.loads((PROJECT_ROOT / "config" / "report_producer_registry.json").read_text()).get("producers") or {}
        )
        for _r in out["noisiest_sources"]:
            _m = _preg.get(str(_r.get("source") or ""))
            _r["producer"] = (_m or {}).get("producer") or _r.get("source")
            _r["kind"] = (_m or {}).get("kind") or "raw"
    except Exception:
        pass
    # Parity: raw store counts in-window vs what the portal indexes (categories() totals)
    raw = {}
    for name, sql in (
        ("alert_events", f"SELECT count(*) n FROM alert_events WHERE created_at > CURRENT_DATE - {days}"),
        ("telegram_outbox", f"SELECT count(*) n FROM telegram_outbox WHERE sent_at > CURRENT_DATE - {days}"),
        ("notification_log", f"SELECT count(*) n FROM notification_log WHERE created_at > CURRENT_DATE - {days}"),
        ("ai_reports", f"SELECT count(*) n FROM ai_reports WHERE generated_at > CURRENT_DATE - {days}"),
    ):
        r = _db_query(sql, fetch="one") or {}
        raw[name] = _json_clean(r.get("n"))
    indexed = None
    try:
        import sys as _s

        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import reports_portal as _rp

        cats = (_rp.categories() or {}).get("categories") or []
        indexed = sum(int(c.get("count") or 0) for c in cats)
    except Exception:
        pass
    out["parity"] = {
        "raw_stores": raw,
        "raw_total": sum(v or 0 for v in raw.values()),
        "portal_indexed_total": indexed,
        "note": "portal categories index ALL history (no day window) and route each row to exactly one category; raw totals here are windowed — differences are window + routing, stated not hidden",
    }
    # WS-A3: the indexing policy is CONFIG, rendered as the parity legend — not lore.
    try:
        import json as _pj

        out["index_policy"] = _pj.loads((PROJECT_ROOT / "config" / "report_index_policy.json").read_text())
    except Exception:
        out["index_policy"] = None
    return out


def _reports_analyst_status(query=None):
    """GET /api/v2/reports/analyst/status — Reports Desk v1 (C1/C3/C4): the truth pass.
    One registry read defines every count on-page: eligible (live holdings+watchlist
    eligibility fns), generated (registry), need-refresh (age ≥ stale_days; fingerprint
    deltas are evaluated at generation time by should_regenerate — stated in the note),
    former holdings (reports whose symbol left the book), unmapped instruments
    (CUSIP-symbol $0 holdings rows — real rows, never hidden, never peers of equities)."""
    import json as _j
    import datetime as _dt

    try:
        reg = _j.loads((PROJECT_ROOT / "data" / "portfolios" / "reports" / "analyst" / "registry.json").read_text())
    except Exception:
        reg = {}
    reps = reg.get("reports") or []
    holdings = (_load_json(STATE_DIR / "holdings.json") or {}).get("holdings") or []
    held = {
        str(h.get("symbol", "")).upper()
        for h in holdings
        if h.get("symbol") and not h.get("is_cash") and (h.get("market_value") or 0) > 1
    }
    unmapped = [
        {
            "symbol": str(h.get("symbol")),
            "market_value": _json_clean(h.get("market_value")),
            "description": h.get("description") or "",
        }
        for h in holdings
        if h.get("symbol")
        and (str(h.get("symbol"))[:1].isdigit() or (not h.get("is_cash") and (h.get("market_value") or 0) <= 1))
    ]
    now = _dt.datetime.now(_dt.timezone.utc)
    stale_days = 7
    latest_by_symbol: dict = {}
    for r in reps:
        s = str(r.get("symbol") or "").upper()
        g = r.get("generated_at") or ""
        if s and g > (latest_by_symbol.get(s, {}).get("generated_at") or ""):
            latest_by_symbol[s] = r
    stale, fresh, former = [], 0, []
    for s, r in latest_by_symbol.items():
        try:
            g = _dt.datetime.fromisoformat(str(r["generated_at"]).replace("Z", "+00:00"))
            if g.tzinfo is None:
                g = g.replace(tzinfo=_dt.timezone.utc)
            age_d = (now - g).days
        except Exception:
            age_d = None
        if s not in held and r.get("report_type") == "symbol_holding":
            former.append(s)
        if age_d is not None and age_d >= stale_days:
            stale.append({"symbol": s, "age_days": age_d})
        else:
            fresh += 1
    try:
        import sys as _s

        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import reporting_engine as _re

        eligible_holdings = len(_re.eligible_holding_symbols())
    except Exception:
        eligible_holdings = None
    return {
        "ok": True,
        "registry_updated_at": reg.get("updated_at"),
        "reports_total": len(reps),
        "symbols_covered": len(latest_by_symbol),
        "eligible_holdings": eligible_holdings,
        "fresh": fresh,
        "need_refresh": len(stale),
        "need_refresh_definition": f"latest report age ≥ {stale_days}d (fingerprint deltas are evaluated at generation by should_regenerate — refresh runs Sun 21:15)",
        "stale_list": sorted(stale, key=lambda x: -x["age_days"])[:20],
        "former_holdings": sorted(set(former)),
        "unmapped_instruments": unmapped,
        "schedule": "weekly refresh Sun 21:15 · fingerprint-delta regeneration at run time",
    }


