def _today_pnl_provenance(
    holdings: dict,
    *,
    today_by_account: dict,
    account_summaries: dict,
    total_change: float,
    positions: Any = None,
) -> dict:
    """Provenance for today's P&L: its session, when it was computed, who is in it.

    A day-change figure is only meaningful against the session it was struck in
    and the set of accounts that actually contributed one. The overview payload
    carried NEITHER, so the header reached for the nearest available date --
    `data_as_of`, the POSITION observation -- and rendered "TODAY -$3,734 ·
    data_as_of 2026-09-03" over a figure computed from 2026-09-04 intraday
    marks (live capture, release a7c550d1d).

    The session a P&L belongs to is the session its MARKS were observed in,
    never the session its share counts were.

    Accounts are split four ways and none is silently dropped:
      contributing  reported a non-zero day change this session
      zero_change   linked and priced, but flat (a real 0, not a missing one)
      empty         linked, holds no positions and no value -- nothing to report
      missing       linked, HOLDS something, and still did not report

    The empty/missing split matters: fidelity_rollover_ira and
    moomoo_taxable_live hold $0 and no positions, and lumping them under
    "missing" made TODAY warn "2 acct(s) missing" and flag itself STALE over
    accounts with nothing to contribute -- while PORTFOLIO, correctly, called
    the same two "empty". One header, two characterisations of one fact.
    Absence of data and absence of holdings are not the same claim.
    """
    repriced = str(holdings.get("last_repriced") or "").strip()
    session = repriced[:10] if len(repriced) >= 10 else None

    held_by_acct: dict[str, int] = {}
    for _r in positions or []:
        if isinstance(_r, dict):
            _a = str(_r.get("account") or "").strip()
            if _a:
                held_by_acct[_a] = held_by_acct.get(_a, 0) + 1

    contributing: list[str] = []
    zero_change: list[str] = []
    empty: list[str] = []
    missing: list[str] = []
    for acct in sorted(account_summaries or {}):
        row = (today_by_account or {}).get(acct)
        if row is None:
            summary = (account_summaries or {}).get(acct) or {}
            try:
                value = abs(float(summary.get("total_value") or 0))
            except (TypeError, ValueError):
                value = 0.0
            # Nothing held and nothing worth: there is no day change to be
            # missing. Named, never counted as absent data.
            if not held_by_acct.get(acct) and value == 0.0:
                empty.append(acct)
            else:
                missing.append(acct)
            continue
        try:
            changed = float(row.get("change") or 0) != 0.0
        except (TypeError, ValueError):
            changed = False
        (contributing if changed else zero_change).append(acct)

    linked = len(account_summaries or {})
    funded = linked - len(empty)
    represented = len(contributing) + len(zero_change)
    try:
        total = round(float(total_change or 0), 2)
    except (TypeError, ValueError):
        total = None

    return {
        "contract_version": "TodayPnl@v1",
        "total_change": total,
        # ── clocks ────────────────────────────────────────────────────────────
        "session_date": session,
        "session_source": "holdings.last_repriced" if session else None,
        "calculated_at": str(holdings.get("generated_at") or "") or None,
        "mark_source": str(holdings.get("reprice_source") or "") or None,
        # ── coverage ──────────────────────────────────────────────────────────
        "scope": "ALL_ACCOUNTS",
        "linked_account_count": linked,
        "funded_account_count": funded,
        "represented_account_count": represented,
        "contributing_accounts": contributing,
        "zero_change_accounts": zero_change,
        "empty_accounts": empty,
        "missing_accounts": missing,
        # Complete means every FUNDED account reported. An empty account cannot
        # make the day incomplete.
        "complete": not missing,
        "coverage_reason": (
            f"{represented}/{funded} funded account(s) represented"
            + (f"; {len(empty)} empty ({', '.join(empty)})" if empty else "")
            + (f"; MISSING {', '.join(missing)}" if missing else "")
        ),
    }


def _resolve_country_name(symbol, raw):
    """Headquarters-country name for a scan row. Prefer the scan's own value; when
    it is empty (common for AI/social-sourced symbols that never went through the
    Finviz screener) fall back to the Finviz enrichment cache
    (data/state/ticker_enrichment_cache.json, keyed by symbol). Returns the raw
    country name ('' if still unknown)."""
    v = (raw or "").strip()
    if v:
        return v
    try:
        return ((_enrich_cache().get((symbol or "").upper()) or {}).get("country") or "").strip()
    except Exception:
        return ""


_hermes_gov_mod = [None, 0.0]  # [module, mtime]


def _hermes_governance_mod():
    """Return the hermes_governance_api module, reloading it when its source file changes. Mirrors the
    api_v2 hot-reload guard so edits to the governance summary land without a full server restart
    (a plain __import__ would keep serving the stale in-memory copy)."""
    import importlib
    import hermes_governance_api as _mod

    try:
        m = os.path.getmtime(_mod.__file__)
        if m != _hermes_gov_mod[1]:
            _mod = importlib.reload(_mod)
            _hermes_gov_mod[1] = m
        _hermes_gov_mod[0] = _mod
    except Exception:
        _hermes_gov_mod[0] = _mod
    return _hermes_gov_mod[0]


def _db_query(sql, params=None, fetch="all"):
    """Run a read-only DB query. Returns list or dict or None."""
    try:
        import sys

        sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from db_adapter import _execute, USE_DB

        if not USE_DB:
            return None
        return _execute(sql, params, fetch=fetch)
    except Exception:
        return None


def _system_pipeline_health():
    """GET /api/v2/system/pipeline-health — one aggregated view of every pipeline stage's
    live numbers: ingestion → curation → LLM → RAG → jobs → hermes. Read-only.
    Each value is a plain count/timestamp so the v3 Pipeline tab can render at-a-glance."""

    def s1(sql):
        r = _db_query(sql, fetch="one")
        if not r:
            return None
        return list(r.values())[0] if isinstance(r, dict) else r[0]

    def ts(sql):
        v = s1(sql)
        return _json_clean(v) if v is not None else None

    # YouTube cookie health → stoplight. red=logged-out (refresh needed), amber=authed but
    # ingestion stale, green=authed + flowing. The blocker that froze transcripts for 14 days.
    yt = {"status": "red", "auth_cookies": 0, "refreshed": None, "detail": "no cookie file"}
    try:
        import os as _os

        cpath = PROJECT_ROOT / "config" / "youtube_cookies.txt"
        if cpath.exists():
            names = set()
            for ln in cpath.read_text().splitlines():
                if ln.startswith("#") or "\t" not in ln:
                    continue
                parts = ln.split("\t")
                if len(parts) >= 6:
                    names.add(parts[5])
            # Authenticated YouTube/Google session cookies. Includes the 3P (third-party-context)
            # variants modern exports use — checking only 1P/legacy names false-flagged a logged-in
            # jar as RED. Matches scripts/credential_monitor.py.
            auth = names & {
                "SID",
                "HSID",
                "SSID",
                "SAPISID",
                "LOGIN_INFO",
                "__Secure-1PSID",
                "__Secure-3PSID",
                "__Secure-1PAPISID",
                "__Secure-3PAPISID",
            }
            yt["auth_cookies"] = len(auth)
            yt["refreshed"] = _json_clean(datetime.fromtimestamp(_os.path.getmtime(cpath)).astimezone())
            tlatest = s1("SELECT MAX(ingested_at) FROM youtube_transcripts")
            age_h = None
            if tlatest:
                age_h = (
                    (datetime.now(tlatest.tzinfo) - tlatest).total_seconds() / 3600
                    if hasattr(tlatest, "tzinfo") and tlatest.tzinfo
                    else None
                )
            if not auth:
                yt["status"], yt["detail"] = "red", "logged-out cookies — refresh config/youtube_cookies.txt"
            elif age_h is not None and age_h > 72:
                yt["status"], yt["detail"] = "amber", f"authenticated, but ingestion {round(age_h)}h stale"
            else:
                yt["status"], yt["detail"] = "green", "authenticated + ingestion flowing"
    except Exception:
        pass

    # Hermes research by status (curation routing ratios)
    hr = {
        r["status"]: r["cnt"]
        for r in (_db_query("SELECT status, COUNT(*) cnt FROM hermes_research_intelligence GROUP BY status") or [])
    }
    # Iris proposal funnel
    ir = {
        r["status"]: r["cnt"]
        for r in (_db_query("SELECT status, COUNT(*) cnt FROM iris_taxonomy_proposals GROUP BY status") or [])
    }
    # Agent job queue
    jq = {
        r["status"]: r["cnt"]
        for r in (
            _db_query(
                "SELECT status, COUNT(*) cnt FROM watchlist_agent_jobs WHERE status IN ('queued','processing','pending') GROUP BY status"
            )
            or []
        )
    }

    return {
        "as_of": datetime.now().astimezone().isoformat(),
        "ingestion": {
            "news_today": s1("SELECT COUNT(*) FROM news_articles WHERE created_at::date=CURRENT_DATE"),
            "news_7d": s1("SELECT COUNT(*) FROM news_articles WHERE created_at>NOW()-INTERVAL '7 days'"),
            "news_latest": ts("SELECT MAX(created_at) FROM news_articles"),
            "topics_active": s1("SELECT COUNT(*) FROM topic_monitor WHERE enabled=true"),
            "transcripts_total": s1("SELECT COUNT(*) FROM youtube_transcripts"),
            "transcripts_latest": ts("SELECT MAX(ingested_at) FROM youtube_transcripts"),
            "sec_form4_7d": s1("SELECT COUNT(*) FROM sec_form4 WHERE created_at>NOW()-INTERVAL '7 days'"),
            "sec_latest": ts("SELECT MAX(created_at) FROM sec_form4"),
            "youtube_cookies": yt,
        },
        "curation": {
            "iris_pending": ir.get("pending", 0),
            "iris_approved": ir.get("approved", 0),
            "iris_expired": ir.get("expired", 0),
            "hermes_promoted": hr.get("promoted", 0),
            "hermes_staged": hr.get("staged", 0),
            "hermes_research_backlog": hr.get("research_backlog", 0),
            "momentum_catalyst_today": s1(
                "SELECT COUNT(*) FROM hermes_research_intelligence WHERE research_type='momentum_catalyst' AND created_at::date=CURRENT_DATE"
            ),
        },
        "llm": {
            "agent_results_today": s1(
                "SELECT COUNT(*) FROM watchlist_agent_results WHERE created_at::date=CURRENT_DATE"
            ),
            "agent_results_7d": s1(
                "SELECT COUNT(*) FROM watchlist_agent_results WHERE created_at>NOW()-INTERVAL '7 days'"
            ),
            "holdings_llm_count": s1(
                "SELECT COUNT(*) FROM watchlist_items WHERE source='portfolio' AND holdings_llm_health IS NOT NULL"
            ),
            "holdings_llm_latest": ts("SELECT MAX(holdings_llm_at) FROM watchlist_items WHERE source='portfolio'"),
            "daily_sections": s1("SELECT COUNT(*) FROM llm_intelligence_cache"),
            "daily_sections_latest": ts("SELECT MAX(generated_at) FROM llm_intelligence_cache"),
        },
        "rag": {
            "corpus_total": s1("SELECT COUNT(*) FROM content_embeddings"),
            "corpus_7d": s1("SELECT COUNT(*) FROM content_embeddings WHERE created_at>NOW()-INTERVAL '7 days'"),
            "model": s1(
                "SELECT embedding_model FROM content_embeddings WHERE embedding_model IS NOT NULL ORDER BY created_at DESC LIMIT 1"
            ),
            "latest": ts("SELECT MAX(created_at) FROM content_embeddings"),
            "hermes_promoted": hr.get("promoted", 0),
            "hermes_embedded": s1("SELECT COUNT(*) FROM content_embeddings WHERE source_type='hermes_research'"),
            "hermes_queue_pending": s1("SELECT COUNT(*) FROM hermes_embedding_queue WHERE embedding_status='pending'"),
            "hermes_queue_failed": s1("SELECT COUNT(*) FROM hermes_embedding_queue WHERE embedding_status='failed'"),
        },
        "jobs": {
            "queued": jq.get("queued", 0),
            "processing": jq.get("processing", 0),
            "pending": jq.get("pending", 0),
            "completed_today": s1(
                "SELECT COUNT(*) FROM watchlist_agent_jobs WHERE status='completed' AND completed_at::date=CURRENT_DATE"
            ),
            "failed_today": s1(
                "SELECT COUNT(*) FROM watchlist_agent_jobs WHERE status='failed' AND completed_at::date=CURRENT_DATE"
            ),
        },
    }


