def _pi_score(d: dict) -> int:
    """Position Intelligence score — ports v1 piScore() exactly."""
    score = 50
    rsi = float(d.get("rsi") or 50)
    s50 = float(d.get("sma50_pct") or 0)
    s200 = float(d.get("sma200_pct") or 0)
    w52h = float(d.get("week52_high_pct") or 0)
    w52l = float(d.get("week52_low_pct") or 0)
    pos52 = 50
    if w52h != 0 or w52l != 0:
        rng = abs(w52h) + abs(w52l)
        pos52 = (abs(w52l) / rng * 100) if rng > 0 else 50
    short_flt = float(d.get("short_float_pct") or 0)
    eps_growth = float(d.get("eps_qoq") or d.get("eps_past_5y") or 0)
    # SMA alignment
    if s200 > 0 and s50 > 0:
        score += 12
    elif s200 > 0:
        score += 5
    elif s200 < -5:
        score -= 12
    # RSI zone
    if rsi > 70:
        score -= 8
    elif rsi > 55:
        score += 5
    elif rsi < 30:
        score -= 10
    elif rsi < 45:
        score -= 4
    # 52wk position
    if pos52 > 80:
        score += 8
    elif pos52 > 60:
        score += 3
    elif pos52 < 20:
        score -= 8
    # Short float
    if short_flt > 20:
        score -= 5
    # EPS growth
    if eps_growth > 15:
        score += 6
    elif eps_growth > 5:
        score += 3
    elif eps_growth < -10:
        score -= 5
    return max(0, min(100, score))


def _weighted_beta(positions):
    """Compute market-value-weighted beta from enrichment cache. Null-safe: a new/unpriced position
    (e.g. just-bought SPCX or a delisted CUSIP) may carry beta=None and/or market_value=None — default
    beta to 1.0 and treat missing market_value as 0 so one new holding can't crash the whole overview."""
    ec = _load_json(STATE_DIR / "ticker_enrichment_cache.json") or {}
    total_mv = sum((p.get("market_value") or 0) for p in positions)
    if total_mv <= 0:
        return 0
    beta_sum = 0.0
    for p in positions:
        sym = p.get("symbol", "")
        raw = (ec.get(sym) or {}).get("beta") if isinstance(ec.get(sym), dict) else None
        try:
            beta = float(raw) if raw is not None else 1.0
        except (TypeError, ValueError):
            beta = 1.0
        weight = (p.get("market_value") or 0) / total_mv
        beta_sum += beta * weight
    return round(beta_sum, 3)


def _live_portfolio_day_change(holdings_list):
    """Portfolio day change = Σ per-holding day $ recomputed from the fresh Finviz day % at the live
    Finviz price. The stored portfolio_totals.day_change and per-row day_change go $0 whenever the
    repricer wrote prev_price == new_price, so summing them silently under-counts (the header read
    +$171 while the book had moved ~+$5,258). Shared by /overview (header TODAY) and
    /portfolio/performance (Returns 1D) so both surfaces agree. Returns None if it cannot compute."""
    try:
        import sys as _s

        _lib = str(PROJECT_ROOT / "scripts" / "lib")
        if _lib not in _s.path:
            _s.path.insert(0, _lib)
        from holding_day_change import resolve_holding_day_change as _rhdc

        _fv = _load_json(STATE_DIR / "finviz_quote_cache.json") or {}
        _day: dict[str, float] = {}
        _px: dict[str, float] = {}
        for _fs, _fr in _fv.items():
            if not isinstance(_fr, dict):
                continue
            _u = str(_fs).upper()
            if _fr.get("change_pct") is not None:
                try:
                    _day[_u] = float(_fr["change_pct"])
                except (TypeError, ValueError):
                    pass
            if _fr.get("price"):
                try:
                    _px[_u] = float(_fr["price"])
                except (TypeError, ValueError):
                    pass
        _tc = 0.0
        for _p in holdings_list or []:
            if _p.get("is_cash") or _p.get("is_loan"):
                continue
            _u = str(_p.get("symbol") or "").upper()
            _fvpx = _px.get(_u)
            _sh = float(_p.get("shares") or 0)
            _mv = (_sh * _fvpx) if (_fvpx and _sh) else float(_p.get("market_value") or 0)
            _pxp = _fvpx or float(_p.get("price") or 0)
            _dc, _ = _rhdc(_p, market_value=_mv, price=_pxp, stale_price=_pxp, finviz_day_pct=_day.get(_u))
            _tc += _dc or 0
        return round(_tc, 2)
    except Exception:
        return None


def overview():
    # ── Canonical observation contract ───────────────────────────────────────
    # This payload is built from four separate stores. Until now it emitted the
    # value from one and the freshness metadata from another with no check
    # between them, which is how a 3-second-old portfolio value shipped beside
    # 7.4-day-old periods and a hardcoded "fresh"
    # (audit cc-truth-v1-20260902T202759Z). Each store is now read ONCE through
    # an envelope that carries its own resolved path, hash, clocks and computed
    # freshness, so value and metadata travel together and a divergent root is
    # visible in the payload instead of silent.
    from lib.canonical_observation import (
        NOT_FRESH,
        envelope_diagnostics,
        new_trace_id,
        observe_state_file,
        position_count_contract,
        worst_status,
    )

    _trace = new_trace_id()
    h, _env_h = observe_state_file("holdings.json", observed_at_field="last_repriced", trace_id=_trace)
    perf, _env_perf = observe_state_file("performance_history.json", trace_id=_trace)
    fresh, _env_fresh = observe_state_file("_freshness.json", trace_id=_trace)
    news, _env_news = observe_state_file("portfolio_news.json", trace_id=_trace)
    _envelopes = {
        "holdings": _env_h,
        "performance_history": _env_perf,
        "freshness": _env_fresh,
        "portfolio_news": _env_news,
    }

    holdings = h.get("holdings", [])
    totals = h.get("portfolio_totals", {})
    periods = perf.get("periods", {})
    active_positions = [p for p in holdings if not p.get("is_cash") and (p.get("market_value") or 0) > 100]

    # ── Data Broker Wave B: pre-computed snapshot replaces individual recomputes ──
    from lib.data_broker.portfolio_snapshot import get_portfolio_snapshot

    # write_on_miss=False: a GET must not mutate a store. This handler used to
    # publish portfolio_snapshot.json on every cache miss, so the snapshot was
    # refreshed by whoever browsed rather than on a schedule.
    snap = get_portfolio_snapshot(write_on_miss=False)
    snap_totals = snap.get("totals", {})

    # Sector allocation — sourced from broker snapshot (pre-computed, cached ≤45s)
    sector_list = [
        (s.get("sector") or "Other / Unclassified", s.get("value") or 0)
        for s in snap.get("sector_allocation", [])
        if (s.get("value") or 0) > 0
    ][:13]
    if not sector_list:
        # Fallback: per-row aggregation (only when snapshot is unavailable)
        sectors = {}
        for p in active_positions:
            s = p.get("sector_type") or "Other"
            sectors[s] = sectors.get(s, 0) + (p.get("market_value") or 0)
        sector_list = sorted(sectors.items(), key=lambda x: -x[1])[:10]

    # Top movers — from broker snapshot
    snap_mover_syms = {str(m.get("symbol") or "").upper() for m in snap.get("top_movers", [])}
    movers = [p for p in holdings if str(p.get("symbol") or "").upper() in snap_mover_syms]
    if not movers:
        movers = sorted(active_positions, key=lambda p: abs(p.get("day_change") or 0), reverse=True)[:6]

    # Notifications count — remaining direct DB reads (not covered by broker snapshot)
    notif_rows = _db_query("SELECT count(*) AS cnt FROM notification_log", fetch="one")
    aq_cnt = (_db_query("SELECT count(*) AS cnt FROM action_queue WHERE status='pending'", fetch="one") or {}).get(
        "cnt", 0
    )
    jdq_cnt = (
        _db_query("SELECT count(*) AS cnt FROM john_decision_queue WHERE status='pending_john'", fetch="one") or {}
    ).get("cnt", 0)
    pending_rows = {"cnt": aq_cnt + jdq_cnt}

    # Today's change — from broker snapshot (uses same _day_change logic as _live_portfolio_day_change)
    total_val = snap_totals.get("total_value", 0) or totals.get("total_value", 0) or 0
    today_change = snap_totals.get("day_change") or 0
    today_pct = snap_totals.get("day_change_pct", 0) or 0
    if today_change is None or today_change == 0:
        today_change = _live_portfolio_day_change(holdings)
        if today_change is None or today_change == 0:
            today_change = totals.get("day_change")
            if today_change is None:
                today_change = sum(p.get("day_change") or 0 for p in holdings)
        if today_change is not None:
            today_pct = (today_change / (total_val - today_change) * 100) if total_val > abs(today_change or 0) else 0

    # per-account breakdown — from broker snapshot, with per-account top-movers from holdings
    today_by_account = {}
    for a, d in snap.get("by_account", {}).items():
        entry = {"change": d.get("change", 0), "value": d.get("value", 0), "pct": d.get("pct")}
        movers_a = sorted(
            [p for p in holdings if (p.get("account") or "unknown") == a],
            key=lambda p: abs(p.get("day_change") or 0),
            reverse=True,
        )[:2]
        entry["top_movers"] = "; ".join(
            f"{m.get('symbol')} {('+' if (m.get('day_change') or 0) >= 0 else '')}{round(m.get('day_change') or 0)}"
            for m in movers_a
            if m.get("day_change")
        )
        today_by_account[a] = entry
    # Ensure every known account gets an entry (snapshot may only cover accounts with activity)
    for p in holdings:
        a = p.get("account") or "unknown"
        if a not in today_by_account:
            today_by_account[a] = {"change": 0.0, "value": 0.0, "pct": None, "top_movers": ""}

    # Trade AI run data — read from the SAME cached payload the summary
    # endpoint serves, so overview and /trade-ai/summary can never disagree on
    # the canonical run identity and counts (cc-header-truth-v2 Phase 2 C).
    # trade_ai() is cache-backed and never recomputes on the request path.
    tai = trade_ai() or {}

    # Journal stats (exclude flat/zero-pnl trades from win rate, matching v1)
    # Headline journal metrics — the LOCAL journal the operator sees on the Journal page: broker-verified
    # round trips in trade_closed (refreshed from schwab_round_trips by the 6:15pm + intraday cron;
    # unknown-basis + canary trips excluded). Same source + filter as /api/v2/journal, so the header tiles
    # tie exactly to the Journal page (157 / 50.3% / $150,706, current through today). Operator 2026-07-21:
    # switched OFF the legacy_fifo_journal basis (trade_journal.json), which was frozen at the last manual
    # CSV import (2026-04-30) and read 83 days stale. Falls back to the legacy CSV only if the table is empty.
    # Split ACTIVE TRADING from LONG-TERM TRIMS (operator 2026-07-21). Selling decades-old buy-and-hold
    # lots (e.g. a 17-yr Visa position, classification long_term_trim) is not a trading decision, yet it
    # was 76% of realized P&L ($114.6k of $150.7k). The headline "trading" tiles must reflect trading
    # skill (day_trade + swing); the full realized figure (incl. trims) is shown separately.
    j_basis = "broker_round_trips"
    j_trade_count = 0
    j_total_pnl = 0.0
    j_win_rate = 0.0
    j_realized_count = 0
    j_realized_pnl = 0.0
    j_realized_win_rate = 0.0
    j_long_term_trim_pnl = 0.0
    j_last_close = None
    try:
        _jr = (
            _db_query(
                "WITH j AS ("
                "  SELECT tc.pnl AS pnl, COALESCE(srt.classification,'') AS cls, tc.close_date AS close_date "
                "  FROM trade_closed tc "
                "  LEFT JOIN schwab_round_trips srt ON tc.dedupe_key = 'srt:' || srt.id "
                "  WHERE tc.buy_price > 0 OR tc.pnl != 0"
                ") "
                "SELECT "
                "  count(*) FILTER (WHERE cls NOT IN ('long_term_trim','pre_window_trim') AND pnl!=0) AS trade_n, "
                "  COALESCE(SUM((pnl>0)::int) FILTER (WHERE cls NOT IN ('long_term_trim','pre_window_trim') AND pnl!=0),0) AS trade_wins, "
                "  COALESCE(SUM(pnl) FILTER (WHERE cls NOT IN ('long_term_trim','pre_window_trim') AND pnl!=0),0) AS trade_pnl, "
                "  count(*) FILTER (WHERE pnl!=0) AS all_n, "
                "  COALESCE(SUM((pnl>0)::int) FILTER (WHERE pnl!=0),0) AS all_wins, "
                "  COALESCE(SUM(pnl) FILTER (WHERE pnl!=0),0) AS all_pnl, "
                "  COALESCE(SUM(pnl) FILTER (WHERE cls='long_term_trim'),0) AS ltt_pnl, "
                "  MAX(close_date) AS last_close "
                "FROM j",
                fetch="one",
            )
            or {}
        )
        _tn = int(_jr.get("trade_n") or 0)
        _an = int(_jr.get("all_n") or 0)
        if _an > 0:
            j_trade_count = _tn
            j_total_pnl = float(_jr.get("trade_pnl") or 0)
            j_win_rate = round(100.0 * float(_jr.get("trade_wins") or 0) / _tn, 1) if _tn else 0.0
            j_realized_count = _an
            j_realized_pnl = float(_jr.get("all_pnl") or 0)
            j_realized_win_rate = round(100.0 * float(_jr.get("all_wins") or 0) / _an, 1)
            j_long_term_trim_pnl = float(_jr.get("ltt_pnl") or 0)
            _lc = _jr.get("last_close")
            j_last_close = _lc.isoformat() if hasattr(_lc, "isoformat") else (str(_lc) if _lc else None)
    except Exception:
        j_trade_count = 0
    # Journal-pipeline freshness (rebase the STALE badge here, NOT on last close date). trade_closed
    # schwab rows are DELETE-then-INSERTed with created_at=NOW() on every schwab_journal_builder --apply,
    # so MAX(created_at) = last successful rebuild. This is the real "is the journal up to date" signal;
    # last_close_date (above) is just "when did I last close a position", which is legitimately old during
    # a quiet market and must NOT be flagged as stale data.
    j_last_ingested = None
    j_ledger_last_trade = None
    try:
        _ing = (
            _db_query(
                "SELECT MAX(created_at) AS last_ingested_at FROM trade_closed WHERE account LIKE 'schwab%'", fetch="one"
            )
            or {}
        )
        _lt = (
            _db_query(
                "SELECT MAX(trade_time) AS last_trade_time FROM trade_transactions WHERE import_source='schwab_api'",
                fetch="one",
            )
            or {}
        )
        _ia, _ltv = _ing.get("last_ingested_at"), _lt.get("last_trade_time")
        j_last_ingested = _ia.isoformat() if hasattr(_ia, "isoformat") else (str(_ia) if _ia else None)
        j_ledger_last_trade = _ltv.isoformat() if hasattr(_ltv, "isoformat") else (str(_ltv) if _ltv else None)
    except Exception:
        j_last_ingested = j_ledger_last_trade = None
    if j_trade_count == 0:
        journal = _load_json(STATE_DIR / "trade_journal.json") or {}
        j_all = journal.get("closed_trades") or journal.get("trades") or []
        j_total_pnl = sum(t.get("pnl") or t.get("realized_pnl") or 0 for t in j_all)
        j_real = [t for t in j_all if (t.get("pnl") or t.get("realized_pnl") or 0) != 0]
        j_wins = sum(1 for t in j_real if (t.get("pnl") or t.get("realized_pnl") or 0) > 0)
        j_win_rate = (j_wins / len(j_real) * 100) if j_real else 0
        j_stats = journal.get("stats", {})
        if j_stats.get("win_rate"):
            j_win_rate = j_stats["win_rate"]
        if j_stats.get("total_pnl") is not None:
            j_total_pnl = j_stats["total_pnl"]
        j_trade_count = len(j_all)
        j_last_close = max((t.get("close_date") or "" for t in j_all), default="") or None
        j_basis = "legacy_fifo_journal"
        # No classification split available for the legacy CSV — realized mirrors the single figure.
        j_realized_count = j_trade_count
        j_realized_pnl = j_total_pnl
        j_realized_win_rate = j_win_rate

    # Watch Desk v2 (A1): portfolio_totals.total_value is CANONICAL. The old
    # ">$500 drift → silently swap to derived" rule made the shell header flip
    # $96.9K whenever SPAXX (Fidelity MM sweep) was momentarily unpriced during
    # a pipeline run — an unlabeled scope change on every page. Derived only
    # fills in when totals are missing entirely; drift is FLAGGED, never swapped.
    _derived_total = round(sum(p.get("market_value") or 0 for p in holdings), 2)
    _total_drift = round(_derived_total - (total_val or 0), 2) if _derived_total > 0 else 0
    if _derived_total > 0 and not total_val:
        total_val = _derived_total
        today_change = round(sum(p.get("day_change") or 0 for p in holdings), 2)
        today_pct = (today_change / (total_val - today_change) * 100) if total_val > abs(today_change) else 0
    _fv_meta = (_load_json(STATE_DIR / "finviz_quote_cache.json") or {}).get("_meta") or {}
    # Cash = sum of the actual CASH positions. The stored portfolio_totals.total_cash had drifted to
    # $478k while the real cash was $186k. The read-site recompute that used to
    # live here was a workaround for a field nothing refreshed, and it is now
    # retired: #635 made portfolio_repricer._recalc_totals write total_cash from
    # the is_cash position rows on every pass.
    #
    # The 2026-08-29 Saturday proof once showed the stored field agreeing with
    # the row sum to the cent at 630,784.82 (gap 0.00). That sentence is no
    # longer true as a live claim: on 2026-09-01 the live row sum /
    # portfolio_totals.total_cash / overview / capital_plan read 630,513.62,
    # while cash_letter still published the CASH_SLEEVE fossil 630,784.82
    # (delta $271.20 — LITMUS_MONEY). The letter now follows capital_plan; the
    # fossil remains as prior_cash_* on that payload. Do not resurrect
    # 630,784.82 as proof of agreement.
    #
    # Read the stored field. Two places deriving the same number is how the
    # original drift went unnoticed for three months: the read site quietly
    # papered over a writer that had stopped writing.
    _total_cash = totals.get("total_cash")
    if _total_cash is None:
        # No stored value at all is a real gap, not something to silently
        # reconstruct — surface 0 and let the data-quality surface say so.
        _total_cash = 0

    # ── Position-count contract ──────────────────────────────────────────────
    # The audit measured overview 14 against risk 15. Neither was wrong: they
    # count different populations, and two unlabeled integers cannot say so, so
    # a consumer is forced to read one as a contradiction of the other. Publish
    # every scope BY NAME with its rule, plus an explicit agreement flag.
    _rm_positions = (_load_json(STATE_DIR / "risk_management.json") or {}).get("positions", [])
    _position_counts = position_count_contract(
        {
            "overview.non_cash_over_100": len(active_positions),
            "holdings.all_rows": len(holdings),
            "holdings.non_cash": sum(1 for p in holdings if not p.get("is_cash")),
            "risk.risk_included": sum(1 for p in _rm_positions if not p.get("risk_excluded")),
        }
    )
    _position_counts["scope_definitions"] = {
        "overview.non_cash_over_100": "holdings.json rows where not is_cash and market_value > 100",
        "holdings.all_rows": "every row in holdings.json including cash",
        "holdings.non_cash": "holdings.json rows where not is_cash, no value floor",
        "risk.risk_included": "risk_management.json positions where not risk_excluded (same rule as GET /api/v2/risk)",
    }

    # ── Surface freshness ────────────────────────────────────────────────────
    # As fresh as the OLDEST contributing dataset, never as fresh as the newest.
    _surface_status = worst_status(_envelopes)
    _observation_block = {
        "trace_id": _trace,
        "surface_status": _surface_status,
        "snapshot_cache": snap.get("_cache", {}),
        "snapshot_computed_at": snap.get("computed_at"),
        "read_only": True,
        "envelopes": {name: env.to_dict() for name, env in _envelopes.items()},
        "diagnostics": envelope_diagnostics(_envelopes),
        "not_fresh_datasets": sorted(n for n, e in _envelopes.items() if e.status in NOT_FRESH),
        "position_counts": _position_counts,
    }

    # ── Portfolio aggregate contract (cc-header-truth-v2 Phase 2 A) ──────────
    # The header total is an ALL-ACCOUNTS aggregate. Oldest/newest MUST come from
    # the same accounts[] observation times (never mix top-level data_as_of for
    # oldest with account_summaries for newest — live acceptance 2026-09-03).
    from lib.portfolio_aggregate_contract import build_portfolio_aggregate

    # v2: the valuation clock and the quote clock are supplied EXPLICITLY. They
    # are not derived from the position observations and never substitute for
    # them -- that conflation is what dated a July-observed book "2026-09-03".
    _portfolio_aggregate = build_portfolio_aggregate(
        aggregate_value=total_val,
        account_summaries=h.get("account_summaries") or {},
        data_as_of=h.get("data_as_of"),
        data_as_of_account=h.get("data_as_of_account"),
        # The position rows are the maintained copy of the position clock;
        # account_summaries.as_of is an abandoned mirror. Both are published.
        positions=h.get("holdings"),
        valuation_time=h.get("generated_at") or h.get("updated_at"),
        quote_observation_time=h.get("last_repriced"),
        quote_source=h.get("reprice_source"),
    )

    # Canonical quote-selection projection (cc-header-truth-v2 Phase 2 B).
    # One source of truth for provider roles; reports what the repricer did.
    from lib.quote_selection_contract import project_quote_selection

    _q_src_counts: dict[str, int] = {}
    for _p in active_positions:
        _qs = str(_p.get("price_source") or _p.get("canonical_mark_source") or "").lower()
        _q_src_counts[_qs] = _q_src_counts.get(_qs, 0) + 1
    _quote_selection = project_quote_selection(
        reprice_source=h.get("reprice_source", ""),
        last_repriced=h.get("last_repriced", ""),
        source_counts=_q_src_counts,
        has_any_price=bool(total_val),
    )

    return {
        "portfolio_value": total_val,
        "portfolio_aggregate": _portfolio_aggregate,
        "quote_selection": _quote_selection,
        "derived_total_value": _derived_total,
        # non-zero while a position is unpriced mid-pipeline (e.g. SPAXX) —
        # UI may show a subtle "repricing…" hint but the total never flips
        "total_value_drift": _total_drift if abs(_total_drift) > 500 else 0,
        "total_cash": _total_cash,
        "today_change": round(today_change, 2),
        "today_pct": round(today_pct, 2),
        "reprice_source": h.get("reprice_source", ""),
        "pricing": {
            "last_repriced": h.get("last_repriced", ""),
            "reprice_source": h.get("reprice_source", ""),
            "finviz_cache_updated": _fv_meta.get("last_updated", ""),
            "holdings_as_of": h.get("as_of", ""),
            "derived_total_value": _derived_total,
            "canonical_total_value": totals.get("total_value", 0),
        },
        "today_by_account": today_by_account,
        "today_pnl": _today_pnl_provenance(
            h,
            today_by_account=today_by_account,
            account_summaries=h.get("account_summaries") or {},
            positions=h.get("holdings"),
            total_change=today_change,
        ),
        "position_count": len(active_positions),
        # Named scopes so overview and risk can never silently disagree again.
        "position_counts": _position_counts,
        "account_count": len(h.get("account_summaries", {})),
        "as_of": h.get("as_of", ""),
        # as_of records WHEN THE LOADER RAN, not when any data was fetched: it is
        # written `= today` by portfolio_loader. On 2026-09-01 it read 2026-08-29
        # while the Schwab rows carried 08-31 and the moomoo/alpaca CASH rows
        # carried 08-03/04 -- older than 28 of 30 rows and newer than the other 2,
        # so it was wrong in both directions at once and described nothing in the
        # file. data_as_of is the OLDEST contributing row, with the account that
        # owns it, so a stale $500 cash row cannot hide behind 28 fresh equity
        # rows (AGENTS.md 9.1: "a 27-day-old $500 makes the block 27 days old").
        "data_as_of": h.get("data_as_of"),
        "data_as_of_account": h.get("data_as_of_account"),
        "last_repriced": h.get("last_repriced", ""),
        "periods": {
            k: {
                "change_pct": v.get("change_pct"),
                "change": v.get("change"),
                "estimated": v.get("source") == "repriced",
            }
            for k, v in periods.items()
            if isinstance(v, dict)
        },
        "sectors": [{"name": n, "value": v} for n, v in sector_list],
        "sectors_by_account": {
            acct: [{"name": r.get("sector"), "value": r.get("value")} for r in (rows or [])]
            for acct, rows in (h.get("resolved_sectors_by_account") or {}).items()
        },
        # Allocation drill-down: which positions / underlyings feed each look-through sector
        "sector_contributors": h.get("resolved_sector_contributors") or {},
        "sector_underlyings": h.get("resolved_sector_underlyings") or {},
        "lookthrough_as_of": h.get("lookthrough_as_of") or "",
        "top_movers": [
            {
                "symbol": m.get("symbol"),
                "name": (m.get("name") or "")[:30],
                "day_change": m.get("day_change", 0),
                "day_change_pct": m.get("day_change_pct", 0),
            }
            for m in movers
        ],
        "trade_ai": {
            "vix": tai.get("vix"),
            "vix_source": tai.get("vix_source"),
            "vix_observation_time": tai.get("vix_observation_time"),
            "breadth": tai.get("breadth"),
            "market_regime": tai.get("market_regime"),
            "run_id": tai.get("run_id"),
            "setup_run_summary": tai.get("setup_run_summary"),
            "go_count": tai.get("go_count", tai.get("current_run_go", 0)),
            "wait_count": tai.get("wait_count", tai.get("current_run_wait", 0)),
            "no_go_count": tai.get("avoid_count", tai.get("current_run_nogo", 0)),
            "run_date": tai.get("run_date", tai.get("date", "")),
            "run_label": tai.get("run_label", tai.get("run_label", "")),
        },
        "journal": {
            # TRADING = active decisions (day_trade + swing); the headline win-rate/P&L tile.
            "trade_count": j_trade_count,
            "total_pnl": round(j_total_pnl, 2),
            "win_rate": round(j_win_rate, 1),
            # REALIZED = all closed trades incl. long-term trims of old buy-and-hold lots (shown as a
            # separate tile so decades-old-position gains don't inflate the trading number).
            "realized_count": j_realized_count,
            "realized_pnl": round(j_realized_pnl, 2),
            "realized_win_rate": round(j_realized_win_rate, 1),
            "long_term_trim_pnl": round(j_long_term_trim_pnl, 2),
            "source": "journal",
            # 2026-07-21: reads the LOCAL broker-verified journal (trade_closed, same source as
            # /api/v2/journal); was legacy_fifo_journal (trade_journal.json), frozen at the last CSV import.
            "basis": j_basis,
            "last_close_date": j_last_close,
            "last_ingested_at": j_last_ingested,
            "ledger_last_trade_time": j_ledger_last_trade,
            # Provenance (cc-header-truth-v2 Phase 2 E): the header must state the
            # basis, window, account scope and as-of so TRADING and REALIZED can
            # never be mistaken for a mixed-source or differently-windowed figure.
            "calculation_version": "JournalMetrics@v1",
            "account_scope": "schwab",
            "time_window": "all_time",
            "as_of": j_last_ingested,
            "quality": "OK" if j_basis == "broker_round_trips" else "DEGRADED",
        },
        "news_count": len(news.get("catalysts", [])),
        "notification_count": (notif_rows or {}).get("cnt", 0),
        "pending_approvals": (pending_rows or {}).get("cnt", 0),
        # COMPUTED from the observation envelopes, not republished from the
        # file. `fresh["status"]` was a literal written unconditionally by
        # portfolio_orchestrator.py, so a stranded file reported "fresh"
        # indefinitely; and the surface is only as fresh as its oldest
        # contributing dataset (AGENTS.md 9.1). Fails closed to unknown.
        "pipeline_status": _surface_status.lower(),
        "pipeline_status_source": "computed:canonical_observation",
        "pipeline_status_reported": fresh.get("status", "unknown"),
        "pipeline_completed": fresh.get("completed_at", ""),
        "observation": _observation_block,
        # Sprint 4A additions (total_cash / last_repriced already set above — do not rekey)
        "weighted_beta": _weighted_beta(active_positions),
        "concentration_alerts": [
            {"symbol": p.get("symbol"), "pct": p.get("portfolio_pct", 0)}
            for p in active_positions
            if (p.get("portfolio_pct") or 0) > 20
        ],
        "pending_pipeline": h.get("pending_pipeline_run", False),
        "index_tape": {
            "spy": tai.get("spy"),
            "qqq": tai.get("qqq"),
            "iwm": tai.get("iwm"),
        },
        "delta_events": tai.get("delta_events", 0),
    }


def _fib_analysis(price, high_pct, low_pct):
    """52-week fib retracement from %-from-high / %-above-low. The retracement position
    and nearest level are computable from the percentages alone (price cancels out);
    absolute dollar levels are added only when a real `price` is supplied (proxies omit
    them since the proxy's price scale differs from the fund NAV). Returns None if not
    computable (e.g. NAV-priced funds with no technical data)."""
    try:
        high_pct = float(high_pct)
        low_pct = float(low_pct)
    except (TypeError, ValueError):
        return None
    # Work in a price-independent frame (P=100) to get the retracement position.
    try:
        rel_high = 100.0 / (1 + high_pct / 100.0)  # high_pct = (price-high)/high*100
        rel_low = 100.0 / (1 + low_pct / 100.0)  # low_pct  = (price-low)/low*100
    except ZeroDivisionError:
        return None
    rel_rng = rel_high - rel_low
    if rel_rng <= 0 or rel_high <= 0:
        return None
    ratios = [
        ("0% (52w high)", 0.0),
        ("23.6%", 0.236),
        ("38.2%", 0.382),
        ("50%", 0.5),
        ("61.8%", 0.618),
        ("78.6%", 0.786),
        ("100% (52w low)", 1.0),
    ]
    retr = (rel_high - 100.0) / rel_rng * 100.0  # 0 at high, 100 at low
    nearest = min(ratios, key=lambda lr: abs(lr[1] * 100 - retr))
    out = {"retracement_from_high_pct": round(retr, 1), "nearest_level": nearest[0]}
    # Absolute dollar levels only when a real price is provided.
    try:
        p = float(price)
        if p > 0:
            high = p / (1 + high_pct / 100.0)
            low = p / (1 + low_pct / 100.0)
            rng = high - low
            if rng > 0:
                out["week52_high"] = round(high, 2)
                out["week52_low"] = round(low, 2)
                out["levels"] = {label: round(high - rng * r, 2) for label, r in ratios}
    except (TypeError, ValueError):
        pass
    return out


