# ── Share reconciliation (dividend reinvestment / broker drift) ─────────────────


def _share_drift_list(query=None):
    """GET /api/v2/holdings/share-drift — open (and active-snoozed) share drift tasks."""
    try:
        import share_reconciliation as sr

        open_tasks = sr.list_open_drifts(include_snoozed=True)
        # attach impact previews (lightweight)
        for t in open_tasks:
            try:
                t["impact"] = sr.impact_preview(t["account_key"], t["symbol"])
            except Exception:
                t["impact"] = None
        return {"ok": True, "count": len(open_tasks), "items": open_tasks}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200], "items": []}


def _share_drift_history(query=None):
    """GET /api/v2/holdings/share-reconciliation/history?account=&symbol=&limit="""
    try:
        import share_reconciliation as sr

        q = query or {}
        acct = (q.get("account") or [None])[0] if isinstance(q.get("account"), list) else q.get("account")
        sym = (q.get("symbol") or [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol")
        lim = q.get("limit") or 50
        if isinstance(lim, list):
            lim = lim[0]
        return {"ok": True, "history": sr.history(acct, sym, int(lim or 50))}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200], "history": []}


def _share_drift_impact(query=None):
    """GET /api/v2/holdings/share-drift/impact?account=&symbol="""
    try:
        import share_reconciliation as sr

        q = query or {}
        acct = (q.get("account") or [None])[0] if isinstance(q.get("account"), list) else q.get("account")
        sym = (q.get("symbol") or [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol")
        if not (acct and sym):
            return {"ok": False, "error": "account and symbol required"}
        return sr.impact_preview(str(acct), str(sym))
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _share_drift_apply(body=None):
    """POST /api/v2/holdings/share-drift/apply — set system_shares = broker (approval).

    Body: {account, symbol, task_id?, source?, notes?, new_shares?}
    """
    try:
        import share_reconciliation as sr

        b = body or {}
        acct = str(b.get("account") or b.get("account_key") or "").strip()
        sym = str(b.get("symbol") or "").strip().upper()
        if not (acct and sym):
            return {"ok": False, "error": "account and symbol required"}
        tid = b.get("task_id")
        try:
            tid = int(tid) if tid is not None else None
        except (TypeError, ValueError):
            tid = None
        ns = b.get("new_shares")
        try:
            ns = float(ns) if ns is not None else None
        except (TypeError, ValueError):
            ns = None
        return sr.apply_reconciliation(
            account=acct,
            symbol=sym,
            source=str(b.get("source") or "manual"),
            notes=b.get("notes"),
            reconciled_by=str(b.get("reconciled_by") or "operator"),
            task_id=tid,
            new_shares=ns,
        )
    except Exception as e:
        return {"ok": False, "error": str(e)[:240]}


def _share_drift_snooze(body=None):
    """POST /api/v2/holdings/share-drift/snooze — body: {task_id, days: 1|7}"""
    try:
        import share_reconciliation as sr

        b = body or {}
        tid = int(b.get("task_id") or 0)
        days = int(b.get("days") or 1)
        if not tid:
            return {"ok": False, "error": "task_id required"}
        return sr.snooze_drift(tid, days=days, notes=b.get("notes"))
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _share_drift_detect(body=None):
    """POST /api/v2/holdings/share-drift/detect — rescan holdings.json and open tasks."""
    try:
        import share_reconciliation as sr

        return sr.detect_from_holdings_file()
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


# ── Position transfer history / rollover normalization ─────────────────────────


def _position_transfer_history(query=None):
    """GET /api/v2/holdings/transfer-history?account=&symbol=&limit="""
    try:
        from lib.position_transfer_normalize import list_transfer_history

        q = query or {}

        def _one(k):
            v = q.get(k)
            return (v[0] if isinstance(v, list) else v) if v is not None else None

        lim = _one("limit") or 50
        try:
            lim = int(lim)
        except (TypeError, ValueError):
            lim = 50
        rows = list_transfer_history(account=_one("account"), symbol=_one("symbol"), limit=lim)
        return {"ok": True, "count": len(rows), "history": rows}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200], "history": []}


def _position_transfer_notifications(query=None):
    """GET /api/v2/holdings/transfer-notifications — active rollover/Roth notices."""
    try:
        from lib.position_transfer_normalize import list_active_notifications

        items = list_active_notifications()
        return {"ok": True, "count": len(items), "items": items}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200], "items": []}


def _position_transfer_dismiss(body=None):
    """POST /api/v2/holdings/transfer-notifications/dismiss — body: {id}"""
    try:
        from lib.position_transfer_normalize import dismiss_notification

        b = body or {}
        nid = int(b.get("id") or b.get("notification_id") or 0)
        if not nid:
            return {"ok": False, "error": "id required"}
        return dismiss_notification(nid)
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _position_transfer_detect(body=None):
    """POST /api/v2/holdings/transfer-detect — re-run transfer normalize on last holdings write.

    Optional body: {dry_run: true} uses prior snapshot if available; otherwise no-op detect
    against current holdings only (partial arrivals still need a prior snapshot).
    """
    try:
        from lib.position_transfer_normalize import process_and_normalize, ensure_tables

        ensure_tables()
        hpath = STATE_DIR / "holdings.json"
        if not hpath.exists():
            return {"ok": False, "error": "holdings.json missing"}
        current = json.loads(hpath.read_text())
        # Prefer most recent backup as prior if present
        prior = None
        bak_dir = STATE_DIR / "backups"
        if bak_dir.is_dir():
            baks = sorted(bak_dir.glob("holdings*.json"), key=lambda p: p.stat().st_mtime, reverse=True)
            for b in baks[:5]:
                try:
                    prior = json.loads(b.read_text())
                    break
                except Exception:
                    continue
        # Also try cost_basis events replay against empty prior won't detect; require prior
        b = body if isinstance(body, dict) else {}
        dry = bool(b.get("dry_run"))
        if prior is None:
            # Still return any stored history
            from lib.position_transfer_normalize import list_transfer_history, list_active_notifications

            return {
                "ok": True,
                "events": 0,
                "summary": "no prior snapshot for re-detect; returning stored history",
                "history": list_transfer_history(limit=50),
                "notifications": list_active_notifications(),
            }
        result = process_and_normalize(prior, current, sync_source="manual_transfer_detect", apply=not dry)
        if not dry and result.get("holdings_doc") and result.get("normalized"):
            try:
                from schwab_position_sync import protected_holdings_write

                protected_holdings_write(
                    result["holdings_doc"],
                    source="transfer_normalize",
                    account_key="portfolio",
                    skip_transfer_detect=True,
                )
            except Exception as we:
                # Fall back to direct write through guard path only
                result["write_error"] = str(we)[:160]
        return result
    except Exception as e:
        return {"ok": False, "error": str(e)[:240]}


def portfolio_holdings():
    h = _load_json(STATE_DIR / "holdings.json") or {}
    ec = _load_json(STATE_DIR / "ticker_enrichment_cache.json") or {}
    ts = _load_json(STATE_DIR / "technical_snapshot.json") or {}
    holdings = h.get("holdings", [])
    # Enrichment freshness: newest mtime of the market-data caches (ISO).
    _enrich_as_of = None
    try:
        import os as _os

        _mtimes = [
            _os.path.getmtime(STATE_DIR / f)
            for f in ("ticker_enrichment_cache.json", "technical_snapshot.json")
            if (STATE_DIR / f).exists()
        ]
        if _mtimes:
            _enrich_as_of = datetime.fromtimestamp(max(_mtimes)).astimezone().isoformat()
    except Exception:
        pass

    # Load cost basis from DB for gain/loss calculation
    basis_map = {}
    basis_rows = (
        _db_query("SELECT symbol, account_key, total_cost_basis, shares, per_share_basis FROM cost_basis_anchors") or []
    )
    for br in basis_rows or []:
        basis_map[(br.get("symbol", ""), br.get("account_key", ""))] = {
            "total": float(br.get("total_cost_basis", 0)),
            "shares": float(br.get("shares") or 0),
            "per_share": float(br.get("per_share_basis") or 0) or None,
        }

    # Load signals and dividend data for enrichment
    signals_data = _load_json(STATE_DIR / "action_signals.json") or {}
    sig_list = signals_data.get("signals", [])
    sig_map = {}
    if isinstance(sig_list, list):
        for s in sig_list:
            sig_map[s.get("symbol", "")] = s.get("signal", "")
    div_data = _load_json(STATE_DIR / "dividend_calendar.json") or {}
    div_map = {}
    for dp in div_data.get("payers", []):
        sym = dp.get("symbol", "")
        if sym not in div_map:
            div_map[sym] = dp.get("yield_pct", 0)

    # Load LLM health data from watchlist_items
    llm_health_map = {}
    llm_rows = (
        _db_query("""
        SELECT symbol, holdings_llm_health, holdings_llm_action,
               holdings_llm_confidence, holdings_llm_summary, holdings_llm_at
        FROM watchlist_items
        WHERE source = 'portfolio' AND holdings_llm_health IS NOT NULL
    """)
        or []
    )
    for lr in llm_rows:
        llm_health_map[lr["symbol"]] = lr

    # lot count per symbol — the holdings-health LLM analysis is SYMBOL-level (one
    # watchlist_items row per symbol), so a multi-lot symbol's facts may describe a
    # different account's lot; the UI labels the block accordingly (operator 2026-07-14:
    # Fidelity SCHD share counts were rendering on the Schwab SCHD drawer unlabeled).
    _lots_per_symbol: dict[str, int] = {}
    for _p in holdings:
        _ls = str(_p.get("symbol") or "").upper()
        if _ls:
            _lots_per_symbol[_ls] = _lots_per_symbol.get(_ls, 0) + 1
    _total_mv = float((h.get("portfolio_totals") or {}).get("total_value") or 0)
    # Live quote overlay — source hierarchy by account:
    #   schwab_*     → Schwab API sync + portfolio_repricer (Finviz) in holdings.json FIRST;
    #                  market_quotes (Alpaca) only when broker price missing.
    #   fidelity_*   → SnapTrade is positions/basis only (prices lag hours); use market_quotes
    #                  (Alpaca ingest) → finviz_quote_cache → technical snapshot — NOT SnapTrade.
    _live_mq: dict[str, float] = {}
    _live_mq_ts: dict[str, str] = {}
    _live_fv: dict[str, float] = {}
    # Quote-source fetch times — so each holding can carry a source_timestamp the protective-stop gate uses
    # to judge freshness (without it the gate reads "Price timestamp: missing" and blocks every live stop).
    _live_fv_ts: dict[str, str] = {}

    def _is_cash_holding(p: dict) -> bool:
        """Shared cash boundary — synthetic cash never receives equity enrichment."""
        if p.get("is_cash") is True:
            return True
        sym_u = str(p.get("symbol") or "").upper()
        if sym_u == "CASH":
            return True
        at = str(p.get("asset_type") or p.get("assetType") or p.get("security_type") or "").lower()
        return at in ("cash", "currency", "cash_equivalent")

    # Exclude synthetic CASH from market_quotes / finviz symbol fan-out.
    _holding_symbols = sorted(
        {
            str(p.get("symbol") or "").upper()
            for p in holdings
            if str(p.get("symbol") or "").strip() and not _is_cash_holding(p)
        }
    )
    # ── Data Broker Wave B: use market_quote.get_price_batch() instead of raw market_quotes DB query ──
    from lib.data_broker.market_quote import get_price_batch as _brk_get_price_batch

    _brk_prices = _brk_get_price_batch(_db_query, _holding_symbols, skip_live=True) if _holding_symbols else {}
    _live_mq: dict[str, float] = {}
    _live_mq_ts: dict[str, str] = {}
    for _sym, _bq in _brk_prices.items():
        _p = _bq.get("price")
        if _p is not None:
            _live_mq[_sym] = float(_p)
        _as = _bq.get("as_of")
        if _as:
            _live_mq_ts[_sym] = str(_as)
    _fv = _load_json(STATE_DIR / "finviz_quote_cache.json") or {}
    _fv_meta = _fv.get("_meta") or {}
    _fv_day: dict[str, float] = {}
    for _fsym, _fvrow in _fv.items():
        if not isinstance(_fvrow, dict):
            continue
        _su = str(_fsym).upper()
        try:
            if _fvrow.get("price"):
                _live_fv[_su] = float(_fvrow["price"])
                _ffa = _fvrow.get("last_fetched") or _fvrow.get("last_updated")
                if _ffa:
                    _live_fv_ts[_su] = str(_ffa)
        except (TypeError, ValueError):
            pass
        try:
            if _fvrow.get("change_pct") is not None:
                _fv_day[_su] = float(_fvrow["change_pct"])
        except (TypeError, ValueError):
            pass
    _latest_fidelity_trade: dict[tuple[str, str], dict] = {}
    try:
        for _tr in (
            _db_query("""
            SELECT DISTINCT ON (account, upper(symbol))
                   account, upper(symbol) AS symbol, action, quantity, trade_date, trade_time, amount
            FROM trade_transactions
            WHERE account LIKE 'fidelity_%'
              AND action IN ('Buy','Sell')
              AND trade_date >= CURRENT_DATE - INTERVAL '45 days'
            ORDER BY account, upper(symbol), trade_date DESC, trade_time DESC NULLS LAST
        """)
            or []
        ):
            _latest_fidelity_trade[(str(_tr.get("account") or ""), str(_tr.get("symbol") or "").upper())] = _tr
    except Exception:
        _latest_fidelity_trade = {}
    rows = []
    for p in holdings:
        if (p.get("market_value") or 0) < 50 and not p.get("is_cash"):
            continue
        sym = p.get("symbol", "")
        _shares = float(p.get("shares") or 0)
        _acct = str(p.get("account") or "")
        _is_cash = _is_cash_holding(p)

        # ── Cash boundary: unit price 1.0, preserve market_value, no equity enrichment ──
        if _is_cash:
            _mv = float(p.get("market_value") or 0)
            _ppct = p.get("portfolio_pct")
            if (not _ppct) and _total_mv > 0 and _mv > 0:
                _ppct = round(_mv / _total_mv * 100, 4)
            rows.append(
                {
                    "symbol": sym or "CASH",
                    "name": (p.get("name") or "Cash & Cash Investments")[:40],
                    "account": p.get("account", ""),
                    "shares": _shares or p.get("shares", 0),
                    "system_shares": p.get("system_shares")
                    if p.get("system_shares") is not None
                    else (_shares or p.get("shares")),
                    "broker_actual_shares": p.get("broker_actual_shares"),
                    "share_drift": p.get("share_drift"),
                    "share_drift_status": p.get("share_drift_status"),
                    "share_drift_source": p.get("share_drift_source"),
                    "last_reconciled_at": p.get("last_reconciled_at"),
                    "last_reconciliation_source": p.get("last_reconciliation_source"),
                    "original_source_account": p.get("original_source_account"),
                    "current_account": p.get("current_account") or p.get("account"),
                    "transfer_history": p.get("transfer_history") or [],
                    "transfer_history_tag": p.get("transfer_history_tag"),
                    "transfer_display_note": p.get("transfer_display_note"),
                    "performance_adjusted": p.get("performance_adjusted"),
                    "adjusted_for_transfer": p.get("adjusted_for_transfer"),
                    "normalized_after_transfer": p.get("normalized_after_transfer"),
                    "normalization_status": p.get("normalization_status"),
                    "price": 1.0,
                    "current_price": 1.0,
                    "price_source": "cash_unit",
                    "price_as_of": h.get("last_repriced", "") or h.get("as_of", ""),
                    "price_live": False,
                    "source_timestamp": h.get("last_repriced") or p.get("updated_at") or p.get("as_of"),
                    "market_value": _mv,
                    "portfolio_pct": _ppct or 0,
                    "day_change": 0.0,
                    "day_change_pct": 0.0,
                    "sector": "Cash",
                    "signal": "",
                    "yield_pct": None,
                    "rsi": None,
                    "beta": None,
                    "pe": None,
                    "forward_pe": None,
                    "eps_ttm": None,
                    "sma20_pct": None,
                    "sma50_pct": None,
                    "sma200_pct": None,
                    "atr": None,
                    "short_float_pct": None,
                    "week52_high_pct": None,
                    "market_cap_b": None,
                    "company": "",
                    "industry": "",
                    "cost_basis": None,
                    "gain_loss": None,
                    "gain_loss_pct": None,
                    "pi_score": None,
                    "analyst_rating": None,
                    "recom_score": None,
                    "insider_own_pct": None,
                    "inst_own_pct": None,
                    "peg": None,
                    "eps_next_y": None,
                    "perf_ytd_pct": None,
                    "is_cash": True,
                    "asset_type": "cash",
                    "llm_health": None,
                    "llm_action": None,
                    "llm_confidence": None,
                    "llm_summary": None,
                    "llm_at": None,
                    "llm_evidence": [],
                    "llm_lots": 1,
                    "llm_data_i_doubt": None,
                    "rsi_status": None,
                    "fib": None,
                    "data_available": False,
                    "analysis_note": "Cash position.",
                    "enrichment_as_of": _enrich_as_of,
                }
            )
            continue

        e_cache = ec.get(sym, {}) if isinstance(ec.get(sym), dict) else {}
        t_snap = ts.get(sym, {}) if isinstance(ts.get(sym), dict) else {}

        # Merge: enrichment cache wins, technical snapshot fills gaps
        def _pick(*sources, key):
            for src in sources:
                v = src.get(key)
                if v is not None:
                    return v
            return None

        merged_rsi = _pick(e_cache, t_snap, key="rsi")
        merged_beta = _pick(e_cache, t_snap, key="beta")
        merged_sma20 = _pick(e_cache, t_snap, key="sma20_pct")
        merged_sma50 = _pick(e_cache, t_snap, key="sma50_pct")
        merged_sma200 = _pick(e_cache, t_snap, key="sma200_pct")
        merged_atr = _pick(e_cache, t_snap, key="atr")
        # For pi_score, build a merged dict with all needed fields
        pi_input = {**t_snap, **{k: v for k, v in e_cache.items() if v is not None}}
        # Map technical snapshot field names to pi_score expected names
        if "pct_from_high" in t_snap and "week52_high_pct" not in pi_input:
            pi_input["week52_high_pct"] = t_snap["pct_from_high"]
        if "pct_from_low" in t_snap and "week52_low_pct" not in pi_input:
            pi_input["week52_low_pct"] = t_snap["pct_from_low"]
        _is_fidelity_acct = _acct.startswith("fidelity") and _acct != "fidelity_401k"
        _latest_trade = _latest_fidelity_trade.get((_acct, sym.upper())) if _is_fidelity_acct else None
        if _latest_trade and str(_latest_trade.get("action") or "").lower() == "sell":
            try:
                _sold_qty = abs(float(_latest_trade.get("quantity") or 0))
            except (TypeError, ValueError):
                _sold_qty = 0.0
            if _shares > 0 and _sold_qty >= _shares - 1e-6:
                # SnapTrade positions can lag after a Fidelity stop/manual sale. If the synced activity ledger
                # says the latest trade fully sold the stale holding, suppress it from Portfolio/stop cards.
                continue
        _stale_px = float(p.get("current_price") or p.get("price") or 0)
        _su = sym.upper()
        _mq = _live_mq.get(_su)
        _fvpx = _live_fv.get(_su)
        _is_schwab_acct = _acct.startswith("schwab")
        if _is_schwab_acct and _stale_px > 0:
            _px, _px_source = _stale_px, "schwab"
        elif _is_fidelity_acct and _fvpx and _fvpx > 0:
            _px, _px_source = float(_fvpx), "finviz"
        elif _is_fidelity_acct and _mq and _mq > 0:
            _px, _px_source = float(_mq), "market_quotes"
        elif _mq and _mq > 0:
            _px, _px_source = float(_mq), "market_quotes"
        elif _fvpx and _fvpx > 0:
            _px, _px_source = float(_fvpx), "finviz"
        elif _stale_px > 0:
            _px, _px_source = _stale_px, "snaptrade" if _is_fidelity_acct else "holdings"
        else:
            _tp = _pick(t_snap, e_cache, key="price")
            try:
                _px = float(_tp) if _tp is not None else 0.0
            except (TypeError, ValueError):
                _px = 0.0
            _px_source = "technical_snapshot"
        if _px_source == "finviz":
            _price_as_of = _fv_meta.get("last_updated", "")
        elif _px_source == "market_quotes":
            _price_as_of = _live_mq_ts.get(_su, "")
        elif _px_source in ("schwab", "holdings", "snaptrade"):
            _price_as_of = h.get("last_repriced", "") or h.get("as_of", "")
        else:
            _price_as_of = _json_clean(t_snap.get("as_of") or e_cache.get("as_of") or "")
        _px_live = _px_source in ("market_quotes", "finviz") and _px > 0
        # Stamp the price with WHEN its source was fetched, so the protective-stop freshness gate has a real
        # timestamp instead of treating every holding as a stale quote. Per source: market_quotes/finviz carry
        # their own fetch time; broker-synced (schwab) and holdings/snaptrade prices use the holding's as_of.
        if _px_source == "market_quotes":
            _px_ts = _live_mq_ts.get(_su)
        elif _px_source == "finviz":
            _px_ts = _live_fv_ts.get(_su)
        elif _px_source in ("schwab", "holdings", "snaptrade"):
            # Freshness gate = how current is our price knowledge for this symbol. A live finviz / market-quote
            # tick (the same source the schwab reprice draws from, just more recent) is the freshest signal;
            # fall back to the holdings.json reprice time, then the clean per-holding ISO updated_at, then the
            # date-only as_of last (it parses to midnight and would read as stale).
            _px_ts = (
                _live_fv_ts.get(_su)
                or _live_mq_ts.get(_su)
                or h.get("last_repriced")
                or p.get("updated_at")
                or p.get("as_of")
            )
        else:
            _px_ts = None
        _mv = (
            round(_shares * _px, 2)
            if (_px > 0 and _shares > 0 and not p.get("is_cash"))
            else float(p.get("market_value") or 0)
        )
        # Basis anchors are point-in-time exports: after a partial/near-full sale the
        # anchor TOTAL is stale relative to live shares (PFLT: $9,746 anchor vs 11.7 sh
        # left -> phantom $829.71/sh). Only trust the anchor total when its share count
        # still matches; otherwise scale by per-share basis, else fall back to broker.
        _anchor = basis_map.get((sym, p.get("account", "")))
        _cb = p.get("cost_basis")
        if _anchor:
            _a_sh = _anchor.get("shares") or 0
            if _a_sh and _shares and abs(_a_sh - _shares) / max(_a_sh, _shares) <= 0.05:
                _cb = _anchor["total"]
            elif _anchor.get("per_share") and _shares:
                _cb = round(_anchor["per_share"] * _shares, 2)
        if _cb is None and p.get("avg_cost") and _shares:
            _cb = float(p.get("avg_cost")) * _shares
        try:
            _cb_f = float(_cb) if _cb is not None else None
        except (TypeError, ValueError):
            _cb_f = None
        _gl = round(_mv - _cb_f, 2) if _cb_f is not None else None
        _glp = round(_gl / _cb_f * 100, 2) if (_gl is not None and _cb_f and _cb_f > 0) else None
        _ppct = p.get("portfolio_pct")
        if (not _ppct) and _total_mv > 0 and _mv > 0:
            _ppct = round(_mv / _total_mv * 100, 4)
        _fv_day_pct = None if p.get("is_cash") or sym.upper() == "CASH" else _fv_day.get(sym.upper())
        try:
            import sys as _sys_hdc

            _hdc_lib = PROJECT_ROOT / "scripts" / "lib"
            if str(_hdc_lib) not in _sys_hdc.path:
                _sys_hdc.path.insert(0, str(_hdc_lib))
            from holding_day_change import resolve_holding_day_change

            _day_chg, _day_pct = resolve_holding_day_change(
                p,
                market_value=_mv,
                price=_px,
                stale_price=_stale_px,
                finviz_day_pct=_fv_day_pct,
            )
        except Exception:
            _day_pct = p.get("day_change_pct")
            if (_day_pct is None or float(_day_pct or 0) == 0) and _fv_day_pct is not None:
                _day_pct = _fv_day_pct
            _day_chg = (
                round(_mv * float(_day_pct or 0) / 100, 2)
                if (_day_pct is not None and _mv)
                else float(p.get("day_change") or 0)
            )
        rows.append(
            {
                "symbol": sym,
                "name": (p.get("name") or "")[:40],
                "account": p.get("account", ""),
                "shares": _shares or p.get("shares", 0),
                # Share reconciliation dual fields (optional; null-safe for older snapshots)
                "system_shares": p.get("system_shares")
                if p.get("system_shares") is not None
                else (_shares or p.get("shares")),
                "broker_actual_shares": p.get("broker_actual_shares"),
                "share_drift": p.get("share_drift"),
                "share_drift_status": p.get("share_drift_status"),
                "share_drift_source": p.get("share_drift_source"),
                "last_reconciled_at": p.get("last_reconciled_at"),
                "last_reconciliation_source": p.get("last_reconciliation_source"),
                # Transfer / rollover provenance (Fidelity→Schwab, Trad→Roth ladder)
                "original_source_account": p.get("original_source_account"),
                "current_account": p.get("current_account") or p.get("account"),
                "transfer_history": p.get("transfer_history") or [],
                "transfer_history_tag": p.get("transfer_history_tag"),
                "transfer_display_note": p.get("transfer_display_note"),
                "performance_adjusted": p.get("performance_adjusted"),
                "adjusted_for_transfer": p.get("adjusted_for_transfer"),
                "normalized_after_transfer": p.get("normalized_after_transfer"),
                "normalization_status": p.get("normalization_status"),
                "price": _px,
                "current_price": _px,
                "price_source": _px_source,
                "price_as_of": _price_as_of,
                "price_live": _px_live,
                "source_timestamp": _px_ts,  # quote fetch time → protective-stop freshness gate (null = unknown)
                "market_value": _mv,
                "portfolio_pct": _ppct or 0,
                "day_change": _day_chg,
                "day_change_pct": _day_pct if _day_pct is not None else 0,
                "sector": e_cache.get("sector") or t_snap.get("sector") or p.get("sector_type", ""),
                "signal": sig_map.get(sym, "") or t_snap.get("tech_grade", ""),
                "yield_pct": div_map.get(sym),
                "rsi": merged_rsi,
                "beta": merged_beta,
                "pe": e_cache.get("pe"),
                "forward_pe": e_cache.get("forward_pe"),
                "eps_ttm": e_cache.get("eps_ttm"),
                "sma20_pct": merged_sma20,
                "sma50_pct": merged_sma50,
                "sma200_pct": merged_sma200,
                "atr": merged_atr,
                "short_float_pct": e_cache.get("short_float_pct"),
                "week52_high_pct": e_cache.get("week52_high_pct") or t_snap.get("pct_from_high"),
                "market_cap_b": e_cache.get("market_cap_b"),
                "company": e_cache.get("company") or t_snap.get("company", ""),
                "industry": e_cache.get("industry", ""),
                "cost_basis": _cb_f,
                "gain_loss": _gl,
                "gain_loss_pct": _glp,
                "pi_score": _pi_score(pi_input) if (e_cache or t_snap) else None,
                "analyst_rating": e_cache.get("analyst_rating"),
                "recom_score": e_cache.get("recom_score"),
                "insider_own_pct": e_cache.get("insider_own_pct"),
                "inst_own_pct": e_cache.get("inst_own_pct"),
                "peg": e_cache.get("peg"),
                "eps_next_y": e_cache.get("eps_next_y"),
                "perf_ytd_pct": e_cache.get("perf_ytd_pct"),
                "is_cash": bool(p.get("is_cash")),
                # LLM health assessment
                "llm_health": (llm_health_map.get(sym) or {}).get("holdings_llm_health"),
                "llm_action": (llm_health_map.get(sym) or {}).get("holdings_llm_action"),
                "llm_confidence": (llm_health_map.get(sym) or {}).get("holdings_llm_confidence"),
                "llm_summary": _json_clean((llm_health_map.get(sym) or {}).get("holdings_llm_summary")),
                "llm_at": _json_clean((llm_health_map.get(sym) or {}).get("holdings_llm_at")),
            }
        )
        _hls = rows[-1].get("llm_summary")
        if isinstance(_hls, str):
            try:
                _hls = json.loads(_hls)
            except Exception:
                _hls = None
        _hlep = _evidence_packet(
            _hls if isinstance(_hls, dict) else (llm_health_map.get(sym) or {}).get("holdings_llm_summary")
        )
        rows[-1]["llm_evidence"] = _hlep.get("evidence") or []
        rows[-1]["llm_lots"] = _lots_per_symbol.get(sym, 1)
        rows[-1]["llm_data_i_doubt"] = _hlep.get("data_i_doubt")
        # ── Technical analysis enrichment: RSI zone, fib levels, data availability ──
        _row = rows[-1]
        _rsi_status = e_cache.get("rsi_status") or t_snap.get("rsi_status")
        if not _rsi_status and merged_rsi is not None:
            _rsi_status = "oversold" if merged_rsi <= 30 else "overbought" if merged_rsi >= 70 else "neutral"
        _row["rsi_status"] = _rsi_status
        _w52h = _pick(e_cache, t_snap, key="week52_high_pct")
        if _w52h is None:
            _w52h = t_snap.get("week52_high")
        _w52l = e_cache.get("week52_low_pct")
        if _w52l is None:
            _w52l = t_snap.get("week52_low")
        _row["fib"] = _fib_analysis(p.get("price"), _w52h, _w52l)
        # data_available = we have real market enrichment (False for NAV funds / cash)
        _row["data_available"] = bool(merged_rsi is not None or e_cache.get("pe") is not None or _row.get("fib"))
        if not _row["data_available"]:
            # No direct market data — fall back to a labeled public-ETF proxy if mapped.
            _proxy = _HOLDING_PROXY_MAP.get(sym) if not p.get("is_cash") else None
            if _proxy:
                _ptkr, _plabel = _proxy
                _pe = ec.get(_ptkr, {}) if isinstance(ec.get(_ptkr), dict) else {}
                _pt = ts.get(_ptkr, {}) if isinstance(ts.get(_ptkr), dict) else {}
                _prsi = _pick(_pe, _pt, key="rsi")
                _pstat = _pe.get("rsi_status") or _pt.get("rsi_status")
                if not _pstat and _prsi is not None:
                    _pstat = "oversold" if _prsi <= 30 else "overbought" if _prsi >= 70 else "neutral"
                _pw52h = _pe.get("week52_high_pct")
                _pw52l = _pe.get("week52_low_pct")
                if _pw52h is None:
                    _pw52h = _pt.get("week52_high")
                if _pw52l is None:
                    _pw52l = _pt.get("week52_low")
                _pprice = _pt.get("price")  # proxy price (dollar fib levels only if present)
                _pfib = _fib_analysis(_pprice, _pw52h, _pw52l)
                if _prsi is not None or _pfib:
                    _row["rsi"] = _prsi
                    _row["rsi_status"] = _pstat
                    _row["beta"] = _pick(_pe, _pt, key="beta")
                    _row["sma20_pct"] = _pick(_pe, _pt, key="sma20_pct")
                    _row["sma50_pct"] = _pick(_pe, _pt, key="sma50_pct")
                    _row["sma200_pct"] = _pick(_pe, _pt, key="sma200_pct")
                    _row["fib"] = _pfib
                    _row["proxy"] = {"ticker": _ptkr, "label": _plabel}
                    _row["analysis_note"] = (
                        f"No direct market data for this fund/pool — showing {_ptkr} "
                        f"({_plabel}) as a public proxy. Technicals approximate the asset class, "
                        f"not the exact fund."
                    )
                else:
                    _row["analysis_note"] = f"No direct market data; proxy {_ptkr} has no cached technicals right now."
            else:
                _row["analysis_note"] = (
                    "Cash position."
                    if p.get("is_cash")
                    else "No market data — commingled fund / 401(k) pool or NAV-priced asset with no public ticker. "
                    "Technical (RSI, fib, SMA) and fundamental data are not available for this symbol."
                )
        _row["enrichment_as_of"] = _enrich_as_of
    rows.sort(key=lambda r: -r["market_value"])

    # Equity curve from snapshot_index
    snap_idx = _load_json(STATE_DIR / "snapshot_index.json") or []
    equity_curve = []
    for s in snap_idx[-30:]:
        total = sum(v for k, v in s.items() if k != "date" and isinstance(v, (int, float)))
        if total > 0:
            equity_curve.append({"date": s["date"], "value": round(total, 0)})

    _priced_total = round(sum(r.get("market_value") or 0 for r in rows), 2)
    # Per-row day_change is recomputed live from the day % (holding_day_change), so the
    # row-sum is authoritative. The stored portfolio_totals.day_change comes from the same
    # repricer that writes $0 when prev_price == new_price at write time, so it can silently
    # under-count (it once read +$171 while the rows truly summed to ~+$5,258). Only fall back
    # to the stored total when we have NO per-row signal at all (row-sum ~0 but a total exists).
    _day_total = round(sum(r.get("day_change") or 0 for r in rows), 2)
    _totals_day = (h.get("portfolio_totals") or {}).get("day_change")
    if abs(_day_total) < 0.01 and _totals_day is not None:
        try:
            _day_total = round(float(_totals_day), 2)
        except (TypeError, ValueError):
            pass
    _mq_as_of = None
    try:
        _mqr = _db_query("SELECT MAX(fetched_at) AS ts FROM market_quotes", fetch="one") or {}
        _mq_as_of = _json_clean(_mqr.get("ts"))
    except Exception:
        pass
    _src_counts: dict[str, int] = {}
    for r in rows:
        s = r.get("price_source") or "unknown"
        _src_counts[s] = _src_counts.get(s, 0) + 1
    return {
        "count": len(rows),
        "holdings": rows,
        "as_of": h.get("as_of", ""),
        "enrichment_as_of": _enrich_as_of,
        "equity_curve": equity_curve,
        "total_value": _priced_total,
        "today_change": _day_total,
        "last_repriced": h.get("last_repriced", ""),
        "reprice_source": h.get("reprice_source", ""),
        "pricing": {
            "last_repriced": h.get("last_repriced", ""),
            "reprice_source": h.get("reprice_source", ""),
            "finviz_cache_updated": _fv_meta.get("last_updated", ""),
            "market_quotes_as_of": _mq_as_of,
            "enrichment_as_of": _enrich_as_of,
            "price_sources": _src_counts,
            "note": "Schwab accounts: broker-synced prices in holdings.json. Fidelity/SnapTrade: Finviz Elite or market_quotes overlay (not SnapTrade lag). Technicals timestamp is separate from live price.",
        },
    }


def _compute_drawdown_series(values: list) -> list:
    """Underwater % from chronological {date, value} points."""
    peak = 0.0
    out = []
    for pt in values:
        v = float(pt.get("value") or pt.get("total_value") or 0)
        if v <= 0:
            continue
        if v > peak:
            peak = v
        dd = round((v - peak) / peak * 100, 2) if peak > 0 else 0.0
        out.append(
            {
                "date": str(pt.get("date") or "")[:10],
                "value": round(v, 0),
                "drawdown": dd,
            }
        )
    return out


def portfolio_performance():
    perf = _load_json(STATE_DIR / "performance_history.json") or {}
    holdings = _load_json(STATE_DIR / "holdings.json") or {}
    periods = perf.get("periods", {})
    accounts = perf.get("accounts", {})
    repriced_list = perf.get("reconstructed", [])

    # Overlay 1D with canonical market day (matches header TODAY). The 1D comes from
    # portfolio_totals.day_change; inject the live per-position day change (Finviz day %) so the
    # Returns 1D equals the header TODAY instead of the stale repricer $0-undercount (2026-07-21 audit).
    try:
        _live_dc = _live_portfolio_day_change(holdings.get("holdings") or [])
        if _live_dc is not None and _live_dc != 0:
            _pt = dict(holdings.get("portfolio_totals") or {})
            _pt["day_change"] = _live_dc
            try:
                _tv = float(_pt.get("total_value") or 0)
            except (TypeError, ValueError):
                _tv = 0
            if _tv and (_tv - _live_dc):
                _pt["day_change_pct"] = round(_live_dc / (_tv - _live_dc) * 100, 4)
            holdings = {**holdings, "portfolio_totals": _pt}
    except Exception:
        pass
    try:
        from portfolio_snapshot_sanity import apply_market_day_1d

        perf = apply_market_day_1d(perf, holdings)
        periods = perf.get("periods", periods)
        accounts = perf.get("accounts", accounts)
    except Exception:
        pass

    # Use canonical holdings.json total, not stale performance_history snapshot
    _canonical = holdings.get("portfolio_totals", {}).get("total_value", 0)
    _perf_val = perf.get("current_value", 0)
    result = {
        "current_value": _canonical or _perf_val,
        "periods": {},
        "accounts": {},
        "snapshot_source": "holdings.json (canonical)" if _canonical else "performance_history.json (snapshot)",
        "snapshot_count": perf.get("snapshot_count", 0),
        "warning": "Periods marked 'estimated' use repriced current holdings at historical prices. After position changes (buys/sells), these may be inaccurate."
        if repriced_list
        else None,
    }
    result["snapshot_outliers"] = perf.get("snapshot_outliers") or []
    for k, v in periods.items():
        if isinstance(v, dict):
            is_repriced = v.get("source") == "repriced"
            result["periods"][k] = {
                "change_pct": v.get("change_pct"),
                "change": v.get("change"),
                "start_value": v.get("start_value"),
                "start_date": v.get("start_date"),
                "source": v.get("source", "unknown"),
                "estimated": is_repriced,
                "snapshot_replaced": v.get("snapshot_replaced"),
                "snapshot_1d_pct": v.get("snapshot_1d_pct"),
            }
    for acct, data in accounts.items():
        ap = {}
        for k, v in (data.get("periods") or {}).items():
            if isinstance(v, dict):
                ap[k] = {
                    "change_pct": v.get("change_pct"),
                    "change": v.get("change"),
                    "start_value": v.get("start_value"),
                    "end_value": v.get("end_value"),
                    "start_date": v.get("start_date"),
                    "source": v.get("source"),
                    "snapshot_replaced": v.get("snapshot_replaced"),
                }
        result["accounts"][acct] = {"current_value": data.get("current_value", 0), "periods": ap}

    # Transfer / funding quality + contribution-adjusted (≈ market) P/L
    try:
        from portfolio_period_quality import annotate_performance_result

        result = annotate_performance_result(result, STATE_DIR, holdings)
    except Exception as _pq_err:
        result["period_quality_error"] = str(_pq_err)[:160]

    # Index benchmarks: SPY (S&P 500), QQQ (Nasdaq-100), IWM, DIA + alpha vs book
    try:
        from lib.portfolio_benchmarks import build_benchmarks

        result["benchmarks"] = build_benchmarks(result.get("periods") or {})
    except Exception as _bm_err:
        try:
            # Fallback if scripts/ not on path the same way
            import sys
            from pathlib import Path as _P

            _root = _P(__file__).resolve().parent
            if str(_root) not in sys.path:
                sys.path.insert(0, str(_root))
            if str(_root / "lib") not in sys.path:
                sys.path.insert(0, str(_root / "lib"))
            from portfolio_benchmarks import build_benchmarks  # type: ignore

            result["benchmarks"] = build_benchmarks(result.get("periods") or {})
        except Exception as _bm2:
            result["benchmarks_error"] = str(_bm2)[:160]

    # Drawdown / underwater series — sanitize reconciliation outlier peaks
    dd_series = []
    _outlier_dates: list[str] = []
    try:
        from portfolio_snapshot_sanity import (
            compute_drawdown_series,
            holding_phantom_corrections,
            load_snapshots_from_dir,
        )

        _raw_snaps = load_snapshots_from_dir(STATE_DIR / "snapshots")
        if _raw_snaps:
            _phantom = holding_phantom_corrections(_raw_snaps)
            dd_series = compute_drawdown_series(_raw_snaps)
            result["snapshot_outliers"] = sorted(_phantom.keys())
            result["snapshot_phantom_trims"] = _phantom
    except Exception:
        pass
    if not dd_series:
        snap_pts = []
        for s in perf.get("snapshots") or []:
            if isinstance(s, dict):
                val = s.get("value") or s.get("total_value") or s.get("portfolio_value")
                if val:
                    snap_pts.append({"date": s.get("date") or s.get("as_of"), "value": val})
        if not snap_pts:
            snap_idx = _load_json(STATE_DIR / "snapshot_index.json") or []
            for s in snap_idx[-90:]:
                if not isinstance(s, dict):
                    continue
                total = sum(v for k, v in s.items() if k != "date" and isinstance(v, (int, float)))
                if total > 0:
                    snap_pts.append({"date": s.get("date"), "value": total})
        dd_series = _compute_drawdown_series(snap_pts)
    if dd_series:
        result["drawdown_series"] = dd_series
        result["max_drawdown_pct"] = min(p["drawdown"] for p in dd_series)
        try:
            from datetime import date as _date, timedelta as _td

            _cutoff = (_date.today() - _td(days=30)).isoformat()
            _recent = [p for p in dd_series if str(p.get("date", ""))[:10] >= _cutoff]
            if _recent:
                result["max_drawdown_pct_30d"] = min(p["drawdown"] for p in _recent)
        except Exception:
            pass
    return result


