def _ops_audit():
    """GET /api/v2/ops/audit — recent runs, imports, and action audit trail."""
    import glob as _glob

    # Recent UI-triggered runs
    run_dir = PROJECT_ROOT / "logs" / "ui_runs"
    recent_runs = []
    if run_dir.exists():
        for f in sorted(run_dir.glob("*.log"), key=lambda x: x.stat().st_mtime, reverse=True)[:10]:
            size = f.stat().st_size
            lines = f.read_text(errors="replace").strip().split("\n") if size > 0 else []
            last_line = lines[-1][:100] if lines else ""
            recent_runs.append(
                {
                    "name": f.stem,
                    "size_kb": round(size / 1024, 1),
                    "modified": datetime.fromtimestamp(f.stat().st_mtime).isoformat(timespec="seconds"),
                    "last_line": last_line,
                    "success": "error" not in last_line.lower(),
                }
            )

    # Recent imports — prefer structured JSONL, fallback to raw log
    import_structured = PROJECT_ROOT / "logs" / "import_audit_structured.jsonl"
    import_log = PROJECT_ROOT / "logs" / "import_audit.log"
    recent_imports = []
    if import_structured.exists():
        for line in import_structured.read_text(errors="replace").strip().split("\n")[-10:]:
            try:
                recent_imports.append(json.loads(line))
            except Exception:
                recent_imports.append({"raw": line})
    elif import_log.exists():
        for line in import_log.read_text(errors="replace").strip().split("\n")[-10:]:
            recent_imports.append({"raw": line.strip()})

    # Recent notifications
    notifs = (
        _db_query(
            "SELECT notification_type, channel, subject, status, sent_at::text FROM notification_log ORDER BY created_at DESC LIMIT 10"
        )
        or []
    )

    # Recovery watch runs
    recovery_log = PROJECT_ROOT / "logs" / "recovery-watch.log"
    recovery_lines = []
    if recovery_log.exists():
        for line in recovery_log.read_text(errors="replace").strip().split("\n")[-8:]:
            recovery_lines.append(line.strip())

    return {
        "recent_runs": recent_runs,
        "recent_imports": recent_imports,
        "recent_notifications": [{k: _json_clean(v) for k, v in r.items()} for r in notifs],
        "recovery_log": recovery_lines,
    }


def ops_summary():
    fresh = _load_json(STATE_DIR / "_freshness.json") or {}
    health_rows = (
        _db_query(
            """
        SELECT s.relname AS name, s.n_live_tup AS live_rows, s.n_dead_tup AS dead_rows,
               pg_size_pretty(pg_total_relation_size(s.schemaname||'.'||s.relname)) AS size
        FROM pg_stat_user_tables s
        ORDER BY pg_total_relation_size(s.schemaname||'.'||s.relname) DESC
    """,
            fetch="all",
        )
        or []
    )

    return {
        "pipeline": {
            "status": fresh.get("status", "unknown"),
            "completed_at": fresh.get("completed_at", ""),
            "duration_seconds": fresh.get("pipeline_duration_seconds", 0),
            "steps": fresh.get("steps_completed", 0),
            "run_type": fresh.get("run_type", ""),
            "holdings_hash": fresh.get("holdings_hash", ""),
            "run_id": fresh.get("run_id", ""),
        },
        "database": {
            "table_count": len(health_rows),
            "total_rows": sum(r.get("live_rows", 0) for r in health_rows),
            "tables": [dict(r) for r in health_rows],
        },
    }


def _journal_edge_analytics(query=None):
    """GET /api/v2/journal/edge-analytics?account=&days= — time-of-day/day-of-week/session breakdowns,
    equity curve + drawdown/Sharpe, R-distribution, and per-strategy/setup/emotion edge from the real
    round-trip journal (read-only). Complements /journal/analytics (review-based)."""
    q = query or {}

    def _one(k):
        v = q.get(k)
        return v[0] if isinstance(v, list) else v

    acct = _one("account") or None
    try:
        days = int(_one("days") or 180)
    except Exception:
        days = 180
    try:
        import sys as _sys

        _sys.path.insert(0, str(Path(__file__).resolve().parent))
        import importlib, journal_analytics_engine as _eng

        importlib.reload(_eng)
        return _json_clean(_eng.run(acct, days))
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def journal_analytics():
    """GET /api/v2/journal/analytics — aggregated review metrics from journal_trade_reviews."""
    # Setup performance
    setup_rows = (
        _db_query("""
        SELECT setup_name, COUNT(*) as n,
               AVG(realized_r) as avg_r,
               AVG(execution_quality_score) as avg_exec,
               AVG(sizing_quality_score) as avg_sizing,
               SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate,
               SUM(CASE WHEN followed_plan THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as plan_follow_rate
        FROM journal_trade_reviews WHERE setup_name IS NOT NULL AND setup_name != ''
        GROUP BY setup_name ORDER BY n DESC
    """)
        or []
    )

    # Emotion breakdown
    emotion_rows = (
        _db_query("""
        SELECT emotion_before, COUNT(*) as n FROM journal_trade_reviews
        WHERE emotion_before IS NOT NULL AND emotion_before != ''
        GROUP BY emotion_before ORDER BY n DESC
    """)
        or []
    )
    emotion_during_rows = (
        _db_query("""
        SELECT emotion_during, COUNT(*) as n FROM journal_trade_reviews
        WHERE emotion_during IS NOT NULL AND emotion_during != ''
        GROUP BY emotion_during ORDER BY n DESC
    """)
        or []
    )

    # Mistake tag frequency
    mistake_rows = (
        _db_query("""
        SELECT tag, COUNT(*) as n FROM (
            SELECT unnest(mistake_tags) as tag FROM journal_trade_reviews
            WHERE mistake_tags IS NOT NULL AND array_length(mistake_tags, 1) > 0
        ) sub GROUP BY tag ORDER BY n DESC
    """)
        or []
    )

    # Strength tag frequency
    strength_rows = (
        _db_query("""
        SELECT tag, COUNT(*) as n FROM (
            SELECT unnest(strength_tags) as tag FROM journal_trade_reviews
            WHERE strength_tags IS NOT NULL AND array_length(strength_tags, 1) > 0
        ) sub GROUP BY tag ORDER BY n DESC
    """)
        or []
    )

    # Timeframe breakdown
    tf_rows = (
        _db_query("""
        SELECT timeframe, COUNT(*) as n,
               AVG(execution_quality_score) as avg_exec,
               SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate
        FROM journal_trade_reviews WHERE timeframe IS NOT NULL AND timeframe != ''
        GROUP BY timeframe ORDER BY n DESC
    """)
        or []
    )

    # Overall stats
    totals = (
        _db_query(
            """
        SELECT COUNT(*) as total_reviews,
               AVG(execution_quality_score) as avg_exec,
               AVG(sizing_quality_score) as avg_sizing,
               SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate,
               SUM(CASE WHEN followed_plan THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as plan_follow_rate
        FROM journal_trade_reviews
    """,
            fetch="one",
        )
        or {}
    )

    def _clean_rows(rows):
        return [
            {k: (float(v) if isinstance(v, Decimal) else _json_clean(v)) for k, v in r.items()} for r in (rows or [])
        ]

    return {
        "total_reviews": totals.get("total_reviews", 0),
        "avg_execution": float(totals["avg_exec"]) if totals.get("avg_exec") else None,
        "avg_sizing": float(totals["avg_sizing"]) if totals.get("avg_sizing") else None,
        "well_executed_rate": float(totals["well_exec_rate"]) if totals.get("well_exec_rate") else None,
        "plan_follow_rate": float(totals["plan_follow_rate"]) if totals.get("plan_follow_rate") else None,
        "by_setup": _clean_rows(setup_rows),
        "by_timeframe": _clean_rows(tf_rows),
        "emotion_before": _clean_rows(emotion_rows),
        "emotion_during": _clean_rows(emotion_during_rows),
        "mistake_tags": _clean_rows(mistake_rows),
        "strength_tags": _clean_rows(strength_rows),
        "has_data": (totals.get("total_reviews") or 0) > 0,
        # Monthly execution quality trend
        "monthly_trend": _clean_rows(
            _db_query("""
            SELECT TO_CHAR(closed_date, 'YYYY-MM') as month, COUNT(*) as n,
                   AVG(execution_quality_score) as avg_exec,
                   AVG(sizing_quality_score) as avg_sizing,
                   SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate
            FROM journal_trade_reviews WHERE closed_date IS NOT NULL
            GROUP BY TO_CHAR(closed_date, 'YYYY-MM') ORDER BY month
        """)
            or []
        ),
        # Setup family rollups
        "by_setup_family": _clean_rows(
            _db_query("""
            SELECT COALESCE(setup_family, 'Unclassified') as family, COUNT(*) as n,
                   AVG(execution_quality_score) as avg_exec,
                   SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate
            FROM journal_trade_reviews GROUP BY COALESCE(setup_family, 'Unclassified') ORDER BY n DESC
        """)
            or []
        ),
        # Cross-reference: journal review data for specific symbols (for recovery integration)
        "reviewed_symbols": _clean_rows(
            _db_query("""
            SELECT symbol, COUNT(*) as review_count,
                   AVG(execution_quality_score) as avg_exec,
                   SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate,
                   array_agg(DISTINCT setup_name) FILTER (WHERE setup_name IS NOT NULL) as setups_used
            FROM journal_trade_reviews WHERE symbol IS NOT NULL
            GROUP BY symbol ORDER BY review_count DESC
        """)
            or []
        ),
        # Catalyst breakdown
        "by_catalyst": _clean_rows(
            _db_query("""
            SELECT catalyst_type, COUNT(*) as n,
                   AVG(execution_quality_score) as avg_exec,
                   SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate
            FROM journal_trade_reviews WHERE catalyst_type IS NOT NULL AND catalyst_type != ''
            GROUP BY catalyst_type ORDER BY n DESC
        """)
            or []
        ),
        # New dimension rollups (Tier 2L batch)
        "by_direction": _clean_rows(
            _db_query("""
            SELECT direction, COUNT(*) as n, AVG(execution_quality_score) as avg_exec,
                   SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate
            FROM journal_trade_reviews WHERE direction IS NOT NULL AND direction != ''
            GROUP BY direction ORDER BY n DESC
        """)
            or []
        ),
        "by_entry_type": _clean_rows(
            _db_query("""
            SELECT entry_type, COUNT(*) as n, AVG(execution_quality_score) as avg_exec
            FROM journal_trade_reviews WHERE entry_type IS NOT NULL AND entry_type != ''
            GROUP BY entry_type ORDER BY n DESC
        """)
            or []
        ),
        "by_exit_type": _clean_rows(
            _db_query("""
            SELECT exit_type, COUNT(*) as n, AVG(execution_quality_score) as avg_exec
            FROM journal_trade_reviews WHERE exit_type IS NOT NULL AND exit_type != ''
            GROUP BY exit_type ORDER BY n DESC
        """)
            or []
        ),
        "by_market_regime": _clean_rows(
            _db_query("""
            SELECT market_regime, COUNT(*) as n, AVG(execution_quality_score) as avg_exec,
                   SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate
            FROM journal_trade_reviews WHERE market_regime IS NOT NULL AND market_regime != ''
            GROUP BY market_regime ORDER BY n DESC
        """)
            or []
        ),
        "by_risk_management": _clean_rows(
            _db_query("""
            SELECT risk_management_score, COUNT(*) as n,
                   SUM(CASE WHEN well_executed THEN 1 ELSE 0 END)::float / NULLIF(COUNT(*),0) as well_exec_rate
            FROM journal_trade_reviews WHERE risk_management_score IS NOT NULL
            GROUP BY risk_management_score ORDER BY risk_management_score
        """)
            or []
        ),
        # Pattern insights — best/worst performing dimensions
        "insights": _compute_journal_insights(totals, setup_rows, tf_rows, emotion_rows, mistake_rows),
    }


def _compute_journal_insights(totals, setup_rows, tf_rows, emotion_rows, mistake_rows):
    """Generate actionable pattern insights from journal review data."""
    insights = []
    total = totals.get("total_reviews", 0) or 0
    if total < 2:
        insights.append(
            {
                "type": "guidance",
                "text": f"Only {total} review{'s' if total != 1 else ''} recorded. Add more reviews to unlock pattern insights. Aim for 10+ for meaningful analytics.",
            }
        )
        return insights

    # Best/worst setup
    if setup_rows and len(setup_rows) >= 2:
        best = max(setup_rows, key=lambda r: float(r.get("avg_exec") or 0))
        worst = min(setup_rows, key=lambda r: float(r.get("avg_exec") or 0))
        if best.get("setup_name") != worst.get("setup_name"):
            insights.append(
                {
                    "type": "setup",
                    "text": f"Best setup: {best['setup_name']} (exec {float(best.get('avg_exec') or 0):.1f}/5, {best.get('n', 0)} trades). Worst: {worst['setup_name']} (exec {float(worst.get('avg_exec') or 0):.1f}/5, {worst.get('n', 0)} trades). Focus on setups where execution is strongest.",
                }
            )
    elif setup_rows and len(setup_rows) == 1:
        s = setup_rows[0]
        insights.append(
            {
                "type": "setup",
                "text": f"Only setup used so far: {s['setup_name']} ({s.get('n', 0)} trades, exec {float(s.get('avg_exec') or 0):.1f}/5). Add more setup variety to compare methodologies.",
            }
        )

    # Timeframe comparison
    if tf_rows and len(tf_rows) >= 2:
        best_tf = max(tf_rows, key=lambda r: float(r.get("well_exec_rate") or 0))
        worst_tf = min(tf_rows, key=lambda r: float(r.get("well_exec_rate") or 0))
        if best_tf.get("timeframe") != worst_tf.get("timeframe"):
            insights.append(
                {
                    "type": "timeframe",
                    "text": f"Best timeframe: {best_tf['timeframe']} ({float(best_tf.get('well_exec_rate') or 0) * 100:.0f}% well-executed). Weakest: {worst_tf['timeframe']} ({float(worst_tf.get('well_exec_rate') or 0) * 100:.0f}%). Consider whether the weaker timeframe suits your decision style.",
                }
            )

    # Plan follow rate
    pfr = float(totals.get("plan_follow_rate") or 0)
    if pfr > 0:
        if pfr < 0.5:
            insights.append(
                {
                    "type": "discipline",
                    "text": f"Plan follow rate is {pfr * 100:.0f}% — less than half of trades follow the plan. This is the single highest-leverage improvement. Every trade should have a plan before entry.",
                }
            )
        elif pfr >= 0.8:
            insights.append(
                {
                    "type": "strength",
                    "text": f"Plan follow rate is {pfr * 100:.0f}% — strong discipline. Maintain this by writing the plan before entry.",
                }
            )

    # Execution vs sizing gap
    avg_exec = float(totals.get("avg_exec") or 0)
    avg_sizing = float(totals.get("avg_sizing") or 0)
    if avg_exec > 0 and avg_sizing > 0 and abs(avg_exec - avg_sizing) > 1.0:
        weaker = "sizing" if avg_sizing < avg_exec else "execution"
        insights.append(
            {
                "type": "gap",
                "text": f"Execution ({avg_exec:.1f}/5) vs Sizing ({avg_sizing:.1f}/5) gap detected. Your {weaker} quality is lagging — focus improvement there.",
            }
        )

    # Emotion patterns
    if emotion_rows:
        negative_emotions = [
            e
            for e in emotion_rows
            if (e.get("emotion_before") or "").lower()
            in ("fomo", "revenge", "impatient", "anxious", "greedy", "distracted")
        ]
        positive_emotions = [
            e for e in emotion_rows if (e.get("emotion_before") or "").lower() in ("calm", "confident", "focused")
        ]
        if negative_emotions:
            top = negative_emotions[0]
            insights.append(
                {
                    "type": "warning",
                    "text": f"Negative pre-trade emotion detected: {top.get('emotion_before', '')} ({top.get('n', 0)} trades). When you feel {top.get('emotion_before', '').lower()}, pause and re-evaluate. Consider waiting 15 minutes before acting.",
                }
            )
        if positive_emotions:
            top = positive_emotions[0]
            insights.append(
                {
                    "type": "strength",
                    "text": f"Most common positive state: {top.get('emotion_before', '')} ({top.get('n', 0)} trades). Aim to trade from this state.",
                }
            )

    # Mistake frequency
    if mistake_rows:
        top_mistake = mistake_rows[0]
        insights.append(
            {
                "type": "mistake",
                "text": f"Most frequent mistake: {top_mistake.get('tag', '')} ({top_mistake.get('n', 0)} times). Write this on a sticky note near your screen. Every review that flags this pattern is a learning opportunity.",
            }
        )

    # Coaching summaries — Keep Doing / Stop Doing / Review Next
    keep_doing = []
    stop_doing = []
    review_next = []

    if setup_rows:
        best_s = max(setup_rows, key=lambda r: float(r.get("well_exec_rate") or 0))
        if float(best_s.get("well_exec_rate") or 0) >= 0.6:
            keep_doing.append(
                f"{best_s['setup_name']} setups ({float(best_s.get('well_exec_rate') or 0) * 100:.0f}% well-executed)"
            )

    if mistake_rows and len(mistake_rows) >= 1:
        stop_doing.append(f"{mistake_rows[0].get('tag', '')} — your most frequent mistake")

    if emotion_rows:
        neg = [e for e in emotion_rows if (e.get("emotion_before") or "").lower() in ("fomo", "revenge", "impatient")]
        if neg:
            stop_doing.append(f"Trading from {neg[0].get('emotion_before', '').lower()} state")

    if total >= 3:
        review_next.append("Trades with execution score < 3 — what went wrong?")
        if float(totals.get("plan_follow_rate") or 0) < 0.7:
            review_next.append("Trades where plan was not followed — what caused the deviation?")

    if keep_doing or stop_doing or review_next:
        coaching = []
        if keep_doing:
            coaching.append({"type": "keep", "text": "Keep doing: " + ". ".join(keep_doing)})
        if stop_doing:
            coaching.append({"type": "stop", "text": "Stop doing: " + ". ".join(stop_doing)})
        if review_next:
            coaching.append({"type": "review", "text": "Review next: " + ". ".join(review_next)})
        insights.extend(coaching)

    # Sample size guidance
    if total >= 5 and total < 10:
        insights.append(
            {
                "type": "guidance",
                "text": f"{total} reviews — patterns are emerging but not yet statistically reliable. Keep reviewing trades. 20+ reviews will show strong methodology signals.",
            }
        )
    elif total >= 10 and total < 20:
        insights.append(
            {
                "type": "guidance",
                "text": f"{total} reviews — enough for preliminary methodology comparison. The patterns above are directionally useful.",
            }
        )

    return insights


def _attach_backtest_grades(trades):
    """Enrich a list of trade dicts (each carrying a 'trade_key') with entry_grade /
    exit_grade from trade_backtest_results. Mutates in place; silent no-op on error so
    the journal never fails just because grading data is missing."""
    keys = [t.get("trade_key") for t in trades if t.get("trade_key")]
    if not keys:
        return
    try:
        rows = _db_query(
            """SELECT trade_key, entry_grade, exit_grade, entry_rsi, left_on_table_20d
               FROM trade_backtest_results
               WHERE trade_key = ANY(%s) AND entry_grade IS NOT NULL""",
            (keys,),
            fetch="all",
        )
        gmap = {r["trade_key"]: r for r in (rows or [])}
        for t in trades:
            g = gmap.get(t.get("trade_key"))
            if g:
                t["entry_grade"] = g.get("entry_grade")
                t["exit_grade"] = g.get("exit_grade")
                if g.get("entry_rsi") is not None:
                    t["entry_rsi"] = float(g["entry_rsi"])
                if g.get("left_on_table_20d") is not None:
                    t["left_on_table_20d"] = float(g["left_on_table_20d"])
    except Exception:
        pass


def _journal_by_ticker(query=None):
    """GET /api/v2/journal/by-ticker [?symbol=&from=&to=&account=] — PER-TICKER realized-performance
    rollup over trade_closed (the same closed-trade source as /api/v2/journal). Answers "aggregate total
    performance of a ticker over time" — e.g. all BJDX trades → #trades, win rate, total/avg P&L, avg
    hold, best/worst, profit factor, over an optional date range.

    - No symbol → ranked ticker table (one row per symbol) + portfolio totals.
    - symbol given → that ticker's rollup + per-strategy & per-account splits + the individual trades.
    Read-only.
    """
    q = query or {}
    g = lambda k: (q.get(k)[0] if isinstance(q.get(k), list) else q.get(k)) or None
    symbol = (g("symbol") or "").upper().strip() or None
    d_from, d_to, account = g("from"), g("to"), g("account")

    where = ["pnl IS NOT NULL"]
    params = []
    if symbol:
        where.append("UPPER(symbol) = %s")
        params.append(symbol)
    if account:
        where.append("account = %s")
        params.append(account)
    if d_from:
        where.append("close_date >= %s")
        params.append(d_from)
    if d_to:
        where.append("close_date <= %s")
        params.append(d_to)
    where_sql = " AND ".join(where)

    # aggregate expressions reused for the ticker table, per-strategy, per-account, and totals
    aggs = """
        count(*) AS trades,
        SUM((pnl > 0)::int) AS wins,
        SUM((pnl < 0)::int) AS losses,
        ROUND(100.0 * SUM((pnl > 0)::int) / NULLIF(count(*), 0), 1) AS win_rate_pct,
        ROUND(SUM(pnl)::numeric, 2) AS total_pnl,
        ROUND(AVG(pnl)::numeric, 2) AS avg_pnl,
        ROUND(AVG(pnl_pct)::numeric, 2) AS avg_pnl_pct,
        ROUND(MAX(pnl)::numeric, 2) AS best_pnl,
        ROUND(MIN(pnl)::numeric, 2) AS worst_pnl,
        ROUND(AVG(hold_days)::numeric, 1) AS avg_hold_days,
        ROUND(AVG(r_multiple)::numeric, 2) AS avg_r,
        ROUND((SUM(pnl) FILTER (WHERE pnl > 0)
               / NULLIF(ABS(SUM(pnl) FILTER (WHERE pnl < 0)), 0))::numeric, 2) AS profit_factor,
        MIN(close_date)::text AS first_close,
        MAX(close_date)::text AS last_close
    """
    tickers = (
        _db_query(
            f"SELECT symbol, {aggs} FROM trade_closed WHERE {where_sql} GROUP BY symbol "
            f"ORDER BY total_pnl DESC NULLS LAST",
            tuple(params) if params else None,
        )
        or []
    )
    totals = (
        _db_query(f"SELECT {aggs} FROM trade_closed WHERE {where_sql}", tuple(params) if params else None, fetch="one")
        or {}
    )

    # hold-length distribution: bucket closed trades by holding period → count / win-rate / P&L per band,
    # so the UI can chart "which holding period actually works." Ordered intraday → long. Same filters.
    hold_bucket_case = """
        CASE WHEN hold_days = 0 THEN 'Intraday'
             WHEN hold_days <= 4 THEN '1-4d'
             WHEN hold_days <= 20 THEN '5-20d'
             WHEN hold_days <= 60 THEN '21-60d'
             ELSE '60d+' END"""
    hold_rows = (
        _db_query(
            f"""SELECT {hold_bucket_case} AS bucket,
                   MIN(CASE WHEN hold_days = 0 THEN 0 WHEN hold_days <= 4 THEN 1 WHEN hold_days <= 20 THEN 2
                            WHEN hold_days <= 60 THEN 3 ELSE 4 END) AS ord,
                   count(*) AS trades,
                   SUM((pnl > 0)::int) AS wins,
                   ROUND(100.0 * SUM((pnl > 0)::int) / NULLIF(count(*), 0), 1) AS win_rate_pct,
                   ROUND(SUM(pnl)::numeric, 2) AS total_pnl,
                   ROUND(AVG(pnl)::numeric, 2) AS avg_pnl,
                   ROUND(AVG(pnl_pct)::numeric, 2) AS avg_pnl_pct,
                   ROUND(AVG(hold_days)::numeric, 1) AS avg_hold_days
            FROM trade_closed WHERE {where_sql} AND hold_days IS NOT NULL
            GROUP BY bucket ORDER BY ord""",
            tuple(params) if params else None,
        )
        or []
    )

    out = {
        "ok": True,
        "advisory_only": True,
        "symbol": symbol,
        "filters": {"from": d_from, "to": d_to, "account": account},
        "tickers": [_json_clean(t) for t in tickers],
        "totals": _json_clean(totals),
        "hold_distribution": [_json_clean(h) for h in hold_rows],
        "source": "trade_closed (realized closed trades)",
    }

    if symbol:
        out["by_strategy"] = [
            _json_clean(r)
            for r in (
                _db_query(
                    f"SELECT COALESCE(strategy_id, setup, 'unclassified') AS strategy, {aggs} "
                    f"FROM trade_closed WHERE {where_sql} GROUP BY 1 ORDER BY total_pnl DESC NULLS LAST",
                    tuple(params) if params else None,
                )
                or []
            )
        ]
        out["by_account"] = [
            _json_clean(r)
            for r in (
                _db_query(
                    f"SELECT account, {aggs} FROM trade_closed WHERE {where_sql} GROUP BY account "
                    f"ORDER BY total_pnl DESC NULLS LAST",
                    tuple(params) if params else None,
                )
                or []
            )
        ]
        out["trades"] = [
            _json_clean(r)
            for r in (
                _db_query(
                    f"""SELECT symbol, account, open_date::text, close_date::text, trade_type, shares,
                       buy_price, sell_price, pnl, pnl_pct, hold_days, r_multiple,
                       COALESCE(strategy_id, setup) AS strategy, setup, rating
                FROM trade_closed WHERE {where_sql} ORDER BY close_date DESC, id DESC LIMIT 500""",
                    tuple(params) if params else None,
                )
                or []
            )
        ]
    return out


def journal():
    """GET /api/v2/journal — closed trades from DB (trade_closed table)."""
    import psycopg2.extras

    # Try DB first, fall back to JSON
    trades = []
    try:
        rows = _db_query(
            """SELECT tc.symbol, tc.account, tc.open_date::text, tc.close_date::text, tc.trade_type,
                      tc.shares, tc.buy_price, tc.sell_price, tc.cost_basis, tc.proceeds,
                      tc.pnl, tc.pnl_pct, tc.hold_days,
                      srt.strategy_tag, srt.classification,
                      COALESCE(eq.entry_time, srt.entry_time)::text AS entry_time,
                      COALESCE(eq.exit_time, srt.exit_time)::text AS exit_time
               FROM trade_closed tc
               LEFT JOIN LATERAL (
                   SELECT s.strategy_tag, s.classification, s.entry_time, s.exit_time
                   FROM schwab_round_trips s
                   WHERE UPPER(s.symbol) = UPPER(tc.symbol) AND s.account = tc.account
                     AND s.exit_time::date = tc.close_date::date
                     AND ABS(s.entry_price - tc.buy_price) < 0.08
                   ORDER BY ABS(s.entry_price - tc.buy_price), s.exit_time DESC LIMIT 1
               ) srt ON true
               LEFT JOIN LATERAL (
                   SELECT entry_time, exit_time FROM trade_execution_quality eq
                   WHERE UPPER(eq.symbol) = UPPER(tc.symbol) AND eq.entry_time::date = tc.close_date
                     AND ABS(eq.entry_price - tc.buy_price) < 0.08
                   ORDER BY ABS(eq.entry_price - tc.buy_price), eq.exit_time DESC LIMIT 1
               ) eq ON true
               WHERE tc.buy_price > 0 OR tc.pnl != 0
               ORDER BY tc.close_date DESC, tc.symbol
               LIMIT 2000""",
            fetch="all",
        )
        if rows:
            for r in rows:
                item = {k: (float(v) if isinstance(v, Decimal) else v) for k, v in r.items()}
                # Construct trade_key for review linkage
                item["trade_key"] = f"{item.get('symbol', '')}:{item.get('account', '')}:{item.get('close_date', '')}"
                trades.append(item)
    except Exception:
        pass

    # Fallback to JSON if DB empty
    if not trades:
        j = _load_json(STATE_DIR / "trade_journal.json") or {}
        raw = j.get("closed_trades", [])
        for t in raw[:500]:
            item = {
                "symbol": t.get("symbol", ""),
                "account": t.get("account", ""),
                "open_date": t.get("open_date", ""),
                "close_date": t.get("close_date", ""),
                "trade_type": t.get("trade_type", ""),
                "shares": t.get("shares", 0),
                "buy_price": t.get("buy_price", 0),
                "sell_price": t.get("sell_price", 0),
                "cost_basis": t.get("cost_basis", 0),
                "proceeds": t.get("proceeds", 0),
                "pnl": t.get("pnl", 0),
                "pnl_pct": t.get("pnl_pct", 0),
                "hold_days": t.get("hold_days", 0),
            }
            item["trade_key"] = f"{item['symbol']}:{item['account']}:{item['close_date']}"
            trades.append(item)

    # Enrich with entry/exit grades from backtest grading (join on trade_key)
    _attach_backtest_grades(trades)

    real_trades = [t for t in trades if (t.get("pnl") or 0) != 0]

    # Compute stats from DB data
    total_pnl = sum(t.get("pnl", 0) for t in real_trades)
    winners = [t for t in real_trades if t["pnl"] > 0]
    losers = [t for t in real_trades if t["pnl"] < 0]
    win_rate = round(len(winners) / len(real_trades) * 100, 1) if real_trades else 0
    avg_winner = round(sum(t["pnl"] for t in winners) / len(winners), 2) if winners else 0
    avg_loser = round(sum(t["pnl"] for t in losers) / len(losers), 2) if losers else 0
    gross_profit = sum(t["pnl"] for t in winners)
    gross_loss = abs(sum(t["pnl"] for t in losers))
    profit_factor = round(gross_profit / gross_loss, 2) if gross_loss > 0 else 0
    expectancy = round(total_pnl / len(real_trades), 2) if real_trades else 0

    stats = {
        "total_pnl": round(total_pnl, 2),
        "win_rate": win_rate,
        "profit_factor": profit_factor,
        "avg_winner": avg_winner,
        "avg_loser": avg_loser,
        "trade_expectancy": expectancy,
    }

    return {
        "stats": stats,
        # P0-6 labeling (2026-07-14): this endpoint reads trade_closed, which is refreshed from
        # schwab_round_trips (broker-derived round trips; basis_unknown + canary trips excluded).
        # The global header's "Journal" tiles read trade_journal.json instead — a FIFO rebuild of the
        # manually-imported Schwab History CSV (includes pre-2025 history + $0 scratches, lags until a
        # new CSV import). Different basis → intentionally different numbers; both surfaces are labeled.
        "stats_basis": "broker_round_trips",
        "stats_basis_note": (
            "Broker-verified round trips (schwab_round_trips → trade_closed); "
            "excludes unknown-basis and canary trips. Header Journal tiles use the "
            "CSV-import FIFO journal — a different, wider-history basis."
        ),
        "trade_count": len(trades),
        "real_trade_count": len(real_trades),
        "trades": [
            {
                "trade_key": f"{t.get('symbol', '')}:{t.get('account', '')}:{t.get('close_date', '')}",
                **t,
            }
            for t in trades[:500]
        ],
    }


def risk():
    """GET /api/v2/risk — portfolio risk overview.

    TODO Data Broker: get_risk_snapshot covers ~70% (JSON file aggregation, position risk,
         stop health, correlation data). The broker-protective-stop overlay from
         open_trades_intelligence and paper-trade enrichment stay in this handler.
    """
    # ---- Data Broker: risk_snapshot (primary) ----
    try:
        from lib.data_broker.risk_snapshot import get_risk_snapshot

        snap = get_risk_snapshot(db_query=_db_query, max_age_s=45)
        if snap and snap.get("ok"):
            # The broker covers position risk + stop health + correlation.
            # Still need live broker stop overlay for canonical protection truth.
            _bstops = {}
            try:
                import sys as _sys2

                _sys2.path.insert(0, str(Path(__file__).resolve().parent))
                import open_trades_intelligence as _oti

                _accts = sorted({p.get("account", "") for p in (snap.get("positions") or []) if p.get("account")})
                for (acct, sym), v in (_oti._broker_protective_stops(_accts) or {}).items():
                    _bstops[(sym, acct)] = v
            except Exception:
                pass
            # Enrich positions with live broker stop data
            for p in snap.get("positions") or []:
                _bs = _bstops.get((p.get("symbol", ""), p.get("account", "")))
                if _bs:
                    p["broker_protected"] = True
                    p["broker_stop"] = _bs.get("stop_price")
                    p["broker_order_id"] = _bs.get("order_id")
                    p["stop_source"] = "broker"
                    if _bs.get("stop_price"):
                        p["stop_price"] = _bs["stop_price"]
                else:
                    p["broker_protected"] = False
                    p["stop_source"] = "planned" if p.get("stop_price") else "none"
                p["has_stop"] = bool(p.get("stop_price"))
            return {
                "portfolio_heat_pct": snap.get("portfolio", {}).get("heat_pct", 0),
                "total_risk_dollars": snap.get("portfolio", {}).get("total_risk_dollars", 0),
                "pct_protected": snap.get("portfolio", {}).get("pct_protected", 0),
                "total_protected_mv": snap.get("portfolio", {}).get("total_protected_mv", 0),
                "total_unprotected_mv": snap.get("portfolio", {}).get("total_unprotected_mv", 0),
                "position_count": snap.get("portfolio", {}).get("position_count_real", 0),
                "paper_position_count": snap.get("portfolio", {}).get("position_count_paper", 0),
                "positions": snap.get("positions", []),
                "stops": snap.get("stops_map", {}),
                "escalation": snap.get("escalation", {}),
                "correlation": snap.get("correlation", []),
                "stop_health": snap.get("stop_health", {}),
                "source": "data_broker.risk_snapshot",
            }
    except Exception:
        pass
    # ---- Original fallback ----
    rm = _load_json(STATE_DIR / "risk_management.json") or {}
    stops = _load_json(STATE_DIR / "stops.json") or {}
    positions = rm.get("positions", [])
    # Tag real-money positions so the UI can split real vs paper (headline heat/risk KPIs below stay
    # real-money only — they come precomputed from risk_management.json and exclude paper by design).
    for _rp in positions:
        _rp.setdefault("environment", "real")
    # ── PAPER ACCOUNT (operator 2026-06-21) ──────────────────────────────────────────────────────────────
    # Show the Alpaca paper account on Risk too. Paper positions carry REAL live SELL stops (the bracket/
    # ratchet pipeline), so they flow through the SAME canonical stop reconciliation below and show as
    # broker_protected. Tagged environment="paper" + risk_excluded so the UI can filter and the real-money
    # aggregates are never polluted.
    try:
        _prows = (
            _db_query("""SELECT UPPER(account) account, symbol, sum(shares) sh,
                                     sum(entry_price*shares)/NULLIF(sum(shares),0) avg_entry,
                                     min(stop_loss) stop, max(current_price) cur_px
                              FROM paper_trades WHERE lower(status)='open'
                              GROUP BY UPPER(account), symbol""")
            or []
        )
        for _pr in _prows:
            _sh = float(_pr.get("sh") or 0)
            if _sh <= 0:
                continue
            _cur = (
                float(_pr["cur_px"]) if _pr.get("cur_px") else (float(_pr["avg_entry"]) if _pr.get("avg_entry") else 0)
            )
            _stop = float(_pr["stop"]) if _pr.get("stop") is not None else None
            _mv = _sh * _cur if _cur else 0
            _dist = round(((_cur - _stop) / _cur) * 100, 1) if (_cur and _stop) else None
            positions.append(
                {
                    "symbol": (_pr.get("symbol") or "").strip(),
                    "account": "tradeai_automated",
                    "environment": "paper",
                    "risk_excluded": True,
                    "market_value": round(_mv, 2),
                    "current_price": _cur,
                    "stop_price": _stop,
                    "distance_pct": _dist,
                    "distance_to_stop_pct": _dist,
                    "max_loss": round(_sh * (_cur - _stop), 0) if (_cur and _stop) else 0,
                    "shares": _sh,
                    "status": "",
                    "triggered": bool(_dist is not None and _dist < 0),
                }
            )
    except Exception:
        pass
    # Enrich with live prices from holdings if risk prices are $0
    holdings = _load_json(STATE_DIR / "holdings.json") or {}
    h_prices = {}
    for h in holdings.get("holdings", []):
        sym = h.get("symbol", "")
        if sym and h.get("price", 0) > 0:
            h_prices[sym] = h["price"]
    # Also try enrichment cache
    enrich = _load_json(STATE_DIR / "ticker_enrichment_cache.json") or {}
    # ── CANONICAL STOP RECONCILIATION (operator 2026-06-21) ──────────────────────────────────────────────
    # risk_management.json holds the PLANNED stop (the level the strategy intends). The source of truth for
    # whether a position is actually protected — and at what price — is the broker's LIVE working SELL-stop
    # order (Stage 2c, same source the Open Trades card uses). Overlay it so 'protected'/'triggered' reflect
    # broker reality, not a planned value that may not be live (e.g. PFLT showed a $8.21 planned stop while no
    # live stop exists at the broker). canonical stop = live broker stop when present, else the planned stop.
    _bstops = {}
    try:
        import sys as _sys

        _sys.path.insert(0, str(Path(__file__).resolve().parent))
        import open_trades_intelligence as _oti

        _accts = sorted({p.get("account", "") for p in positions if p.get("account")})
        for (acct, sym), v in (_oti._broker_protective_stops(_accts) or {}).items():
            _bstops[(sym, acct)] = v
    except Exception:
        pass
    for p in positions:
        sym = p.get("symbol", "")
        if not p.get("current_price") or p["current_price"] == 0:
            p["current_price"] = h_prices.get(sym, 0)
        if not p.get("current_price") or p["current_price"] == 0:
            ec = enrich.get(sym, {})
            if isinstance(ec, dict) and ec.get("price", 0) > 0:
                p["current_price"] = ec["price"]
        # Recompute distance_pct and max_loss with live price
        if p.get("current_price", 0) > 0 and p.get("stop_price"):
            dist = ((p["current_price"] - p["stop_price"]) / p["current_price"]) * 100
            p["distance_pct"] = round(dist, 1)
            shares = p.get("market_value", 0) / p["current_price"] if p["current_price"] > 0 else 0
            p["max_loss"] = (
                round(shares * (p["current_price"] - p["stop_price"]), 0) if shares > 0 else p.get("max_loss", 0)
            )
    # Load stop confirmations for enrichment
    conf_rows = (
        _db_query(
            "SELECT symbol, account, stop_status, stop_confirmed, stop_price_confirmed, stop_confirmed_at, reminder_count FROM stop_confirmations"
        )
        or []
    )
    conf_map = {}
    for cr in conf_rows:
        conf_map[(cr.get("symbol", ""), cr.get("account", ""))] = {
            "stop_conf_status": cr.get("stop_status", "unknown"),
            "stop_confirmed": cr.get("stop_confirmed", False),
            "stop_price_confirmed": float(cr["stop_price_confirmed"]) if cr.get("stop_price_confirmed") else None,
            "stop_confirmed_at": str(cr["stop_confirmed_at"])[:16] if cr.get("stop_confirmed_at") else None,
            "reminder_count": cr.get("reminder_count", 0),
        }
    return {
        "portfolio_heat_pct": rm.get("portfolio_heat_pct", 0),
        "total_risk_dollars": rm.get("total_risk_dollars", 0),
        "pct_protected": rm.get("pct_protected", 0),
        "total_protected_mv": rm.get("total_protected_mv", 0),
        "total_unprotected_mv": rm.get("total_unprotected_mv", 0),
        "position_count": sum(1 for p in positions if not p.get("risk_excluded")),
        "paper_position_count": sum(1 for p in positions if p.get("risk_excluded")),
        "positions": [
            (
                lambda _bs, _planned, _conf: {
                    "symbol": p.get("symbol", ""),
                    "market_value": p.get("market_value", 0),
                    "account": p.get("account", ""),
                    "environment": p.get("environment", "real"),
                    "risk_excluded": bool(p.get("risk_excluded")),
                    # CANONICAL protection hierarchy: (1) live broker stop order [API accounts], (2) operator-confirmed
                    # stop [no-API accounts: stop lives in ToS, confirmed in stop_confirmations], (3) planned stop
                    # [risk_management.json, advisory only]. stop_price = the highest-confidence value available.
                    "stop_price": (
                        _bs.get("stop_price")
                        if _bs
                        else (_conf.get("stop_price_confirmed") if _conf.get("stop_confirmed") else _planned)
                    ),
                    "current_price": p.get("current_price") or p.get("price", 0),
                    "distance_pct": p.get("distance_pct"),
                    "max_loss": p.get("max_loss") or p.get("max_loss_dollar", 0),
                    "status": p.get("status", ""),
                    "triggered": bool(p.get("triggered"))
                    or (isinstance(p.get("distance_pct"), (int, float)) and p["distance_pct"] < 0),
                    # has_stop = a stop LEVEL exists (broker/confirmed/planned) — keeps buckets stable, avoids a
                    # transient broker hiccup flagging everything unprotected.
                    "has_stop": bool(_bs or _conf.get("stop_confirmed") or _planned),
                    # broker_protected = CANONICAL truth: a VERIFIED live stop — broker API order OR operator-confirmed.
                    "broker_protected": bool(_bs) or bool(_conf.get("stop_confirmed")),
                    "broker_stop": (_bs.get("stop_price") if _bs else None),
                    "broker_order_id": (_bs.get("order_id") if _bs else None),
                    "planned_stop": _planned,
                    "stop_source": (
                        "broker"
                        if _bs
                        else ("confirmed" if _conf.get("stop_confirmed") else ("planned" if _planned else "none"))
                    ),
                    "rsi": p.get("rsi"),
                    "day_change_pct": p.get("day_change_pct"),
                    "distance_to_stop_pct": p.get("distance_to_stop_pct") or p.get("distance_pct"),
                    **_conf,
                }
            )(
                _bstops.get((p.get("symbol", ""), p.get("account", ""))),
                p.get("stop_price"),
                conf_map.get((p.get("symbol", ""), p.get("account", "")), {}),
            )
            for p in positions
        ],
        "stops": {
            sym: {"stop_price": v.get("stop_price") or v.get("stop"), "triggered": v.get("triggered", False)}
            for sym, v in stops.items()
            if isinstance(v, dict)
        },
        # Escalation lane
        "escalation": {
            "danger": [
                {
                    "symbol": p.get("symbol", ""),
                    "max_loss": p.get("max_loss", 0),
                    "distance_pct": p.get("distance_pct", 0),
                    "account": p.get("account", ""),
                }
                for p in positions
                if p.get("status") in ("TRIGGERED", "DANGER")
            ][:4],
            "warning": [
                {
                    "symbol": p.get("symbol", ""),
                    "max_loss": p.get("max_loss", 0),
                    "distance_pct": p.get("distance_pct", 0),
                    "account": p.get("account", ""),
                }
                for p in positions
                if p.get("status") == "WARNING"
            ][:4],
            "unprotected": [
                {
                    "symbol": p.get("symbol", ""),
                    "market_value": p.get("market_value", 0),
                    "account": p.get("account", ""),
                }
                for p in positions
                if not p.get("stop_price") and not p.get("protected")
            ][:4],
        },
    }


def tax_lots():
    """Tax view built as ONE aggregate lot per CURRENT holding, from the holdings' authoritative
    Schwab average-cost basis (2026-07-21, operator choice). Reconciles with the portfolio by
    construction, so unrealized gains and taxable-loss harvest candidates are correct — replacing the
    stale tax_lots.json (double-counted / phantom-full-basis-loss lots after the Fidelity→Schwab
    transfer). Tradeoff: per-position, not per-purchase-lot; short/long-term is approximated from the
    earliest known lot DATE (not the stale share counts) or 'unknown'. Precise per-lot terms need a
    fresh Schwab Cost-Basis CSV import (imports/schwab_gainloss/)."""
    holdings = _load_json(STATE_DIR / "holdings.json") or {}

    # Best-effort acquisition date per (symbol, account) — DATES ONLY from the legacy lot file, never
    # its stale share counts — so we can approximate the holding-period term.
    _old = _load_json(STATE_DIR / "tax_lots.json") or {}
    _acq: dict[str, str] = {}
    for key, lot_list in _old.items() if isinstance(_old, dict) else []:
        if not isinstance(lot_list, list):
            continue
        for lot in lot_list:
            ld = lot.get("lot_date") or lot.get("acquired")
            if not ld:
                continue
            sym = lot.get("symbol", key.split(":")[0])
            acct = lot.get("account", key.split(":")[-1] if ":" in key else "")
            k = f"{sym}:{acct}"
            if k not in _acq or str(ld) < _acq[k]:  # earliest = conservative for long-term
                _acq[k] = str(ld)

    from datetime import datetime, date

    flat = []
    for p in holdings.get("holdings", []):
        if p.get("is_cash"):
            continue
        shares = float(p.get("shares") or 0)
        cost_basis = float(p.get("cost_basis") or 0)
        mv = float(p.get("market_value") or 0)
        px = float(p.get("current_price") or p.get("price") or 0)
        worthless = bool(p.get("delisted")) or str(p.get("bucket") or "").lower().startswith("delisted")
        if shares <= 0:
            continue
        # Include priced positions normally, AND genuinely delisted/worthless positions that carry a cost
        # basis (a real capital loss — the ONE case where full-basis-as-loss is correct; SRNE, delisted
        # CUSIPs). Skip only unpriced-but-LIVE positions we cannot value (e.g. rolled-over Fidelity funds).
        if px <= 0 and not (worthless and cost_basis > 0):
            continue
        symbol = p.get("symbol", "")
        account = p.get("account", "")
        unrealized_gain = round(mv - cost_basis, 2)
        gain_pct = round(unrealized_gain / cost_basis * 100, 1) if cost_basis > 0 else 0
        lot_date = _acq.get(f"{symbol}:{account}", "")
        holding_period = "unknown"
        if lot_date:
            try:
                ld = datetime.strptime(lot_date[:10], "%Y-%m-%d").date()
                holding_period = "long" if (date.today() - ld).days > 365 else "short"
            except Exception:
                pass
        flat.append(
            {
                "symbol": symbol,
                "account": account,
                "shares": round(shares, 4),
                "cost_basis": round(cost_basis, 2),
                "current_value": round(mv, 2),
                "unrealized_gain": unrealized_gain,
                "gain_pct": gain_pct,
                "acquired": lot_date,
                "holding_period": holding_period,
                "worthless": worthless and px <= 0,
                "basis_source": p.get("cost_basis_source"),
                "basis_partial": bool(p.get("basis_partial")),
            }
        )
    flat.sort(key=lambda x: abs(x.get("unrealized_gain", 0)), reverse=True)
    total_lots = len(flat)
    harvest = [l for l in flat if l["unrealized_gain"] < -100 and l["account"] in ("schwab_taxable", "taxable")]
    _lot_mv = sum(l.get("current_value") or 0 for l in flat)
    _hold_mv = sum(float(h.get("market_value") or 0) for h in holdings.get("holdings", []) if not h.get("is_cash"))
    _reconciled = bool(_hold_mv) and abs(_lot_mv - _hold_mv) < max(1.0, _hold_mv * 0.001)
    _total_gain = round(sum(l.get("unrealized_gain") or 0 for l in flat), 2)
    _worthless_loss = round(sum(l.get("unrealized_gain") or 0 for l in flat if l.get("worthless")), 2)
    return {
        "count": total_lots,
        "lots": flat[:500],
        "harvest_candidates": len(harvest),
        "total_unrealized_gain": _total_gain,
        "worthless_security_loss": _worthless_loss,
        "lots_market_value": round(_lot_mv, 2),
        "holdings_market_value": round(_hold_mv, 2),
        "reconciled_to_holdings": _reconciled,
        "basis": "aggregate_per_position",
        "data_note": (
            "One aggregate lot per current holding (Schwab average-cost basis); market value "
            "reconciles with the portfolio. Includes delisted/worthless positions (SRNE, delisted "
            "CUSIPs) as realizable capital losses, so total unrealized here is below the Holdings "
            "page's headline (which hides worthless names). Per-position, not per-purchase-lot; "
            "short/long-term is approximate — import fresh Schwab Cost-Basis CSVs for precise terms."
        ),
    }


def dividends():
    """Dividend income desk payload.

    Expands portfolio-level payers into per-account rows using current holdings
    market-value share so Portfolio → Dividends can filter by ?acct= without
    client-side guesswork. Portfolio totals remain the calendar source of truth.
    """
    d = _load_json(STATE_DIR / "dividend_calendar.json") or {}
    payers = list(d.get("payers") or [])
    for p in payers:
        p.setdefault("qualified", False)
        p.setdefault("safety", "watch")

    holdings_doc = _load_json(STATE_DIR / "holdings.json") or {}
    holdings = holdings_doc.get("holdings") or []
    # symbol -> [(account, market_value, shares), ...]
    by_sym: dict = {}
    for h in holdings:
        sym = str(h.get("symbol") or "").upper().strip()
        if not sym or sym in ("CASH", "SPAXX", "VMFXX", "USD"):
            continue
        try:
            mv = float(h.get("market_value") or 0)
        except (TypeError, ValueError):
            mv = 0.0
        if mv <= 0:
            continue
        acct = str(h.get("account") or h.get("account_key") or "unknown")
        try:
            sh = float(h.get("quantity") or h.get("shares") or 0)
        except (TypeError, ValueError):
            sh = 0.0
        by_sym.setdefault(sym, []).append((acct, mv, sh))

    expanded = []
    already_accounted = any(p.get("account") or p.get("account_key") for p in payers)
    if already_accounted:
        expanded = payers
        attribution = "source_calendar"
    else:
        attribution = "holdings_mv_share"
        for p in payers:
            sym = str(p.get("symbol") or "").upper().strip()
            legs = by_sym.get(sym) or []
            try:
                annual = float(p.get("annual_income") or 0)
            except (TypeError, ValueError):
                annual = 0.0
            try:
                monthly = float(p.get("monthly_amort") or (annual / 12.0))
            except (TypeError, ValueError):
                monthly = annual / 12.0
            if not legs:
                row = dict(p)
                row["account"] = None
                expanded.append(row)
                continue
            total_mv = sum(mv for _, mv, _ in legs) or 1.0
            for acct, mv, sh in legs:
                share = mv / total_mv
                row = dict(p)
                row["account"] = acct
                row["account_key"] = acct
                row["market_value"] = round(mv, 2)
                if sh > 0:
                    row["shares"] = round(sh, 4)
                elif p.get("shares") is not None:
                    try:
                        row["shares"] = round(float(p["shares"]) * share, 4)
                    except (TypeError, ValueError):
                        pass
                row["annual_income"] = round(annual * share, 2)
                row["monthly_amort"] = round(monthly * share, 2)
                expanded.append(row)

    by_account: dict = {}
    for row in expanded:
        acct = row.get("account") or row.get("account_key") or "_unassigned"
        bucket = by_account.setdefault(acct, {"annual": 0.0, "monthly": 0.0, "payers": 0})
        try:
            bucket["annual"] += float(row.get("annual_income") or 0)
            bucket["monthly"] += float(row.get("monthly_amort") or 0)
        except (TypeError, ValueError):
            pass
        bucket["payers"] += 1
    for acct, b in by_account.items():
        b["annual"] = round(b["annual"], 2)
        b["monthly"] = round(b["monthly"], 2)

    return {
        "has_data": d.get("has_data", bool(payers)),
        "payers": expanded,
        "payers_portfolio": payers,
        "by_account": by_account,
        "account_attribution": attribution,
        "total_annual": d.get("total_annual", 0),
        "qualified_annual": d.get("qualified_annual", 0),
        "ordinary_annual": d.get("ordinary_annual", 0),
        "monthly_average": d.get("monthly_average", 0),
        "monthly_summary": d.get("monthly_summary", {}),
        "ex_div_alerts": d.get("ex_div_alerts", []),
        "last_updated": d.get("last_updated", ""),
    }


def retirement():
    r = _load_json(STATE_DIR / "retirement_roadmap.json") or {}
    div_cal = _load_json(STATE_DIR / "dividend_calendar.json") or {}
    accounts = r.get("accounts") or {}
    key_dates = r.get("key_dates") or {}
    loan = r.get("loan") or {}
    gw = r.get("golden_window") or {}
    tl = r.get("timeline") or []

    # Use canonical holdings total as primary, fall back to roadmap snapshot
    _canonical_h = _load_json(STATE_DIR / "holdings.json") or {}
    total = (
        _canonical_h.get("portfolio_totals", {}).get("total_value")
        or accounts.get("portfolio_total")
        or accounts.get("total")
        or 0
    )
    roth = accounts.get("roth") or accounts.get("roth_balance") or 0
    traditional = accounts.get("traditional") or accounts.get("traditional_ira") or accounts.get("pre_tax") or 0
    taxable = accounts.get("taxable") or 0
    current_age = r.get("current_age", 0)
    annual_div = div_cal.get("total_annual", 0)
    gw_start = gw.get("start_age") or 68.5
    gw_conversion = gw.get("optimal_annual_conversion") or gw.get("sweet_spot_annual") or 50000
    loan_balance = loan.get("balance", 0)
    loan_days = loan.get("days_remaining") or key_dates.get("days_to_loan_deadline", 0)

    # ── Generate actionable narrative ──
    narrative_lines = []

    # Roth conversion guidance
    roth_pct = round(roth / total * 100, 1) if total else 0
    trad_pct = round(traditional / total * 100, 1) if total else 0
    narrative_lines.append(
        f"Portfolio: ${total:,.0f} — {trad_pct}% traditional (${traditional:,.0f}), {roth_pct}% Roth (${roth:,.0f}), taxable ${taxable:,.0f}."
    )

    if current_age and current_age < 62:
        years_to_gw = round(float(gw_start) - current_age, 1) if gw_start else 0
        if years_to_gw > 0:
            projected_roth = roth * (1.07**years_to_gw)  # 7% growth assumption
            narrative_lines.append(
                f"Golden Window starts in ~{years_to_gw} years (age {gw_start}). "
                f"At 7% growth, Roth projects to ~${projected_roth:,.0f} by then."
            )
            if gw_conversion:
                narrative_lines.append(
                    f"Optimal annual conversion: ${gw_conversion:,.0f}/year during the {gw.get('years_available', 4.5)}-year window. "
                    f"This targets converting ~${gw_conversion * float(gw.get('years_available', 4.5)):,.0f} total from traditional to Roth tax-free."
                )

    # SSDI context
    if current_age and current_age < 62:
        narrative_lines.append(
            "Current income: SSDI. Roth conversions during SSDI years benefit from lower tax bracket. "
            "Maximize conversions now while income is below standard deduction + SSDI thresholds."
        )

    # Loan urgency
    if loan_balance > 0 and loan_days > 0:
        monthly = loan.get("monthly_to_payoff", 0)
        urgency = "URGENT" if loan_days < 365 else ("MODERATE" if loan_days < 730 else "ON TRACK")
        narrative_lines.append(
            f"401k Loan: ${loan_balance:,.0f} due in {loan_days} days ({urgency}). "
            f"Monthly payment: ${monthly:,.0f}. Failure to repay triggers taxable distribution + 10% penalty if under 59.5."
        )

    # Dividend income in retirement context
    if annual_div > 0:
        monthly_div = annual_div / 12
        narrative_lines.append(
            f"Dividend income: ${annual_div:,.0f}/year (${monthly_div:,.0f}/month). "
            f"This covers {round(monthly_div / 4000 * 100, 0)}% of estimated $4,000/month retirement spending need."
        )
        qualified = div_cal.get("qualified_annual", 0)
        if qualified:
            narrative_lines.append(
                f"Qualified dividends: ${qualified:,.0f}/year — taxed at preferential long-term capital gains rates (0% if income under ~$44K)."
            )

    # Current month dividends
    current_month = _get_current_month_dividends(div_cal)
    if current_month.get("symbols"):
        narrative_lines.append(
            f"This month ({current_month['month_name']}): ${current_month['total']:,.0f} expected from {current_month['count']} positions — {', '.join(current_month['symbols'][:8])}."
        )

    # Golden-window calendar YEARS from key_dates (the gw object only carries ages) — the UI shows the
    # window as years; without these it rendered "No window configured" despite the dates existing.
    def _yr(s):
        try:
            y = int(str(s)[:4])
            return y if 1900 < y < 2200 else None
        except Exception:
            return None

    gw_start_year = _yr(key_dates.get("golden_window_start"))
    gw_end_year = _yr(key_dates.get("golden_window_end"))

    return {
        "as_of": r.get("as_of", ""),
        "current_age": current_age,
        "key_dates": key_dates,
        "accounts": {
            "total": total,
            "roth": roth,
            "traditional": traditional,
            "taxable": taxable,
        },
        "loan": {
            "balance": loan_balance,
            "deadline": loan.get("deadline", key_dates.get("loan_deadline", "")),
            "days_remaining": loan_days,
            "monthly_to_payoff": loan.get("monthly_to_payoff", 0),
        },
        "timeline": tl,
        "golden_window": {
            "start_age": gw_start,
            "end_age": gw.get("end_age") or key_dates.get("golden_window_end", ""),
            # UI-facing calendar-year + conversion fields (the card reads start_year/end_year/annual_conversion)
            "start_year": gw_start_year,
            "end_year": gw_end_year,
            "annual_conversion": gw_conversion,
            "bracket_ceiling": gw.get("bracket_ceiling") or "",
            "years_available": gw.get("years_available") or key_dates.get("years_to_golden", 0),
            "optimal_annual_conversion": gw_conversion,
            "projected_roth_at_start": gw.get("projected_roth_at_start") or roth,
            "narrative": gw.get("narrative") or "",
        },
        "dividend_income": {
            "annual": annual_div,
            # UI reads annual_total; keep it consistent with monthly_avg (annual/12) so it never shows $0 vs $X/mo
            "annual_total": annual_div,
            "monthly_avg": round(annual_div / 12, 2) if annual_div else 0,
            "yield_pct": round(annual_div / total * 100, 2) if total else None,
            "qualified_annual": div_cal.get("qualified_annual", 0),
            "current_month": current_month,
            "top_payers": [
                {
                    "symbol": p.get("symbol"),
                    "annual": p.get("annual_income"),
                    "yield_pct": p.get("yield_pct"),
                    "safety": p.get("safety"),
                }
                for p in (div_cal.get("payers") or [])[:8]
            ],
        },
        "intelligence_brief": narrative_lines,
        "canonical_total": (_load_json(STATE_DIR / "holdings.json") or {})
        .get("portfolio_totals", {})
        .get("total_value", 0),
        "snapshot_delta": round(
            float((_load_json(STATE_DIR / "holdings.json") or {}).get("portfolio_totals", {}).get("total_value", 0))
            - float(total),
            2,
        )
        if total
        else None,
        "snapshot_source": f"retirement_roadmap.json (generated {r.get('generated_at', 'unknown')})",
    }


def ai_analyst():
    """GET /api/v2/ai-analyst — pre-generated AI analysis sections from daily pipeline."""
    cache = _load_json(STATE_DIR / "ai_analysis_cache.json") or {}
    sections = []
    section_keys = [
        "executive_summary",
        "deep_holdings",
        "dividend_strategy",
        "bond_strategy",
        "ira_opportunities",
        "v_strategy",
        "defense_analysis",
    ]
    for key in section_keys:
        content = cache.get(key)
        if content:
            sections.append({"key": key, "title": key.replace("_", " ").title(), "content": content})
    # Compute staleness
    _ai_stale = True
    gen_at = cache.get("generated_at")
    if gen_at:
        try:
            from datetime import datetime

            _gen_dt = datetime.fromisoformat(str(gen_at).replace("Z", "+00:00")).replace(tzinfo=None)
            _ai_stale = (datetime.now() - _gen_dt).total_seconds() > 48 * 3600
        except Exception:
            pass
    # Add canonical context so frontend can show current values alongside stale text
    _canonical_total = (_load_json(STATE_DIR / "holdings.json") or {}).get("portfolio_totals", {}).get("total_value", 0)
    _div = (_load_json(STATE_DIR / "dividend_calendar.json") or {}).get("total_annual", 0)
    _rm = _load_json(STATE_DIR / "risk_management.json") or {}
    _triggered = len([p for p in _rm.get("positions", []) if p.get("status") == "TRIGGERED"])
    _heat = _rm.get("portfolio_heat_pct", 0)

    # Input freshness manifest
    _input_manifest = {
        "holdings_age_hours": round(
            (datetime.now() - datetime.fromtimestamp((STATE_DIR / "holdings.json").stat().st_mtime)).total_seconds()
            / 3600,
            1,
        )
        if (STATE_DIR / "holdings.json").exists()
        else None,
        "risk_age_hours": round(
            (
                datetime.now() - datetime.fromtimestamp((STATE_DIR / "risk_management.json").stat().st_mtime)
            ).total_seconds()
            / 3600,
            1,
        )
        if (STATE_DIR / "risk_management.json").exists()
        else None,
        "dividend_age_hours": round(
            (
                datetime.now() - datetime.fromtimestamp((STATE_DIR / "dividend_calendar.json").stat().st_mtime)
            ).total_seconds()
            / 3600,
            1,
        )
        if (STATE_DIR / "dividend_calendar.json").exists()
        else None,
        "canonical_total": _canonical_total,
        "annual_income": float(_div),
        "triggered_stops": _triggered,
        "portfolio_heat_pct": float(_heat) if _heat else 0,
    }

    return {
        "has_data": len(sections) > 0,
        "sections": sections,
        "generated_at": gen_at,
        "run_type": cache.get("run_type"),
        "model": cache.get("model"),
        "is_stale": _ai_stale,
        "stale_warning": f"This analysis was generated {gen_at} and may not reflect current portfolio state (${_canonical_total:,.0f}). Regenerate for current recommendations."
        if _ai_stale
        else None,
        "input_manifest": _input_manifest,
        "tlh_summary": _build_tlh_summary(),
    }


def _build_tlh_summary():
    """Build tax-loss harvesting summary for AI Analyst. Only taxable accounts."""
    try:
        lots = _load_json(STATE_DIR / "tax_lots.json") or {}
        holdings = _load_json(STATE_DIR / "holdings.json") or {}
        h_prices = {h["symbol"]: h.get("price", 0) for h in holdings.get("holdings", []) if h.get("symbol")}

        taxable_losses = []
        total_unrealized = 0
        # tax_lots.json is keyed by "symbol:account"
        for key, lot_list in lots.items():
            if not isinstance(lot_list, list):
                continue
            acct = key.split(":")[-1] if ":" in key else ""
            if "taxable" not in acct.lower():
                continue
            sym = key.split(":")[0] if ":" in key else key
            price = h_prices.get(sym, 0)
            for lot in lot_list:
                shares = float(lot.get("shares_remaining", 0) or 0)
                cost_per = float(lot.get("cost_per_share", 0) or 0)
                basis = shares * cost_per
                current = shares * price if price else 0
                gain = current - basis if basis > 0 else 0
                if gain < -50:
                    taxable_losses.append(
                        {"symbol": sym, "loss": round(gain, 2), "basis": round(basis, 2), "current": round(current, 2)}
                    )
                    total_unrealized += gain

        # Aggregate by symbol
        by_sym = {}
        for tl in taxable_losses:
            s = tl["symbol"]
            by_sym.setdefault(s, {"symbol": s, "loss": 0, "basis": 0, "current": 0})
            by_sym[s]["loss"] += tl["loss"]
            by_sym[s]["basis"] += tl["basis"]
            by_sym[s]["current"] += tl["current"]
        agg = sorted(by_sym.values(), key=lambda x: x["loss"])
        for a in agg:
            a["loss"] = round(a["loss"], 2)
            a["basis"] = round(a["basis"], 2)
            a["current"] = round(a["current"], 2)

        return {
            "taxable_candidates": len(agg),
            "total_taxable_loss": round(total_unrealized, 2),
            "top_candidates": agg[:10],
            "note": f"Only taxable account lots shown ({len(agg)} symbols with losses). IRA/401k losses cannot be harvested."
            if agg
            else "No material taxable losses to harvest.",
        }
    except Exception:
        return {
            "taxable_candidates": 0,
            "total_taxable_loss": 0,
            "top_candidates": [],
            "note": "Tax lot data unavailable.",
        }


def ai_ask(body: dict):
    """POST /api/v2/ai-ask — live query via the governed advisory lane."""
    question = (body.get("question") or "").strip()
    if not question:
        return 400, {"ok": False, "error": "question required"}
    context = body.get("context", "")
    # Build portfolio context from current data
    h = _load_json(STATE_DIR / "holdings.json") or {}
    totals = h.get("portfolio_totals", {})
    portfolio_ctx = f"Portfolio: ${totals.get('total_value', 0):,.0f}. Heat: {totals.get('day_change_pct', 0):.2f}%. "
    prompt = f"You are a portfolio analyst. Answer concisely based on this context:\n{portfolio_ctx}{context}\n\nQuestion: {question}"
    try:
        import llm_lane

        raw = llm_lane.generate(prompt, lane="deepseek-flash", timeout=90, process_id="api_v2_ai_ask")
        return 200, {"ok": True, "answer": str(raw or "").strip(), "model": "deepseek-v4-flash", "question": question}
    except Exception as e:
        return 500, {"ok": False, "error": f"LLM unavailable: {e}"}


# ── Watchlist DB-Backed Endpoints ──────────────────────────────────────────────

_SCREENER_FIND_BUY_SIDE = frozenset({"BUY", "STRONG_BUY", "ADD", "ADD_ON_PULLBACK"})


def _ensure_screener_find_pins_table():
    _db_query(
        """CREATE TABLE IF NOT EXISTS screener_find_pins (
                   symbol text PRIMARY KEY,
                   pinned_at timestamptz NOT NULL DEFAULT now(),
                   auto_research_at timestamptz,
                   discovery_reason text,
                   strategy_type text,
                   brief_snippet text,
                   cio_recommendation text,
                   active boolean NOT NULL DEFAULT true)""",
        fetch="none",
    )


def _screener_find_cio_rec(symbol):
    row = _db_query(
        """
        SELECT COALESCE(fs.recommendation, rc.latest_recommendation) AS rec
        FROM watchlist_items wi
        LEFT JOIN watchlist_final_synthesis fs ON upper(fs.symbol) = upper(wi.symbol)
        LEFT JOIN watchlist_research_cards rc ON rc.symbol = wi.symbol
        WHERE upper(wi.symbol) = upper(%s) AND wi.status <> 'removed'
        LIMIT 1
    """,
        (symbol,),
        fetch="one",
    )
    return str((row or {}).get("rec") or "").upper().strip()


def _sync_screener_find_pin(symbol, reason="", strategy_type=None, brief_snippet="", auto_research_at=None):
    """Pin a screener find while CIO verdict is buy-side; deactivate otherwise."""
    _ensure_screener_find_pins_table()
    sym = str(symbol or "").upper().strip()
    if not sym:
        return False
    cio = _screener_find_cio_rec(sym)
    active = cio in _SCREENER_FIND_BUY_SIDE
    _db_query(
        """
        INSERT INTO screener_find_pins
            (symbol, auto_research_at, discovery_reason, strategy_type, brief_snippet,
             cio_recommendation, active, pinned_at)
        VALUES (%s, COALESCE(%s, now()), %s, %s, %s, %s, %s, now())
        ON CONFLICT (symbol) DO UPDATE SET
            auto_research_at = COALESCE(EXCLUDED.auto_research_at, screener_find_pins.auto_research_at),
            discovery_reason = COALESCE(NULLIF(EXCLUDED.discovery_reason, ''), screener_find_pins.discovery_reason),
            strategy_type = COALESCE(EXCLUDED.strategy_type, screener_find_pins.strategy_type),
            brief_snippet = COALESCE(NULLIF(EXCLUDED.brief_snippet, ''), screener_find_pins.brief_snippet),
            cio_recommendation = EXCLUDED.cio_recommendation,
            active = EXCLUDED.active
    """,
        (sym, auto_research_at, (reason or "")[:500], strategy_type, (brief_snippet or "")[:800], cio or None, active),
        fetch="none",
    )
    return active


def _sync_all_screener_find_pins():
    _ensure_screener_find_pins_table()
    for r in _db_query("SELECT symbol FROM screener_find_pins") or []:
        _sync_screener_find_pin(r["symbol"])


def _screener_finds_candidates(query=None):
    """GET /api/v2/screener-finds/candidates — auto-research screener finds with buy-side CIO cards."""
    _sync_all_screener_find_pins()
    pins = (
        _db_query("""
        SELECT symbol, pinned_at, auto_research_at, discovery_reason, strategy_type,
               brief_snippet, cio_recommendation, active
        FROM screener_find_pins
        WHERE active = true
        ORDER BY auto_research_at DESC NULLS LAST, pinned_at DESC
    """)
        or []
    )
    syms = [p["symbol"] for p in pins]
    items_out = []
    if syms:
        wl = _wl_items({"symbols": ",".join(syms)})
        items_out = wl.get("items") or []
        sym_order = {s: i for i, s in enumerate(syms)}
        items_out.sort(key=lambda x: sym_order.get(x.get("symbol"), 999))
    return _json_clean(
        {
            "ok": True,
            "count": len(pins),
            "candidates": pins,
            "items": items_out,
            "buy_side_only": True,
            "retention": "Active while CIO is BUY, STRONG_BUY, ADD, or ADD_ON_PULLBACK",
            # Watch Desk v3 (D1): the CIO-qualified lane is structurally thin — widen the
            # tab to ALL screener+discovery finds with the CIO subset highlighted, and
            # give the tab its WS-A track record so it justifies existing
            "wide_finds": _wide_finds_payload(),
            "track_record": _finds_track_record(),
        }
    )


_WQG_CACHE = {"ts": 0.0, "cfg": None, "low": None, "per_source": None}


def _watch_quality_gate():
    """Watch Desk v4 (WS-D): per-source rolling efficacy from watch_candidate_events.
    Returns (low_efficacy_sources: set, per_source: list). Cached 1h — the underlying
    ledger only moves on the Sunday reconciler. Visibility throttle only, no blocking;
    the label lifts automatically when the rolling median α recovers above the floor.
    NOTE (Engine Room WS-4 hook): the Hermes backlog drain can read the same per-source
    table to deprioritize research on low-efficacy discovery lanes — same corpus, one truth."""
    import time as _t

    if _WQG_CACHE["low"] is not None and _t.time() - _WQG_CACHE["ts"] < 3600:
        return _WQG_CACHE["low"], _WQG_CACHE["per_source"]
    cfg = {"alpha_floor_pct": -2.0, "min_n": 30, "window_days": 90}
    try:
        import json as _j

        cfg.update(
            {
                k: v
                for k, v in _j.loads((PROJECT_ROOT / "config" / "watch_quality_gate.json").read_text()).items()
                if isinstance(v, (int, float))
            }
        )
    except Exception:
        pass
    per_source, low = [], set()
    try:
        rows = (
            _db_query(
                """SELECT source_type,
                                   count(*) AS emitted,
                                   count(*) FILTER (WHERE alpha_21d IS NOT NULL) AS n,
                                   round((percentile_cont(0.5) WITHIN GROUP (ORDER BY alpha_21d)
                                     FILTER (WHERE alpha_21d IS NOT NULL))::numeric, 2) AS alpha_21d_median,
                                   round((percentile_cont(0.5) WITHIN GROUP (ORDER BY alpha_21d)
                                     FILTER (WHERE alpha_21d IS NOT NULL AND proposed))::numeric, 2) AS converted_alpha_21d,
                                   count(*) FILTER (WHERE proposed) AS converted
                            FROM watch_candidate_events
                            WHERE emitted_on > CURRENT_DATE - %s
                            GROUP BY source_type ORDER BY source_type""",
                (int(cfg["window_days"]),),
            )
            or []
        )
        for r in rows:
            rec = {k: _json_clean(v) for k, v in r.items()}
            rec["low_efficacy"] = bool(
                (rec.get("n") or 0) >= cfg["min_n"]
                and rec.get("alpha_21d_median") is not None
                and float(rec["alpha_21d_median"]) < float(cfg["alpha_floor_pct"])
            )
            if rec["low_efficacy"]:
                low.add(rec["source_type"])
            per_source.append(rec)
    except Exception:
        pass
    _WQG_CACHE.update({"ts": _t.time(), "cfg": cfg, "low": low, "per_source": per_source})
    return low, per_source


def _wide_finds_payload():
    """All screener_find + ai_discovered emissions (90d), newest first, for the
    widened Finds band (CIO-qualified subset renders separately above).
    v4 (WS-D): rows from low-efficacy sources carry low_efficacy_source=True —
    the UI folds them into a collapsed band; nothing is blocked or deleted."""
    try:
        low, _ = _watch_quality_gate()
        rows = (
            _db_query("""SELECT source_type, symbol, emitted_on, anchor_price, alpha_21d, verdict, proposed
                            FROM watch_candidate_events
                            WHERE source_type IN ('screener_find','ai_discovered')
                              AND emitted_on > CURRENT_DATE - 90
                            ORDER BY emitted_on DESC LIMIT 120""")
            or []
        )
        return [
            {**{k: _json_clean(v) for k, v in r.items()}, "low_efficacy_source": r.get("source_type") in low}
            for r in rows
        ]
    except Exception:
        return []


def _finds_track_record():
    """WS-A header stats + v4 WS-D converted-α breakdown: 'all emissions α' vs
    'converted-to-proposal α' vs per-source α with n — the number that decides how
    damning the headline −4.82% actually is (funnel-top noise vs converted underperformance)."""
    try:
        r = (
            _db_query(
                """SELECT count(*) AS n,
                                count(*) FILTER (WHERE alpha_21d IS NOT NULL) AS scored,
                                round((percentile_cont(0.5) WITHIN GROUP (ORDER BY alpha_21d)
                                  FILTER (WHERE alpha_21d IS NOT NULL))::numeric, 2) AS median_alpha_21d,
                                round((percentile_cont(0.5) WITHIN GROUP (ORDER BY alpha_21d)
                                  FILTER (WHERE alpha_21d IS NOT NULL AND proposed))::numeric, 2) AS converted_alpha_21d,
                                count(*) FILTER (WHERE proposed AND alpha_21d IS NOT NULL) AS converted_scored,
                                count(*) FILTER (WHERE proposed) AS converted
                         FROM watch_candidate_events
                         WHERE source_type IN ('screener_find','ai_discovered')
                           AND emitted_on > CURRENT_DATE - 90""",
                fetch="one",
            )
            or {}
        )
        out = {k: _json_clean(v) for k, v in r.items()}
        low, per_source = _watch_quality_gate()
        out["per_source"] = per_source
        out["low_efficacy_sources"] = sorted(low)
        try:
            cfg = _WQG_CACHE.get("cfg") or {}
            out["gate"] = {
                "alpha_floor_pct": cfg.get("alpha_floor_pct"),
                "min_n": cfg.get("min_n"),
                "note": "visibility throttle only — label lifts when rolling α recovers",
            }
        except Exception:
            pass
        return out
    except Exception:
        return {}


def _wl_items(query: dict = None):
    """GET /api/v2/watchlist/items — DB-backed watchlist items with filters."""
    q = query or {}
    _ensure_screener_find_pins_table()
    # NOTE: this SELECT joins several tables that also have source/status/asset_type columns
    # (watchlist_symbol_master, strategy cards, …) — filter columns MUST be qualified with wi.,
    # else Postgres raises "column reference ... is ambiguous" and the whole list silently returns 0.
    conditions = ["wi.status <> 'removed'"]
    params = []
    _sym_lookup = None
    _sym_list = None
    _lane = str((q.get("lane") or [""])[0] if isinstance(q.get("lane"), list) else (q.get("lane") or "")).strip()
    if _lane == "screener_finds":
        _ensure_screener_find_pins_table()
        _sync_all_screener_find_pins()
        _sym_list = [
            r["symbol"]
            for r in (
                _db_query(
                    "SELECT symbol FROM screener_find_pins WHERE active = true ORDER BY auto_research_at DESC NULLS LAST"
                )
                or []
            )
        ]
    elif q.get("symbols"):
        raw = q["symbols"][0] if isinstance(q["symbols"], list) else q["symbols"]
        _sym_list = [s.strip().upper() for s in str(raw or "").split(",") if s.strip()]
    if _sym_list is not None:
        if not _sym_list:
            return {"count": 0, "items": []}
        conditions.append("upper(wi.symbol) = ANY(%s)")
        params.append(_sym_list)
    elif q.get("symbol"):
        _sym_lookup = str(q["symbol"][0] if isinstance(q["symbol"], list) else q["symbol"]).strip().upper()
        if _sym_lookup:
            conditions.append("upper(wi.symbol) = %s")
            params.append(_sym_lookup)
    if q.get("source"):
        conditions.append("wi.source = %s")
        params.append(q["source"][0] if isinstance(q["source"], list) else q["source"])
    if q.get("bucket"):
        conditions.append("wi.bucket = %s")
        params.append(q["bucket"][0] if isinstance(q["bucket"], list) else q["bucket"])
    if q.get("asset_type"):
        conditions.append("wi.asset_type = %s")
        params.append(q["asset_type"][0] if isinstance(q["asset_type"], list) else q["asset_type"])
    if q.get("status"):
        conditions = [c for c in conditions if "status" not in c]
        conditions.append("wi.status = %s")
        params.append(q["status"][0] if isinstance(q["status"], list) else q["status"])
    if q.get("cio"):
        # server-side CIO-view filter (operator 2026-07-06): the page's client-side filter only sees
        # the loaded window, so verdicts on names ranked below the load size (219 of 222
        # ADD_ON_PULLBACK) were unfindable. Matches research-card rec OR CIO synthesis verdict —
        # same fields as the client filter. Applied inside `picked` so it narrows BEFORE the LIMIT.
        _cio = str(q["cio"][0] if isinstance(q["cio"], list) else q["cio"]).strip()
        _groups = {
            "buy_side": ["BUY", "STRONG_BUY", "ADD", "ADD_ON_PULLBACK"],
            "avoid_side": ["AVOID", "IGNORE", "SELL", "TRIM"],
        }
        if _cio == "none":
            conditions.append("""(NOT EXISTS (SELECT 1 FROM watchlist_research_cards rc
                                    WHERE rc.symbol = wi.symbol AND COALESCE(rc.latest_recommendation,'') <> '')
                                  AND NOT EXISTS (SELECT 1 FROM watchlist_final_synthesis fs
                                    WHERE upper(fs.symbol) = upper(wi.symbol) AND COALESCE(fs.recommendation,'') <> ''))""")
        else:
            _vals = _groups.get(_cio, [_cio.upper()])
            conditions.append("""(EXISTS (SELECT 1 FROM watchlist_research_cards rc
                                    WHERE rc.symbol = wi.symbol AND upper(rc.latest_recommendation) = ANY(%s))
                                  OR EXISTS (SELECT 1 FROM watchlist_final_synthesis fs
                                    WHERE upper(fs.symbol) = upper(wi.symbol) AND upper(fs.recommendation) = ANY(%s)))""")
            params.extend([_vals, _vals])
    where = " AND ".join(conditions)
    sort = "updated_at DESC"
    sort_p = "p.updated_at DESC"
    if q.get("sort"):
        s = q["sort"][0] if isinstance(q["sort"], list) else q["sort"]
        sort_map = {
            "score": "score DESC NULLS LAST",
            "symbol": "symbol",
            "updated": "updated_at DESC",
            "hermes": "hermes_rank ASC NULLS LAST, hermes_composite_score DESC NULLS LAST",
        }
        # p.-qualified twin used in the enrichment step (where `symbol`/`updated_at`/etc. would otherwise be
        # ambiguous against the joined tables). Must stay in lock-step with sort_map above.
        sort_map_p = {
            "score": "p.score DESC NULLS LAST",
            "symbol": "p.symbol",
            "updated": "p.updated_at DESC",
            "hermes": "p.hermes_rank ASC NULLS LAST, p.hermes_composite_score DESC NULLS LAST",
        }
        sort = sort_map.get(s, sort)
        sort_p = sort_map_p.get(s, sort_p)

    # Two-step so enrichment runs for ONLY the 200 returned symbols, not the whole ~4.4k-name non-removed
    # universe. The old single-pass shape enriched every row THEN applied LIMIT 200 — the planner can't push
    # the limit down through DISTINCT ON + the multi-key display sort → it hash-joins the full strategy/
    # research/synthesis/maturity tables (~17s on the request path). Step 1 (`picked`) is a cheap
    # base-table-only dedup + display sort + LIMIT 200 (~0.3s). Every dedup/sort column (symbol, status,
    # source, first_seen_at, in_directive_watch, updated_at, score, hermes_rank, hermes_composite_score)
    # lives on watchlist_items, so nothing enrichment-derived is needed to pick the window.
    #
    # picked is MATERIALIZED (a hard optimization barrier) and ALL enrichment is LEFT JOIN LATERAL, NOT plain
    # LEFT JOIN. This is deliberate and load-bearing: with plain LEFT JOINs the PG17 planner *still* rebuilds
    # the enrichment over the full 4.4k universe via hash joins and joins the result to picked (measured 8s,
    # and raising join_collapse_limit does NOT fix it). LATERAL forces a per-row index lookup driven by the
    # 200 picked rows → ~0.4s. Every enrichment table is 1:1 on symbol (symbol is the pkey), so LIMIT 1 is
    # exact. Reversible (pure query shape); identical output schema + row set + order to the old query.
    #
    # DISTINCT ON (symbol) — one row per symbol (the watchlist is seeded from multiple discovery sources, so a
    # symbol can have several rows). Keep the best row: directive-linked first, then operator-seeded, then the
    # oldest. Filter columns MUST stay qualified with wi. (see note above).
    rows = (
        _db_query(
            f"""
        WITH picked AS MATERIALIZED (
            SELECT * FROM (
                SELECT DISTINCT ON (wi.symbol) wi.*,
                       EXISTS (SELECT 1 FROM operator_starred_symbols s
                               WHERE upper(s.symbol) = upper(wi.symbol)) AS starred,
                       EXISTS (SELECT 1 FROM screener_find_pins sfp
                               WHERE upper(sfp.symbol) = upper(wi.symbol) AND sfp.active = true) AS screener_pinned
                FROM watchlist_items wi
                WHERE {where}
                ORDER BY wi.symbol,
                         (COALESCE(wi.in_directive_watch, false) = false),
                         (wi.source = 'personal_watchlist') DESC,
                         wi.first_seen_at ASC
            ) dedup
            ORDER BY (NOT starred),          -- operator-starred always make the top-200 window + sort first
                     (NOT screener_pinned),   -- buy-side screener finds stay in the top-200 window
                     (COALESCE(in_directive_watch, false) = false),
                     (status <> 'active'),   -- active names always make the top-200 window (e.g. CURR)
                     {sort} LIMIT {len(_sym_list) if _sym_list else (1 if _sym_lookup else 200)}
        )
        SELECT p.*,
               -- ── ONE PRICE PER CARD (2026-07-20) ────────────────────────────
               -- The BETA card showed $19.09 in its header and "current $19.83"
               -- in the Fib block at the same moment — 4 pct apart on one card.
               -- (No literal percent sign anywhere in this SQL: psycopg2 reads it
               -- as a parameter placeholder and the execute dies with an
               -- IndexError. Caught here the same day a test was added for the
               -- identical mistake in watchlist_entry_planner.)
               -- The header served watchlist_items.price, a cached enrichment
               -- snapshot written by a cron (13:42), while the Fib panel derived
               -- its price from the latest OHLC bar. Every percentage in the
               -- header — today's change, distance to stop, distance to target —
               -- was computed off the stale one.
               --
               -- market_quotes is the live source and was 48 minutes fresher than
               -- the enrichment at the time. Overlay it when it is genuinely
               -- newer; keep the enrichment value when it is not, so a stalled
               -- quote feed cannot make the card go backwards.
               --
               -- price_as_of and price_source travel WITH the number: a price
               -- with no timestamp cannot be judged stale by anything
               -- downstream, which is how the divergence survived.
               CASE WHEN mq.price IS NOT NULL
                         AND (p.last_enriched_at IS NULL OR mq.fetched_at > p.last_enriched_at)
                    THEN mq.price ELSE p.price END AS price,
               CASE WHEN mq.price IS NOT NULL
                         AND (p.last_enriched_at IS NULL OR mq.fetched_at > p.last_enriched_at)
                    THEN mq.fetched_at ELSE p.last_enriched_at END AS price_as_of,
               CASE WHEN mq.price IS NOT NULL
                         AND (p.last_enriched_at IS NULL OR mq.fetched_at > p.last_enriched_at)
                    THEN 'market_quotes' ELSE 'enrichment' END AS price_source,
               p.price AS price_enriched,
               mq.price AS price_live,
               -- PRIMARY DECISION SURFACE (2026-07-21): the latest live shadow
               -- decision packet, attached inline so the card renders the
               -- multidimensional summary as its LEAD without firing a
               -- per-card /packet request. Null for symbols not yet analysed —
               -- the card falls back to the legacy verdict band, no regression.
               dpk.packet AS decision_packet,
               dpk.generated_at AS decision_packet_at,
               sc.strategy_type, sc.latest_price, sc.support, sc.resistance,
               sc.ideal_entry, sc.stop_loss, sc.target_price, sc.risk_reward,
               sc.confidence as strategy_confidence, sc.account_fit,
               sc.technical_summary, sc.needs_iteration as strategy_needs_iteration,
               rc.latest_summary as research_summary, rc.latest_recommendation,
               rc.confidence as research_confidence,
               am.analysis_stage, am.maria_status, am.steph_status,
               am.risk_status, am.tax_status, am.full_chain_status,
               am.final_synthesis_status, am.required_agents, am.completed_agents,
               am.needs_iteration as maturity_needs_iteration,
               am.decision_quality_status, am.actionable as decision_actionable,
               sm.in_portfolio,
               ep.setup_type AS entry_setup, ep.entry_zone_low, ep.entry_zone_high,
               ep.limit_price AS entry_limit, ep.stop_price AS entry_stop,
               ep.target_price AS entry_target, ep.risk_reward AS entry_rr,
               ep.urgency AS entry_urgency, ep.proposal_tag AS entry_tag,
               ep.confidence AS entry_confidence, ep.created_at AS entry_planned_at,
               ep.model_used AS entry_model, ep.price_at_plan AS entry_price_at_plan,
               fs.recommendation AS synthesis_recommendation,
               fs.grok_recommendation, fs.chatgpt_recommendation, fs.models_agree,
               fs.decision_safety, fs.actionable AS synthesis_actionable,
               fs.model_used AS cio_model_used,
               fs.dual_consensus_json, fs.synthesis_narrative, fs.conflicts, fs.unresolved,
               fs.updated_at AS synthesis_updated_at,
               sp.sector AS profile_sector, sp.industry AS profile_industry,
               sp.instrument_type AS instrument_type,
               sp.expense_ratio AS expense_ratio,
               sp.analyst_look_through_pct AS analyst_look_through_pct,
               sp.ytd_return_pct AS ytd_return_pct,
               sp.dividend_yield_pct AS dividend_yield_pct,
               sp.ttm_dividend AS ttm_dividend,
               sp.description_1s AS profile_description,
               sp.next_earnings_date AS next_earnings_date,
               cat.catalyst_type, cat.headline AS catalyst_headline,
               cat.impact_score AS catalyst_impact, cat.severity AS catalyst_severity,
               cat.ts AS catalyst_at, cat.source_url AS catalyst_url,
               (SELECT string_agg(DISTINCT wd.label, ' · ' ORDER BY wd.label)
                FROM watch_directives wd
                WHERE wd.kind='ticker' AND upper(wd.spec->>'symbol')=upper(p.symbol)
                  AND wd.label IS NOT NULL AND wd.label <> upper(p.symbol)) AS watch_lists
        FROM picked p
        -- Plain equality, NOT upper(t.symbol) = upper(p.symbol). market_quotes has
        -- 3.4M rows and an index on (symbol, fetched_at DESC); wrapping either side
        -- in upper() makes it unusable and this endpoint took 142 SECONDS. Both
        -- tables are verified all-uppercase (0 mixed-case rows in either), so the
        -- functions bought nothing and cost everything. (2026-07-20)
        LEFT JOIN LATERAL (SELECT t.price, t.fetched_at FROM market_quotes t
                           WHERE t.symbol = p.symbol
                           ORDER BY t.fetched_at DESC LIMIT 1) mq ON true
        LEFT JOIN LATERAL (SELECT dpp.packet, dpp.generated_at FROM decision_packets dpp
                           WHERE upper(dpp.symbol) = upper(p.symbol)
                             AND dpp.superseded_by IS NULL
                           ORDER BY dpp.generated_at DESC LIMIT 1) dpk ON true
        LEFT JOIN LATERAL (SELECT * FROM watchlist_strategy_cards t WHERE t.symbol = p.symbol LIMIT 1) sc ON true
        LEFT JOIN LATERAL (SELECT * FROM watchlist_research_cards t WHERE t.symbol = p.symbol LIMIT 1) rc ON true
        -- failed-LLM artifacts ("LLM error: …") never surface as CIO notes (purged 2026-07-03; guard in run_synthesis)
        LEFT JOIN LATERAL (SELECT * FROM watchlist_final_synthesis t WHERE t.symbol = p.symbol
                           AND (t.synthesis_narrative IS NULL OR t.synthesis_narrative NOT ILIKE 'LLM error:%%') LIMIT 1) fs ON true
        LEFT JOIN LATERAL (SELECT * FROM watchlist_analysis_maturity t WHERE t.symbol = p.symbol LIMIT 1) am ON true
        LEFT JOIN LATERAL (SELECT * FROM watchlist_symbol_master t WHERE t.symbol = p.symbol LIMIT 1) sm ON true
        LEFT JOIN LATERAL (SELECT * FROM symbol_profiles t WHERE upper(t.symbol) = upper(p.symbol) LIMIT 1) sp ON true
        LEFT JOIN LATERAL (
            SELECT catalyst_type, headline, severity, impact_score, source_url,
                   COALESCE(published_at, created_at) AS ts
            FROM catalyst_events ce
            WHERE upper(ce.symbol) = upper(p.symbol) AND ce.catalyst_type <> 'other'
              AND COALESCE(ce.published_at, ce.created_at) > now() - interval '45 days'
            ORDER BY COALESCE(ce.published_at, ce.created_at) DESC LIMIT 1) cat ON true
        LEFT JOIN LATERAL (
            SELECT setup_type, entry_zone_low, entry_zone_high, limit_price, stop_price,
                   target_price, risk_reward, urgency, proposal_tag, confidence, created_at, model_used,
                   price_at_plan
            FROM watchlist_entry_plans wep WHERE wep.symbol = p.symbol
            ORDER BY created_at DESC, id DESC LIMIT 1) ep ON true
        ORDER BY (NOT p.starred),           -- operator-starred first
                 (NOT COALESCE(p.screener_pinned, false)),
                 (COALESCE(p.in_directive_watch, false) = false),
                 (p.status <> 'active'),
                 {sort_p}
    """,
            params,
        )
        or []
    )
    _items = [{k: _json_clean(v) for k, v in r.items()} for r in rows]
    for _it in _items:
        # HQ country for the card flag (frontend lib/country.ts). symbol_profiles has no
        # country column, so resolve from the Finviz enrichment cache (with ADR handling
        # done client-side by symbol).
        _it["country_name"] = _resolve_country_name(_it.get("symbol"), _it.get("country_name"))
        _dcj = _it.get("dual_consensus_json")
        if isinstance(_dcj, str):
            try:
                _dcj = json.loads(_dcj)
            except Exception:
                _dcj = {}
        _ep = _evidence_packet(_dcj if isinstance(_dcj, dict) else {})
        _it["synthesis_evidence"] = _ep.get("evidence") or []
        _it["synthesis_data_i_doubt"] = _ep.get("data_i_doubt") or "none"
        _it["synthesis_agent_contract"] = _ep.get("agent_contract")
        if _it.get("synthesis_narrative"):
            _it["synthesis_narrative_snip"] = str(_it["synthesis_narrative"])[:280]
        if _it.get("conflicts") and isinstance(_it["conflicts"], list) and _it["conflicts"]:
            _it["synthesis_conflicts_snip"] = "; ".join(str(c) for c in _it["conflicts"][:2])[:200]
        # Drop mis-tagged catalysts (e.g. Pasqal article on MRLN via Yahoo RSS).
        try:
            from news_symbol_guard import headline_matches_symbol

            _ch = _it.get("catalyst_headline")
            if _ch:
                _ok, _ = headline_matches_symbol(
                    _it.get("symbol") or "",
                    str(_ch),
                    company_description=_it.get("profile_description"),
                )
                if not _ok:
                    for _k in (
                        "catalyst_headline",
                        "catalyst_at",
                        "catalyst_url",
                        "catalyst_type",
                        "catalyst_impact",
                        "catalyst_severity",
                    ):
                        _it.pop(_k, None)
            if not _it.get("catalyst_headline"):
                _ln = _db_query(
                    """SELECT title, published_at, source_url FROM news_articles
                       WHERE symbol=%s ORDER BY published_at DESC NULLS LAST LIMIT 1""",
                    (_it.get("symbol"),),
                    fetch="one",
                )
                if _ln:
                    _okn, _ = headline_matches_symbol(
                        _it.get("symbol") or "",
                        str(_ln.get("title") or ""),
                        company_description=_it.get("profile_description"),
                    )
                    if _okn:
                        _it["catalyst_headline"] = _ln.get("title")
                        _it["catalyst_at"] = _ln.get("published_at")
                        _it["catalyst_url"] = _ln.get("source_url")
                        _it["catalyst_type"] = "news_headline"
        except Exception:
            pass
    # Flag PRIVATE / non-tradeable names (genuinely private only — kept current vs IPOs). reload so registry
    # edits go live without a full restart.
    try:
        import importlib, private_symbols as _ps

        importlib.reload(_ps)
        for _it in _items:
            _info = _ps.private_info(_it.get("symbol", ""))
            if _info:
                _it["private_nontradeable"] = True
                _it["private_company"] = _info["company"]
                _it["private_note"] = _info["note"]
    except Exception:
        pass
    try:
        import sys as _sys_wv

        _sys_wv.path.insert(0, str(PROJECT_ROOT / "scripts" / "lib"))
        from watchlist_volatility import attach_atr20_batch, plan_volatility_fields as _pvol

        _plan_n = sum(1 for _it in _items if _it.get("entry_stop"))
        _atr_cap = min(60, max(_plan_n, 15), len(_items))
        attach_atr20_batch(_items, max_fetch=_atr_cap)
        for _it in _items:
            _ec = (_enrich_cache() or {}).get(str(_it.get("symbol") or "").upper()) or {}
            _px = _it.get("price") or _it.get("latest_price")
            _it.update(
                _pvol(
                    entry_limit=_it.get("entry_limit"),
                    entry_stop=_it.get("entry_stop"),
                    price=_px,
                    atr_14=_ec.get("atr"),
                    atr_20=_it.get("atr_20"),
                    atr_20_pct=_it.get("atr_20_pct"),
                )
            )
    except Exception:
        pass
    # Watch Desk v3 (WS-C): deterministic setup_context per row — REUSES the
    # existing _hermes_setup(rsi, trend) spec-§8 classifier (extraction, not
    # duplication). Labeled context, NOT a quality score; the sample-gated
    # setup_quality_prior stays untouched.
    for _it in _items:
        try:
            _sc = _hermes_setup(_it.get("rsi"), _it.get("trend"))
            _rv = _it.get("rvol")
            _glyphs = []
            _tr = (_it.get("trend") or "").lower()
            _glyphs.append("▲" if _tr == "bullish" else "▼" if _tr == "bearish" else "◆")
            _r = _it.get("rsi")
            _glyphs.append(
                "R↓" if (_r is not None and float(_r) < 40) else "R↑" if (_r is not None and float(_r) > 65) else "R·"
            )
            if _rv is not None:
                _glyphs.append("V↑" if float(_rv) >= 2 else "V·")
            _it["setup_context"] = {
                "glyphs": " ".join(_glyphs),
                "type": _sc.get("type"),
                "hint": _sc.get("why"),
                "conviction": _sc.get("conviction"),
                "label": "deterministic context — not a quality score",
            }
        except Exception:
            continue

    # Watch Desk v3 (D3): list payload trim — narrative/CIO-evidence blobs move
    # behind ?full=1 (the detail drawer refetches); list keeps snips only
    if not (query or {}).get("full"):
        # Conservative cut: snips remain for everything dropped. v4 (B4) widened per a
        # render census of the LOCKED Card v4 family: hermes_score_components is KEPT
        # (card reads it); dual_consensus_json / synthesis_conflicts_snip / trigger_source /
        # origin_detail / provenance_reason / technical_summary are rendered ONLY by the
        # ToS desk diligence view, which now requests ?full=1.
        _HEAVY = (
            "synthesis_narrative",
            "profile_description",
            "conflicts",
            "research_summary",
            "unresolved",
            "synthesis_evidence",
            "dual_consensus_json",
            "synthesis_conflicts_snip",
            "trigger_source",
            "origin_detail",
            "provenance_reason",
            "technical_summary",
            "holdings_llm_summary",
        )
        for _it in _items:
            for _k in _HEAVY:
                _it.pop(_k, None)

    # Watch Desk v2 (A2/C3): facet counts computed over the SAME corpus the rows
    # come from (RI v3.0 lesson — one corpus), plus the honest denominator.
    # setup_advisory is FREE TEXT ("RSI 46 · band 40-55") written by the
    # enrichment pipeline / setup_quality_prior — not a favorable/caution enum.
    _facets: dict = {}
    for _it in _items:
        _sa = str(_it.get("setup_advisory") or "").strip()
        if not _sa:
            _key = "(unset)"
        elif "awaiting enrichment" in _sa:
            _key = "awaiting enrichment"
        elif "band" in _sa:
            _key = "band " + _sa.split("band", 1)[1].strip()
        else:
            _key = _sa[:40]
        _facets[_key] = _facets.get(_key, 0) + 1
    try:
        _uni = (
            _db_query("SELECT count(*) AS n FROM watchlist_items WHERE status IN ('active','researched')", fetch="one")
            or {}
        )
        _universe_n = _uni.get("n")
    except Exception:
        _universe_n = None
    # CANONICAL ACTION POLICY (2026-07-21) — the ONE authority for action
    # eligibility, computed from the inline packet so the card renders exactly
    # what the API decides (no cioAvoid drift). Symbols without a valid packet get
    # action_policy=None; the card falls back to legacy behaviour behind a clearly
    # named flag ("LEGACY FALLBACK — PACKET REQUIRED"), defaulting to build/refresh.
    try:
        import decision_action_policy as _pol
        import decision_packet as _dp
        import packet_invalidation as _inv
        from db_adapter import _get_conn as _gc

        _conn = _gc()
        _open_props = set()
        try:
            _pr = (
                _db_query("""SELECT DISTINCT upper(symbol) AS s FROM options_approval_queue
                               WHERE status IN ('pending','approved')""")
                or []
            )
            _open_props = {r["s"] for r in _pr}
        except Exception:
            pass
        for _it in _items:
            _pkt = _it.get("decision_packet")
            if _pkt and isinstance(_pkt, dict):
                # Single egress gate — same materialize used by readback + action-policy.
                try:
                    _pkt = _dp.materialize_packet(_pkt)
                    _it["decision_packet"] = _pkt
                except Exception:
                    pass
                # Same current-input builder the standalone endpoint uses, so the
                # inline path never carries a weaker context than the endpoint.
                # V5 Section 11: 60s per-symbol cache — this ran per packet row on
                # EVERY list request (23 × several queries = the 4.4s worst case).
                try:
                    _snap = _v5_snapshot_cached(str(_it.get("symbol")), _conn, _inv)
                except Exception:
                    _snap = None
                _ap = _pol.evaluate_action(
                    _pkt,
                    packet_id=None,
                    generated_at=_it.get("decision_packet_at"),
                    existing_proposal=(str(_it.get("symbol") or "").upper() in _open_props),
                    current_snapshot=_snap,
                )
                _it["action_policy"] = _ap
                # Surface CURRENT VALIDITY separately from DATA AT BUILD.
                if _ap and "inputs_match" in _ap:
                    _pkt["current_validity"] = {
                        "state": (
                            "CURRENT"
                            if _ap.get("inputs_match")
                            else "STALE"
                            if _ap.get("state") == "STALE"
                            else "INVALIDATED"
                        ),
                        "packet_input_hash": _ap.get("packet_input_hash"),
                        "current_input_hash": _ap.get("current_input_hash"),
                        "invalidation_reasons": _ap.get("invalidation_reasons") or _ap.get("blocks") or [],
                    }
                    _it["decision_packet"] = _pkt
                # V6 universal gate: ONE server-side presentation object — header,
                # tiles, CTA, mechanics and verification all derive from it.
                try:
                    import operator_presentation as _opres

                    _pkt["operator_presentation"] = _opres.build(_pkt, _ap)
                except Exception as _ope:
                    _pkt["operator_presentation"] = {
                        "verification_state": "UNVERIFIED_LEGACY",
                        "display_current_mechanics": False,
                        "error": str(_ope)[:120],
                    }
                # V5 Section 11: LIST rows carry a presenter-sufficient TRIM, not the
                # full forensic packet (input_snapshot + raw lane outputs + blind
                # facts were ~70% of a 1.27MB list payload / 4.4s worst). The full
                # packet stays on /api/v2/watch/decision/latest for Details/Audit.
                _it["decision_packet"] = _trim_packet_for_list(_pkt)
            else:
                _it["action_policy"] = None
        # ROOT: in_portfolio from live holdings.json for every symbol — not the
        # potentially stale watchlist_symbol_master flag (HELD badge contradictions).
        try:
            _hpath = PROJECT_ROOT / "data" / "portfolios" / "state" / "holdings.json"
            _held = set()
            if _hpath.exists():
                _hd = json.loads(_hpath.read_text())
                for _h in _hd.get("holdings") or []:
                    if _h.get("is_cash"):
                        continue
                    _s = str(_h.get("symbol") or "").upper()
                    if not _s:
                        continue
                    if float(_h.get("quantity") or _h.get("shares") or 0) > 0 or float(_h.get("market_value") or 0) > 0:
                        _held.add(_s)
            for _it in _items:
                _sym = str(_it.get("symbol") or "").upper()
                _it["in_portfolio"] = _sym in _held
                # Packet ownership is authoritative for decision mechanics; when it
                # disagrees with live holdings, current_validity/invalidation handles it.
                # HELD badge uses in_portfolio (live holdings) only.
        except Exception:
            pass
    except Exception as _pe:
        for _it in _items:
            _it.setdefault("action_policy", None)

    # Canonical quote contract: shared CASE-bound selector for both Watch
    # surfaces. Fail-closed — never leave pre-overlay legacy price/change when
    # import/DB/compose fails (no silent pass that keeps legacy prices).
    try:
        from lib.watch_canonical_quote import apply_canonical_quote_overlay as _apply_cq

        _apply_cq(_items)
    except Exception as _cq_err:
        # Helper import/runtime broken — still fail closed, log type only.
        try:
            import logging as _logging

            _logging.getLogger("api_v2").warning("canonical_quote_overlay_failed type=%s", type(_cq_err).__name__)
        except Exception:
            pass
        for _it in _items:
            for _k in (
                "price",
                "change_pct",
                "price_as_of",
                "price_source",
                "quote_id",
                "source_record_id",
                "market_session",
                "winning_branch",
            ):
                _it[_k] = None
            _it["freshness_state"] = "DATA_UNAVAILABLE"
            _it["market_state"] = "DATA_UNAVAILABLE"
            _it["quote_missing"] = ["canonical_market_quote"]
            _it["quote_error_code"] = "CANONICAL_QUOTE_SELECTOR_FAILED"

    return {
        "count": len(_items),
        "items": _items,
        "facets": dict(sorted(_facets.items(), key=lambda x: -x[1])),
        "universe_count": _universe_n,
        "rank_name": "Hermes rank (composite score order)",
        "facet_note": (
            "setup_advisory is descriptive text from the enrichment pipeline "
            "(RSI band), not a favorable/advisory/caution rating engine"
        ),
    }


def _wl_summary():
    """GET /api/v2/watchlist/summary — counts by source and status."""
    by_source = (
        _db_query(
            "SELECT source, COUNT(DISTINCT symbol) as cnt FROM watchlist_items WHERE status <> 'removed' GROUP BY source"
        )
        or []
    )
    by_status = _db_query("SELECT status, COUNT(*) as cnt FROM watchlist_items GROUP BY status") or []
    jobs = _db_query("SELECT status, COUNT(*) as cnt FROM watchlist_agent_jobs GROUP BY status") or []
    cards = _db_query("SELECT COUNT(*) as cnt FROM watchlist_research_cards", fetch="one") or {}
    needs_iter = (
        _db_query("SELECT COUNT(*) as cnt FROM watchlist_research_cards WHERE needs_iteration = true", fetch="one")
        or {}
    )
    return {
        "by_source": {r["source"]: r["cnt"] for r in by_source},
        "by_status": {r["status"]: r["cnt"] for r in by_status},
        "jobs": {r["status"]: r["cnt"] for r in jobs},
        "total_active": sum(r["cnt"] for r in by_source),
        "research_cards": cards.get("cnt", 0),
        "needs_iteration": needs_iter.get("cnt", 0),
    }


def _wl_submit(body: dict):
    """POST /api/v2/watchlist/submit — submit symbols to agent for research."""
    symbols = body.get("symbols", [])
    agent = body.get("agent", "maria")
    request_type = body.get("request_type", "research")
    note = body.get("note", "")
    if not symbols:
        return 400, {"ok": False, "error": "symbols list required"}

    created = []
    for sym in symbols:
        job_id = f"wl-{sym.lower()}-{agent}-{datetime.now().strftime('%Y%m%d%H%M%S')}"
        ok = _db_write(
            """INSERT INTO watchlist_agent_jobs (id, symbol, requested_agent, request_type, note, status, payload)
               VALUES (%s, %s, %s, %s, %s, 'queued', %s)
               ON CONFLICT (id) DO NOTHING""",
            (job_id, sym, agent, request_type, note or None, json.dumps({"submitted_from": "api"})),
        )
        if ok:
            created.append(job_id)
            # Update item status
            _db_write(
                "UPDATE watchlist_items SET status='queued', updated_at=now() WHERE symbol=%s AND status='active'",
                (sym,),
            )
            # Event
            _db_write(
                "INSERT INTO watchlist_events (event_type, symbol, agent, status, message) VALUES ('submitted', %s, %s, 'queued', %s)",
                (sym, agent, f"Submitted to {agent} for {request_type}"),
            )

    return 200, {"ok": True, "created_jobs": created, "count": len(created)}


def _wl_requeue_symbol(sym: str) -> tuple[int, dict]:
    """Re-queue Maria → Steph → Risk → CIO synthesis for one watchlist symbol."""
    sym = (sym or "").strip().upper()
    if not sym or not sym.isalpha() or len(sym) > 5:
        return 400, {"ok": False, "error": "invalid symbol"}

    reset = _db_query(
        "UPDATE watchlist_agent_jobs SET status='queued', priority=-5, started_at=NULL, completed_at=NULL "
        "WHERE symbol=%s RETURNING id",
        (sym,),
        fetch="all",
    )
    n = len(reset or [])
    if n == 0:
        ts = datetime.now().strftime("%Y%m%d%H%M%S")
        for agent in ("maria", "steph", "risk_agent"):
            job_id = f"requeue-{sym.lower()}-{agent}-{ts}"
            _db_query(
                """INSERT INTO watchlist_agent_jobs
                   (id, symbol, requested_agent, request_type, note, status, priority, submitted_from)
                   VALUES (%s, %s, %s, 'full_analysis', %s, 'queued', -5, 'watchlist_requeue')
                   ON CONFLICT (id) DO NOTHING""",
                (job_id, sym, agent, f"Manual requeue {sym}"),
                fetch="none",
            )
            n += 1
    _db_query(
        "UPDATE watchlist_final_synthesis SET next_review_date=CURRENT_DATE "
        "WHERE symbol=%s AND COALESCE(superseded,false)=false",
        (sym,),
        fetch="none",
    )
    _db_query("UPDATE watchlist_research_cards SET needs_iteration=true WHERE symbol=%s", (sym,), fetch="none")
    _db_query(
        "UPDATE watchlist_analysis_maturity SET final_synthesis_status='pending' WHERE symbol=%s", (sym,), fetch="none"
    )
    return 200, {"ok": True, "symbol": sym, "requeued": n}


def _wl_cio_synthesis(sym: str, body: dict | None) -> tuple[int, dict]:
    """POST /api/v2/watchlist/<SYMBOL>/cio-synthesis — manual CIO synthesis on Grok and/or ChatGPT.

    Body: {"lanes": ["grok","chatgpt"], "dry_run": true} — dry_run returns full prompt + OAuth
    response without writing watchlist_final_synthesis."""
    sym = (sym or "").strip().upper()
    if not sym or not sym.isalpha() or len(sym) > 5:
        return 400, {"ok": False, "error": "invalid symbol"}
    dry_run = bool((body or {}).get("dry_run"))
    raw_lanes = (body or {}).get("lanes")
    lanes = None
    if isinstance(raw_lanes, list) and raw_lanes:
        lanes = tuple(str(x).strip().lower() for x in raw_lanes if str(x).strip().lower() in ("grok", "chatgpt"))
        if not lanes:
            return 400, {"ok": False, "error": "lanes must include grok and/or chatgpt"}
    try:
        import sys as _sys

        _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import process_watchlist_agent_jobs as _pwaj
        from lib.llm_consumption import ManualRequired as _ManualRequired

        conn = _pwaj._get_conn()
        try:
            result = _pwaj.run_synthesis(conn, sym, lanes=lanes, manual_trigger=True, dry_run=dry_run)
        finally:
            conn.close()
        if not result:
            return 500, {"ok": False, "error": "synthesis_failed", "symbol": sym}
        out = {**result, "advisory_only": True, "process_id": "watchlist_cio_synthesis"}
        if dry_run:
            out["persisted"] = False
        return 200, out
    except _ManualRequired as mr:
        return 200, {
            "ok": False,
            "manual_required": True,
            "process_id": mr.process_id,
            "lane": mr.lane,
            "task_summary": mr.task_summary,
            "symbol": sym,
        }
    except Exception as e:
        return 500, {"ok": False, "error": str(e)[:200], "symbol": sym}


def _wl_run_refresh_script(script: str, args: list[str], *, timeout: int = 120) -> dict:
    import subprocess

    venv_py = _project_python()
    _cwd = _scripts_cwd()
    try:
        proc = subprocess.run(
            [venv_py, str(_cwd / "scripts" / script), *args],
            capture_output=True,
            text=True,
            timeout=timeout,
            cwd=str(_cwd),
        )
        return {
            "ok": proc.returncode == 0,
            "exit_code": proc.returncode,
            "stdout_tail": (proc.stdout or "")[-300:],
            "stderr_tail": (proc.stderr or "")[-300:],
        }
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


_WL_CIO_REFRESH_GROUPS = {
    "buy_side": ["BUY", "STRONG_BUY", "ADD", "ADD_ON_PULLBACK"],
    "avoid_side": ["AVOID", "IGNORE", "SELL", "TRIM"],
}


def _wl_resolve_refresh_symbols(cio: str = "all_rated", limit: int = 10) -> list[str]:
    """Symbols to refresh for a CIO tier (buy, hold, avoid, pullback, all_rated, …)."""
    cio = (cio or "all_rated").strip()
    lim = max(1, min(int(limit or 10), 25))
    if cio in ("all", "all_rated"):
        import sys as _sys

        _sys.path.insert(0, str(PROJECT_ROOT / "scripts" / "lib"))
        from watchlist_priority import DAILY_PRIORITY_RATED_RECS  # noqa: E402

        rated = sorted(r.upper() for r in DAILY_PRIORITY_RATED_RECS)
        rows = (
            _db_query(
                """SELECT DISTINCT UPPER(wi.symbol) AS symbol, wi.hermes_rank
               FROM watchlist_items wi
               WHERE wi.status IN ('active','researched')
                 AND (
                   EXISTS (SELECT 1 FROM watchlist_research_cards rc
                           WHERE rc.symbol = wi.symbol
                             AND UPPER(REPLACE(REPLACE(rc.latest_recommendation,' ','_'),'-','_')) = ANY(%s))
                   OR EXISTS (SELECT 1 FROM watchlist_final_synthesis fs
                               WHERE upper(fs.symbol)=upper(wi.symbol)
                                 AND UPPER(REPLACE(REPLACE(fs.recommendation,' ','_'),'-','_')) = ANY(%s))
                 )
               ORDER BY wi.hermes_rank ASC NULLS LAST, symbol
               LIMIT %s""",
                (rated, rated, lim),
            )
            or []
        )
        return [str(r["symbol"]).upper() for r in rows if r.get("symbol")]
    _vals = _WL_CIO_REFRESH_GROUPS.get(cio, [cio.upper().replace(" ", "_")])
    rows = (
        _db_query(
            """SELECT DISTINCT UPPER(wi.symbol) AS symbol, wi.hermes_rank
           FROM watchlist_items wi
           WHERE wi.status IN ('active','researched')
             AND (
               EXISTS (SELECT 1 FROM watchlist_research_cards rc
                       WHERE rc.symbol = wi.symbol AND upper(rc.latest_recommendation) = ANY(%s))
               OR EXISTS (SELECT 1 FROM watchlist_final_synthesis fs
                           WHERE upper(fs.symbol)=upper(wi.symbol) AND upper(fs.recommendation) = ANY(%s))
             )
           ORDER BY wi.hermes_rank ASC NULLS LAST, symbol
           LIMIT %s""",
            (_vals, _vals, lim),
        )
        or []
    )
    return [str(r["symbol"]).upper() for r in rows if r.get("symbol")]


def _wl_refresh_batch(body: dict | None = None) -> tuple[int, dict]:
    """POST /api/v2/watchlist/refresh-batch — refresh news/catalyst/technicals for a CIO tier."""
    b = body or {}
    cio = str(b.get("cio") or "all_rated").strip()
    limit = max(1, min(int(b.get("limit") or 10), 25))
    raw_syms = b.get("symbols")
    if isinstance(raw_syms, list) and raw_syms:
        syms = [str(s).strip().upper() for s in raw_syms[:limit] if s]
    else:
        syms = _wl_resolve_refresh_symbols(cio, limit)

    if not syms:
        return 200, {"ok": True, "refreshed": 0, "cio": cio, "symbols": [], "note": "no symbols matched filter"}

    try:
        from db_adapter import get_connection
        from news_symbol_guard import purge_mismatched_watchlist

        conn = get_connection()
        purge_mismatched_watchlist(conn, symbols=syms, apply=True)
        conn.close()
    except Exception:
        pass

    results = []
    ok_n = 0
    for sym in syms:
        code, out = _wl_refresh_symbol(sym)
        entry = {"symbol": sym, "ok": code == 200 and out.get("ok", True), "status": code}
        if code != 200:
            entry["error"] = out.get("error") or out.get("message")
        results.append(entry)
        if entry["ok"]:
            ok_n += 1

    return 200, {
        "ok": ok_n > 0,
        "cio": cio,
        "requested": len(syms),
        "refreshed": ok_n,
        "results": results,
        "note": "Batch refresh: news + catalyst + technicals for all CIO verdict tiers (advisory-only).",
    }


_WL_REFRESH_LOCK = __import__("threading").Lock()
_WL_REFRESH_INFLIGHT: set[str] = set()


def _wl_refresh_symbol_async(sym: str) -> tuple[int, dict]:
    """Queue a heavy watchlist refresh off the request thread (news/catalyst/agents can run 10+ min)."""
    sym = (sym or "").strip().upper()
    if not sym:
        return 400, {"ok": False, "error": "symbol required"}
    with _WL_REFRESH_LOCK:
        if sym in _WL_REFRESH_INFLIGHT:
            return 200, {
                "ok": True,
                "symbol": sym,
                "queued": False,
                "already_running": True,
                "note": "Refresh already running for this symbol",
            }
        _WL_REFRESH_INFLIGHT.add(sym)

    def _run():
        try:
            _wl_refresh_symbol(sym)
        except Exception:
            pass
        finally:
            with _WL_REFRESH_LOCK:
                _WL_REFRESH_INFLIGHT.discard(sym)

    __import__("threading").Thread(target=_run, daemon=True).start()
    return 202, {
        "ok": True,
        "symbol": sym,
        "queued": True,
        "note": "Refresh queued in background — card updates in ~1–2 min; polls stay responsive",
    }


def _wl_refresh_symbol(sym: str) -> tuple[int, dict]:
    """Manual refresh: news/catalyst + technicals + analyst coverage + agent requeue."""
    sym = (sym or "").strip().upper()
    if not sym:
        return 400, {"ok": False, "error": "symbol required"}

    exists = _db_query(
        "SELECT 1 FROM watchlist_items WHERE symbol=%s AND status IN ('active','researched') LIMIT 1",
        (sym,),
        fetch="one",
    )
    if not exists:
        return 404, {"ok": False, "error": f"{sym} not on active watchlist"}

    steps: dict = {}

    try:
        from db_adapter import get_connection
        from news_symbol_guard import purge_mismatched_for_symbol

        conn = get_connection()
        steps["purge_mismatch"] = purge_mismatched_for_symbol(conn, sym, apply=True)
        conn.close()
    except Exception as e:
        steps["purge_mismatch"] = {"error": str(e)[:120]}

    steps["news"] = _wl_run_refresh_script("news_ingestion.py", ["--symbol", sym, "--json"], timeout=90)
    steps["catalyst"] = _wl_run_refresh_script(
        "news_to_catalyst.py",
        ["--symbol", sym, "--json"],
        timeout=120,
    )
    steps["analyst"] = _wl_run_refresh_script(
        "hermes_analyst_coverage.py",
        ["--symbols", sym, "--apply"],
        timeout=180,
    )
    try:
        import sys as _sys_px

        _sys_px.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from price_db_sync import sync_watchlist_prices

        steps["price_history"] = sync_watchlist_prices([sym])
    except Exception as e:
        steps["price_history"] = {"error": str(e)[:120]}
    steps["strategy_card"] = _wl_run_refresh_script(
        "materialize_watchlist_strategy_cards.py",
        ["--symbols", sym],
        timeout=90,
    )

    enriched_n = 0
    enrich_err = None
    try:
        import sys as _sys

        _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from watchlist_enrichment_sweep import enrich_symbols

        er = enrich_symbols([sym])
        enriched_n = int(er.get("enriched") or 0)
        steps["technicals"] = er
    except Exception as e:
        enrich_err = str(e)[:200]
        steps["technicals"] = {"error": enrich_err}

    try:
        import sys as _sys_atr

        _sys_atr.path.insert(0, str(PROJECT_ROOT / "scripts" / "lib"))
        from watchlist_volatility import refresh_atr20_symbol

        _px_row = (
            _db_query(
                "SELECT price, latest_price FROM watchlist_items WHERE symbol=%s LIMIT 1",
                (sym,),
                fetch="one",
            )
            or {}
        )
        _px = _px_row.get("price") or _px_row.get("latest_price")
        steps["atr20"] = refresh_atr20_symbol(sym, float(_px) if _px else None)
    except Exception as e:
        steps["atr20"] = {"error": str(e)[:120]}

    # Bump this symbol ahead of the agent backlog and kick the processor once.
    try:
        _db_write(
            """UPDATE watchlist_agent_jobs
               SET status='queued', priority=-5, started_at=NULL
               WHERE symbol=%s AND status IN ('pending','queued','processing')""",
            (sym,),
        )
        steps["agents_kick"] = _wl_run_refresh_script(
            "process_watchlist_agent_jobs.py",
            ["--limit", "3"],
            timeout=600,
        )
    except Exception as e:
        steps["agents_kick"] = {"error": str(e)[:120]}

    code, rq = _wl_requeue_symbol(sym)
    if code != 200:
        return code, rq

    out = {
        **rq,
        "enriched": enriched_n > 0,
        "enriched_rows": enriched_n,
        "refresh_steps": steps,
        "note": (
            "News + catalyst + technicals refreshed; analyst coverage + strategy card updated; "
            "agents prioritized (Maria → Steph → Risk → synthesis). Advisory-only."
        ),
    }
    if enrich_err:
        out["enrich_warning"] = enrich_err
    return 200, out


def _wl_propose_symbol(sym: str, body: dict | None = None) -> tuple[int, dict]:
    """POST /api/v2/watchlist/<SYMBOL>/propose — queue broker proposal from watchlist plan."""
    sym = (sym or "").strip().upper()
    if not sym:
        return 400, {"ok": False, "error": "symbol required"}

    b = body or {}
    row = _db_query(
        """SELECT entry_limit, entry_stop, entry_target, entry_rr
           FROM watchlist_items WHERE symbol=%s AND status IN ('active','researched') LIMIT 1""",
        (sym,),
        fetch="one",
    )
    if not row:
        return 404, {"ok": False, "error": f"{sym} not on active watchlist"}

    entry = float(b.get("entry") or row.get("entry_limit") or 0)
    stop = float(b.get("stop") or row.get("entry_stop") or 0)
    target = float(b.get("target") or row.get("entry_target") or 0)
    shares = int(b.get("shares") or 0)
    account = str(b.get("account") or os.environ.get("ENTRY_DESK_DEFAULT_ACCOUNT") or "").strip()
    risk_pct = float(b.get("risk_pct") or 1)
    confirm_over = bool(b.get("confirm_over_risk"))

    if not account:
        return 400, {"ok": False, "error": "account required"}
    if shares <= 0:
        return 400, {"ok": False, "error": "shares required"}
    if not (entry > 0 and stop > 0 and target > 0 and entry > stop and target > entry):
        return 400, {"ok": False, "error": "valid entry > stop and target > entry required"}

    # Advisory risk guard: size on available cash, not total equity.
    confirm_over_cash = bool(b.get("confirm_over_cash"))
    try:
        import account_policy as _ap

        equity, _ = _ap.equity_for_account(account)
        cash_base, _, _ = _ap.sizing_cash_base(account)
        cash_settled, _ = _ap.cash_for_account(account)
    except Exception:
        equity, cash_base, cash_settled = 0, None, None

    dollar_risk = abs(entry - stop) * shares
    investment = entry * shares
    deployable = cash_base if cash_base and cash_base > 0 else None

    if deployable and deployable > 0:
        pct_risk_cash = dollar_risk / deployable * 100
        if pct_risk_cash > 2.05 and not confirm_over:
            return 400, {
                "ok": False,
                "error": f"Risk {pct_risk_cash:.2f}% of available cash exceeds 2% cap — confirm or reduce shares",
                "pct_risk_cash": round(pct_risk_cash, 2),
            }
        if investment > deployable * 1.001 and not confirm_over_cash:
            return 400, {
                "ok": False,
                "error": (
                    f"Investment ${investment:,.0f} exceeds available cash "
                    f"${deployable:,.0f} — confirm or reduce shares"
                ),
                "investment": round(investment, 2),
                "cash_available": round(deployable, 2),
            }
    elif equity and equity > 0:
        pct_risk = dollar_risk / equity * 100
        if pct_risk > 2.05 and not confirm_over:
            return 400, {
                "ok": False,
                "error": f"Risk {pct_risk:.2f}% exceeds 2% cap — confirm override or reduce shares",
                "pct_risk": round(pct_risk, 2),
            }

    import entry_desk_ops as edo

    res = edo.promote_to_broker_queue(
        {
            "symbol": sym,
            "account": account,
            "shares": shares,
            "entry": entry,
            "stop": stop,
            "target": target,
            "source": b.get("source") or "watchlist_card",
        }
    )
    code = 200 if res.get("ok") else 400
    return code, res


_WL_PLAN_INFLIGHT: dict = {}  # symbol -> monotonic start ts; impatient re-clicks spawned 4 racing
# planner threads in 9s for FATN (2026-07-06), inserting 4 conflicting
# plans with a created_at tie — one click = one plan


def _wl_build_plan(sym: str) -> tuple[int, dict]:
    """POST /api/v2/watchlist/<SYMBOL>/plan — run entry planner for one symbol (async)."""
    sym = (sym or "").strip().upper()
    if not sym:
        return 400, {"ok": False, "error": "symbol required"}

    exists = _db_query(
        "SELECT 1 FROM watchlist_items WHERE symbol=%s AND status IN ('active','researched') LIMIT 1",
        (sym,),
        fetch="one",
    )
    if not exists:
        return 404, {"ok": False, "error": f"{sym} not on active watchlist"}

    import threading
    import time as _time

    started = _WL_PLAN_INFLIGHT.get(sym)
    if started and _time.monotonic() - started < 180:
        return 200, {
            "ok": True,
            "symbol": sym,
            "already_running": True,
            "message": f"Entry planner already running for {sym} — refresh card in ~1–2 min",
        }
    fresh = _db_query(
        "SELECT 1 FROM watchlist_entry_plans WHERE symbol=%s AND created_at > now() - interval '3 minutes' LIMIT 1",
        (sym,),
        fetch="one",
    )
    if fresh:
        return 200, {
            "ok": True,
            "symbol": sym,
            "already_planned": True,
            "message": f"{sym} was re-planned under 3 min ago — refresh the card to see it",
        }
    _WL_PLAN_INFLIGHT[sym] = _time.monotonic()

    def _run():
        try:
            import watchlist_entry_planner as wep

            wep.run(symbols=[sym], limit=1, alert=False)
        except Exception as e:
            log.warning(f"watchlist plan {sym} failed: {e}")
        finally:
            _WL_PLAN_INFLIGHT.pop(sym, None)

    threading.Thread(target=_run, daemon=True).start()
    return 200, {
        "ok": True,
        "symbol": sym,
        "message": f"Entry planner queued for {sym} — refresh card in ~1–2 min",
        "note": "Advisory-only — validates limit, stop, target, and R:R",
    }


