def _llm_oauth_lanes():
    """GET /api/v2/llm/oauth-lanes — health of the FREE OAuth LLM lanes (Grok :8645, ChatGPT codex :8646,
    Hermes/Nous portal) + the local gemma lane, for Command Center monitoring. Read-only probes (proxy
    /health + ollama tags); no API key, no paid call. Shared by rotation oversight + all Hermes tasks."""
    import time as _t, os as _os, json as _j

    try:
        import sys as _sys

        _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from lib.oauth_lane_status import all_lanes

        lanes = []
        for ln in all_lanes(include_local=True, use_cache=False):
            row = dict(ln)
            row["status"] = "ready" if row.get("ready") else row.get("status", "offline")
            lanes.append(row)
        # Hermes — Nous Portal OAuth (auth.json presence)
        _nous = False
        try:
            _aj = _j.loads(open(_os.path.expanduser("~/.hermes/auth.json")).read())
            _nous = any("nous" in k.lower() for k in (_aj.get("providers") or {}))
        except Exception:
            pass
        lanes.append(
            {
                "lane": "hermes",
                "label": "Hermes (Nous Portal OAuth)",
                "kind": "oauth_proxy",
                "port": 8645,
                "reachable": True,
                "authenticated": _nous,
                "ready": _nous,
                "token_expired": None,
                "status": "ready" if _nous else "not logged in",
                "billing": "free_oauth",
                "hint": None if _nous else "hermes portal login",
            }
        )
        # Append DeepSeek metered readiness (no secret names/values in payload).
        try:
            from lib.consumption_run_manual import deepseek_readiness_rows

            lanes.extend(deepseek_readiness_rows())
        except Exception as _ds_e:
            lanes.append(
                {
                    "lane": "deepseek-flash",
                    "label": "DeepSeek V4 Flash",
                    "kind": "metered_api",
                    "billing": "metered",
                    "ready": False,
                    "status": "offline",
                    "authenticated": False,
                    "hint": "Provider readiness probe unavailable",
                    "reason_code": "PROVIDER_PROBE_FAILED",
                }
            )
            lanes.append(
                {
                    "lane": "deepseek-v4-pro",
                    "label": "DeepSeek V4 Pro",
                    "kind": "metered_api",
                    "billing": "metered",
                    "ready": False,
                    "status": "offline",
                    "authenticated": False,
                    "hint": "Provider readiness probe unavailable",
                    "reason_code": "PROVIDER_PROBE_FAILED",
                }
            )
        _ready = sum(1 for ln in lanes if ln.get("status") == "ready" or ln.get("ready"))
        return {
            "ok": True,
            "advisory_only": True,
            "lanes": lanes,
            "ready_count": _ready,
            "total": len(lanes),
            "generated_at": _t.strftime("%Y-%m-%dT%H:%M:%S"),
            "note": "Free OAuth (Grok :8645, ChatGPT :8646) + DeepSeek metered API readiness. No secret values exposed.",
        }
    except Exception as e:
        return {"ok": False, "error": str(e)[:200], "lanes": []}


