def _symbol_timeline(symbol: str):
    """GET /api/v2/symbol/{symbol}/timeline — unified symbol timeline."""
    sym = symbol.upper()
    # Alert events
    alerts = (
        _db_query(
            """
        SELECT id, alert_type, severity, raw_text, price, stop_price, gap_pct,
               position_value, decision, data_quality_status, created_at
        FROM alert_events WHERE symbol = %s ORDER BY created_at DESC LIMIT 30
    """,
            (sym,),
        )
        or []
    )
    # Watchlist events
    wl_events = (
        _db_query(
            """
        SELECT event_type, agent, status, message, created_at
        FROM watchlist_events WHERE symbol = %s ORDER BY created_at DESC LIMIT 20
    """,
            (sym,),
        )
        or []
    )
    # Agent jobs
    jobs = (
        _db_query(
            """
        SELECT id, requested_agent, request_type, status, created_at, completed_at
        FROM watchlist_agent_jobs WHERE symbol = %s ORDER BY created_at DESC LIMIT 10
    """,
            (sym,),
        )
        or []
    )
    # Agent results
    results = (
        _db_query(
            """
        SELECT agent, recommendation, confidence, summary, created_at
        FROM watchlist_agent_results WHERE symbol = %s ORDER BY created_at DESC LIMIT 10
    """,
            (sym,),
        )
        or []
    )
    # Strategy card
    strategy = _db_query("SELECT * FROM watchlist_strategy_cards WHERE symbol = %s", (sym,), fetch="one")
    # Maturity
    maturity = _db_query(
        "SELECT analysis_stage, required_agents, completed_agents, needs_iteration FROM watchlist_analysis_maturity WHERE symbol = %s",
        (sym,),
        fetch="one",
    )
    # Synthesis
    synthesis = _db_query(
        "SELECT recommendation, confidence, action, conflicts, unresolved FROM watchlist_final_synthesis WHERE symbol = %s",
        (sym,),
        fetch="one",
    )
    # Data quality warnings
    dq_warnings = (
        _db_query(
            """
        SELECT alert_type, data_quality_status, raw_text, created_at
        FROM alert_events WHERE symbol = %s AND data_quality_status NOT IN ('valid', 'unknown')
        AND created_at > NOW() - INTERVAL '7 days'
        ORDER BY created_at DESC LIMIT 5
    """,
            (sym,),
        )
        or []
    )

    return {
        "symbol": sym,
        "alerts": [{k: _json_clean(v) for k, v in r.items()} for r in alerts],
        "watchlist_events": [{k: _json_clean(v) for k, v in r.items()} for r in wl_events],
        "jobs": [{k: _json_clean(v) for k, v in r.items()} for r in jobs],
        "results": [{k: _json_clean(v) for k, v in r.items()} for r in results],
        "strategy": {k: _json_clean(v) for k, v in strategy.items()} if strategy else None,
        "maturity": {k: _json_clean(v) for k, v in maturity.items()} if maturity else None,
        "synthesis": {k: _json_clean(v) for k, v in synthesis.items()} if synthesis else None,
        "data_quality_warnings": [{k: _json_clean(v) for k, v in r.items()} for r in dq_warnings],
    }


def _wl_symbols(query: dict = None):
    """GET /api/v2/watchlist/symbols — deduplicated symbol master (one row per symbol)."""
    q = query or {}
    conditions = []
    params = []

    # Source filter — filter by membership boolean
    src = q.get("source", [None])[0] if isinstance(q.get("source"), list) else q.get("source")
    if src == "candidates":
        conditions.append("(in_ai_watchlist = true OR in_personal_watchlist = true)")
        conditions.append("in_portfolio = false")
    elif src == "curated":
        conditions.append("(in_ai_watchlist = true OR in_personal_watchlist = true OR in_portfolio = true)")
    elif src == "portfolio":
        conditions.append("in_portfolio = true")
    elif src == "ai_discovered":
        conditions.append("in_ai_discovered = true")
    elif src == "ai_watchlist":
        conditions.append("in_ai_watchlist = true")
    elif src == "personal_watchlist":
        conditions.append("in_personal_watchlist = true")

    # Stage filter
    stage = q.get("stage", [None])[0] if isinstance(q.get("stage"), list) else q.get("stage")
    if stage:
        conditions.append("analysis_stage = %s")
        params.append(stage)

    # Strategy filter
    strategy = q.get("strategy", [None])[0] if isinstance(q.get("strategy"), list) else q.get("strategy")
    if strategy:
        conditions.append("strategy_type = %s")
        params.append(strategy)

    where = " WHERE " + " AND ".join(conditions) if conditions else ""

    sort_col = "updated_at DESC"
    s = (q.get("sort", ["updated"])[0] if isinstance(q.get("sort"), list) else q.get("sort")) or "updated"
    sort_map = {
        "score": "score DESC NULLS LAST",
        "symbol": "symbol",
        "updated": "updated_at DESC",
        "price": "latest_price DESC NULLS LAST",
        "rr": "risk_reward DESC NULLS LAST",
    }
    sort_col = sort_map.get(s, sort_col)

    rows = _db_query(f"SELECT * FROM watchlist_symbol_master{where} ORDER BY {sort_col} LIMIT 200", params) or []

    # Enrich with account-level holdings from JSON
    holdings = _load_json(STATE_DIR / "holdings.json") or {}
    acct_summaries = holdings.get("account_summaries", {})
    acct_display = {aid: info.get("display_name", aid) for aid, info in acct_summaries.items()}
    total_portfolio = sum(info.get("total_value", 0) for info in acct_summaries.values())

    holdings_by_sym = {}
    for h in holdings.get("holdings", []):
        sym = h.get("symbol")
        if sym:
            holdings_by_sym.setdefault(sym, []).append(h)

    items = []
    for r in rows:
        item = {k: _json_clean(v) for k, v in r.items()}
        sym = item.get("symbol")
        # Add account holdings
        sym_holdings = holdings_by_sym.get(sym, [])
        if sym_holdings:
            acct_detail = []
            total_shares = 0
            total_mv = 0
            for h in sym_holdings:
                aid = h.get("account_id") or h.get("account", "unknown")
                shares = float(h.get("shares", 0) or 0)
                mv = float(h.get("market_value", 0) or 0)
                total_shares += shares
                total_mv += mv
                acct_detail.append(
                    {
                        "account_id": aid,
                        "account_name": acct_display.get(aid, aid),
                        "account_type": h.get("account_type") or _infer_account_type(aid),
                        "shares": round(shares, 4),
                        "market_value": round(mv, 2),
                        "cost_basis": round(float(h.get("cost_basis", 0) or 0), 2) if h.get("cost_basis") else None,
                        "gain_loss": round(float(h.get("gain_loss", 0) or 0), 2)
                        if h.get("gain_loss") is not None
                        else None,
                        "gain_loss_pct": round(float(h.get("gain_loss_pct", 0) or 0), 2)
                        if h.get("gain_loss_pct") is not None
                        else None,
                        "weight_in_account": round(float(h.get("portfolio_pct", 0) or 0), 2),
                    }
                )
            item["account_holdings"] = acct_detail
            item["total_shares"] = round(total_shares, 4)
            item["total_market_value"] = round(total_mv, 2)
            item["portfolio_weight"] = round(total_mv / total_portfolio * 100, 2) if total_portfolio > 0 else 0
        else:
            item["account_holdings"] = []
            item["total_shares"] = 0
            item["total_market_value"] = 0
            item["portfolio_weight"] = 0

        # Enrich: days watched + source agent + why added
        wi_rows = (
            _db_query(
                "SELECT source, first_seen_at, last_seen_at, LEFT(source_payload::text, 200) as why FROM watchlist_items WHERE symbol=%s AND status != 'removed' ORDER BY first_seen_at LIMIT 3",
                (sym,),
            )
            or []
        )
        if wi_rows:
            first_seen = wi_rows[0].get("first_seen_at")
            if first_seen:
                from datetime import datetime as _dtx, timezone as _tzx

                try:
                    fs = (
                        first_seen
                        if isinstance(first_seen, _dtx)
                        else _dtx.fromisoformat(str(first_seen).replace("Z", "+00:00"))
                    )
                    item["days_watched"] = max(0, (_dtx.now(_tzx.utc) - fs.astimezone(_tzx.utc)).days)
                except Exception:
                    item["days_watched"] = 0
            item["added_by"] = wi_rows[0].get("source", "unknown")
            item["why_added"] = wi_rows[0].get("why", "")[:200] if wi_rows[0].get("why") else ""
            item["all_sources"] = list(set(r.get("source", "") for r in wi_rows))
        else:
            item["days_watched"] = 0
            item["added_by"] = "unknown"
            item["why_added"] = ""
            item["all_sources"] = []

        # Enrich: latest agent confidence + recommendation
        agent_row = _db_query(
            "SELECT agent, recommendation, confidence, created_at FROM watchlist_agent_results WHERE symbol=%s ORDER BY created_at DESC LIMIT 1",
            (sym,),
        )
        if agent_row:
            item["last_agent"] = agent_row[0].get("agent", "")
            item["last_recommendation"] = agent_row[0].get("recommendation", "")
            item["last_confidence"] = _json_clean(agent_row[0].get("confidence"))
            item["last_analyzed_at"] = _json_clean(agent_row[0].get("created_at"))
        # Curated badge: 2+ days watched or 2+ agent analyses
        agent_cnt = _db_query(
            "SELECT count(*) as cnt FROM watchlist_agent_results WHERE symbol=%s AND created_at > NOW() - INTERVAL '7 days'",
            (sym,),
        )
        item["is_curated"] = (item.get("days_watched", 0) >= 2) or ((agent_cnt[0]["cnt"] if agent_cnt else 0) >= 2)

        items.append(item)

    return {"count": len(items), "symbols": items}


def _infer_account_type(account_id: str) -> str:
    """Infer account type from account_id naming convention."""
    aid = (account_id or "").lower()
    if "roth" in aid:
        return "Roth IRA"
    if "rollover" in aid or "ira" in aid:
        return "Rollover IRA"
    if "401k" in aid:
        return "401k"
    if "taxable" in aid or "individual" in aid:
        return "Taxable"
    return "Unknown"


def attribution():
    a = _load_json(STATE_DIR / "performance_attribution.json") or {}

    def _clean_rows(rows, gain_key):
        out = []
        for r in rows or []:
            if isinstance(r, dict):
                out.append(
                    {
                        "symbol": r.get("symbol", ""),
                        gain_key: float(r.get(gain_key, r.get("gain", r.get("loss", 0))) or 0),
                    }
                )
        return out

    return {
        "has_data": a.get("has_data", False),
        "benchmark": a.get("benchmark", ""),
        "benchmark_label": a.get("benchmark_label", "Benchmark"),
        "port_cagr": a.get("port_cagr"),
        "bench_cagr": a.get("bench_cagr"),
        "alpha_annualized": a.get("alpha_annualized"),
        "inception_return": a.get("inception_return"),
        "bench_3yr_return": a.get("bench_3yr_return"),
        "port_sharpe": a.get("port_sharpe"),
        "bench_sharpe": a.get("bench_sharpe"),
        "port_sortino": a.get("port_sortino"),
        "bench_sortino": a.get("bench_sortino"),
        "port_maxdd": a.get("port_maxdd"),
        "bench_maxdd": a.get("bench_maxdd"),
        "rolling_alpha": a.get("rolling_alpha", []),
        "top_gainers": _clean_rows(a.get("top_gainers", []), "gain"),
        "top_losers": _clean_rows(a.get("top_losers", []), "loss"),
        "snapshot_count": a.get("snapshot_count", 0),
        "note": a.get("note", ""),
        "last_updated": a.get("last_updated", ""),
        "accounts": _attribution_accounts(),
    }


def _attribution_accounts():
    """Extract per-account breakdown from holdings.json."""
    try:
        h = _load_json(STATE_DIR / "holdings.json") or {}
        summaries = h.get("account_summaries") or {}
        if not summaries:
            # Build from holdings array
            accts: dict = {}
            for pos in h.get("holdings", []):
                acct = pos.get("account", pos.get("broker", "unknown"))
                if acct not in accts:
                    accts[acct] = {"display_name": acct, "total_value": 0, "positions": 0, "total_gain": 0}
                accts[acct]["total_value"] += float(pos.get("market_value", 0) or 0)
                accts[acct]["positions"] += 1
                accts[acct]["total_gain"] += float(pos.get("gain_total", pos.get("unrealized_gain", 0)) or 0)
            return accts
        # Use pre-computed summaries
        out = {}
        labels = {
            "fidelity_401k": "Fidelity 401k",
            "schwab_rollover_ira": "Schwab Rollover IRA",
            "schwab_roth": "Schwab Roth IRA",
            "schwab_taxable": "Schwab Taxable",
        }
        for k, v in summaries.items():
            tv = float(v.get("total_value", v.get("market_value", 0)) or 0)
            if tv <= 0:
                continue  # Skip phantom/zero-value accounts
            out[k] = {
                "display_name": labels.get(k, k),
                "total_value": tv,
                "positions": int(v.get("position_count", v.get("positions", 0)) or 0),
                "total_gain": float(v.get("total_gain", v.get("unrealized_gain", 0)) or 0),
            }
        return out
    except Exception:
        return {}


def correlation():
    c = _load_json(STATE_DIR / "correlation.json") or {}
    matrix = c.get("correlation_matrix") or {}
    symbols = list(matrix.keys()) if isinstance(matrix, dict) else []
    return {
        "has_data": c.get("has_data", False),
        "sector_exposure": c.get("sector_exposure", {}),
        "geographic": c.get("geographic", {}),
        "rate_sensitivity": c.get("rate_sensitivity", {}),
        "rate_interpretation": c.get("rate_interpretation", ""),
        "defense_cluster_pct": c.get("defense_cluster_pct", 0),
        "correlation_matrix": matrix,
        "high_correlations": c.get("high_correlations", []),
        "symbols": symbols,
        "symbols_analyzed": len(c.get("symbols_analyzed", symbols)),
        "total_value": c.get("total_value", 0),
        "last_updated": c.get("last_updated", ""),
    }


def rebalance():
    yo = _load_json(STATE_DIR / "yaml_advisor_output.json") or {}
    opus = yo.get("opus_output") or {} if isinstance(yo.get("opus_output"), dict) else {}
    gt = yo.get("ground_truth_summary") or {}

    # Pull observations and suggestions from opus_output first, then top-level fallback
    observations = opus.get("observations") or yo.get("observations") or []
    suggestions = opus.get("suggestions") or yo.get("suggestions") or []
    yaml_health = opus.get("yaml_health_score")
    yaml_notes = opus.get("yaml_health_notes", "")

    executive_lines = []
    for obs in observations[:6]:
        msg = obs.get("message") if isinstance(obs, dict) else str(obs)
        if msg:
            executive_lines.append(msg)
    if not executive_lines:
        executive_lines = [
            "Use Rebalance to review concentration, income architecture, and validation links before making account-level changes."
        ]

    v_strategy_lines = []
    bond_strategy_lines = []
    for item in suggestions:
        if not isinstance(item, dict):
            continue
        rationale = item.get("rationale", "")
        lower = rationale.lower()
        if "visa" in lower or "v " in lower[:10] or "single stock" in lower or "v_single" in lower:
            v_strategy_lines.append(rationale)
        if "bond" in lower or "fixed income" in lower or "treasury" in lower or "bnd" in lower:
            bond_strategy_lines.append(rationale)
    if not v_strategy_lines:
        v_strategy_lines = [
            m for m in executive_lines if "visa" in m.lower() or "single stock" in m.lower() or "v " in m.lower()[:10]
        ][:3]

    # Build structured suggestion cards with account routing
    suggestion_cards = []
    for item in suggestions:
        if not isinstance(item, dict):
            continue
        suggestion_cards.append(
            {
                "id": item.get("id", ""),
                "type": item.get("type", ""),
                "account": item.get("account", ""),
                "rationale": item.get("rationale", ""),
                "confidence": item.get("confidence", ""),
                "do_not_apply_if": item.get("do_not_apply_if", ""),
                "current_value": item.get("current_value"),
                "suggested_value": item.get("suggested_value"),
            }
        )

    # Structured observations with account context
    obs_cards = []
    for obs in observations:
        if not isinstance(obs, dict):
            continue
        obs_cards.append(
            {
                "type": obs.get("type", "info"),
                "account": obs.get("account", ""),
                "message": obs.get("message", ""),
                "data": obs.get("data"),
            }
        )

    summary = opus.get("summary", "")
    recommendations = opus.get("recommendations", [])
    has_pipeline_recs = bool(recommendations)

    # If no pipeline recommendations, compute from live portfolio state
    if not recommendations:
        _rh = _load_json(STATE_DIR / "holdings.json") or {}
        _rrm = _load_json(STATE_DIR / "risk_management.json") or {}
        _rdc = _load_json(STATE_DIR / "dividend_calendar.json") or {}
        _rholdings = [p for p in _rh.get("holdings", []) if not p.get("is_cash") and (p.get("market_value") or 0) > 50]
        _rtotal = sum(p.get("market_value", 0) for p in _rholdings)
        computed = []
        for p in _rholdings:
            pct = (p.get("market_value", 0) / _rtotal * 100) if _rtotal > 0 else 0
            if pct > 20:
                computed.append(
                    {
                        "symbol": p["symbol"],
                        "action": "REVIEW TRIM",
                        "rationale": f"{p['symbol']} at {pct:.1f}% — exceeds 20% concentration threshold. Consider trimming to reduce single-name risk.",
                        "severity": "high",
                        "account": p.get("account", ""),
                    }
                )
            elif pct > 15:
                computed.append(
                    {
                        "symbol": p["symbol"],
                        "action": "MONITOR",
                        "rationale": f"{p['symbol']} at {pct:.1f}% — approaching concentration limit.",
                        "severity": "medium",
                        "account": p.get("account", ""),
                    }
                )
        for p in _rrm.get("positions", []):
            if (
                p.get("status") == "NO STOP"
                and (p.get("market_value") or 0) > 10000
                and p.get("account") != "fidelity_401k"
            ):
                computed.append(
                    {
                        "symbol": p["symbol"],
                        "action": "SET STOP",
                        "rationale": f"{p['symbol']} (${p['market_value']:,.0f}) has no stop. Consider placing a trailing stop.",
                        "severity": "medium",
                        "account": p.get("account", ""),
                    }
                )
        _rann = _rdc.get("total_annual", 0)
        if _rtotal > 0 and _rann / _rtotal < 0.01:
            computed.append(
                {
                    "symbol": "",
                    "action": "INCOME REVIEW",
                    "rationale": f"Portfolio yield {_rann / _rtotal * 100:.2f}% — below 1% target. Consider adding income positions (SCHD, JEPI, BDCs).",
                    "severity": "low",
                }
            )
        # Sector concentration check
        _sector_map = {}
        for p in _rholdings:
            s = p.get("sector", "Other")
            _sector_map[s] = _sector_map.get(s, 0) + p.get("market_value", 0)
        for s, mv in _sector_map.items():
            spct = mv / _rtotal * 100 if _rtotal else 0
            if spct > 30:
                computed.append(
                    {
                        "symbol": "",
                        "action": "SECTOR CONCENTRATION",
                        "rationale": f"{s} sector at {spct:.0f}% — over 30% threshold. Consider diversifying.",
                        "severity": "high",
                    }
                )
        # Cash adequacy
        _cash = sum(p.get("market_value", 0) for p in _rh.get("holdings", []) if p.get("is_cash"))
        _cash_pct = _cash / _rtotal * 100 if _rtotal else 0
        if _cash_pct < 2:
            computed.append(
                {
                    "symbol": "CASH",
                    "action": "LOW CASH",
                    "rationale": f"Cash at {_cash_pct:.1f}% (${_cash:,.0f}) — below 2% buffer. Consider raising cash.",
                    "severity": "medium",
                }
            )
        # Portfolio heat
        _heat = _rrm.get("portfolio_heat_pct", 0)
        if _heat > 5:
            computed.append(
                {
                    "symbol": "",
                    "action": "HEAT ELEVATED",
                    "rationale": f"Portfolio heat at {_heat:.1f}% — above 5% threshold. Reduce risk exposure or add stops.",
                    "severity": "high",
                }
            )
        recommendations = computed

    # ── Staleness indicator ──
    generated_at = yo.get("generated_at", "")
    is_stale = False
    stale_days = None
    if generated_at:
        try:
            from datetime import datetime as _dt

            gen_dt = _dt.fromisoformat(str(generated_at).replace("Z", "+00:00"))
            stale_days = (datetime.now() - gen_dt.replace(tzinfo=None)).days
            is_stale = stale_days > 7
        except Exception:
            is_stale = True

    return {
        "generated_at": generated_at,
        "status": yo.get("status", ""),
        "is_stale": is_stale,
        "stale_days": stale_days,
        "stale_note": f"Rebalance data is {stale_days} days old. Click Refresh to regenerate." if is_stale else None,
        "model_used": opus.get("_model_used")
        or yo.get("_model_used")
        or (yo.get("model") if yo.get("model") else None),
        "ground_truth": gt,
        "recommendations": recommendations,
        "summary": summary,
        "executive_lines": executive_lines,
        "v_strategy_lines": v_strategy_lines,
        "bond_strategy_lines": bond_strategy_lines,
        "computed": not has_pipeline_recs,
        "account_summary": _rebalance_account_summary(),
        "observations": obs_cards,
        "suggestions": suggestion_cards,
        "yaml_health_score": yaml_health,
        "yaml_health_notes": yaml_notes,
        "llm_suggestions": {
            k: _json_clean(v)
            for k, v in (
                _db_query(
                    "SELECT content, generated_at FROM llm_intelligence_cache WHERE section='rebalance_suggestions'",
                    fetch="one",
                )
                or {}
            ).items()
        },
        "deep_analysis": _get_deep_rebalance_analysis(),
        "computed_values": {
            "total_value": (_load_json(STATE_DIR / "holdings.json") or {})
            .get("portfolio_totals", {})
            .get("total_value", 0),
            "income_target": 55000,
            "income_current": float((_load_json(STATE_DIR / "dividend_calendar.json") or {}).get("total_annual", 0)),
            "income_gap": round(
                55000 - float((_load_json(STATE_DIR / "dividend_calendar.json") or {}).get("total_annual", 0)), 2
            ),
        },
        "snapshot_source": "holdings.json filtered > $50 market value",
    }


def _get_deep_rebalance_analysis():
    """Get latest deep rebalance analysis from rebalance_analysis_results."""
    try:
        row = _db_query(
            """
            SELECT id, generated_at, yaml_health_score, executive_summary,
                   recommendations, v_concentration_plan, bond_ballast_assessment,
                   yaml_gaps, verification_passed, ssdi_irmaa_flags,
                   verified_at, model_primary, stale_days_at_run
            FROM rebalance_analysis_results
            ORDER BY generated_at DESC LIMIT 1
        """,
            fetch="one",
        )
        if not row:
            return None
        return {k: _json_clean(v) for k, v in row.items()}
    except Exception:
        return None


def _rebalance_account_summary():
    """Build account-level summary for rebalance context."""
    h = _load_json(STATE_DIR / "holdings.json") or {}
    accts = {}
    for p in h.get("holdings", []):
        a = p.get("account", "unknown")
        if a not in accts:
            accts[a] = {"account": a, "total_value": 0, "position_count": 0, "cash": 0}
        if p.get("is_cash"):
            accts[a]["cash"] += p.get("market_value", 0)
        else:
            accts[a]["total_value"] += p.get("market_value", 0)
            accts[a]["position_count"] += 1
    return sorted(accts.values(), key=lambda x: -x["total_value"])


def _forecast():
    """Portfolio projection based on current yield, dividend income, and account values."""
    dc = _load_json(STATE_DIR / "dividend_calendar.json") or {}
    ret = _load_json(STATE_DIR / "retirement_roadmap.json") or {}

    # --- Data Broker: portfolio_snapshot for total_value (Phase D wiring) ---
    total = None
    accts = {}
    try:
        from lib.data_broker.portfolio_snapshot import get_portfolio_snapshot

        snap = get_portfolio_snapshot()
        total = (snap.get("totals") or {}).get("total_value", 0) or 0
        # Snapshots don't carry account_summaries per-account-key; fallback to holdings.json below
    except Exception:
        total = None
    # Fallback: direct holdings.json read if broker didn't provide total_value or account_summaries
    if total is None or total == 0:
        h = _load_json(STATE_DIR / "holdings.json") or {}
        total = h.get("portfolio_totals", {}).get("total_value", 0) or 0
        accts = h.get("account_summaries", {})
    else:
        # Broker provided total_value but not account_summaries; read holdings.json for those
        h = _load_json(STATE_DIR / "holdings.json") or {}
        accts = h.get("account_summaries", {})

    annual_div = dc.get("total_annual", 0)
    portfolio_yield = (annual_div / total * 100) if total > 0 else 0
    scenarios = {
        "conservative": {"market_return": 4.0, "label": "Conservative (4% + divs)"},
        "moderate": {"market_return": 7.0, "label": "Moderate (7% + divs)"},
        "aggressive": {"market_return": 10.0, "label": "Aggressive (10% + divs)"},
    }

    projections = {}
    for scenario_key, scenario in scenarios.items():
        total_return = scenario["market_return"] + portfolio_yield
        years = {}
        for yr in [1, 2, 3, 5]:
            projected = total * ((1 + total_return / 100) ** yr)
            div_cumulative = annual_div * yr
            years[f"{yr}Y"] = {
                "projected_value": round(projected, 0),
                "growth": round(projected - total, 0),
                "cumulative_dividends": round(div_cumulative, 0),
                "total_return_pct": round(((projected / total) - 1) * 100, 1),
            }
        projections[scenario_key] = {
            "label": scenario["label"],
            "total_return_pct": round(total_return, 2),
            "years": years,
        }

    account_detail = []
    for acct_key in ["fidelity_401k", "schwab_rollover_ira", "schwab_roth", "schwab_taxable"]:
        val = accts.get(acct_key, {}).get("total_value", 0)
        account_detail.append(
            {"account": acct_key, "current_value": val, "pct_of_total": round(val / total * 100, 1) if total else 0}
        )

    payers = dc.get("payers", [])
    top_payers = sorted(payers, key=lambda p: p.get("annual_income", 0), reverse=True)[:10]

    return {
        "portfolio_value": total,
        "annual_dividend_income": annual_div,
        "portfolio_yield_pct": round(portfolio_yield, 2),
        "monthly_dividend_avg": dc.get("monthly_average", 0),
        "projections": projections,
        "accounts": account_detail,
        "top_dividend_payers": [
            {
                "symbol": p.get("symbol"),
                "yield_pct": p.get("yield_pct", 0),
                "annual_income": p.get("annual_income", 0),
                "frequency": p.get("frequency", ""),
                "value": p.get("market_value", 0),
            }
            for p in top_payers
        ],
        "assumptions": {
            "basis": "Current portfolio value and dividend yield held constant. No contributions, withdrawals, or rebalancing assumed.",
            "market_scenarios": "Conservative=4%, Moderate=7%, Aggressive=10% annual appreciation",
            "dividend_basis": "Trailing 12-month dividend rates from current holdings",
            "limitations": "No tax impact. No inflation adjustment. Fidelity 401k yield may be understated for proprietary funds. Projections are estimates only.",
        },
        "retirement_age": ret.get("current_age"),
    }


def _vix_observation(run_vix, run_timestamp=None):
    """Return (value, source, observation_time) for the VIX headline.

    cc-header-truth-v2 (Phase 2 D): VIX must name its source and observation
    time. The run_summary vix and the regime collector's vix_close are two
    different sources; a bare float hides which one answered. This returns the
    source label alongside the value so the surface can name it.
    """
    try:
        v = float(run_vix or 0)
        if v > 0:
            return v, "trade_ai_run_summary", run_timestamp
    except (TypeError, ValueError):
        pass
    try:
        row = _db_query(
            """SELECT value, created_at FROM market_regime_indicators
               WHERE indicator_key='vix_close' AND created_at > now() - interval '48 hours'
               ORDER BY created_at DESC LIMIT 1""",
            fetch="one",
        )
        if row and row.get("value") is not None:
            _ct = row.get("created_at")
            _obs = _ct.isoformat() if hasattr(_ct, "isoformat") else (str(_ct) if _ct else None)
            return float(row["value"]), "market_regime_indicators.vix_close", _obs
    except Exception:
        pass
    return None, None, None


def _vix_effective(run_vix):
    """v3.1 (WS-F2): the orchestrator's run_summary has carried vix=0 since its
    fetch died — fall back to the regime collector's vix_close (fresh daily at
    06:30) so the header tile never shows a dead '—' while real VIX exists."""
    return _vix_observation(run_vix)[0]


def _compute_trade_ai():
    """Trade AI workspace — latest run data from run_summary + watchlist CSV. HEAVY (run JSON glob +
    a DISTINCT-ON scan of trade_ai_scans, hundreds of rows). Never call from the request path — go
    through trade_ai(), which serves the disk cache that warm_caches.py refreshes."""
    import csv, io, glob

    # Find all runs for today + yesterday
    all_runs = []
    for pattern in ["reports/2026-*/*/run_summary.json"]:
        for fp in sorted(glob.glob(str(PROJECT_ROOT / pattern)), reverse=True)[:24]:
            rs = _load_json(Path(fp))
            if rs:
                rs["_path"] = fp
                all_runs.append(rs)

    # Prefer real packages (with tickers) over empty session-heal anchors
    def _run_rank(rs):
        """Rank runs so that `latest` means MOST RECENT, not BIGGEST.

        This used to return (heal, tc, date, generated_at) -- raw ticker_count
        ranked ABOVE date, so a large stale run beat a small fresh one. Observed
        2026-09-01 09:45: the panel showed run_label "1730" (a 17:30 run) with
        latest_run_timestamp empty and latest_run_symbols_scanned 0, because a
        38-ticker evening package outranked the morning's 10-ticker run. The
        variable is called `latest`; it was returning the largest.

        The intent of ranking by count was only to prefer real packages over empty
        session-heal anchors -- so keep that as a BOOLEAN (non-empty beats empty)
        and let date decide among real runs. Size becomes the last tiebreak, where
        it cannot mask recency.
        """
        tc = int(rs.get("ticker_count") or len(rs.get("tickers") or []) or 0)
        lbl = str(rs.get("run_label") or "")
        heal = 0 if lbl == "HEALTH_AUTOHEAL" or rs.get("session_heal") else 1
        date = str(rs.get("date") or rs.get("run_date") or "")
        has_tickers = 1 if tc > 0 else 0
        return (heal, has_tickers, date, str(rs.get("generated_at") or ""), tc)

    all_runs.sort(key=_run_rank, reverse=True)
    latest = all_runs[0] if all_runs else {}

    # Read tickers from DB (primary) or CSV (fallback)
    tickers = []
    try:
        # Get the most recent scan per symbol from today's latest run
        _db_tickers = _db_query("""
            SELECT DISTINCT ON (symbol)
                symbol, score, grade, decision, original_decision,
                rvol, price, change_pct, gap_pct, float_m, volume,
                catalyst, catalyst_verified, catalyst_confidence, catalyst_source,
                critic_verdict, critic_confidence, critic_reasoning, decision_changed,
                disqualified, disqualification_reason,
                sector, industry, country, sector_etf,
                ticker_perf_1m, sector_perf_1m, vs_sector_pct,
                social_sentiment, social_score, social_reddit, social_stocktwits,
                social_bullish_pct, social_wsb,
                source, source_detail, run_type, run_label as scan_run_label,
                intelligence_readiness,
                route, route_actionability,
                scout_status, scout_pillar_count, scout_pillars_met, scout_pillars_missing,
                operator_pill, operator_subtitle, operator_color_token,
                not_validation_ready, not_tradeable,
                awareness_status, setup_class, manual_review_required, symbol_candidate,
                run_date AS scan_run_date,
                scanned_at
            FROM trade_ai_scans
            WHERE run_date >= CURRENT_DATE - INTERVAL '1 day'
            ORDER BY symbol, scanned_at DESC
        """)
        if _db_tickers:
            for r in _db_tickers:
                _cn = _resolve_country_name(r["symbol"], r.get("country"))
                tickers.append(
                    {
                        "symbol": r["symbol"],
                        "score": int(r.get("score") or 0),
                        "grade": r.get("grade") or "",
                        "decision": r.get("decision") or "",
                        "rvol": float(r.get("rvol") or 0),
                        "volume": int(r.get("volume") or 0) or None,
                        "price": float(r.get("price") or 0),
                        "change_pct": str(round(float(r["change_pct"]), 2)) if r.get("change_pct") is not None else "",
                        "gap_pct": str(round(float(r["gap_pct"]), 2)) if r.get("gap_pct") is not None else "",
                        "float_m": str(round(float(r["float_m"]), 2)) if r.get("float_m") is not None else "",
                        "catalyst": r.get("catalyst") or "",
                        "critic_verdict": r.get("critic_verdict"),
                        "critic_confidence": r.get("critic_confidence"),
                        "original_decision": r.get("original_decision"),
                        "decision_changed": bool(r.get("decision_changed")),
                        "catalyst_verified": r.get("catalyst_verified"),
                        "catalyst_confidence": r.get("catalyst_confidence"),
                        "industry": r.get("industry"),
                        "critic_reasoning": r.get("critic_reasoning"),
                        "disqualified": bool(r.get("disqualified")),
                        "disqualification_reason": r.get("disqualification_reason"),
                        "critic_flags": [],
                        "sector": r.get("sector"),
                        "country": _country_flag(_cn),
                        "country_name": _cn,  # raw HQ name for flag+tooltip (frontend lib/country.ts); Finviz-cache fallback
                        "sector_etf": r.get("sector_etf"),
                        "ticker_perf_1m": r.get("ticker_perf_1m"),
                        "sector_perf_1m": r.get("sector_perf_1m"),
                        "vs_sector_pct": r.get("vs_sector_pct"),
                        # Social from DB scan record
                        "social_sentiment": r.get("social_sentiment") or None,
                        "social_score": r.get("social_score"),
                        "social_reddit": r.get("social_reddit") or 0,
                        "social_stocktwits": r.get("social_stocktwits") or 0,
                        "social_bullish_pct": r.get("social_bullish_pct"),
                        "social_wsb": r.get("social_wsb") or 0,
                        "source": r.get("source") or "screener",
                        "source_detail": r.get("source_detail") or "",
                        "run_type": r.get("run_type"),
                        "scan_run_label": r.get("scan_run_label"),
                        # Run identity is (run_date, run_label). The label alone
                        # repeats every day -- see the scoping comment below.
                        "scan_run_date": str(r.get("scan_run_date") or "")[:10],
                        "intelligence_readiness": r.get("intelligence_readiness"),
                        # --- Social Scout operator-awareness fields (P0-5). Awareness only: a scout is
                        # never tradeable / never validation-ready (see route policy + gates). ---
                        "route": r.get("route"),
                        "route_actionability": r.get("route_actionability"),
                        "scout_status": r.get("scout_status"),
                        "scout_pillar_count": r.get("scout_pillar_count"),
                        "scout_pillars_met": r.get("scout_pillars_met"),
                        "scout_pillars_missing": r.get("scout_pillars_missing"),
                        "operator_pill": r.get("operator_pill"),
                        "operator_subtitle": r.get("operator_subtitle"),
                        "operator_color_token": r.get("operator_color_token"),
                        "not_validation_ready": r.get("not_validation_ready"),
                        "not_tradeable": r.get("not_tradeable"),
                        "awareness_status": r.get("awareness_status"),
                        "setup_class": r.get("setup_class"),
                        "manual_review_required": r.get("manual_review_required"),
                        "symbol_candidate": r.get("symbol_candidate"),
                    }
                )
    except Exception:
        pass

    # CSV fallback if DB is empty (bootstrap period)
    if not tickers:
        csv_pattern = latest.get("_path", "").replace("run_summary.json", "").rstrip("/")
        if csv_pattern:
            csvs = sorted(glob.glob(csv_pattern + "/trade_ai_*_watchlist.csv"))
            if csvs:
                try:
                    rows = list(csv.DictReader(io.StringIO(Path(csvs[-1]).read_text())))
                    for r in rows:
                        _cn = _resolve_country_name(r.get("Symbol", ""), r.get("Country"))
                        tickers.append(
                            {
                                "symbol": r.get("Symbol", ""),
                                "score": int(r.get("Score", 0) or 0),
                                "grade": r.get("Grade", ""),
                                "decision": r.get("Decision", ""),
                                "rvol": float(r.get("RVOL", 0) or 0),
                                "price": float(r.get("Price", 0) or 0),
                                "change_pct": r.get("Change%", ""),
                                "gap_pct": r.get("Gap%", ""),
                                "float_m": r.get("Float_M", ""),
                                "catalyst": r.get("Catalyst", ""),
                                "critic_verdict": r.get("CriticVerdict", "") or None,
                                "critic_confidence": float(r.get("CriticConf", 0) or 0)
                                if r.get("CriticConf")
                                else None,
                                "catalyst_verified": r.get("CatalystVerified", "").lower() == "true"
                                if r.get("CatalystVerified")
                                else None,
                                "industry": r.get("Industry", "") or None,
                                "critic_reasoning": r.get("CriticReasoning", "") or None,
                                "disqualified": r.get("Disqualified", "").lower() == "true"
                                if r.get("Disqualified")
                                else False,
                                "critic_flags": [],
                                "sector": r.get("Sector", "") or None,
                                "country": _country_flag(_cn) or None,
                                "country_name": _cn,
                                "sector_etf": r.get("SectorETF", "") or None,
                                "ticker_perf_1m": float(r["TickerPerf1M"]) if r.get("TickerPerf1M") else None,
                                "sector_perf_1m": float(r["SectorPerf1M"]) if r.get("SectorPerf1M") else None,
                                "vs_sector_pct": float(r["VsSectorPct"]) if r.get("VsSectorPct") else None,
                            }
                        )
                except Exception:
                    pass

    # Volume from latest Finviz snapshot when DB row lacks it (same refresh cadence as RVOL)
    try:
        import sys as _sys_vol

        _sys_vol.path.insert(0, str(PROJECT_ROOT / "scripts" / "lib"))
        from finviz_snapshot import load_latest_field_map

        _vol_map = load_latest_field_map(PROJECT_ROOT, "volume")
        for t in tickers:
            if not t.get("volume"):
                v = _vol_map.get((t.get("symbol") or "").upper())
                if v:
                    t["volume"] = int(v)
    except Exception:
        pass

    # Enrich tickers with historical appearance data from DB
    try:
        _history = (
            _db_query("""
            SELECT symbol,
                   COUNT(DISTINCT run_date) as days_appeared,
                   COUNT(DISTINCT run_date) FILTER (WHERE decision = 'GO') as days_go,
                   MIN(run_date) as first_seen,
                   MAX(run_date) as last_seen,
                   MAX(score) as peak_score
            FROM trade_ai_scans
            WHERE run_type = 'full'
            GROUP BY symbol
        """)
            or []
        )
        _hist_map = {r["symbol"]: r for r in _history}
        for t in tickers:
            h = _hist_map.get(t["symbol"])
            if h:
                t["history_days"] = h.get("days_appeared", 1)
                t["history_go_days"] = h.get("days_go", 0)
                t["history_first_seen"] = str(h.get("first_seen", ""))
                t["history_peak_score"] = h.get("peak_score", 0)
    except Exception:
        pass

    # Social sentiment: served from DB (populated by continuous_runner each scan cycle)
    # No live API calls here — avoids 20-30s page load from per-ticker StockTwits lookups

    # Enrich tickers with source origin (Finviz screener vs Social scalp vs portfolio)
    try:
        wi_sources = {}
        for sr in (
            _db_query(
                "SELECT symbol, array_agg(DISTINCT source ORDER BY source) as sources FROM watchlist_items WHERE status != 'removed' GROUP BY symbol"
            )
            or []
        ):
            wi_sources[sr["symbol"]] = sr["sources"]
        scalp_sources = {}
        for sr in (
            _db_query(
                "SELECT symbol, sources FROM scalp_scan_results WHERE scanned_at > NOW() - INTERVAL '48 hours' ORDER BY scanned_at DESC"
            )
            or []
        ):
            if sr["symbol"] not in scalp_sources:
                scalp_sources[sr["symbol"]] = sr.get("sources") or []
        for t in tickers:
            sym = t["symbol"]
            ss = scalp_sources.get(sym)
            ws = wi_sources.get(sym)
            # Check if live social sentiment shows activity
            has_social = (t.get("social_reddit", 0) or 0) > 0 or (t.get("social_stocktwits", 0) or 0) >= 10
            if ss:
                t["source"] = "social"
                t["source_detail"] = ", ".join(str(s) for s in ss[:2]) if ss else ""
            elif ws:
                src = ws[0] if ws else "screener"
                t["source"] = src
                t["source_detail"] = ", ".join(ws[:2]) if len(ws) > 1 else ""
            elif has_social:
                # Finviz screener pick with social activity
                parts = []
                if t.get("social_reddit", 0) > 0:
                    parts.append("Reddit")
                if t.get("social_stocktwits", 0) >= 10:
                    parts.append("StockTwits")
                t["source"] = "screener"
                t["source_detail"] = " + ".join(parts)
            else:
                t["source"] = "screener"
                t["source_detail"] = ""
    except Exception:
        pass

    # Social awareness-only rows (premarket StockTwits without Finviz price/RVOL)
    try:
        import sys as _sys_sa

        _sa_lib = PROJECT_ROOT / "scripts" / "lib"
        if str(_sa_lib) not in _sys_sa.path:
            _sys_sa.path.insert(0, str(_sa_lib))
        from social_awareness import (
            enrich_awareness_market_fields,
            is_social_awareness_row,
            tag_social_awareness_row,
        )

        _aware_syms = [t["symbol"] for t in tickers if is_social_awareness_row(t)]
        _news_cat: dict = {}
        if _aware_syms:
            for nr in (
                _db_query(
                    """
                SELECT DISTINCT ON (symbol) symbol, title
                FROM news_articles
                WHERE symbol = ANY(%s) AND COALESCE(title, '') <> ''
                ORDER BY symbol, published_at DESC NULLS LAST
            """,
                    (_aware_syms,),
                )
                or []
            ):
                _news_cat[nr["symbol"]] = nr.get("title") or ""
        for t in tickers:
            if not is_social_awareness_row(t):
                continue
            fb = _news_cat.get(t["symbol"]) or ""
            if not fb and (t.get("social_stocktwits") or t.get("mention_count")):
                mc = int(t.get("mention_count") or t.get("social_stocktwits") or 0)
                fb = f"StockTwits pre-market activity ({mc} posts/2hr)"
            tag_social_awareness_row(t, catalyst_fallback=fb)
        enrich_awareness_market_fields(tickers, PROJECT_ROOT)
    except Exception:
        pass

    # LLM enrichment: incubator screen + holdings health + proposal reviews
    try:
        _ticker_syms = [t["symbol"] for t in tickers]
        # Incubator LLM screen grades
        _incub_llm = (
            _db_query(
                """
            SELECT DISTINCT ON (symbol) symbol, llm_screen_grade, llm_screen_verdict,
                   llm_screen_confidence, llm_screen_at
            FROM incubator_universe
            WHERE symbol = ANY(%s) AND llm_screen_grade IS NOT NULL
            ORDER BY symbol, llm_screen_at DESC NULLS LAST
        """,
                [_ticker_syms],
            )
            or []
        )
        _incub_map = {r["symbol"]: r for r in _incub_llm}

        # Holdings LLM health
        _hold_llm = (
            _db_query(
                """
            SELECT symbol, holdings_llm_health, holdings_llm_action,
                   holdings_llm_confidence, holdings_llm_at
            FROM watchlist_items
            WHERE source = 'portfolio' AND symbol = ANY(%s) AND holdings_llm_health IS NOT NULL
        """,
                [_ticker_syms],
            )
            or []
        )
        _hold_map = {r["symbol"]: r for r in _hold_llm}

        # Proposal LLM reviews (latest per symbol)
        _prop_llm = (
            _db_query(
                """
            SELECT DISTINCT ON (symbol) symbol, llm_review_stage, llm_model_used,
                   confidence_score as llm_confidence,
                   llm_review_chunks
            FROM paper_trade_proposals
            WHERE symbol = ANY(%s) AND status = 'PENDING' AND llm_review_stage IS NOT NULL
            ORDER BY symbol, confidence_score DESC NULLS LAST
        """,
                [_ticker_syms],
            )
            or []
        )
        _prop_map = {r["symbol"]: r for r in _prop_llm}

        for t in tickers:
            sym = t["symbol"]
            inc = _incub_map.get(sym)
            if inc:
                t["incubator_llm_grade"] = inc.get("llm_screen_grade")
                t["incubator_llm_verdict"] = inc.get("llm_screen_verdict")
            hld = _hold_map.get(sym)
            if hld:
                t["holdings_llm_health"] = hld.get("holdings_llm_health")
                t["holdings_llm_action"] = hld.get("holdings_llm_action")
            prp = _prop_map.get(sym)
            if prp:
                t["proposal_llm_stage"] = prp.get("llm_review_stage")
                t["proposal_llm_confidence"] = prp.get("llm_confidence")
                chunks = prp.get("llm_review_chunks")
                if chunks and isinstance(chunks, dict):
                    t["proposal_llm_decision"] = (chunks.get("decision") or {}).get("decision")
                    t["proposal_risk_grade"] = (chunks.get("risk") or {}).get("risk_grade")
                    t["proposal_catalyst_grade"] = (chunks.get("catalyst") or {}).get("catalyst_grade")
    except Exception:
        pass

    # Options desk context (portfolio proposals: CC/CSP/spreads)
    options_desk_summary = {}
    try:
        import options_engine as _oe

        options_desk_summary = _load_json(_oe.OPTIONS_DESK_RUNTIME) or _oe.build_options_desk_summary()
        for t in tickers:
            ctx = _oe.options_context_for_symbol(t.get("symbol", ""), options_desk_summary)
            if ctx:
                t["options_desk"] = ctx
    except Exception:
        options_desk_summary = {}

    # Finviz prime-setup top gainers — awareness pill for names blocked from momentum-scalp GO
    # (e.g. recent reverse split) so operators still see leading movers like GMM.
    _top_gainer_rows: list = []
    try:
        import sys as _sys_tg

        _sys_tg.path.insert(0, str(PROJECT_ROOT / "scripts" / "lib"))
        from squeeze_manual_review import attach_squeeze_manual_tags
        from micro_float_manual_review import attach_micro_float_manual_tags
        from high_rvol_manual_review import attach_high_rvol_manual_tags
        from low_price_manual_review import attach_low_price_manual_tags
        from catalyst_exception import attach_catalyst_exception_tags
        from top_gainer_awareness import attach_top_gainer_awareness, load_top_gainers

        attach_squeeze_manual_tags(tickers)
        attach_micro_float_manual_tags(tickers)
        attach_high_rvol_manual_tags(tickers)
        attach_low_price_manual_tags(tickers)
        attach_catalyst_exception_tags(tickers)
        # Runs LAST on purpose — the lane taggers above own awareness_status. The
        # gainer marker is orthogonal (row["top_gainer"]) so it survives a squeeze.
        attach_top_gainer_awareness(tickers, PROJECT_ROOT, limit=30)
        _top_gainer_rows = load_top_gainers(PROJECT_ROOT, limit=30)
    except Exception:
        _top_gainer_rows = []

    # Sector breakdown from tickers (basic)
    sectors: dict = {}
    _ec_cache = _load_json(STATE_DIR / "ticker_enrichment_cache.json") or {}
    for t in tickers:
        sec = (
            (_ec_cache.get(t["symbol"], {}) or {}).get("sector", "Unknown")
            if isinstance(_ec_cache.get(t["symbol"]), dict)
            else "Unknown"
        )
        sectors[sec] = sectors.get(sec, 0) + 1

    # Run history for sparkline
    run_history = []
    for rs in all_runs[:8]:
        run_history.append(
            {
                "date": rs.get("date", ""),
                "label": rs.get("run_label", ""),
                "go": rs.get("go_count", 0),
                "wait": rs.get("wait_count", 0),
                "total": rs.get("ticker_count", 0),
                "top_ticker": rs.get("top_ticker", ""),
                "top_score": rs.get("top_score", 0),
            }
        )

    # Universe counts (all tickers from today + yesterday — may be larger than latest run)
    go_count = sum(1 for t in tickers if t.get("decision") == "GO")
    wait_count = sum(1 for t in tickers if t.get("decision") == "WAIT")
    avoid_count = sum(1 for t in tickers if t.get("decision") not in ("GO", "WAIT"))

    # SCALP-COUNT-1: current-run counts scoped to the latest run.
    #
    # This filtered on run_label ALONE. The ticker query spans two days
    # (`run_date >= CURRENT_DATE - INTERVAL '1 day'`) and collapses to one row
    # per symbol via DISTINCT ON, so a symbol scanned in YESTERDAY's 0900 run and
    # absent from today's survived the collapse still carrying label '0900' and
    # was counted into today's run. Run 2026-09-04::0900 reported 60 scanned
    # against a run_summary ticker_count of 49: eleven of those rows were the
    # previous day's. That is the entire "60 vs 49" disagreement that pinned
    # count_integrity at PARTIAL -- the taxonomy was fine, the population was not.
    #
    # Run identity is (run_date, run_label). Scope on both. Rows predating the
    # run_date projection carry no date; they are counted only when the run has
    # no dated rows at all, so an older cached payload degrades to the previous
    # behaviour rather than reporting an empty run.
    _current_run_label = latest.get("run_label", "")
    _current_run_date = str(latest.get("date", "") or "")[:10]
    if _current_run_label:
        _label_rows = [t for t in tickers if t.get("scan_run_label") == _current_run_label]
        _dated_rows = [t for t in _label_rows if t.get("scan_run_date")]
        if _current_run_date and _dated_rows:
            _current_run_tickers = [t for t in _dated_rows if t.get("scan_run_date") == _current_run_date]
        else:
            _current_run_tickers = _label_rows
    else:
        _current_run_tickers = tickers
    current_run_go = sum(1 for t in _current_run_tickers if t.get("decision") == "GO")
    current_run_wait = sum(1 for t in _current_run_tickers if t.get("decision") == "WAIT")
    current_run_nogo = sum(1 for t in _current_run_tickers if t.get("decision") not in ("GO", "WAIT"))
    current_run_total = len(_current_run_tickers)

    # Run health enrichment (status + reason_codes already in screener_run_health)
    _latest_run_label = latest.get("run_label", "")
    # Prefer the zoned stamp when the producer wrote one. `generated_at` is
    # naive host-local and cannot be converted; a surface that renders it must
    # say the zone is unstated rather than infer one from the host's TZ.
    _latest_run_timestamp = latest.get("generated_at_utc") or latest.get("generated_at", "")
    _run_health_status = None
    _run_health_reason_codes = []
    _expected_min_symbols = None
    _run_health_scope = None
    _run_health_run_label = None
    _today_signal_count = 0
    _RH_COLS = (
        "status, symbols_scanned, go_count AS rh_go, wait_count AS rh_wait, "
        "no_go_count, reason_codes, finished_at, expected_min_symbols, "
        "run_label AS rh_run_label, run_date AS rh_run_date"
    )
    try:
        # Scope the health row to THIS run, not merely to today.
        #
        # This was `WHERE run_date = CURRENT_DATE ORDER BY finished_at DESC LIMIT 1`,
        # while run_id / run_label come from run_summary.json. On a day with
        # several runs those describe different runs, so the header printed a
        # health verdict beside an id it did not belong to — the same defect
        # class as the cross-day run_label leak fixed in #857.
        #
        # A hard join is the WRONG fix: record_screener_run_finish stamps
        # run_date from the DB server's clock while run_summary uses the
        # orchestrator's date_str, so around midnight or on a re-run they
        # legitimately differ. A strict join turns a possibly-wrong verdict into
        # a silently absent one, which is worse. Scope, fall back, and publish
        # which of the two happened — never resolve it silently.
        _rh = None
        if _latest_run_label and latest.get("date"):
            _rh = _db_query(
                f"""
                SELECT {_RH_COLS}
                FROM screener_run_health
                WHERE run_date = %s AND run_label = %s
                ORDER BY finished_at DESC NULLS LAST LIMIT 1
            """,
                [str(latest.get("date"))[:10], str(_latest_run_label)],
                fetch="one",
            )
            if _rh:
                _run_health_scope = "exact_run"
        if not _rh:
            _rh = _db_query(
                f"""
                SELECT {_RH_COLS}
                FROM screener_run_health
                WHERE run_date = CURRENT_DATE
                ORDER BY finished_at DESC NULLS LAST LIMIT 1
            """,
                fetch="one",
            )
            if _rh:
                # The verdict is real but may describe a different run. Say so.
                _run_health_scope = "latest_today_unmatched"
        if _rh:
            _run_health_run_label = _rh.get("rh_run_label")
            _run_health_status = _rh.get("status")
            _rc = _rh.get("reason_codes") or []
            if isinstance(_rc, str):
                try:
                    import json as _json

                    _rc = _json.loads(_rc)
                except Exception:
                    _rc = [_rc] if _rc else []
            if isinstance(_rc, (list, tuple)):
                _run_health_reason_codes = [str(x) for x in _rc if x is not None and str(x).strip()]
            if _rh.get("expected_min_symbols") is not None:
                try:
                    _expected_min_symbols = int(_rh.get("expected_min_symbols"))
                except (TypeError, ValueError):
                    _expected_min_symbols = None
    except Exception:
        pass
    try:
        _sig = _db_query(
            """
            SELECT COUNT(*) AS cnt FROM strategy_signals
            WHERE fired_at::date = CURRENT_DATE
        """,
            fetch="one",
        )
        if _sig:
            _today_signal_count = int(_sig.get("cnt") or 0)
    except Exception:
        pass

    # Canonical run-scoped setup summary (cc-header-truth-v2 Phase 2 C).
    # One taxonomy, one reconciliation, served identically by overview and
    # /trade-ai/summary. AVOID/NO_GO/disqualified/unclassified are NOT lumped.
    from lib.setup_run_contract import build_setup_run_summary, derive_run_id, tally_decisions

    _current_run_tally = tally_decisions(_current_run_tickers)
    _run_id = derive_run_id(_current_run_label, latest.get("date", ""), latest.get("generated_at", ""))
    _vix_val, _vix_src, _vix_obs = _vix_observation(latest.get("vix"), _latest_run_timestamp)
    _setup_run_summary = build_setup_run_summary(
        run_id=_run_id,
        run_label=_current_run_label,
        run_date=latest.get("date", ""),
        run_timestamp=_latest_run_timestamp,
        source="trade_ai_scans",
        tally=_current_run_tally,
        scanned_count=current_run_total,
        scanned_count_alt=latest.get("ticker_count"),
        freshness_status=(_run_health_status or "UNKNOWN"),
        quality="OK" if _run_health_status == "RUN_HEALTHY" else "DEGRADED",
    )

    return {
        "ok": True,
        "run_date": latest.get("date", ""),
        "run_label": latest.get("run_label", ""),
        "run_id": _run_id,
        "setup_run_summary": _setup_run_summary,
        "latest_run_label": _latest_run_label,
        "latest_run_timestamp": _latest_run_timestamp,
        "latest_run_symbols_scanned": latest.get("ticker_count", 0),
        "latest_run_go_count": current_run_go,
        "latest_run_wait_count": current_run_wait,
        "latest_run_no_go_count": current_run_nogo,
        "current_run_scanned": current_run_total,
        "current_run_go": current_run_go,
        "current_run_wait": current_run_wait,
        "current_run_nogo": current_run_nogo,
        "run_health_status": _run_health_status,
        "run_health_reason_codes": _run_health_reason_codes,
        "reason_codes": _run_health_reason_codes,  # alias for UI (same envelope)
        "expected_min_symbols": _expected_min_symbols,
        # 'exact_run' = the health row is this run's. 'latest_today_unmatched' =
        # it is today's most recent, which may be a different run. Published so a
        # surface can qualify the verdict instead of implying a match.
        "run_health_scope": _run_health_scope,
        "run_health_run_label": _run_health_run_label,
        "vix": _vix_val,
        "vix_source": _vix_src,
        "vix_observation_time": _vix_obs,
        "breadth": latest.get("breadth", ""),
        "market_regime": latest.get("breadth", latest.get("market_regime", "Neutral")),
        "go_count": current_run_go,
        "wait_count": current_run_wait,
        "avoid_count": current_run_nogo,
        "ticker_count": current_run_total or latest.get("ticker_count", 0),
        "universe_count": len(tickers),
        "universe_go": go_count,
        "universe_wait": wait_count,
        "universe_nogo": avoid_count,
        "top_ticker": latest.get("top_ticker", ""),
        "top_score": latest.get("top_score", 0),
        "delta_events": latest.get("delta_events", 0),
        "today_strategy_signal_count": _today_signal_count,
        "tickers": tickers,
        "top_gainers": [
            {
                "symbol": g.get("symbol"),
                "change_pct": g.get("change_pct"),
                "operator_pill": f"TOP GAINER · {g.get('change_pct_display', '')}",
                "rvol": g.get("rvol"),
                "price": g.get("price"),
                "float_m": g.get("float_m"),
                "rank": g.get("rank"),
                "source": g.get("source"),
                "captured_at": g.get("captured_at"),
                "stale": bool(g.get("stale")),
            }
            for g in _top_gainer_rows
        ],
        "sectors": dict(sorted(sectors.items(), key=lambda x: -x[1])),
        "run_history": run_history,
        "options_desk": {
            "generated_at": options_desk_summary.get("generated_at"),
            "proposal_count": options_desk_summary.get("proposal_count", 0),
            "strategy_counts": options_desk_summary.get("strategy_counts", {}),
            "top_proposals": (options_desk_summary.get("top_proposals") or [])[:8],
        },
    }


