def _normalize_trade_ai_session_date(data: dict) -> dict:
    """Keep CC SETUPS header current on weekends / between scheduled scans.

    warm_caches → trade_ai(force=True) rebuilds from the latest reports package
    (often yesterday's 1000 label). Without this patch, SETUPS shows STALE every
    8 minutes even when tickers are present. Preserves tickers + GO/WAIT counts.
    """
    if not isinstance(data, dict):
        return data
    try:
        from zoneinfo import ZoneInfo

        today = datetime.now(ZoneInfo("America/New_York")).date().isoformat()
    except Exception:
        from datetime import date as _date

        today = _date.today().isoformat()
    rd = str(data.get("run_date") or data.get("date") or "")[:10]
    if not rd or rd >= today:
        return data
    tickers = data.get("tickers") or []
    if not isinstance(tickers, list):
        tickers = []

    def _dec(t):
        return str((t or {}).get("decision") or "").upper()

    real_label = str(data.get("latest_run_label") or data.get("run_label") or "")
    if real_label in ("", "HEALTH_AUTOHEAL"):
        labels = [str(t.get("scan_run_label") or "") for t in tickers if isinstance(t, dict)]
        labels = [x for x in labels if x and x != "HEALTH_AUTOHEAL"]
        real_label = max(set(labels), key=labels.count) if labels else "1000"
    cur = [t for t in tickers if str((t or {}).get("scan_run_label") or "") == real_label] or tickers
    go_n = sum(1 for t in cur if _dec(t) == "GO")
    wait_n = sum(1 for t in cur if _dec(t) == "WAIT")
    nogo_n = sum(1 for t in cur if _dec(t) not in ("GO", "WAIT", ""))
    data = dict(data)
    data.update(
        {
            "run_date": today,
            "date": today,
            "run_label": real_label,
            "latest_run_label": real_label,
            "go_count": go_n,
            "wait_count": wait_n,
            "avoid_count": nogo_n,
            "latest_run_go_count": go_n,
            "latest_run_wait_count": wait_n,
            "latest_run_no_go_count": nogo_n,
            "current_run_go": go_n,
            "current_run_wait": wait_n,
            "current_run_nogo": nogo_n,
            "current_run_scanned": len(cur),
            "session_date_normalized": {
                "from": rd,
                "to": today,
                "label": real_label,
                "go": go_n,
                "wait": wait_n,
                "nogo": nogo_n,
            },
            "stale": False,
        }
    )
    return data


def _write_trade_ai_cache(path, data: dict) -> None:
    """Atomic cache write — avoids mid-write JSON that forces request-path recompute."""
    import json as _j, os as _os

    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    data = _normalize_trade_ai_session_date(data if isinstance(data, dict) else {})
    tmp = path.with_suffix(path.suffix + f".tmp.{_os.getpid()}")
    tmp.write_text(_j.dumps(data, default=str))
    tmp.replace(path)


def _symbol_headlines(query=None):
    """GET /api/v2/news/symbol-headlines?symbol=X&hours=72 — Home v2 WS-C: GUARDED headlines.

    ONLY rows passing news_symbol_guard.headline_matches_symbol render (session contract:
    zero guarded headlines says so honestly — never padded with unguarded matches)."""
    q = query or {}
    g = lambda k: (q.get(k) or [None])[0] if isinstance(q.get(k), list) else q.get(k)
    sym = (g("symbol") or "").upper().strip()[:8]
    hours = min(int(g("hours") or 72), 168)
    if not sym.isalnum():
        return {"ok": False, "error": "bad symbol"}
    rows = (
        _db_query(
            f"""SELECT title, summary, source, source_url, published_at, sentiment
                         FROM news_articles
                         WHERE upper(symbol) = %s AND published_at > now() - interval '{hours} hours'
                           AND COALESCE(is_duplicate, false) = false
                         ORDER BY published_at DESC LIMIT 40""",
            [sym],
        )
        or []
    )
    try:
        import sys as _s

        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from news_symbol_guard import headline_matches_symbol
    except ImportError:
        headline_matches_symbol = None
    out_rows, rejected = [], 0
    for r in rows:
        if headline_matches_symbol is not None:
            ok, _reason = headline_matches_symbol(sym, r.get("title") or "", r.get("summary") or "")
            if not ok:
                rejected += 1
                continue
        out_rows.append(
            {
                "title": r.get("title"),
                "source": r.get("source"),
                "url": r.get("source_url"),
                "published_at": _json_clean(r.get("published_at")),
                "sentiment": r.get("sentiment"),
            }
        )
        if len(out_rows) >= 12:
            break
    ing = (
        _db_query(
            """SELECT count(*) n, max(published_at) latest FROM news_articles
                       WHERE published_at > now() - interval '72 hours'""",
            fetch="one",
        )
        or {}
    )
    return {
        "ok": True,
        "symbol": sym,
        "headlines": out_rows,
        "guard_rejected": rejected,
        "ingest": {"guarded_72h": _json_clean(ing.get("n")), "latest": _json_clean(ing.get("latest"))},
    }


_HL_COUNTS_MEMO = {"ts": 0.0, "key": None, "data": None}


def _headline_counts(query=None):
    """GET /api/v2/news/headline-counts?symbols=A,B,C — GUARDED headline counts per symbol
    (72h). Lets the Major News grid mark which cells actually have news BEFORE the click
    (operator 2026-07-17: 'major news listed and when i click no news' — cells for names
    with zero guarded rows now say so up front). Guard applied row-by-row; 5-min memo."""
    import time as _t

    q = query or {}
    g = lambda k: (q.get(k) or [None])[0] if isinstance(q.get(k), list) else q.get(k)
    syms = [s.strip().upper() for s in (g("symbols") or "").split(",") if s.strip().isalnum()][:40]
    if not syms:
        return {"ok": False, "error": "no symbols"}
    key = ",".join(sorted(syms))
    now = _t.time()
    m = _HL_COUNTS_MEMO
    if m["data"] is not None and m["key"] == key and now - m["ts"] < 300:
        return dict(m["data"])
    rows = (
        _db_query(
            """SELECT upper(symbol) s, title, summary FROM news_articles
                        WHERE upper(symbol) = ANY(%s)
                          AND published_at > now() - interval '72 hours'
                          AND COALESCE(is_duplicate, false) = false
                        LIMIT 400""",
            [syms],
        )
        or []
    )
    try:
        import sys as _s

        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from news_symbol_guard import headline_matches_symbol as _guard
    except ImportError:
        _guard = None
    counts = {s: 0 for s in syms}
    for r in rows:
        s = r["s"]
        if _guard is not None:
            ok, _ = _guard(s, r.get("title") or "", r.get("summary") or "")
            if not ok:
                continue
        counts[s] = counts.get(s, 0) + 1
    out = {"ok": True, "counts": counts, "hours": 72}
    m.update(ts=now, key=key, data=out)
    return dict(out)


_BOOK_MAP_MEMO = {"etag": None, "data": None}


def _portfolio_book_map(query=None):
    """GET /api/v2/portfolio/book-map — Home v2 WS-B: the operator's book as treemap rows.

    One row per position (symbol×account): value, day change $/%, sector (symbol_profiles;
    missing → Unclassified, visible never dropped), stop overlay (triggered / unprotected
    ≥$10k / no_stop) from the same risk pass the Risk hub uses. ETag on holdings mtime. <10KB."""
    hp = PROJECT_ROOT / "data" / "portfolios" / "state" / "holdings.json"
    if not hp.exists():
        return {"ok": False, "error": "holdings.json missing", "rows": []}
    st = hp.stat()
    etag = f'W/"bmap-{int(st.st_mtime)}-{st.st_size}"'
    if _BOOK_MAP_MEMO["etag"] == etag and _BOOK_MAP_MEMO["data"] is not None:
        return dict(_BOOK_MAP_MEMO["data"])
    h = _load_json(hp) or {}
    sect = {}
    try:
        for r in _db_query("SELECT upper(symbol) s, sector FROM symbol_profiles WHERE sector IS NOT NULL") or []:
            sect[r["s"]] = r["sector"]
    except Exception:
        pass
    stop_state = {}
    try:
        rk = risk() or {}
        for p in rk.get("positions") or []:
            sym = str(p.get("symbol", "")).upper()
            mv = float(p.get("market_value") or 0)
            if (p.get("status") or "").upper() == "TRIGGERED":
                stop_state[(sym, p.get("account"))] = "triggered"
            elif not p.get("has_stop") and not p.get("risk_excluded") and mv >= 10_000:
                stop_state[(sym, p.get("account"))] = "unprotected"
            elif not p.get("has_stop") and not p.get("risk_excluded"):
                stop_state[(sym, p.get("account"))] = "no_stop"
    except Exception:
        pass
    rows = []
    for r in h.get("holdings", []):
        if r.get("is_cash") or not r.get("symbol"):
            continue
        sym = str(r["symbol"]).upper()
        rows.append(
            {
                "symbol": sym,
                "account": r.get("account"),
                "value": round(float(r.get("market_value") or 0), 2),
                "day_change": round(float(r.get("day_change") or 0), 2),
                "day_change_pct": r.get("day_change_pct"),
                "weight_pct": r.get("portfolio_pct"),
                "sector": sect.get(sym) or "Unclassified",
                "stop": stop_state.get((sym, r.get("account"))),
                "delisted": bool(r.get("delisted")) or None,
            }
        )
    out = {
        "ok": True,
        "as_of": h.get("as_of"),
        "rows": rows,
        "total_value": round(sum(x["value"] for x in rows), 2),
        "total_day_change": round(sum(x["day_change"] for x in rows), 2),
        "__etag__": etag,
    }
    _BOOK_MAP_MEMO.update(etag=etag, data=out)
    return dict(out)


def _defense_posture(query=None):
    """GET /api/v2/defense/posture — Defense Desk v1: sector momentum state table +
    confirmed transitions + would-have-fired (hypothetical, labeled). Disk snapshots
    written by sector_momentum_engine (nightly 17:25); cheap reads."""
    out = {"ok": True}
    snap = _load_json(PROJECT_ROOT / "data" / "runtime" / "sector_momentum_latest.json")
    if not snap or not (snap.get("rows") if isinstance(snap, dict) else False):
        # --- Data Broker: sector_momentum as fallback (Phase D wiring) ---
        # When the sector_momentum_engine snapshot is missing (first run, disk error),
        # compute sector-relative-strength live from market_quotes via the broker module.
        try:
            from lib.data_broker.sector_momentum import get_sector_momentum

            bm = get_sector_momentum(db_query=_db_query, max_age_s=300)
            sectors = bm.get("sectors") or {}
            rows = []
            for etf, data in sectors.items():
                rows.append(
                    {
                        "sector": etf,
                        "chg_pct": data.get("chg_pct"),
                        "rel_pct": data.get("rel_pct"),
                        "state": (data.get("label") or "").upper(),
                    }
                )
            snap = {
                "rows": rows,
                "spy_chg_pct": bm.get("spy_chg_pct"),
                "computed_at": bm.get("computed_at"),
                "source": "data_broker.sector_momentum",
                "note": "Broker fallback; snapshot file absent/empty. Sector states are fresh momentum labels only.",
            }
        except Exception:
            snap = {"rows": [], "note": "engine has not run yet"}
    out["momentum"] = snap
    whf = _load_json(PROJECT_ROOT / "data" / "runtime" / "sector_momentum_wouldhavefired.json")
    out["would_have_fired"] = whf or {"hypothetical": True, "transitions": []}
    try:
        caps = _pj_loads((PROJECT_ROOT / "config" / "account_capabilities.json").read_text())
    except Exception:
        caps = None
    out["account_capabilities"] = caps
    # v5 RP3: rotation-plan count chip for the Home posture strip (cheap disk read)
    try:
        recs = _load_json(PROJECT_ROOT / "data" / "runtime" / "defense_recommendations_latest.json") or {}
        armed = sum(
            1 for lad in recs.get("ladders") or [] for t in lad.get("tranches", []) if t.get("status") == "armed"
        )
        fired = sum(
            1 for lad in recs.get("ladders") or [] for t in lad.get("tranches", []) if t.get("status") == "fired"
        )
        out["rotation_plan_counts"] = {
            "plans": len(recs.get("rotation_plan") or []),
            "tranches_armed": armed,
            "tranches_fired": fired,
            "rollback_open": sum(1 for t in recs.get("round_trips") or [] if t.get("status") == "rollback_open"),
        }
    except Exception as e:
        import traceback

        print(f"[defense-posture] rotation_plan_counts failed: {e}\n{traceback.format_exc()}", flush=True)
    try:
        from db_adapter import _get_conn as _hgc

        _hc = _hgc().cursor()
        _hc.execute("""SELECT status, fill_price, symbol FROM defense_order_intents
                       WHERE intent_type='inverse_etf' AND status IN ('filled','armed_ticket','submitted_paper')
                       ORDER BY updated_at DESC LIMIT 1""")
        _hint = _hc.fetchone()
        _hc.execute("""SELECT symbol, threshold, last_fired_at FROM watch_alerts
                       WHERE created_by='defense_hedge' AND note LIKE '%%bounce%%' LIMIT 1""")
        _bounce = _hc.fetchone()
        _rows = (out.get("momentum") or {}).get("rows") or []
        _tech = next((r for r in _rows if r.get("sector") == "Technology"), {})
        if _tech.get("state") not in ("LAGGING", "WEAKENING", None) and _hint:
            hs = {
                "state": "stand_down",
                "line": f"HEDGE: stand-down signaled — Technology recovered to {_tech.get('state')}",
            }
        elif _hint and _hint[0] == "filled":
            _hc.execute(
                """SELECT close_price FROM ticker_prices WHERE symbol=%s
                           ORDER BY price_date DESC LIMIT 1""",
                (_hint[2],),
            )
            _px = _hc.fetchone()
            _pl = round((float(_px[0]) - float(_hint[1])) / float(_hint[1]) * 100, 1) if _px and _hint[1] else None
            hs = {
                "state": "in_play",
                "line": f"HEDGE: {_hint[2]} in play" + (f" {_pl:+.1f}%" if _pl is not None else ""),
            }
        elif _bounce and _bounce[2] and str(_bounce[2])[:10] == datetime.now(timezone.utc).date().isoformat():
            hs = {
                "state": "entry_window_open",
                "line": f"HEDGE: entry window OPEN — {_bounce[0]} bounce ≥ ${_bounce[1]}",
            }
        else:
            hs = {
                "state": "armed",
                "line": f"HEDGE: waiting for a bounce day ({_bounce[0]} ≥ ${_bounce[1]})"
                if _bounce
                else "HEDGE: alerts arming tonight",
            }
        out["hedge_state"] = hs
    except Exception as e:
        import traceback

        print(f"[defense-posture] hedge_state failed: {e}\n{traceback.format_exc()}", flush=True)
    try:
        sl = _load_json(PROJECT_ROOT / "data" / "runtime" / "inverse_stoplights_latest.json")
        active = [c for c in (sl or {}).get("candidates", []) if c["lights"]["THESIS"]["state"] != "RED"]
        if active:
            c0 = active[0]
            L = c0["lights"]
            out["inverse_stoplights"] = {
                "line": (
                    f"🚦 {c0['inverse']}/{c0['bench']}: THESIS {L['THESIS']['state']} · "
                    f"ENTRY {L['ENTRY']['state']} — {L['ENTRY']['label']}"
                ),
                "tip": L["ENTRY"].get("reason", ""),
            }
    except Exception as e:
        import traceback

        print(f"[defense-posture] inverse_stoplights failed: {e}\n{traceback.format_exc()}", flush=True)
    try:
        bm = _portfolio_book_map() or {}
        ov_val = None
        try:
            ov = _load_json(PROJECT_ROOT / "data" / "portfolios" / "state" / "holdings.json") or {}
            cash = sum(float(r.get("market_value") or 0) for r in ov.get("holdings", []) if r.get("is_cash"))
            ov_val = cash
        except Exception as e2:
            import traceback

            print(f"[defense-posture] net_exposure holdings parse failed: {e2}\n{traceback.format_exc()}", flush=True)
        eq = float(bm.get("total_value") or 0)
        if ov_val is not None and eq:
            tot = eq + ov_val
            out["net_exposure"] = {
                "equity_pct": round(eq / tot * 100, 1),
                "cash_pct": round(ov_val / tot * 100, 1),
                "equity_dollars": round(eq),
                "cash_dollars": round(ov_val),
            }
    except Exception as e:
        import traceback

        print(f"[defense-posture] net_exposure failed: {e}\n{traceback.format_exc()}", flush=True)
    # Grok OAuth proxy health check — the desk needs to know if Grok is reachable
    try:
        import urllib.request

        req = urllib.request.Request("http://127.0.0.1:8645/health", method="GET")
        with urllib.request.urlopen(req, timeout=3) as resp:
            out["grok_proxy_health"] = {"available": resp.status == 200, "status": resp.status}
    except Exception:
        out["grok_proxy_health"] = {"available": False, "status": 0}
    # Defense engine gap summary — reads the gap checker ledger for frontend chips
    try:
        gaps_json = _load_json(PROJECT_ROOT / "data" / "runtime" / "defense_engine_gaps.json")
        out["engine_gaps"] = gaps_json or {"gaps": [], "last_check": None}
    except Exception:
        out["engine_gaps"] = {"gaps": [], "last_check": None}
    # LLM Timeline — last-run and next-scheduled for every oversight + rotation seat
    out["llm_timeline"] = _build_llm_timeline()
    # Data Rhythm — schedule + freshness of every data producer the desk consumes
    out["data_rhythm"] = _build_data_rhythm()
    return out


def _build_llm_timeline():
    try:
        ov = _oversight_latest() or {}
        seats = ov.get("seats", {})
        from datetime import time

        et = timezone(timedelta(hours=-4))
        now_utc = datetime.now(timezone.utc)
        seats_timeline = {}
        for name, s in seats.items():
            at = s.get("at") if isinstance(s, dict) else None
            status = s.get("status", "?") if isinstance(s, dict) else "?"
            if at:
                try:
                    at_dt = datetime.strptime(str(at)[:16], "%Y-%m-%d %H:%M")
                    at_utc = at_dt.replace(tzinfo=et).astimezone(timezone.utc)
                    age_m = round((now_utc - at_utc).total_seconds() / 60, 1)
                except Exception:
                    age_m = None
            else:
                age_m = None
            seats_timeline[name] = {"last_run": str(at)[:16] if at else None, "status": status, "age_m": age_m}
        windows = [
            {
                "label": "AM build",
                "et": "10:30",
                "utc_hour": 14,
                "utc_min": 30,
                "seats": ["deepseek", "chatgpt", "grok"],
            },
            {
                "label": "PM build",
                "et": "17:50",
                "utc_hour": 21,
                "utc_min": 50,
                "seats": ["deepseek", "chatgpt", "grok"],
            },
            {
                "label": "Weekly paid",
                "et": "Fri 18:15",
                "utc_day": 4,
                "utc_hour": 22,
                "utc_min": 15,
                "seats": ["paid_ds", "paid", "paid_gpt", "paid_xai"],
            },
        ]
        schedule = []
        for w in windows:
            if "utc_day" in w:
                d = (w["utc_day"] - now_utc.weekday()) % 7
                nd = now_utc.replace(hour=w["utc_hour"], minute=w["utc_min"], second=0, microsecond=0)
                if d == 0 and nd <= now_utc:
                    d = 7
                next_dt = nd + timedelta(days=d)
            else:
                nd = now_utc.replace(hour=w["utc_hour"], minute=w["utc_min"], second=0, microsecond=0)
                next_dt = nd if nd > now_utc else nd + timedelta(days=1)
            schedule.append(
                {
                    "label": w["label"],
                    "et": w["et"],
                    "next_utc": next_dt.isoformat(),
                    "next_et": next_dt.astimezone(et).strftime("%a %H:%M ET"),
                    "in_min": round((next_dt - now_utc).total_seconds() / 60, 1),
                    "seats": w["seats"],
                }
            )
        return {"seats": seats_timeline, "schedule": schedule, "generated_at": now_utc.isoformat()}
    except Exception:
        return {"seats": {}, "schedule": [], "generated_at": None}


def _build_data_rhythm():
    """Returns schedule + freshness for every defense data producer, with stoplight age bands."""
    from datetime import time

    et = timezone(timedelta(hours=-4))
    now_utc = datetime.now(timezone.utc)
    now_et = now_utc.astimezone(et)

    # Age → stoplight: green ≤6h, yellow ≤24h (1d), amber ≤5d, red >5d
    def light(iso: str | None):
        if not iso:
            return "red", "never"
        try:
            age_m = round((now_utc - datetime.fromisoformat(iso.replace("Z", "+00:00"))).total_seconds() / 60, 1)
            label = (
                f"{age_m:.0f}m" if age_m < 60 else f"{age_m / 60:.1f}h" if age_m < 48 * 60 else f"{age_m / 1440:.1f}d"
            )
            if age_m <= 360:
                return "green", label
            if age_m <= 1440:
                return "yellow", label
            if age_m <= 7200:
                return "amber", label
            return "red", label
        except Exception:
            return "red", "parse_err"

    rhythm = {"producers": [], "generated_at": now_utc.isoformat()}

    # Read each snapshot file's age
    snapshots = [
        (
            "sectors",
            "data/runtime/sector_momentum_latest.json",
            "generated_at",
            "Daily 17:25 ET · ranks, states, transitions",
        ),
        (
            "industries",
            "data/runtime/industry_momentum_latest.json",
            "generated_at",
            "2× daily 12:30 (display) + 16:18 ET (close·debounce)",
        ),
        (
            "recommendations",
            "data/runtime/defense_recommendations_latest.json",
            "generated_at",
            "2× daily 10:30 + 17:50 ET · trim ladders, plan, oversight",
        ),
        (
            "inverse_stoplights",
            "data/runtime/inverse_stoplights_latest.json",
            "generated_at",
            "2× daily 10:15 + 17:55 ET · inverse-ETF entry gates",
        ),
        (
            "cash_alternatives",
            "data/runtime/defense_cash_alternatives_latest.json",
            "generated_at",
            "Daily 17:15 ET · conservative cash vehicles",
        ),
        (
            "hedging_radar",
            "data/runtime/hedging_radar_latest.json",
            "generated_at",
            "2× daily 10:00 + 17:35 ET · option chain snapshots",
        ),
    ]
    for key, path, ts_field, schedule in snapshots:
        s = _load_json(PROJECT_ROOT / path) or {}
        ts = (s.get(ts_field) or s.get("captured_at")) if isinstance(s, dict) else None
        clr, age_label = light(str(ts) if ts else None)
        rhythm["producers"].append(
            {
                "key": key,
                "schedule": schedule,
                "last_run": str(ts)[:19] if ts else None,
                "age_label": age_label,
                "light": clr,
            }
        )
    # Engine gaps
    gaps = _load_json(PROJECT_ROOT / "data/runtime/defense_engine_gaps.json") or {}
    clr, age_label = light(str(gaps.get("last_check")) if gaps.get("last_check") else None)
    rhythm["producers"].append(
        {
            "key": "gap_checker",
            "schedule": "2× daily 10:16 + 17:56 ET · stale-sector watchdog",
            "last_run": str(gaps.get("last_check"))[:19] if gaps.get("last_check") else None,
            "age_label": age_label,
            "light": clr,
        }
    )
    return rhythm


