def _defense_chain_validate(body=None):
    """POST /api/v2/defense/chain/validate {symbol, strike, exp, delta} — WS-CHAIN:
    fresh single-contract pull (throttled) → rails verdict rows + drift suggestion.
    The trade control is gated on this being ≤15 min old (client + returned ts)."""
    body = body or {}
    sym = str(body.get("symbol", "")).upper()[:8]
    strike = float(body.get("strike") or 0)
    exp = str(body.get("exp", ""))[:10]
    want_delta = float(body.get("delta") or 0.28)
    if not (sym and strike and exp):
        return {"ok": False, "error": "symbol/strike/exp required"}
    from schwab_transport import get_option_chain

    # strike_count is an ATM-CENTRED window, not a filter. 14 covered roughly
    # +/-8% for SPCX, so a legitimately-listed 141.0 strike (15.7% OTM) reported
    # "not found in the live chain" while Schwab returns it fine at 40
    # (verified 2026-07-20: 14 -> 85.0..139.0, 40 -> 25.0..152.5).
    # Covered-call recommendations routinely sit 15-16% OTM (ANET 200.0 vs
    # 172.20 is +16.1%), so the window must cover the strikes we ourselves
    # propose. Same class as the lifecycle 16->48 widening.
    ch = get_option_chain(sym, strike_count=48)
    if not ch or ch.get("status") != "ok":
        return {"ok": False, "error": "chain unavailable"}
    import json as _j

    vc = _pj_loads((PROJECT_ROOT / "config" / "defense_recommendations.json").read_text())["cc_validation"]
    target, best_alt = None, None
    for e in ch.get("expirations", []):
        for s in e.get("strikes", []):
            if s["side"] != "call" or s.get("delta") is None:
                continue
            ad = abs(float(s["delta"]))
            if e["exp"] == exp and abs(s["strike"] - strike) < 0.01:
                target = {**s, "ad": ad}
            if e["exp"] == exp and abs(ad - want_delta) < 0.05:
                if best_alt is None or abs(ad - want_delta) < abs(best_alt["ad"] - want_delta):
                    best_alt = {**s, "ad": ad}
    now_ts = datetime.now(timezone.utc).isoformat()
    if not target:
        return {"ok": False, "error": f"{sym} {exp} ${strike}C not found in the live chain", "validated_at": now_ts}
    mid = ((target.get("bid") or 0) + (target.get("ask") or 0)) / 2
    spread_pct = round(((target.get("ask") or 0) - (target.get("bid") or 0)) / mid * 100, 1) if mid else 999
    rows = [
        {
            "rail": "open interest",
            "value": target.get("oi") or 0,
            "need": f"≥{vc['min_open_interest']}",
            "pass": (target.get("oi") or 0) >= vc["min_open_interest"],
        },
        {
            "rail": "volume/OI",
            "value": max(target.get("volume") or 0, target.get("oi") or 0),
            "need": f"≥{vc['min_volume_or_oi']}",
            "pass": max(target.get("volume") or 0, target.get("oi") or 0) >= vc["min_volume_or_oi"],
        },
        {
            "rail": "spread % of mid",
            "value": spread_pct,
            "need": f"≤{vc['max_spread_pct_of_mid']}%",
            "pass": spread_pct <= vc["max_spread_pct_of_mid"],
        },
        {
            "rail": "delta",
            "value": round(target["ad"], 2),
            "need": f"{vc['delta_band'][0]}–{vc['delta_band'][1]}",
            "pass": vc["delta_band"][0] <= target["ad"] <= vc["delta_band"][1],
        },
    ]
    drift = None
    if (
        (abs(target["ad"] - want_delta) > 0.05 or spread_pct > 6)
        and best_alt
        and abs(best_alt["strike"] - strike) > 0.01
    ):
        drift = {
            "line": f"${strike}C Δ{round(target['ad'], 2)} → suggest ${best_alt['strike']}C Δ{round(best_alt['ad'], 2)}",
            "suggested_strike": best_alt["strike"],
            "requires_restage": True,
        }
    return {
        "ok": True,
        "validated_at": now_ts,
        "all_pass": all(r["pass"] for r in rows),
        "rows": rows,
        "book": {"bid": target.get("bid"), "ask": target.get("ask"), "mid": round(mid, 2), "iv": target.get("iv")},
        "drift": drift,
    }


def _defense_cc_queue_trade(body=None):
    """POST /api/v2/defense/cc/queue-trade — the CC card's 'queue trade (2FA)' bubble.
    Inserts a pending row into options_approval_queue; the EXISTING approvals flow +
    per-order 2FA owns everything downstream. The desk itself never places orders."""
    body = body or {}
    cs = body.get("cc_struct") or {}
    sym = str(cs.get("symbol", "")).upper()[:8]
    if not (sym and cs.get("strike") and cs.get("exp") and cs.get("contracts")):
        return {"ok": False, "error": "cc_struct{symbol,strike,exp,contracts} required"}
    # Operator acknowledgement of earnings inside the contract, carried from the
    # card's tick-box. It is only ever an INPUT to the risk evaluation below —
    # evaluate_hard_risk_blocks decides whether it actually applies, and refuses
    # any acknowledgement that does not name the exact earnings date it is
    # blocking on. The server never fabricates one (2026-07-20).
    _op_ack = body.get("operator_ack")
    _op_ack = _op_ack if isinstance(_op_ack, dict) else None
    # A card that demands acknowledgement may not be queued without it.
    if cs.get("requires_ack") and not _op_ack:
        return {
            "ok": False,
            "error": "operator_ack required — this contract spans earnings",
            "blocks": [
                {
                    "code": "EARNINGS_INSIDE_CONTRACT",
                    "reason": f"{sym} earnings {cs.get('earnings_date')} fall before "
                    f"expiration {cs.get('exp')}; acknowledge to queue",
                }
            ],
        }
    from db_adapter import _get_conn
    import json as _j

    # live_eligible was hardcoded false with blocks_json '[]' — an incoherent
    # pair ("ineligible, for no stated reason") that made every Defense-queued
    # covered call PERMANENTLY unapprovable and therefore unable to ever reach
    # the 2FA/submit step, contradicting this function's own contract that the
    # approvals flow + per-order 2FA own everything downstream (2026-07-20).
    # Evaluate for real: eligible iff no hard block, and record the blocks so a
    # refusal always states its reason.
    conn = _get_conn()
    cur = conn.cursor()
    pid = f"defense-cc-{sym}-{str(cs['exp'])[:10]}-{cs['strike']}"
    proposal = {
        "id": pid,
        "symbol": sym,
        "strategy": "covered_call",
        "source": "defense_desk_v6",
        "account": cs.get("account"),
        "contracts": cs["contracts"],
        "strike": cs["strike"],
        "exp": cs["exp"],
        "delta": cs.get("delta"),
        "mid": cs.get("mid"),
        "premium_est": cs.get("premium_est"),
        "note": "queued from the Defense CC card — greeks/liquidity validated at snapshot time",
    }
    if _op_ack:
        # Persisted on the proposal so the SAME acknowledgement is re-evaluated
        # at approval and preflight, not just at queue time.
        proposal["operator_ack"] = _op_ack
    # NOTE: this evaluation must run AFTER `proposal` exists. It previously sat
    # above the assignment and raised NameError into its own except, so every
    # queued row silently got block_eval_failed and live_eligible=False —
    # reintroducing the very "ineligible for no stated reason" state this code
    # was added to remove (caught 2026-07-20).
    try:
        import options_desk_enterprise as _ent

        _cc_blocks = _ent.evaluate_hard_risk_blocks(proposal, mode="submit") or []
    except Exception as _ce:
        _cc_blocks = [
            {
                "code": "block_eval_failed",
                "reason": f"could not evaluate risk blocks: {type(_ce).__name__}: {_ce}"[:200],
            }
        ]
    _cc_live_eligible = not _cc_blocks
    cur.execute(
        """INSERT INTO options_approval_queue
           (proposal_id, symbol, strategy, desk_tier, edge_score, status,
            live_eligible, blocks_json, proposal_json, expires_at)
           VALUES (%s,%s,'covered_call','C',NULL,'pending',%s,%s::jsonb,%s::jsonb,
                   NOW() + INTERVAL '24 hours')
           ON CONFLICT (proposal_id) DO UPDATE SET proposal_json=EXCLUDED.proposal_json,
             live_eligible=EXCLUDED.live_eligible, blocks_json=EXCLUDED.blocks_json,
             status=CASE WHEN options_approval_queue.status IN ('approved','rejected','executed')
                        THEN options_approval_queue.status ELSE 'pending' END,
             updated_at=NOW()""",
        (pid, sym, _cc_live_eligible, _j.dumps(_cc_blocks, default=str), _j.dumps(proposal, default=str)),
    )
    conn.commit()

    # QUEUE STATUS HONESTY (2026-07-20).
    # A row can land in the queue and STILL carry a hard block — an acknowledged
    # earnings risk clears only the earnings block, and something like
    # no_resolved_occ survives it. Reporting that as a flat success and telling
    # the operator to "approve, then SUBMIT" recreates the exact CSCO failure
    # this desk was repaired for: a green confirmation followed by a refusal the
    # system already knew about. The write succeeded either way; what differs is
    # whether the thing that was written can actually be actioned, so say which.
    if _cc_live_eligible:
        return {
            "ok": True,
            "status": "QUEUED_REVIEWABLE",
            "proposal_id": pid,
            "blocks": [],
            "actionable": True,
            "next": "pending in the options approval queue — approve there; per-order 2FA gates execution",
        }
    return {
        "ok": True,
        "status": "QUEUED_BLOCKED",
        "proposal_id": pid,
        "blocks": _cc_blocks,
        "actionable": False,
        "next": "QUEUED FOR RESEARCH — cannot be approved or submitted while these "
        "blocks stand: " + "; ".join(f"{b.get('code')}: {b.get('reason')}" for b in _cc_blocks),
    }


def _shadow_batch_status(query=None):
    """GET /api/v2/shadow/strategy/batch — progress of the bounded batch run."""
    import shadow_batch_generator as bg

    return {"ok": True, **bg.status()}


def _shadow_batch_start(body=None):
    """POST /api/v2/shadow/strategy/batch — the 'run adhoc batch' button.

    SHADOW ONLY. Spawns the bounded batch generator DETACHED (top-N by rank in the
    eligible ratings + all starred), returns immediately. Idempotent: a run
    already in flight is reported rather than started twice."""
    import shadow_batch_generator as bg

    st = bg.status()
    if st.get("state") == "running":
        return {
            "ok": True,
            "started": False,
            "already_running": True,
            "done": st.get("done"),
            "to_generate": st.get("to_generate"),
        }
    import subprocess

    body = body or {}
    cmd = [
        str(PROJECT_ROOT / ".venv" / "bin" / "python"),
        str(PROJECT_ROOT / "scripts" / "shadow_batch_generator.py"),
        "--run",
    ]
    if body.get("top"):
        cmd += ["--top", str(int(body["top"]))]
    if body.get("force"):
        cmd.append("--force")
    subprocess.Popen(
        cmd, cwd=PROJECT_ROOT, start_new_session=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL
    )
    return {"ok": True, "started": True}


def _decision_action_policy(query=None):
    """GET /api/v2/decision/action-policy?symbol=X — the canonical action decision
    for a symbol's latest live packet. Same evaluator the card renders inline, so
    this is the parity reference: the card cannot advertise an action this refuses.
    Read-only; advisory (upstream of approval + per-order 2FA)."""
    query = query or {}
    sym = query.get("symbol")
    if isinstance(sym, (list, tuple)):
        sym = sym[0] if sym else None
    if not sym:
        return {"ok": False, "error": "symbol required"}
    import decision_action_policy as _pol

    row = _db_query(
        """SELECT packet_id, packet, generated_at FROM decision_packets
                       WHERE upper(symbol)=upper(%s) AND superseded_by IS NULL
                       ORDER BY generated_at DESC LIMIT 1""",
        (str(sym),),
        fetch="one",
    )
    if not row:
        return {
            "ok": True,
            "symbol": str(sym).upper(),
            "action_policy": None,
            "note": "no live packet — LEGACY FALLBACK, build a packet first",
        }
    pkt = row["packet"] if isinstance(row["packet"], dict) else json.loads(row["packet"])
    try:
        import decision_packet as _dp

        pkt = _dp.materialize_packet(pkt)
    except Exception:
        pass
    op = set()
    try:
        _pr = (
            _db_query(
                """SELECT 1 FROM options_approval_queue
                           WHERE upper(symbol)=upper(%s) AND status IN ('pending','approved') LIMIT 1""",
                (str(sym),),
            )
            or []
        )
        op = bool(_pr)
    except Exception:
        op = False
    import packet_invalidation as _inv
    from db_adapter import _get_conn as _gc

    try:
        _snap = _inv.build_current_input_snapshot(str(sym), _gc())
    except Exception:
        _snap = None
    res = _pol.evaluate_action(
        pkt,
        packet_id=row["packet_id"],
        generated_at=str(row["generated_at"]),
        existing_proposal=bool(op),
        current_snapshot=_snap,
    )
    return {"ok": True, "symbol": str(sym).upper(), "action_policy": res, "packet": pkt, "current_snapshot": _snap}


