def _refresh_trade_ai_cache_age(data: dict, now: float) -> dict:
    """Recompute cache_age_sec / stale from _cached_ts (request-path, not durable).

    `stale` here means warm-cache TTL exceeded (~600s) — a refresh signal for
    warm_caches consumers. Operator chrome must NOT treat it as SETUPS STALE
    by itself (see tradeAiSurfaceFreshness). Always recompute on serve so
    in-memory hits and JSON body-cache etags cannot freeze a pre-TTL snapshot.
    """
    if not isinstance(data, dict):
        return data
    try:
        age = float(now) - float(data.get("_cached_ts") or 0)
    except (TypeError, ValueError):
        age = 1e9
    if age < 0:
        age = 0.0
    data["cached_at"] = data.get("_cached_at") or data.get("cached_at")
    data["cache_age_sec"] = round(age)
    data["stale"] = bool(data.get("cache_missing")) or age > 600
    return data


def _trade_ai_with_etag(data, disk=None):
    """Shallow-copy + attach content ETag so json_response can 304 / body-cache.

    Must not mutate the in-memory cache dict — json_response pops __etag__.

    ETag includes a minute age-band: /api/v2 JSON body cache keys by etag alone
    (_stamp_serving age_bucket is /api/v3-only), so a fixed mtime+size etag used
    to freeze stale=false / cache_age_sec from the first post-warm serialize while
    /trade-ai/summary (no etag) showed live age — header SETUPS STALE vs Trading
    page not STALE SESSION with the same cached_at (2026-09-01).
    """
    if not isinstance(data, dict):
        return data
    out = dict(data)
    try:
        age_band = int(out.get("cache_age_sec") or 0) // 60
        if disk is not None and getattr(disk, "exists", lambda: False)() and disk.exists():
            st = disk.stat()
            out["__etag__"] = f'W/"tai-{int(st.st_mtime)}-{st.st_size}-m{age_band}"'
        else:
            n = len(out.get("tickers") or [])
            ts = int(_TRADE_AI_CACHE.get("ts") or 0)
            out["__etag__"] = f'W/"tai-mem-{ts}-{n}-m{age_band}"'
    except Exception:
        out["__etag__"] = 'W/"tai-fallback"'
    return out


def trade_ai(force=False):
    """GET /api/v2/trade-ai — served from a disk cache (data/runtime/trade_ai_cache.json) refreshed by
    warm_caches.py. The compute is heavy (run JSONs + a hundreds-row trade_ai_scans scan); running it
    in the request path hangs all DASHBOARD_MAX_CONCURRENCY threads (~250s each) and wedges the
    dashboard (2026-06-25 reconnection outage; 2026-07-16 CLOSE-WAIT pileup). Stale is served
    (flagged) rather than blocking. force=True (warm cron) recomputes + rewrites the cache.

    NEVER fall through to _compute_trade_ai on the live request path if any cache exists — a
    torn mid-write read used to parse-fail and trigger full recompute under load.

    Always attaches __etag__ (disk mtime+size + age-band) so concurrent CC polls 304 / reuse a
    serialized body instead of re-json.dumps a ~1.7MB payload under load (scanner timeout
    2026-07-17), without freezing TTL flags across minutes.
    """
    import time as _t, json as _j, datetime as _dt

    # Defense-in-depth: only a literal True forces the heavy compute. The route dispatcher
    # passes the query DICT to 1-param handlers — a truthy dict here silently became
    # force=True on every cache-busted poll (the 2026-06-25..07-17 server-busy root cause).
    force = force is True
    _disk = PROJECT_ROOT / "data" / "runtime" / "trade_ai_cache.json"
    _now = _t.time()
    if not force:
        # 1) in-memory fresh (<2m) — still refresh TTL fields so age/stale move
        if _TRADE_AI_CACHE["data"] and (_now - _TRADE_AI_CACHE["ts"] < 120):
            _d = dict(_TRADE_AI_CACHE["data"])
            _refresh_trade_ai_cache_age(_d, _now)
            _TRADE_AI_CACHE["data"] = _d
            return _trade_ai_with_etag(_d, _disk)
        # 2) disk cache — serve fresh OR stale without a heavy recompute in the request path
        for _attempt in (1, 2):
            try:
                if _disk.exists():
                    _raw = _disk.read_text()
                    if not _raw or not _raw.strip():
                        raise ValueError("empty trade_ai cache")
                    _d = _j.loads(_raw)
                    _d = _normalize_trade_ai_session_date(_d)
                    _refresh_trade_ai_cache_age(_d, _now)
                    # Persist session date bump so warm_caches consumers stay current
                    if _d.get("session_date_normalized"):
                        try:
                            _write_trade_ai_cache(_disk, _d)
                        except Exception:
                            pass
                    _age = float(_d.get("cache_age_sec") or 0)
                    _TRADE_AI_CACHE.update(ts=_now - min(_age, 119), data=_d)
                    return _trade_ai_with_etag(_d, _disk)
            except Exception:
                # brief retry — warm_caches may have been mid-replace without atomic write (legacy)
                if _attempt == 1:
                    _t.sleep(0.05)
                    continue
                # Prefer last good in-memory over a 4-minute request-path recompute
                if _TRADE_AI_CACHE["data"]:
                    _d = dict(_TRADE_AI_CACHE["data"])
                    _d["stale"] = True
                    _d["cache_error"] = "disk_read_failed_served_memory"
                    return _trade_ai_with_etag(_d, _disk)
        # 3) no disk cache and no memory — return light stub; warm_caches will fill it
        return _trade_ai_with_etag(
            {
                "ok": False,
                "error": "trade_ai cache not ready — warm_caches still building",
                "go_count": 0,
                "wait_count": 0,
                "avoid_count": 0,
                "tickers": [],
                "stale": True,
                "cache_missing": True,
            },
            _disk,
        )
    data = _compute_trade_ai()
    # Fail-closed guard (2026-07-17): during the Postgres slot exhaustion _db_query returned
    # None, the compute produced 0 tickers, and the warm cron overwrote a good 1.7MB cache
    # with an empty one — every consumer then showed a legitimate-looking zero-row scan.
    # An empty compute NEVER replaces a non-empty cache; keep serving last-good, flagged stale.
    if not (data.get("tickers") if isinstance(data, dict) else None):
        try:
            if _disk.exists():
                _old = _j.loads(_disk.read_text())
                if isinstance(_old, dict) and _old.get("tickers"):
                    print(
                        "  [trade_ai] compute returned 0 tickers — refusing to overwrite "
                        "non-empty cache (fail-closed; check DB connectivity)"
                    )
                    _refresh_trade_ai_cache_age(_old, _now)
                    _old["stale"] = True
                    _old["cache_error"] = "empty_compute_kept_last_good"
                    _age = float(_old.get("cache_age_sec") or 0)
                    _TRADE_AI_CACHE.update(ts=_now - min(_age, 119), data=_old)
                    return _trade_ai_with_etag(_old, _disk)
        except Exception:
            pass
    try:
        data["_cached_ts"] = _now
        data["_cached_at"] = _dt.datetime.now(_dt.timezone.utc).isoformat()
        _write_trade_ai_cache(_disk, data)
    except Exception:
        pass
    _refresh_trade_ai_cache_age(data, _now)
    _TRADE_AI_CACHE.update(ts=_now, data=data)
    return _trade_ai_with_etag(data, _disk)


_TRADE_AI_SCANNER_CACHE = {"etag": None, "data": None}

# Plain-AVOID universe rows are never rendered as table rows (no AVOID filter in the UI) —
# they only feed the Universe copy list, KPI count fallbacks, and the Central Intelligence
# score>=30 sweep. These keys cover every field those paths read (scannerSelection.ts sort
# keys + CentralIntelligencePages catalyst??reason??sector fallback chain).
_TRADE_AI_TRIM_KEYS = (
    "symbol",
    "decision",
    "score",
    "grade",
    "rvol",
    "change_pct",
    "gap_pct",
    "price",
    "volume",
    "float_m",
    "sector",
    "source",
    "catalyst",
    "reason",
)

# Any of these mark a row the scanner CAN render (social/manual/awareness lanes surface
# rows whose decision is AVOID) — such rows must keep every field the pills read.
_TRADE_AI_FLAG_KEYS = (
    "scout_status",
    "awareness_status",
    "setup_class",
    "operator_color_token",
    "operator_pill",
    "manual_review_required",
    "disqualified",
)


def trade_ai_scanner():
    """GET /api/v2/trade-ai/scanner — scanner-grade slim projection of /trade-ai.

    The full payload is ~1.7MB and 95% of it is plain-AVOID universe rows
    (1,154/1,198 on 2026-07-17) that the scanner never renders. Under load the
    multi-MB transfer × concurrent 60s polls is what blew the 30s watchdog and
    500-looped the Market Opportunities Scanner. Full rows are kept for
    actionable (GO/WAIT/MANUAL_REVIEW) and pill-flagged rows; the rest shrink
    to _TRADE_AI_TRIM_KEYS. Result is memoized per underlying cache generation
    (base ETag) so concurrent polls don't re-trim 1,200 rows.
    """
    d = trade_ai() or {}
    if not isinstance(d, dict):
        return d
    base_etag = d.get("__etag__")
    cached = _TRADE_AI_SCANNER_CACHE
    if base_etag and cached["etag"] == base_etag and cached["data"] is not None:
        # fresh copy per request — json_response pops __etag__ from what we hand it
        return dict(cached["data"])
    out = {k: v for k, v in d.items() if k not in ("tickers", "__etag__")}
    slim = []
    for row in d.get("tickers") or []:
        if not isinstance(row, dict):
            continue
        dec = str(row.get("decision") or "").upper()
        if dec in ("GO", "WAIT", "MANUAL_REVIEW") or any(row.get(k) for k in _TRADE_AI_FLAG_KEYS):
            slim.append(row)
        else:
            slim.append({k: row[k] for k in _TRADE_AI_TRIM_KEYS if k in row})
    out["tickers"] = slim
    out["slim"] = True
    if base_etag:
        out["__etag__"] = f'W/"scan-{base_etag.strip(chr(34)).replace("W/", "").strip(chr(34))}"'
        _TRADE_AI_SCANNER_CACHE.update(etag=base_etag, data=out)
        return dict(out)
    return out


# ── Journal Review Layer ──────────────────────────────────────────────────


def _db_write(sql, params=None):
    """Run a DB write (INSERT/UPDATE). Returns row dict or None."""
    try:
        import sys

        sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from db_adapter import _get_conn, USE_DB

        if not USE_DB:
            return None
        conn = _get_conn()
        import psycopg2.extras

        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
        cur.execute(sql, params)
        conn.commit()
        try:
            return dict(cur.fetchone()) if cur.description else None
        except Exception:
            return None
    except Exception as e:
        print(f"  [api_v2] _db_write error: {e}")
        return None


