def _local_llm_status_api():
    """GET /api/v2/local-llm-status — local LLM availability and run history."""
    try:
        # Central config
        _cfg_model = get_local_llm_model()
        _cfg_base = get_local_llm_base_url().rstrip("/")
        _llm_status = get_local_llm_status()

        # Check Ollama availability
        ollama_available = False
        ollama_models = []
        last_error = None
        try:
            import urllib.request as _ur

            req = _ur.Request(f"{_cfg_base}/api/tags", method="GET")
            with _ur.urlopen(req, timeout=5) as resp:
                import json as _j

                data = _j.loads(resp.read())
                ollama_models = [m.get("name", "") for m in data.get("models", [])]
                ollama_available = True
        except Exception as _e:
            last_error = str(_e)

        # Last run
        last_run = _db_query(
            """
            SELECT id, model_name, status, run_type, started_at, finished_at,
                   duration_sec, items_processed, items_failed, last_error
            FROM local_llm_runs ORDER BY started_at DESC LIMIT 1
        """,
            fetch="one",
        )

        # Awaiting analysis
        awaiting_trades = (
            _db_query(
                """
            SELECT COUNT(*) as cnt FROM paper_trades
            WHERE status='closed' AND (post_trade_analyzed IS NOT TRUE)
        """,
                fetch="one",
            )
            or {}
        )

        # "awaiting analysis" = non-terminal proposals that still lack an LLM analysis row.
        # (Was counting EXPIRED/REJECTED — terminal proposals that will NEVER be analyzed — inflating
        #  the backlog to a scary stale 530 and making the lane look stalled when it is idle-correct.)
        awaiting_proposals = (
            _db_query(
                """
            SELECT COUNT(*) as cnt FROM paper_trade_proposals p
            WHERE upper(p.status) NOT IN ('EXPIRED', 'REJECTED', 'RISK_BLOCKED', 'CANCELLED', 'FILLED', 'CLOSED')
              AND NOT EXISTS (SELECT 1 FROM paper_proposal_analysis a WHERE a.proposal_id = p.id)
        """,
                fetch="one",
            )
            or {}
        )

        result = {
            "ok": True,
            "local_llm": {
                "provider": _llm_status.get("provider", "ollama"),
                "model": _cfg_model,
                "base_url": _cfg_base,
                "backend": _llm_status.get("backend", "vulkan"),
                "require_gpu": _llm_status.get("require_gpu", True),
                "runtime_env": _llm_status.get("runtime_env", {}),
                "available": ollama_available,
                "loaded_models": ollama_models,
                "last_error": last_error,
            },
            "available": ollama_available,
            "model": _cfg_model,
            "ollama_host": _cfg_base,
            "trades_awaiting_analysis": awaiting_trades.get("cnt", 0),
            "proposals_awaiting_analysis": awaiting_proposals.get("cnt", 0),
        }
        if not ollama_available:
            result["reason"] = "Ollama not reachable"
        if last_run:
            result["last_run"] = _json_clean(last_run.get("started_at"))
            result["last_status"] = last_run.get("status")
            result["items_processed_last_run"] = last_run.get("items_processed", 0)
        return result
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _incubator_api():
    """GET /api/v2/incubator — incubator universe with lifecycle state."""
    try:
        rows = (
            _db_query("""
            SELECT id, symbol, strategy_id, status, lifecycle_state,
                   first_seen_at, last_seen_at, source_first_seen, source_latest,
                   source_run_label, baseline_score, latest_score, best_score,
                   score_delta, rvol_baseline, rvol_latest, gap_baseline, gap_latest,
                   catalyst, catalyst_verified, sector, industry,
                   days_active, promoted_to_signal_at, promoted_to_proposal_at,
                   last_paper_trade_id, last_outcome, rolloff_reason, notes,
                   created_at, updated_at
            FROM incubator_universe
            ORDER BY
                CASE status WHEN 'ACTIVE' THEN 0 ELSE 1 END,
                latest_score DESC NULLS LAST,
                updated_at DESC
            LIMIT 200
        """)
            or []
        )
        active_rows = [r for r in rows if r.get("status") == "ACTIVE"]
        promoted = sum(1 for r in rows if r.get("promoted_to_proposal_at"))

        # Blocker diagnostics
        blockers = {
            "stale_source": sum(
                1 for r in active_rows if not r.get("source_latest") or r.get("lifecycle_state") == "source_missing"
            ),
            "low_score": sum(1 for r in active_rows if (r.get("latest_score") or 0) < 38),
            "no_catalyst": sum(1 for r in active_rows if not r.get("catalyst_verified")),
            "strategy_unvalidated": 0,  # would need strategy config lookup
            "rolled_off": sum(1 for r in rows if r.get("status") == "ROLLED_OFF"),
            "expired": sum(1 for r in rows if r.get("status") == "EXPIRED"),
        }
        # Check promotion gate
        pending_proposals = (
            _db_query("SELECT COUNT(*) as cnt FROM paper_trade_proposals WHERE status='pending'", fetch="one") or {}
        ).get("cnt", 0)
        blockers["global_proposal_ceiling"] = int(pending_proposals) >= 20

        return {
            "ok": True,
            "universe": [{k: _json_clean(v) for k, v in r.items()} for r in rows],
            "total": len(rows),
            "active": len(active_rows),
            "promoted": promoted,
            "promotion_blockers": blockers,
            "promotion_gate": {
                "pending_proposals": int(pending_proposals),
                "max_pending": 20,
                "can_promote": int(pending_proposals) < 20,
            },
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}


