def _atm_gate_status():
    """GET /api/v2/atm/gate-status — live-trading gate state + progress + per-account interlock
    status (paper = writable now; live = blocked until the gate passes). Read-only."""
    import live_trading_interlock as ilk

    conn = ilk._conn()
    try:
        gs = ilk.gate_status(conn)
        accts = (
            _db_query(
                "SELECT account_label, broker, mode, enabled, auto_execution_capable "
                "FROM accounts ORDER BY mode, account_label"
            )
            or []
        )
        rows = []
        for a in accts:
            a = {k: _json_clean(v) for k, v in a.items()}
            a["interlock"] = "writable" if (a.get("mode") == "paper" or gs.get("passed")) else "blocked_gate_not_passed"
            rows.append(a)
        atm = (
            _db_query(
                "SELECT mode, last_state_change_at, last_state_change_by, paused_until, "
                "pause_reason FROM atm_state WHERE id=1",
                fetch="one",
            )
            or {}
        )
        risk = {}
        try:
            from admin_write_guard import RISK_CONFIG_FIELDS, ATM_CONFIG_PATH, read_yaml_value

            risk = {f: read_yaml_value(ATM_CONFIG_PATH, kp) for f, kp in RISK_CONFIG_FIELDS.items()}
        except Exception:
            pass
        operator_path = {}
        try:
            import execution_state as es

            operator_path = es.live_trading_labels()
        except Exception as e:
            operator_path = {"operator_path_inspect_error": str(e)[:120]}
        return {
            "gate": gs,
            "operator_path": operator_path,
            "accounts": rows,
            "atm_state": {k: _json_clean(v) for k, v in atm.items()},
            "risk_config": risk,
        }
    finally:
        conn.close()


def _atm_actionable_proposals():
    """GET /api/v2/atm/actionable-proposals — proposals the operator can act on (approve/adjust/edit)."""
    rows = (
        _db_query("""SELECT id, symbol, status, strategy_id, signal_grade,
                          NULLIF(COALESCE(target_account, proposed_account, intended_broker), '') AS account,
                          proposed_entry, proposed_stop, proposed_target1, proposed_target2, proposed_shares
                        FROM paper_trade_proposals
                        WHERE status IN ('PENDING','APPROVED_FOR_PAPER_TEST','MODIFIED')
                        ORDER BY created_at DESC LIMIT 30""")
        or []
    )
    return {"proposals": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}


def _atm_schwab_readiness():
    """GET /api/v2/atm/schwab-readiness — the unchecked prerequisites that must ALL be true before
    Schwab live could ever arm. Pure visibility checklist; wires nothing live."""
    import os as _os
    import live_trading_interlock as ilk

    conn = ilk._conn()
    try:
        gs = ilk.gate_status(conn)
    finally:
        conn.close()
    root = _os.path.dirname(_os.path.dirname(_os.path.abspath(__file__)))
    confirm_exists = _os.path.exists(_os.path.join(root, "scripts", "broker_confirm_schwab.py"))
    adapter_impl = False
    ap = _os.path.join(root, "scripts", "schwab_adapter.py")
    if _os.path.exists(ap):
        src = open(ap).read()
        adapter_impl = ("def submit_entry" in src) and ("NotImplementedError" not in src)
    ck = gs.get("checks", {})
    items = [
        {
            "item": "Live-trading gate passed",
            "done": bool(gs.get("passed")),
            "detail": (
                f"days {ck.get('days', {}).get('have')}/{ck.get('days', {}).get('need')} · "
                f"trades {ck.get('closed_trades', {}).get('have')}/{ck.get('closed_trades', {}).get('need')} · "
                f"win {ck.get('win_rate', {}).get('have')}/{ck.get('win_rate', {}).get('need')} · "
                f"PF {ck.get('profit_factor', {}).get('have')}/{ck.get('profit_factor', {}).get('need')}"
            ),
        },
        {
            "item": "Schwab broker-confirmation module (broker_confirm_schwab.py)",
            "done": confirm_exists,
            "detail": "exists" if confirm_exists else "missing — Schwab fills cannot be confirmed yet",
        },
        {
            "item": "Schwab order submission implemented (schwab_adapter, non-stub)",
            "done": adapter_impl,
            "detail": "implemented" if adapter_impl else "stub / no live submit path",
        },
        {
            "item": "Broker-confirmation PROVEN on Schwab (fills verified live)",
            "done": False,
            "detail": "not yet demonstrated on Schwab",
        },
        {
            "item": "Operator out-of-band live-arm confirmation",
            "done": False,
            "detail": "deliberate manual step — taken only after every item above is green",
        },
    ]
    return {
        "schwab_live_ready": all(i["done"] for i in items),
        "items": items,
        "note": "Wires nothing live. Live Schwab arming is a deliberate out-of-band step taken "
        "only after every prerequisite is met.",
    }


def _runtime_inv_path():
    return os.path.join(
        os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
        "data",
        "runtime",
        "runtime_job_inventory_latest.json",
    )


def _system_runtime_inventory():
    """GET /api/v2/system/runtime-inventory — Phase 199B runtime inventory (read-only)."""
    import json as _j

    p = _runtime_inv_path()
    if not os.path.exists(p):
        return {"available": False, "note": "run scripts/inventory_runtime_jobs.py to generate"}
    try:
        d = _j.load(open(p))
        return {
            "available": True,
            "summary": d.get("summary", {}),
            "cron_count": len(d.get("cron_jobs", [])),
            "systemd_count": len(d.get("systemd_jobs", [])),
        }
    except Exception as e:
        return {"available": False, "error": str(e)[:120]}


_PIPELINE_CATEGORY_MAP = {
    "tradeai-market-pipeline": ["MARKET_PIPELINE", "MARKET_MORNING", "DATA_FEED"],
    "tradeai-after-close-pipeline": ["AFTER_CLOSE", "OVERNIGHT_BATCH"],
    "hermes-advisory-pipeline": ["HERMES_ADVISORY"],
    "hermes-research-pipeline": ["HERMES_RESEARCH"],
    "llm-control-pipeline": ["LLM_QUEUE"],
    "governance-pipeline": ["GOVERNANCE"],
    "portfolio-maintenance-pipeline": ["PORTFOLIO_MAINTENANCE"],
}


def _system_pipeline_summary():
    """GET /api/v2/system/pipeline-summary — 199C pipelines mapped over the 199B inventory (read-only)."""
    import json as _j

    p = _runtime_inv_path()
    inv = _j.load(open(p)) if os.path.exists(p) else {"cron_jobs": [], "systemd_jobs": [], "summary": {}}
    cron = inv.get("cron_jobs", [])
    systemd = inv.get("systemd_jobs", [])
    dups = inv.get("summary", {}).get("duplicate_scripts", {})
    out = []
    for name, cats in _PIPELINE_CATEGORY_MAP.items():
        jobs = [j for j in cron if j.get("category") in cats]
        units = [j for j in systemd if j.get("category") in cats]
        comp = sorted({j["script"] for j in jobs if j.get("script") in dups})
        out.append(
            {
                "pipeline": name,
                "categories": cats,
                "cron_jobs": len(jobs),
                "systemd_units": len(units),
                "compression_candidates": comp,
            }
        )
    return {
        "pipelines": out,
        "standalone_services": [j.get("name") for j in systemd if j.get("category") == "24_7_SERVICE"],
        "unknown_triage_count": len([j for j in cron if j.get("category") == "UNKNOWN"]),
        "safety": {"live_trading": False, "level7": "prohibited", "paper_only": True},
        "namespace_note": "/api/v2 is the shared backend namespace serving canonical v3 UI (not v2 UI)",
    }


