def _broker_account_readiness():
    """GET /api/v2/broker-accounts/readiness?account=KEY — capability checks (read-only)."""
    acct = (_current_query.get("account") or "").strip()
    if not acct:
        return {"error": "account query param required"}
    rows = (
        _db_query(
            """SELECT c.check_name, c.status, c.detail, c.last_checked_at
        FROM broker_capability_checks c JOIN broker_accounts ba ON ba.id=c.account_id
        WHERE ba.account_key=%s ORDER BY c.id""",
            (acct,),
        )
        or []
    )
    ready = bool(rows) and all(r["status"] in ("ok", "n/a") for r in rows)
    return {"account": acct, "ready": ready, "checks": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}


def _llm_health():
    """GET /api/v2/llm-health — LLM review lane health + Hermes hybrid policy (2026-08-04).

    Base: three free/local review lanes via llm_health_check.
    Enrichment: DeepSeek Flash/Pro readiness (llm_lane) + free-OAuth→Flash rollover policy
    from config/hermes_research_budget.yaml. No secret values returned.
    """
    try:
        import llm_health_check as _lhc

        out = _lhc.check_all_lanes(30)
    except Exception as e:
        out = {"error": str(e)[:160], "lanes": {}, "review_corpus": {}}
    if not isinstance(out, dict):
        out = {"lanes": {}, "review_corpus": {}, "raw": str(out)[:200]}
    lanes = out.setdefault("lanes", {})
    # DeepSeek readiness (metered) — never expose credentials
    try:
        import llm_lane

        for lane, model in (
            ("deepseek-flash", "deepseek-v4-flash"),
            ("deepseek-v4-pro", "deepseek-v4-pro"),
        ):
            try:
                up = bool(llm_lane.available(lane))
                lanes[lane] = {
                    "available": up,
                    "billing": "metered",
                    "model": model,
                    "reason": None if up else "not ready or credential missing",
                }
            except Exception as le:
                lanes[lane] = {
                    "available": False,
                    "billing": "metered",
                    "model": model,
                    "reason": str(le)[:100],
                }
    except Exception as e:
        lanes.setdefault(
            "deepseek-flash",
            {
                "available": False,
                "billing": "metered",
                "reason": f"llm_lane import: {type(e).__name__}",
            },
        )
    # Hybrid policy (sanitized)
    try:
        from pathlib import Path as _P
        import yaml  # type: ignore

        root = _P(__file__).resolve().parent.parent
        pol_path = root / "config" / "hermes_research_budget.yaml"
        pol = yaml.safe_load(pol_path.read_text()) if pol_path.exists() else {}
        cu = (pol or {}).get("cloud_unavailable") or {}
        roll = cu.get("free_oauth_bottleneck_rollover") or {}
        out["hybrid_policy"] = {
            "local_first": True,
            "free_oauth_lanes": ["grok", "chatgpt"],
            "free_oauth_bottleneck_rollover": {
                "enabled": bool(roll.get("enabled", True)),
                "lane": roll.get("lane") or "deepseek-flash",
                "model": roll.get("model") or "deepseek-v4-flash",
                "policy": roll.get("policy") or "FAST",
                "never_pro": roll.get("never_pro", True),
                "credential_slot": roll.get("credential_slot") or "deepseek_tradeai",
                "triggers": roll.get("triggers")
                or [
                    "free_oauth_unavailable",
                    "free_oauth_zero_ok_lanes",
                ],
            },
            "no_paid_fallback_for_local_failure": True,
            "docs": [
                "docs/ops/HERMES_DEEPSEEK_HYBRID_FREE_OAUTH_ROLLOVER_2026-08-04.md",
                "docs/hermes/HERMES_DEEPSEEK_HYBRID_POLICY.md",
            ],
        }
    except Exception as e:
        out["hybrid_policy"] = {
            "error": str(e)[:160],
            "local_first": True,
            "free_oauth_bottleneck_rollover": {
                "enabled": True,
                "lane": "deepseek-flash",
                "model": "deepseek-v4-flash",
                "never_pro": True,
            },
        }
    return out


def _strategy_leaderboard():
    """GET /api/v2/strategy-leaderboard — LIVE strategy ranking blending closed paper trades + the
    backtest sample (strategy_backtest_results) + the latest assessment snapshot. Ranked by a
    confidence-weighted expectancy so a 2-trade fluke can't top a proven strategy (operator 2026-06-19)."""
    try:
        live = (
            _db_query("""
            SELECT strategy_id,
                   count(*) AS n, count(*) FILTER (WHERE pnl>0) AS wins,
                   round(100.0*count(*) FILTER (WHERE pnl>0)/NULLIF(count(*),0),1) AS win_rate,
                   round(avg(pnl)::numeric,2) AS avg_pnl, round(sum(pnl)::numeric,2) AS total_pnl,
                   round(avg(pnl_pct)::numeric,2) AS avg_pct, round(avg(r_multiple)::numeric,2) AS avg_r
              FROM paper_trades
             WHERE status='closed' AND pnl IS NOT NULL
             GROUP BY strategy_id""")
            or []
        )
        bt = (
            _db_query("""
            SELECT strategy_id, sum(sample_size) AS sample,
                   round((sum(win_rate*sample_size)/NULLIF(sum(sample_size),0))::numeric,1) AS win_rate,
                   round((sum(expectancy_r*sample_size)/NULLIF(sum(sample_size),0))::numeric,2) AS expectancy_r,
                   round(avg(profit_factor)::numeric,2) AS profit_factor
              FROM strategy_backtest_results GROUP BY strategy_id""")
            or []
        )
        snaps = (
            _db_query("""
            SELECT DISTINCT ON (strategy_id) strategy_id, win_rate, avg_r, profit_factor, total_pnl,
                   assessment, recommendation, snapshot_date
              FROM strategy_performance_snapshots ORDER BY strategy_id, snapshot_date DESC""")
            or []
        )
        tilts = (
            _db_query("""SELECT DISTINCT ON (strategy_id) strategy_id, multiplier
                               FROM strategy_tilt_multipliers ORDER BY strategy_id, computed_at DESC""")
            or []
        )
        tilt_by = {r["strategy_id"]: float(r["multiplier"]) for r in tilts}
        bt_by = {r["strategy_id"]: r for r in bt}
        sn_by = {r["strategy_id"]: r for r in snaps}
        R_CLAMP = 3.0  # no real strategy has |expectancy| > ~3R — anything beyond is a data error, not signal

        def _clamp(v):
            try:
                return max(-R_CLAMP, min(R_CLAMP, float(v)))
            except Exception:
                return None

        out = []
        for lv in live:
            sid = lv["strategy_id"]
            b, s = bt_by.get(sid, {}), sn_by.get(sid, {})
            n = lv["n"] or 0
            live_r = float(lv["avg_r"]) if lv["avg_r"] is not None else None
            bt_r_raw = float(b["expectancy_r"]) if b.get("expectancy_r") is not None else None
            bt_suspect = bt_r_raw is not None and abs(bt_r_raw) > R_CLAMP  # flag garbage backtest values
            bt_r = _clamp(bt_r_raw)
            # Blend is SUPPORTING context only (clamped). RANKING is LIVE-PRIMARY (below) so a single
            # corrupt backtest row can't crown a live loser. Trust live more as n grows.
            w = min(1.0, n / 20.0)
            if live_r is not None and bt_r is not None and not bt_suspect:
                blended = round(w * live_r + (1 - w) * bt_r, 2)
            else:
                blended = live_r if live_r is not None else bt_r
            conf = "high" if n >= 20 else "medium" if n >= 8 else "low"
            out.append(
                {
                    "strategy_id": sid,
                    "live": {
                        k: _json_clean(lv[k])
                        for k in ("n", "wins", "win_rate", "avg_pnl", "total_pnl", "avg_pct", "avg_r")
                    },
                    "backtest": (
                        {k: _json_clean(b.get(k)) for k in ("sample", "win_rate", "expectancy_r", "profit_factor")}
                        | {"data_suspect": bt_suspect}
                    )
                    if b
                    else None,
                    "snapshot": {
                        k: _json_clean(s.get(k))
                        for k in ("win_rate", "avg_r", "profit_factor", "assessment", "recommendation", "snapshot_date")
                    }
                    if s
                    else None,
                    "blended_expectancy_r": blended,
                    "confidence": conf,
                    "tilt": tilt_by.get(sid, 1.0),
                    "excluded": sid == "momentum_scalp",
                }
            )

        # RANK LIVE-PRIMARY: live expectancy (avg_r) desc, then total P&L, then win-rate. Backtest/snapshot
        # are context, never the ranking driver (avoids a corrupt backtest crowning a live loser).
        def _key(x):
            lv = x["live"]
            return (
                lv["avg_r"] if lv["avg_r"] is not None else -99,
                lv["total_pnl"] if lv["total_pnl"] is not None else -1e9,
                lv["win_rate"] if lv["win_rate"] is not None else -1,
            )

        out.sort(key=_key, reverse=True)
        for i, x in enumerate(out):
            x["rank"] = i + 1
        supp = (
            _db_query("""SELECT strategy_id, count(*) n, max(suppressed_at) last
                              FROM proposal_suppression_log WHERE suppressed_at > now() - interval '7 days'
                              GROUP BY strategy_id ORDER BY n DESC""")
            or []
        )
        return {
            "leaderboard": out,
            "strategy_gate": {
                "active": True,
                "min_trades_required": 5,
                "wr_gate": "25% at >=10 closed trades",
                "suppressed_last_7d": [{k: _json_clean(v) for k, v in r.items()} for r in supp],
                "note": "Dormant until a strategy reaches >=10 closed trades at <25% WR",
            },
            "note": (
                "Ranked by LIVE expectancy (avg R per trade), tiebreak total P&L then win-rate. "
                "Backtest + assessment shown as context (expectancy clamped at ±3R; data_suspect flags "
                "corrupt rows). LOW confidence = <8 live trades — directional only, not proven."
            ),
        }
    except Exception as e:
        return {"error": str(e)[:160], "leaderboard": []}


def _broker_account_label_meta(account_key: str) -> dict:
    """Broker execution labels only — no live Schwab/Fidelity API calls."""
    key = (account_key or "").lower()
    if "fidelity" in key:
        return {"execution_mode": "manual", "execution_label": "Manual · Fidelity", "auto_eligible": False}
    if "schwab" in key:
        return {"execution_mode": "auto_or_manual", "execution_label": "Schwab · auto or manual", "auto_eligible": True}
    return {"execution_mode": "manual", "execution_label": "Manual", "auto_eligible": False}


def _broker_account_execution_meta(account_key: str) -> dict:
    """Label auto vs manual execution path + cash/day-activity snapshot per broker account."""
    meta = _broker_account_label_meta(account_key)
    try:
        import broker_promote_sizing as bps

        meta["activity"] = bps.account_activity_snapshot(account_key)
    except Exception:
        meta["activity"] = {}
    return meta


def _fetch_watchlist_buy_symbols(symbols: list[str] | None = None) -> set[str]:
    """Symbols with active BUY+ watchlist rating (for dual-source attribution)."""
    if not symbols:
        return set()
    syms = sorted({str(s or "").upper() for s in symbols if s})
    if not syms:
        return set()
    rows = (
        _db_query(
            """SELECT DISTINCT UPPER(wi.symbol) AS symbol
           FROM watchlist_items wi
           LEFT JOIN watchlist_research_cards rc ON rc.symbol = wi.symbol
           LEFT JOIN watchlist_final_synthesis fs ON UPPER(fs.symbol) = UPPER(wi.symbol)
           WHERE wi.status <> 'removed'
             AND UPPER(wi.symbol) = ANY(%s)
             AND (
               lower(COALESCE(rc.latest_recommendation, '')) IN
                 ('buy','strong_buy','add','add_on_pullback','strong buy','add on pullback')
               OR lower(COALESCE(fs.recommendation, '')) IN
                 ('buy','strong_buy','add','add_on_pullback','strong buy','add on pullback')
             )""",
            (syms,),
        )
        or []
    )
    return {str(r.get("symbol") or "").upper() for r in rows if r.get("symbol")}


def _attach_source_attribution(row: dict, watchlist_buy_syms: set[str] | None = None) -> dict:
    """Tag row with watchlist / proposal / both source badges for UI."""
    origin = str(row.get("origin") or "").lower()
    discovery = str(row.get("discovery_source") or "").lower()
    proposed_by = str(row.get("proposed_by") or "").lower()
    sym = str(row.get("symbol") or "").upper()
    basis = row.get("sizing_basis") or {}
    if isinstance(basis, str):
        try:
            basis = json.loads(basis)
        except Exception:
            basis = {}
    rating = (
        row.get("cio_view")
        or row.get("watchlist_rating")
        or (basis.get("watchlist_rating") if isinstance(basis, dict) else None)
    )
    has_signal = bool(
        (row.get("signal_evidence") or {}).get("screener") or row.get("screener_name") or row.get("scan_screener")
    )
    watchlist_bridge = origin == "watchlist" or discovery == "watchlist" or proposed_by == "watchlist_proposal_bridge"
    also_on_watchlist = sym in (watchlist_buy_syms or set())
    watchlist = watchlist_bridge or also_on_watchlist
    auto_proposal = (
        origin == "auto"
        or discovery in ("screener", "incubator", "signal", "pullback_macd")
        or has_signal
        or "auto_proposal" in proposed_by
        or "incubator" in proposed_by
        or "pullback_macd" in proposed_by
        or (bool(row.get("auto_created")) and not watchlist_bridge)
    )
    proposal = auto_proposal and not (watchlist_bridge and not has_signal and discovery != "pullback_macd")
    if watchlist and proposal:
        label = "both"
    elif watchlist:
        label = "watchlist"
    elif proposal:
        label = "proposal"
    else:
        label = "unknown"
    channel = None
    if proposal:
        sc = (row.get("signal_evidence") or {}).get("screener") or row.get("screener_name") or row.get("scan_screener")
        if discovery == "pullback_macd" or "pullback_macd" in proposed_by:
            channel = "Pullback MACD"
        elif discovery == "screener" or sc:
            channel = f"Screener · {sc}" if sc else "Screener"
        elif discovery == "incubator":
            channel = "Incubator"
        elif discovery and discovery != "watchlist":
            channel = discovery.replace("_", " ").title()
        else:
            channel = "Proposal"
    routing_lane = basis.get("routing_lane") if isinstance(basis, dict) else None
    row["also_on_watchlist"] = also_on_watchlist
    row["source_attribution"] = {
        "watchlist": watchlist,
        "proposal": proposal,
        "watchlist_rating": str(rating or "BUY").upper().replace(" ", "_") if watchlist else None,
        "proposal_channel": channel,
        "label": label,
        "routing_lane": routing_lane,
    }
    return row


_BROKER_STRATEGY_META_CACHE: dict[str, dict] = {}


def _broker_strategy_meta(strategy_id: str) -> dict:
    sid = (strategy_id or "").strip()
    if sid in _BROKER_STRATEGY_META_CACHE:
        return _BROKER_STRATEGY_META_CACHE[sid]
    meta: dict = {"strategy_id": sid, "display_name": sid.replace("_", " ").title() if sid else "—"}
    try:
        from proposal_lifecycle import get_strategy_metadata

        meta.update(get_strategy_metadata(sid) or {})
    except Exception:
        pass
    try:
        from strategy_config_loader import load_strategy_config

        cfg = load_strategy_config(sid) or {}
        if cfg.get("display_name"):
            meta["display_name"] = cfg["display_name"]
        if cfg.get("purpose"):
            meta["purpose"] = cfg["purpose"]
        if cfg.get("timeframe"):
            meta["timeframe"] = cfg["timeframe"]
        if cfg.get("timeframe_class"):
            meta["timeframe_class"] = cfg["timeframe_class"]
    except Exception:
        pass
    _BROKER_STRATEGY_META_CACHE[sid] = meta
    return meta


def _broker_symbol_profiles_batch(symbols: list) -> dict[str, dict]:
    syms = sorted({str(s or "").upper() for s in symbols if s})
    if not syms:
        return {}
    rows = (
        _db_query(
            """SELECT upper(symbol) AS symbol, description_1s, sector, industry, instrument_type
           FROM symbol_profiles WHERE upper(symbol) = ANY(%s)""",
            (syms,),
        )
        or []
    )
    return {str(r.get("symbol") or "").upper(): r for r in rows}


def _attach_broker_ticker_context(row: dict, profile: dict | None = None) -> dict:
    """Strategy display + sector/industry for broker card headers (list + detail)."""
    prof = profile or {}
    exec_sid = str(row.get("resolved_strategy_id") or row.get("strategy_id") or "")
    try:
        import broker_strategy_resolver as _bsr

        if _bsr.is_watchlist_sleeve(exec_sid) or not row.get("resolved_strategy_id"):
            resolved = _bsr.resolve_executable_strategy(str(row.get("symbol") or ""), row.get("strategy_id"))
            exec_sid = resolved.get("strategy_id") or exec_sid
            row["resolved_strategy_id"] = exec_sid
            row["watchlist_sleeve"] = row.get("watchlist_sleeve") or resolved.get("watchlist_sleeve")
    except Exception:
        pass
    sm = _broker_strategy_meta(exec_sid)
    row["strategy_display_name"] = sm.get("display_name")
    row["strategy_type"] = sm.get("strategy_type")
    row["strategy_type_label"] = sm.get("strategy_type_label")
    row["strategy_description"] = sm.get("purpose")
    row["strategy_timeframe"] = sm.get("timeframe") or sm.get("timeframe_class")
    row["sector"] = prof.get("sector") or row.get("sector")
    row["industry"] = prof.get("industry") or row.get("industry")
    row["instrument_type"] = prof.get("instrument_type") or row.get("instrument_type")
    desc = prof.get("description_1s")
    if desc:
        row["company_description"] = str(desc)[:400]
    basis = row.get("sizing_basis")
    if isinstance(basis, str):
        try:
            basis = json.loads(basis)
        except Exception:
            basis = {}
    if isinstance(basis, dict):
        if basis.get("watchlist_sleeve"):
            row["watchlist_sleeve"] = basis["watchlist_sleeve"]
        if basis.get("exit_summary"):
            row["exit_summary"] = basis["exit_summary"]
        if basis.get("exit_rationale"):
            row["exit_rationale"] = basis["exit_rationale"]
        if basis.get("strategy_resolve_source"):
            row["strategy_resolve_source"] = basis["strategy_resolve_source"]
    try:
        import broker_strategy_resolver as _bsr

        if _bsr.is_watchlist_sleeve(str(row.get("strategy_id") or "")):
            resolved = _bsr.resolve_executable_strategy(str(row.get("symbol") or ""), row.get("strategy_id"))
            row["resolved_strategy_id"] = resolved.get("strategy_id")
            row["watchlist_sleeve"] = row.get("watchlist_sleeve") or resolved.get("watchlist_sleeve")
            row["strategy_resolve_source"] = resolved.get("resolve_source")
        elif not row.get("resolved_strategy_id"):
            row["resolved_strategy_id"] = row.get("strategy_id")
    except Exception:
        if not row.get("resolved_strategy_id"):
            row["resolved_strategy_id"] = row.get("strategy_id")
    return row


def _attach_lane_gates_and_grades(row: dict) -> dict:
    """Lane-specific gate status + screener vs Finviz grade split for unified queue cards."""
    basis = row.get("sizing_basis")
    if isinstance(basis, str):
        try:
            basis = json.loads(basis)
        except Exception:
            basis = {}
    routing_lane = basis.get("routing_lane") if isinstance(basis, dict) else None
    if not routing_lane:
        br = str(row.get("intended_broker") or row.get("account") or "").lower()
        routing_lane = "live_2fa" if br.startswith(("schwab", "fidelity")) else "paper_atm"
    row["routing_lane"] = routing_lane

    screener_grade = str(row.get("signal_grade") or "").upper() or None
    finviz_grade = finviz_score = finviz_tech = None
    try:
        from atm_technical_gate import letter_grade

        # the snapshot's numeric score column is confluence_score (technical_score never
        # existed) — the erroring query forced the expensive enrichment-bridge recompute
        # fallback on every proposal render
        _ts = _db_query(
            """SELECT technical_grade, confluence_score AS technical_score
                 FROM proposal_technical_snapshots
                WHERE proposal_id=%s ORDER BY computed_at DESC LIMIT 1""",
            [row.get("id")],
            fetch="one",
        )
        if _ts and _ts.get("technical_grade"):
            finviz_tech = str(_ts.get("technical_grade"))
            finviz_score = int(_ts.get("technical_score") or 0)
            finviz_grade = letter_grade(finviz_score)
        else:
            import proposal_enrichment_bridge as peb

            sym = str(row.get("symbol") or "").upper()
            _px = row.get("current_price") or row.get("proposed_entry")
            snap = peb.snapshot_from_enrichment(
                sym,
                live_price=float(_px) if _px is not None else None,
            )
            finviz_tech = str(snap.get("technical_grade") or "")
            finviz_score = int(snap.get("technical_score") or 0)
            finviz_grade = letter_grade(finviz_score)
    except Exception:
        pass

    ds = str(row.get("discovery_source") or "").lower()
    screener_label = (
        "Pullback"
        if ds == "pullback_macd"
        else "Watchlist"
        if ds == "watchlist" or str(row.get("origin") or "").lower() == "watchlist"
        else "Screener"
    )
    row["grade_split"] = {
        "screener": {
            "label": screener_label,
            "grade": screener_grade,
            "score": row.get("signal_score"),
        },
        "finviz": {
            "label": "Finviz",
            "grade": finviz_grade,
            "score": finviz_score,
            "technical_grade": finviz_tech,
        },
    }

    traded = row.get("traded") or {}
    pid = row.get("id")
    lane_gates: dict = {}
    if routing_lane == "paper_atm":
        if traded.get("status") == "open" or traded.get("broker_status") == "filled":
            atm_st = "filled"
        elif str(row.get("status") or "").upper() == "APPROVED_FOR_PAPER_TEST":
            atm_st = "approved"
        elif str(row.get("status") or "").upper() == "PENDING":
            atm_st = "pending"
        else:
            atm_st = str(row.get("status") or "unknown").lower()
        msg = None
        if atm_st == "filled" and traded.get("trade_id"):
            ep = traded.get("entry_price")
            msg = f"Paper filled · trade #{traded['trade_id']}"
            if ep is not None:
                msg += f" @ ${float(ep):.2f}"
        elif atm_st == "pending":
            msg = "ATM lane — requires Finviz score ≥60, trade plan, position limits (not Path B agents)"
        lane_gates["paper_atm"] = {
            "status": atm_st,
            "trade_id": traded.get("trade_id"),
            "entry_price": traded.get("entry_price"),
            "message": msg,
        }
    if routing_lane == "live_2fa":
        pending_agents: list[str] = []
        try:
            ar = (
                _db_query(
                    """SELECT agent_name FROM proposal_agent_reviews
                    WHERE proposal_id=%s AND status='pending'""",
                    [pid],
                )
                or []
            )
            pending_agents = [str(a.get("agent_name")) for a in ar if a.get("agent_name")]
        except Exception:
            pass
        path_blocked = bool(pending_agents)
        msg = (
            f"BLOCK — agents pending: {', '.join(pending_agents)}"
            if pending_agents
            else "Route-eligible — Litmus + sizing + 2FA (agents advisory)"
        )
        lane_gates["path_b"] = {
            "status": "blocked" if path_blocked else "route_eligible",
            "agents_pending": pending_agents,
            "message": msg,
        }
    row["lane_gates"] = lane_gates
    return row


def _broker_proposal_row_base(
    r: dict,
    quote_map: dict | None = None,
    watchlist_buy_syms: set[str] | None = None,
    profiles_map: dict | None = None,
) -> dict:
    """Lightweight broker queue row — economics + quotes only."""
    row = {k: _json_clean(v) for k, v in r.items()}
    basis = row.get("sizing_basis")
    if isinstance(basis, str):
        try:
            basis = json.loads(basis)
        except Exception:
            basis = {}
    if isinstance(basis, dict) and basis.get("watchlist_rating"):
        row["watchlist_rating"] = basis["watchlist_rating"]
    # Backtest snapshot (proposal_backtest_engine) — surfaces the Backtest chip on the card instead of
    # a hardcoded 'not run'. Latest snapshot per proposal; compact for the UI.
    try:
        _btrows = (
            _db_query(
                """SELECT backtest_quality, sample_size, win_rate, avg_r, expectancy,
                                      similar_setup_summary, created_at
                               FROM proposal_backtest_snapshots WHERE proposal_id=%s
                               ORDER BY created_at DESC LIMIT 1""",
                [row.get("id")],
            )
            if row.get("id")
            else None
        )
        _bt = _btrows[0] if _btrows else None
        if _bt:
            row["backtest"] = {
                "quality": _bt.get("backtest_quality"),
                "samples": _bt.get("sample_size"),
                "win_rate": float(_bt["win_rate"]) if _bt.get("win_rate") is not None else None,
                "avg_r": float(_bt["avg_r"]) if _bt.get("avg_r") is not None else None,
                "summary": _bt.get("similar_setup_summary"),
                "as_of": str(_bt.get("created_at"))[:19] if _bt.get("created_at") else None,
            }
    except Exception:
        pass
    # Cloud dual-consensus advisory verdict (cloud_consensus_verdict.py) — latest per proposal.
    # ADVISORY ONLY: signal for the card's hero row 2 chip; never gates or mutates anything.
    try:
        _ccrows = (
            _db_query(
                """SELECT consensus, grok_verdict, grok_note, chatgpt_verdict, chatgpt_note,
                                      created_at
                               FROM cloud_consensus_verdicts WHERE proposal_id=%s
                               ORDER BY created_at DESC LIMIT 1""",
                [row.get("id")],
            )
            if row.get("id")
            else None
        )
        _cc = _ccrows[0] if _ccrows else None
        if _cc:
            row["cloud_consensus"] = {
                "consensus": _cc.get("consensus"),
                "grok_verdict": _cc.get("grok_verdict"),
                "grok_note": _cc.get("grok_note"),
                "chatgpt_verdict": _cc.get("chatgpt_verdict"),
                "chatgpt_note": _cc.get("chatgpt_note"),
                "as_of": str(_cc.get("created_at"))[:19] if _cc.get("created_at") else None,
                "advisory_only": True,
            }
    except Exception:
        pass
    # Trade outcome — did this proposal become a trade, and how did it do (Expired-view "results").
    try:
        _trows = (
            _db_query(
                """SELECT id, status, broker_status, entry_price, shares,
                                     pnl, pnl_pct, dollar_risk, exit_reason, exit_time
                              FROM paper_trades
                             WHERE (proposal_id=%s OR source_proposal_id=%s)
                               AND COALESCE(status,'') NOT IN ('superseded_by_fill', 'cancelled')
                             ORDER BY CASE WHEN status='open' THEN 0 ELSE 1 END,
                                      entry_time DESC NULLS LAST
                             LIMIT 1""",
                [row.get("id"), str(row.get("id"))],
            )
            if row.get("id")
            else None
        )
        _tr = _trows[0] if _trows else None
        if _tr:
            _pnl = float(_tr["pnl"]) if _tr.get("pnl") is not None else None
            _risk = float(_tr["dollar_risk"]) if _tr.get("dollar_risk") else None
            row["traded"] = {
                "trade_id": _tr.get("id"),
                "status": _tr.get("status"),
                "broker_status": _tr.get("broker_status"),
                "entry_price": float(_tr["entry_price"]) if _tr.get("entry_price") is not None else None,
                "shares": int(_tr["shares"]) if _tr.get("shares") is not None else None,
                "pnl": _pnl,
                "pnl_pct": float(_tr["pnl_pct"]) if _tr.get("pnl_pct") is not None else None,
                "r_multiple": round(_pnl / _risk, 2) if (_pnl is not None and _risk) else None,
                "exit_reason": _tr.get("exit_reason"),
                "exit_time": str(_tr.get("exit_time"))[:19] if _tr.get("exit_time") else None,
            }
    except Exception:
        pass
    # Would-have-played-out — for an UNTRADED proposal, where the trade would stand now if it had been
    # entered at its plan. Uses the live current price (a snapshot, NOT an intraday path: ticker_prices
    # stores close-only, so we can't prove an intraday target/stop touch). Honest about the method.
    try:
        if not row.get("traded"):
            _en = float(row.get("proposed_entry") or 0)
            _st = float(row.get("proposed_stop") or 0)
            _tg = float(row.get("proposed_target1") or 0)
            _cur = float(row.get("current_price") or 0)
            if _en > 0 and _cur > 0:
                _move = round((_cur - _en) / _en * 100, 1)
                if _tg and _cur >= _tg:
                    _verdict, _to_tgt = "hit TARGET", 0.0
                elif _st and _cur <= _st:
                    _verdict, _to_tgt = "STOPPED", None
                else:
                    _verdict = "open"
                    _to_tgt = round((_tg - _cur) / _cur * 100, 1) if _tg and _cur else None
                row["would_have"] = {
                    "verdict": _verdict,
                    "move_pct": _move,
                    "to_target_pct": _to_tgt,
                    "method": "live snapshot (close-only — not intraday path)",
                }
    except Exception:
        pass
    # Unified queue: a row is a real broker-routed entry, or a paper-source PROPOSAL surfaced
    # in the broker view (badged by origin). The backend paper automation is unchanged.
    _broker_route = str(row.get("intended_broker") or row.get("account") or "").lower()
    row["source_kind"] = (
        "broker" if (_broker_route.startswith("schwab") or _broker_route.startswith("fidelity")) else "proposal"
    )
    row["proposal_origin"] = str(row.get("origin") or row.get("discovery_source") or "auto")
    # P1-9: which live-submit path this row uses if routed. Prefer persisted tag (set at submit time);
    # fall back to inferred path from account/broker when not yet submitted.
    _stored_path = str(row.get("live_submit_path") or "").strip()
    if _stored_path:
        row["routing_path"] = _stored_path
    elif _broker_route.startswith("schwab"):
        row["routing_path"] = "queue_route_2fa"  # OTOCO bracket via approval_service 2FA
    elif _broker_route.startswith("fidelity"):
        row["routing_path"] = "record_only"  # FA-executed, recorded
    else:
        row["routing_path"] = "paper_auto"  # autonomous Alpaca paper (backend maturation)
    if row.get("last_correlation_id"):
        row["correlation_id"] = str(row.get("last_correlation_id"))
    sym = str(row.get("symbol") or "").upper()
    # Surface rvol/gap/catalyst at top level so the card's meme/high-risk banner fires in the LIST
    # (no detail-load required). Banner reads p.rvol / p.gap_pct / p.catalyst directly.
    try:
        row["rvol"] = float(row["rvol"]) if row.get("rvol") is not None else None
    except Exception:
        row["rvol"] = None
    try:
        row["gap_pct"] = float(row["gap_pct"]) if row.get("gap_pct") is not None else None
    except Exception:
        row["gap_pct"] = None
    _catraw = row.get("catalyst")
    row["catalyst"] = str(_catraw)[:300] if _catraw else None
    sh = float(row.get("proposed_shares") or 0)
    en = float(row.get("proposed_entry") or 0)
    st = float(row.get("proposed_stop") or 0)
    tg = float(row.get("proposed_target1") or 0)
    risk_ps = max(0.0, en - st)
    reward_ps = max(0.0, tg - en)
    row["investment"] = round(sh * en, 2) if sh and en else None
    row["max_risk"] = round(risk_ps * sh, 2) if sh and risk_ps else None
    row["profit_at_target"] = round(reward_ps * sh, 2) if sh and reward_ps else None
    q = (quote_map or {}).get(sym) or {}
    bid, ask = q.get("bid"), q.get("ask")
    if bid is not None and ask is not None and float(bid) > 0:
        row["quote_bid"] = float(bid)
        row["quote_ask"] = float(ask)
        row["quote_last"] = float(q.get("last") or en)
        row["quote_spread"] = round(float(ask) - float(bid), 4)
        row["quote_spread_pct"] = round(row["quote_spread"] / float(bid) * 100, 3)
    elif q.get("last") is not None:
        row["quote_last"] = float(q.get("last"))
    if q.get("provider"):
        row["quote_provider"] = q.get("provider")
        row["refreshed_at"] = q.get("refreshed_at") or datetime.now(timezone.utc).isoformat()[:19]
    try:
        from broker_thesis_validity import attach_thesis_validity

        attach_thesis_validity(row)
    except Exception:
        pass
    # Curation snapshot: support/resistance + last curated stamp
    snap = row.get("curation_snapshot")
    if isinstance(snap, str):
        try:
            snap = json.loads(snap)
        except Exception:
            snap = {}
    if isinstance(snap, dict):
        levels = snap.get("levels") or {}
        if levels.get("support_1") is not None:
            row["support_1"] = levels.get("support_1")
        if levels.get("resistance_1") is not None:
            row["resistance_1"] = levels.get("resistance_1")
        if levels.get("support_2") is not None:
            row["support_2"] = levels.get("support_2")
        if levels.get("resistance_2") is not None:
            row["resistance_2"] = levels.get("resistance_2")
        row["levels_source"] = levels.get("source")
        row["curation_detail"] = {
            "criteria": snap.get("criteria"),
            "strategy": snap.get("strategy"),
            "curated_at": snap.get("curated_at"),
        }
    if row.get("support_1") is None:
        tc = row.get("technical_context")
        if isinstance(tc, str):
            try:
                tc = json.loads(tc)
            except Exception:
                tc = {}
        if isinstance(tc, dict):
            row["support_1"] = tc.get("support_1")
            row["resistance_1"] = tc.get("resistance_1")
            row["levels_source"] = tc.get("levels_source")
    # Moving-average / entry-helper context (SMA20/50/200 vs live price, RSI, RVOL, ATR%, entry hint).
    # Helps time the entry on watchlist/income proposals that carry no momentum-scanner technicals.
    try:
        _mc = _ma_context(sym, row.get("current_price") or row.get("proposed_entry"))
        if _mc:
            row["ma_context"] = _mc
            # backfill top-level rsi/rvol if the proposal row had none (card header reads these)
            if row.get("rsi") is None and _mc.get("rsi") is not None:
                row["rsi"] = _mc["rsi"]
            if row.get("rvol") is None and _mc.get("rvol") is not None:
                row["rvol"] = _mc["rvol"]
    except Exception:
        pass
    prof = (profiles_map or {}).get(sym) or {}
    _attach_broker_ticker_context(row, prof)
    _attach_lane_gates_and_grades(row)
    return _attach_source_attribution(row, watchlist_buy_syms)


