def _proposal_cloud_consensus(qs):
    """GET /api/v2/proposals/cloud-consensus?proposal_id= — latest cloud dual-consensus
    advisory verdict for one proposal (cloud_consensus_verdicts). ADVISORY ONLY — this
    surface never gates, approves, or mutates the proposal."""
    try:
        pid = int(str((qs or {}).get("proposal_id") or "0"))
    except Exception:
        pid = 0
    if pid <= 0:
        return {"ok": False, "error": "proposal_id required", "advisory_only": True}
    row = _db_query(
        """SELECT id, proposal_id, grok_verdict, grok_note, chatgpt_verdict, chatgpt_note,
                  consensus, qualified_reason, created_at
             FROM cloud_consensus_verdicts WHERE proposal_id=%s
            ORDER BY created_at DESC LIMIT 1""",
        [pid],
        fetch="one",
    )
    if not row:
        return {"ok": True, "proposal_id": pid, "verdict": None, "advisory_only": True}
    return {
        "ok": True,
        "proposal_id": pid,
        "verdict": {k: _json_clean(v) for k, v in row.items()},
        "advisory_only": True,
    }


def _broker_proposals_audit():
    """GET /api/v2/broker-proposals/audit — pipeline + broker queue dysfunction report."""
    try:
        import broker_queue_hygiene as bqh

        audit = bqh.audit_proposal_pipeline(days=7)
        sweep = bqh.sweep_broker_queue(dry_run=True, refresh_quotes=False)
        audit["broker_sweep_preview"] = {
            "checked": sweep.get("checked"),
            "would_expire": sweep.get("would_expire"),
            "would_reject": sweep.get("would_reject"),
            "details": sweep.get("details"),
        }
        return {"ok": True, "data": audit}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _broker_qp(query, key, default=None):
    q = query or {}
    v = q.get(key)
    if isinstance(v, list):
        v = v[0] if v else None
    return default if v in (None, "") else v


_BROKER_LIST_CACHE: dict[str, tuple[float, dict]] = {}
_BROKER_LIST_CACHE_TTL = int(os.getenv("BROKER_LIST_CACHE_SEC", "180"))
_BROKER_LIST_DISK = PROJECT_ROOT / "data" / "runtime" / "broker_list_cache.json"
BROKER_LIST_LIVE_QUOTES = os.getenv("BROKER_LIST_LIVE_QUOTES", "1").lower() not in ("0", "false", "no")


def _broker_list_cache_key(query: dict | None) -> str:
    q = query or {}
    parts = []
    for k in sorted(q.keys()):
        v = q[k]
        if isinstance(v, list):
            v = v[0] if len(v) == 1 else v
        parts.append(f"{k}={v}")
    return "v2|" + ("|".join(parts) if parts else "default")


def _broker_list_cache_get(key: str) -> dict | None:
    import time as _t

    hit = _BROKER_LIST_CACHE.get(key)
    if hit and (_t.time() - hit[0]) < _BROKER_LIST_CACHE_TTL:
        out = dict(hit[1])
        out["cached"] = True
        out["cache_age_sec"] = int(_t.time() - hit[0])
        return out
    try:
        if _BROKER_LIST_DISK.exists():
            blob = json.loads(_BROKER_LIST_DISK.read_text(encoding="utf-8"))
            entry = (blob or {}).get(key)
            if entry and (_t.time() - float(entry.get("ts") or 0)) < _BROKER_LIST_CACHE_TTL:
                out = dict(entry.get("data") or {})
                out["cached"] = True
                out["cache_age_sec"] = int(_t.time() - float(entry.get("ts") or 0))
                _BROKER_LIST_CACHE[key] = (_t.time(), out)
                return out
    except Exception:
        pass
    return None


def _broker_list_cache_put(key: str, data: dict) -> None:
    import time as _t

    payload = dict(data)
    payload.pop("cached", None)
    payload.pop("cache_age_sec", None)
    _BROKER_LIST_CACHE[key] = (_t.time(), payload)
    try:
        _BROKER_LIST_DISK.parent.mkdir(parents=True, exist_ok=True)
        blob = {}
        if _BROKER_LIST_DISK.exists():
            blob = json.loads(_BROKER_LIST_DISK.read_text(encoding="utf-8")) or {}
        blob[key] = {"ts": _t.time(), "data": payload}
        if len(blob) > 24:
            blob = dict(sorted(blob.items(), key=lambda kv: float((kv[1] or {}).get("ts") or 0))[-24:])
        _BROKER_LIST_DISK.write_text(json.dumps(blob, default=str)[:800000], encoding="utf-8")
    except Exception:
        pass


def _broker_list_cache_clear() -> None:
    """Clear in-memory and on-disk broker list caches."""
    try:
        _BROKER_LIST_CACHE.clear()
    except Exception:
        pass
    try:
        if _BROKER_LIST_DISK.exists():
            _BROKER_LIST_DISK.unlink()
    except Exception:
        pass


def _broker_batch_live_quotes(symbols: list[str]) -> dict:
    return _broker_list_quote_map(symbols)


# ── Broker list-path latency guards (P0 2026-07-14: Proposals tab forever-spinner) ────────────
# broker_proposal_autocal.batch_live_quotes falls back to SERIAL per-symbol provider-chain
# quotes (~3-4s each) whenever the Schwab batch lane is down (e.g. OAuth refresh 400) — a
# 15-row page held /api/v2/broker-proposals for 35-60s, past the UI timeout, so the tab
# never rendered. Same quotes / same payload shape, but the list path now: (1) serves a
# short-TTL in-process quote cache, (2) waits at most BROKER_LIST_QUOTE_BUDGET_SEC for the
# fetch, letting it finish on a daemon thread to warm the cache for the next poll. Symbols
# with no quote inside the budget keep their DB price — identical to batch_live_quotes'
# existing behavior for symbols the providers can't quote.
_BROKER_QUOTE_CACHE: dict[str, tuple[float, dict]] = {}
_BROKER_QUOTE_CACHE_TTL = float(os.getenv("BROKER_LIST_QUOTE_TTL_SEC", "90"))
_BROKER_QUOTE_BUDGET_SEC = float(os.getenv("BROKER_LIST_QUOTE_BUDGET_SEC", "8"))
_BROKER_QUOTE_FETCH: dict = {"event": None}  # single-flight: {"event": threading.Event}
_BROKER_QUOTE_FETCH_LOCK = None  # created lazily (threading.Lock)


def _broker_list_quote_map(symbols: list) -> dict:
    import time as _t
    import threading as _th

    global _BROKER_QUOTE_FETCH_LOCK
    if _BROKER_QUOTE_FETCH_LOCK is None:
        _BROKER_QUOTE_FETCH_LOCK = _th.Lock()
    syms = sorted({str(s or "").upper() for s in symbols if s})
    if not syms:
        return {}
    now = _t.time()
    out: dict = {}
    missing: list[str] = []
    for s in syms:
        hit = _BROKER_QUOTE_CACHE.get(s)
        if hit and (now - hit[0]) < _BROKER_QUOTE_CACHE_TTL:
            out[s] = hit[1]
        else:
            missing.append(s)
    if not missing:
        return out
    with _BROKER_QUOTE_FETCH_LOCK:
        ev = _BROKER_QUOTE_FETCH.get("event")
        if ev is None or ev.is_set():
            # no fetch in flight — start one for this request's missing set
            ev = _th.Event()
            _BROKER_QUOTE_FETCH["event"] = ev

            def _fetch(batch=list(missing), done=ev):
                try:
                    from broker_proposal_autocal import batch_live_quotes

                    qmap = batch_live_quotes(batch) or {}
                    ts = _t.time()
                    for k, v in qmap.items():
                        _BROKER_QUOTE_CACHE[str(k).upper()] = (ts, v)
                except Exception:
                    pass
                finally:
                    done.set()

            _th.Thread(target=_fetch, name="broker-list-quotes", daemon=True).start()
    # Wait up to the budget for the in-flight fetch (ours or a concurrent request's),
    # then serve whatever the cache has. A slow fetch keeps running and warms the
    # cache for the next 15-30s poll instead of wedging this response.
    ev.wait(_BROKER_QUOTE_BUDGET_SEC)
    now = _t.time()
    for s in missing:
        hit = _BROKER_QUOTE_CACHE.get(s)
        if hit and (now - hit[0]) < _BROKER_QUOTE_CACHE_TTL:
            out[s] = hit[1]
    return out


_BROKER_AUTOCAL_BG: dict = {"running": False}


def _broker_autocal_kick() -> dict:
    """Fire broker_proposal_autocal.maybe_auto_recalibrate WITHOUT blocking the request.
    The recal itself is unchanged (same 5-min throttle, same DB writes); with the Schwab
    lane degraded an inline run requoted the whole stale queue serially and held the
    triggering /api/v2/broker-proposals request for minutes."""
    import threading as _th

    if _BROKER_AUTOCAL_BG.get("running"):
        return {"skipped": True, "reason": "in_progress"}
    _BROKER_AUTOCAL_BG["running"] = True

    def _run():
        try:
            from broker_proposal_autocal import maybe_auto_recalibrate

            maybe_auto_recalibrate()
        except Exception:
            pass
        finally:
            _BROKER_AUTOCAL_BG["running"] = False

    _th.Thread(target=_run, name="broker-autocal", daemon=True).start()
    return {"scheduled": True}


_BROKER_QSUM_CACHE: dict = {"ts": 0.0, "data": None, "refreshing": False}
_BROKER_QSUM_TTL = float(os.getenv("BROKER_QUEUE_SUMMARY_TTL_SEC", "60"))


def _broker_queue_summary_fast():
    """Serve the last queue summary; recompute on a daemon thread when stale.
    compute_queue_summary() pushes every active proposal through the sizing/gate
    evaluators (12s+ cold, includes network quote lookups) — too slow for the list
    request path. Data is identical, just up to ~TTL+compute seconds old."""
    import time as _t
    import threading as _th

    now = _t.time()
    data = _BROKER_QSUM_CACHE.get("data")
    if data is not None and (now - _BROKER_QSUM_CACHE["ts"]) < _BROKER_QSUM_TTL:
        return data

    def _compute():
        try:
            import broker_proposal_queue_ops as _bqo

            res = _bqo.compute_queue_summary()
            if res:
                _BROKER_QSUM_CACHE["data"] = res
                _BROKER_QSUM_CACHE["ts"] = _t.time()
        except Exception:
            pass
        finally:
            _BROKER_QSUM_CACHE["refreshing"] = False

    if not _BROKER_QSUM_CACHE.get("refreshing"):
        _BROKER_QSUM_CACHE["refreshing"] = True
        _th.Thread(target=_compute, name="broker-qsum", daemon=True).start()
    # Stale (or first-call None) copy — the UI tolerates a missing queue_summary and
    # the next poll picks up the refreshed one.
    return data


def _broker_enrich_trust_rows(rows: list[dict]) -> list[dict]:
    """Cross-surface trust context (2026-07-03): held position in the target account + next
    earnings date on every proposal row — approving an add-to-position or a pre-earnings entry
    should never look identical to a fresh clean entry. Cheap: one holdings.json read + one
    earnings query per serve; failures never block the list."""
    if not rows:
        return rows
    try:
        held: dict = {}
        h = _load_json(STATE_DIR / "holdings.json") or {}
        for r in h.get("holdings", []):
            if r.get("is_cash"):
                continue
            key = (str(r.get("symbol") or "").upper(), str(r.get("account") or ""))
            held[key] = held.get(key, 0.0) + float(r.get("shares") or 0)
        syms = sorted({str(r.get("symbol") or "").upper() for r in rows if r.get("symbol")})
        earn = {}
        if syms:
            for e in (
                _db_query(
                    "SELECT upper(symbol) AS s, next_earnings_date FROM symbol_profiles WHERE upper(symbol) = ANY(%s)",
                    (syms,),
                )
                or []
            ):
                if e.get("next_earnings_date"):
                    earn[e["s"]] = str(e["next_earnings_date"])
        # Latest catalyst headline per symbol — same source as the watchlist items query's
        # catalyst_events LATERAL (non-'other', 45-day window), batched here. Failure-tolerant:
        # a catalyst outage must never block the proposal list.
        cata: dict = {}
        if syms:
            try:
                for c in (
                    _db_query(
                        """SELECT DISTINCT ON (upper(symbol)) upper(symbol) AS s, headline,
                                  COALESCE(published_at, created_at) AS ts
                             FROM catalyst_events
                            WHERE upper(symbol) = ANY(%s) AND catalyst_type <> 'other'
                              AND COALESCE(published_at, created_at) > now() - interval '45 days'
                            ORDER BY upper(symbol), COALESCE(published_at, created_at) DESC""",
                        (syms,),
                    )
                    or []
                ):
                    if c.get("headline"):
                        cata[c["s"]] = {"title": str(c["headline"]), "at": str(c["ts"]) if c.get("ts") else None}
            except Exception:
                cata = {}
        for r in rows:
            sym = str(r.get("symbol") or "").upper()
            acct = str(r.get("account_key") or r.get("intended_account") or r.get("account") or "")
            r["held_shares_in_account"] = round(held.get((sym, acct), 0.0), 4) if acct else 0.0
            r["held_shares_total"] = round(sum(v for (s, _a), v in held.items() if s == sym), 4)
            r["next_earnings_date"] = earn.get(sym)
            r["catalyst_title"] = (cata.get(sym) or {}).get("title")
            r["catalyst_at"] = (cata.get(sym) or {}).get("at")
    except Exception:
        pass
    return rows


def _broker_reprice_proposal_rows(rows: list[dict]) -> list[dict]:
    if not rows:
        return rows
    if BROKER_LIST_LIVE_QUOTES:
        from broker_proposal_autocal import apply_live_quotes_to_rows

        # Pass a pre-built bounded quote map — apply_live_quotes_to_rows' own
        # batch_live_quotes call is unbounded/serial on provider fallback (P0 spinner).
        # An empty map must NOT be passed through (falsy → it would refetch serially);
        # no quotes inside the budget simply means rows keep their DB prices this poll.
        _qmap = _broker_list_quote_map([r.get("symbol") for r in rows])
        if _qmap:
            rows = apply_live_quotes_to_rows(rows, quote_map=_qmap)
    return _broker_enrich_trust_rows(rows)


def _broker_parse_rr_filters(query: dict | None) -> dict:
    """Normalize R:R / quality filter query params."""
    q = query or {}
    preset = str(_broker_qp(q, "rr_preset", _broker_qp(q, "quality", "")) or "").lower()
    min_live = _broker_qp(q, "min_live_rr", "")
    min_planned = _broker_qp(q, "min_planned_rr", "")
    actionable = str(_broker_qp(q, "actionable", "") or "").lower() in ("1", "true", "yes")
    sort_hint = None
    if preset == "best":
        min_live, actionable, sort_hint = "2", True, "rr_live"
    elif preset == "live_2":
        min_live, sort_hint = "2", "rr_live"
    elif preset == "live_15":
        min_live, sort_hint = "1.5", "rr_live"
    elif preset == "planned_2":
        min_planned, sort_hint = "2", "rr"
    elif preset == "actionable":
        actionable = True
    try:
        min_live_f = float(min_live) if min_live not in (None, "") else None
    except Exception:
        min_live_f = None
    try:
        min_planned_f = float(min_planned) if min_planned not in (None, "") else None
    except Exception:
        min_planned_f = None
    return {
        "preset": preset or None,
        "min_live_rr": min_live_f,
        "min_planned_rr": min_planned_f,
        "actionable": actionable,
        "sort_hint": sort_hint,
    }


def _fetch_protection_union_rows(symbol_f: str = "", account_f: str = "") -> list:
    """Protection adjustments shaped for the broker-proposals queue (negative ids avoid collisions)."""
    from automated_account import (
        AUTOMATED_ACCOUNT_KEY,
        LEGACY_AUTOMATED_KEYS,
        display_account_label,
        is_automated_account,
        normalize_account_key,
    )

    AUTO = {
        "MOVE_STOP_TO_PROFIT_LOCK",
        "MOVE_STOP_TO_BREAKEVEN",
        "ADD_FIXED_TAKE_PROFIT",
        "CONVERT_TO_TRAILING_STOP",
    }
    where = ["a.status = 'PROPOSED'", "t.status = 'open'"]
    params: list = []
    if symbol_f:
        where.append("UPPER(a.symbol) LIKE %s")
        params.append(f"%{symbol_f}%")
    if account_f:
        if is_automated_account(account_f):
            keys = sorted(LEGACY_AUTOMATED_KEYS)
            where.append(f"t.account IN ({','.join(['%s'] * len(keys))})")
            params.extend(keys)
        else:
            where.append("t.account = %s")
            params.append(account_f)
    rows = (
        _db_query(
            f"""SELECT a.id, a.symbol, a.action, a.current_stop, a.proposed_stop, a.status,
                   a.requires_operator_approval, a.no_live_execution, a.created_at,
                   a.evidence_refs, a.tradeai_reason,
                   t.account, t.entry_price, t.shares, t.strategy_id, t.target_account,
                   p.discovery_source AS entry_discovery_source, p.origin AS entry_origin
              FROM paper_protection_adjustment_proposals a
              JOIN paper_trades t ON t.id = a.trade_id
              LEFT JOIN paper_trade_proposals p ON p.id::text = t.source_proposal_id
             WHERE {" AND ".join(where)}
             ORDER BY a.created_at DESC, a.id DESC""",
            tuple(params) if params else None,
        )
        or []
    )
    out = []
    for r in rows:
        acct_raw = str(r.get("account") or "")
        acct = normalize_account_key(acct_raw)
        act = (r.get("action") or "").upper()
        if is_automated_account(acct_raw) and act in AUTO:
            atm_disp = "paper_auto_apply"
        elif is_automated_account(acct_raw):
            atm_disp = "advisory"
        else:
            atm_disp = "operator_approval"
        pid = int(r["id"])
        strat_id = str(r.get("strategy_id") or "")
        sm = _broker_strategy_meta(strat_id) if strat_id else {}
        entry_disc = str(r.get("entry_discovery_source") or "").lower()
        entry_origin = str(r.get("entry_origin") or "").lower()
        prot_row = {
            "id": -pid,
            "protection_id": pid,
            "queue_kind": "protection",
            "proposal_kind": "protection",
            "symbol": r.get("symbol"),
            "account": acct,
            "action": act,
            "proposed_stop": r.get("proposed_stop"),
            "current_stop": r.get("current_stop"),
            "entry_price": r.get("entry_price"),
            "shares": r.get("shares"),
            "status": r.get("status") or "PROPOSED",
            "origin": "protection",
            "discovery_source": entry_disc or "protection",
            "routing_state": "protection",
            "atm_disposition": atm_disp,
            "created_at": r.get("created_at"),
            "account_display": display_account_label(acct_raw),
            "account_broker": "alpaca" if is_automated_account(acct_raw) else None,
            "detail_pending": False,
            "activity": None,
            "activity_pending": False,
            "intel": {"ok": False, "lazy": True, "skip": True},
            "oversight": {"status": None, "lazy": True, "skip": True},
            "no_broker_actions": True,
            "evidence_refs": r.get("evidence_refs"),
            "tradeai_reason": r.get("tradeai_reason"),
            "strategy_id": strat_id or None,
            "resolved_strategy_id": strat_id or None,
            "strategy_display_name": sm.get("display_name"),
            "strategy_type": sm.get("strategy_type"),
            "strategy_type_label": sm.get("strategy_type_label"),
            "strategy_description": sm.get("purpose"),
            "routing_lane": "paper_atm" if is_automated_account(acct_raw) else "live_2fa",
        }
        if entry_disc or entry_origin:
            prot_row["entry_source"] = entry_disc or entry_origin
        prot_row["source_attribution"] = {
            "watchlist": False,
            "proposal": False,
            "label": "protection",
            "proposal_channel": "Protection · ATM",
            "routing_lane": prot_row["routing_lane"],
            "entry_source": prot_row.get("entry_source"),
        }
        out.append(prot_row)
    # Company context parity with entry proposals (2026-07-04 audit: protection cards showed
    # no company one-liner — this builder bypasses _broker_proposal_row_base's profile attach).
    try:
        pmap = _broker_symbol_profiles_batch([r.get("symbol") for r in out])
        for r in out:
            prof = pmap.get(str(r.get("symbol") or "").upper()) or {}
            r.setdefault("sector", prof.get("sector"))
            r.setdefault("industry", prof.get("industry"))
            r.setdefault("instrument_type", prof.get("instrument_type"))
            if prof.get("description_1s"):
                r.setdefault("company_description", str(prof["description_1s"])[:400])
    except Exception:
        pass
    return out


def _broker_proposals(query=None):
    """GET /api/v2/broker-proposals — fast list; per-card detail via POST /broker-proposals/detail.

    Query: page, page_size, sort, source, zone, symbol|q, account, strategy_id,
           min_live_rr, min_planned_rr, actionable, rr_preset (best|live_2|live_15|planned_2|actionable)
    Cached in-memory + disk (~120s) for fast tab load.
    Auto-recalibrates stale broker rows in DB (throttled ~5m) before serve.
    """
    # Auto-recal runs on a daemon thread (same throttle/writes) — inline it wedged the
    # request for the whole stale-queue requote whenever the 5-min throttle expired.
    autocal_meta: dict = _broker_autocal_kick()
    cache_key = _broker_list_cache_key(query)
    if str(_broker_qp(query, "refresh", "") or "").lower() not in ("1", "true", "yes"):
        cached = _broker_list_cache_get(cache_key)
        if cached:
            out = dict(cached)
            out["proposals"] = _broker_reprice_proposal_rows(out.get("proposals") or [])
            out["quotes_live"] = True
            out["queue_summary"] = _broker_queue_summary_fast()
            try:
                import broker_desk_automation as _bda

                out["desk_automation"] = _bda.get_desk_automation_state()
            except Exception:
                pass
            return out
    try:
        page = max(1, int(_broker_qp(query, "page", 1) or 1))
        page_size = min(50, max(5, int(_broker_qp(query, "page_size", 15) or 15)))
        sort = str(_broker_qp(query, "sort", "priority") or "priority").lower()
        source_f = str(_broker_qp(query, "source", "") or "").lower()
        zone_f = str(_broker_qp(query, "zone", "") or "").lower()
        symbol_f = str(_broker_qp(query, "symbol", _broker_qp(query, "q", "")) or "").upper().strip()
        account_f = str(_broker_qp(query, "account", "") or "").strip()
        strategy_f = str(_broker_qp(query, "strategy_id", _broker_qp(query, "strategy", "")) or "").strip()
        proposal_id_f = str(_broker_qp(query, "proposal_id", _broker_qp(query, "proposal", "")) or "").strip()
        if proposal_id_f.isdigit():
            _pid_row = _db_query(
                """SELECT id, symbol, strategy_id, COALESCE(target_account, proposed_account) AS account,
                          intended_broker, status, COALESCE(routing_state,'queued') AS routing_state,
                          COALESCE(origin,'auto') AS origin, discovery_source, cio_view, sizing_basis,
                          proposed_entry, proposed_stop, proposed_target1, current_price,
                          proposed_shares, proposed_dollar_size, proposed_dollar_risk, proposed_rr,
                          created_at, expires_at, updated_at, rvol, gap_pct, catalyst,
                          last_curated_at, curation_status, curation_snapshot, technical_context,
                          live_submit_path, last_correlation_id
                   FROM paper_trade_proposals WHERE id = %s LIMIT 1""",
                (int(proposal_id_f),),
                fetch="one",
            )
            if _pid_row:
                _wl = _fetch_watchlist_buy_symbols([_pid_row.get("symbol")])
                _prof = _broker_symbol_profiles_batch([_pid_row.get("symbol")])
                _row = _broker_proposal_row_base(_pid_row, {}, _wl, _prof)
                _acct = _row.get("account") or ""
                _row.update(_broker_account_label_meta(_acct))
                _row["activity"] = None
                _row["activity_pending"] = True
                _row["intel"] = {"ok": False, "lazy": True}
                _row["detail_pending"] = True
                _row["broker_diligence"] = None
                _row["oversight"] = {"status": None, "lazy": True}
                _one = _broker_reprice_proposal_rows([_row])
                accounts = (
                    _db_query("""SELECT account_key, broker, display_name FROM broker_accounts
                    WHERE broker ILIKE '%%schwab%%' OR broker ILIKE '%%fidelity%%' ORDER BY account_key""")
                    or []
                )
                return {
                    "proposals": _one,
                    "quotes_live": True,
                    "autocal": autocal_meta or None,
                    "list_mode": "proposal_deeplink",
                    "cached": False,
                    "pagination": {"page": 1, "page_size": 1, "total": 1, "total_pages": 1},
                    "filters": {"proposal_id": int(proposal_id_f), "symbol": _pid_row.get("symbol")},
                    "accounts": [
                        {
                            **{k: _json_clean(v) for k, v in a.items()},
                            **_broker_account_label_meta(a.get("account_key") or ""),
                        }
                        for a in accounts
                    ],
                }
        rr_f = _broker_parse_rr_filters(query)
        if sort == "priority" and rr_f.get("sort_hint"):
            sort = rr_f["sort_hint"]

        # Unified queue (kind=all): broker-routed entries + paper-source PROPOSALS (badged).
        # kind=broker → only schwab/fidelity routed; kind=proposal → only paper-source.
        kind_f = str(_broker_qp(query, "kind", "all") or "all").lower()
        broker_routed = (
            "(lower(COALESCE(intended_broker, target_account, proposed_account, '')) LIKE 'schwab%%'"
            " OR lower(COALESCE(intended_broker, target_account, proposed_account, '')) LIKE 'fidelity%%')"
        )
        # status view: default = active queue; status=EXPIRED → the Expired tab (chronological, newest
        # first, paginated). Account-agnostic — any account's expired proposals.
        status_view = str(_broker_qp(query, "status", "") or "").upper().strip()
        protection_only = kind_f == "protection" and status_view != "EXPIRED"
        if protection_only:
            prot_rows = _fetch_protection_union_rows(symbol_f, account_f)
            total = len(prot_rows)
            start = (page - 1) * page_size
            page_rows = prot_rows[start : start + page_size]
            total_pages = max(1, (total + page_size - 1) // page_size) if total else 1
            accounts = (
                _db_query("""SELECT account_key, broker, display_name FROM broker_accounts
                WHERE broker ILIKE '%%schwab%%' OR broker ILIKE '%%fidelity%%' ORDER BY account_key""")
                or []
            )
            sd = PROJECT_ROOT / "config" / "strategies"
            strategies = sorted(
                [
                    f.stem
                    for f in sd.glob("*.yaml")
                    if f.stem not in ("shared_risk_rules", "strategy_schema", "recommendation_schema")
                ]
            )
            acct_rows = []
            for a in accounts:
                row = {k: _json_clean(v) for k, v in a.items()}
                ak = row.get("account_key") or ""
                row.update(_broker_account_label_meta(ak))
                row["activity"] = None
                row["activity_pending"] = True
                acct_rows.append(row)
            return {
                "proposals": page_rows,
                "quotes_live": False,
                "autocal": autocal_meta or None,
                "curator": None,
                "accounts": acct_rows,
                "strategies": strategies,
                "list_mode": "fast",
                "cached": False,
                "pagination": {
                    "page": page,
                    "page_size": page_size,
                    "total": total,
                    "total_pages": total_pages,
                },
                "filters": {
                    "sort": sort,
                    "kind": kind_f,
                    "symbol": symbol_f or None,
                    "account": account_f or None,
                },
            }
        if status_view == "EXPIRED":
            where = ["status = 'EXPIRED'"]
            sort = "created"  # chronological, newest first
        else:
            where = ["status IN ('PENDING', 'APPROVED_FOR_PAPER_TEST')"]
        if kind_f == "broker":
            where.append(broker_routed)
        elif kind_f == "proposal":
            where.append("NOT " + broker_routed)
        # kind=all → no routing restriction (paper proposals + protection union on page 1)
        params: list = []
        if account_f:
            where.append("COALESCE(target_account, proposed_account) = %s")
            params.append(account_f)
        if symbol_f:
            where.append("UPPER(symbol) LIKE %s")
            params.append(f"%{symbol_f}%")
        if strategy_f:
            where.append("strategy_id = %s")
            params.append(strategy_f)
        if source_f == "watchlist":
            where.append("(COALESCE(origin,'') = 'watchlist' OR COALESCE(discovery_source,'') = 'watchlist')")
        elif source_f == "proposal":
            where.append("(COALESCE(origin,'') <> 'watchlist' AND COALESCE(discovery_source,'') <> 'watchlist')")
        elif source_f in ("pullback_macd", "pullback"):
            where.append("COALESCE(discovery_source,'') = 'pullback_macd'")

        where_sql = " AND ".join(where)
        total_row = (
            _db_query(
                f"SELECT COUNT(*) AS n FROM paper_trade_proposals WHERE {where_sql}",
                tuple(params) if params else None,
                fetch="one",
            )
            or {}
        )
        db_total = int(total_row.get("n") or 0)

        # Pullback/MACD triggers use signal_score when hermes_score is absent — keeps Telegram
        # alerts visible on page 1 instead of buried behind watchlist bridge rows.
        _queue_priority = (
            "CASE WHEN COALESCE(discovery_source,'') = 'pullback_macd' "
            "THEN GREATEST(COALESCE((sizing_basis->>'hermes_score')::float, 0), "
            "COALESCE(signal_score, 0), 70) "
            "ELSE COALESCE((sizing_basis->>'hermes_score')::float, 0) END"
        )
        order_sql = {
            "symbol": "symbol ASC, id ASC",
            "created": "created_at DESC, id DESC",
            "created_asc": "created_at ASC, id ASC",
            "rr": "COALESCE(proposed_rr, 0) DESC NULLS LAST, created_at DESC",
            "hermes": f"{_queue_priority} DESC NULLS LAST, symbol ASC",
            "priority": f"{_queue_priority} DESC NULLS LAST, created_at DESC, id DESC",
        }.get(sort, f"{_queue_priority} DESC NULLS LAST, created_at DESC, id DESC")

        protection_rows: list = []
        prot_count = 0
        if kind_f == "all" and status_view != "EXPIRED":
            protection_rows = _fetch_protection_union_rows(symbol_f, account_f)
            prot_count = len(protection_rows)

        # Zone, R:R filters, live-rr sort, and source=both need post-row filtering before pagination.
        needs_post = (
            bool(zone_f)
            or sort in ("zone", "rr_live")
            or source_f == "both"
            or rr_f.get("min_live_rr") is not None
            or rr_f.get("min_planned_rr") is not None
            or rr_f.get("actionable")
        )
        if needs_post:
            fetch_limit = min(1000, db_total)
            fetch_offset = 0
        elif prot_count and kind_f == "all":
            fetch_limit = page_size if page > 1 else max(0, page_size - prot_count)
            fetch_offset = max(0, (page - 1) * page_size - prot_count)
        else:
            fetch_limit = page_size
            fetch_offset = (page - 1) * page_size

        proposals = (
            _db_query(
                f"""SELECT id, symbol, strategy_id, COALESCE(target_account, proposed_account) AS account,
                       intended_broker, status, COALESCE(routing_state,'queued') AS routing_state,
                       COALESCE(origin,'auto') AS origin, discovery_source, cio_view, sizing_basis,
                       proposed_entry, proposed_stop, proposed_target1, current_price,
                       proposed_shares, proposed_dollar_size, proposed_dollar_risk, proposed_rr,
                       created_at, expires_at, updated_at, rvol, gap_pct, catalyst,
                       last_curated_at, curation_status, curation_snapshot, technical_context,
                       live_submit_path, last_correlation_id
                  FROM paper_trade_proposals
                 WHERE {where_sql}
                 ORDER BY {order_sql}
                 LIMIT %s OFFSET %s""",
                tuple(params + [fetch_limit, fetch_offset]),
            )
            or []
        )

        accounts = (
            _db_query("""SELECT account_key, broker, display_name FROM broker_accounts
            WHERE broker ILIKE '%%schwab%%' OR broker ILIKE '%%fidelity%%' ORDER BY account_key""")
            or []
        )
        sd = PROJECT_ROOT / "config" / "strategies"
        strategies = sorted(
            [
                f.stem
                for f in sd.glob("*.yaml")
                if f.stem not in ("shared_risk_rules", "strategy_schema", "recommendation_schema")
            ]
        )
        quote_map: dict = {}
        if needs_post and (rr_f.get("min_live_rr") is not None or sort == "rr_live"):
            post_syms = [str(r.get("symbol") or "").upper() for r in proposals if r.get("symbol")]
            quote_map = _broker_batch_live_quotes(post_syms) if BROKER_LIST_LIVE_QUOTES else {}
            if not quote_map:
                for r in proposals:
                    sym = str(r.get("symbol") or "").upper()
                    px = r.get("current_price")
                    if sym and px is not None:
                        try:
                            quote_map[sym] = {"last": float(px)}
                        except Exception:
                            pass

        wl_buy_syms = _fetch_watchlist_buy_symbols([r.get("symbol") for r in proposals])
        profiles_map = _broker_symbol_profiles_batch([r.get("symbol") for r in proposals])
        acct_meta_cache: dict = {}
        prop_rows = []
        for r in proposals:
            row = _broker_proposal_row_base(r, quote_map, wl_buy_syms, profiles_map)
            if source_f == "both":
                sa = row.get("source_attribution") or {}
                if sa.get("label") != "both":
                    continue
            acct = row.get("account") or ""
            if acct not in acct_meta_cache:
                acct_meta_cache[acct] = _broker_account_label_meta(acct)
            row.update(acct_meta_cache.get(acct) or {})
            row["activity"] = None
            row["activity_pending"] = True
            row["intel"] = {"ok": False, "lazy": True}
            row["detail_pending"] = True
            row["broker_diligence"] = None
            row["oversight"] = {"status": None, "lazy": True}
            prop_rows.append(row)

        if zone_f:
            prop_rows = [
                p for p in prop_rows if str((p.get("thesis_validity") or {}).get("zone_status") or "").lower() == zone_f
            ]
        if rr_f.get("min_live_rr") is not None:
            floor = float(rr_f["min_live_rr"])
            prop_rows = [
                p
                for p in prop_rows
                if not p.get("price_stale")
                and float((p.get("thesis_validity") or {}).get("current_rr") or p.get("live_rr") or 0) >= floor
            ]
        if rr_f.get("min_planned_rr") is not None:
            floor = float(rr_f["min_planned_rr"])
            prop_rows = [
                p
                for p in prop_rows
                if float((p.get("thesis_validity") or {}).get("planned_rr") or p.get("proposed_rr") or 0) >= floor
            ]
        if rr_f.get("actionable"):
            prop_rows = [p for p in prop_rows if (p.get("thesis_validity") or {}).get("actionable")]

        zone_rank = {"comfortable": 0, "approaching": 1, "at_risk": 2, "invalid": 3, "unknown": 4}
        if sort == "zone":
            prop_rows.sort(
                key=lambda p: zone_rank.get(
                    str((p.get("thesis_validity") or {}).get("zone_status") or "unknown").lower(), 4
                )
            )
        elif sort == "rr_live":
            prop_rows.sort(
                key=lambda p: float((p.get("thesis_validity") or {}).get("current_rr") or 0),
                reverse=True,
            )

        if needs_post:
            combined = (protection_rows + prop_rows) if prot_count else prop_rows
            total = len(combined)
            start = (page - 1) * page_size
            prop_rows = combined[start : start + page_size]
        else:
            total = db_total + prot_count
            if prot_count and page == 1:
                prop_rows = protection_rows + prop_rows

        total_pages = max(1, (total + page_size - 1) // page_size) if total else 1

        entry_rows = [r for r in prop_rows if r.get("queue_kind") != "protection"]
        if entry_rows:
            repriced = {r["id"]: r for r in _broker_reprice_proposal_rows(entry_rows)}
            prop_rows = [repriced.get(r["id"], r) if r.get("queue_kind") != "protection" else r for r in prop_rows]
        else:
            prop_rows = list(prop_rows)

        acct_rows = []
        for a in accounts:
            row = {k: _json_clean(v) for k, v in a.items()}
            ak = row.get("account_key") or ""
            row.update(_broker_account_label_meta(ak))
            row["activity"] = None
            row["activity_pending"] = True
            acct_rows.append(row)
        curator_meta = None
        try:
            _cp = PROJECT_ROOT / "data" / "runtime" / "broker_curator_last.json"
            if _cp.exists():
                curator_meta = json.loads(_cp.read_text(encoding="utf-8"))
        except Exception:
            pass
        queue_summary = _broker_queue_summary_fast()
        desk_automation = None
        try:
            import broker_desk_automation as _bda

            desk_automation = _bda.get_desk_automation_state()
        except Exception:
            pass
        result = {
            "proposals": prop_rows,
            "queue_summary": queue_summary,
            "desk_automation": desk_automation,
            "quotes_live": bool(BROKER_LIST_LIVE_QUOTES),
            "autocal": autocal_meta or None,
            "curator": curator_meta,
            "accounts": acct_rows,
            "strategies": strategies,
            "list_mode": "fast",
            "cached": False,
            "pagination": {
                "page": page,
                "page_size": page_size,
                "total": total,
                "total_pages": total_pages,
            },
            "filters": {
                "sort": sort,
                "kind": kind_f or None,
                "source": source_f or None,
                "zone": zone_f or None,
                "symbol": symbol_f or None,
                "account": account_f or None,
                "strategy_id": strategy_f or None,
                "rr_preset": rr_f.get("preset"),
                "min_live_rr": rr_f.get("min_live_rr"),
                "min_planned_rr": rr_f.get("min_planned_rr"),
                "actionable": rr_f.get("actionable") or None,
            },
        }
        _broker_list_cache_put(cache_key, result)
        # Trust enrichment on the cache-MISS path too — only the cache-HIT branch ran the
        # reprice/enrich hook, so a fresh build served held_shares/next_earnings as None
        # (caught in the PR #68 post-deploy verification). Enrich AFTER caching: held/earnings
        # are re-derived per serve so the cached copy stays enrichment-free like quotes.
        result = dict(result)
        result["proposals"] = _broker_enrich_trust_rows(list(result.get("proposals") or []))
        return result
    except Exception as e:
        stale = _broker_list_cache_get(cache_key)
        if stale:
            stale["error"] = str(e)[:120]
            return stale
        return {
            "error": str(e)[:160],
            "proposals": [],
            "accounts": [],
            "strategies": [],
            "pagination": {"page": 1, "page_size": 15, "total": 0, "total_pages": 1},
        }


def _broker_refresh_prices(body: dict):
    """POST /api/v2/broker-proposals/refresh-prices — live quote + thesis band + sizing recalc."""
    b = body or {}
    pid = int(b.get("proposal_id") or 0)
    if not pid:
        return {"ok": False, "error": "proposal_id required"}
    row = _db_query(
        """SELECT id, symbol, strategy_id, COALESCE(target_account, proposed_account) AS account,
                  intended_broker, status, proposed_entry, proposed_stop, proposed_target1,
                  proposed_shares, proposed_rr, current_price
           FROM paper_trade_proposals WHERE id=%s""",
        (pid,),
        fetch="one",
    )
    if not row:
        return {"ok": False, "error": f"proposal #{pid} not found"}
    sym = str(row.get("symbol") or "").upper()
    price_history = {}
    if sym:
        try:
            import sys as _sys_ph

            _sys_ph.path.insert(0, str(PROJECT_ROOT / "scripts"))
            from price_db_sync import ensure_price_history

            price_history = ensure_price_history([sym])
        except Exception:
            pass
    acct_override = str(b.get("account") or "").strip()
    quote = _broker_promote_quote(sym)
    last = quote.get("last")
    drift_pct = None
    if last is not None and row.get("proposed_entry"):
        try:
            drift_pct = round((float(last) - float(row["proposed_entry"])) / float(row["proposed_entry"]) * 100, 2)
        except Exception:
            pass
    try:
        _db_query(
            """UPDATE paper_trade_proposals
               SET current_price=%s, price_drift_pct=%s, updated_at=NOW()
               WHERE id=%s""",
            [last, drift_pct, pid],
        )
    except Exception:
        pass
    quote_map = {}
    if sym and last is not None:
        quote_map[sym] = {
            "bid": quote.get("bid"),
            "ask": quote.get("ask"),
            "last": last,
        }
        row["quote_provider"] = (
            quote.get("provider") or row.get("intended_broker") or "schwab"  # hardcode-ok fallback label
        )
        row["refreshed_at"] = datetime.now(timezone.utc).isoformat()[:19]
        row["updated_at"] = row["refreshed_at"]
    base = _broker_proposal_row_base(row, quote_map)
    if acct_override:
        base["account"] = acct_override
    base.update(_broker_account_execution_meta(base.get("account") or ""))
    enriched = _enrich_broker_proposal_row(base)
    recal = {}
    try:
        import broker_promote_sizing as bps

        acct = enriched.get("account") or ""
        strat = str(enriched.get("strategy_id") or "momentum_scalp")
        en = float(enriched.get("proposed_entry") or 0)
        st = float(enriched.get("proposed_stop") or 0)
        tg = float(enriched.get("proposed_target1") or 0)
        sizing = bps.compute_broker_sizing(acct, strat, en, st) if acct and en and st else {}
        rec_sh = int(sizing.get("shares") or enriched.get("proposed_shares") or 0)
        ev = (
            bps.evaluate_broker_promote(
                acct,
                strat,
                en,
                st,
                tg,
                rec_sh,
                quote=quote,
                proposal_id=int(pid) if pid else None,
            )
            if acct
            else {}
        )
        ev = _merge_broker_oversight(ev, pid) if ev else {}
        recal = {
            "recommended_shares": ev.get("recommended_shares") or rec_sh,
            "max_shares": ev.get("max_shares"),
            "evaluation": ev,
            "sizing": sizing,
            "quote": quote,
        }
        if ev:
            enriched["evaluation"] = ev
            enriched["gate_status"] = ev.get("status")
            enriched["oversight"] = ev.get("oversight") or enriched.get("oversight") or {}
            max_sh = int(ev.get("max_shares") or 0)
            sh = float(enriched.get("proposed_shares") or 0)
            enriched["broker_sizing"] = {
                "max_shares": max_sh,
                "recommended_shares": ev.get("recommended_shares"),
                "oversized": bool(sh and max_sh and int(sh) > max_sh),
                "binding": (ev.get("sizing") or {}).get("binding"),
                "violations": ev.get("violations") or [],
                "warnings": ev.get("warnings") or [],
            }
    except Exception:
        recal = {"quote": quote}
    enriched["refreshed_at"] = datetime.now(timezone.utc).isoformat()[:19]
    enriched["quote_provider"] = quote.get("provider")
    if price_history:
        enriched["price_history"] = price_history
    return {"ok": True, "data": enriched, "recalibration": recal}


def _broker_validate_trade(body: dict):
    """POST /api/v2/broker-proposals/validate — litmus test: live quote, thesis band, R:R, gates, cloud snapshot."""
    b = body or {}
    pid = int(b.get("proposal_id") or 0)
    if not pid:
        return {"ok": False, "error": "proposal_id required"}
    acct = str(b.get("account") or "").strip() or None
    refresh = str(b.get("refresh", "1")).lower() not in ("0", "false", "no")
    try:
        import broker_trade_litmus as litmus

        result = litmus.run_litmus(pid, account=acct, refresh=refresh)
        if not result.get("ok"):
            return result
        data = dict(result)
        if str(b.get("run_cloud", "")).lower() in ("1", "true", "yes"):
            try:
                import broker_promote_oversight as bpo

                cloud = bpo.run_cloud_oversight(pid, timeout=int(b.get("timeout") or 120))
                data["cloud_run"] = cloud
                data["oversight"] = bpo.evaluate_oversight(pid, cloud=cloud if cloud.get("ok") else None)
            except Exception as e:
                data["cloud_run"] = {"ok": False, "error": str(e)[:160]}
        return {"ok": True, "data": data, "litmus": data}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _broker_refresh_prices_batch(body: dict):
    """POST /api/v2/broker-proposals/refresh-prices-batch — batch live quotes + DB persist for many cards."""
    b = body or {}
    ids = b.get("proposal_ids") or b.get("ids") or []
    if not isinstance(ids, list) or not ids:
        return {"ok": False, "error": "proposal_ids required"}
    ids = [int(x) for x in ids[:50] if x]
    if not ids:
        return {"ok": False, "error": "no valid proposal ids"}
    rows = (
        _db_query(
            """SELECT id, symbol, strategy_id, COALESCE(target_account, proposed_account) AS account,
                  intended_broker, status, proposed_entry, proposed_stop, proposed_target1,
                  proposed_shares, proposed_rr, current_price
           FROM paper_trade_proposals WHERE id = ANY(%s)""",
            (ids,),
        )
        or []
    )
    if not rows:
        return {"ok": False, "error": "proposals not found"}
    _batch_syms = list(dict.fromkeys(str(r.get("symbol") or "").upper() for r in rows if r.get("symbol")))
    _batch_price_history = {}
    if _batch_syms:
        try:
            import sys as _sys_bph

            _sys_bph.path.insert(0, str(PROJECT_ROOT / "scripts"))
            from price_db_sync import ensure_price_history

            _batch_price_history = ensure_price_history(_batch_syms)
        except Exception:
            pass
    qmap = _broker_batch_live_quotes([r.get("symbol") for r in rows])
    refreshed = []
    for row in rows:
        pid = int(row.get("id") or 0)
        sym = str(row.get("symbol") or "").upper()
        q = qmap.get(sym) or {}
        last = q.get("last")
        drift_pct = None
        if last is not None and row.get("proposed_entry"):
            try:
                drift_pct = round((float(last) - float(row["proposed_entry"])) / float(row["proposed_entry"]) * 100, 2)
            except Exception:
                pass
        if last is not None:
            try:
                _db_query(
                    """UPDATE paper_trade_proposals
                       SET current_price=%s, price_drift_pct=%s, updated_at=NOW()
                       WHERE id=%s""",
                    [last, drift_pct, pid],
                )
            except Exception:
                pass
            row["quote_provider"] = q.get("provider")
            row["refreshed_at"] = q.get("refreshed_at") or datetime.now(timezone.utc).isoformat()[:19]
            row["updated_at"] = row["refreshed_at"]
        quote_map = {sym: q} if sym and q else {}
        base = _broker_proposal_row_base(row, quote_map)
        refreshed.append(
            {
                "id": pid,
                "symbol": sym,
                "thesis_validity": base.get("thesis_validity"),
                "price_stale": base.get("price_stale"),
            }
        )
    try:
        _BROKER_LIST_CACHE.clear()
    except Exception:
        pass
    out = {"ok": True, "refreshed_count": len(refreshed), "data": refreshed}
    if _batch_price_history:
        out["price_history"] = _batch_price_history
    return out


def _broker_proposal_detail(body: dict):
    """POST /api/v2/broker-proposals/detail — lazy-load gates for one queue card.

    Default light=1: DB intel packet + oversight + sizing (no live Schwab account snapshot).
    Pass light=0 or full=1 for live broker account activity + Schwab quote refresh (slow).
    """
    b = body or {}
    pid = int(b.get("proposal_id") or 0)
    if not pid:
        return {"ok": False, "error": "proposal_id required"}
    light = str(b.get("light", "1")).lower() not in ("0", "false", "no", "full")
    full = str(b.get("full", "0")).lower() in ("1", "true", "yes")
    row = _db_query(
        """SELECT id, symbol, strategy_id, COALESCE(target_account, proposed_account) AS account,
                  intended_broker, status, COALESCE(routing_state,'queued') AS routing_state,
                  COALESCE(origin,'auto') AS origin, discovery_source, cio_view, sizing_basis,
                  proposed_entry, proposed_stop, proposed_target1, current_price,
                  proposed_shares, proposed_dollar_size, proposed_dollar_risk, proposed_rr,
                  created_at, expires_at, updated_at,
                  last_curated_at, curation_status, curation_snapshot, technical_context
           FROM paper_trade_proposals WHERE id=%s""",
        (pid,),
        fetch="one",
    )
    if not row:
        return {"ok": False, "error": f"proposal #{pid} not found"}
    try:
        import broker_promote_oversight as _bpo_sync

        _bpo_sync.sync_proposal_reviews_from_watchlist(pid)
    except Exception:
        pass
    sym = str(row.get("symbol") or "").upper()
    quote_map = _broker_batch_live_quotes([sym]) if sym else {}
    if not light or full:
        try:
            import schwab_transport as _st

            sq = _st.get_quotes([sym])
            if sq.get("status") == "ok":
                live = (sq.get("quotes") or {}).get(sym) or {}
                if live.get("last") is not None:
                    quote_map[sym] = {
                        **(quote_map.get(sym) or {}),
                        "last": float(live["last"]),
                        "bid": live.get("bid"),
                        "ask": live.get("ask"),
                        "provider": "schwab",
                        "refreshed_at": datetime.now(timezone.utc).isoformat()[:19],
                    }
        except Exception:
            pass
    wl_buy = _fetch_watchlist_buy_symbols([sym])
    profiles_map = _broker_symbol_profiles_batch([sym])
    base = _broker_proposal_row_base(row, quote_map, wl_buy, profiles_map)
    acct = base.get("account") or ""
    if light and not full:
        base.update(_broker_account_label_meta(acct))
        base["activity"] = None
        base["activity_pending"] = True
        enriched = _enrich_broker_proposal_row_light(base)
    else:
        base.update(_broker_account_execution_meta(acct))
        base["activity"] = base.get("activity") or {}
        enriched = _enrich_broker_proposal_row(base)
    return {"ok": True, "data": enriched}


def _broker_promote_quote(symbol: str) -> dict:
    sym = str(symbol or "").upper()
    quote = {}
    try:
        import schwab_transport as _st

        sq = _st.get_quotes([sym]) if sym else {}
        if sq.get("status") == "ok":
            q = (sq.get("quotes") or {}).get(sym) or {}
            bid, ask, last = q.get("bid"), q.get("ask"), q.get("last")
            spread = None
            spread_pct = None
            if bid is not None and ask is not None and float(bid) > 0:
                spread = round(float(ask) - float(bid), 4)
                spread_pct = round(spread / float(bid) * 100, 3)
            quote = {
                "last": last,
                "bid": bid,
                "ask": ask,
                "spread": spread,
                "spread_pct": spread_pct,
                "provider": "schwab",
            }
    except Exception:
        pass
    if not quote.get("last"):
        try:
            from market_quote_provider import get_best_quote

            q = get_best_quote(sym) or {}
            quote = {
                "last": q.get("last_price"),
                "bid": q.get("bid"),
                "ask": q.get("ask"),
                "spread": q.get("spread"),
                "spread_pct": q.get("spread_pct"),
                "provider": q.get("provider"),
                "quote_timestamp": q.get("quote_timestamp"),
            }
        except Exception:
            pass
    return quote


def _broker_oversight_for_proposal(proposal_id: int, *, auto_queue_cloud: bool = True) -> dict:
    """Evaluate AI oversight; optionally spawn background Grok+ChatGPT when prerequisites are met."""
    import broker_promote_oversight as bpo

    pid = int(proposal_id)
    if auto_queue_cloud:
        try:
            bpo.maybe_queue_cloud_oversight(pid)
        except Exception:
            pass
    return bpo.evaluate_oversight(pid)


def _merge_broker_oversight(ev: dict, proposal_id: int | None) -> dict:
    if not proposal_id:
        return ev
    try:
        import broker_promote_oversight as bpo

        oversight = _broker_oversight_for_proposal(int(proposal_id))
        return bpo.merge_evaluation_with_oversight(ev, oversight)
    except Exception:
        return ev


def _evaluate_broker_promote(body: dict):
    """POST /api/v2/broker-proposals/evaluate-promote — sizing caps + PASS/WARN/BLOCK for modal."""
    import broker_promote_sizing as bps

    b = body or {}
    pid = int(b["proposal_id"]) if b.get("proposal_id") else None
    acct = str(b.get("account") or "").strip()
    shares = b.get("shares")
    entry = b.get("entry")
    stop = b.get("stop")
    target = b.get("target")
    strategy_id = str(b.get("strategy_id") or "").strip()
    if pid and not strategy_id:
        row = _db_query("SELECT strategy_id, symbol FROM paper_trade_proposals WHERE id=%s", (pid,), fetch="one") or {}
        strategy_id = str(row.get("strategy_id") or "momentum_scalp")
        symbol = str(row.get("symbol") or "")
    else:
        symbol = str(b.get("symbol") or "")
    if not (acct and shares is not None and entry is not None and stop is not None and target is not None):
        return {"ok": False, "error": "account, shares, entry, stop, target are required"}
    quote = b.get("quote") if isinstance(b.get("quote"), dict) else _broker_promote_quote(symbol)
    op_route = b.get("operator_route", True)
    if isinstance(op_route, str):
        op_route = op_route.lower() not in ("0", "false", "no")
    ev = bps.evaluate_broker_promote(
        acct,
        strategy_id or "momentum_scalp",
        float(entry),
        float(stop),
        float(target),
        int(shares),
        quote=quote,
        operator_route=bool(op_route),
        proposal_id=pid,
    )
    ev = _merge_broker_oversight(ev, pid)
    return {"ok": True, "data": ev, "quote": quote}


def _prepare_broker_promote(body: dict):
    """POST /api/v2/broker-proposals/prepare-promote — pre-fill Send-to-Broker modal from paper proposal."""
    import manual_execution_tracker as met
    import broker_promote_sizing as bps

    b = body or {}
    pid = int(b["proposal_id"]) if b.get("proposal_id") else None
    if not pid:
        return {"ok": False, "error": "proposal_id required"}
    row = (
        _db_query(
            """SELECT id, symbol, strategy_id, status, proposed_entry, proposed_stop, proposed_target1,
                  proposed_shares, proposed_rr, intended_broker, target_account
           FROM paper_trade_proposals WHERE id=%s""",
            (pid,),
            fetch="one",
        )
        or {}
    )
    if not row:
        return {"ok": False, "error": f"proposal #{pid} not found"}
    acct = str(b.get("account") or "").strip()
    if not acct:
        acct = str(row.get("target_account") or row.get("intended_broker") or "").strip()
    if not acct:
        accounts = (
            _db_query(
                """SELECT account_key, broker, display_name FROM broker_accounts
               WHERE broker ILIKE '%%schwab%%' OR broker ILIKE '%%fidelity%%'
               ORDER BY account_key"""
            )
            or []
        )
        for a in accounts:
            if "schwab" in (a.get("account_key") or "").lower():
                acct = a["account_key"]
                break
        if not acct and accounts:
            acct = accounts[0]["account_key"]
    prep = met.prepare_manual_execution(symbol=str(row.get("symbol") or ""), account=acct, proposal_id=pid)
    broker_key = (row.get("intended_broker") or row.get("target_account") or "").lower()
    already_broker = broker_key.startswith("schwab") or broker_key.startswith("fidelity")
    accounts = (
        _db_query(
            """SELECT account_key, broker, display_name FROM broker_accounts
           WHERE broker ILIKE '%%schwab%%' OR broker ILIKE '%%fidelity%%'
           ORDER BY account_key"""
        )
        or []
    )
    acct_rows = []
    for a in accounts:
        ar = {k: _json_clean(v) for k, v in a.items()}
        ar.update(_broker_account_execution_meta(ar.get("account_key") or ""))
        acct_rows.append(ar)
    rec = prep.get("recommended") or {}
    sym = str(row.get("symbol") or "").upper()
    quote = _broker_promote_quote(sym)

    def _econ(shares, entry, stop, target):
        sh = float(shares or 0)
        en = float(entry or 0)
        st = float(stop or 0)
        tg = float(target or 0)
        risk_ps = max(0.0, en - st)
        reward_ps = max(0.0, tg - en)
        return {
            "investment": round(sh * en, 2) if sh and en else None,
            "max_risk": round(risk_ps * sh, 2) if sh and risk_ps else None,
            "profit_at_target": round(reward_ps * sh, 2) if sh and reward_ps else None,
            "risk_per_share": round(risk_ps, 4) if risk_ps else None,
            "reward_per_share": round(reward_ps, 4) if reward_ps else None,
            "rr": round(reward_ps / risk_ps, 2) if risk_ps > 0 and reward_ps else None,
        }

    rec_sh = rec.get("shares") or row.get("proposed_shares")
    rec_en = rec.get("entry_price") or row.get("proposed_entry")
    rec_st = rec.get("stop_price") or row.get("proposed_stop")
    rec_tg = rec.get("target_price") or row.get("proposed_target1")
    strategy_id = str(row.get("strategy_id") or "momentum_scalp")

    sizing = bps.compute_broker_sizing(acct, strategy_id, float(rec_en or 0), float(rec_st or 0))
    rec_sh = sizing.get("shares") or rec_sh
    evaluation = bps.evaluate_broker_promote(
        acct,
        strategy_id,
        float(rec_en or 0),
        float(rec_st or 0),
        float(rec_tg or 0),
        int(rec_sh or 0),
        quote=quote,
        proposal_id=pid,
    )
    evaluation = _merge_broker_oversight(evaluation, pid)
    intel = {}
    oversight = evaluation.get("oversight") or {}
    diligence_auto_queued = False
    try:
        import broker_promote_oversight as _bpo

        if _bpo.needs_oversight_queue(pid):
            _bpo.queue_oversight_jobs(pid)
            diligence_auto_queued = True
        oversight = _broker_oversight_for_proposal(pid)
        evaluation = _bpo.merge_evaluation_with_oversight(evaluation, oversight)
        if str((oversight.get("cloud_review") or {}).get("status") or "").lower() == "running":
            diligence_auto_queued = True
    except Exception:
        pass
    diligence_plan = {}
    try:
        import broker_promote_oversight as _bpo2

        diligence_plan = _bpo2.build_promote_diligence_plan(pid)
    except Exception:
        diligence_plan = {}
    try:
        import broker_proposal_intel as _bpi

        intel = _bpi.get_intel_packet(pid)
        if isinstance(intel, dict):
            intel["oversight"] = oversight
    except Exception:
        intel = {"ok": False, "oversight": oversight}
    return {
        "ok": True,
        "data": {
            "proposal_id": pid,
            "symbol": sym,
            "strategy_id": strategy_id,
            "intel": intel,
            "oversight": oversight,
            "diligence_plan": diligence_plan,
            "diligence_auto_queued": diligence_auto_queued,
            "promote_ready": bool(diligence_plan.get("promote_ready") or oversight.get("promote_ready")),
            "status": row.get("status"),
            "already_on_broker_queue": already_broker,
            "current_broker": row.get("intended_broker"),
            "accounts": acct_rows,
            "quote": quote,
            "economics": _econ(rec_sh, rec_en, rec_st, rec_tg),
            "sizing": sizing,
            "evaluation": evaluation,
            "recommended": {
                "account": acct,
                "shares": rec_sh,
                "entry": rec_en,
                "stop": rec_st,
                "target": rec_tg,
                "risk_reward": rec.get("risk_reward") or row.get("proposed_rr"),
            },
            "paper_original": {
                "shares": row.get("proposed_shares"),
                "entry": row.get("proposed_entry"),
                "dollar_size": round(float(row.get("proposed_shares") or 0) * float(row.get("proposed_entry") or 0), 2)
                if row.get("proposed_shares") and row.get("proposed_entry")
                else None,
            },
            "origins": prep.get("origins") or [],
        },
    }


def _broker_oversight_snapshot(body: dict):
    """POST /api/v2/broker-proposals/oversight — AI review snapshot for modal."""
    import broker_promote_oversight as bpo

    pid = int((body or {}).get("proposal_id") or 0)
    if not pid:
        return {"ok": False, "error": "proposal_id required"}
    oversight = bpo.evaluate_oversight(pid)
    return {"ok": True, "data": oversight}


def _broker_run_cloud_oversight(body: dict):
    """POST /api/v2/broker-proposals/run-cloud-oversight — Grok+ChatGPT second opinion."""
    import broker_promote_oversight as bpo

    b = body or {}
    pid = int(b.get("proposal_id") or 0)
    if not pid:
        return {"ok": False, "error": "proposal_id required"}
    timeout = min(180, max(30, int(b.get("timeout") or 120)))
    raw_lanes = b.get("lanes")
    lanes = None
    if isinstance(raw_lanes, list) and raw_lanes:
        lanes = tuple(str(x).strip().lower() for x in raw_lanes if str(x).strip().lower() in ("grok", "chatgpt"))
    cloud = bpo.run_cloud_oversight(pid, timeout=timeout, lanes=lanes)
    if not cloud.get("ok") and cloud.get("error"):
        return {"ok": False, "error": cloud["error"], "data": cloud}
    oversight = bpo.evaluate_oversight(pid, cloud=cloud)
    return {"ok": True, "data": {"cloud": cloud, "oversight": oversight}}


def _broker_filtered_proposal_ids(query: dict | None, *, max_ids: int = 30) -> list[int]:
    """First N proposal IDs matching list filters (zone/source/etc.), up to max_ids."""
    list_res = _broker_proposals({**(query or {}), "page": "1", "page_size": str(max_ids)})
    return [int(r["id"]) for r in (list_res.get("proposals") or []) if r.get("id")]


def _broker_queue_cloud_batch(body: dict):
    """POST /api/v2/broker-proposals/queue-cloud-batch — queue cloud for filtered/page IDs only."""
    import broker_promote_oversight as bpo

    b = body or {}
    timeout = min(180, max(30, int(b.get("timeout") or 120)))
    max_batch = min(50, max(1, int(b.get("max") or 30)))
    scope = str(b.get("scope") or "ids").lower()
    if scope == "filtered":
        filt = b.get("filters") if isinstance(b.get("filters"), dict) else b
        ids = _broker_filtered_proposal_ids(filt, max_ids=max_batch)
    else:
        ids = []
        for raw in b.get("proposal_ids") or []:
            try:
                ids.append(int(raw))
            except Exception:
                pass
        ids = ids[:max_batch]
    if not ids:
        return {"ok": False, "error": "no proposal IDs to queue — adjust filters or select a page"}
    result = bpo.queue_cloud_oversight_batch(ids, timeout=timeout, max_batch=max_batch)
    result["scope"] = scope
    result["requested"] = len(ids)
    return {"ok": True, "data": result}


