# ── Feedback loop dashboard ───────────────────────────────────────────────


def _feedback_dashboard():
    """GET /api/v2/feedback-dashboard — Feedback loop closure metrics."""
    # Proposal outcome chain
    chain_stats = (
        _db_query("""
        SELECT chain_status, COUNT(*) as cnt
        FROM proposal_outcome_chain GROUP BY chain_status
    """)
        or []
    )

    # Alert effectiveness
    alert_eff = (
        _db_query("""
        SELECT notification_type,
               COUNT(*) as total,
               COUNT(*) FILTER (WHERE action_taken = true) as acted_on,
               AVG(effectiveness_score)::numeric(3,2) as avg_score
        FROM alert_effectiveness
        WHERE alert_date > CURRENT_DATE - 30
        GROUP BY notification_type ORDER BY total DESC
    """)
        or []
    )

    # Agent sample tracking
    agent_samples = (
        _db_query("""
        SELECT DISTINCT ON (agent_name)
               agent_name, resolved, correct, wrong, sample_tier,
               accuracy_pct, days_to_next_tier, snapshot_date
        FROM agent_sample_tracking
        ORDER BY agent_name, snapshot_date DESC
    """)
        or []
    )

    # Strategy snapshots (latest)
    strat_snaps = (
        _db_query("""
        SELECT strategy_id, trades_closed, wins, losses, win_rate,
               profit_factor, recommendation, snapshot_date
        FROM strategy_performance_snapshots
        WHERE snapshot_date = (SELECT MAX(snapshot_date) FROM strategy_performance_snapshots)
        ORDER BY trades_closed DESC
    """)
        or []
    )

    # Recovery outcomes
    recovery_outcomes = (
        _db_query("""
        SELECT symbol, final_verdict, patience_correct, days_monitored, reentry_pnl
        FROM recovery_outcome_log ORDER BY resolved_at DESC LIMIT 10
    """)
        or []
    )

    # CIO response rate
    cio_responses = (
        _db_query("""
        SELECT response, COUNT(*) as cnt
        FROM cio_decision_responses GROUP BY response
    """)
        or []
    )

    return {
        "proposal_chain": [{k: _json_clean(v) for k, v in r.items()} for r in chain_stats],
        "alert_effectiveness": [{k: _json_clean(v) for k, v in r.items()} for r in alert_eff],
        "agent_samples": [{k: _json_clean(v) for k, v in r.items()} for r in agent_samples],
        "strategy_snapshots": [{k: _json_clean(v) for k, v in r.items()} for r in strat_snaps],
        "recovery_outcomes": [{k: _json_clean(v) for k, v in r.items()} for r in recovery_outcomes],
        "cio_response_rate": [{k: _json_clean(v) for k, v in r.items()} for r in cio_responses],
    }


# ── Global alerts: persistent banner data ─────────────────────────────────


def _global_alerts():
    """GET /api/v2/global-alerts — Critical conditions for persistent banner.

    Returns alerts sorted by severity. Frontend displays as a banner
    across all pages until conditions resolve.
    """
    rm = _load_json(STATE_DIR / "risk_management.json") or {}
    freshness = _load_json(STATE_DIR / "_freshness.json") or {}

    alerts = []
    heat = rm.get("portfolio_heat_pct", 0)
    # Exclude retirement/buy-and-hold accounts from stop-loss alert
    _STOP_EXEMPT_ACCOUNTS = {"fidelity_401k", "schwab_rollover_ira", "schwab_roth_ira", "schwab_roth", "schwab_taxable"}
    no_stop = sum(
        1
        for p in rm.get("positions", [])
        if p.get("status") == "NO STOP" and (p.get("account", "") or "").lower() not in _STOP_EXEMPT_ACCOUNTS
    )
    triggered = [p.get("symbol", "?") for p in rm.get("positions", []) if p.get("status") == "TRIGGERED"]

    # Filter out operator-overridden symbols (HOLD_OVERRIDE in last 24h or snoozed)
    triggered = [s for s in triggered if s not in _get_stop_overrides()]

    if triggered:
        alerts.append(
            {
                "severity": "critical",
                "message": f"{len(triggered)} stop(s) triggered: {', '.join(triggered[:5])}",
                "action": "Review stops",
                "link": "/recovery",
            }
        )
    if heat > 5:
        alerts.append(
            {
                "severity": "warning",
                "message": f"Portfolio heat {heat:.1f}% — above 5% threshold",
                "action": "Review risk",
                "link": "/risk",
            }
        )
    if no_stop > 5:
        alerts.append(
            {
                "severity": "warning",
                "message": f"{no_stop} positions without stop losses",
                "action": "Set stops",
                "link": "/portfolio",
            }
        )

    # Data freshness
    completed = freshness.get("completed_at", "")
    if completed:
        try:
            from datetime import datetime as _dt

            age_h = (datetime.now() - _dt.fromisoformat(completed)).total_seconds() / 3600
            if age_h > 6:
                alerts.append(
                    {
                        "severity": "info",
                        "message": f"Data is {age_h:.0f}h old",
                        "action": "Check pipeline",
                        "link": "/pipeline",
                    }
                )
        except Exception:
            pass

    # Stale rebalance
    try:
        yo = _load_json(STATE_DIR / "yaml_advisor_output.json") or {}
        gen = yo.get("generated_at", "")
        if gen:
            from datetime import datetime as _dt2

            days = (datetime.now() - _dt2.fromisoformat(str(gen).replace("Z", "+00:00")).replace(tzinfo=None)).days
            if days > 14:
                alerts.append(
                    {
                        "severity": "info",
                        "message": f"Rebalance data is {days} days old",
                        "action": "View rebalance",
                        "link": "/rebalance",
                    }
                )
    except Exception:
        pass

    return {
        "alerts": alerts,
        "count": len(alerts),
        "has_critical": any(a["severity"] == "critical" for a in alerts),
        "freshness": {
            "last_refresh": freshness.get("completed_at"),
            "status": freshness.get("status", "unknown"),
        },
    }


# ── Deep Overnight LLM Queue endpoints ─────────────────────────────────────


def _queue_summary():
    from datetime import datetime, timedelta

    rows = _db_query("SELECT status, count(*) as cnt FROM deep_overnight_llm_queue GROUP BY status") or []
    by_status = {r["status"]: r["cnt"] for r in rows}
    tier_rows = (
        _db_query(
            "SELECT priority_tier, count(*) as cnt FROM deep_overnight_llm_queue WHERE status='pending' GROUP BY priority_tier"
        )
        or []
    )
    tier_map = {r["priority_tier"]: r["cnt"] for r in tier_rows}
    done_today = (
        _db_query(
            "SELECT count(*) as cnt FROM deep_overnight_llm_queue WHERE status='done' AND completed_at > NOW() - INTERVAL '24 hours'",
            fetch="one",
        )
        or {}
    ).get("cnt", 0)
    pending = by_status.get("pending", 0)
    cap = 100
    now = datetime.now()
    window_start = now.replace(hour=23, minute=0, second=0, microsecond=0)
    if now.hour >= 23:
        window_start += timedelta(days=1)
    next_hrs = max(0, (window_start - now).total_seconds() / 3600) if now.hour >= 3 else 0
    will_run = min(pending, cap)
    return {
        "pending": pending,
        "done_today": done_today,
        "failed": by_status.get("failed", 0),
        "running": by_status.get("running", 0),
        "cap_tonight": cap,
        "window_start": "23:00",
        "window_end": "03:00",
        "next_window_in_hours": round(next_hrs, 1),
        "estimated_completion_nights": round(pending / cap, 1) if cap else 0,
        "by_status": [{"status": s, "count": c} for s, c in by_status.items()],
        "job_budget": {
            "cap": cap,
            "pending_p0": tier_map.get("P0", 0),
            "pending_p1": tier_map.get("P1", 0),
            "pending_p2": tier_map.get("P2", 0),
            "pending_p3": tier_map.get("P3", 0),
            "pending_p4": tier_map.get("P4", 0),
            "will_run_tonight": will_run,
            "wont_run_tonight": max(0, pending - cap),
        },
    }


def _queue_pending():
    rows = (
        _db_query("""
        SELECT id, job_type, symbol, priority_tier, priority_score, reason_codes,
               queued_at, attempt_count, source_table, source_id,
               EXTRACT(EPOCH FROM (NOW() - queued_at))/3600 as age_hours
        FROM deep_overnight_llm_queue WHERE status = 'pending'
        ORDER BY priority_score DESC, queued_at ASC LIMIT 300
    """)
        or []
    )
    cap = 100
    jobs = []
    for i, r in enumerate(rows):
        d = {k: _json_clean(v) for k, v in r.items()}
        d["will_run_tonight"] = i < cap
        d["age_hours"] = round(float(d.get("age_hours") or 0), 1)
        jobs.append(d)
    return {"jobs": jobs, "total": len(jobs)}


def _queue_completed():
    rows = (
        _db_query("""
        SELECT q.id, q.job_type, q.symbol, q.priority_tier, q.priority_score,
               q.completed_at, q.last_gemma_runtime_sec as duration_seconds, q.last_error,
               r.summary, r.curation_verdict, r.curation_weight,
               r.risk_narrative, r.reentry_verdict, r.cc_verdict
        FROM deep_overnight_llm_queue q
        LEFT JOIN deep_overnight_llm_results r ON r.queue_id = q.id
        WHERE q.status = 'done' AND q.completed_at > NOW() - INTERVAL '24 hours'
        ORDER BY q.completed_at DESC LIMIT 200
    """)
        or []
    )
    jobs = [{**{k: _json_clean(v) for k, v in r.items()}, "had_error": bool(r.get("last_error"))} for r in rows]
    durs = [float(r.get("duration_seconds") or 0) for r in rows if r.get("duration_seconds")]
    return {
        "jobs": jobs,
        "total": len(jobs),
        "stats": {
            "total_ran": len(jobs),
            "avg_duration": round(sum(durs) / len(durs), 1) if durs else 0,
            "fastest": round(min(durs), 1) if durs else 0,
            "slowest": round(max(durs), 1) if durs else 0,
            "error_count": sum(1 for r in rows if r.get("last_error")),
        },
    }


def _queue_failed():
    rows = (
        _db_query("""
        SELECT id, job_type, symbol, priority_tier, priority_score,
               attempt_count, last_error, started_at, completed_at, queued_at
        FROM deep_overnight_llm_queue
        WHERE status IN ('failed', 'error') OR (attempt_count > 1 AND status = 'pending')
        ORDER BY queued_at DESC LIMIT 100
    """)
        or []
    )
    return {"jobs": [{k: _json_clean(v) for k, v in r.items()} for r in rows], "total": len(rows)}


def _system_health_api():
    """System Health Agent — latest checks for all monitored components."""
    # Get latest check per component
    checks = (
        _db_query("""
        SELECT DISTINCT ON (component)
            component, check_type, status, expected_schedule, last_success_at,
            last_failure_at, last_run_duration_sec, expected_max_duration_sec,
            failure_count, retry_count, last_error, last_action, downstream_impact,
            severity, updated_at
        FROM system_health_checks
        ORDER BY component, updated_at DESC
    """)
        or []
    )
    # Summary
    ok = sum(1 for c in checks if c.get("status") == "OK")
    stale = sum(1 for c in checks if c.get("status") == "STALE")
    missing = sum(1 for c in checks if c.get("status") == "MISSING")
    failed = sum(1 for c in checks if c.get("status") in ("OUTPUT_INVALID", "LOCK_TIMEOUT", "STALE_LOCK"))
    recovered = sum(1 for c in checks if c.get("status") == "RECOVERED")
    total = len(checks)
    # Recent events
    events = (
        _db_query("""
        SELECT component, event_type, severity, message, action_taken, success, created_at
        FROM system_health_events ORDER BY created_at DESC LIMIT 50
    """)
        or []
    )
    # P0.5B: safe_flock event summary
    _sf = {"events_seen": 0, "lock_skips": 0, "repeated_lock_skips": 0, "stale_locks_cleared": 0, "command_failures": 0}
    try:
        import json as _sfj

        _sf_log = PROJECT_ROOT / "logs" / "safe_flock_events.jsonl"
        if _sf_log.exists():
            _sf_cutoff = __import__("datetime").datetime.now(__import__("datetime").timezone.utc) - __import__(
                "datetime"
            ).timedelta(hours=1)
            _skip_counts = {}
            for _line in open(_sf_log):
                _line = _line.strip()
                if not _line:
                    continue
                try:
                    _ev = _sfj.loads(_line)
                    _ts = __import__("datetime").datetime.fromisoformat(_ev.get("ts", ""))
                    if _ts.tzinfo:
                        _ts = _ts.astimezone(__import__("datetime").timezone.utc)
                    if _ts >= _sf_cutoff:
                        _sf["events_seen"] += 1
                        if _ev.get("event_type") == "lock_skip":
                            _sf["lock_skips"] += 1
                            _c = _ev.get("component", "")
                            _skip_counts[_c] = _skip_counts.get(_c, 0) + 1
                        elif _ev.get("event_type") == "stale_lock_cleared":
                            _sf["stale_locks_cleared"] += 1
                        elif _ev.get("event_type") == "completed" and _ev.get("exit_code", 0) != 0:
                            _sf["command_failures"] += 1
                except Exception:
                    pass
            _sf["repeated_lock_skips"] = sum(1 for v in _skip_counts.values() if v >= 2)
    except Exception:
        pass

    # P0.5B: time-stop review summary
    _ts_summary = {
        "total_open": 0,
        "overdue_count": 0,
        "review_due_count": 0,
        "approaching_count": 0,
        "overdue_positions": [],
    }
    try:
        _open_trades = (
            _db_query("""
            SELECT id, symbol, strategy_id, entry_time FROM paper_trades WHERE exit_time IS NULL AND (exit_reason IS NULL OR exit_reason = '')
        """)
            or []
        )
        from strategy_trailing_policy import get_trailing_policy as _gtp

        _now_utc = __import__("datetime").datetime.now(__import__("datetime").timezone.utc)
        _ts_summary["total_open"] = len(_open_trades)
        for _t in _open_trades:
            _pol = _gtp(_t.get("strategy_id", ""))
            _tsc = _pol.get("time_stop", {})
            _ttype = _tsc.get("type", "review")
            _et = _t.get("entry_time")
            if not _et:
                continue
            if hasattr(_et, "tzinfo") and _et.tzinfo is None:
                _et = _et.replace(tzinfo=__import__("datetime").timezone.utc)
            _hold = (_now_utc - _et).days
            if _ttype == "intraday" and _hold > 0:
                _ts_summary["overdue_count"] += 1
                _ts_summary["overdue_positions"].append(
                    {"symbol": _t["symbol"], "strategy": _t["strategy_id"], "hold_days": _hold, "type": "intraday"}
                )
            elif _ttype == "calendar":
                _max = _tsc.get("max_hold_days", 21)
                if _hold > _max:
                    _ts_summary["overdue_count"] += 1
                    _ts_summary["overdue_positions"].append(
                        {
                            "symbol": _t["symbol"],
                            "strategy": _t["strategy_id"],
                            "hold_days": _hold,
                            "type": "calendar",
                            "max": _max,
                        }
                    )
                elif _hold > _max * 0.8:
                    _ts_summary["approaching_count"] += 1
            elif _ttype == "review":
                _rev = _tsc.get("review_at_days", 90)
                if _hold >= _rev:
                    _ts_summary["review_due_count"] += 1
    except Exception:
        pass

    # P0.5B: alert routing inventory
    _alert_routing = {
        "bypass_router_files": 3,
        "direct_telegram_senders": 64,
        "direct_api_telegram": 40,
        "migration_status": "P0.5_AUDIT_ONLY",
    }

    return {
        "ok": True,
        "summary": {
            "total": total,
            "ok": ok,
            "stale": stale,
            "missing": missing,
            "failed": failed,
            "recovered": recovered,
        },
        "checks": [{k: _json_clean(v) for k, v in c.items()} for c in checks],
        "recent_events": [{k: _json_clean(v) for k, v in e.items()} for e in events],
        "safe_flock": _sf,
        "time_stop_summary": _ts_summary,
        "alert_routing": _alert_routing,
    }


