def _journal_integrity_warnings():
    """Check paper_trades data integrity. Returns list of warning strings."""
    warnings = []
    try:
        r1 = _db_query(
            "SELECT COUNT(*) as cnt FROM paper_trades WHERE lifecycle_state='open' AND filled_at IS NULL AND broker_status NOT IN ('filled')",
            fetch="one",
        )
        if r1 and r1.get("cnt", 0) > 0:
            warnings.append(f"{r1['cnt']} open trade(s) never confirmed filled")
        r2 = _db_query(
            "SELECT COUNT(*) as cnt FROM paper_trades WHERE lifecycle_state='closed' AND outcome_verdict IS NULL AND pnl IS NOT NULL",
            fetch="one",
        )
        if r2 and r2.get("cnt", 0) > 0:
            warnings.append(f"{r2['cnt']} closed trade(s) missing outcome verdict")
        r3 = (
            _db_query(
                "SELECT symbol, COUNT(*) as cnt FROM paper_trades WHERE lifecycle_state='open' GROUP BY symbol HAVING COUNT(*)>1"
            )
            or []
        )
        for r in r3:
            warnings.append(f"{r['symbol']} has {r['cnt']} open records — possible duplicate")
    except Exception:
        pass
    return warnings


def _strategy_intelligence():
    """GET /api/v2/strategy-intelligence — health dashboard for all 20 strategies."""
    import yaml, glob

    strategies = []
    yaml_dir = PROJECT_ROOT / "config" / "strategies"
    for f in sorted(glob.glob(str(yaml_dir / "*.yaml"))):
        if "schema" in f or "shared" in f or "recommendation" in f:
            continue
        try:
            with open(f) as fh:
                y = yaml.safe_load(fh) or {}
            sid = y.get("strategy_id", "")
            if not sid:
                continue
            # Get governance data
            gov = (
                _db_query(
                    "SELECT governance_state, paper_trades, closed_trades, win_rate, profit_factor, expectancy_r, avg_r FROM paper_performance_governance WHERE strategy_id=%s ORDER BY created_at DESC LIMIT 1",
                    [sid],
                    fetch="one",
                )
                or {}
            )
            # Get proposal/trade counts
            prop_count = (
                _db_query(
                    "SELECT count(*) as n FROM paper_trade_proposals WHERE strategy_id=%s AND status='PENDING'",
                    [sid],
                    fetch="one",
                )
                or {}
            ).get("n", 0)
            trade_count = gov.get("closed_trades") or 0
            strategies.append(
                {
                    "strategy_id": sid,
                    "display_name": y.get("display_name", sid.replace("_", " ").title()),
                    "governance_state": gov.get("governance_state", "UNVALIDATED"),
                    "trade_count": trade_count,
                    "win_rate": float(gov["win_rate"]) if gov.get("win_rate") else None,
                    "profit_factor": float(gov["profit_factor"]) if gov.get("profit_factor") else None,
                    "avg_r": float(gov["avg_r"]) if gov.get("avg_r") else None,
                    "expectancy": float(gov["expectancy_r"]) if gov.get("expectancy_r") else None,
                    "trades_to_validation": max(0, 30 - (trade_count or 0)),
                    "active_proposals": prop_count,
                    "yaml_version": y.get("version", "?"),
                    "has_entry_criteria": len(y.get("entry_criteria", [])) >= 4,
                    "has_auto_disqualifiers": len(y.get("auto_disqualifiers", [])) >= 3,
                    "has_agent_responsibilities": bool(y.get("agent_responsibilities")),
                    "has_vix_rules": bool(y.get("vix_rules")),
                    "has_technical_indicators": bool(y.get("technical_indicators_required")),
                    "co_enables": y.get("co_enables", []),
                    "performance_verdict": "PERFORMING"
                    if gov.get("profit_factor") and float(gov["profit_factor"]) >= 1.3
                    else "UNDERPERFORMING"
                    if gov.get("profit_factor") and float(gov["profit_factor"]) < 0.8
                    else "ACCUMULATING"
                    if trade_count
                    else "NO_DATA",
                }
            )
        except Exception:
            continue

    seen = {s["strategy_id"] for s in strategies}
    extra_rows = (
        _db_query("""
        WITH ids AS (
            SELECT DISTINCT strategy_id FROM paper_trade_proposals
            WHERE strategy_id IS NOT NULL AND strategy_id <> ''
            UNION
            SELECT DISTINCT strategy_id FROM paper_trades
            WHERE strategy_id IS NOT NULL AND strategy_id <> ''
        )
        SELECT i.strategy_id,
               COALESCE(p.n, 0) AS active_proposals,
               COALESCE(o.n, 0) AS open_trades,
               COALESCE(c.n, 0) AS closed_90d
        FROM ids i
        LEFT JOIN (
            SELECT strategy_id, count(*) AS n FROM paper_trade_proposals
            WHERE status = 'PENDING' AND COALESCE(proposal_kind, 'entry') = 'entry'
            GROUP BY strategy_id
        ) p ON p.strategy_id = i.strategy_id
        LEFT JOIN (
            SELECT strategy_id, count(*) AS n FROM paper_trades WHERE status = 'open'
            GROUP BY strategy_id
        ) o ON o.strategy_id = i.strategy_id
        LEFT JOIN (
            SELECT strategy_id, count(*) AS n FROM paper_trades
            WHERE status = 'closed' AND closed_at > NOW() - INTERVAL '90 days'
            GROUP BY strategy_id
        ) c ON c.strategy_id = i.strategy_id
    """)
        or []
    )
    for r in extra_rows:
        sid = str(r.get("strategy_id") or "")
        if not sid or sid in seen:
            continue
        sm = _broker_strategy_meta(sid)
        strategies.append(
            {
                "strategy_id": sid,
                "display_name": sm.get("display_name") or sid.replace("_", " ").title(),
                "governance_state": "DB_ACTIVE_NO_YAML",
                "trade_count": int(r.get("closed_90d") or 0),
                "win_rate": None,
                "profit_factor": None,
                "avg_r": None,
                "expectancy": None,
                "trades_to_validation": max(0, 30 - int(r.get("closed_90d") or 0)),
                "active_proposals": int(r.get("active_proposals") or 0),
                "open_trades": int(r.get("open_trades") or 0),
                "yaml_version": None,
                "has_entry_criteria": False,
                "has_auto_disqualifiers": False,
                "has_agent_responsibilities": False,
                "has_vix_rules": False,
                "has_technical_indicators": False,
                "co_enables": [],
                "performance_verdict": "NO_YAML",
                "source": "db_active",
            }
        )
        seen.add(sid)

    unvalidated = sum(
        1 for s in strategies if s["governance_state"] in ("UNVALIDATED", "DB_ACTIVE_NO_YAML", "PAPER_ONLY")
    )
    with_proposals = sum(1 for s in strategies if s["active_proposals"] > 0)
    return {
        "strategies": strategies,
        "summary": {
            "total_strategies": len(strategies),
            "unvalidated": unvalidated,
            "with_proposals": with_proposals,
            "without_proposals": len(strategies) - with_proposals,
            "total_closed_trades": sum(s["trade_count"] or 0 for s in strategies),
            "db_active_no_yaml": sum(1 for s in strategies if s.get("source") == "db_active"),
        },
    }


