def _system_scheduled_jobs():
    """GET /api/v2/system/scheduled-jobs — read-only scheduler health."""
    import subprocess as _sp

    def _run(cmd, timeout=10):
        try:
            import os as _os

            # portfolio_server runs as a SYSTEM service; `systemctl --user` needs the user bus
            # env or it returns nothing → every timer shows 'unknown'. Inject XDG_RUNTIME_DIR.
            env = dict(_os.environ)
            env.setdefault("XDG_RUNTIME_DIR", f"/run/user/{_os.getuid()}")
            r = _sp.run(cmd, capture_output=True, text=True, timeout=timeout, shell=isinstance(cmd, str), env=env)
            # is-active reports active/inactive/failed on stdout even with non-zero exit.
            return r.stdout.strip() or r.stderr.strip()
        except Exception:
            return ""

    # Systemd user timers — scan unit files directly
    timers = []
    import glob as _gl

    timer_dir = Path.home() / ".config" / "systemd" / "user"
    if timer_dir.exists():
        timer_files = sorted(timer_dir.glob("*.timer"))
        unit_names = [tf.name for tf in timer_files]

        def _batch_states(verb):
            """One systemctl call for all units (is-active/is-enabled print one state per line,
            in order). Falls back to per-unit only if the line count doesn't align."""
            if not unit_names:
                return {}
            lines = _run(f"systemctl --user {verb} " + " ".join(unit_names)).splitlines()
            if len(lines) == len(unit_names):
                return {n: lines[i].strip() for i, n in enumerate(unit_names)}
            return {n: _run(f"systemctl --user {verb} {n}").strip() for n in unit_names}

        active_map = _batch_states("is-active")
        enabled_map = _batch_states("is-enabled")
        for tf in timer_files:
            status = active_map.get(tf.name) or "unknown"
            enabled = enabled_map.get(tf.name) or "unknown"
            # A disabled timer sitting inactive is retired/superseded (intentional), not a fault —
            # surface it explicitly so the UI stops reading it as an alarming bare "inactive".
            retired = enabled == "disabled" and status == "inactive"
            timers.append(
                {"name": tf.stem, "status": status, "enabled": enabled, "retired": retired, "type": "systemd_user"}
            )

    hermes_timers = [t for t in timers if "hermes" in t["name"]]
    tradeai_timers = [t for t in timers if "tradeai" in t["name"]]

    # Cron count
    cron_out = _run("crontab -l 2>/dev/null | grep -v '^#' | grep -v '^$' | grep -v '^SHELL\\|^PROJ\\|^PY' | wc -l")
    cron_count = int(cron_out) if cron_out.isdigit() else 0
    migrated = _run("crontab -l 2>/dev/null | grep -c 'PHASE41-MIGRATED'")
    migrated_count = int(migrated) if migrated.isdigit() else 0

    # Observation/backlog latest
    obs_ts = None
    bl_ts = None
    try:
        import json as _jsj

        obs_f = Path(str(PROJECT_ROOT)) / "docs" / "hermes" / "observations" / "latest_observation_summary.json"
        if obs_f.exists():
            obs_ts = _jsj.loads(obs_f.read_text()).get("timestamp")
        bl_f = Path(str(PROJECT_ROOT)) / "docs" / "hermes" / "backlog_health" / "latest_backlog_health_summary.json"
        if bl_f.exists():
            bl_ts = _jsj.loads(bl_f.read_text()).get("timestamp")
    except Exception:
        pass

    return {
        "ok": True,
        "timers": {
            "total": len(timers),
            "hermes": [
                {"name": t["name"], "status": t["status"], "enabled": t["enabled"], "retired": t["retired"]}
                for t in hermes_timers
            ],
            "tradeai": [
                {"name": t["name"], "status": t["status"], "enabled": t["enabled"], "retired": t["retired"]}
                for t in tradeai_timers
            ],
            "other_count": len(timers) - len(hermes_timers) - len(tradeai_timers),
        },
        "cron": {
            "active": cron_count,
            "migrated": migrated_count,
        },
        "health": {
            "last_observation": obs_ts,
            "last_backlog_health": bl_ts,
        },
    }


