def _hermes_scope_governor(query=None):
    """GET /api/v2/hermes/scope-governor — governed universe feed + recent tier decisions.

    Read-only. Sole scope owner is hermes_scope_governor.py; Hermes consumers read this feed
    rather than deciding their own scope. Hot/Warm/Cold = S0+S1 / S2 / S3.
    """
    q = query or {}
    symbol = (q.get("symbol") or [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol")
    try:
        import sys as _sysc

        _sysc.path.insert(0, str(PROJECT_ROOT / "scripts" / "lib"))
        from lib.hermes_scope_governor.universe import read_universe_feed
        from lib.hermes_scope_governor.config import load_config

        feed = read_universe_feed() or {}
        cfg = load_config(PROJECT_ROOT / "config" / "hermes_scope_governor.yaml")
        audit = (
            _db_query(
                """SELECT run_id, symbol, action, from_tier, to_tier, reason, created_at
                             FROM scope_governor_audit
                             """
                + ("WHERE UPPER(symbol)=UPPER(%s) " if symbol else "")
                + "ORDER BY created_at DESC LIMIT %s",
                ((symbol.upper(), 25) if symbol else (30,)),
            )
            or []
        )
        if symbol and feed.get("symbols"):
            sym_row = next(
                (s for s in feed["symbols"] if str(s.get("symbol", "")).upper() == str(symbol).upper()), None
            )
        else:
            sym_row = None
        lifecycle = {}
        lifecycle_audit = []
        try:
            from lib.hermes_scope_governor.watchlist_lifecycle import (
                load_lifecycle_audit_tail,
                load_lifecycle_state,
            )

            lifecycle = load_lifecycle_state()
            lifecycle_audit = load_lifecycle_audit_tail(15)
        except Exception:
            pass
        return _json_clean(
            {
                "ok": True,
                "advisory_notice": "Scope Governor — advisory only; Hermes reads this feed, does not self-scope",
                "philosophy": "outcome_yield_outranks_throughput",
                "heat_map": {"hot": "S0+S1", "warm": "S2", "cold": "S3"},
                "config_total_cap": cfg.get("total_cap", 800),
                "scoring_weights": (cfg.get("scoring") or {}).get("weights"),
                "universe": feed,
                "symbol_detail": sym_row,
                "recent_audit": audit,
                "watchlist_lifecycle": lifecycle,
                "watchlist_lifecycle_audit": lifecycle_audit,
            }
        )
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _hermes_research_critique(query=None):
    """GET /api/v2/hermes/research-critique — shared librarian/taxonomy scores + stale removal flags.

    Primary source: data/runtime/research_critique_latest.json (written each curator tick).
    Supplements with live DB index for scored directives and open critique findings.
    """
    q = query or {}
    agent = (q.get("agent") or [None])[0] if isinstance(q.get("agent"), list) else q.get("agent")
    snapshot = {}
    try:
        import sys as _sysc

        _sysc.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from research_critique_pipeline import load_critique_snapshot, extract_critique_fields

        snapshot = load_critique_snapshot()
    except Exception as e:
        snapshot = {"load_error": str(e)[:160]}

    findings_sql = """
        SELECT id, hermes_agent_name, finding_type, severity, symbol,
               affected_table, affected_id, LEFT(description, 300) AS description,
               evidence_json, recommended_action, status, created_at
        FROM hermes_validation_findings
        WHERE source='hermes' AND hermes_agent_name='research_critique_pipeline'
    """
    args = []
    if agent:
        findings_sql += " AND hermes_agent_name=%s"
        args.append(agent)
    findings_sql += " ORDER BY created_at DESC LIMIT 60"
    findings = _db_query(findings_sql, tuple(args) if args else None) or []

    directives = (
        _db_query("""
        SELECT id, kind, label, status, priority, created_by, spec, updated_at
        FROM watch_directives
        WHERE status IN ('active', 'paused')
          AND created_by IN ('think_tank', 'sector_universe')
        ORDER BY updated_at DESC NULLS LAST
        LIMIT 60
    """)
        or []
    )
    scored = []
    for d in directives:
        spec = d.get("spec") or {}
        critique = extract_critique_fields(spec)
        if not critique:
            continue
        scored.append(
            {
                "id": d["id"],
                "label": d.get("label"),
                "status": d.get("status"),
                "created_by": d.get("created_by"),
                "updated_at": _json_clean(d.get("updated_at")),
                "critique": {k: _json_clean(v) for k, v in critique.items()},
            }
        )

    consciousness = {}
    try:
        consciousness = json.loads((PROJECT_ROOT / "data" / "runtime" / "hermes_consciousness_latest.json").read_text())
    except Exception:
        pass

    return {
        "ok": True,
        "snapshot": {k: _json_clean(v) for k, v in snapshot.items()},
        "scored_directives": scored,
        "open_findings": [{k: _json_clean(v) for k, v in f.items()} for f in findings if f.get("status") == "open"],
        "findings_recent": [{k: _json_clean(v) for k, v in f.items()} for f in findings[:20]],
        "consciousness_attention": consciousness.get("attention"),
        "shared_paths": snapshot.get("shared_paths")
        or {
            "critique_latest": "data/runtime/research_critique_latest.json",
            "consciousness": "data/runtime/hermes_consciousness_latest.json",
        },
        "advisory_notice": "Librarian/taxonomy critique — shared with Trade AI processes; advisory only",
    }


def _hermes_intelligence():
    """GET /api/v2/hermes/intelligence — full Hermes intelligence view."""
    rows = (
        _db_query("""
        SELECT r.id, r.hermes_agent_name, r.research_type, r.symbol, r.topic,
               LEFT(r.summary, 500) AS summary, LEFT(r.thesis, 300) AS thesis,
               r.confidence_score, r.status, r.freshness_date, r.model_used, r.created_at,
               CASE WHEN ce.id IS NOT NULL THEN true ELSE false END AS embedded
        FROM hermes_research_intelligence r
        LEFT JOIN content_embeddings ce ON ce.source_type = 'hermes_research' AND ce.source_id = r.id
        ORDER BY r.created_at DESC
    """)
        or []
    )
    audit = (
        _db_query("""
        SELECT source_id, target_table, promoted_at FROM hermes_promotion_audit ORDER BY promoted_at DESC
    """)
        or []
    )
    promoted = sum(1 for r in rows if r.get("status") == "promoted")
    staged = sum(1 for r in rows if r.get("status") == "staged")
    embedded = sum(1 for r in rows if r.get("embedded"))
    return {
        "ok": True,
        "rows": [{k: _json_clean(v) for k, v in r.items()} for r in rows],
        "total": len(rows),
        "promoted": promoted,
        "staged": staged,
        "embedded": embedded,
        "audit": [{k: _json_clean(v) for k, v in a.items()} for a in audit],
    }


