def _analyst_detail(query=None):
    """GET /api/v2/analyst-detail[?symbol=X][?map=1] — per-symbol analyst breakdown for the bulleted card
    view: rating distribution (strong_buy/buy/hold/sell, finnhub) + target range (mean/median/high/low,
    Yahoo) + counts + dates/sources. NOTE: sources aggregate — no individual firm names are available.
    Read-only/advisory."""
    q = query or {}
    sym = q.get("symbol")
    sym = (sym[0] if isinstance(sym, list) else sym or "").upper().strip()
    want_map = bool(q.get("map"))
    # latest target snapshot per symbol (Yahoo)
    tgt_rows = (
        _db_query(
            """SELECT DISTINCT ON (upper(symbol)) upper(symbol) s, target_mean_price, target_median_price,
                              target_high_price, target_low_price, number_of_analyst_opinions, recommendation_key,
                              current_price, snapshot_date
                            FROM yahoo_analyst_targets_history
                            {} ORDER BY upper(symbol), snapshot_date DESC""".format(
                "WHERE upper(symbol)=%s" if sym else ""
            ),
            ((sym,) if sym else None),
        )
        or []
    )
    # latest rating distribution per symbol (finnhub)
    dist_rows = (
        _db_query(
            """SELECT DISTINCT ON (upper(symbol)) upper(symbol) s, payload
                             FROM analyst_data_history
                             {} ORDER BY upper(symbol), as_of DESC""".format("WHERE upper(symbol)=%s" if sym else ""),
            ((sym,) if sym else None),
        )
        or []
    )
    dist = {}
    for r in dist_rows:
        p = r["payload"] if isinstance(r["payload"], dict) else {}
        dist[r["s"]] = p

    def _f(v):
        try:
            return round(float(v), 2)
        except Exception:
            return None

    out = {}
    for r in tgt_rows:
        s = r["s"]
        mean = _f(r["target_mean_price"])
        cur = _f(r["current_price"])
        d = dist.get(s, {})
        out[s] = {
            "rec": r["recommendation_key"],
            "n": r["number_of_analyst_opinions"],
            "target_mean": mean,
            "target_median": _f(r["target_median_price"]),
            "target_high": _f(r["target_high_price"]),
            "target_low": _f(r["target_low_price"]),
            "current": cur,
            "upside": (round((mean - cur) / cur * 100, 1) if (mean and cur) else None),
            "as_of": str(r["snapshot_date"]) if r["snapshot_date"] else None,
            "dist": {k: d.get(k) for k in ("strong_buy", "buy", "hold", "sell", "strong_sell") if d.get(k) is not None},
            "dist_period": d.get("recommendation_period"),
            "dist_source": d.get("provider"),
        }
    if want_map or not sym:
        return {"ok": True, "advisory_only": True, "count": len(out), "map": out}
    return {"ok": True, "advisory_only": True, "symbol": sym, "detail": out.get(sym)}


def _pro_analyst_pills(query=None):
    """GET /api/v2/pro-analyst/pills [?symbol=AAPL] — advisory professional-analyst layer: per-symbol Yahoo
    consensus + targets + upgrade/downgrade events + internal-vs-Street divergence + coverage by tier.
    Read-only; never affects GO/WAIT or scoring."""
    import json as _jp

    # ── Data Broker Wave B: wire through analyst_rollup instead of direct file I/O ──
    from lib.data_broker.analyst_rollup import get_analyst_rollup

    _broker_rollup = get_analyst_rollup()  # validates broker path; used for per-symbol consensus below
    try:
        d = _jp.loads((PROJECT_ROOT / "data" / "runtime" / "pro_analyst_pills_latest.json").read_text())
    except Exception:
        return {"note": "run scripts/build_pro_analyst_read_model.py", "pills": []}
    # Enrich pills with broker-normalized consensus data where available
    for _p in d.get("pills", []):
        _b = _broker_rollup.get(str(_p.get("symbol") or "").upper())
        if _b:
            _p.setdefault("_broker_consensus", _b.get("consensus"))
            _p.setdefault("_broker_mean_target", _b.get("mean_target"))
            _p.setdefault("_broker_analyst_count", _b.get("analyst_count"))
            _p.setdefault("_broker_rec_key", _b.get("rec_key"))
    q = query or {}
    if q.get("map"):
        # compact symbol→pill map for per-page pills (one fetch covers all rows, incl. no-coverage)
        m = {
            p["symbol"]: {
                "rec": p.get("recommendation_key"),
                "n": p.get("number_of_analyst_opinions"),
                "target": p.get("target_mean_price"),
                "upside": p.get("upside_to_mean_target_pct"),
                "street": p.get("street_direction"),
                "internal": p.get("internal_direction"),
                "divergence": p.get("divergence"),
                "stale": p.get("stale"),
                "src": p.get("analyst_rating_source"),
                "has": p.get("has_professional_coverage"),
                "event": p.get("latest_event_type"),
            }
            for p in d.get("pills", [])
        }
        return {"updated_at": d.get("updated_at"), "count": len(m), "map": m}
    sym = q.get("symbol")
    if isinstance(sym, list):
        sym = sym[0] if sym else None
    if sym:
        p = next((x for x in d.get("pills", []) if x["symbol"] == sym.upper()), None)
        return {
            "updated_at": d.get("updated_at"),
            "symbol": sym.upper(),
            "pill": p,
            "found": p is not None,
            "note": d.get("note"),
        }
    coverage_health = {}
    try:
        h = _jp.loads((PROJECT_ROOT / "data" / "runtime" / "pro_analyst_coverage_history.json").read_text()).get(
            "snapshots", []
        )
        if h:
            latest = h[-1]
            coverage_health = {
                "status": latest.get("status"),
                "coverage_pct": latest.get("coverage_pct"),
                "with_consensus": latest.get("with_consensus"),
                "stale": latest.get("stale"),
                "notes": latest.get("notes", []),
                "divergence_counts": latest.get("divergence_counts"),
                "comparable": latest.get("comparable"),
                "divergent_symbols": latest.get("divergent_symbols"),
                "newly_divergent": latest.get("newly_divergent"),
                "trend": [
                    {
                        "date": s["date"],
                        "coverage_pct": s["coverage_pct"],
                        "with_consensus": s["with_consensus"],
                        "divergent": s.get("divergent"),
                        "comparable": s.get("comparable"),
                    }
                    for s in h[-14:]
                ],
            }
    except Exception:
        pass
    return {
        "updated_at": d.get("updated_at"),
        "symbol_count": d.get("symbol_count"),
        "coverage_by_tier": d.get("coverage_by_tier"),
        "note": d.get("note"),
        "with_consensus": sum(1 for p in d.get("pills", []) if p.get("has_professional_coverage")),
        "coverage_health": coverage_health,
        "divergent": [p["symbol"] for p in d.get("pills", []) if p.get("divergence") == "divergent"],
        "pills": [p for p in d.get("pills", []) if p.get("has_professional_coverage")][:50],
    }


