def _watch_alerts_post(body=None):
    """POST /api/v2/watch/alerts {action: arm|disarm, ...} — deterministic
    conditions only; evaluation rides the 20-min RTH cron (notifications, not
    content production)."""
    b = body or {}
    action = (b.get("action") or "arm").lower()
    if action == "disarm":
        try:
            aid = int(b.get("id") or 0)
        except (TypeError, ValueError):
            return {"ok": False, "error": "id required"}
        _db_query("UPDATE watch_alerts SET active=false WHERE id=%s", (aid,), fetch=None)
        return {"ok": True, "id": aid, "disarmed": True}
    ct = (b.get("condition_type") or "").lower()
    allowed = ("price_cross_above", "price_cross_below", "rsi_above", "rsi_below", "directive_hit")
    if ct not in allowed:
        return {"ok": False, "error": f"condition_type must be one of {allowed}"}
    sym = (b.get("symbol") or "").upper().strip() or None
    did = b.get("directive_id")
    if ct == "directive_hit" and not did:
        return {"ok": False, "error": "directive_id required for directive_hit"}
    if ct != "directive_hit" and not sym:
        return {"ok": False, "error": "symbol required"}
    row = _db_query(
        """INSERT INTO watch_alerts (symbol, directive_id, condition_type, threshold,
                                                 recurring, note)
                       VALUES (%s,%s,%s,%s,%s,%s) RETURNING id""",
        (sym, did, ct, b.get("threshold"), bool(b.get("recurring")), (b.get("note") or "")[:200]),
        fetch="one",
    )
    return {
        "ok": True,
        "id": (row or {}).get("id"),
        "armed": True,
        "note": "evaluated every 20 min during RTH; one batched Telegram per pass, daily cap applies",
    }


def _ui_prefs_get(query=None):
    """GET /api/v2/ui/prefs?key=K — Watch Desk v4 (B1): tiny server-side prefs store
    (ui_prefs key/value jsonb). Server-side because the operator works desktop+phone
    over Tailscale; localStorage doesn't travel. Read-only GET."""
    q = query or {}
    key = str((q.get("key") or [""])[0] if isinstance(q.get("key"), list) else q.get("key") or "").strip()
    if not key:
        return {"ok": False, "error": "key required"}
    r = _db_query("SELECT value, updated_at FROM ui_prefs WHERE key=%s", (key,), fetch="one")
    return {
        "ok": True,
        "key": key,
        "value": _json_clean(r["value"]) if r else None,
        "updated_at": _json_clean(r["updated_at"]) if r else None,
    }


def _ui_prefs_set(body=None):
    """POST /api/v2/ui/prefs {key, value} — upsert one operator pref blob."""
    b = body or {}
    key = str(b.get("key") or "").strip()
    if not key or len(key) > 128:
        return {"ok": False, "error": "key required (≤128 chars)"}
    import json as _j

    try:
        blob = _j.dumps(b.get("value"))
    except (TypeError, ValueError):
        return {"ok": False, "error": "value must be JSON-serializable"}
    max_bytes = 262144
    if len(blob.encode("utf-8")) > max_bytes:
        return {"ok": False, "error": f"value too large ({max_bytes // 1024}KB cap)"}
    _db_query(
        """INSERT INTO ui_prefs (key, value, updated_at) VALUES (%s, %s::jsonb, now())
                 ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, updated_at=now()""",
        (key, blob),
        fetch=None,
    )
    return {"ok": True, "key": key}


def _watch_directive_detail(query=None):
    """GET /api/v2/watch/directives/detail?id=N — Watch Desk v4 (C1): the directive
    drawer. Full thesis/spec + aliases, 90d hit timeline, α outcome events
    (watch_candidate_events, source_id = directive id), staged children in the
    watchpool, and TTL expiry. Read-only."""
    q = query or {}
    try:
        did = int((q.get("id") or [0])[0] if isinstance(q.get("id"), list) else q.get("id") or 0)
    except (TypeError, ValueError):
        did = 0
    if not did:
        return {"ok": False, "error": "id required"}
    d = _db_query("SELECT * FROM watch_directives WHERE id=%s", (did,), fetch="one")
    if not d:
        return {"ok": False, "error": f"directive {did} not found"}
    spec = d.get("spec") if isinstance(d.get("spec"), dict) else {}
    try:
        import json as _j

        if isinstance(d.get("spec"), str):
            spec = _j.loads(d["spec"])
    except Exception:
        spec = {}
    timeline = (
        _db_query(
            """SELECT surfaced_at::date AS day, count(*) AS hits
                            FROM watch_directive_hits
                            WHERE directive_id=%s AND surfaced_at > now() - interval '90 days'
                            GROUP BY 1 ORDER BY 1""",
            (did,),
        )
        or []
    )
    alpha_events = (
        _db_query(
            """SELECT symbol, emitted_on, alpha_21d, alpha_63d, verdict, staged, proposed
                                FROM watch_candidate_events
                                WHERE source_type='directive_hit' AND source_id=%s
                                ORDER BY emitted_on DESC LIMIT 60""",
            (str(did),),
        )
        or []
    )
    children = (
        _db_query(
            """SELECT symbol, strategy_id, bucket, current_status, origin_system
                            FROM strategy_watchpool WHERE directive_id=%s
                            ORDER BY symbol LIMIT 60""",
            (did,),
        )
        or []
    )
    expires_in = None
    if d.get("ttl_days") is not None and d.get("created_at") is not None:
        try:
            import datetime as _dt

            age = (_dt.datetime.now(_dt.timezone.utc) - d["created_at"]).days
            expires_in = int(d["ttl_days"]) - age
        except Exception:
            pass
    alpha_scored = [e for e in alpha_events if e.get("alpha_21d") is not None]
    return {
        "ok": True,
        "directive": {k: _json_clean(v) for k, v in d.items() if k != "spec"},
        "spec": _json_clean(spec),
        "aliases": _json_clean(spec.get("aliases") or []),
        "hit_timeline_90d": [{k: _json_clean(v) for k, v in r.items()} for r in timeline],
        "alpha_events": [{k: _json_clean(v) for k, v in r.items()} for r in alpha_events],
        "alpha_n": len(alpha_scored),
        "children": [{k: _json_clean(v) for k, v in r.items()} for r in children],
        "expires_in_days": expires_in,
    }


_MERGE_PLAN_CACHE = {"ts": 0.0, "plan": None}


def _watch_directive_merge_plan(query=None):
    """GET /api/v2/watch/directives/merge-plan — Watch Desk v4 (C3): the Sunday tier-3
    family-merge plan rendered as an in-UI approvals fold. Read-only plan; each approval
    goes through the SAME governed merge_into action as the Telegram/CLI path. Cached 6h."""
    import time as _t

    if (
        _MERGE_PLAN_CACHE["plan"] is not None
        and _t.time() - _MERGE_PLAN_CACHE["ts"] < 21600
        and not (query or {}).get("refresh")
    ):
        return _MERGE_PLAN_CACHE["plan"]
    try:
        import sys as _s

        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import importlib

        wdd = importlib.import_module("watch_directive_dedup")
        actions = wdd.plan([3])
        merges = [
            {
                "family": m["family"],
                "survivor": {
                    "id": m["survivor"]["id"],
                    "label": m["survivor"]["label"],
                    "hits": _json_clean(m["survivor"].get("hits")),
                },
                "dups": [{"id": x["id"], "label": x["label"], "hits": _json_clean(x.get("hits"))} for x in m["dups"]],
            }
            for m in actions.get("merges", [])
        ]
        out = {
            "ok": True,
            "merges": merges,
            "count": len(merges),
            "note": "approve = governed merge_into per pair (alias + hits reassigned + dup archived); never deleted",
        }
    except Exception as e:
        out = {"ok": False, "error": str(e)[:200]}
    _MERGE_PLAN_CACHE.update({"ts": _t.time(), "plan": out})
    return out


def _watch_directive_update(body=None):
    """POST /api/v2/watch/directives/update {id, action, target_id?} — Watch Desk
    v2 (B3) row actions. Governed transitions only, never delete:
      pause: active→paused · resume: paused/proposed→active · archive: →archived
      merge_into: alias this directive onto target survivor, then archive it."""
    b = body or {}
    try:
        did = int(b.get("id") or 0)
    except (TypeError, ValueError):
        return {"ok": False, "error": "id required"}
    action = (b.get("action") or "").lower()
    row = _db_query("SELECT id, kind, label, status FROM watch_directives WHERE id=%s", (did,), fetch="one")
    if not row:
        return {"ok": False, "error": f"directive {did} not found"}
    if action == "pause" and row["status"] == "active":
        _db_query("UPDATE watch_directives SET status='paused', updated_at=NOW() WHERE id=%s", (did,), fetch=None)
    elif action == "resume" and row["status"] in ("paused", "proposed", "expired"):
        _db_query("UPDATE watch_directives SET status='active', updated_at=NOW() WHERE id=%s", (did,), fetch=None)
    elif action == "archive" and row["status"] != "archived":
        _db_query("UPDATE watch_directives SET status='archived', updated_at=NOW() WHERE id=%s", (did,), fetch=None)
    elif action == "merge_into":
        try:
            tid = int(b.get("target_id") or 0)
        except (TypeError, ValueError):
            return {"ok": False, "error": "target_id required for merge_into"}
        tgt = _db_query("SELECT id, status FROM watch_directives WHERE id=%s AND kind='trend'", (tid,), fetch="one")
        if not tgt or tgt["status"] != "active":
            return {"ok": False, "error": "merge target must be an active trend directive"}
        import sys as _s

        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from lib.watch_directive_gate import attach_alias

        attach_alias(tid, row["label"], rationale=f"operator merge of #{did}", created_by="operator_merge")
        _db_query("""UPDATE watch_directive_hits SET directive_id=%s WHERE directive_id=%s""", (tid, did), fetch=None)
        _db_query("UPDATE watch_directives SET status='archived', updated_at=NOW() WHERE id=%s", (did,), fetch=None)
        return {"ok": True, "id": did, "merged_into": tid, "hits_reassigned": True}
    else:
        return {"ok": False, "error": f"invalid transition {row['status']} → {action}"}
    return {"ok": True, "id": did, "action": action}


