def _two_way_curation_health(query=None):
    """GET /api/v2/watch/two-way-curation — loop health KPIs (read-only advisory).

    Forward: staging undrained / desk directives / desk hits / audit.
    Reverse: realized_outcome / hermes_research / options_edge coverage.
    """

    def q1(sql):
        rows = _db_query(sql) or []
        if not rows:
            return 0
        r = rows[0]
        return list(r.values())[0] if isinstance(r, dict) else r[0]

    def qkv(sql):
        rows = _db_query(sql) or []
        out = {}
        for r in rows:
            if isinstance(r, dict):
                out[str(r.get("k"))] = r.get("n")
            else:
                out[str(r[0])] = r[1]
        return out

    try:
        body = {
            "ok": True,
            "authority": "READ_ONLY_ADVISORY",
            "forward": {
                "staging_undrained": {
                    "cio": q1("SELECT count(*) AS n FROM cio_directive_hits_staging WHERE NOT drained"),
                    "advisory": q1("SELECT count(*) AS n FROM advisory_directive_hits_staging WHERE NOT drained"),
                    "defense": q1("SELECT count(*) AS n FROM defense_directive_hits_staging WHERE NOT drained"),
                    "rotation": q1("SELECT count(*) AS n FROM rotation_directive_hits_staging WHERE NOT drained"),
                    "reentry": q1("SELECT count(*) AS n FROM reentry_directive_hits_staging WHERE NOT drained"),
                    "hermes": q1("SELECT count(*) AS n FROM hermes_directive_hits_staging WHERE NOT drained"),
                },
                "desk_directives_active": q1(
                    "SELECT count(*) AS n FROM watch_directives WHERE status='active' "
                    "AND created_by IN ('cio','advisory','defense','rotation','reentry')"
                ),
                "desk_hits_24h": qkv(
                    "SELECT surfaced_by AS k, count(*) AS n FROM watch_directive_hits "
                    "WHERE surfaced_at > now() - interval '24 hours' "
                    "AND surfaced_by IN ('cio','advisory','defense','rotation','reentry') GROUP BY 1"
                ),
                "audit_events_24h": q1(
                    "SELECT count(*) AS n FROM curation_loop_audit WHERE created_at > now() - interval '24 hours'"
                ),
                "audit_by_source_24h": qkv(
                    "SELECT source AS k, count(*) AS n FROM curation_loop_audit "
                    "WHERE created_at > now() - interval '24 hours' GROUP BY 1"
                ),
            },
            "reverse": {
                "with_realized_outcome": q1(
                    "SELECT count(*) AS n FROM watchlist_items "
                    "WHERE status IN ('active','researched') AND realized_outcome IS NOT NULL"
                ),
                "with_hermes_research": q1(
                    "SELECT count(*) AS n FROM watchlist_items "
                    "WHERE status IN ('active','researched') AND hermes_research_score IS NOT NULL"
                ),
                "with_options_edge": q1(
                    "SELECT count(*) AS n FROM watchlist_items "
                    "WHERE status IN ('active','researched') AND options_edge_score IS NOT NULL"
                ),
                "active_researched": q1(
                    "SELECT count(*) AS n FROM watchlist_items WHERE status IN ('active','researched')"
                ),
            },
            "recent_audit": _db_query(
                "SELECT id, source, event, payload, created_at FROM curation_loop_audit "
                "ORDER BY created_at DESC LIMIT 15"
            )
            or [],
            # Alex-consumable opportunity queue: one deterministic digest fed by
            # staged/undrained desk suggestions (cio/advisory/defense/rotation/reentry).
            "opportunity_queue": _opportunity_queue_summary(),
            # Alex's sector-opportunity synthesis (Sector X is improving…).
            "sector_opportunities": _sector_opportunities_compact(),
            # Alex's capital plan (sources/uses, net deploy/raise, position decisions).
            "capital_plan": _capital_plan_compact(),
            # Institutional Report v2 (Part A + Part B + coverage matrix + manifest).
            "report_v2": _report_v2_compact(),
            # Operator interactive inbox: desk staged suggestions ready for one-tap promote
            "suggestions": _db_query(
                """SELECT h.id AS hit_id, h.directive_id, d.label AS directive_label,
                          d.created_by AS directive_created_by, h.symbol, h.surfaced_by,
                          h.divergence, h.promotion_status, h.hit_reason, h.surfaced_at
                   FROM watch_directive_hits h
                   JOIN watch_directives d ON d.id = h.directive_id
                   WHERE h.promotion_status = 'STAGED_FOR_REVIEW'
                     AND h.surfaced_by IN ('cio','advisory','defense','rotation','reentry')
                     AND h.surfaced_at > now() - interval '7 days'
                   ORDER BY h.surfaced_at DESC
                   LIMIT 50"""
            )
            or [],
            "undrained_staging_rows": {
                "cio": _db_query(
                    """SELECT id, symbol, thesis, proposed_at FROM cio_directive_hits_staging
                       WHERE NOT drained ORDER BY proposed_at DESC LIMIT 10"""
                )
                or [],
                "advisory": _db_query(
                    """SELECT id, symbol, thesis, proposed_at FROM advisory_directive_hits_staging
                       WHERE NOT drained ORDER BY proposed_at DESC LIMIT 10"""
                )
                or [],
                "defense": _db_query(
                    """SELECT id, symbol, thesis, proposed_at FROM defense_directive_hits_staging
                       WHERE NOT drained ORDER BY proposed_at DESC LIMIT 10"""
                )
                or [],
                "rotation": _db_query(
                    """SELECT id, symbol, thesis, proposed_at FROM rotation_directive_hits_staging
                       WHERE NOT drained ORDER BY proposed_at DESC LIMIT 10"""
                )
                or [],
                "reentry": _db_query(
                    """SELECT id, symbol, thesis, proposed_at FROM reentry_directive_hits_staging
                       WHERE NOT drained ORDER BY proposed_at DESC LIMIT 10"""
                )
                or [],
            },
        }
        # Simple maturity hint for operator
        f, r = body["forward"], body["reverse"]
        desk_hits = sum((f.get("desk_hits_24h") or {}).values()) if isinstance(f.get("desk_hits_24h"), dict) else 0
        circulating = (
            (f.get("desk_directives_active") or 0) > 0
            or desk_hits > 0
            or (f.get("audit_events_24h") or 0) > 0
            or sum((f.get("staging_undrained") or {}).values()) > 0
        )
        reverse_ok = (r.get("with_hermes_research") or 0) > 0
        body["loop_status"] = (
            "CIRCULATING"
            if circulating and reverse_ok
            else "REVERSE_ONLY"
            if reverse_ok and not circulating
            else "FORWARD_ONLY"
            if circulating
            else "COLD"
        )
        body["suggestions_count"] = len(body.get("suggestions") or [])
        return body
    except Exception as exc:
        return {"ok": False, "error": str(exc)[:200], "authority": "READ_ONLY_ADVISORY"}


def _watch_directives(query=None):
    """GET /api/v2/watch-directives — operator watch directives + recent hits + Hermes staging (read-only)."""
    directives = (
        _db_query("""SELECT id, kind, label, status, priority, trade_ai_enabled, hermes_enabled,
                              last_serviced_at, created_at, spec, created_by, rationale, ttl_days,
                              CASE WHEN ttl_days IS NOT NULL
                                   THEN ttl_days - extract(days FROM now() - created_at)::int
                              END AS expires_in_days
                              FROM watch_directives ORDER BY created_at DESC""")
        or []
    )
    hits = (
        _db_query("""SELECT h.directive_id, d.label, h.symbol, h.surfaced_by, h.divergence, h.promotion_status,
                        h.surfaced_at FROM watch_directive_hits h JOIN watch_directives d ON d.id=h.directive_id
                        ORDER BY h.surfaced_at DESC LIMIT 40""")
        or []
    )
    # Dedicated desk-suggestions inbox (not drowned by Hermes volume in recent_hits)
    desk_suggestions = (
        _db_query("""
        SELECT h.id AS hit_id, h.directive_id, d.label, d.created_by, h.symbol, h.surfaced_by,
               h.divergence, h.promotion_status, h.hit_reason, h.surfaced_at
        FROM watch_directive_hits h
        JOIN watch_directives d ON d.id = h.directive_id
        WHERE h.promotion_status = 'STAGED_FOR_REVIEW'
          AND h.surfaced_by IN ('cio','advisory','defense','rotation','reentry')
          AND h.surfaced_at > now() - interval '7 days'
        ORDER BY h.surfaced_at DESC
        LIMIT 40
    """)
        or []
    )
    # Per-directive surfaced symbols (fix 2026-06-19): trend/sector directives link items via hits, NOT
    # by setting directive_id on the item — so the Watchlist directive filter must match on these symbols.
    _hs = (
        _db_query("""SELECT directive_id, array_agg(DISTINCT upper(symbol)) syms,
                              count(*) hit_count,
                              count(*) FILTER (WHERE promotion_status='STAGED_FOR_REVIEW') staged_count,
                              max(surfaced_at) AS last_hit_at,
                              count(*) FILTER (WHERE surfaced_at > now() - interval '7 days')  AS hits_7d,
                              count(*) FILTER (WHERE surfaced_at > now() - interval '30 days') AS hits_30d
                       FROM watch_directive_hits GROUP BY directive_id""")
        or []
    )
    # Watch Desk v2 (B3): 8-week hit sparkline per directive (one grouped query)
    _spark_rows = (
        _db_query("""SELECT directive_id, (extract(days from now() - surfaced_at)::int / 7) AS wk, count(*) AS n
                               FROM watch_directive_hits
                               WHERE surfaced_at > now() - interval '56 days'
                               GROUP BY 1, 2""")
        or []
    )
    _spark: dict = {}
    for r in _spark_rows:
        _spark.setdefault(r["directive_id"], [0] * 8)
        wk = int(r["wk"])
        if 0 <= wk < 8:
            _spark[r["directive_id"]][7 - wk] = r["n"]
    _hit_meta = {r["directive_id"]: r for r in _hs}
    # Watch Desk v3 (A3): per-directive outcome evidence from the source scoreboard —
    # the input the 150-cap and Sunday hygiene were missing (cull by evidence)
    _score_meta = {}
    try:
        for r in (
            _db_query("""SELECT source_id::bigint AS did,
                                      count(*) AS events,
                                      count(*) FILTER (WHERE alpha_21d IS NOT NULL) AS scored,
                                      round((percentile_cont(0.5) WITHIN GROUP (ORDER BY alpha_21d)
                                        FILTER (WHERE alpha_21d IS NOT NULL))::numeric, 2) AS alpha_21d_median,
                                      count(*) FILTER (WHERE proposed) AS proposed_n
                               FROM watch_candidate_events
                               WHERE source_type='directive_hit' AND source_id ~ '^[0-9]+$'
                               GROUP BY 1""")
            or []
        ):
            _score_meta[r["did"]] = r
    except Exception:
        _score_meta = {}
    _hit_sym_map = {r["directive_id"]: (r["syms"] or []) for r in _hs}
    # Per-directive TOTAL counts (fix 2026-06-19): the chip count must come from here, NOT from the global
    # recent_hits feed below — that feed is LIMIT 40 (most-recent activity), so older/ticker-tag hits fall
    # out of the window and the chip wrongly shows "0 hits" for a directive that did surface symbols.
    _hit_cnt = {r["directive_id"]: (r["hit_count"], r["staged_count"]) for r in _hs}
    staging = (
        _db_query(
            "SELECT count(*) c, count(*) FILTER (WHERE NOT drained) undrained FROM hermes_directive_hits_staging",
            fetch="one",
        )
        or {}
    )
    promoted = _db_query("SELECT count(*) c FROM watchlist_items WHERE source='operator_directive'", fetch="one") or {}
    health = {}
    try:
        import json as _jw

        _h = _jw.loads((PROJECT_ROOT / "data" / "runtime" / "watch_directives_history.json").read_text()).get(
            "snapshots", []
        )
        if _h:
            _l = _h[-1]
            health = {
                "status": _l.get("status"),
                "hits_24h": _l.get("hits_24h"),
                "by_status_24h": _l.get("by_status_24h"),
                "by_surfaced_24h": _l.get("by_surfaced_24h"),
                "promoted_total": _l.get("promoted_total"),
                "staging_undrained": _l.get("staging_undrained"),
                "stale_directives": _l.get("stale_directives"),
                "notes": _l.get("notes", []),
                "trend": [
                    {"date": s["date"], "hits_7d": s.get("hits_7d"), "promoted_total": s.get("promoted_total")}
                    for s in _h[-14:]
                ],
            }
    except Exception:
        pass
    critique_summary = {}
    critique_snapshot_at = None
    try:
        import sys as _sysc2

        _sysc2.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from research_critique_pipeline import load_critique_snapshot, extract_critique_fields

        _critique_snap = load_critique_snapshot()
        critique_summary = _critique_snap.get("summary") or {}
        critique_snapshot_at = _critique_snap.get("updated_at")
        _extract = extract_critique_fields
    except Exception:
        _extract = lambda _s: {}

    return {
        "note": "Operator-owned watch directives honored by Trade AI + Hermes (firewall: Hermes proposes via "
        "staging only). Advisory; no GO/WAIT or scoring change.",
        "critique_summary": {k: _json_clean(v) for k, v in critique_summary.items()},
        "critique_snapshot_at": critique_snapshot_at,
        "directive_count": len(directives),
        # surface the spec context (gap_type/sleeve/symbol) + created_by so the Watchpool can label
        # rotate-gap directives instead of showing them as generic ticker directives (operator 2026-06-19)
        # Watch Desk v2 (B3+E): reviewable rows — age/last-hit/7d/30d/sparkline —
        # with the LIST payload slimmed (full spec/rationale only behind ?full=1;
        # the list was 793 KB of specs nobody reads in a table)
        "directives": [
            {
                **{
                    k: _json_clean(v)
                    for k, v in r.items()
                    if (query or {}).get("full") or k not in ("spec", "rationale")
                },
                "symbol": (r.get("spec") or {}).get("symbol"),
                "gap_type": (r.get("spec") or {}).get("gap_type"),
                "sleeve": (r.get("spec") or {}).get("sleeve"),
                "aliases_n": len((r.get("spec") or {}).get("aliases") or []),
                "rationale_short": (str(r.get("rationale") or "")[:160] or None),
                "critique": {k: _json_clean(v) for k, v in _extract(r.get("spec") or {}).items()},
                "hit_symbols": _hit_sym_map.get(r["id"], [])[:20],
                "hit_count": _hit_cnt.get(r["id"], (0, 0))[0],
                "staged_count": _hit_cnt.get(r["id"], (0, 0))[1],
                "last_hit_at": _json_clean((_hit_meta.get(r["id"]) or {}).get("last_hit_at")),
                "hits_7d": (_hit_meta.get(r["id"]) or {}).get("hits_7d") or 0,
                "hits_30d": (_hit_meta.get(r["id"]) or {}).get("hits_30d") or 0,
                "spark_8w": _spark.get(r["id"], [0] * 8),
                "alpha_21d_median": _json_clean((_score_meta.get(r["id"]) or {}).get("alpha_21d_median")),
                "alpha_n": (_score_meta.get(r["id"]) or {}).get("scored") or 0,
                "conv_pct": _json_clean(
                    round(
                        100.0
                        * (_score_meta.get(r["id"]) or {}).get("proposed_n", 0)
                        / max(1, (_score_meta.get(r["id"]) or {}).get("events") or 1),
                        1,
                    )
                    if _score_meta.get(r["id"])
                    else None
                ),
                "age_days": _json_clean(
                    (datetime.now(timezone.utc) - r["created_at"]).days
                    if r.get("created_at") is not None and hasattr(r.get("created_at"), "year")
                    else None
                ),
            }
            for r in directives
        ],
        "proposed_count": sum(1 for r in directives if r.get("status") == "proposed"),
        "recent_hits": [{k: _json_clean(v) for k, v in r.items()} for r in hits],
        "desk_suggestions": [{k: _json_clean(v) for k, v in r.items()} for r in desk_suggestions],
        "desk_suggestions_count": len(desk_suggestions),
        "hermes_staging": {"total": staging.get("c"), "undrained": staging.get("undrained")},
        "promoted_to_watchlist": promoted.get("c"),
        "health": health,
    }


def _retirement_planning_research(query=None):
    """GET /api/v2/retirement/planning-research — Hermes knowledge research on the operator's retirement /
    estate / tax / Medicare planning topics (research_type='topic_research'), grouped by theme. Read-only.
    Feeds the RetirementHub 'Planning Research' section. Advisory — consult professionals."""
    # Classify on the TOPIC NAME (concise + on-point) — NOT topic+summary, whose long
    # cross-references caused trading topics to leak in via bare "tax/income/dividend/nav".
    # Themes require retirement-SPECIFIC anchors; TRADING_EXCLUDE drops market/trading
    # research (sector rotation, options, swing/momentum, AI-datacenter, defense, etc.)
    # — those belong on Intelligence/Research, not the Retirement hub.
    THEMES = [
        ("Roth & conversions", r"\broth\b|conversion|golden window|\brmd\b|backdoor|qualified charitable"),
        ("Medicare & IRMAA", r"medicare|irmaa|medigap|part [bd]\b"),
        (
            "Medicaid & asset protection",
            r"medicaid|\bmapt\b|asset protection|spend.?down|look.?back|estate recovery|special needs|supplemental needs",
        ),
        ("Estate & trusts", r"estate|\btrust\b|probate|life estate|beneficiar|\bwill\b|inheritance"),
        (
            "SSDI & taxes",
            r"\bssdi\b|social security|disability|\bmagi\b|tax.?loss|tax-efficient|tax strateg|\bqcd\b|\bhsa\b|earnings test|substantial gainful",
        ),
        (
            "Income & dividends (retirement)",
            r"dividend income|covered call|bond ladder|tips|fixed.?income|annuit|drawdown|income sleeve|monthly income|dividend aristocrat|income strateg|bucket strateg|\bcef\b|\bpty\b|\bnav\b",
        ),
    ]
    TRADING_EXCLUDE = (
        r"swing|momentum|sector rotation|option|greeks|iron condor|earnings season|technical|breakout|scalp|"
        r"reddit|chart|implied vol|theta|premium sell|datacenter|data center|semiconductor|ai chip|ai hardware|"
        r"ai networking|ai datacenter|\bgpu\b|nvidia|defense|aerospace|materials sector|geopolitical|glp-1|"
        r"weight.?loss|hot topics|controvers|collar|sentiment-driven|emerging sector|infrastructure buildout|"
        r"hedging|catalyst|energy sector|utilities sector|consumer (defensive|staples)|healthcare rotation|trending|hype"
    )
    rows = (
        _db_query("""SELECT topic, summary, thesis, confidence_score, freshness_date, model_used,
                          research_type, created_at, status, evidence_json
                        FROM hermes_research_intelligence
                        WHERE research_type='topic_research'
                        ORDER BY created_at DESC LIMIT 400""")
        or []
    )
    groups = {n: [] for n, _ in THEMES}
    import re as _re, json as _json

    seen = set()
    excluded = 0
    for r in rows:
        topic_name = r.get("topic") or ""
        key = topic_name[:60]
        # drop market/trading research outright — it isn't retirement planning
        if _re.search(TRADING_EXCLUDE, topic_name, _re.I):
            excluded += 1
            continue
        # vetted sources this research grounded on (cataloged by the synthesizer; graded-good only)
        ev = r.get("evidence_json")
        ev = ev if isinstance(ev, dict) else (_json.loads(ev) if ev else {})
        srcs = [
            {"source": g.get("source"), "title": g.get("title"), "url": g.get("url")}
            for g in (ev.get("grounded_on") or [])
        ][:6]
        for name, rx in THEMES:
            if _re.search(rx, topic_name, _re.I):
                if (name, key) in seen:
                    break
                seen.add((name, key))
                groups[name].append(
                    {
                        "topic": r.get("topic"),
                        "summary": (r.get("summary") or "")[:400],
                        "thesis": (r.get("thesis") or "")[:300] or None,
                        "confidence": _json_clean(r.get("confidence_score")),
                        "status": r.get("status"),
                        "model": r.get("model_used"),
                        "sources": srcs,
                        "source_count": len(srcs),
                        "at": _json_clean(r.get("created_at")),
                    }
                )
                break
    out = [{"theme": n, "count": len(groups[n]), "items": groups[n][:8]} for n, _ in THEMES if groups[n]]
    return {
        "ok": True,
        "advisory_only": True,
        "as_of": datetime.now().astimezone().isoformat(),
        "themes": out,
        "total": sum(len(groups[n]) for n in groups),
        "excluded_non_retirement": excluded,
        "note": "Retirement/estate/tax/Medicare/SSDI planning research only (advisory; consult an "
        "elder-law attorney + tax advisor). Trading/market research is filtered out to the "
        "Intelligence/Research surfaces.",
    }


def _data_source_health(query=None):
    """GET /api/v2/data-source-health — per-source freshness/yield monitor for EVERY ingest feed
    (news APIs, RSS, Finviz, FRED, YouTube, web-search). Each source: last update, recent volume, and a
    status vs its expected cadence (live/slow/stale/dead). This is the gap that let DuckDuckGo fail
    silently — job-level monitors saw topic_ingestion 'succeed' while a sub-source produced 0 for weeks.
    Read-only."""
    # (label, category, SQL → (last_ts, recent_count), expected-fresh hours, notes)
    # Age by INGEST time (created_at = when the feed last delivered to us), NOT the article's publish
    # date — several sources (DuckDuckGo, etc.) don't populate published_at, which would falsely read
    # as dead even while producing fresh rows.
    NEWS = (
        "SELECT max(created_at), count(*) FILTER (WHERE created_at>now()-interval '{w}') "
        "FROM news_articles WHERE source {op} %s"
    )
    SPECS = [
        # news / RSS / API feeds (source LIKE/=)
        ("Yahoo RSS", "news", NEWS, "=", "yahoo_rss", 24),
        ("Google News RSS", "news", NEWS, "LIKE", "google_news%", 24),
        ("Google News (topic)", "news", NEWS, "=", "topic_google_news_rss", 48),
        ("Finnhub API", "news", NEWS, "=", "finnhub", 24),
        ("Finviz News", "news", NEWS, "=", "finviz_news", 24),
        ("Benzinga RSS", "news", NEWS, "=", "benzinga_rss", 48),
        ("Seeking Alpha", "news", NEWS, "=", "seeking_alpha", 72),
        ("YouTube (topic API)", "news", NEWS, "=", "topic_youtube_api", 72),
        ("DuckDuckGo (topic)", "websearch", NEWS, "=", "topic_duckduckgo", 168),
        ("Yahoo search (topic)", "websearch", NEWS, "=", "topic_yahoo_search", 168),
        # Brave (topic) retired 2026-07-07: account 402-paywalled (credits exhausted);
        # replaced by the free Yahoo Finance + DuckDuckGo topic lanes. Re-add a
        # ("Brave (topic)", ..., "topic_brave_news", 336) SPEC and set
        # TOPIC_BRAVE_ENABLED=1 in topic_ingestion once Brave billing is restored.
        ("Hermes research", "research", NEWS, "=", "hermes", 48),
    ]
    out, now_iso = [], datetime.now().astimezone()
    for label, cat, tmpl, op, val, thr in SPECS:
        try:
            w = f"{max(thr * 2, 48)} hours"
            row = _db_query(tmpl.format(w=w, op=op), (val,), fetch="one") or {}
            vals = list(row.values())
            last_ts = vals[0] if vals else None
            cnt = vals[1] if len(vals) > 1 else 0
            age_h = None
            if last_ts:
                try:
                    age_h = (now_iso - last_ts).total_seconds() / 3600.0
                except Exception:
                    age_h = None
            status = (
                "dead"
                if (age_h is None or age_h > thr * 4)
                else "stale"
                if age_h > thr * 2
                else "slow"
                if age_h > thr
                else "live"
            )
            out.append(
                {
                    "source": label,
                    "category": cat,
                    "last_update": _json_clean(last_ts),
                    "age_hours": round(age_h, 1) if age_h is not None else None,
                    "recent_count": cnt or 0,
                    "expected_fresh_h": thr,
                    "status": status,
                }
            )
        except Exception as e:
            out.append({"source": label, "category": cat, "status": "error", "error": str(e)[:80]})

    # non-news feeds (own queries)
    def _feed(label, cat, sql, thr):
        try:
            r = _db_query(sql, fetch="one") or {}
            v = list(r.values())
            last = v[0] if v else None
            cnt = v[1] if len(v) > 1 else None
            age_h = (now_iso - last).total_seconds() / 3600.0 if last else None
            status = (
                "dead"
                if (age_h is None or age_h > thr * 4)
                else "stale"
                if age_h > thr * 2
                else "slow"
                if age_h > thr
                else "live"
            )
            out.append(
                {
                    "source": label,
                    "category": cat,
                    "last_update": _json_clean(last),
                    "age_hours": round(age_h, 1) if age_h is not None else None,
                    "recent_count": cnt,
                    "expected_fresh_h": thr,
                    "status": status,
                }
            )
        except Exception as e:
            out.append({"source": label, "category": cat, "status": "error", "error": str(e)[:80]})

    _feed("FRED macro", "macro", "SELECT max(fetched_at), count(*) FROM fred_economic_series", 72)
    _feed(
        "Finviz screeners", "finviz", "SELECT max(last_run), count(*) FILTER (WHERE active) FROM finviz_screeners", 24
    )
    _feed(
        "Finviz enrichment",
        "finviz",
        "SELECT max(last_enriched_at), count(*) FROM watchlist_items WHERE last_enriched_at IS NOT NULL",
        48,
    )
    _feed(
        "Screener membership",
        "finviz",
        "SELECT max(last_seen_in_screener_at), count(*) FILTER (WHERE present_this_run) FROM screener_symbol_membership",
        48,
    )
    _feed(
        "YouTube transcripts",
        "news",
        "SELECT max(ingested_at), count(*) FROM youtube_transcripts WHERE ingested_at>now()-interval '7 days'",
        96,
    )
    _feed(
        "Catalyst events",
        "research",
        "SELECT max(created_at), count(*) FILTER (WHERE created_at>now()-interval '2 days') FROM catalyst_events",
        24,
    )
    _feed(
        "Finviz sector/industry",
        "finviz",
        "SELECT max(created_at), count(*) FROM finviz_group_performance WHERE snapshot_date=(SELECT max(snapshot_date) FROM finviz_group_performance)",
        30,
    )
    _feed(
        "SEC Form-4 insider",
        "research",
        "SELECT max(created_at), count(*) FILTER (WHERE filing_date>current_date-7) FROM sec_form4",
        48,
    )
    _feed(
        "Earnings dates (profile)",
        "research",
        "SELECT max(updated_at), count(*) FILTER (WHERE next_earnings_date IS NOT NULL AND next_earnings_date >= current_date) FROM symbol_profiles WHERE next_earnings_date IS NOT NULL",
        30,
    )
    _feed(
        "Symbol profiles",
        "research",
        "SELECT max(updated_at), count(*) FROM symbol_profiles WHERE updated_at > now() - interval '48 hours'",
        48,
    )
    order = {"dead": 0, "error": 1, "stale": 2, "slow": 3, "live": 4}
    out.sort(key=lambda x: order.get(x.get("status"), 9))
    counts = {}
    for o in out:
        counts[o["status"]] = counts.get(o["status"], 0) + 1
    return {
        "ok": True,
        "as_of": now_iso.isoformat(),
        "sources": out,
        "summary": counts,
        "total": len(out),
        "note": "Per-source freshness vs expected cadence. status: live=within cadence, slow=1-2x late, "
        "stale=2-4x late, dead=>4x late or no data. Catches silent sub-source failures.",
    }


_FINVIZ_ENRICH_CACHE = {"mtime": 0, "data": {}}


def _finviz_enrichment(query=None):
    """GET /api/v2/finviz-enrichment?symbol=X — the ~60 Finviz fields already collected daily
    (ticker_enrichment_cache.json), grouped for display: technicals / performance / valuation /
    fundamentals / ownership. Read-only. mtime-cached so we don't re-read the 5k-ticker file each call."""
    q = query or {}
    sym = q.get("symbol", [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol")
    if not sym:
        return {"ok": False, "error": "symbol required"}
    sym = sym.upper().strip()
    try:
        # The governed persistent state root is the same root used by the quote
        # cache and by the deployed portfolio reader.  The old path was a
        # checkout-relative legacy location; in an immutable release it did not
        # exist, so a healthy cache was misreported as service-unavailable.
        p = PROJECT_ROOT / "data" / "portfolios" / "state" / "ticker_enrichment_cache.json"
        mt = p.stat().st_mtime
        if mt != _FINVIZ_ENRICH_CACHE["mtime"]:
            loaded = json.loads(p.read_text())
            if not isinstance(loaded, dict):
                raise ValueError("cache root must be an object")
            _FINVIZ_ENRICH_CACHE["data"] = loaded
            _FINVIZ_ENRICH_CACHE["mtime"] = mt
    except Exception as e:
        return {"ok": False, "error": f"cache unavailable: {str(e)[:60]}"}
    d = _FINVIZ_ENRICH_CACHE["data"].get(sym) or {}
    if not d:
        return {
            "ok": True,
            "symbol": sym,
            "found": False,
            "cache_available": True,
            "groups": [],
            "note": "No Finviz enrichment cached.",
        }
    GROUPS = [
        (
            "Technicals",
            [
                ("RSI", "rsi"),
                ("RSI status", "rsi_status"),
                ("SMA20 %", "sma20_pct"),
                ("SMA50 %", "sma50_pct"),
                ("SMA200 %", "sma200_pct"),
                ("ATR", "atr"),
                ("Beta", "beta"),
                ("Volatility W %", "volatility_w_pct"),
                ("RVOL", "rvol"),
                ("52w high %", "week52_high_pct"),
                ("52w low %", "week52_low_pct"),
                ("Short float %", "short_float_pct"),
                ("Trend", "trend"),
            ],
        ),
        (
            "Performance",
            [
                ("Week %", "perf_week_pct"),
                ("Month %", "perf_month_pct"),
                ("Quarter %", "perf_quarter_pct"),
                ("Half-yr %", "perf_halfyr_pct"),
                ("YTD %", "perf_ytd_pct"),
                ("Year %", "perf_year_pct"),
            ],
        ),
        (
            "Valuation",
            [
                ("P/E", "pe"),
                ("Fwd P/E", "forward_pe"),
                ("PEG", "peg"),
                ("P/B", "pb"),
                ("P/S", "ps"),
                ("P/FCF", "pfcf"),
                ("Mkt cap $B", "market_cap_b"),
                ("Div yield %", "div_yield_pct"),
            ],
        ),
        (
            "Fundamentals",
            [
                ("Gross margin %", "gross_margin_pct"),
                ("Oper margin %", "oper_margin_pct"),
                ("Profit margin %", "profit_margin_pct"),
                ("ROE %", "roe_pct"),
                ("ROA %", "roa_pct"),
                ("ROIC %", "roic_pct"),
                ("EPS QoQ", "eps_qoq"),
                ("EPS next Y", "eps_next_y"),
                ("Debt/Eq", "total_debt_equity"),
            ],
        ),
        (
            "Ownership",
            [
                ("Insider own %", "insider_own_pct"),
                ("Insider trans %", "insider_trans_pct"),
                ("Inst own %", "inst_own_pct"),
                ("Inst trans %", "inst_trans_pct"),
                ("Float M", "float_m"),
                ("Short ratio", "short_ratio"),
            ],
        ),
    ]
    groups = []
    for gname, fields in GROUPS:
        items = [{"label": lbl, "value": _json_clean(d.get(key))} for lbl, key in fields if d.get(key) is not None]
        if items:
            groups.append({"group": gname, "items": items})
    return {
        "ok": True,
        "symbol": sym,
        "found": True,
        "cache_available": True,
        "company": d.get("company"),
        "sector": d.get("sector"),
        "industry": d.get("industry"),
        "cached_at": d.get("cached_at"),
        "groups": groups,
        "note": "Finviz enrichment (daily). Advisory.",
    }


_FINVIZ_STRIP_CACHE_PATH = PROJECT_ROOT / "data" / "runtime" / "finviz_strip_map_cache.json"
_FINVIZ_STRIP_TTL_SEC = int(os.getenv("FINVIZ_STRIP_TTL_SEC", "600"))  # 10 min


def _finviz_strip_map(query=None):
    """GET /api/v2/finviz-strip-map — compact Finviz metrics for the whole watch universe in ONE call.

    Served from a pre-warmed disk TTL cache so the per-call universe queries (watchlist + proposals +
    symbol_profiles ANY(...)) never block the single-threaded server. `?fresh=1` forces recompute.
    """
    import time as _time

    _q = query or {}
    _fresh = str((_q.get("fresh", [""])[0] if isinstance(_q.get("fresh"), list) else _q.get("fresh")) or "").lower()
    if _fresh not in ("1", "true", "yes") and _FINVIZ_STRIP_CACHE_PATH.exists():
        try:
            _cached = json.loads(_FINVIZ_STRIP_CACHE_PATH.read_text())
            if _time.time() - float(_cached.get("_cached_at") or 0) < _FINVIZ_STRIP_TTL_SEC:
                _cached["cached"] = True
                return _cached
        except Exception:
            pass
    _out = _finviz_strip_map_compute()
    try:
        _out["_cached_at"] = _time.time()
        _FINVIZ_STRIP_CACHE_PATH.parent.mkdir(parents=True, exist_ok=True)
        _FINVIZ_STRIP_CACHE_PATH.write_text(json.dumps(_out, default=str))
    except Exception:
        pass
    return _out


def _finviz_strip_map_compute(query=None):
    """Heavy computation for the Finviz strip map (cached by _finviz_strip_map). Read-only."""
    try:
        p = PROJECT_ROOT / "data" / "state" / "ticker_enrichment_cache.json"
        mt = p.stat().st_mtime
        if mt != _FINVIZ_ENRICH_CACHE["mtime"]:
            _FINVIZ_ENRICH_CACHE["data"] = json.loads(p.read_text())
            _FINVIZ_ENRICH_CACHE["mtime"] = mt
    except Exception as e:
        return {"ok": False, "error": f"cache unavailable: {str(e)[:60]}", "map": {}}
    cache = _FINVIZ_ENRICH_CACHE["data"]
    # union of the surfaces that render Finviz strips: watchlist + open broker proposals + held positions
    syms = {
        r["symbol"]
        for r in (
            _db_query("SELECT DISTINCT symbol FROM watchlist_items WHERE status<>'removed' AND symbol ~ '^[A-Z]{1,5}$'")
            or []
        )
    }
    syms |= {
        r["symbol"]
        for r in (
            _db_query(
                "SELECT DISTINCT symbol FROM paper_trade_proposals WHERE status IN ('PENDING','APPROVED') AND symbol ~ '^[A-Z]{1,5}$'"
            )
            or []
        )
    }
    try:
        hj = _load_json(STATE_DIR / "holdings.json") or {}
        for h in hj.get("holdings", []):
            s = str(h.get("symbol", "")).upper()
            if s and not h.get("is_cash") and re.fullmatch(r"[A-Z]{1,5}", s):
                syms.add(s)
    except Exception:
        pass
    # Mutual funds aren't covered by Finviz (null strip) → fall back to symbol_profiles technicals computed
    # from yfinance NAV history (fund_technicals_enrich). Per-field fallback so a partial Finviz row still wins
    # where it has data. (operator 2026-06-21)
    _prof = {}
    try:
        for r in (
            _db_query(
                """SELECT upper(symbol) s, rsi14, perf_week_pct, perf_month_pct,
                                      ytd_return_pct, sma50_pct FROM symbol_profiles
                               WHERE upper(symbol) = ANY(%s)""",
                (sorted(syms),),
            )
            or []
        ):
            _prof[r["s"]] = r
    except Exception:
        _prof = {}
    # Supplemental valuation for names Finviz's screeners never enriched (watchlist
    # favorites in no screener — CARR, LII, LI, …). Sourced from yfinance by
    # scripts/watch_valuation_backfill.py into a runtime cache and merged per-field below,
    # so a Finviz row still wins wherever it has data. Non-equities are negative-cached
    # (no_valuation) so they stay N/A, never fabricated.
    _val_supp = {}
    try:
        _vp = PROJECT_ROOT / "data" / "state" / "valuation_supplement_cache.json"
        if _vp.exists():
            _val_supp = json.loads(_vp.read_text())
    except Exception:
        _val_supp = {}

    def _rsi_status(v):
        if v is None:
            return "unknown"
        return "oversold" if v <= 30 else "overbought" if v >= 70 else "neutral"

    out = {}
    for s in syms:
        d = cache.get(s) or {}
        pf = _prof.get(s) or {}
        rsi = d.get("rsi")
        rsi = rsi if rsi is not None else _json_clean(pf.get("rsi14"))
        pw = d.get("perf_week_pct")
        pw = pw if pw is not None else _json_clean(pf.get("perf_week_pct"))
        pm = d.get("perf_month_pct")
        pm = pm if pm is not None else _json_clean(pf.get("perf_month_pct"))
        pytd = d.get("perf_ytd_pct")
        pytd = pytd if pytd is not None else _json_clean(pf.get("ytd_return_pct"))
        sma = d.get("sma50_pct")
        sma = sma if sma is not None else _json_clean(pf.get("sma50_pct"))
        atr = d.get("atr")
        # Valuation is already in the enrichment cache (pe/forward_pe/peg/pb/ps) but was
        # never passed through, so the whole Watch queue rendered "valuation unavailable"
        # for every symbol — even mega-caps. The Watch valuation panel reads fv.pe /
        # fv.forward_pe / fv.peg / fv.pb / fv.ps off this strip row, so surface them here.
        # yfinance-NAV fallback rows (mutual funds) legitimately have none; those stay null
        # and the UI marks the instrument N/A rather than missing.
        sd = _val_supp.get(s) or {}
        supp_ok = not sd.get("no_valuation")  # non-equities are negative-cached
        pe = _json_clean(d.get("pe"))
        pe = pe if pe is not None else (_json_clean(sd.get("pe")) if supp_ok else None)
        forward_pe = _json_clean(d.get("forward_pe"))
        forward_pe = forward_pe if forward_pe is not None else (_json_clean(sd.get("forward_pe")) if supp_ok else None)
        peg = _json_clean(d.get("peg"))
        peg = peg if peg is not None else (_json_clean(sd.get("peg")) if supp_ok else None)
        pb = _json_clean(d.get("pb"))
        pb = pb if pb is not None else (_json_clean(sd.get("pb")) if supp_ok else None)
        ps = _json_clean(d.get("ps"))
        ps = ps if ps is not None else (_json_clean(sd.get("ps")) if supp_ok else None)
        has_val = any(v is not None for v in (pe, forward_pe, peg, pb, ps))
        # Provenance: the supplement is the source only when the Finviz row contributed no
        # valuation field at all (it carries pb/ps for some names that lack pe, so checking
        # pe/forward_pe alone would mislabel those as yfinance).
        finviz_has_val = any(_json_clean(d.get(k)) is not None for k in ("pe", "forward_pe", "peg", "pb", "ps"))
        val_from_supp = supp_ok and not finviz_has_val and has_val
        val_as_of = sd.get("cached_at") if val_from_supp else d.get("cached_at")
        if rsi is None and pw is None and pm is None and pytd is None and sma is None and atr is None and not has_val:
            continue  # nothing for this symbol from either source
        row = {
            "rsi": _json_clean(rsi),
            "rsi_status": d.get("rsi_status") if d.get("rsi") is not None else _rsi_status(rsi),
            "perf_week": _json_clean(pw),
            "perf_month": _json_clean(pm),
            "perf_ytd": _json_clean(pytd),
            "sma50": _json_clean(sma),
            "atr": _json_clean(atr),
            "pe": pe,
            "forward_pe": forward_pe,
            "peg": peg,
            "pb": pb,
            "ps": ps,
            "fundamentals_as_of": val_as_of,
            "valuation_source": ("yfinance" if val_from_supp else "finviz" if has_val else None),
            "source": ("finviz" if d.get("rsi") is not None else "yfinance_nav"),
        }
        out[s] = row
    return {
        "ok": True,
        "count": len(out),
        "map": out,
        "note": "Finviz inline-strip metrics (daily); mutual funds fall back to yfinance-NAV technicals.",
    }


def _sector_performance(query=None):
    """GET /api/v2/sector-performance — latest Finviz sector + industry performance snapshot
    (leaders/laggards) for macro/rotation research. Read-only."""
    q = query or {}
    gtype = (q.get("type", ["sector"])[0] if isinstance(q.get("type"), list) else q.get("type")) or "sector"
    rows = (
        _db_query(
            """SELECT name, change_pct, pe, dividend_yield, market_cap, stocks, snapshot_date
                        FROM finviz_group_performance
                        WHERE group_type=%s AND snapshot_date=(SELECT max(snapshot_date)
                              FROM finviz_group_performance WHERE group_type=%s)
                        ORDER BY change_pct DESC NULLS LAST""",
            (gtype, gtype),
        )
        or []
    )
    items = [
        {
            "name": r.get("name"),
            "change_pct": _json_clean(r.get("change_pct")),
            "pe": _json_clean(r.get("pe")),
            "dividend_yield": _json_clean(r.get("dividend_yield")),
            "market_cap": _json_clean(r.get("market_cap")),
            "stocks": r.get("stocks"),
            "as_of": _json_clean(r.get("snapshot_date")),
        }
        for r in rows
    ]
    return {
        "ok": True,
        "group_type": gtype,
        "count": len(items),
        "leaders": items[:5],
        "laggards": items[-5:][::-1],
        "items": items,
        "as_of": items[0]["as_of"] if items else None,
        "note": "Finviz group performance (advisory · macro/rotation lens).",
    }


def _insider_activity(query=None):
    """GET /api/v2/insider-activity[?symbol=X] — recent SEC Form-4 insider filings (authoritative) for a
    symbol, else across the held + active-watchlist universe. Read-only/advisory."""
    q = query or {}
    sym = q.get("symbol", [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol")
    if sym:
        rows = (
            _db_query(
                """SELECT symbol, filer_name, filer_relation, transaction_type, shares, price,
                              total_value, ownership_after, filing_date, transaction_date, sec_url
                            FROM sec_form4 WHERE symbol=%s ORDER BY filing_date DESC NULLS LAST LIMIT 40""",
                (sym.upper(),),
            )
            or []
        )
    else:
        rows = (
            _db_query("""SELECT s.symbol, s.filer_name, s.filer_relation, s.transaction_type, s.shares,
                              s.price, s.total_value, s.ownership_after, s.filing_date, s.transaction_date, s.sec_url
                            FROM sec_form4 s
                            WHERE s.filing_date > current_date - 30
                              AND (s.symbol IN (SELECT symbol FROM watchlist_items WHERE status<>'removed')
                                   OR s.symbol IN (SELECT symbol FROM watchlist_items WHERE source='portfolio'))
                            ORDER BY s.filing_date DESC NULLS LAST LIMIT 80""")
            or []
        )
    items = [{k: _json_clean(v) for k, v in r.items()} for r in rows]
    return {
        "ok": True,
        "symbol": (sym or None),
        "count": len(items),
        "items": items,
        "note": "SEC Form-4 insider filings (authoritative). Advisory.",
    }


def _watch_provenance(symbol):
    """GET /api/v2/watch/provenance/{symbol} — unified provenance contract for the shared pill row.
    origin + tier + freshness + directive link + Street consensus (Yahoo-authoritative) + divergence.
    Read-only. Uncovered symbol -> explicit nulls, never fabricated."""
    symbol = (symbol or "").upper().strip()
    if not symbol:
        return {"error": "symbol required"}
    item = (
        _db_query(
            """SELECT wi.symbol, wi.origin_system, wi.origin_detail, wi.directive_id,
                          wi.in_directive_watch, wi.source_tier, wi.first_seen_at, wi.last_validated_at,
                          wi.seen_count, wi.provenance_reason, wi.source, d.label AS directive_label, d.kind AS directive_kind
                        FROM watchlist_items wi LEFT JOIN watch_directives d ON d.id = wi.directive_id
                        WHERE wi.symbol = %s ORDER BY wi.updated_at DESC NULLS LAST LIMIT 1""",
            (symbol,),
            fetch="one",
        )
        or {}
    )
    pool = (
        _db_query(
            """SELECT strategy_id, bucket, current_status, expires_at, origin_system, directive_id
                        FROM strategy_watchpool WHERE symbol = %s AND current_status = 'ACTIVE'
                        ORDER BY entered_at DESC""",
            (symbol,),
        )
        or []
    )
    # Tier + divergence + Street consensus via the promotion engine's read-models (shared source of truth).
    tier, divergence, street = item.get("source_tier"), "unavailable", None
    try:
        import sys as _s

        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import directive_promotion as _dp

        if item.get("origin_system"):
            tier = tier or _dp.get_source_tier(item.get("origin_system"))
        divergence = _dp.get_divergence_status(symbol)
        street = _dp.get_street_consensus(symbol)
    except Exception:
        pass
    return {
        "symbol": symbol,
        "origin_system": item.get("origin_system"),
        "origin_detail": item.get("origin_detail"),
        "source": item.get("source"),
        "directive": {
            "id": item.get("directive_id"),
            "label": item.get("directive_label"),
            "kind": item.get("directive_kind"),
        }
        if item.get("directive_id")
        else None,
        "in_directive_watch": item.get("in_directive_watch"),
        "source_tier": tier,
        "divergence": divergence,
        "first_seen_at": _json_clean(item.get("first_seen_at")),
        "last_validated_at": _json_clean(item.get("last_validated_at")),
        "seen_count": item.get("seen_count"),
        "reason": item.get("provenance_reason"),
        "watchpool": [{k: _json_clean(v) for k, v in r.items()} for r in pool],
        "street_consensus": street,
        "note": "Street consensus = Yahoo (authoritative). null = no professional coverage (not fabricated).",
    }


def _watch_directive_create(body):
    """POST /api/v2/watch/directives — create an operator watch directive (APP ROLE — the firewall:
    Hermes can never write this). kind ticker|sector|trend; spec is the resolution payload."""
    import json as _j

    kind = (body.get("kind") or "").strip().lower()
    label = (body.get("label") or "").strip()
    spec = body.get("spec") or {}
    if kind not in ("ticker", "sector", "trend"):
        return 400, {"ok": False, "error": "kind must be ticker|sector|trend"}
    if not label:
        return 400, {"ok": False, "error": "label required"}
    if kind == "ticker" and not (spec.get("symbol")):
        return 400, {"ok": False, "error": "ticker directive needs spec.symbol"}

    # ── KNOWLEDGE THEMES ARE RESEARCH TOPICS, NOT WATCH DIRECTIVES (operator 2026-06-21) ──────────────
    # A trend like "Roth conversion ladder" / "Medicaid Asset Protection Trust" / "IRMAA planning" can never
    # surface a tradeable ticker — creating a watch_directive for it just floods the watchlist with 0-hit
    # noise (it sat at "0 hits · 0 staged" forever). Route these to the KNOWLEDGE-research pipeline
    # (topic_monitor → Hermes/TradeAI research) ONLY; never create a ticker-discovery directive. Genuine
    # ticker-discovery trends ("AI datacenter", "Defense", "Energy") don't match and flow through normally.
    import re as _re

    if kind == "trend":
        _theme = _re.sub(r"^trend\s+", "", label or "", flags=_re.I).strip()
        _kws = [k for k in (spec.get("keywords") or []) if k]
        _planning = bool(
            _re.search(
                r"roth|irmaa|medicaid|medicare|ssdi|estate|trust|mapt|retire|tax|"
                r"conversion|dividend|covered call|income|cef|pty|nav|annuit",
                _theme + " " + " ".join(_kws),
                _re.I,
            )
        )
        if _planning and bool(body.get("hermes_enabled", True)):
            tid = "k_" + _re.sub(r"[^a-z0-9]+", "_", _theme.lower()).strip("_")[:46]
            queries = _kws[:8] if _kws else [_theme]
            ctx = (
                "Operator age 58 (59 Aug 2026), SSDI, NY, Medicare ~Dec 2026, Golden-Window Roth, MAPT "
                "asset protection, ~$1.2M portfolio."
            )
            try:
                _db_query(
                    """INSERT INTO topic_monitor (topic_id, display_name, search_queries, priority,
                               agent_owner, owner, enabled, max_age_days, min_articles, personal_context)
                             VALUES (%s,%s,%s::jsonb,2,'Steph','shared',true,30,3,%s)
                             ON CONFLICT (topic_id) DO NOTHING""",
                    (tid, _theme[:80], _j.dumps(queries), ctx),
                    fetch="none",
                )
            except Exception as e:
                return 200, {"ok": False, "error": "research-topic routing failed: " + str(e)[:160]}
            return 200, {
                "ok": True,
                "directive_id": None,
                "kind": "research_topic",
                "label": label,
                "routed_to_research": True,
                "research_topic": {"topic_id": tid, "knowledge": True},
                "note": "knowledge/planning theme → research pipeline only (no watchlist directive)",
            }

    # ── DEDUP TICKER DIRECTIVES (operator 2026-06-21) ────────────────────────────────────────────────
    # Don't stack a second active ticker directive for the same symbol — re-adds were creating duplicate
    # rows (CEG ×3, SOFI ×3, …) cluttering the Watch Directives list. Reuse the existing active directive
    # (it gets re-serviced below, so the symbol re-evaluates) instead of inserting a duplicate. The
    # existing label is preserved (don't clobber a named-list label with a generic re-add).
    reused = False
    did = None
    if kind == "ticker":
        _symU = (spec.get("symbol") or "").upper()
        _ex = _db_query(
            """SELECT id FROM watch_directives
                           WHERE kind='ticker' AND status='active' AND UPPER(spec->>'symbol')=%s
                           ORDER BY id LIMIT 1""",
            (_symU,),
            fetch="one",
        )
        if _ex:
            did = _ex["id"]
            reused = True
    # Watch Desk v2 (B1): trend family gate — SOFT warning for operator UI:
    # first call returns merge prompt; retry with force=true creates anyway
    if kind == "trend" and did is None and not body.get("force"):
        try:
            import sys as _s

            _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
            from lib.watch_directive_gate import family_gate as _fg

            _g = _fg(label, "trend")
            if not _g["allow"]:
                return 200, {
                    "ok": False,
                    "needs_confirm": True,
                    "merge_candidate": {"id": _g["survivor_id"], "label": _g["survivor_label"]},
                    "note": (
                        f"Merges with existing: '{_g['survivor_label']}' — retry with force=true to create anyway."
                    ),
                }
        except Exception:
            pass
    if did is None:
        row = _db_query(
            """INSERT INTO watch_directives (kind, label, spec, rationale, created_by, ttl_days, priority,
                              trade_ai_enabled, hermes_enabled)
                           VALUES (%s, %s, %s::jsonb, %s, %s, %s, %s, %s, %s) RETURNING id""",
            (
                kind,
                label,
                _j.dumps(spec),
                body.get("rationale"),
                body.get("created_by", "operator"),
                body.get("ttl_days"),
                body.get("priority", "normal"),
                bool(body.get("trade_ai_enabled", True)),
                bool(body.get("hermes_enabled", True)),
            ),
            fetch="one",
        )
        did = (row or {}).get("id")
    # ── SERVICE-AT-CREATION (operator caught 2026-06-12: CIFR added 22:47, servicer cron is
    # market-hours-only → ticker sat invisible until 09:00). Ticker directives now run through the
    # SAME real evaluation engine (directive_promotion.promote_directive_lead) synchronously, so the
    # symbol appears in the watchlist immediately, 24/7. Sector/trend directives still discover via
    # the cron (they are searches, not single symbols). Failure here never loses the directive —
    # the cron remains the safety net.
    serviced = None
    if kind == "ticker" and did:
        try:
            import sys as _sys

            _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
            import directive_promotion as _dp

            res = _dp.promote_directive_lead(
                (spec.get("symbol") or "").upper(), did, f"directive:{label}", "operator", auto=True
            )
            serviced = {"status": res.get("status"), "detail": str(res)[:200]}
            _db_query(
                "UPDATE watch_directives SET last_serviced_at=now(), updated_at=now() WHERE id=%s", (did,), fetch="none"
            )
        except Exception as e:
            serviced = {"status": "DEFERRED_TO_CRON", "detail": str(e)[:140]}
    # ── ROUTE TO BOTH (operator 2026-06-20: "make all route properly to trends and research both"): a
    # trend directive feeds TICKER DISCOVERY only — but knowledge themes (Roth/Medicaid/sector theses)
    # need the KNOWLEDGE-research pipeline too. Mirror every trend directive into topic_monitor (owner
    # 'shared' → researched by BOTH Hermes + TradeAI via the topic bridge). Idempotent; non-fatal.
    research_topic = None
    if kind == "trend" and did and bool(body.get("hermes_enabled", True)):
        try:
            import re as _re

            theme = _re.sub(r"^trend\s+", "", label or "", flags=_re.I).strip()
            tid = "d{}_{}".format(did, _re.sub(r"[^a-z0-9]+", "_", theme.lower()).strip("_")[:44])
            kws = [k for k in (spec.get("keywords") or []) if k]
            queries = kws[:8] if kws else [theme]
            planning = bool(
                _re.search(
                    r"roth|irmaa|medicaid|medicare|ssdi|estate|trust|mapt|retire|tax|"
                    r"conversion|dividend|covered call|income|cef|pty|nav|annuit",
                    theme + " " + " ".join(kws),
                    _re.I,
                )
            )
            ctx = (
                (
                    "Operator age 58 (59 Aug 2026), SSDI, NY, Medicare ~Dec 2026, Golden-Window Roth, MAPT "
                    "asset protection, ~$1.2M portfolio."
                )
                if planning
                else ""
            )
            _db_query(
                """INSERT INTO topic_monitor (topic_id, display_name, search_queries, priority,
                           agent_owner, owner, enabled, max_age_days, min_articles, personal_context)
                         VALUES (%s,%s,%s::jsonb,%s,%s,'shared',true,30,3,%s) ON CONFLICT (topic_id) DO NOTHING""",
                (tid, theme[:80], _j.dumps(queries), 2 if planning else 4, "Steph" if planning else "Alex", ctx),
                fetch="none",
            )
            research_topic = {"topic_id": tid, "planning": planning}
        except Exception as e:
            research_topic = {"error": str(e)[:120]}
    return 200, {
        "ok": True,
        "directive_id": did,
        "kind": kind,
        "label": label,
        "serviced": serviced,
        "research_topic": research_topic,
        "reused": reused,
    }


def _watch_directive_promote(body):
    """POST /api/v2/watch/directives/promote — operator one-tap promotion of a staged hit.
    Routes through the real engine with auto=True (operator override); scalp firewall + fail-closed
    still apply. Runs under the app role."""
    symbol = (body.get("symbol") or "").upper().strip()
    directive_id = body.get("directive_id")
    if not symbol or not directive_id:
        return 400, {"ok": False, "error": "symbol and directive_id required"}
    try:
        import sys as _s

        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import directive_promotion as _dp

        res = _dp.promote_directive_lead(
            symbol,
            int(directive_id),
            body.get("reason") or "operator one-tap promote",
            body.get("source_system") or "operator",
            auto=True,
            actor="operator",
        )
        return 200, {"ok": True, "result": res}
    except Exception as e:
        return 500, {"ok": False, "error": str(e)[:200]}


def _watchpool_list(query=None):
    """GET /api/v2/watchpool — unified watchpool: strategy_watchpool rows with origin + directive link.
    Read-only. Powers the /v3/watchpool page (screener candidates + directive-sourced, same pill row)."""
    # Watch Desk v2 (A3): DISTINCT ON kills the duplicated-row rendering (same
    # symbol+strategy+origin re-entered → keep the latest entry only)
    rows = (
        _db_query("""SELECT * FROM (
                          SELECT DISTINCT ON (sp.symbol, sp.strategy_id, sp.origin_system)
                                 sp.id, sp.strategy_id, sp.symbol, sp.screener_id, sp.bucket, sp.current_status,
                                 sp.entered_at, sp.expires_at, sp.origin_system, sp.directive_id, d.label AS directive_label
                          FROM strategy_watchpool sp LEFT JOIN watch_directives d ON d.id = sp.directive_id
                          ORDER BY sp.symbol, sp.strategy_id, sp.origin_system, sp.entered_at DESC
                        ) t ORDER BY t.entered_at DESC LIMIT 200""")
        or []
    )
    by_status, by_origin = {}, {}
    for r in rows:
        st = r.get("current_status") or "?"
        by_status[st] = by_status.get(st, 0) + 1
        o = r.get("origin_system") or "screener"
        by_origin[o] = by_origin.get(o, 0) + 1
    return {
        "count": len(rows),
        "by_status": by_status,
        "by_origin": by_origin,
        "rows": [{k: _json_clean(v) for k, v in r.items()} for r in rows],
    }


def _watch_sectors(query=None):
    """GET /api/v2/watch/sectors — Finviz sector list with DISTINCT constituent counts + sample
    symbols, for the Add-Watch sector dropdown + constituent preview. Read-only."""
    rows = (
        _db_query("""SELECT sector, count(DISTINCT symbol) AS n,
                          (array_agg(DISTINCT symbol ORDER BY symbol))[1:10] AS sample
                        FROM incubator_universe WHERE sector IS NOT NULL AND sector <> ''
                        GROUP BY sector ORDER BY count(DISTINCT symbol) DESC""")
        or []
    )
    return {"sectors": [{"sector": r["sector"], "count": r["n"], "sample": r.get("sample") or []} for r in rows]}


def _hermes_setup(rsi, trend):
    """Classify a trade setup (spec §8) from posture. Advisory — entry/invalidation/conviction."""
    r = float(rsi) if rsi is not None else None
    t = (trend or "").lower()
    if r is None or t in ("", "unknown"):
        return {
            "type": "no-trade / low-conviction",
            "entry": "insufficient signal",
            "invalidation": "—",
            "conviction": "low",
            "why": "awaiting enrichment / no clear posture",
        }
    if t == "bullish" and r < 45:
        return {
            "type": "pullback entry",
            "entry": "buy strength off the pullback",
            "invalidation": "loss of the recent higher-low",
            "conviction": "medium",
            "why": "uptrend with RSI cooled into a buy zone",
        }
    if t == "bullish" and r < 65:
        return {
            "type": "trend continuation",
            "entry": "join on continuation / minor pullback",
            "invalidation": "break below trend support",
            "conviction": "medium-high",
            "why": "uptrend intact, RSI constructive",
        }
    if t == "bullish":
        return {
            "type": "momentum continuation (extended)",
            "entry": "only on a controlled pullback",
            "invalidation": "momentum stall + RSI roll-over",
            "conviction": "medium",
            "why": "strong momentum but RSI extended — chase risk",
        }
    if t == "bearish" and r < 38:
        return {
            "type": "reversal / mean-reversion watch",
            "entry": "wait for a reversal trigger",
            "invalidation": "new lows",
            "conviction": "low-medium",
            "why": "downtrend but oversold — bounce possible, not confirmed",
        }
    if t == "bearish":
        return {
            "type": "no-trade (downtrend)",
            "entry": "stand aside / short bias only",
            "invalidation": "reclaim of trend",
            "conviction": "low",
            "why": "downtrend without an oversold edge",
        }
    return {
        "type": "range / mean-reversion",
        "entry": "fade the edges of the range",
        "invalidation": "range break",
        "conviction": "low",
        "why": "neutral trend — range conditions",
    }


def _hermes_risks(comp, divergence, advisory):
    out = []
    if (comp.get("_coverage") or 1) < 0.45:
        out.append("thin intelligence coverage — score from few factors")
    if divergence == "divergent":
        out.append("internal view diverges from Street (analyst) consensus")
    if advisory and "caution" in str(advisory).lower():
        out.append("RSI band historically weak (setup-advisory caution)")
    if comp.get("social_sentiment") and not comp.get("setup_quality"):
        out.append("attention-driven (social) without a qualified strategy setup")
    return out


def _hermes_competition(symbol, sector, industry):
    """H-3: peer group from same industry (fallback sector) + relative strength by Hermes score.
    Limited to peers with intelligence coverage; honest 'no peers' when none. Advisory."""
    key, val = ("industry", industry) if industry else ("sector", sector)
    if not val:
        return None
    peers = (
        _db_query(
            f"""SELECT e.display_name AS symbol, wi.hermes_composite_score AS score,
                            e.change_pct, wi.trend
                          FROM intelligence_entities e
                          LEFT JOIN watchlist_items wi ON wi.symbol = e.display_name
                          WHERE e.{key} = %s AND e.display_name ~ '^[A-Z]{{1,5}}$' AND e.display_name <> %s
                          ORDER BY wi.hermes_composite_score DESC NULLS LAST LIMIT 12""",
            (val, symbol),
        )
        or []
    )
    if not peers:
        return {"peer_group": val, "peer_count": 0, "peers": [], "vs_peers": "no peers with intelligence coverage"}
    scores = [float(p["score"]) for p in peers if p.get("score") is not None]
    me = (
        _db_query(
            """SELECT hermes_composite_score FROM watchlist_items WHERE symbol=%s
                      ORDER BY hermes_composite_score DESC NULLS LAST LIMIT 1""",
            (symbol,),
            fetch="one",
        )
        or {}
    )
    my = me.get("hermes_composite_score")
    rel_rank, vs = None, "unknown"
    if my is not None and scores:
        my = float(my)
        rel_rank = f"#{sum(1 for s in scores if s > my) + 1} of {len(scores) + 1} in {val}"
        med = sorted(scores)[len(scores) // 2]
        vs = "leading peers" if my > med else "lagging peers"
    return {
        "peer_group": val,
        "peer_count": len(peers),
        "peers": [
            {"symbol": p["symbol"], "score": _json_clean(p.get("score")), "trend": p.get("trend")} for p in peers[:6]
        ],
        "relative_rank": rel_rank,
        "vs_peers": vs,
    }


def _hermes_intel(symbol):
    """GET /api/v2/hermes/intel/{symbol} — structured Hermes intelligence card (spec §9): composite
    score + rank + confidence, factor breakdown, analyst / sector / social views, trade-setup
    recommendation, catalysts, risks. Read-only; advisory."""
    symbol = (symbol or "").upper().strip()
    wi = _db_query(
        """SELECT symbol, hermes_composite_score, hermes_rank, hermes_score_components,
                        hermes_scored_at, rsi, trend, price, change_pct, setup_advisory,
                        origin_system, source_tier, directive_id
                      FROM watchlist_items WHERE symbol=%s AND status <> 'removed'
                      ORDER BY hermes_composite_score DESC NULLS LAST LIMIT 1""",
        (symbol,),
        fetch="one",
    )
    if not wi:
        return {"symbol": symbol, "note": "not on the watchlist or not yet scored"}
    comp = wi.get("hermes_score_components") or {}
    ie = (
        _db_query(
            """SELECT sector, industry, social_sentiment, social_score, catalyst, catalyst_verified, rvol
                      FROM intelligence_entities WHERE display_name=%s LIMIT 1""",
            (symbol,),
            fetch="one",
        )
        or {}
    )
    analyst, divergence = None, None
    try:
        # ── Data Broker Wave B: use analyst_rollup instead of direct file I/O ──
        from lib.data_broker.analyst_rollup import get_analyst_rollup

        _ar = get_analyst_rollup(symbols=[symbol]).get(symbol.upper()) or {}
        # Fall back to raw file for fields the broker doesn't yet expose
        import json as _j

        _pills_raw = _j.loads((PROJECT_ROOT / "data" / "runtime" / "pro_analyst_pills_latest.json").read_text()).get(
            "pills", []
        )
        _raw = next((x for x in _pills_raw if str(x.get("symbol") or "").upper() == symbol.upper()), {})
        if _raw.get("has_professional_coverage"):
            divergence = _raw.get("divergence")
            analyst = {
                "recommendation": _ar.get("rec_key") or _raw.get("recommendation_key"),
                "rec_mean": _raw.get("recommendation_mean"),
                "target_mean": _ar.get("mean_target") or _raw.get("target_mean_price"),
                "upside_pct": _raw.get("upside_to_mean_target_pct"),
                "analysts": _ar.get("analyst_count") or _raw.get("number_of_analyst_opinions"),
                "divergence": divergence,
                "latest_event": _raw.get("latest_event_headline"),
            }
    except Exception:
        pass
    factors = [{"factor": k, **v} for k, v in comp.items() if not k.startswith("_")]
    factors.sort(key=lambda f: -(f.get("score", 0) * f.get("weight", 0)))
    # H-6: external-LLM full theses (latest per lane) for the intel-card drawer
    ext_rows = (
        _db_query(
            """SELECT DISTINCT ON (lane) lane, model, recommendation, evidence_json, dissent,
                              confidence, risk_flags, created_at
                            FROM hermes_external_research
                            WHERE symbol=%s AND status IN ('sent','ok','complete','success')
                            ORDER BY lane, created_at DESC""",
            (symbol,),
        )
        or []
    )
    external_intel = []
    for e in ext_rows:
        _eep = _evidence_packet(e.get("evidence_json") or e)
        external_intel.append(
            {
                "lane": e["lane"],
                "model": e.get("model"),
                "recommendation": e.get("recommendation"),
                "evidence": _eep.get("evidence") or [],
                "data_i_doubt": _eep.get("data_i_doubt"),
                "agent_contract": _eep.get("agent_contract"),
                "dissent": e.get("dissent"),
                "confidence": _json_clean(e.get("confidence")),
                "risk_flags": e.get("risk_flags"),
                "at": _json_clean(e.get("created_at")),
            }
        )
    _fs = _db_query(
        "SELECT dual_consensus_json, synthesis_narrative, recommendation FROM watchlist_final_synthesis WHERE symbol=%s",
        (symbol,),
        fetch="one",
    )
    _cio_ep = _evidence_packet(_fs.get("dual_consensus_json") if _fs else {})
    return {
        "symbol": symbol,
        "composite_score": _json_clean(wi.get("hermes_composite_score")),
        "external_intel": external_intel,
        "cio_synthesis": {
            "recommendation": _fs.get("recommendation") if _fs else None,
            "narrative_snip": str((_fs or {}).get("synthesis_narrative") or "")[:320],
            "evidence": _cio_ep.get("evidence") or [],
            "data_i_doubt": _cio_ep.get("data_i_doubt"),
            "agent_contract": _cio_ep.get("agent_contract"),
        }
        if _fs
        else None,
        "rank": wi.get("hermes_rank"),
        "confidence": comp.get("_confidence"),
        "coverage": comp.get("_coverage"),
        "raw_score": comp.get("_raw_score"),
        "scored_at": _json_clean(wi.get("hermes_scored_at")),
        "factors": factors,
        "analyst": analyst,
        "sector": {"sector": ie.get("sector"), "industry": ie.get("industry")} if ie.get("sector") else None,
        "competition": _hermes_competition(symbol, ie.get("sector"), ie.get("industry")),
        "social": {"sentiment": ie.get("social_sentiment"), "score": _json_clean(ie.get("social_score"))}
        if (ie.get("social_sentiment") or ie.get("social_score"))
        else None,
        "setup": _hermes_setup(wi.get("rsi"), wi.get("trend")),
        "catalysts": [str(ie["catalyst"])[:160]] if ie.get("catalyst") else [],
        "risks": _hermes_risks(comp, divergence, wi.get("setup_advisory")),
        "technical": {
            "rsi": _json_clean(wi.get("rsi")),
            "trend": wi.get("trend"),
            "rvol": _json_clean(ie.get("rvol")),
            "price": _json_clean(wi.get("price")),
            "change_pct": _json_clean(wi.get("change_pct")),
        },
        "provenance": {
            "origin": wi.get("origin_system"),
            "tier": wi.get("source_tier"),
            "directive_id": wi.get("directive_id"),
        },
        "note": "Advisory composite of news/social, analyst, sector, momentum, setup, R:R. Never gates execution.",
    }


def _hermes_external_intel_map(query=None):
    """GET /api/v2/hermes/external-intel-map — per-symbol external-LLM curation (which lane curated it +
    when + verdict) from hermes_external_research (last 14d). Powers the watchlist 'curated by
    ChatGPT/Grok' badges + tooltip dates. Read-only; advisory."""
    rows = (
        _db_query("""SELECT DISTINCT ON (symbol, lane) symbol, lane, model, created_at, recommendation, confidence
                        FROM hermes_external_research
                        WHERE status IN ('sent','ok','complete','success') AND symbol IS NOT NULL
                          AND created_at > now() - interval '14 days'
                        ORDER BY symbol, lane, created_at DESC""")
        or []
    )
    out = {}
    for r in rows:
        out.setdefault(r["symbol"], []).append(
            {
                "lane": r["lane"],
                "model": r.get("model"),
                "at": _json_clean(r["created_at"]),
                "recommendation": r.get("recommendation"),
                "confidence": _json_clean(r.get("confidence")),
            }
        )
    return {"map": out, "symbols": len(out)}


def _hermes_subject_intel(query=None):
    """GET /api/v2/hermes/subject-intel?type=&key= — external-LLM full theses for ANY subject
    (proposal/position/closed_trade/sector/report), latest per lane. Powers the per-surface drawers."""
    q = query or {}
    ttype, key = q.get("type", ""), q.get("key", "")
    if not ttype or not key:
        return {"external_intel": []}
    rows = (
        _db_query(
            """SELECT DISTINCT ON (lane) lane, model, recommendation, evidence_json, dissent,
                          confidence, risk_flags, created_at
                        FROM hermes_external_research
                        WHERE symbol=%s AND trigger_reason=%s AND status IN ('sent','ok','complete','success')
                        ORDER BY lane, created_at DESC""",
            (key, f"enh_{ttype}"),
        )
        or []
    )
    # Hermes composite (2026-06-11): the watchlist intelligence rank surfaces wherever decisions happen
    hermes = None
    try:
        h = _db_query(
            """SELECT hermes_composite_score, hermes_rank,
                                hermes_score_components->>'_regime' AS regime
                         FROM watchlist_items
                         WHERE symbol=%s AND hermes_rank IS NOT NULL
                         ORDER BY hermes_rank LIMIT 1""",
            (key,),
            fetch="one",
        )
        if h:
            hermes = {
                "composite": _json_clean(h.get("hermes_composite_score")),
                "rank": h.get("hermes_rank"),
                "regime": h.get("regime"),
            }
    except Exception:
        pass
    return {
        "type": ttype,
        "key": key,
        "hermes": hermes,
        "external_intel": [
            {
                "lane": r["lane"],
                "model": r.get("model"),
                "recommendation": r.get("recommendation"),
                "evidence": r.get("evidence_json"),
                "dissent": r.get("dissent"),
                "confidence": _json_clean(r.get("confidence")),
                "risk_flags": r.get("risk_flags"),
                "at": _json_clean(r.get("created_at")),
            }
            for r in rows
        ],
    }


