def _finviz_chart(query=None):
    """GET /api/v2/finviz-chart?symbol=&p= — proxy the Finviz Elite chart IMAGE (attaches the Elite cookie
    server-side; the browser can't). Returns the PNG bytes. Tier-3 fallback when Alpaca/Schwab have no bars."""
    import os as _os, urllib.request

    q = query or {}
    g = lambda k: (q.get(k) or [None])[0] if isinstance(q.get(k), list) else q.get(k)
    sym = (g("symbol") or "").upper()[:8]
    p = g("p") or "d"
    if not sym.isalnum():
        return 400, {"ok": False, "error": "bad symbol"}
    import base64 as _b64

    ck = _os.environ.get("FINVIZ_COOKIE", "").strip().strip("\"'")
    ua = _os.environ.get("FINVIZ_USER_AGENT", "Mozilla/5.0").strip().strip("\"'")
    url = f"https://elite.finviz.com/chart.ashx?t={sym}&ty=c&ta=1&p={p}&s=l"
    try:
        # On-demand chart proxy — throttled like every other Finviz call.
        # Local import: api_v2 is hot-reloaded, keep module import surface stable.
        import finviz_throttle

        finviz_throttle.acquire(timeout=20)
        req = urllib.request.Request(url, headers={"Cookie": ck, "User-Agent": ua})
        with urllib.request.urlopen(req, timeout=12) as r:
            data = r.read()
        if data[:8].startswith(b"\x89PNG") or data[:3] == b"\xff\xd8\xff":  # PNG or JPEG
            mime = "image/png" if data[:8].startswith(b"\x89PNG") else "image/jpeg"
            # base64 data URI — the server JSON-serializes, so we can't stream raw bytes
            return {"ok": True, "symbol": sym, "image": f"data:{mime};base64," + _b64.b64encode(data).decode()}
        return 502, {
            "ok": False,
            "error": "finviz returned non-image (cookie expired — refresh FINVIZ_COOKIE in System > secrets)",
        }
    except Exception as e:
        return 502, {"ok": False, "error": str(e)[:120]}


def _upload_csv(body):
    """POST /api/v2/upload-csv {dest, filename, content} — save an operator CSV to a whitelisted import dir.

    For remote (Tailscale) operators who can't drop files on the box. Whitelisted dirs only; filename is
    sanitized to a basename (no traversal); .csv/.txt only; size-capped. Read-only data intake, no exec."""
    import os as _os, re as _re

    b = body or {}
    dest = (b.get("dest") or "").strip()
    fn = (b.get("filename") or "").strip()
    content = b.get("content") or ""
    ALLOWED = {"schwab_history", "schwab_gainloss", "tos_watchlists"}
    if dest not in ALLOWED:
        return 400, {"ok": False, "error": f"dest must be one of {sorted(ALLOWED)}"}
    fn = _re.sub(r"[^A-Za-z0-9._-]", "_", _os.path.basename(fn))
    if not fn or not _re.search(r"\.(csv|txt)$", fn, _re.I):
        return 400, {"ok": False, "error": "filename must end in .csv or .txt"}
    if not isinstance(content, str) or len(content) > 12_000_000:
        return 400, {"ok": False, "error": "content missing or too large (>12MB)"}
    base = (PROJECT_ROOT / "imports" / dest).resolve()
    base.mkdir(parents=True, exist_ok=True)
    path = (base / fn).resolve()
    if _os.path.commonpath([str(base), str(path)]) != str(base):
        return 400, {"ok": False, "error": "invalid path"}
    path.write_text(content)
    return 200, {"ok": True, "saved": f"imports/{dest}/{fn}", "bytes": len(content), "rows": content.count(chr(10))}


def _execution_hypotheses(query=None):
    """GET /api/v2/backtesting/execution-hypotheses?strategy=&symbol= — evidence-only rule-variant aggregates."""
    q = query or {}
    g = lambda k: (q.get(k) or [None])[0] if isinstance(q.get(k), list) else q.get(k)
    where, params = ["applicable"], []
    if g("strategy"):
        where.append("strategy_id=%s")
        params.append(g("strategy"))
    if g("symbol"):
        where.append("symbol=%s")
        params.append(g("symbol").upper())
    agg = (
        _db_query(
            f"""SELECT hypothesis, count(*) AS sample,
                          round(100.0*count(*) FILTER(WHERE improved)/count(*)) AS improved_pct,
                          round(avg(delta_ps),4) AS avg_delta_ps, (count(*) < 5) AS do_not_graft
                        FROM trade_execution_hypothesis_results WHERE {" AND ".join(where)}
                        GROUP BY hypothesis ORDER BY avg(delta_ps) DESC""",
            tuple(params),
        )
        or []
    )
    return {
        "aggregate": [_json_clean(r) for r in agg],
        "note": "Evidence only — never auto-applied to live strategy configs.",
    }


def _execution_quality(query=None):
    """GET /api/v2/journal/execution-quality?source=&symbol=&limit= — computed execution grades + Grok review."""
    q = query or {}
    g = lambda k: (q.get(k) or [None])[0] if isinstance(q.get(k), list) else q.get(k)
    where, params = ["path_status='OK'"], []
    if g("source"):
        where.append("source=%s")
        params.append(g("source"))
    if g("symbol"):
        where.append("symbol=%s")
        params.append(g("symbol").upper())
    limit = min(int(g("limit") or 200), 500)
    rows = (
        _db_query(
            f"""SELECT trade_key, source, symbol, account, entry_time, exit_time, strategy_id, outcome_grade, execution_grade,
                          entry_timing_grade, exit_timing_grade, capture_ratio, entry_volume_ratio,
                          entry_above_vwap, mfe_after_exit_pct, missed_opportunity_grade, computed_summary,
                          strategy_rule_violations, grok_execution_label, grok_what_to_do_next_time,
                          grok_strategy_backtest_hypotheses, normalized_tags,
                          entry_price, exit_price, mfe_after_entry, mae_after_entry, post_exit_high,
                          runner_type, post_exit_gave_back_ratio
                         FROM v_trade_execution_quality_latest WHERE {" AND ".join(where)}
                         ORDER BY exit_time DESC LIMIT {limit}""",
            tuple(params),
        )
        or []
    )
    return {"trades": [_json_clean(r) for r in rows], "count": len(rows)}


def _daily_coaching(query=None):
    """GET /api/v2/journal/daily-execution-coaching[/latest] — latest coaching run + ranked items + Grok digest.
    Read-only/advisory: no live-strategy/trading state. Hypotheses surface as shadow-research candidates only."""
    run = _db_query("SELECT * FROM daily_execution_coaching_runs ORDER BY id DESC LIMIT 1")
    if not run:
        return {"run": None, "items": [], "digest": None, "advisory": True}
    run = run[0]
    items = (
        _db_query(
            "SELECT rank, severity, item_type, symbol, strategy_family, source, sample_size, "
            "avg_capture_ratio, avg_missed_pct, avg_delta_ps, lesson, operator_action, status, trade_keys_json "
            "FROM daily_execution_coaching_items WHERE run_id=%s ORDER BY rank",
            (run["id"],),
        )
        or []
    )
    digest = _db_query(
        "SELECT digest_json, review_status, created_at FROM daily_execution_grok_digests "
        "WHERE run_id=%s ORDER BY id DESC LIMIT 1",
        (run["id"],),
    )
    ai_critique = None
    try:
        import journal_trade_in_view as tiv

        ai_critique = tiv.ai_critique_insights(days=30)
    except Exception:
        pass
    return {
        "run": _json_clean(run),
        "items": [_json_clean(i) for i in items],
        "digest": _json_clean(digest[0]) if digest else None,
        "advisory": True,
        "ai_critique_insights": ai_critique,
    }


