def _journal_csv_import(body):
    """POST /api/v2/journal/import-csv — Schwab transaction history CSV → holdings journal + round-trip rebuild."""
    b = body or {}
    csv_text = b.get("csv_text") or ""
    if not csv_text.strip():
        return {"ok": False, "error": "csv_text required"}
    try:
        from portfolio_server import _parse_txn_csv, handle_import_transactions

        parsed = _parse_txn_csv({"csv_text": csv_text, "filename": b.get("filename", "schwab_taxable_history.csv")})
        status, result = handle_import_transactions(parsed)
        import subprocess

        subprocess.run(
            [
                str(PROJECT_ROOT / ".venv/bin/python3"),
                str(PROJECT_ROOT / "scripts/schwab_journal_builder.py"),
                "--apply",
            ],
            cwd=str(PROJECT_ROOT),
            timeout=120,
            check=False,
        )
        enrich = {}
        try:
            import journal_trade_in_view as tiv

            enrich = tiv.tagging_queue_auto_enrich(days=int(b.get("days") or 365))
        except Exception as enrich_err:
            enrich = {"ok": False, "error": str(enrich_err)}
        return {
            "ok": True,
            "import_status": status,
            "auto_enrich": enrich,
            **(result if isinstance(result, dict) else {"result": result}),
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _tos_watchlists_list(query=None):
    """GET /api/v2/tos-watchlists — ToS-imported watchlists with members (active + removed dates) + events."""
    wls = (
        _db_query("""SELECT id, name, display_name, strategy_match, notes, symbol_count, last_imported_at,
                         created_at FROM tos_watchlists ORDER BY COALESCE(display_name, name)""")
        or []
    )
    out = []
    for w in wls:
        mems = (
            _db_query(
                """SELECT symbol, added_at, removed_at, notes FROM tos_watchlist_members
                            WHERE watchlist_id=%s ORDER BY (removed_at IS NOT NULL), symbol""",
                (w["id"],),
            )
            or []
        )
        out.append(
            {
                **w,
                "last_imported_at": _json_clean(w["last_imported_at"]),
                "created_at": _json_clean(w["created_at"]),
                "active": [
                    {"symbol": m["symbol"], "added_at": _json_clean(m["added_at"]), "notes": m["notes"]}
                    for m in mems
                    if not m["removed_at"]
                ],
                "removed": [
                    {
                        "symbol": m["symbol"],
                        "added_at": _json_clean(m["added_at"]),
                        "removed_at": _json_clean(m["removed_at"]),
                    }
                    for m in mems
                    if m["removed_at"]
                ],
            }
        )
    return {
        "watchlists": out,
        "count": len(out),
        "note": "ToS (thinkorswim) watchlists — Schwab Trader API has no watchlist endpoint, so these import from imports/tos_watchlists/. Add/remove dates tracked.",
    }


def _tos_watchlist_manage(body):
    """POST /api/v2/tos-watchlists/manage {watchlist_id, action: rename|strategy|notes|member_note, value, symbol?}."""
    b = body or {}
    wid, action, value = b.get("watchlist_id"), (b.get("action") or "").lower(), b.get("value")
    if not wid or action not in ("rename", "strategy", "notes", "member_note"):
        return 400, {"ok": False, "error": "watchlist_id + action(rename|strategy|notes|member_note) required"}
    col = {"rename": "display_name", "strategy": "strategy_match", "notes": "notes"}.get(action)
    if col:
        _db_query(f"UPDATE tos_watchlists SET {col}=%s, updated_at=NOW() WHERE id=%s", (value, int(wid)), fetch="none")
        return 200, {"ok": True, "watchlist_id": wid, "action": action, "value": value}
    # member_note: per-symbol note
    _db_query(
        "UPDATE tos_watchlist_members SET notes=%s WHERE watchlist_id=%s AND symbol=%s",
        (value, int(wid), b.get("symbol")),
        fetch="none",
    )
    return 200, {"ok": True, "watchlist_id": wid, "action": "member_note", "symbol": b.get("symbol")}


def _schwab_round_trips(query=None):
    """GET /api/v2/journal/schwab-round-trips — real-account round-trips (5-min agg + FIFO from the
    API-authoritative ledger). Read-only."""
    rows = (
        _db_query("""SELECT account, symbol, entry_time, exit_time, hold_minutes, qty, entry_price,
                          exit_price, gross_pnl, fees, net_pnl, pnl_pct, classification,
                          strategy_tag, entry_grade, exit_grade, lesson, review_lane, basis_status, basis_source,
                          canary
                        FROM schwab_round_trips ORDER BY exit_time DESC LIMIT 600""")
        or []
    )
    trips = [
        {
            **r,
            "entry_time": _json_clean(r["entry_time"]),
            "exit_time": _json_clean(r["exit_time"]),
            **{
                k: _json_clean(r[k])
                for k in ("qty", "entry_price", "exit_price", "gross_pnl", "fees", "net_pnl", "pnl_pct")
            },
        }
        for r in rows
    ]
    # ACTIVE trading stats EXCLUDE long-term trims (pre-window lots) + basis_unknown — they aren't trading.
    # Stage 2a: canary test orders also EXCLUDED from every aggregate (listed with a canary badge only).
    active = [t for t in trips if not t.get("basis_status") and not t.get("canary")]
    canary_trips = [t for t in trips if t.get("canary")]
    lt = [t for t in trips if t.get("basis_status") == "long_term_trim"]
    unk = [t for t in trips if t.get("basis_status") == "basis_unknown"]
    wins = sum(1 for t in active if (t["net_pnl"] or 0) > 0)
    by_acct = {}
    for t in active:
        a = by_acct.setdefault(t["account"], {"count": 0, "net": 0.0})
        a["count"] += 1
        a["net"] = round(a["net"] + (t["net_pnl"] or 0), 2)
    return {
        "round_trips": trips,
        "count": len(active),
        "wins": wins,
        "losses": len(active) - wins,
        "win_rate": round(wins / len(active) * 100, 1) if active else 0,
        "net_pnl": round(sum(t["net_pnl"] or 0 for t in active), 2),
        "by_account": by_acct,
        "long_term_trims": {"count": len(lt), "realized": round(sum(t["net_pnl"] or 0 for t in lt), 2)},
        "basis_unknown": {"count": len(unk), "symbols": sorted(set(t["symbol"] for t in unk))},
        "canary": {
            "count": len(canary_trips),
            "symbols": sorted(set(t["symbol"] for t in canary_trips)),
            "note": "Stage 2a test orders — excluded from ALL stats/aggregates above",
        },
        "note": "Active trading stats exclude long-term trims (pre-window lots, e.g. V at ~$10.75 IPO basis), basis_unknown sells (no opening lot in the data — flagged, never fabricated as losses), and Stage-2a canary test orders. Real-account, separate from the paper-only live-trading gate.",
    }


