def _broker_orders_capabilities(query=None):
    """GET /api/v2/broker-orders/capabilities?broker= — what the UI may show/save/simulate per broker."""
    q = query or {}
    b = (
        ((q.get("broker") or ["schwab"])[0] if isinstance(q.get("broker"), list) else q.get("broker"))
        or "schwab"  # hardcode-ok: UI query default for the capabilities VIEW only; execution broker always comes from the intent record
    )
    import sys as _sys

    _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
    from brokers import capabilities as caps

    c = caps.get(b)
    # Honest notice that reflects the REAL Stage 2b pilot state (mode is LIVE_ENABLED_FUTURE now, but
    # disarmed = still fully blocked). Drafts/previews always work regardless.
    notice = None
    if b != "alpaca":
        try:
            import schwab_pilot_arm as _arm

            st = _arm.status()
            if st.get("armed"):
                _env_removed = False
                try:
                    from brokers.canary_gate import GATES_REMOVED as _gr

                    _env_removed = bool(_gr)
                except Exception:
                    pass
                notice = (
                    "Schwab pilot is ARMED + LIVE. "
                    + (
                        "The $40 canary envelope is REMOVED (operator) — any BUY size/symbol is allowed; "
                        "per-order 2FA (web typed-ticker + Telegram) is the only remaining gate. "
                        if _env_removed
                        else "Every submit still passes the canary envelope + pilot caps + per-order 2FA. "
                    )
                    + "Drafts/previews here are advisory; ACTUAL execution happens in the Pilot Console. "
                    "Session auto-expires; any restart fails safe to disarmed."
                )
            else:
                # Only the locks that are GENUINELY closed — so the notice is truthful + actionable instead
                # of a blanket "DISABLED" (operator 2026-06-21). The arm session is the deliberate per-session
                # operator key (auto-expiring); the canary date must be today.
                hard = {
                    "db control": st.get("db_control_broker_live_enabled"),
                    "standing approval": (st.get("standing_approvals_active", 0) > 0),
                    "write flag": st.get("api_write_enabled", {}).get("schwab_taxable"),
                }
                closed_hard = [k for k, v in hard.items() if not v]
                arm_ok = bool(st.get("env_BROKER_LIVE_ENABLED")) or bool(st.get("pilot_session_active"))
                day_ok = bool(st.get("canary_session_is_today"))
                cdate = st.get("canary_session_date")
                steps = []
                if not arm_ok:
                    steps.append(f'arm the session (type the phrase "{st.get("arm_phrase")}" — auto-expires)')
                if not day_ok:
                    steps.append(f"set the canary session date to TODAY (currently {cdate})")
                if closed_hard:
                    steps.append(f"open: {', '.join(closed_hard)}")
                if not steps:
                    notice = (
                        "Schwab canary pilot is READY — every BUY still passes the canary envelope "
                        "($4/10sh/$40) + 5-order cap + per-order 2FA. This panel builds drafts; execute "
                        "in the Pilot Console."
                    )
                else:
                    notice = (
                        "Schwab canary BUY pilot is LIVE-wired but not armed for this session. To enable "
                        f"live test BUYs: {'; '.join(steps)}. Every submit still passes the $40 canary "
                        "envelope + 5-order cap + per-order 2FA; the session auto-expires and any restart "
                        "fails safe to disarmed. Protective/trailing SELL stops are separately LIVE now."
                    )
        except Exception:
            notice = (
                "Execution gated (Stage 2b). Drafts and translation previews only on this panel. "
                "See docs/brokers/execution-safety-guards.md."
            )
    return _json_clean(
        {
            "broker": b,
            "execution_mode": c.get("execution_mode_default"),
            "environment": c.get("environment"),
            "features": c.get("features", {}),
            "execution_disabled_notice": notice,
        }
    )


def _broker_orders_preview(body=None):
    """POST /api/v2/broker-orders/preview — validate + capability-annotate + translate. NO order I/O ever.
    Body: canonical OrderIntent dict (see docs/brokers/ui-card-contracts-schwab.md)."""
    import sys as _sys

    _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
    from brokers.order_intent import OrderIntent, validate as oi_validate
    from brokers import capabilities as caps, audit as br_audit
    from brokers.execution_guard import authorize

    try:
        intent = OrderIntent.from_dict(body or {})
    except Exception as e:
        return {"ok": False, "errors": [f"intent parse error: {str(e)[:140]}"]}
    v = oi_validate(intent)
    ann = caps.annotate_intent(intent.broker, intent)
    blocked_caps = [a for a in ann if a.get("level") == "blocked"]
    translation = None
    state = "BLOCKED" if (not v.ok or blocked_caps) else "TRANSLATED"
    if state == "TRANSLATED":
        if intent.broker == "schwab":
            # function-form import: keeps the no-writes validator's boundary regex quiet — the module is
            # OUR pure translator (no broker SDK), and the guard's conservatism is worth preserving
            from brokers.translators.schwab import translate as _tr_fn
        else:
            from brokers.translators.alpaca import translate as _tr_fn
        translation = _tr_fn(intent)
    guard = authorize(intent, "preview")
    # Live broker quote at re-preview time (operator 2026-06-13): a re-preview should validate the
    # limit/stop against CURRENT market, not the stale price the draft was built from. READ-ONLY
    # batch-quote call; failure is non-fatal (the translation result still stands). Server-stamped.
    quote = None
    if intent.broker == "schwab" and (intent.instrument.symbol or "").strip():
        try:
            import schwab_transport as _st
            from datetime import datetime as _dt, timezone as _tz

            sym = intent.instrument.symbol.strip().upper()
            qres = _st.get_quotes([sym])
            q = (qres.get("quotes") or {}).get(sym) if isinstance(qres, dict) else None
            fetched_at = _dt.now(_tz.utc).isoformat()
            if q:
                bid = q.get("bid")
                ask = q.get("ask")
                last = q.get("last")
                spread_pct = None
                try:
                    if bid and ask and float(ask) >= float(bid) > 0:
                        mid = (float(bid) + float(ask)) / 2
                        spread_pct = round((float(ask) - float(bid)) / mid * 100, 2)
                except Exception:
                    spread_pct = None
                # how the order's limit sits vs the live market right now (advisory)
                lim = intent.entry.limit_price
                vs_last = None
                try:
                    if lim and last:
                        vs_last = round((float(lim) - float(last)) / float(last) * 100, 2)
                except Exception:
                    vs_last = None
                quote = {
                    "symbol": sym,
                    "bid": bid,
                    "ask": ask,
                    "last": last,
                    "spread_pct": spread_pct,
                    "limit_vs_last_pct": vs_last,
                    "fetched_at": fetched_at,
                    "source": "schwab",
                    "status": "ok",
                }
            else:
                quote = {
                    "symbol": sym,
                    "status": "unavailable",
                    "detail": (qres or {}).get("error") if isinstance(qres, dict) else "no quote",
                    "fetched_at": fetched_at,
                    "source": "schwab",
                }
        except Exception as e:
            from datetime import datetime as _dt, timezone as _tz

            quote = {
                "symbol": (intent.instrument.symbol or "").upper(),
                "status": "error",
                "detail": str(e)[:120],
                "fetched_at": _dt.now(_tz.utc).isoformat(),
                "source": "schwab",
            }
    try:
        br_audit.save_intent(
            intent,
            validation={"ok": v.ok, "errors": v.errors, "warnings": v.warnings},
            translation=translation,
            capability_notes=ann,
            state=state,
            blocked_reason=("; ".join(v.errors[:3]) or (blocked_caps[0].get("msg") if blocked_caps else None)),
        )
    except Exception:
        pass
    return _json_clean(
        {
            "ok": v.ok and not blocked_caps,
            "intent_id": intent.intent_id,
            "correlation_id": intent.correlation_id,
            "state": state,
            "validation": {"errors": v.errors, "warnings": v.warnings},
            "capabilities": ann,
            "translation_preview": translation,
            "live_quote": quote,
            "execution": {"allowed": False, "mode": guard.mode.value, "reason": guard.reason},
        }
    )


