_SYMBOL_CARDS_CACHE = {"ts": 0.0, "etag": None, "payload": None}
_SYMBOL_CARDS_TTL = 300  # rebuild at most every 5 min; card inputs move on cron cadence


def _symbol_cards(query=None):
    """GET /api/v2/symbol-cards — cached wrapper. Engine Room v1: this was the top
    unprotected payload (1.95MB × every tab poll, ~1s DB build each time). Serve from a
    5-min in-process cache with a content ETag so repeat polls 304 before serialize/gzip."""
    import time as _t

    c = _SYMBOL_CARDS_CACHE
    if c["payload"] is None or _t.time() - c["ts"] > _SYMBOL_CARDS_TTL:
        import hashlib as _hl, json as _j

        payload = _symbol_cards_build()
        c["etag"] = 'W/"sc-' + _hl.sha1(_j.dumps(payload, sort_keys=True, default=str).encode()).hexdigest()[:16] + '"'
        c["payload"] = payload
        c["ts"] = _t.time()
    out = dict(c["payload"])  # shallow copy: json_response pops __etag__, must not mutate cache
    out["__etag__"] = c["etag"]
    from lib.cc_symbol_cards import apply_symbol_cards_query

    return apply_symbol_cards_query(out, query)


def _symbol_cards_build():
    """Build the unified card map — ONE map powering the card layer on Watchlist / Open Trades /
    Portfolio (operator 2026-06-12): per symbol -> {description, sector, industry, sector_etf,
    perf_week, sector_perf_week, vs_sector_week, analyst{...}, news[top 3 relevant]}. Read-only."""
    profs = (
        _db_query("""SELECT symbol, description_1s, sector, industry, instrument_type, direction_hint,
                                expense_ratio, analyst_look_through_pct, analyst_basis,
                                next_earnings_date, last_earnings_date, last_eps_estimate, last_eps_actual,
                                last_eps_surprise_pct, last_distribution_date, last_distribution_amount,
                                distribution_cadence, next_distribution_est, ttm_distribution_amount
                         FROM symbol_profiles""")
        or []
    )
    out = {
        p["symbol"]: {
            "description": p["description_1s"],
            "sector": p["sector"],
            "industry": p["industry"],
            "instrument_type": p.get("instrument_type") or "stock",
            "direction_hint": p.get("direction_hint"),
            "expense_ratio": _json_clean(p.get("expense_ratio")),
            "analyst_look_through_pct": _json_clean(p.get("analyst_look_through_pct")),
            "analyst_basis": p.get("analyst_basis"),
            # earnings: next report date + last-quarter beat/miss (stocks only; null for ETFs/funds)
            "earnings": (
                {
                    "next_date": _json_clean(p.get("next_earnings_date")),
                    "last_date": _json_clean(p.get("last_earnings_date")),
                    "eps_estimate": _json_clean(p.get("last_eps_estimate")),
                    "eps_actual": _json_clean(p.get("last_eps_actual")),
                    "surprise_pct": _json_clean(p.get("last_eps_surprise_pct")),
                    "beat": (
                        None if p.get("last_eps_surprise_pct") is None else float(p["last_eps_surprise_pct"]) >= 0
                    ),
                }
                if (p.get("next_earnings_date") or p.get("last_earnings_date"))
                else None
            ),
            # distribution (the fund analog of earnings — dividend/cap-gains payout schedule)
            "distribution": (
                {
                    "next_est": _json_clean(p.get("next_distribution_est")),
                    "last_date": _json_clean(p.get("last_distribution_date")),
                    "last_amount": _json_clean(p.get("last_distribution_amount")),
                    "cadence": p.get("distribution_cadence"),
                    "ttm_amount": _json_clean(p.get("ttm_distribution_amount")),
                }
                if (p.get("next_distribution_est") or p.get("last_distribution_date"))
                else None
            ),
        }
        for p in profs
    }
    syms = list(out.keys())
    if not syms:
        return {"cards": {}, "count": 0}
    # weekly perf for symbol + its sector ETF (ticker_snapshot_daily carries both).
    # yfinance sector names differ from the GICS map keys — alias them.
    _YF_ALIAS = {
        "Financial Services": "Financials",
        "Consumer Cyclical": "Consumer Cyclical",
        "Consumer Defensive": "Consumer Defensive",
        "Basic Materials": "Basic Materials",
    }
    etf_map = {**_SECTOR_ETF_MAP, **{k: _SECTOR_ETF_MAP.get(v) for k, v in _YF_ALIAS.items() if _SECTOR_ETF_MAP.get(v)}}
    snaps = (
        _db_query("""SELECT DISTINCT ON (symbol) symbol, perf_week_pct FROM ticker_snapshot_daily
                         WHERE perf_week_pct IS NOT NULL ORDER BY symbol, snapshot_date DESC""")
        or []
    )
    perf = {s["symbol"]: _json_clean(s["perf_week_pct"]) for s in snaps}
    for sym, c in out.items():
        etf = etf_map.get(c.get("sector") or "", None)
        c["sector_etf"] = etf
        c["perf_week"] = perf.get(sym)
        c["sector_perf_week"] = perf.get(etf) if etf else None
        c["vs_sector_week"] = (
            round(c["perf_week"] - c["sector_perf_week"], 2)
            if c["perf_week"] is not None and c["sector_perf_week"] is not None
            else None
        )
    # On-demand analyst fetch for actionable symbols missing rating/target (proposals + watchlist).
    try:
        import analyst_coverage as _ac

        _prio_rows = (
            _db_query("""
            SELECT DISTINCT upper(symbol) AS symbol FROM (
                SELECT symbol FROM paper_trade_proposals
                 WHERE status IN ('PENDING','APPROVED','MODIFIED') AND symbol IS NOT NULL
                UNION SELECT symbol FROM watchlist_items
                 WHERE status='active' AND symbol IS NOT NULL
            ) u
        """)
            or []
        )
        _prio = [r["symbol"] for r in _prio_rows if r.get("symbol")]
        _need_analyst = [
            s
            for s in _prio
            if s in out
            and not out[s].get("analyst")
            and not _ac.is_analyst_exempt(s, instrument_type=out[s].get("instrument_type"))
        ]
        if _need_analyst:
            _conn = None
            try:
                from session13_db import get_conn as _gc

                _conn = _gc()
                _ac.ensure_analyst_batch(_conn, _need_analyst, limit=20)
            except Exception:
                pass
            finally:
                if _conn:
                    try:
                        _conn.close()
                    except Exception:
                        pass
    except Exception:
        pass
    # analyst consensus (latest per symbol)
    an = (
        _db_query(
            """SELECT DISTINCT ON (symbol) symbol, recommendation_key, recommendation_mean,
                        number_of_analyst_opinions, target_mean_price, target_high_price,
                        target_low_price, current_price FROM yahoo_analyst_targets_history
                      WHERE symbol = ANY(%s) ORDER BY symbol, created_at DESC""",
            (syms,),
        )
        or []
    )
    # AUDITED 2026-06-12: finviz fields system-wide are TARGET-DISTANCE math, NOT a 1-5 rating (the
    # read-model warning was right; a naive cross-compare produced 19 false divergence flags).
    # Yahoo is the ONLY true rating source. The honest second layer = Yahoo's analyst VOTE
    # DISTRIBUTION (strong_buy/buy/hold/sell counts) from analyst_data_history.
    dist = (
        _db_query(
            """SELECT DISTINCT ON (symbol) symbol, payload FROM analyst_data_history
                        WHERE symbol = ANY(%s) ORDER BY symbol, as_of DESC""",
            (syms,),
        )
        or []
    )
    dist_map = {}
    for r in dist:
        p = r["payload"] if isinstance(r["payload"], dict) else {}
        if any(p.get(k) for k in ("strong_buy", "buy", "hold", "sell", "strong_sell")):
            dist_map[r["symbol"]] = {k: p.get(k) for k in ("strong_buy", "buy", "hold", "sell", "strong_sell")}
    for a in an:
        s = a["symbol"]
        if s in out:
            tm, cp = a.get("target_mean_price"), a.get("current_price")
            out[s]["analyst"] = {
                "rating": a.get("recommendation_key"),
                "mean": _json_clean(a.get("recommendation_mean")),
                "opinions": a.get("number_of_analyst_opinions"),
                "target": _json_clean(tm),
                "target_high": _json_clean(a.get("target_high_price")),
                "target_low": _json_clean(a.get("target_low_price")),
                "upside_pct": round((float(tm) - float(cp)) / float(cp) * 100, 1)
                if tm and cp and float(cp) > 0
                else None,
                "distribution": dist_map.get(s),
                "sources": ["yahoo"],
            }
    # ETFs/funds don't get sell-side price targets; expose the holdings LOOK-THROUGH analyst upside as the
    # card's analyst signal so rotation candidates + UI show an analyst view for baskets too.
    for s, c in out.items():
        if (
            c.get("instrument_type") in ("etf", "fund", "inverse_etf")
            and not c.get("analyst")
            and c.get("analyst_look_through_pct") is not None
        ):
            c["analyst"] = {
                "rating": "look-through",
                "upside_pct": c.get("analyst_look_through_pct"),
                "basis": c.get("analyst_basis"),
                "sources": ["holdings_look_through"],
            }
    # top 3 latest relevant news per symbol (relevance-weighted recency)
    news = (
        _db_query(
            """SELECT symbol, title, source, source_url, published_at, sentiment FROM (
                          SELECT symbol, title, source, source_url, published_at, sentiment,
                                 row_number() OVER (PARTITION BY symbol ORDER BY published_at DESC,
                                                    relevance_score DESC NULLS LAST) rn
                          FROM news_articles
                          WHERE symbol = ANY(%s) AND published_at > now() - interval '14 days') n
                        WHERE rn <= 3""",
            (syms,),
        )
        or []
    )
    for n in news:
        s = n["symbol"]
        if s in out:
            out[s].setdefault("news", []).append(
                {
                    "title": n["title"],
                    "source": n["source"],
                    "url": n["source_url"],
                    "at": _json_clean(n["published_at"]),
                    "sentiment": n["sentiment"],
                }
            )
    return _json_clean(
        {
            "cards": out,
            "count": len(out),
            "note": "unified card layer — description/sector/vs-sector/analyst/top-3 news; read-only",
        }
    )


def _portfolio_stop_policy_migration(query=None):
    """GET /api/v2/portfolio/stop-policy-migration — ranked tier-divergence report
    (advisory only). Served from the state file written by stop_policy_migration_report.py
    (daily cron after the 06:45 volatility-tier refresh, or on-demand CLI); a disk read,
    never computed inline (heavy-endpoint rule)."""
    import json as _json
    from pathlib import Path as _P

    p = _P(__file__).resolve().parent.parent / "data" / "state" / "stop_policy_migration_latest.json"
    if not p.exists():
        return {"message": "no report yet — run scripts/stop_policy_migration_report.py"}
    return _json_clean(_json.loads(p.read_text()))


def _portfolio_llm_coverage(query=None):
    """GET /api/v2/portfolio/llm-coverage — per-symbol LLM research provenance (operator request
    2026-06-12: 'LLM name badge so we know which has looked at it'). Sources: hermes internal research
    (gemma local models) + hermes_external_research lanes (grok / chatgpt / claude). Advisory-only
    research; 30-day window; read-only."""
    rows = (
        _db_query("""SELECT symbol, model_used AS model, 'local' AS lane, max(created_at) AS at, count(*) n
                        FROM hermes_research_intelligence
                        WHERE symbol IS NOT NULL AND model_used IS NOT NULL
                          AND created_at > NOW()-INTERVAL '30 days'
                        GROUP BY symbol, model_used""")
        or []
    )
    ext = (
        _db_query("""SELECT symbol, model, lane, max(created_at) AS at, count(*) n
                       FROM hermes_external_research
                       WHERE symbol IS NOT NULL AND status='sent'
                         AND created_at > NOW()-INTERVAL '30 days'
                       GROUP BY symbol, model, lane""")
        or []
    )
    cov: dict = {}
    for r in rows + ext:
        cov.setdefault((r["symbol"] or "").upper(), []).append(
            {"model": r["model"], "lane": r["lane"], "last_at": _json_clean(r["at"]), "n": r["n"]}
        )
    # latest stop/trailing-stop advisory per symbol — STRUCTURED (operator 2026-06-12: numeric
    # stop/trail fields so an approved advisory can later become a draft OrderIntent -> Schwab at L4,
    # with live distance-to-stop monitoring meanwhile)
    prot = (
        _db_query("""SELECT DISTINCT ON (symbol) symbol, thesis, summary, model_used, confidence_score,
                          evidence_json, created_at FROM hermes_research_intelligence
                        WHERE research_type='protection_advisory' AND created_at > NOW()-INTERVAL '30 days'
                        ORDER BY symbol, created_at DESC""")
        or []
    )
    quotes = (
        {
            r["symbol"]: r
            for r in (
                _db_query(
                    """SELECT DISTINCT ON (symbol) symbol, price FROM market_quotes
           WHERE symbol = ANY(%s) ORDER BY symbol, fetched_at DESC""",
                    ([p["symbol"] for p in prot],),
                )
                or []
            )
        }
        if prot
        else {}
    )
    protection = {}
    for p in prot:
        sym = (p["symbol"] or "").upper()
        ev = p.get("evidence_json") or {}
        ev = ev if isinstance(ev, dict) else {}
        rec = ev.get("recommendation") or {}
        px = quotes.get(sym, {}).get("price") or (ev.get("inputs") or {}).get("price")
        stop = rec.get("stop_price")
        dist = round((float(px) - float(stop)) / float(px) * 100, 2) if px and stop and float(px) > 0 else None
        trail_rec = bool(rec.get("trail_recommended"))
        trail_off = rec.get("trail_offset")
        suggested_trail = None
        trail_matches_stop = False
        if trail_rec and trail_off is not None:
            suggested_trail = float(trail_off) if rec.get("trail_type") == "PERCENT" else None
        elif dist is not None and float(dist) >= 3:
            suggested_trail = round(float(dist), 1)
            trail_matches_stop = not trail_rec
        _fb = ev.get("family_bounds") if isinstance(ev.get("family_bounds"), dict) else {}
        _floor_pct = _fb.get("stop_min_pct")
        _fam = ev.get("family") or ""
        _pep = _evidence_packet(rec if isinstance(rec, dict) else ev)
        protection[sym] = {
            "rec": p["thesis"],
            "rationale": p["summary"],
            "model": p["model_used"],
            "confidence": _json_clean(p["confidence_score"]),
            "at": _json_clean(p["created_at"]),
            "stop_price": stop,
            "trail_recommended": trail_rec,
            "trail_type": rec.get("trail_type"),
            "trail_offset": trail_off,
            "suggested_trail_pct": suggested_trail,
            "trail_matches_stop": trail_matches_stop,
            "price": _json_clean(px),
            "stop_distance_pct": dist,
            "sanity": ev.get("sanity"),  # advisory self-consistency verdict + issues
            "family": _fam,
            "family_source": ev.get("family_source"),
            "family_bounds": _fb,
            "volatility_tier": ev.get("volatility_tier"),
            "regime": (ev.get("regime") or {}).get("posture")
            if isinstance(ev.get("regime"), dict)
            else ev.get("regime"),
            "regime_adjustment_pct": _fb.get("regime_adjustment_pct"),
            "family_floor_pct": _floor_pct,
            "family_floor": (f"{_fam} floor {_floor_pct}%" if _floor_pct is not None else _fam) or None,
            "evidence": _pep.get("evidence") or [],
            "data_i_doubt": _pep.get("data_i_doubt"),
        }
    # Held symbols with no 30-day LLM advisory still need a suggested Stop $ in the 2FA form.
    try:
        for _h in (portfolio_holdings() or {}).get("holdings") or []:
            _s = str(_h.get("symbol") or "").upper()
            if not _s or (protection.get(_s) or {}).get("stop_price") is not None:
                continue
            _px = _f_or_none(_h.get("current_price")) or _f_or_none(_h.get("price"))
            _pol = _live_policy_stop(_s, _px)
            if not _pol:
                continue
            protection[_s] = {
                "rec": f"policy floor ${_pol['stop']}",
                "rationale": _pol["rationale"],
                "model": _pol["rec_model"],
                "confidence": None,
                "at": None,
                "stop_price": _pol["stop"],
                "trail_recommended": False,
                "trail_type": None,
                "trail_offset": None,
                "suggested_trail_pct": None,
                "trail_matches_stop": False,
                "price": _json_clean(_px),
                "stop_distance_pct": _pol["stop_pct_below"],
                "sanity": {"verdict": "policy", "issues": ["no recent LLM advisory"]},
                "family": _pol["family"],
                "family_source": _pol["family_source"],
                "family_bounds": {},
                "volatility_tier": None,
                "regime": None,
                "family_floor_pct": _pol["family_floor_pct"],
                "family_floor": _pol["family_floor"],
                "evidence": _pol["evidence"],
                "data_i_doubt": _pol["data_i_doubt"],
            }
    except Exception:
        pass
    # monthly Claude arbitration verdicts (structured) — the tie-breaker layer for future approval flow
    cv = (
        _db_query("""SELECT DISTINCT ON (symbol) symbol, recommendation, evidence_json, model, created_at
                      FROM hermes_external_research
                      WHERE lane='claude' AND trigger_reason='monthly_protection_meta_review'
                      ORDER BY symbol, created_at DESC""")
        or []
    )
    claude_verdicts = {
        (r["symbol"] or "").upper(): {
            "verdict": r["recommendation"],
            "model": r["model"],
            "at": _json_clean(r["created_at"]),
            **{
                k: (r["evidence_json"] or {}).get(k)
                for k in ("verdict_stop", "verdict_trail_type", "verdict_trail_offset", "agrees_with", "note")
                if isinstance(r.get("evidence_json"), dict)
            },
        }
        for r in cv
    }
    stop_curation_map = {}
    try:
        for _sc in (
            _db_query(
                "SELECT DISTINCT ON (symbol) symbol, evidence_json, model_used, summary "
                "FROM hermes_research_intelligence "
                "WHERE research_type='stop_curation' AND created_at > NOW()-INTERVAL '30 days' "
                "ORDER BY symbol, created_at DESC"
            )
            or []
        ):
            _sym = (_sc.get("symbol") or "").upper()
            _ev = _sc.get("evidence_json")
            _ev = _ev if isinstance(_ev, dict) else json.loads(_ev or "{}")
            _sep = _evidence_packet(_ev)
            stop_curation_map[_sym] = {
                "grade": _ev.get("grade"),
                "recommendation": _ev.get("recommendation"),
                "rr_assessment": _ev.get("rr_assessment"),
                "suggested_action": _ev.get("suggested_action"),
                "model": _sc.get("model_used"),
                "summary": (_sc.get("summary") or "")[:200],
                "evidence": _sep.get("evidence") or [],
                "data_i_doubt": _sep.get("data_i_doubt"),
            }
    except Exception:
        pass
    # Operator-confirmed live stops (Fidelity manual orders, etc.) — SnapTrade read-only cannot see orders.
    conf_rows = (
        _db_query("""SELECT symbol, account, stop_confirmed, stop_price_confirmed,
                                    stop_confirmed_at, stop_exception_reason
                             FROM stop_confirmations WHERE stop_confirmed = true""")
        or []
    )
    confirmed_stops = {}
    for cr in conf_rows:
        sym = (cr.get("symbol") or "").upper()
        acct = str(cr.get("account") or "")
        sp = float(cr["stop_price_confirmed"]) if cr.get("stop_price_confirmed") else None
        confirmed_stops[f"{sym}:{acct}"] = {
            "symbol": sym,
            "account": acct,
            "stop_price": sp,
            "source": "confirmed",
            "confirmed_at": _json_clean(cr.get("stop_confirmed_at")),
            "note": (cr.get("stop_exception_reason") or "")[:200] or None,
        }
    # Overlay live Schwab broker protective stops (API source of truth). Trailing orders often have
    # stop_price=null — trail_offset + order_type carry the live protection state for the UI.
    _broker_fetched_at = None
    try:
        import open_trades_intelligence as _oti

        _holdings = _load_json(STATE_DIR / "holdings.json") or {}
        _acct_labels = {}
        _broker_accts = []
        for _h in _holdings.get("holdings", []):
            _raw = str(_h.get("account") or "")
            if not _raw:
                continue
            _canon = _resolve_protective_account_key(_raw)
            _acct_labels[_oti._norm_acct(_canon)] = _raw
            _acct_labels[_oti._norm_acct(_raw)] = _raw
            _broker_accts.append(_canon)
        for (_acct_norm, _sym), _bs in (_oti._broker_protective_stops(sorted(set(_broker_accts))) or {}).items():
            _hold_acct = _acct_labels.get(_acct_norm) or str(_bs.get("account") or _acct_norm)
            if not str(_hold_acct).startswith("schwab"):
                continue
            _key = f"{_sym}:{_hold_acct}"
            _otype = str(_bs.get("order_type") or "").upper()
            confirmed_stops[_key] = {
                "symbol": _sym,
                "account": _hold_acct,
                "stop_price": _bs.get("stop_price"),
                "trail_offset": _bs.get("trail_offset"),
                "trail_link": _bs.get("trail_link"),
                "order_type": _bs.get("order_type"),
                "order_id": _bs.get("order_id"),
                "source": "broker",
                "broker_verified": True,
                "fetched_at": _bs.get("fetched_at") or _oti.broker_stops_fetched_at(),
                "note": f"Live {_otype.replace('_', ' ').lower()} order {_bs.get('order_id') or ''}".strip(),
            }
        _broker_fetched_at = _oti.broker_stops_fetched_at()
    except Exception:
        pass
    try:
        _read_ok = sorted(_oti.broker_stop_read_ok())
    except Exception:
        _read_ok = []
    return _json_clean(
        {
            "coverage": cov,
            "protection": protection,
            "stop_curation": stop_curation_map,
            "claude_verdicts": claude_verdicts,
            "confirmed_stops": confirmed_stops,
            "broker_stops_fetched_at": _broker_fetched_at,
            # accounts whose live-stop broker read SUCCEEDED on the last fetch. An account
            # missing here (e.g. Schwab orders lane degraded: no login token) means its
            # live-stop state is UNVERIFIABLE — the UI must not render 'none' for it.
            "broker_stop_read_ok_accounts": _read_ok,
            "window_days": 30,
            "note": "advisory research provenance — structured stop/trail fields + live "
            "distance-to-stop; confirmed_stops = operator-verified broker stops "
            "(Fidelity manual / no API order feed) + live Schwab API protective orders",
        }
    )


