_SCHWAB_LIVE_CACHE: dict = {}  # accounts-live 30s cache — the monitor UI must never hammer the API
_PROPOSAL_ACCOUNTS_CACHE: dict = {}  # proposal-accounts 30s cache


def _infer_account_type(account_key: str, summ: dict | None = None) -> str:
    low = (account_key or "").lower()
    if summ and summ.get("display_name"):
        dn = str(summ["display_name"])
        if "401" in dn:
            return "401k"
        if "Rollover" in dn or "rollover" in low:
            return "Rollover IRA"
        if "Roth" in dn or "roth" in low:
            return "Roth IRA"
        if "Taxable" in dn or "Individual" in dn or "taxable" in low:
            return "Taxable"
    if "401k" in low:
        return "401k"
    if "rollover" in low:
        return "Rollover IRA"
    if "roth" in low:
        return "Roth IRA"
    if "taxable" in low:
        return "Taxable"
    if low.startswith("fidelity"):
        return "Fidelity"
    if low.startswith("schwab"):
        return "Schwab"
    return "Brokerage"


def _proposal_accounts(query=None):
    """GET /api/v2/proposal-accounts — Schwab + Fidelity destinations with equity/cash for propose modal."""
    import time as _t

    hit = _PROPOSAL_ACCOUNTS_CACHE.get("proposal_accounts")
    if hit and _t.time() - hit[0] < 30:
        return hit[1]

    import account_policy as ap

    rows = (
        _db_query("""
        SELECT account_key, display_name, broker, environment
        FROM broker_accounts
        WHERE broker ILIKE '%%schwab%%' OR broker ILIKE '%%fidelity%%'
        ORDER BY (broker ILIKE '%%fidelity%%') DESC, account_key""")
        or []
    )

    h = _load_json(STATE_DIR / "holdings.json") or {}
    summaries = h.get("account_summaries") or {}
    seen = {r.get("account_key") for r in rows}
    _HOLDINGS_ALIAS_SKIP = {"schwab_roth"}  # broker_accounts uses schwab_roth_ira; avoid duplicate row
    for ak, summ in summaries.items():
        if ak in seen or ak == "fidelity_401k" or ak in _HOLDINGS_ALIAS_SKIP:
            continue
        broker = summ.get("broker") or ("fidelity" if ak.startswith("fidelity") else "schwab")
        if not (str(broker).lower().startswith("fidelity") or str(broker).lower().startswith("schwab")):
            continue
        rows.append(
            {
                "account_key": ak,
                "display_name": summ.get("display_name"),
                "broker": broker,
                "environment": "live",
            }
        )
        seen.add(ak)

    schwab_live: dict = {}
    try:
        live_payload = _schwab_accounts_live()
        for a in live_payload.get("accounts") or []:
            schwab_live[a.get("account_key")] = a
    except Exception:
        pass

    accounts = []
    for r in rows:
        ak = r.get("account_key") or ""
        if not ak or ak == "fidelity_401k":
            continue

        equity, eq_src = ap.equity_for_account(ak)
        sizing_base, _, sizing_src = ap.sizing_cash_base(ak)
        cash_only, cash_only_src = ap.cash_for_account(ak)
        bp, bp_src = ap.buying_power_for_account(ak)

        live = schwab_live.get(ak) or {}
        if live.get("balances_status") == "ok":
            if live.get("account_value") is not None:
                equity = float(live["account_value"])
                eq_src = "schwab_live"
            if live.get("cash") is not None:
                cash_only = float(live["cash"])
                cash_only_src = "schwab_live"
            if live.get("buying_power") is not None:
                bp = float(live["buying_power"])
                bp_src = "schwab_live"

        summ = summaries.get(ak) or {}
        display = r.get("display_name") or summ.get("display_name") or ak.replace("_", " ").title()
        acct_type = _infer_account_type(ak, summ)
        is_ret = ap.is_retirement_account(ak)

        if sizing_base is None and cash_only and cash_only > 0:
            sizing_base = cash_only
            sizing_src = cash_only_src
        if sizing_base is None and bp and bp > 0 and not is_ret:
            sizing_base = bp
            sizing_src = bp_src

        accounts.append(
            {
                "account_key": ak,
                "display_name": display,
                "broker": r.get("broker"),
                "account_type": acct_type,
                "is_retirement": is_ret,
                "account_value": round(equity, 2) if equity else None,
                "equity_source": eq_src,
                "cash": round(cash_only, 2) if cash_only else None,
                "buying_power": round(bp, 2) if bp else None,
                "sizing_base": round(sizing_base, 2) if sizing_base else None,
                "sizing_base_label": "cash" if is_ret or (cash_only and cash_only > 0) else "buying_power",
                "cash_source": sizing_src,
                "balances_status": live.get("balances_status") or ("ok" if sizing_base else "unavailable"),
                "sizing_ready": bool(sizing_base and sizing_base > 0),
                # Per-account position cap — the SAME number the backend generator/risk-gate enforce.
                # UNITS MATTER (bug caught live 2026-07-03): max_position_allocation_pct is a percent
                # of EQUITY in compute_sizing, not of cash — applying 3% to cash capped every card at
                # ~$6.6k instead of the intended ~3% of account equity. Named accordingly.
                "max_position_pct_of_equity": (ap.load_policy(ak) or {}).get("max_position_allocation_pct") or None,
            }
        )

    accounts.sort(
        key=lambda a: (
            0 if a.get("sizing_ready") else 1,
            0 if str(a.get("broker") or "").lower().startswith("fidelity") else 1,
            -(a.get("sizing_base") or 0),
        )
    )

    # Desk sizing policy (operator-tunable via env, no hardcoded values in the UI):
    # max_deploy_pct_of_cash caps capital DEPLOYED per position as % of available cash —
    # complements the 2% max-RISK cap (risk = loss-if-stopped; deployment = risk ÷ stop%).
    try:
        _max_deploy = float(os.environ.get("MAX_DEPLOY_PCT_OF_CASH", "20"))
    except (TypeError, ValueError):
        _max_deploy = 20.0
    out = _json_clean(
        {
            "accounts": accounts,
            "sizing_policy": {"max_deploy_pct_of_cash": _max_deploy, "max_risk_pct": 2},
            "note": "Risk sizing uses sizing_base (cash/buying power), not total equity. Retirement accounts are cash-only.",
            "cached_seconds": 30,
        }
    )
    _PROPOSAL_ACCOUNTS_CACHE["proposal_accounts"] = (_t.time(), out)
    return out


def _schwab_accounts_live(query=None):
    """GET /api/v2/schwab/accounts-live — READ-ONLY positions + orders from periodic caches.

    Served from holdings.json (positions + balances, refreshed every 15 min by schwab_position_sync.py)
    and schwab_activity_log (orders, captured by schwab_activity_capture.py). Eliminates live
    Schwab API calls that block the single-threaded server.

    TODO: For truly live (sub-15-min) positions/orders/balances, restore the schwab_transport live API
    calls. The current implementation reads from periodic caches refreshed on the same schedule as the
    existing ingest pipeline."""
    import time as _t

    hit = _SCHWAB_LIVE_CACHE.get("accounts_live")
    if hit and _t.time() - hit[0] < 120:
        return hit[1]

    # ── account key aliases: holdings.json uses short names, broker_accounts uses canonical ──
    _ACCT_ALIASES = {
        "schwab_roth": "schwab_roth_ira",
        "schwab_rollover": "schwab_rollover_ira",
        "schwab_roth_ira": "schwab_roth",
        "schwab_rollover_ira": "schwab_rollover",
    }

    def _resolve(ak, aliases=None):
        """Map an account key to both short and long forms."""
        t = aliases or _ACCT_ALIASES
        return t.get((ak or "").strip().lower(), (ak or "").strip().lower())

    # ── positions + balances from holdings.json (15-min refresh) ──────────────
    holdings_data = _load_json(STATE_DIR / "holdings.json") or {}
    holdings = holdings_data.get("holdings") or []

    # ── recent orders from schwab_activity_log (captured by activity_capture) ──
    activity_rows = (
        _db_query(
            """SELECT account_key, broker_order_id, symbol, status, kind, event_time, captured_at
           FROM schwab_activity_log WHERE captured_at > NOW() - INTERVAL '24 hours'
           ORDER BY captured_at DESC LIMIT 500"""
        )
        or []
    )

    sdbr_rows = (
        _db_query("SELECT account_key FROM broker_accounts WHERE broker ILIKE '%schwab%' ORDER BY account_key") or []
    )

    accounts = []
    for r in sdbr_rows:
        ak_canonical = str(r["account_key"])
        ak_short = _resolve(ak_canonical)

        # ── positions: filter holdings.json for this account ──
        pos = []
        for h in holdings:
            ha = str(h.get("account") or "").strip().lower()
            if ha in (ak_canonical.lower(), ak_short.lower(), _resolve(ak_short)):
                if h.get("is_cash") or h.get("is_loan"):
                    continue
                pos.append(
                    {
                        "symbol": str(h.get("symbol") or "").upper(),
                        "qty": h.get("shares"),
                        "avg_price": h.get("avg_cost") or h.get("cost_basis"),
                        "market_value": h.get("market_value"),
                        "current_price": h.get("current_price") or h.get("price"),
                        "day_change": h.get("day_change"),
                    }
                )

        # ── balances: cash rows from holdings.json ──
        cash = buying_power = account_value = None
        balances_status = "unavailable"
        for h in holdings:
            ha = str(h.get("account") or "").strip().lower()
            if ha in (ak_canonical.lower(), ak_short.lower(), _resolve(ak_short)):
                if h.get("is_cash"):
                    cash = h.get("market_value") or h.get("shares")
                    buying_power = h.get("buying_power")  # may be present
                    account_value = h.get("account_value")
                    balances_status = "ok"
                    break

        # ── orders: recent activity for this account and its alias ──
        orders = []
        for ar in activity_rows:
            aa = str(ar.get("account_key") or "").strip().lower()
            if aa in (ak_canonical.lower(), ak_short.lower(), _resolve(ak_short)):
                orders.append(
                    {
                        "order_id": str(ar.get("broker_order_id") or ""),
                        "status": ar.get("status"),
                        "symbol": str(ar.get("symbol") or "").upper(),
                        "kind": ar.get("kind"),
                        "entered_time": ar.get("event_time"),
                        "captured_at": ar.get("captured_at"),
                    }
                )

        accounts.append(
            {
                "account_key": ak_canonical,
                "positions": pos,
                "positions_status": "ok" if pos else "empty",
                "orders": orders,
                "orders_status": "ok" if activity_rows else "empty",
                "cash": cash,
                "buying_power": buying_power,
                "account_value": account_value,
                "balances_status": balances_status,
            }
        )

    out = _json_clean(
        {
            "accounts": accounts,
            "read_only": True,
            "cached_seconds": 120,
            "source": "holdings_json+schwab_activity_log",
            "note": "READ-ONLY monitor — served from periodic caches (holdings.json + "
            "schwab_activity_log) refreshed every 15 min. Not real-time. "
            "'Edit' on this surface produces a DRAFT modification (preview/translate) "
            "— it NEVER modifies a live order via API.",
        }
    )
    _SCHWAB_LIVE_CACHE["accounts_live"] = (_t.time(), out)
    return out


def _pilot_status(query=None):
    """GET /api/v2/broker-orders/pilot/status — Stage 2b pilot locks/envelope/counter + recent orders.
    Read-only; mirrors schwab_pilot_arm.py --status for the console."""
    import schwab_pilot_arm as arm

    st = arm.status()
    rows = (
        _db_query("""SELECT id, correlation_id, intent_id, account_key, symbol, side, qty, limit_price,
                          status, broker_order_id, detail, created_at, updated_at
                        FROM schwab_pilot_orders ORDER BY id DESC LIMIT 20""")
        or []
    )
    # Reconcile against the broker (source of truth): the local status is captured at SUBMIT time and
    # never reflected a later cancel/fill made in ToS. For rows still in a non-terminal local status that
    # carry a broker_order_id, read Schwab's live order status (best-effort, fail-open) and overlay it as
    # `live_status` — and persist it back so a terminal status sticks without re-polling. (2026-06-15)
    _TERMINAL = {"canceled", "cancelled", "filled", "rejected", "expired", "replaced"}
    _pending = [r for r in rows if r.get("broker_order_id") and str(r.get("status") or "").lower() not in _TERMINAL]
    if _pending:
        try:
            import sys as _sys

            _sys.path.insert(0, str(Path(__file__).resolve().parent))
            import schwab_transport as _st

            accts = {r.get("account_key") for r in _pending if r.get("account_key")} or {"schwab_taxable"}
            live = {}
            for ak in accts:
                raw = _st.get_orders_raw(ak)
                if isinstance(raw, dict) and raw.get("status") in ("NOT_PROVEN", "degraded", "error"):
                    continue
                for o in _st.normalize_orders(raw) or []:
                    oid = o.get("id") or o.get("orderId") or o.get("broker_order_id")
                    if oid is not None and o.get("status"):
                        live[str(oid)] = str(o["status"]).lower()
            for r in rows:
                ls = live.get(str(r.get("broker_order_id") or ""))
                if ls:
                    r["live_status"] = ls
                    if ls != str(r.get("status") or "").lower():
                        try:
                            _db_write(
                                "UPDATE schwab_pilot_orders SET status=%s, updated_at=NOW() WHERE id=%s", (ls, r["id"])
                            )
                            r["status"] = ls
                        except Exception:
                            pass
        except Exception:
            pass  # fail-open: keep the local submit-time status if the broker read is unavailable
    # active 2FA slot (one order at a time)
    slot = (
        _db_query("""SELECT DISTINCT intent_id FROM trade_approvals
                        WHERE status IN ('pending','confirmed') AND expires_at > NOW()""")
        or []
    )
    return _json_clean({**st, "pilot_orders": rows, "active_approval_intents": [r["intent_id"] for r in slot]})


def _pilot_preflight(body=None):
    """POST /api/v2/broker-orders/pilot/preflight — full Stage 2b preflight (envelope, canonical model,
    canary gate, token health, account hash, live quote/spread) + saves the intent DRAFT so the existing
    2FA request-approval/approve routes work on it. NO order I/O."""
    import schwab_stage2b_canary_preflight as pf
    from brokers import audit as br_audit
    from brokers.pilot_caps import PILOT_ACCOUNT_ALLOWLIST

    b = body or {}
    shape = b.get("shape")
    if shape:
        return _pilot_preflight_battery(b)
    try:
        plan = pf.make_plan(
            str(b.get("account_key") or PILOT_ACCOUNT_ALLOWLIST[0]),
            str(b.get("symbol") or ""),
            b.get("qty") or 0,
            str(b.get("limit_price") or "0"),
        )
        checks = {}
        checks["model_and_gate"] = pf.require_model_and_gate(plan)
        checks["token_health"] = pf.require_token_health(plan.account_key)
        pf.require_account_hash(plan.account_key)
        checks["live_quote"] = pf.require_live_quote(plan, pf.DEFAULT_MAX_SPREAD_PCT)
        intent = pf.make_order_intent(plan)
        spec = pf.make_order_spec(plan)
        br_audit.save_intent(
            intent,
            validation={"stage2b_preflight": "passed", **checks},
            translation={"order_spec": spec},
            state="PREVIEWED",
        )
        pf.write_audit("api_preflight", plan, {"checks": checks, "order_spec": spec})
        return _json_clean(
            {
                "ok": True,
                "intent_id": intent.intent_id,
                "correlation_id": plan.correlation_id,
                "order_spec": spec,
                "checks": checks,
                "operator_phrase": plan.operator_phrase,
                "next": "POST /api/v2/broker-orders/request-approval {intent_id} → confirm web "
                "(type ticker) + telegram (button/code) → POST pilot/execute",
            }
        )
    except pf.CanaryAbort as e:
        return _json_clean({"ok": False, "blocked": True, "reason": str(e)})
    except Exception as e:
        return _json_clean({"ok": False, "error": str(e)[:200]})


def _pilot_preflight_battery(b):
    """Battery-shape preflight (Monday 2026-06-15): BUY/SELL LIMIT, SELL STOP, SELL TRAILING_STOP at
    qty≤10. Validates through the SAME stack — canonical model + canary gate (now bounds every
    committed price) + token health + account hash + live quote. Saves the draft for 2FA."""
    import schwab_stage2b_canary_preflight as pf
    from brokers import audit as br_audit, canary_gate as cg
    from brokers.order_intent import validate as oi_validate
    from brokers.pilot_caps import PILOT_ACCOUNT_ALLOWLIST
    from decimal import Decimal

    try:
        acct = str(b.get("account_key") or PILOT_ACCOUNT_ALLOWLIST[0])
        sym = pf._clean_symbol(str(b.get("symbol") or ""))
        qty = int(b.get("qty") or 0)
        shape = str(b.get("shape"))
        if shape not in pf.BATTERY_SHAPES:
            return _json_clean({"ok": False, "blocked": True, "reason": f"unknown shape {shape!r}"})
        D = lambda v: Decimal(str(v)) if v not in (None, "", "0") else None
        price, stop_price, trail_pct = D(b.get("price")), D(b.get("stop_price")), D(b.get("trail_pct"))
        # live quote — also the reference bound for trailing; verify ref ≤ $4 + spread sane
        import schwab_transport as _st

        qres = _st.get_quotes([sym])
        q = (qres.get("quotes") or {}).get(sym) if isinstance(qres, dict) else None
        if not q:
            return _json_clean({"ok": False, "blocked": True, "reason": f"no live quote for {sym}"})
        bid, ask, last = q.get("bid"), q.get("ask"), q.get("last")
        ref = Decimal(str(ask or last or bid or "0"))
        if ref <= 0 or ref > pf.STAGE2B_MAX_PRICE_USD:
            return _json_clean(
                {
                    "ok": False,
                    "blocked": True,
                    "reason": f"{sym} live ref ${ref} not in (0, ${pf.STAGE2B_MAX_PRICE_USD}]",
                }
            )
        spec = pf.make_battery_spec(sym, qty, shape, price=price, stop_price=stop_price, trail_pct=trail_pct)
        intent = pf.make_battery_intent(
            acct, sym, qty, shape, price=price, stop_price=stop_price, trail_pct=trail_pct, reference_price=ref
        )
        vr = oi_validate(intent)
        if not vr.ok:
            return _json_clean({"ok": False, "blocked": True, "reason": f"canonical validation: {vr.errors}"})
        gd = cg.evaluate(intent)
        if not gd.allowed:
            return _json_clean({"ok": False, "blocked": True, "reason": "CANARY_GATE BLOCK: " + "; ".join(gd.reasons)})
        pf.require_account_hash(acct)
        th = pf.require_token_health(acct)
        br_audit.save_intent(
            intent,
            validation={"stage2b_battery": shape, "token_health": th},
            translation={"order_spec": spec},
            state="PREVIEWED",
        )
        phrase = f"OPERATOR CONFIRMS SCHWAB CANARY {shape.upper()} {sym} {qty}"
        return _json_clean(
            {
                "ok": True,
                "intent_id": intent.intent_id,
                "shape": shape,
                "order_spec": spec,
                "operator_phrase": phrase,
                "checks": {"live_quote": {"bid": bid, "ask": ask, "last": last}, "token_health": th},
                "next": "request-approval → 2FA (web+telegram) → pilot/execute",
            }
        )
    except pf.CanaryAbort as e:
        return _json_clean({"ok": False, "blocked": True, "reason": str(e)})
    except Exception as e:
        return _json_clean({"ok": False, "error": str(e)[:200]})


def _pilot_execute(body=None):
    """POST /api/v2/broker-orders/pilot/execute {intent_id} — the ONLY caller of the transport write
    surface. Re-runs nothing itself: the transport enforces the entire stack (taxable-only assert,
    api_write_enabled, canary gate, standing locks, pilot cap, 2FA) and fails closed."""
    from brokers import audit as br_audit
    from brokers.order_intent import OrderIntent
    import schwab_transport as st

    b = body or {}
    iid = str(b.get("intent_id") or "")
    rows = [r for r in br_audit.load_drafts("schwab", 200) if r["intent_id"] == iid]
    if not rows:
        return _json_clean({"ok": False, "error": "unknown intent_id (run pilot/preflight first)"})
    row = rows[0]
    intent = OrderIntent.from_dict(row["intent_json"])
    spec = (row.get("translation_json") or {}).get("order_spec")
    if not spec:
        return _json_clean({"ok": False, "error": "intent has no preflighted order_spec — re-run preflight"})
    try:
        res = st.place_order(intent.account_key, spec, intent)
    except st.NotProvenWrite as e:
        return _json_clean({"ok": False, "blocked": True, "reason": str(e)})
    except Exception as e:
        # ExecutionBlocked (guard deny) and anything else — honest reason, nothing submitted
        return _json_clean({"ok": False, "blocked": True, "reason": str(e)[:240]})
    br_audit.save_intent(
        intent,
        translation={"order_spec": spec, "submit_result": res},
        state="SUBMITTED" if res.get("status") == "submitted" else "BLOCKED",
        blocked_reason=None if res.get("status") == "submitted" else str(res)[:200],
    )
    return _json_clean({"ok": res.get("status") == "submitted", **res})


def _pilot_arm(body=None):
    """POST /api/v2/broker-orders/pilot/arm {confirm} — UI arming (operator 2026-06-13: zero-shell).
    Validates the date-specific typed phrase and opens an AUTO-EXPIRING armed session (no env flag /
    restart). Per-order Telegram 2FA still gates every submit — arming alone places nothing."""
    import schwab_pilot_arm as arm

    r = arm.arm(str((body or {}).get("confirm") or ""))
    return _json_clean(r if r.get("ok") else {"ok": False, "error": r.get("error", "arm failed")})


