def _pilot_cancel(body=None):
    """POST /api/v2/broker-orders/pilot/cancel {broker_order_id} — cancel a PILOT order (safe direction)."""
    import schwab_transport as st
    from brokers.pilot_caps import PILOT_ACCOUNT_ALLOWLIST

    b = body or {}
    oid = str(b.get("broker_order_id") or "")
    if not oid:
        return _json_clean({"ok": False, "error": "broker_order_id required"})
    try:
        acct = str(b.get("account_key") or b.get("account") or "").strip()
        if acct not in PILOT_ACCOUNT_ALLOWLIST:
            return _json_clean(
                {"ok": False, "error": f"account_key required and must be in {list(PILOT_ACCOUNT_ALLOWLIST)}"}
            )
        res = st.cancel_order(acct, oid)
    except Exception as e:
        return _json_clean({"ok": False, "blocked": True, "reason": str(e)[:240]})
    return _json_clean({"ok": res.get("status") == "cancel_requested", **res})


def _broker_orders_suggest_levels(query=None):
    """GET /api/v2/broker-orders/suggest-levels?symbol=X — READ-ONLY advisory entry/stop/target from
    technicals (ATR-buffered stop below structure, limit near support/last, target vs recent range +
    analyst mean). Reuses watchlist_entry_planner._bars/_tech/_analyst. Never places anything."""
    q = query or {}
    sym = (
        ((q.get("symbol") or [""])[0] if isinstance(q.get("symbol"), list) else (q.get("symbol") or "")).strip().upper()
    )
    if not sym:
        return {"error": "symbol required"}
    try:
        import watchlist_entry_planner as wep

        bars = wep._bars(sym)
        if not bars:
            return {"error": f"no price history for {sym}"}
        t = wep._tech(bars)
        price = float(t["price"])
        atr = float(t["atr"])
        swing_low = float(t["swing_low"])
        swing_high = float(t["swing_high"])
        sma50 = float(t["sma50"])
        # analyst mean target (numeric) for the upside ceiling
        from db_adapter import _get_conn

        cur = _get_conn().cursor()
        an = wep._analyst(cur, sym)
        tgt_mean = an.get("tgt_mean_num")
        # ENTRY: just under the last print / nearest support (rising SMA50 if price is above it),
        # so a limit has a realistic fill instead of chasing.
        support = max([v for v in (sma50, swing_low) if v < price] or [price * 0.985])
        limit = round(min(price, (price + support) / 2 if support < price else price), 2)
        # STOP: 1.5x ATR below the chosen entry, but never above structural support − a tick.
        stop = round(min(limit - 1.5 * atr, support - 0.01), 2)
        if stop >= limit:
            stop = round(limit - max(1.5 * atr, limit * 0.02), 2)
        # TARGET: prefer analyst mean if it gives >=1.5R; else recent swing high; else 2R.
        r_per_share = limit - stop
        cand = []
        if tgt_mean and tgt_mean > limit:
            cand.append(float(tgt_mean))
        if swing_high > limit:
            cand.append(swing_high)
        cand.append(limit + 2 * r_per_share)
        target = round(next((c for c in cand if (c - limit) / r_per_share >= 1.5), max(cand)), 2)
        rr = round((target - limit) / r_per_share, 2) if r_per_share > 0 else None
        stop_pct = round((stop - limit) / limit * 100, 2)
        rationale = (
            f"ATR ${atr:.2f} ({atr / price * 100:.1f}%) · entry near "
            f"{'SMA50' if abs(support - sma50) < abs(support - swing_low) else '20d-low'} support "
            f"${support:.2f} · stop 1.5×ATR below structure"
            + (
                f" · target = analyst mean ${tgt_mean:.2f}"
                if tgt_mean and target == round(float(tgt_mean), 2)
                else " · target = 20d-high/2R"
            )
        )
        return _json_clean(
            {
                "symbol": sym,
                "price": round(price, 2),
                "atr": round(atr, 2),
                "limit": limit,
                "stop": stop,
                "stop_pct": stop_pct,
                "target": target,
                "rr": rr,
                "swing_low": round(swing_low, 2),
                "swing_high": round(swing_high, 2),
                "sma50": round(sma50, 2),
                "rsi": t["rsi"],
                "analyst_mean": tgt_mean,
                "rationale": rationale,
                "note": "advisory technical levels — read-only; fills the draft fields, never sends",
            }
        )
    except Exception as e:
        return {"error": str(e)[:160]}


def _broker_orders_explain(body=None):
    """POST /api/v2/broker-orders/explain — ADVISORY-ONLY AI helper for the ToS-style order panel.
    Explains order-type/field MECHANICS and how the canonical intent translates to Schwab. It can
    never submit/approve (pure text; no DB writes) and never gives security-selection advice.
    Routing: governed DeepSeek by default; Claude only on explicit operator escalation."""
    b = body or {}
    topic = str(b.get("topic") or "order basics")[:120]
    question = str(b.get("question") or "")[:600]
    intent = b.get("intent") if isinstance(b.get("intent"), dict) else None
    escalate = bool(b.get("escalate"))
    prompt = (
        "You are an order-mechanics tutor inside a trading dashboard. STRICT RULES: explain ONLY the "
        "mechanics of order types, fields, and how our canonical order intent translates to Schwab's "
        "order payload (session, duration, orderType, orderStrategyType TRIGGER/OCO, "
        "orderLegCollection, stopPriceLink*). You must NEVER recommend what to trade, never evaluate "
        "whether a ticker/price is a good idea, never predict markets. If asked for trade advice, "
        "reply exactly: 'I only explain order mechanics — what to trade is the operator's decision.' "
        "Be concise (<=180 words), plain English.\n\n"
        f"Topic: {topic}\n"
        + (f"Operator question: {question}\n" if question else "")
        + (f"Current draft intent (context only): {json.dumps(intent)[:1200]}\n" if intent else "")
    )
    try:
        if escalate:
            from local_llm import _try_anthropic

            text = _try_anthropic(prompt)
            provider = "anthropic (explicit operator escalation)"
        else:
            import llm_lane

            text = llm_lane.generate(prompt, lane="deepseek-flash", timeout=60, process_id="broker_orders_explain")
            provider = "deepseek-v4-flash"
    except Exception as e:
        text, provider = None, f"unavailable ({str(e)[:60]})"
    return {
        "answer": (text or "").strip() or "(model unavailable — static tooltips still apply)",
        "provider": provider,
        "advisory_only": True,
        "note": "explains mechanics only; cannot submit or approve orders; no security selection",
    }


def _schwab_batch_quotes(query=None):
    """GET /api/v2/schwab/quotes?symbols=A,B,C — READ-ONLY batch quotes served from Data Broker cache.

    Serves from market_quotes DB table (refreshed every 15 min by external_market_data_ingest.py)
    to prevent live Schwab API calls from blocking the single-threaded server.

    TODO: If the frontend needs truly live quotes (real-time bid/ask/spread), restore the live
    schwab_transport.get_quotes() call. The current implementation reads from the 15-min-refreshed
    market_quotes cache and provides only last price, not real-time bid/ask/spread."""
    q = query or {}
    raw = q.get("symbols")
    raw = (raw[0] if isinstance(raw, list) else raw) or ""
    syms = [s.strip().upper() for s in raw.split(",") if s.strip()][:50]
    if not syms:
        return {"status": "error", "error": "symbols required (comma-separated, max 50)"}

    from lib.data_broker.market_quote import get_price_batch

    batch = get_price_batch(_db_query, syms, max_age_hours=4, skip_live=True)

    quotes = {}
    for sym in syms:
        row = batch.get(sym)
        if row:
            quotes[sym] = {
                "last": row.get("price"),
                "bid": None,
                "ask": None,
                "source": row.get("source", "market_quotes"),
                "as_of": row.get("as_of"),
            }
        else:
            quotes[sym] = {"status": "no_data", "last": None, "bid": None, "ask": None}

    return _json_clean(
        {
            "quotes": quotes,
            "status": "ok",
            "source": "market_quotes_cache",
            "note": "Served from 15-min-refreshed cache. Not real-time bid/ask.",
        }
    )


