def _schwab_option_chain(query=None):
    """GET /api/v2/schwab/option-chain?symbol=V&strikes=8 — READ-ONLY near-the-money chain summary."""
    q = query or {}
    g = lambda k, d=None: ((q.get(k) or [d])[0] if isinstance(q.get(k), list) else q.get(k)) or d
    sym = (g("symbol") or "").upper()
    if not sym:
        return {"status": "error", "error": "symbol required"}
    import schwab_transport

    return _json_clean(schwab_transport.get_option_chain(sym, strike_count=min(int(g("strikes", 8) or 8), 20)))


_OPTIONS_ENGINE_MTIME = [0.0]


def _get_options_engine():
    """Return options_engine, reloading when its source changes.

    portfolio_server hot-reloads api_v2 but not its dependencies — without this,
    filter_proposals() can lag behind api_v2 keyword args and return HTTP 500.
    """
    import importlib
    import sys
    import options_engine as oe

    try:
        m = os.path.getmtime(oe.__file__)
    except Exception:
        m = 0.0
    if m != _OPTIONS_ENGINE_MTIME[0]:
        oe = importlib.reload(sys.modules.get("options_engine") or oe)
        for dep in ("options_desk_enterprise", "options_research_bridge"):
            if dep in sys.modules:
                importlib.reload(sys.modules[dep])
        _OPTIONS_ENGINE_MTIME[0] = m
    return oe


# Paper-model strategies surfaced from options_approval_queue (MULTI-STRATEGY
# Stage 2: the ATM long-premium pair joins deep_itm_call; EARNINGS-SPREADS
# Stage 3: the earnings vertical pair joins — the credit id is listed so a
# force-generated/operator-inspected row still renders honestly, but the
# BLOCKED_INITIAL registry row means the scanner never queues it. All
# manual-review, never live-eligible — the fail-closed rendering guard below
# drops any row that lost its paper flags).
PAPER_MODEL_QUEUE_STRATEGIES = (
    "deep_itm_call",
    "atm_call",
    "atm_put",
    "earnings_put_debit_spread",
    "earnings_put_credit_spread",
)

# Alpaca paper-lane queue statuses (Stage 3 state machine).
ALPACA_LANE_STATUSES = (
    "READY_FOR_ALPACA_PAPER",
    "ALPACA_PAPER_SUBMITTED",
    "ALPACA_PAPER_FILLED",
    "ALPACA_PAPER_REJECTED",
    "ALPACA_PAPER_CLOSED",
    "OUTCOME_RECORDED",
    "READY_FOR_LIVE_REVIEW",
)


def _registry_alpaca_paper_enabled() -> dict:
    """{strategy_id: {alpaca_paper_enabled, multi_leg_proven}} from the options
    strategy registry — read-only fallback for queue rows written before
    scan-time meta capture. multi_leg_proven is the Part-G spread-lane key
    (absent everywhere today; absent == False). Fail-closed: an unloadable
    registry yields {} (buttons never show)."""
    try:
        from lib.options_pipeline.universe import load_strategy_registry

        return {
            sid: {
                "alpaca_paper_enabled": bool((row or {}).get("alpaca_paper_enabled")),
                "multi_leg_proven": (row or {}).get("multi_leg_proven") is True,
            }
            for sid, row in (load_strategy_registry().get("strategies") or {}).items()
        }
    except Exception:
        return {}


def _fetch_paper_model_queue_proposals() -> list:
    """Pending paper-model rows (deep_itm_call + atm_call/atm_put, Stage B/2)
    from options_approval_queue.

    The scanner (options_strategy_scanner.py) writes paper-model proposals ONLY
    into the desk's manual-review queue — they never enter options_engine's own
    generation pass. Merge the un-reviewed, un-expired rows into the proposals
    feed so the Options tab renders them alongside desk proposals, with a
    per-row validation-progress chip. Read-only; queue status is attached so
    the UI can show the manual-review lane honestly.
    """
    try:
        from db_adapter import _execute, USE_DB

        if not USE_DB:
            return []
        # Stage 3: in-flight Alpaca-lane rows (READY…OUTCOME/LIVE_REVIEW) stay
        # visible regardless of expires_at — an expired quote must never hide a
        # row that has a live paper order or a recorded outcome behind it.
        rows = (
            _execute(
                """SELECT proposal_id, status AS queue_status, proposal_json, meta,
                      created_at, expires_at
               FROM options_approval_queue
               WHERE strategy = ANY(%s)
                 AND (
                   (status IN ('pending', 'blocked')
                    AND (expires_at IS NULL OR expires_at > NOW()))
                   OR status IN ('READY_FOR_ALPACA_PAPER', 'ALPACA_PAPER_SUBMITTED',
                                 'ALPACA_PAPER_FILLED', 'ALPACA_PAPER_REJECTED',
                                 'ALPACA_PAPER_CLOSED', 'OUTCOME_RECORDED',
                                 'READY_FOR_LIVE_REVIEW')
                 )
               ORDER BY edge_score DESC NULLS LAST, created_at DESC
               LIMIT 60""",
                (list(PAPER_MODEL_QUEUE_STRATEGIES),),
                fetch="all",
            )
            or []
        )
    except Exception:
        return []

    progress_by_strategy: dict = {}

    def _progress_for(strategy: str):
        """Per-strategy advisory validation-gate progress (honest None when the
        validation ledger does not support the strategy yet)."""
        if strategy in progress_by_strategy:
            return progress_by_strategy[strategy]
        progress = None
        try:
            from lib.options_pipeline.validation import validation_status

            vstat = validation_status(strategy)
            if vstat.get("ok"):
                progress = {
                    "label": vstat.get("progress_label"),
                    "n_closed": (vstat.get("metrics") or {}).get("n_closed"),
                    "required": (vstat.get("gate") or {}).get("min_closed_paper_trades"),
                    "gate_met": vstat.get("gate_met"),
                    "message": vstat.get("message"),
                }
        except Exception:
            progress = None
        progress_by_strategy[strategy] = progress
        return progress

    alpaca_enabled_by_strategy = _registry_alpaca_paper_enabled()
    out = []
    for r in rows:
        p = r.get("proposal_json")
        if isinstance(p, str):
            try:
                p = json.loads(p)
            except Exception:
                continue
        if not isinstance(p, dict):
            continue
        # Fail-closed rendering guard: a paper-model row that lost its flags is
        # dropped from the feed rather than rendered as a normal desk proposal.
        if not p.get("educational_paper_model") or (p.get("enterprise") or {}).get("live_eligible"):
            continue
        p["queue_status"] = r.get("queue_status")
        p["queued_at"] = str(r.get("created_at") or "")
        progress = _progress_for(str(p.get("strategy") or ""))
        if progress:
            p["validation_progress"] = progress
        # Stage 3: surface the row's Alpaca order audit + prime rubric to the
        # card (read-only meta passthrough — desk UI renders lane chip/score).
        qmeta = r.get("meta")
        if isinstance(qmeta, str):
            try:
                qmeta = json.loads(qmeta)
            except Exception:
                qmeta = {}
        qmeta = qmeta if isinstance(qmeta, dict) else {}
        if qmeta.get("alpaca_json"):
            p["alpaca_json"] = qmeta["alpaca_json"]
        if qmeta.get("prime_json"):
            p["prime_json"] = qmeta["prime_json"]
        # Stage 2 (Part F): named Alpaca lane fields flattened from
        # meta.alpaca_json — nulls are fine; the lane chips read these first.
        aj = qmeta.get("alpaca_json") if isinstance(qmeta.get("alpaca_json"), dict) else {}
        p["alpaca_paper_status"] = r.get("queue_status") if r.get("queue_status") in ALPACA_LANE_STATUSES else None
        p["alpaca_order_id"] = (aj.get("response") or {}).get("id")
        p["alpaca_fill_price"] = (aj.get("fill") or {}).get("price")
        p["alpaca_submitted_at"] = aj.get("submitted_at")
        p["alpaca_filled_at"] = (aj.get("fill") or {}).get("filled_at")
        # Stage 2 (Part E): Send-to-Alpaca-Paper gating field. Scan-time meta
        # value wins; registry fallback covers rows queued before Stage 2.
        reg_flags = alpaca_enabled_by_strategy.get(str(p.get("strategy") or "")) or {}
        meta_flag = (p.get("meta") or {}).get("alpaca_paper_enabled")
        p["alpaca_paper_enabled"] = bool(meta_flag if meta_flag is not None else reg_flags.get("alpaca_paper_enabled"))
        # EARNINGS-SPREADS Stage 3: the Part-G multi-leg proof flag — spread
        # rows (family earnings_vertical_*) additionally require this before
        # the card may offer Send-to-Alpaca-Paper. Registry is the flag's
        # single home; both flags are false for earnings rows today, so the
        # button never renders until the operator flips them there.
        meta_mlp = (p.get("meta") or {}).get("multi_leg_proven")
        p["multi_leg_proven"] = bool(meta_mlp if meta_mlp is not None else reg_flags.get("multi_leg_proven"))
        out.append(p)
    return out


def _options_validation(query=None):
    """GET /api/v2/options/validation — advisory paper-validation gate report (Stage B).

    Powers the Options tab "Strategy Validation" strip. Advisory only — a met
    gate is reported as operator-decision-required, never acted on.
    """
    try:
        from lib.options_pipeline.validation import SUPPORTED_STRATEGIES, validation_status

        return _json_clean(
            {
                "ok": True,
                "strategies": [validation_status(s) for s in SUPPORTED_STRATEGIES],
            }
        )
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _options_proposals(query=None):
    """GET /api/v2/options/proposals — high-quality options proposals (covered calls + defined risk)."""
    q = query or {}
    g = lambda k, d=None: ((q.get(k) or [d])[0] if isinstance(q.get(k), list) else q.get(k)) or d
    force = str(g("force", "")).lower() in ("1", "true", "yes")
    oe = _get_options_engine()
    data = oe.generate_proposals(force=force)
    proposals = data.get("proposals") or []
    # Stage B: append paper-model queue rows (deep_itm_call) BEFORE filtering so
    # facets/filters treat them uniformly with desk proposals.
    paper_rows = _fetch_paper_model_queue_proposals()
    if paper_rows:
        seen = {p.get("id") for p in proposals}
        proposals = proposals + [p for p in paper_rows if p.get("id") not in seen]
    live_raw = g("live_eligible", "")
    live_eligible = None
    if str(live_raw).lower() in ("1", "true", "yes"):
        live_eligible = True
    elif str(live_raw).lower() in ("0", "false", "no"):
        live_eligible = False
    filtered = oe.filter_proposals(
        proposals,
        symbol=(g("symbol") or "").upper(),
        strategy=g("strategy") or "",
        strategy_group=(g("group") or g("strategy_group") or ""),
        option_type=(g("option_type") or g("type") or ""),
        side=(g("side") or ""),
        sleeve=(g("sleeve") or ""),
        desk_tier=(g("desk_tier") or g("tier") or ""),
        leg_style=(g("leg_style") or g("pairs") or ""),
        live_eligible=live_eligible,
        min_dte=int(g("min_dte", 0) or 0),
        max_dte=int(g("max_dte", 999) or 999),
        min_pop=float(g("min_pop", 0) or 0),
        min_edge=float(g("min_edge", 0) or 0),
    )
    _attach_options_underlying_context(filtered)
    schwab_armed = None
    try:
        import options_pilot_arm as opa

        schwab_armed = bool((opa.status() or {}).get("armed_for_execution"))
    except Exception:
        pass
    try:
        from lib.options_pipeline.card_semantics import apply_card_semantics_batch

        filtered = apply_card_semantics_batch(filtered, schwab_armed=schwab_armed)
    except Exception:
        pass
    return _json_clean(
        {
            **data,
            "proposals": filtered,
            "filtered_count": len(filtered),
            "paper_model_count": len(paper_rows),
            "filter_facets": oe.proposal_filter_facets(proposals),
            "filters_applied": {
                k: v
                for k, v in {
                    "symbol": g("symbol"),
                    "strategy": g("strategy"),
                    "group": g("group") or g("strategy_group"),
                    "option_type": g("option_type") or g("type"),
                    "side": g("side"),
                    "sleeve": g("sleeve"),
                    "desk_tier": g("desk_tier") or g("tier"),
                    "leg_style": g("leg_style") or g("pairs"),
                    "live_eligible": live_eligible,
                    "min_pop": float(g("min_pop", 0) or 0) or None,
                    "min_edge": float(g("min_edge", 0) or 0) or None,
                }.items()
                if v not in (None, "", 0)
            },
        }
    )


def _attach_options_underlying_context(rows: list) -> None:
    """Underlying company context (one-liner/sector/instrument) for options desk cards —
    they previously rendered greeks-only with zero equity intelligence."""
    try:
        pmap = _broker_symbol_profiles_batch([r.get("underlying") or r.get("symbol") for r in rows])
        for r in rows:
            prof = pmap.get(str(r.get("underlying") or r.get("symbol") or "").upper()) or {}
            if prof.get("description_1s") and not r.get("company_description"):
                r["company_description"] = str(prof["description_1s"])[:400]
            for k in ("sector", "industry", "instrument_type"):
                if prof.get(k) and not r.get(k):
                    r[k] = prof.get(k)
    except Exception:
        pass


def _options_positions(query=None):
    """GET /api/v2/options/positions — open options legs from Schwab + monitoring snapshot."""
    q = query or {}
    g = lambda k, d=None: ((q.get(k) or [d])[0] if isinstance(q.get(k), list) else q.get(k)) or d
    force = str(g("force", "")).lower() in ("1", "true", "yes")
    oe = _get_options_engine()
    data = oe.monitor_positions(force=force)
    positions = data.get("positions") or []
    working_raw = g("working_only", "")
    working_only = None
    if str(working_raw).lower() in ("1", "true", "yes"):
        working_only = True
    filtered = oe.filter_positions(
        positions,
        symbol=(g("symbol") or "").upper(),
        option_type=(g("option_type") or g("type") or ""),
        side=(g("side") or ""),
        leg_style=(g("leg_style") or ""),
        working_only=working_only,
    )
    _attach_options_underlying_context(filtered)
    return _json_clean(
        {
            **data,
            "positions": filtered,
            "filtered_count": len(filtered),
            "filter_facets": oe.position_filter_facets(positions),
        }
    )


def _options_monitor(query=None):
    """GET /api/v2/options/monitor — alias for positions monitor + alerts."""
    return _options_positions(query)


def _options_paper_positions(query=None):
    """GET /api/v2/options/paper-positions — monitored lifecycle positions + snapshots."""
    from lib.options_pipeline import paper_positions_api as ppa

    q = query or {}
    g = lambda k, d=None: ((q.get(k) or [d])[0] if isinstance(q.get(k), list) else q.get(k)) or d
    pid = g("position_id", "")
    if pid:
        one = ppa.get_monitored_position(int(pid))
        return _json_clean({"ok": True, "position": one, "count": 1 if one else 0})
    status = (g("status") or "OPEN").upper()
    positions = ppa.list_monitored_positions(
        status=status,
        broker=(g("broker") or None),
        symbol=(g("symbol") or "").upper() or None,
        limit=int(g("limit") or 100),
    )
    filtered = ppa.filter_positions(
        positions,
        symbol=(g("symbol") or "").upper(),
        option_type=(g("option_type") or g("type") or ""),
        side=(g("side") or ""),
        route=(g("route") or ""),
        paper_only=True if str(g("paper_only", "")).lower() in ("1", "true", "yes") else None,
    )
    return _json_clean(
        {
            "ok": True,
            "positions": filtered,
            "count": len(filtered),
            "filter_facets": ppa.position_filter_facets(positions),
        }
    )


def _options_paper_position_alerts(query=None):
    """GET /api/v2/options/paper-positions/alerts — unacked monitored position alerts."""
    from lib.options_pipeline import paper_positions_api as ppa

    q = query or {}
    g = lambda k, d=None: ((q.get(k) or [d])[0] if isinstance(q.get(k), list) else q.get(k)) or d
    unacked = str(g("unacked", "1")).lower() not in ("0", "false", "no")
    alerts = ppa.list_position_alerts(
        unacked_only=unacked,
        limit=int(g("limit") or 50),
    )
    return _json_clean({"ok": True, "alerts": alerts, "count": len(alerts)})


def _options_open_positions(query=None):
    """GET /api/v2/options/open-positions — unified broker legs + monitored paper positions."""
    from lib.options_pipeline import paper_positions_api as ppa

    broker_data = _options_positions(query) or {}
    broker_positions = broker_data.get("positions") or []
    for p in broker_positions:
        p.setdefault("position_source", "broker")
        p.setdefault("unified_id", f"broker:{p.get('id')}")
    q = query or {}
    g = lambda k, d=None: ((q.get(k) or [d])[0] if isinstance(q.get(k), list) else q.get(k)) or d
    monitored = ppa.list_monitored_positions(
        status="OPEN",
        symbol=(g("symbol") or "").upper() or None,
    )
    unified = ppa.build_unified_open_positions(broker_positions, monitored)
    filtered = ppa.filter_positions(
        unified,
        symbol=(g("symbol") or "").upper(),
        option_type=(g("option_type") or g("type") or ""),
        side=(g("side") or ""),
        route=(g("route") or ""),
        source=(g("source") or ""),
        paper_only=True if str(g("paper_only", "")).lower() in ("1", "true", "yes") else None,
    )
    mon_alerts = ppa.list_position_alerts(unacked_only=True, limit=30)
    broker_alerts = broker_data.get("alerts") or []
    return _json_clean(
        {
            **broker_data,
            "ok": True,
            "monitored_positions": monitored,
            "monitored_count": len(monitored),
            "positions": filtered,
            "unified_count": len(unified),
            "filtered_count": len(filtered),
            "filter_facets": ppa.position_filter_facets(unified),
            "alerts": broker_alerts + mon_alerts,
            "monitored_alerts": mon_alerts,
        }
    )


def _options_paper_position_alerts_ack(body=None):
    """POST /api/v2/options/paper-positions/alerts/ack {alert_id}"""
    from lib.options_pipeline import paper_positions_api as ppa

    b = body or {}
    aid = b.get("alert_id")
    if not aid:
        return {"ok": False, "error": "alert_id required"}
    return ppa.acknowledge_alert(int(aid))


