def _held_context(symbols):
    """Watch Desk v2 (C1): position-aware context for buy-side surfaces.
    {SYM: {shares, market_value, stop_price, stop_distance_pct, stop_state, near_stop}}
    from holdings.json + stop_lifecycle. Read-only, fail-open."""
    out = {}
    if not symbols:
        return out
    syms = sorted({str(s).upper() for s in symbols if s})
    try:
        import json as _j

        hd = _j.loads((PROJECT_ROOT / "data" / "portfolios" / "state" / "holdings.json").read_text())
        for h in hd.get("holdings") or []:
            s = str(h.get("symbol") or "").upper()
            if s in syms and not h.get("is_cash"):
                e = out.setdefault(s, {"shares": 0.0, "market_value": 0.0})
                e["shares"] += float(h.get("shares") or 0)
                e["market_value"] += float(h.get("market_value") or 0)
    except Exception:
        return {}
    try:
        rows = (
            _db_query(
                """SELECT DISTINCT ON (upper(symbol)) upper(symbol) AS s, stop_price, proximity_pct, status
               FROM stop_lifecycle
               WHERE status IN ('working','open','awaiting_stop_condition','new')
                 AND upper(symbol) = ANY(%s)
               ORDER BY upper(symbol), snapshot_at DESC""",
                (syms,),
                fetch="all",
            )
            or []
        )
        for r in rows:
            if r["s"] in out:
                prox = r.get("proximity_pct")
                out[r["s"]].update(
                    stop_price=float(r["stop_price"]) if r.get("stop_price") else None,
                    stop_distance_pct=float(prox) if prox is not None else None,
                    stop_state=r.get("status"),
                    near_stop=bool(prox is not None and abs(float(prox)) <= 5.0),
                )
    except Exception:
        pass
    return out


def _pullback_score_formula():
    """v4 (F2): score-formula constants from the screener's own YAML (render-only)."""
    prox, tgt = 0.6, 20.0
    try:
        import yaml as _y

        cfg = _y.safe_load((PROJECT_ROOT / "config" / "pullback_macd_screener.yaml").read_text()) or {}
        flat = {}

        def _walk(d):
            for k, v in (d or {}).items():
                if isinstance(v, dict):
                    _walk(v)
                else:
                    flat[k] = v

        _walk(cfg)
        prox = float(flat.get("macd_proximity_pct", prox))
        tgt = float(flat.get("pullback_target_pct", tgt))
    except Exception:
        pass
    return {
        "base": 100,
        "macd_weight": 30,
        "macd_proximity_pct": prox,
        "pullback_target_pct": tgt,
        "pullback_weight": 1.5,
        "formula": f"100 − (macd_prox/{prox})×30 − |pullback−{tgt:g}|×1.5 + trend_pct",
    }


def _pullback_macd_candidates(query=None):
    """GET /api/v2/pullback-macd/candidates — S&P 500 uptrend + pullback + approaching-MACD-cross.

    Params: tier=trigger|watch (default all active), limit (default 100).
    Returns trigger + watch tiers with pullback %, MACD proximity, entry/stop/target, linked proposal.
    """
    q = query or {}
    g = lambda k, d=None: ((q.get(k) or [d])[0] if isinstance(q.get(k), list) else q.get(k)) or d
    tier = (g("tier") or "").lower()
    limit = int(g("limit", 100) or 100)
    from db_adapter import _execute

    where = "status='active'"
    params = []
    if tier in ("trigger", "watch"):
        where += " AND tier=%s"
        params.append(tier)
    params.append(limit)
    # LEFT JOIN the linked proposal so the UI knows whether proposal_id still points to a LIVE,
    # filterable proposal. A trigger whose proposal has EXPIRED/REJECTED must NOT be advertised as
    # "in queue" — otherwise the widget count drifts above the filtered list, which is exactly the
    # "3 triggers shown but 0 proposals when filtered" bug.
    rows = (
        _execute(
            f"""SELECT c.symbol, c.tier, c.prev_tier, c.price, c.pullback_pct, c.trend_pct, c.macd_prox_pct,
                   c.hist_rising_bars, c.bars_to_cross_est, c.atr, c.entry, c.stop, c.target1, c.rr, c.score,
                   c.why_not, c.vwap, c.above_vwap, c.vwap_dist_pct, c.proposal_id, c.scan_date,
                   c.first_seen_at, c.last_scan_at,
                   p.status AS proposal_status,
                   -- "live" mirrors the proposals-list visibility gate EXACTLY (status only, no expiry
                   -- clause) so the widget's queued count == what the source=pullback_macd list shows.
                   (p.status IN ('PENDING','APPROVED_FOR_PAPER_TEST')) AS proposal_live
            FROM pullback_macd_candidates c
            LEFT JOIN paper_trade_proposals p ON p.id = c.proposal_id
            WHERE {("c." + where.replace(" AND ", " AND c.")) if where else where}
            ORDER BY (c.tier='trigger') DESC, c.score DESC LIMIT %s""",
            params,
            fetch="all",
        )
        or []
    )
    run = _execute("SELECT * FROM pullback_macd_runs ORDER BY created_at DESC LIMIT 1", fetch="one")

    # Watch Desk v2 (D1): idempotent trigger recorder — every active trigger gets
    # one history row per (symbol, day); the weekly reconciler fills outcomes
    try:
        _execute(
            """INSERT INTO pullback_trigger_history (symbol, trigger_date, score, entry, stop, target1)
                    SELECT symbol, COALESCE(scan_date, CURRENT_DATE), score, entry, stop, target1
                    FROM pullback_macd_candidates WHERE tier='trigger' AND status='active'
                    ON CONFLICT (symbol, trigger_date) DO NOTHING""",
            fetch=None,
        )
    except Exception:
        pass

    # Watch Desk v2 (D2): dismissal memory — dismissed symbols sit out a config
    # cooldown (default 10 trading days ≈ 14 calendar) unless score improved ≥25%
    dismissed_out = 0
    try:
        dis = (
            _execute(
                """SELECT upper(symbol) AS s, score_at_dismiss, dismissed_at
                          FROM pullback_macd_dismissals
                          WHERE dismissed_at > now() - interval '14 days'""",
                fetch="all",
            )
            or []
        )
        dmap = {r["s"]: r for r in dis}
        if dmap:
            kept = []
            for r in rows:
                drow = dmap.get(str(r.get("symbol") or "").upper())
                if drow:
                    old = float(drow.get("score_at_dismiss") or 0)
                    if not (old > 0 and float(r.get("score") or 0) >= old * 1.25):
                        dismissed_out += 1
                        continue
                    r["redisplay_reason"] = f"score improved ≥25% vs {old:g} at dismissal"
                kept.append(r)
            rows = kept
    except Exception:
        pass

    # Watch Desk v2 (C1): held-position awareness — a buy TRIGGER on a held name
    # near its stop must be impossible to miss
    held = _held_context([r.get("symbol") for r in rows])
    for r in rows:
        hc = held.get(str(r.get("symbol") or "").upper())
        if hc:
            r["held"] = hc
            r["held_conflict"] = bool(r.get("tier") == "trigger" and hc.get("near_stop"))

    # Watch Desk v2 (D1): trailing trigger hit-rate from pullback_trigger_history
    hit_stats = None
    try:
        hs = _execute(
            """SELECT count(*) AS n,
                                count(*) FILTER (WHERE outcome='TARGET1_FIRST') AS wins,
                                count(*) FILTER (WHERE outcome IS NOT NULL) AS evaluated,
                                percentile_cont(0.5) WITHIN GROUP (ORDER BY days_to_resolve)
                                  FILTER (WHERE days_to_resolve IS NOT NULL) AS median_days
                         FROM pullback_trigger_history
                         WHERE trigger_date > CURRENT_DATE - 90""",
            fetch="one",
        )
        if hs and hs.get("n"):
            hit_stats = {
                "window_days": 90,
                "triggers": hs["n"],
                "evaluated": hs["evaluated"],
                "target1_first": hs["wins"],
                "median_days": hs.get("median_days"),
            }
    except Exception:
        pass

    triggers = [r for r in rows if r.get("tier") == "trigger"]
    # a trigger is "queued" only if its linked proposal is still LIVE (PENDING/APPROVED); ones pointing
    # to expired/rejected proposals are counted separately so the widget matches the list.
    trigger_live = [r for r in triggers if r.get("proposal_live")]
    return _json_clean(
        {
            "ok": True,
            "candidates": rows,
            "trigger_count": len(triggers),
            "trigger_live_count": len(trigger_live),
            "trigger_stale_count": len(triggers) - len(trigger_live),
            "watch_count": sum(1 for r in rows if r.get("tier") == "watch"),
            "dismissed_in_cooldown": dismissed_out,
            "hit_stats": hit_stats,
            "held_count": sum(1 for r in rows if r.get("held")),
            "last_run": run,
            # v4 (F2): the screener's actual score formula constants, so the UI can break the
            # composite into its components on hover — read from the same YAML the screener
            # reads; render-only, nothing about scoring changes.
            "score_formula": _pullback_score_formula(),
            # D3 provenance — universe + schedule stated on-page, not implied
            "scan_provenance": {
                "universe": "S&P 500 uptrend-intact pullbacks approaching MACD cross",
                "screened": (run or {}).get("screened") or (run or {}).get("universe_count"),
                "schedule": "cron-scheduled scans; Run-scan-now is compute-only (reads bars, writes candidates — RTH-safe)",
            },
            "generated_at": (run or {}).get("created_at"),
        }
    )


def _pullback_macd_scan(body=None):
    """POST /api/v2/pullback-macd/scan — trigger a screener run in the background.

    Runs detached (full scan ~40s) so it never blocks the single-threaded API server; flock
    prevents overlapping runs. Returns immediately; the UI re-fetches candidates after.
    """
    import subprocess

    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    launcher = os.path.join(root, "linux_launchers", "run_pullback_macd_screener.sh")
    try:
        subprocess.Popen(
            ["bash", launcher], cwd=root, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True
        )
        return {"ok": True, "started": True, "note": "scan running in background (~40s); refresh shortly"}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _pullback_macd_dismiss(body=None):
    """POST /api/v2/pullback-macd/dismiss — dismiss a candidate (until next scan), optionally
    cancelling its advisory proposal. Body: {symbol, cancel_proposal?: bool}."""
    b = body if isinstance(body, dict) else {}
    sym = str(b.get("symbol") or "").upper().strip()
    if not sym:
        return {"ok": False, "error": "symbol required"}
    from db_adapter import _execute

    row = _execute("SELECT proposal_id FROM pullback_macd_candidates WHERE symbol=%s", (sym,), fetch="one")
    if not row:
        return {"ok": False, "error": "candidate not found"}
    _execute("UPDATE pullback_macd_candidates SET status='dismissed' WHERE symbol=%s", (sym,))
    # Watch Desk v2 (D2): persistent cooldown memory — 10 trading days unless
    # score improves ≥25% (enforced in the candidates read)
    try:
        _sc = (
            _execute(
                "SELECT score FROM pullback_macd_candidates WHERE symbol=%s ORDER BY last_scan_at DESC LIMIT 1",
                (sym,),
                fetch="one",
            )
            or {}
        )
        _execute(
            """INSERT INTO pullback_macd_dismissals (symbol, mode, score_at_dismiss, dismissed_at)
                    VALUES (%s,%s,%s,NOW())
                    ON CONFLICT (symbol) DO UPDATE SET mode=EXCLUDED.mode,
                      score_at_dismiss=EXCLUDED.score_at_dismiss, dismissed_at=NOW()""",
            (sym, "dismiss_cancel" if b.get("cancel_proposal") else "dismiss", _sc.get("score")),
            fetch=None,
        )
    except Exception:
        pass
    cancelled = None
    if b.get("cancel_proposal") and row.get("proposal_id"):
        _execute(
            """UPDATE paper_trade_proposals
                    SET status='REJECTED', rejected_at=NOW(),
                        rejection_reason='dismissed via Pullback/MACD screener'
                    WHERE id=%s AND status='PENDING'""",
            (row["proposal_id"],),
        )
        cancelled = row["proposal_id"]
    return {"ok": True, "symbol": sym, "dismissed": True, "proposal_cancelled": cancelled}


def _costs(query=None, which="summary"):
    """GET /api/v2/journal/costs/* — canonical investment-cost ledger reads.
    Every payload labels actual vs estimated; classes never merge silently."""
    import importlib
    import investment_costs as _ic

    _ic = importlib.reload(_ic)
    from db_adapter import _get_conn

    conn = _get_conn()
    cur = conn.cursor()
    _ic.ensure_cost_tables(cur, conn)
    fn = {
        "summary": _ic.costs_summary,
        "timeseries": _ic.costs_timeseries,
        "by-security": _ic.costs_by_security,
        "unmatched": _ic.costs_unmatched,
        "reconciliation": _ic.costs_reconciliation,
        "events": _ic.costs_events,
        "by-trade": _ic.costs_by_trade,
    }[which]
    return fn(cur, query or {})


