def _inverse_stoplights_get(query=None):
    """GET /api/v2/defense/inverse-stoplights — four labeled lights per -1x
    candidate (runtime snapshot; refreshed by the defense nightly + refresh)."""
    import json as _json

    p = PROJECT_ROOT / "data" / "runtime" / "inverse_stoplights_latest.json"
    if p.exists():
        return _json.loads(p.read_text())
    return {"candidates": [], "note": "no stoplight evaluation yet"}


def _olc():
    """Options lifecycle modules with reload — same dev-cadence pattern as _dex()."""
    import importlib
    import options_lifecycle_tickets, options_lifecycle_alerts, options_lifecycle_run

    return (
        importlib.reload(options_lifecycle_tickets),
        importlib.reload(options_lifecycle_alerts),
        importlib.reload(options_lifecycle_run),
    )


def _options_lifecycle_get():
    """GET /api/v2/options/lifecycle — the desk payload (runner-written) + live
    ticket states. File-served: cheap for the UI, refreshed by cron/refresh."""
    import json as _json
    from db_adapter import _get_conn

    p = PROJECT_ROOT / "data" / "runtime" / "options_lifecycle_latest.json"
    payload = (
        _json.loads(p.read_text())
        if p.exists()
        else {"positions": [], "alerts": [], "counts": {"open_strategies": 0}, "note": "no lifecycle run yet"}
    )
    try:
        cur = _get_conn().cursor()
        cur.execute("""SELECT ticket_id, strategy_position_id, kind, status, tif, created_at
                       FROM options_lifecycle_tickets
                       WHERE status IN ('draft','approved','awaiting_2fa','armed','partial')
                       ORDER BY ticket_id DESC LIMIT 20""")
        payload["live_tickets"] = [
            {
                "ticket_id": r[0],
                "strategy_position_id": r[1],
                "kind": r[2],
                "status": r[3],
                "tif": r[4],
                "created_at": str(r[5]),
            }
            for r in cur.fetchall()
        ]
    except Exception:
        payload["live_tickets"] = []
    try:
        cur.execute("""SELECT o.strategy_position_id, p.underlying, p.strategy_type,
                              o.recommendation_at_action, o.operator_action, o.realized_pnl,
                              o.closed_at
                       FROM options_lifecycle_outcomes o
                       JOIN options_strategy_positions p USING (strategy_position_id)
                       ORDER BY o.closed_at DESC LIMIT 15""")
        payload["closed_outcomes"] = [
            {
                "strategy_position_id": r[0],
                "underlying": r[1],
                "strategy_type": r[2],
                "recommendation": r[3],
                "operator_action": r[4],
                "realized_pnl": float(r[5]) if r[5] is not None else None,
                "closed_at": str(r[6]),
            }
            for r in cur.fetchall()
        ]
    except Exception:
        payload["closed_outcomes"] = []
    return payload


def _options_lifecycle_post(base_path, body):
    """POST /api/v2/options/lifecycle/* — alert lifecycle + hash-bound tickets.
    Every action fail-closed; nothing here submits an order anywhere."""
    from db_adapter import _get_conn

    tickets, alerts_mod, run_mod = _olc()
    conn = _get_conn()
    cur = conn.cursor()
    action = base_path.rsplit("/", 1)[-1]
    if action == "refresh":
        r = run_mod.run(dry=False)
        return {"ok": True, "data": {"counts": r["counts"], "generated_at": r["generated_at"]}}
    if action == "alert-ack":
        return {"ok": True, "data": alerts_mod.ack_alert(cur, conn, int(body["alert_id"]), body.get("snooze_hours"))}
    if action == "ticket-build":
        if body.get("kind") == "roll":
            t = tickets.build_roll_ticket(
                cur,
                conn,
                int(body["strategy_position_id"]),
                new_expiration=body["new_expiration"],
                strike_map=body.get("strike_map") or {},
                tif=body.get("tif"),
            )
        else:
            t = tickets.build_close_ticket(
                cur,
                conn,
                int(body["strategy_position_id"]),
                fraction=float(body.get("fraction") or 1.0),
                tif=body.get("tif"),
                legs_subset=body.get("legs_subset"),
                operator_acknowledged_leg_out=bool(body.get("operator_acknowledged_leg_out")),
            )
        return {"ok": not t.get("blocked"), "data": t}
    if action == "ticket-approve":
        return {
            "ok": True,
            "data": tickets.approve_ticket(cur, conn, int(body["ticket_id"]), str(body.get("hash") or "")),
        }
    if action == "ticket-2fa":
        return {
            "ok": True,
            "data": tickets.verify_ticket_2fa(cur, conn, int(body["ticket_id"]), str(body.get("code") or "")),
        }
    if action == "ticket-evidence":
        return {
            "ok": True,
            "data": tickets.record_fill_evidence(
                cur,
                conn,
                int(body["ticket_id"]),
                body.get("fills") or [],
                str(body.get("source") or "operator_manual"),
                body.get("note") or "",
            ),
        }
    if action == "ticket-cancel":
        return {"ok": True, "data": tickets.cancel_ticket(cur, conn, int(body["ticket_id"]))}
    if action == "attribution":
        import importlib, ticker_attribution as _ta

        _ta = importlib.reload(_ta)
        if body.get("symbol"):
            return {"ok": True, "data": _ta.ticker_attribution(cur, str(body["symbol"]))}
        return {"ok": True, "data": _ta.portfolio_attribution(cur)}
    if action == "journal-entry":
        import importlib, options_journal_bridge as _ob

        _ob = importlib.reload(_ob)
        _ob.ensure_bridge_tables(cur, conn)
        return {"ok": True, "data": _ob.journal_entry(cur, int(body["strategy_position_id"]))}
    if action == "record-basis":
        import importlib, options_lifecycle_basis as _bs

        _bs = importlib.reload(_bs)
        _bs.ensure_basis_tables(cur, conn)
        return {
            "ok": True,
            "data": _bs.record_operator_basis(
                cur,
                conn,
                int(body["leg_id"]),
                opening_premium=float(body["opening_premium"]),
                opening_date=str(body.get("opening_date") or ""),
                contracts=float(body["contracts"]),
                fees=body.get("fees"),
                source_ref=str(body.get("source_ref") or ""),
                operator=str(body.get("operator") or "operator"),
                notes=body.get("notes") or "",
            ),
        }
    if action == "request-review":
        import importlib
        import options_lifecycle_oversight as _ov
        import options_lifecycle_model as _om
        import options_lifecycle_engine as _oe

        _ov, _om, _oe = importlib.reload(_ov), importlib.reload(_om), importlib.reload(_oe)
        s = _om.strategy_with_legs(cur, int(body["strategy_position_id"]))
        if not s:
            return {"ok": False, "error": "unknown strategy"}
        # v1.2 P2: the canonical decision path — never decide() without the reducer+findings
        ev = _oe.evaluate_strategy(cur, conn, s, persist=False)
        res = _ov.run_free_review(cur, conn, s, ev["eco"], ev["decision"], "operator_requested")
        return {
            "ok": True,
            "data": {"results": res, "strongest": _ov.strongest_objection(cur, s["strategy_position_id"])},
        }
    return {"ok": False, "error": f"unknown lifecycle action {action}"}


def _options_approval_resolve(body=None):
    """POST /api/v2/options/approval-queue/resolve — approve or reject desk proposal."""
    b = body if isinstance(body, dict) else {}
    pid = str(b.get("proposal_id") or "").strip()
    action = str(b.get("action") or "").strip().lower()
    if not pid or action not in ("approve", "reject"):
        return {"ok": False, "error": "proposal_id and action (approve|reject) required"}
    import options_desk_enterprise as ent

    return _json_clean(
        ent.resolve_approval(
            pid,
            action,
            reviewer=str(b.get("reviewer") or "operator"),
            note=str(b.get("note") or ""),
        )
    )


# ── ALPACA-OPTIONS Stage 3 (Part F): Alpaca PAPER lane operator routes ────────
# Thin wrappers over the paper-locked state machine in
# lib/options_pipeline/alpaca_paper.py — every guard (paper-endpoint hard lock,
# LIMIT-only, 1-contract cap, operator-only transitions, confirm-required
# submit) lives THERE and is not re-implemented or bypassed here. Refusals come
# back as honest 4xx {reason}. Actor for UI-triggered marks: 'operator:ui'.

_ALPACA_UI_ACTOR = "operator:ui"


def _options_alpaca_refused(e) -> tuple:
    """Map state-machine/policy refusals to an honest 4xx {reason}."""
    return 409, {"ok": False, "reason": str(e)[:400]}


def _options_alpaca_mark_ready(body=None):
    """POST /api/v2/options/alpaca-paper/mark-ready {proposal_id} —
    operator mark: pending/approved → READY_FOR_ALPACA_PAPER.

    MULTI-STRATEGY Stage 2: the registry's per-strategy alpaca_paper_enabled
    gates lane ENTRY here (server-side twin of the card's button gating —
    atm_call/atm_put ship with alpaca_paper_enabled=false until the operator
    flips the registry after paper observation)."""
    from lib.options_pipeline import alpaca_paper as ap

    b = body if isinstance(body, dict) else {}
    pid = str(b.get("proposal_id") or "").strip()
    if not pid:
        return 400, {"ok": False, "reason": "proposal_id required"}
    row = ap.get_queue_row(pid)
    if row is not None:
        sid = str(row.get("strategy") or "")
        if not _registry_alpaca_paper_enabled().get(sid):
            return 409, {
                "ok": False,
                "reason": f"strategy {sid or 'unknown'} has alpaca_paper_enabled=false in "
                "options_strategy_registry — Alpaca paper lane refused "
                "(operator flips the registry after paper observation)",
            }
    try:
        return 200, _json_clean(ap.mark_ready(pid, operator_actor=_ALPACA_UI_ACTOR))
    except (ap.IllegalTransitionError, ap.OperatorActionRequiredError) as e:
        return _options_alpaca_refused(e)


def _options_alpaca_submit(body=None):
    """POST /api/v2/options/alpaca-paper/submit {proposal_id, confirm: true} —
    submit ONE READY row as a 1-contract paper LIMIT order. confirm:true is
    MANDATORY (mirrors the executor CLI's --confirm); missing/false → 400.
    Missing/invalid ALPACA_PAPER_BASE_URL → honest 4xx {reason} from the
    paper-endpoint hard lock — never a silent fallback."""
    from lib.options_pipeline import alpaca_paper as ap

    b = body if isinstance(body, dict) else {}
    pid = str(b.get("proposal_id") or "").strip()
    if not pid:
        return 400, {"ok": False, "reason": "proposal_id required"}
    if b.get("confirm") is not True:
        return 400, {
            "ok": False,
            "reason": "confirm:true required — there is no automatic submit path (operator action)",
        }
    try:
        res = ap.submit_ready_proposal(pid, confirm=True)
    except (ap.PaperEndpointError, ap.OrderPolicyError, ap.IllegalTransitionError, ap.OperatorActionRequiredError) as e:
        return _options_alpaca_refused(e)
    if not res.get("ok"):
        return 502, _json_clean({**res, "reason": res.get("error")})
    return 200, _json_clean(res)


def _options_alpaca_reconcile(body=None):
    """POST /api/v2/options/alpaca-paper/reconcile — poll fills/rejects/closes
    → outcomes (read-only vs Alpaca; state transitions via the legality-checked
    machine)."""
    from lib.options_pipeline import alpaca_paper as ap

    try:
        return 200, _json_clean(ap.reconcile_fills())
    except (ap.PaperEndpointError, ap.IllegalTransitionError) as e:
        return _options_alpaca_refused(e)


def _options_alpaca_record_outcome(body=None):
    """POST /api/v2/options/alpaca-paper/record-outcome {proposal_id, exit_premium}
    — minimal honest operator close: FILLED/CLOSED row + operator-entered exit
    premium → close blob + validation ledger (record_outcome) → OUTCOME_RECORDED.
    P/L math matches reconcile_fills: (exit − entry fill) × 100 × 1 contract."""
    from lib.options_pipeline import alpaca_paper as ap
    from lib.options_pipeline.validation import record_outcome

    b = body if isinstance(body, dict) else {}
    pid = str(b.get("proposal_id") or "").strip()
    if not pid:
        return 400, {"ok": False, "reason": "proposal_id required"}
    exit_px = b.get("exit_premium")
    try:
        exit_px = float(exit_px)
    except (TypeError, ValueError):
        return 400, {"ok": False, "reason": "exit_premium (per-contract price) required"}
    if not (0 <= exit_px < 10000):
        return 400, {"ok": False, "reason": f"exit_premium {exit_px} out of sane range"}
    row = ap.get_queue_row(pid)
    if not row:
        return 404, {"ok": False, "reason": f"proposal {pid!r} not in queue"}
    if row["status"] not in (ap.STATE_FILLED, ap.STATE_CLOSED):
        return 409, {
            "ok": False,
            "reason": f"row is '{row['status']}' — outcome can only be recorded on {ap.STATE_FILLED}/{ap.STATE_CLOSED}",
        }
    aj = ap._alpaca_meta(row)
    entry_px = float((aj.get("fill") or {}).get("price") or 0.0)
    if entry_px <= 0:
        return 409, {
            "ok": False,
            "reason": "no recorded Alpaca fill price in meta — cannot compute P/L honestly (run reconcile first)",
        }
    try:
        if row["status"] == ap.STATE_FILLED:
            entry_debit = round(entry_px * 100.0, 2)
            exit_value = round(exit_px * 100.0, 2)
            pnl = round(exit_value - entry_debit, 2)
            aj = {
                **aj,
                "close": {
                    "exit_price": exit_px,
                    "closed_at": _dtnow_iso(),
                    "pnl": pnl,
                    "entry_debit": entry_debit,
                    "exit_value": exit_value,
                    "close_order": None,
                    "source": "operator_manual_ui",
                },
            }
            ap.transition(pid, ap.STATE_CLOSED, meta_patch={"alpaca_json": aj})
        close = aj.get("close") or {}
        pnl = float(close.get("pnl") or 0.0)
        rec = record_outcome(
            pid,
            outcome=ap._outcome_from_pnl(pnl),
            strategy_id=row.get("strategy") or "deep_itm_call",
            symbol=row.get("symbol") or "",
            pnl=pnl,
            entry_debit=close.get("entry_debit"),
            exit_value=close.get("exit_value"),
            opened_at=(aj.get("fill") or {}).get("filled_at"),
            closed_at=close.get("closed_at"),
            exit_reason="manual",
            notes="operator-entered exit premium via desk UI",
            meta={
                "alpaca_order_id": (aj.get("response") or {}).get("id"),
                "lane": "tradeai_automated",
                "source": "operator_manual_ui",
            },
        )
        if not rec.get("ok"):
            return 502, {
                "ok": False,
                "reason": f"record_outcome failed: {rec.get('error')} — row left in {ap.STATE_CLOSED} for retry",
            }
        ap.transition(pid, ap.STATE_OUTCOME, meta_patch={"outcome_recorded_at": _dtnow_iso()})
    except (ap.IllegalTransitionError, ap.OperatorActionRequiredError) as e:
        return _options_alpaca_refused(e)
    return 200, _json_clean(
        {"ok": True, "proposal_id": pid, "status": ap.STATE_OUTCOME, "pnl": pnl, "outcome": ap._outcome_from_pnl(pnl)}
    )


def _options_alpaca_promote_live_review(body=None):
    """POST /api/v2/options/alpaca-paper/promote-live-review {proposal_id, confirm:true}
    — operator-only OUTCOME_RECORDED → READY_FOR_LIVE_REVIEW. Server-side guard:
    the row's prime verdict must be READY_FOR_LIVE_REVIEW_OPERATOR_ONLY.
    This does NOT place an order; live consideration still requires operator
    2FA + broker preview/read-back, and the model stays unvalidated until
    30 paper outcomes / 3 months."""
    from lib.options_pipeline import alpaca_paper as ap
    from lib.options_pipeline.prime_rubric import VERDICT_LIVE_REVIEW_LABEL

    b = body if isinstance(body, dict) else {}
    pid = str(b.get("proposal_id") or "").strip()
    if not pid:
        return 400, {"ok": False, "reason": "proposal_id required"}
    if b.get("confirm") is not True:
        return 400, {"ok": False, "reason": "confirm:true required (operator action)"}
    row = ap.get_queue_row(pid)
    if not row:
        return 404, {"ok": False, "reason": f"proposal {pid!r} not in queue"}
    meta = row.get("meta")
    if isinstance(meta, str):
        try:
            meta = json.loads(meta)
        except Exception:
            meta = {}
    verdict = ((meta or {}).get("prime_json") or {}).get("verdict")
    if verdict != VERDICT_LIVE_REVIEW_LABEL:
        return 409, {
            "ok": False,
            "reason": f"prime verdict is {verdict!r} — promotion "
            f"requires {VERDICT_LIVE_REVIEW_LABEL} "
            "(run the prime rubric)",
        }
    try:
        res = ap.mark_live_review(pid, operator_actor=_ALPACA_UI_ACTOR)
    except (ap.IllegalTransitionError, ap.OperatorActionRequiredError) as e:
        return _options_alpaca_refused(e)
    return 200, _json_clean(
        {
            **res,
            "note": "READY_FOR_LIVE_REVIEW is a review mark only — "
            "no order was placed; 2FA + broker preview still required",
        }
    )


def _options_prime_rubric(body=None):
    """POST /api/v2/options/prime-rubric {proposal_id} — score the row through
    the 10-component prime rubric, persist meta.prime_json (one UPDATE) and
    return it. Advisory label only — never transitions status."""
    from lib.options_pipeline import prime_rubric as pr

    b = body if isinstance(body, dict) else {}
    pid = str(b.get("proposal_id") or "").strip()
    if not pid:
        return 400, {"ok": False, "reason": "proposal_id required"}
    res = pr.score_and_persist(pid, dry_run=bool(b.get("dry_run")))
    if not res.get("ok"):
        code = 404 if "not in options_approval_queue" in str(res.get("error")) else 502
        return code, _json_clean({**res, "reason": res.get("error")})
    return 200, _json_clean(res)


def _dtnow_iso() -> str:
    from datetime import datetime, timezone

    return datetime.now(timezone.utc).isoformat()


