def _schwab_stream_status(query=None):
    """GET /api/v2/schwab/stream/status — Level-2 capture daemon status (Rule-9 isolated, read-only)."""
    rows = (
        _db_query(
            """SELECT count(*) n, max(captured_at) latest,
                               count(DISTINCT symbol) syms
                        FROM schwab_stream_book WHERE captured_at > NOW()-INTERVAL '1 hour'""",
            fetch="one",
        )
        or {}
    )
    kill = (Path(__file__).resolve().parent.parent / "data" / "state" / "STREAM_DISABLED").exists()
    return _json_clean(
        {
            "status": "ok",
            "book_rows_1h": rows.get("n", 0),
            "symbols_1h": rows.get("syms", 0),
            "latest_capture": rows.get("latest"),
            "kill_switch": kill,
            "live": bool(rows.get("latest") and rows.get("n", 0) > 0),
            "note": "advisory market-data capture only — never an execution trigger (Rule 9)",
        }
    )


def _schwab_stream_book(query=None):
    """GET /api/v2/schwab/stream/book?symbol=X — latest Level-2 snapshot + book-pressure (advisory evidence)."""
    q = query or {}
    sym = (((q.get("symbol") or [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol")) or "").upper()
    if not sym:
        # all symbols, latest each
        rows = (
            _db_query("""SELECT DISTINCT ON (symbol) symbol, venue, bid_depth, ask_depth, imbalance,
                                   best_bid, best_ask, captured_at
                            FROM schwab_stream_book ORDER BY symbol, captured_at DESC""")
            or []
        )
        return {"books": [_json_clean(r) for r in rows], "advisory": True}
    row = _db_query(
        """SELECT symbol, venue, bid_depth, ask_depth, imbalance, best_bid, best_ask,
                              bid_levels, ask_levels, captured_at
                       FROM schwab_stream_book WHERE symbol=%s ORDER BY captured_at DESC LIMIT 1""",
        (sym,),
        fetch="one",
    )
    if not row:
        return {"status": "no_data", "symbol": sym}
    # trailing pressure: avg imbalance over the last 15 minutes
    trail = (
        _db_query(
            """SELECT round(avg(imbalance),4) avg_imb, count(*) n FROM schwab_stream_book
                         WHERE symbol=%s AND captured_at > NOW()-INTERVAL '15 minutes'""",
            (sym,),
            fetch="one",
        )
        or {}
    )
    out = _json_clean(dict(row))
    out["pressure_15m"] = {
        "avg_imbalance": _json_clean(trail.get("avg_imb")),
        "samples": trail.get("n", 0),
        "read": (
            "bid-heavy (buyers stacked)"
            if (trail.get("avg_imb") or 0) > 0.2
            else "ask-heavy (sellers stacked)"
            if (trail.get("avg_imb") or 0) < -0.2
            else "balanced"
        ),
    }
    out["advisory"] = True
    return out


def _schwab_status(query=None):
    """GET /api/v2/system/schwab-status — Schwab read-only integration monitor: Gate-A token health,
    account-hash links, capability checks, recent sync. Read-only; never exposes token material."""
    import datetime as _dt

    toks = (
        _db_query("""SELECT account_key, refresh_expires_at, next_reauth_due_at, access_expires_at,
                          degraded, last_error, rotation_count, updated_at
                        FROM broker_oauth_tokens WHERE broker='schwab' ORDER BY account_key""")
        or []
    )
    links = {
        r["account_key"]: r
        for r in (
            _db_query("SELECT account_key, masked_last4, verified, last_verified_at FROM schwab_account_links") or []
        )
    }
    sync = (
        _db_query("""SELECT account_key, status, reason, position_count, total_value, wrote_holdings, created_at
                        FROM schwab_sync_history ORDER BY created_at DESC LIMIT 10""")
        or []
    )
    now = _dt.datetime.now(_dt.timezone.utc)
    tokens = []
    for t in toks:
        rexp = t.get("refresh_expires_at")
        days = round((rexp - now).total_seconds() / 86400, 1) if rexp else None
        if t.get("degraded"):
            state = "degraded"
        elif days is None:
            state = "no_token"
        elif days <= 0:
            state = "expired"
        elif days <= 1:
            state = "reauth_due_day6"
        elif days <= 2:
            state = "reauth_due_day5"
        else:
            state = "ok"
        lk = links.get(t["account_key"], {})
        tokens.append(
            {
                "account_key": t["account_key"],
                "state": state,
                "days_remaining": days,
                "refresh_expires_at": _json_clean(t.get("refresh_expires_at")),
                "next_reauth_due_at": _json_clean(t.get("next_reauth_due_at")),
                "access_expires_at": _json_clean(t.get("access_expires_at")),
                "degraded": t.get("degraded"),
                "last_error": t.get("last_error"),
                "rotation_count": t.get("rotation_count"),
                "updated_at": _json_clean(t.get("updated_at")),
                "account_linked": bool(lk.get("verified")),
                "masked_last4": lk.get("masked_last4"),
            }
        )
    caps = (
        _db_query("""SELECT capability_name, status FROM broker_capability_checks
                        WHERE broker ILIKE '%schwab%' ORDER BY capability_name""")
        or []
    )
    return {
        "tokens": tokens,
        "account_links": [
            {
                "account_key": k,
                "masked_last4": v.get("masked_last4"),
                "verified": v.get("verified"),
                "last_verified_at": _json_clean(v.get("last_verified_at")),
            }
            for k, v in links.items()
        ],
        "capabilities": [{"name": c.get("capability_name"), "status": c.get("status")} for c in caps],
        "recent_sync": [
            {**s, "created_at": _json_clean(s.get("created_at")), "total_value": _json_clean(s.get("total_value"))}
            for s in sync
        ],
        "write_locked": True,
        "api_write_enabled": False,
        "note": "Read-only Schwab integration. Writes fenced (NotProvenWrite); api_write_enabled=false; MANUAL_REVIEW.",
    }


_SCHWAB_PROBE_CACHE = {"ts": 0.0, "result": None}


def _schwab_true_login_schedule():
    """Anchor true 7-day OAuth clock to last successful reauth audit row (not rolled DB TTL)."""
    import datetime as _dt

    try:
        row = (
            _db_query("""SELECT max(created_at) AS last_login FROM broker_oauth_token_audit
                           WHERE broker='schwab' AND event='reauth' AND status='ok'""")
            or []
        )
        last = row[0].get("last_login") if row else None
    except Exception:
        last = None
    if not last:
        return {
            "last_true_login": None,
            "true_expiry": None,
            "proactive_due_at": None,
            "due_now": None,
            "days_to_true_expiry": None,
        }
    if getattr(last, "tzinfo", None) is None:
        last = last.replace(tzinfo=_dt.timezone.utc)
    now = _dt.datetime.now(_dt.timezone.utc)
    true_exp = last + _dt.timedelta(days=7)
    due_at = last + _dt.timedelta(days=6)
    days = round((true_exp - now).total_seconds() / 86400, 2)
    return {
        "last_true_login": _json_clean(last),
        "true_expiry": _json_clean(true_exp),
        "proactive_due_at": _json_clean(due_at),
        "due_now": now >= due_at,
        "days_to_true_expiry": days,
    }


def _schwab_token_health(query=None):
    """GET /api/v2/brokers/schwab/token-health — is the Schwab OAuth refresh token actually usable RIGHT
    NOW? Combines the DB freshness health with a CACHED ground-truth live probe (the freshness timestamp
    can read 'valid' while Schwab has revoked the token server-side). Lets the protective-stop card warn
    're-auth needed' BEFORE an order attempt. ?probe=1 forces a fresh probe (else 5-min cache). Read-only;
    never exposes token material.

    Also surfaces true-login schedule fields for the site-wide CC banner + manual reauth page."""
    import time as _t

    q = query or {}
    force = str((q.get("probe") or [""])[0] if isinstance(q.get("probe"), list) else q.get("probe") or "").lower() in (
        "1",
        "true",
        "yes",
    )
    import sys as _sys

    _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
    import schwab_token_manager as tm

    key = tm.canonical_token_key("schwab", "live")
    # canonical_token_key() filters out degraded rows — but a degraded token IS the login that needs
    # re-auth, so fall back to the most recent schwab token row (degraded included) for a precise message.
    if not key:
        _row = (
            _db_query("""SELECT account_key FROM broker_oauth_tokens WHERE broker='schwab'
                            AND environment='live' AND refresh_token_enc IS NOT NULL
                            ORDER BY updated_at DESC LIMIT 1""")
            or []
        )
        key = _row[0]["account_key"] if _row else None
    h = (
        tm.health(key, "schwab", "live")
        if key
        else {
            "has_token": False,
            "degraded": True,
            "refresh_valid": False,
            "last_error": "no token on file — manual OAuth login required",
        }
    )
    # cached live probe (5 min) — only worth probing when a token exists
    probe = _SCHWAB_PROBE_CACHE["result"]
    if key and h.get("has_token") and (force or probe is None or (_t.time() - _SCHWAB_PROBE_CACHE["ts"] > 300)):
        probe = tm.live_probe(key, "schwab", "live")
        _SCHWAB_PROBE_CACHE.update(ts=_t.time(), result=probe)
        if probe.get("needs_reauth"):
            h = tm.health(key, "schwab", "live")  # re-read: live_probe may have just marked it degraded
    needs_reauth = bool(
        (not h.get("has_token"))
        or h.get("degraded")
        or (not h.get("refresh_valid"))
        or (probe and probe.get("needs_reauth"))
    )
    sched = _schwab_true_login_schedule()
    dtr = h.get("days_to_reauth")
    proactive = bool(
        sched.get("due_now")
        or (dtr is not None and float(dtr) <= 1.0)
        or (sched.get("days_to_true_expiry") is not None and float(sched["days_to_true_expiry"]) <= 1.0)
    )
    banner = bool(needs_reauth or proactive)
    msg = (
        "Schwab login expired/revoked — re-authenticate before placing live orders."
        if needs_reauth
        else (
            "Schwab login renewal window — renew via Command Center before true expiry."
            if proactive
            else "Schwab token healthy."
        )
    )
    return {
        "ok": not needs_reauth,
        "broker": "schwab",
        "token_key": key,
        "needs_reauth": needs_reauth,
        "degraded": bool(h.get("degraded")),
        "has_token": bool(h.get("has_token")),
        "refresh_valid": bool(h.get("refresh_valid")),
        "access_fresh": bool(h.get("access_fresh")),
        "days_to_reauth": h.get("days_to_reauth"),
        "refresh_expires_at": h.get("refresh_expires_at"),
        "next_reauth_due_at": h.get("next_reauth_due_at"),
        "last_error": h.get("last_error"),
        "live_probe": (
            {
                "probed": probe.get("probed"),
                "live_ok": probe.get("live_ok"),
                "needs_reauth": probe.get("needs_reauth"),
                "error": probe.get("error"),
            }
            if probe
            else None
        ),
        "reauth_command": f"python3 scripts/schwab_token_manager.py reauth-url {key or 'schwab_taxable'}",
        "manual_reauth_path": "/v3/system/schwab-reauth",
        "show_banner": banner,
        "proactive_due": proactive,
        "due_now": sched.get("due_now"),
        "last_true_login": sched.get("last_true_login"),
        "true_expiry": sched.get("true_expiry"),
        "proactive_due_at": sched.get("proactive_due_at"),
        "days_to_true_expiry": sched.get("days_to_true_expiry"),
        "message": msg,
    }


def _finviz_credential_health(query=None):
    """GET /api/v2/data-sources/finviz/credential-health — live FINVIZ_COOKIE probe + last_error.

    Mirrors Schwab token-health for the site-wide FinvizCookieBanner. Uses
    secret_validators._finviz_cookie (Elite CSV export) and data_source_health.last_error.
    Never returns cookie material.
    """
    from datetime import datetime, timezone

    as_of = datetime.now(timezone.utc).isoformat()
    last_error = None
    try:
        row = (
            _db_query(
                "SELECT last_error, status, last_success_at FROM data_source_health WHERE source_key = %s LIMIT 1",
                ("finviz",),
                fetch="one",
            )
            or {}
        )
        last_error = row.get("last_error")
    except Exception:
        row = {}
        last_error = None
    try:
        import sys as _sys

        _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import secret_validators as _sv
        from credential_monitor import is_finviz_cookie_failure_text

        cookie = _sv._key("FINVIZ_COOKIE")
        if not cookie:
            return {
                "ok": False,
                "status": "missing",
                "detail": "FINVIZ_COOKIE not set",
                "last_error": last_error,
                "as_of": as_of,
                "show_banner": True,
                "message": "Finviz Elite cookie expired — screener and social scalp empty",
                "admin_secrets_path": "/v3/system?tab=Admin",
            }
        ok, detail = _sv._finviz_cookie(cookie)
        err_signal = is_finviz_cookie_failure_text(last_error or "") or is_finviz_cookie_failure_text(detail or "")
        healthy = bool(ok) and not is_finviz_cookie_failure_text(last_error or "")
        if healthy:
            status = "ok"
            message = detail
        else:
            status = "expired" if (not ok or err_signal) else "error"
            message = "Finviz Elite cookie expired — screener and social scalp empty"
        return {
            "ok": healthy,
            "status": status,
            "detail": detail,
            "last_error": last_error,
            "as_of": as_of,
            "show_banner": not healthy,
            "message": message,
            "admin_secrets_path": "/v3/system?tab=Admin",
        }
    except Exception as e:
        return {
            "ok": False,
            "status": "check_failed",
            "detail": str(e)[:160],
            "last_error": last_error,
            "as_of": as_of,
            "show_banner": True,
            "message": "Finviz Elite cookie expired — screener and social scalp empty",
            "admin_secrets_path": "/v3/system?tab=Admin",
        }


def _schwab_reauth_url(query=None):
    """GET /api/v2/brokers/schwab/reauth-url — build Schwab OAuth authorize URL for manual login.
    Operator opens the URL on their phone, completes 2FA, then pastes the 127.0.0.1?code=... redirect
    into POST /api/v2/brokers/schwab/exchange-code (or the CC reauth page). Never exposes secrets."""
    import sys as _sys

    _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
    import schwab_token_manager as tm

    q = query or {}
    raw = q.get("account_key") or q.get("account")
    if isinstance(raw, list):
        raw = raw[0] if raw else None
    key = (
        (raw or "").strip()
        or tm.canonical_token_key("schwab", "live")
        or "schwab_taxable"  # hardcode-ok: canonical OAuth token row
    )
    info = tm.reauth_url(key)
    if not info.get("ok"):
        return {
            "ok": False,
            "error": info.get("reason") or "reauth_url failed",
            "account_key": key,
            "manual_reauth_path": "/v3/system/schwab-reauth",
        }
    return {
        "ok": True,
        "account_key": key,
        "authorize_url": info.get("authorize_url"),
        "code_ttl_hint_min": 5,
        "note": (
            "Open authorize_url on your phone, log in + 2FA, then copy the FULL address-bar URL "
            "(https://127.0.0.1/?code=... — page may not load). Paste into Command Center → "
            "Schwab Reauth → Submit. Codes expire ~5 minutes."
        ),
        "manual_reauth_path": "/v3/system/schwab-reauth",
        "step2": "POST /api/v2/brokers/schwab/exchange-code with {redirect_url, account_key?}",
    }


def _schwab_exchange_code(body=None):
    """POST /api/v2/brokers/schwab/exchange-code — exchange operator-pasted 127.0.0.1?code=... for tokens.
    Body: {redirect_url|code, account_key?}. Never logs the code or full redirect URL."""
    import sys as _sys

    _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
    import schwab_token_manager as tm

    b = body if isinstance(body, dict) else {}
    redirect = (b.get("redirect_url") or b.get("code") or b.get("url") or "").strip()
    if not redirect:
        return {"ok": False, "error": "redirect_url required (full https://127.0.0.1/?code=... URL or bare code)"}
    key = (b.get("account_key") or b.get("account") or "").strip()
    if not key:
        key = tm.canonical_token_key("schwab", "live") or "schwab_taxable"  # hardcode-ok: canonical OAuth token row
    try:
        res = tm.exchange_code(key, redirect)
    except Exception as e:
        return {"ok": False, "error": f"exchange failed: {str(e)[:160]}", "account_key": key}
    if not res.get("ok"):
        return {"ok": False, "error": res.get("reason") or "exchange failed", "account_key": key}
    # Invalidate cached live probe so UI reflects the fresh token immediately
    try:
        _SCHWAB_PROBE_CACHE.update(ts=0.0, result=None)
    except Exception:
        pass
    probe = {}
    try:
        probe = tm.live_probe(key, "schwab", "live") or {}
        _SCHWAB_PROBE_CACHE.update(ts=__import__("time").time(), result=probe)
    except Exception as e:
        probe = {"error": str(e)[:120]}
    return {
        "ok": True,
        "account_key": key,
        "refresh_expires_at": res.get("refresh_expires_at"),
        "next_reauth_due_at": res.get("next_reauth_due_at"),
        "scope": res.get("scope"),
        "live_ok": bool(probe.get("live_ok")),
        "live_probe": (
            {
                "probed": probe.get("probed"),
                "live_ok": probe.get("live_ok"),
                "needs_reauth": probe.get("needs_reauth"),
                "error": probe.get("error"),
            }
            if probe
            else None
        ),
        "message": "Schwab token renewed successfully. Stops/quotes/orders can use the new 7-day login.",
        "manual_reauth_path": "/v3/system/schwab-reauth",
    }


