def _portfolio_sync_run(which):
    """POST /api/v2/portfolio/sync/{snaptrade|schwab} — operator-triggered MANUAL full broker refresh.
    Runs the broker's READ-ONLY pipeline in the background (all --apply, via the protected no-wipe write
    path — no trading, no orders): positions/holdings + transaction ledger + journal round-trip rebuild,
    so both current positions AND new closed trades land on demand without waiting for the cron cadence.
    flock prevents overlap; returns immediately.

    NOTE: broker STOP orders are NOT pulled here — Schwab's stop reconcile is read-only and SnapTrade does
    not return Fidelity stop orders (stops are recorded via the Stop Management desk). Fidelity TRADES only
    appear after the broker posts its ledger overnight, so intraday Fidelity fills won't show same-day."""
    import subprocess

    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    py = os.path.join(root, ".venv", "bin", "python")
    targets = {
        # Fidelity: holdings + activity ledger (trades) + journal round-trip rebuild
        "snaptrade": (
            [
                "scripts/snaptrade_sync.py --apply",
                "scripts/snaptrade_activity_ingest.py --apply",
                "scripts/schwab_journal_builder.py --apply",
            ],
            "/tmp/tradeai_snaptrade_sync.lock",
            "logs/snaptrade_sync.log",
            "Fidelity (holdings + trades + journal)",
        ),
        # Schwab: positions + transaction ledger (trades) + journal round-trip rebuild
        "schwab": (
            [
                "scripts/schwab_position_sync.py --apply",
                "scripts/schwab_transaction_ingest.py --apply",
                "scripts/schwab_journal_builder.py --apply",
            ],
            "/tmp/tradeai_schwab_sync.lock",
            "logs/schwab_ingest.log",
            "Schwab (positions + trades + journal)",
        ),
    }
    if which not in targets:
        return {"ok": False, "error": f"unknown sync target '{which}'"}
    steps, lock, log, label = targets[which]
    inner = " ; ".join(f"{py} {s}" for s in steps)
    try:
        subprocess.Popen(
            ["bash", "-c", f'flock -n {lock} bash -c "{inner}" >> {log} 2>&1'],
            cwd=root,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
        return {
            "ok": True,
            "started": True,
            "target": which,
            "note": f"{label} sync started — positions + new trades refresh in ~30-60s (read-only; no trading; stops not pulled).",
        }
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _deploy_event_tier(ev: dict) -> str:
    meta = ev.get("metadata") or {}
    sc = meta.get("sale_context") or {}
    if sc.get("tier"):
        return str(sc["tier"])
    try:
        proceeds = float(ev.get("proceeds_usd") or 0)
    except (TypeError, ValueError):
        proceeds = 0.0
    inst = str(ev.get("instrument_type") or "").lower()
    if proceeds >= 25000 or inst in ("mutual_fund", "fund"):
        return "major"
    if proceeds >= 10000:
        return "moderate"
    return "minor"


def _deploy_events(query=None):
    """GET /api/v2/deploy/events — post-sale redeploy events (advisory only)."""
    try:
        from datetime import date, timedelta
        from db_adapter import _get_conn
        from lib.deploy_events_db import list_deploy_events

        q = query or {}
        status = str(q.get("status") or "open").strip().lower()
        account = str(q.get("account") or "").strip() or None
        days = int(q.get("days") or 14)
        limit = min(max(int(q.get("limit") or 100), 1), 200)
        material_only = str(q.get("material_only") or "true").lower() in ("1", "true", "yes")
        cur = _get_conn().cursor()
        events = list_deploy_events(
            cur,
            status=None if status in ("all", "any", "") else status,
            account=account,
            limit=limit,
        )
        cutoff = date.today() - timedelta(days=max(1, days))
        filtered = []
        for ev in events:
            sold = ev.get("sold_at")
            if sold is None:
                continue
            if not isinstance(sold, date):
                try:
                    sold = date.fromisoformat(str(sold)[:10])
                except Exception:
                    continue
            if sold >= cutoff:
                ev["sold_at"] = str(sold)
                for ts_key in ("created_at", "updated_at"):
                    if ev.get(ts_key) is not None:
                        ev[ts_key] = str(ev[ts_key])[:19]
                ev["tier"] = _deploy_event_tier(ev)
                if material_only and ev["tier"] == "minor":
                    continue
                filtered.append(ev)
        recent_14d = [
            e
            for e in filtered
            if (date.fromisoformat(str(e.get("sold_at"))[:10]) if e.get("sold_at") else date.min)
            >= date.today() - timedelta(days=14)
        ]
        material_proceeds = sum(
            float(e.get("proceeds_usd") or 0) for e in filtered if e.get("tier") in ("major", "moderate")
        )
        meta0 = (filtered[0].get("metadata") or {}) if filtered else {}
        portfolio_gaps = meta0.get("sleeve_gaps") or []
        for ev in filtered:
            meta = ev.get("metadata") or {}
            pb = meta.get("phase_b") or {}
            if pb.get("plans"):
                ev["institutional_plans_summary"] = [
                    {
                        "archetype": p.get("plan_archetype"),
                        "plan_type": p.get("plan_type"),
                        "confidence": p.get("confidence"),
                        "operator_status": p.get("operator_status"),
                        "deploy_pct_of_net": p.get("deploy_pct_of_net"),
                        "reserve_usd": p.get("reserve_usd"),
                        "leg_count": len(p.get("legs") or []),
                    }
                    for p in pb.get("plans") or []
                ]
                ev["primary_plan_archetype"] = pb.get("primary_archetype")
                ev["pm_memo"] = meta.get("pm_memo")
            if meta.get("phase_a"):
                ev["deployable_cash_usd"] = ev.get("deployable_cash_usd") or meta["phase_a"].get(
                    "reconciliation", {}
                ).get("deployable_cash_usd")
                ev["reconciliation_status"] = ev.get("reconciliation_status") or meta["phase_a"].get(
                    "reconciliation", {}
                ).get("reconciliation_status")
            pc = meta.get("phase_c") or {}
            if pc.get("export_readiness"):
                ev["export_readiness"] = pc["export_readiness"]
            pe = meta.get("phase_e") or {}
            if pe:
                ev["monitoring_summary"] = {
                    "fill_count": pe.get("fill_count"),
                    "restoration_pct": pe.get("restoration_pct"),
                    "last_fill_at": pe.get("last_fill_at"),
                }
            if ev.get("plan_locked_at") or meta.get("plan_lock"):
                ev["plan_lock"] = meta.get("plan_lock") or {
                    "locked_at": str(ev.get("plan_locked_at") or "")[:19],
                    "plan_id": ev.get("locked_plan_id"),
                    "version": ev.get("locked_plan_version"),
                }
            if ev.get("operator_status"):
                ev["operator_status"] = ev.get("operator_status")
            ov = meta.get("oversight") or {}
            if ov:
                ev["oversight_summary"] = {
                    "oversight_status": ov.get("oversight_status"),
                    "operator_status": ov.get("operator_status"),
                    "last_run_at": ov.get("last_run_at"),
                }
        return {
            "ok": True,
            "advisory_only": True,
            "count": len(filtered),
            "recent_14d_count": len(recent_14d),
            "minor_hidden": material_only,
            "material_proceeds_usd": round(material_proceeds, 2),
            "portfolio_gaps": portfolio_gaps[:6],
            "events": filtered,
            "market_context": meta0.get("market_context"),
            "methodology": meta0.get("methodology"),
        }
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _deploy_plans(query=None):
    """GET /api/v2/deploy/plans?event_id= — institutional plans A–G (Phase B)."""
    try:
        from db_adapter import _get_conn
        from lib.redeploy_plan_db import list_plans_for_event

        q = query or {}
        eid = int(q.get("event_id") or q.get("id") or 0)
        if not eid:
            return {"ok": False, "error": "event_id required"}
        version = q.get("version")
        ver = int(version) if version not in (None, "") else None
        cur = _get_conn().cursor()
        plans = list_plans_for_event(cur, eid, version=ver)
        # Readiness is a LIVE governance state: recompute from current oversight_status
        # (an oversight verdict lands after the plan snapshot was persisted; a passed
        # plan must show OPERATOR-READY without waiting for a regeneration that would
        # reset oversight to pending).
        try:
            from lib.redeploy_decision import readiness_state

            cur.execute(
                """SELECT reconciliation_status, locked_plan_id, status,
                                  metadata->'phase_a'->'portfolio_context'->>'is_major_sale'
                           FROM deploy_events WHERE id=%s""",
                (eid,),
            )
            _er = cur.fetchone() or (None, None, None, None)
            _rctx = {
                "settled": str(_er[0] or "") in ("verified", "settled"),
                "is_major": str(_er[3] or "").lower() in ("true", "1"),
                "dismissed": _er[2] == "dismissed",
                "analytics_exist": {},
                "memo_exists": True,
                "audit_exists": True,
                "p0_warnings": [],
            }
            for p in plans:
                _rctx["locked"] = _er[1] is not None and p.get("id") == _er[1]
                p["readiness"] = readiness_state(p, _rctx)
        except Exception:
            pass
        # decision layer (Phases 5/6/14): recommendation + structured memo ride with plans
        recommendation, memo, generated_basis = None, None, None
        try:
            cur.execute(
                "SELECT metadata, locked_plan_id, locked_plan_version, operator_status FROM deploy_events WHERE id=%s",
                (eid,),
            )
            row = cur.fetchone()
            meta = row[0] if row else {}
            if isinstance(meta, str):
                import json as _json

                meta = _json.loads(meta)
            bundle = (meta or {}).get("phase_b") or {}
            recommendation = (meta or {}).get("recommendation") or bundle.get("recommendation")
            memo = (meta or {}).get("pm_memo_structured") or bundle.get("pm_memo_structured")
            # PM memo is generated at plan-build time; status fields must render LIVE
            # (P1-1: memo said 'oversight: pending' after the lanes passed). DB is
            # authoritative for governance; the memo text is advisory.
            try:
                if memo and isinstance(memo.get("sections"), dict):
                    _lp_id = row[1]
                    _live_plan = next((p2 for p2 in plans if p2.get("id") == _lp_id), None) or next(
                        (
                            p2
                            for p2 in plans
                            if p2.get("plan_archetype")
                            == ((recommendation or {}).get("primary") or {}).get("archetype")
                        ),
                        None,
                    )
                    if _live_plan:
                        _ov = _live_plan.get("oversight_status")
                        _rd = (_live_plan.get("readiness") or {}).get("display")
                        memo = dict(memo)
                        memo["sections"] = dict(memo["sections"])
                        memo["sections"]["oversight_conclusion"] = (
                            f"Oversight status: {_ov} (live from database"
                            + (f"; readiness: {_rd}" if _rd else "")
                            + ")."
                        )
            except Exception:
                pass
            generated_basis = {
                "settled_basis": bundle.get("settled_basis"),
                "regime_basis": bundle.get("regime_basis"),
                "generator_version": bundle.get("generator_version"),
            }
            locked = {"locked_plan_id": row[1], "locked_plan_version": row[2], "operator_status": row[3]} if row else {}
        except Exception:
            locked = {}
        return {
            "ok": True,
            "advisory_only": True,
            "event_id": eid,
            "plans": plans,
            "recommendation": recommendation,
            "pm_memo_structured": memo,
            "generation_basis": generated_basis,
            **(locked or {}),
        }
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _deploy_export(query=None):
    """GET /api/v2/deploy/export — trade plan JSON/CSV (Phase C; fresh quotes required)."""
    try:
        from db_adapter import _get_conn
        from lib.entry_planner_adapter import enrich_event_phase_c, export_trade_plan
        from lib.redeploy_plan_db import fetch_deploy_event, fetch_institutional_plan

        q = query or {}
        eid = int(q.get("event_id") or q.get("id") or 0)
        if not eid:
            return {"ok": False, "error": "event_id required"}
        plan_id = q.get("plan_id")
        pid = int(plan_id) if plan_id not in (None, "") else None
        archetype = (q.get("archetype") or q.get("plan_archetype") or "F").upper()[:1]
        fmt = (q.get("format") or "json").lower()
        force = str(q.get("force_stale") or "").lower() in ("1", "true", "yes")
        version = q.get("version")
        ver = int(version) if version not in (None, "") else None
        cur = _get_conn().cursor()
        event = fetch_deploy_event(cur, eid)
        if not event:
            return {"ok": False, "error": "event_not_found"}
        event = enrich_event_phase_c(event)
        meta = event.get("metadata") or {}
        plans = (meta.get("phase_b") or {}).get("plans") or []
        plan = None
        if pid:
            db_plan = fetch_institutional_plan(cur, eid, plan_id=pid, version=ver)
            if db_plan:
                arch = db_plan.get("plan_archetype")
                plan = next((p for p in plans if p.get("plan_archetype") == arch), db_plan)
        else:
            plan = next((p for p in plans if p.get("plan_archetype") == archetype), None)
            if not plan:
                plan = fetch_institutional_plan(
                    cur,
                    eid,
                    archetype=archetype,
                    version=ver,
                )
        if not plan:
            return {"ok": False, "error": "plan_not_found"}
        # Governance projection gate (adjudication): a LOCKED plan's export must carry the
        # canonical governance block and FAIL when any surface disagrees — force_stale is a
        # quotes-only override and never bypasses governance consistency.
        governance = None
        try:
            from lib.redeploy_oversight import governance_projection

            cur.execute("SELECT locked_plan_id FROM deploy_events WHERE id=%s", (eid,))
            _lp = (cur.fetchone() or [None])[0]
            if _lp:
                governance = governance_projection(cur, eid)
                exporting_locked = (
                    (pid == _lp)
                    or (pid is None and plan.get("id") == _lp)
                    or (str(plan.get("plan_archetype") or "") == str(governance.get("plan_archetype") or ""))
                )
                if exporting_locked and not governance.get("consistent"):
                    return {
                        "ok": False,
                        "error": "governance_mismatch",
                        "mismatches": governance.get("mismatches"),
                        "hint": "locked-plan export refused until every governance surface agrees",
                    }
        except Exception as _ge:
            return {"ok": False, "error": f"governance_projection_failed: {str(_ge)[:120]}"}
        result = export_trade_plan(event, plan, fmt=fmt, force_stale=force)
        if isinstance(result, dict) and result.get("trade_plan") is not None and governance:
            tp = result["trade_plan"]
            tp["governance"] = governance
            tp["operator_status"] = governance.get("operator_status")
            tp["oversight_status"] = governance.get("oversight_status")
            tp["readiness_status"] = governance.get("readiness_status")
            tp["event_status"] = governance.get("event_operator_status")
            tp["capital_status"] = governance.get("capital_status")
            tp["locked_plan_id"] = governance.get("plan_id")
            tp["locked_plan_version"] = governance.get("plan_version")
            tp["implementation_review_approved"] = governance.get("implementation_review_approved")
            tp["locked_at"] = governance.get("locked_at")
            tp["locked_by"] = governance.get("locked_by")
            tp["oversight_completed_at"] = governance.get("oversight_completed_at")
            tp["oversight_run_ids"] = governance.get("oversight_run_ids")
            tp["calculation_snapshot_id"] = governance.get("calculation_snapshot_id")
            tp["quote_snapshot_id"] = max((str(l.get("price_as_of") or "") for l in tp.get("legs") or []), default=None)
            tp["packet_generated_at"] = tp.get("generated_at")
        try:
            from lib.redeploy_audit import audit_log

            exported_ok = isinstance(result, str) or result.get("ok", True)
            audit_log(
                cur,
                eid,
                "export_requested",
                plan_id=pid,
                actor="operator",
                new_value=f"plan {plan.get('plan_archetype')} fmt={fmt} "
                f"{'ok' if exported_ok else 'blocked:' + str(result.get('error'))}",
            )
            cur.connection.commit()
        except Exception:
            pass
        if isinstance(result, str):
            return {"ok": True, "format": "csv", "content": result, "advisory_only": True}
        if not result.get("ok", True) and result.get("error"):
            return result
        return result
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


