                if entry <= 0 or stop <= 0 or shares <= 0:
                    return 400, {
                        "ok": False,
                        "error": f"{symbol} missing trade plan (entry={entry:.2f} stop={stop:.2f} shares={shares})",
                    }
                import sys as _sys

