    if method == "POST" and base_path == "/api/v2/paper-proposals/approve":
        audit_id = None
        _audit_conn = None
        try:
            body = body or {}
            pid = body.get("proposal_id")
            if not pid:
                return 400, {"ok": False, "error": "proposal_id required"}
            confirmed = body.get("confirmed", False)
            approval_mode = body.get("approval_mode", "approve_ready")

            # ── AUDIT: Create audit attempt before any gates ──
            import sys as _sys

            _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
            try:
                from phase6_approval_audit import (
                    create_approval_audit_attempt,
                    update_approval_audit,
                    append_approval_audit_event,
                    finalize_approval_audit,
                )
                from session13_db import get_conn as _get_audit_conn

                _audit_conn = _get_audit_conn()
                # Load proposal snapshot for audit
                _prop_snap = _db_query("SELECT * FROM paper_trade_proposals WHERE id=%s", [int(pid)], fetch="one") or {}
                _prop_snap["proposal_id"] = int(pid)
                audit_id = create_approval_audit_attempt(
                    _audit_conn,
                    _prop_snap,
                    requested_by=body.get("requested_by", "dashboard"),
                    request_source="api",
                    metadata={"confirmed": confirmed, "approval_mode": approval_mode},
                )
                append_approval_audit_event(
                    _audit_conn, audit_id, "approval_started", "ok", message=f"Approval attempt for proposal #{pid}"
                )
            except Exception as _audit_err:
                # Fail closed: if audit creation fails, block approval
                return 400, {
                    "ok": False,
                    "error": f"Approval audit could not be created; approval blocked fail-closed. ({_audit_err})",
                    "approval_audit": {"audit_id": None, "status": "error_fail_closed", "audit_created": False},
                }

            # Check decision state before approving
            rp = _db_query(
                """
                SELECT packet_status, research_score, confidence_score
                FROM proposal_research_packets WHERE proposal_id = %s
                ORDER BY updated_at DESC LIMIT 1
            """,
                [int(pid)],
                fetch="one",
            )

            if rp:
                ds = rp.get("packet_status", "")
                blocked_states = (
                    "BLOCKED_BY_RISK_GATE",
                    "RESEARCH_INCOMPLETE",
                    "AI_REVIEW_MISSING",
                    "DATA_STALE",
                    "REJECT_RECOMMENDED",
                )
                if ds in blocked_states and not confirmed:
                    if _audit_conn and audit_id:
                        finalize_approval_audit(
                            _audit_conn, audit_id, "blocked_research", f"Research packet blocked: {ds}"
                        )
                    return 400, {
                        "ok": False,
                        "error": f"Cannot approve: {ds}. Run research first or use confirmation.",
                        "decision_state": ds,
                        "approval_audit": {"audit_id": audit_id, "status": "blocked_research", "audit_created": True},
                    }
                cautious_states = ("CAUTIOUS_PAPER_TEST", "BACKTEST_INSUFFICIENT")
                if ds in cautious_states and not confirmed:
                    if _audit_conn and audit_id:
                        finalize_approval_audit(
                            _audit_conn, audit_id, "blocked_needs_confirmation", f"Requires confirmation: {ds}"
                        )
                    return 400, {
                        "ok": False,
                        "error": f"Requires confirmation: {ds}",
                        "decision_state": ds,
                        "needs_confirmation": True,
                        "approval_audit": {
                            "audit_id": audit_id,
                            "status": "blocked_needs_confirmation",
                            "audit_created": True,
                        },
                    }
                if ds in cautious_states:
                    approval_mode = (
                        "cautious_confirmed" if ds == "CAUTIOUS_PAPER_TEST" else "first_sample_learning_confirmed"
                    )

            # ── GATE: Proposal Freshness (Phase 6D) ──
            _proposal_freshness = None
            try:
                from phase6_proposal_staleness_policy import classify_proposal_staleness

                _proposal_freshness = classify_proposal_staleness(_prop_snap)
            except Exception as _pf_err:
                _proposal_freshness = {
                    "fresh": False,
                    "status": "error",
                    "reason": f"Freshness check error: {_pf_err}. Blocked fail-closed.",
                }

            if _audit_conn and audit_id:
                update_approval_audit(
                    _audit_conn,
                    audit_id,
                    gate="proposal_freshness",
                    gate_passed=_proposal_freshness.get("fresh", False),
                    fields={"quote_age_minutes": _proposal_freshness.get("age_minutes")},
                )
                append_approval_audit_event(
                    _audit_conn,
                    audit_id,
                    "proposal_freshness",
                    "fresh" if _proposal_freshness.get("fresh") else "stale",
                    message=_proposal_freshness.get("reason", ""),
                )

            if _proposal_freshness.get("status") == "terminal":
                pass  # Terminal proposals will be caught by the status check above
            elif not _proposal_freshness.get("fresh", False) and _proposal_freshness.get("status") != "terminal":
                if _audit_conn and audit_id:
                    finalize_approval_audit(
                        _audit_conn,
                        audit_id,
                        "blocked_stale_proposal",
                        _proposal_freshness.get("reason", "Proposal is stale"),
                    )
                if _audit_conn:
                    try:
                        _audit_conn.close()
                    except Exception:
                        pass
                return 400, {
                    "ok": False,
                    "error": _proposal_freshness.get(
                        "reason", "Proposal is stale or expired. Refresh before approving."
                    ),
                    "message": _proposal_freshness.get("reason", "Proposal is stale or expired."),
                    "proposal_freshness": _proposal_freshness,
                    "market_session_policy": None,
                    "market_revalidation": None,
                    "approval_audit": {
                        "audit_id": audit_id,
                        "status": "blocked_stale_proposal",
                        "gate_sequence": ["proposal_freshness"],
                        "audit_created": True,
                    },
                }

            # ── GATE: Market Session Policy (Phase 6B) ──
            _session_policy = None
            try:
                from phase6_market_session_policy import classify_market_session

                _session_policy = classify_market_session()
            except Exception as _sp_err:
                _session_policy = {
                    "ok": False,
                    "session": "unknown",
                    "allowed": False,
                    "reason": f"Session classification error: {_sp_err}. Blocked fail-closed.",
                }

            if _audit_conn and audit_id:
                update_approval_audit(
                    _audit_conn,
                    audit_id,
                    session_policy=_session_policy,
                    gate="session_policy",
                    gate_passed=_session_policy.get("allowed", False),
                )
                append_approval_audit_event(
                    _audit_conn,
                    audit_id,
                    "session_policy",
                    "passed" if _session_policy.get("allowed") else "blocked",
                    message=_session_policy.get("reason", ""),
                )

            if not _session_policy.get("allowed", False):
                if _audit_conn and audit_id:
                    finalize_approval_audit(
                        _audit_conn, audit_id, "blocked_session", _session_policy.get("reason", "Session blocked")
                    )
                if _audit_conn:
                    try:
                        _audit_conn.close()
                    except Exception:
                        pass
                return 400, {
                    "ok": False,
                    "error": _session_policy.get("reason", "Approval blocked: market session not allowed."),
                    "message": _session_policy.get("reason", "Approval blocked: market session not allowed."),
                    "market_session_policy": _session_policy,
                    "market_revalidation": None,
                    "approval_audit": {
                        "audit_id": audit_id,
                        "status": "blocked_session",
                        "gate_sequence": ["session_policy"],
                        "audit_created": True,
                    },
                }

            _route_key = str((_prop_snap.get("intended_broker") or _prop_snap.get("target_account") or "")).lower()
            if _route_key.startswith("schwab") or _route_key.startswith("fidelity"):
                if _audit_conn and audit_id:
                    finalize_approval_audit(
                        _audit_conn,
                        audit_id,
                        "blocked_live_routed",
                        "Proposal routed for live broker — use Broker Proposals (Path B)",
                    )
                if _audit_conn:
                    try:
                        _audit_conn.close()
                    except Exception:
                        pass
                return 400, {
                    "ok": False,
                    "error": "Proposal is routed for live broker (Path B). Use Broker Proposals — not paper approve.",
                    "execution_path": "live",
                    "approval_audit": {"audit_id": audit_id, "status": "blocked_live_routed", "audit_created": True},
                }

            from paper_trade_logger import approve_proposal

            result = approve_proposal(
                int(pid),
                override_shares=body.get("shares"),
                override_entry=body.get("entry"),
                override_stop=body.get("stop"),
                override_target=body.get("target"),
            )

            # ── AUDIT: Record market revalidation + risk gate results from approve_proposal ──
            mr = result.get("market_revalidation") or {}
            if _audit_conn and audit_id:
                reval_passed = result.get("success", False) or mr.get("passed", False)
                update_approval_audit(
                    _audit_conn,
                    audit_id,
                    market_revalidation=mr,
                    gate="market_revalidation",
                    gate_passed=mr.get("passed", False),
                    fields={
                        "live_price": mr.get("live_price"),
                        "adjusted_entry": mr.get("adjusted_entry"),
                        "rr_at_approval": mr.get("live_rr"),
                        "spread_pct": mr.get("live_spread_pct"),
                        "quote_age_minutes": (mr.get("quote_age_seconds") or 0) / 60
                        if mr.get("quote_age_seconds")
                        else None,
                    },
                )
                append_approval_audit_event(
                    _audit_conn,
                    audit_id,
                    "market_revalidation",
                    "passed" if mr.get("passed") else "blocked",
                    message=mr.get("message", ""),
                )

                if not mr.get("passed", True) and not result.get("success"):
                    finalize_approval_audit(
                        _audit_conn,
                        audit_id,
                        "blocked_market_revalidation",
                        result.get("message", "Market revalidation blocked"),
                    )
                elif result.get("risk_gate") and result.get("risk_gate") != "APPROVED" and not result.get("success"):
                    # Risk gate blocked
                    update_approval_audit(
                        _audit_conn,
                        audit_id,
                        risk_gate={"result": result.get("risk_gate"), "codes": result.get("blockers", [])},
                        gate="risk_gate",
                        gate_passed=False,
                    )
                    finalize_approval_audit(
                        _audit_conn, audit_id, "blocked_risk_gate", result.get("message", "Risk gate blocked")
                    )
                    append_approval_audit_event(
                        _audit_conn, audit_id, "risk_gate", "blocked", message=result.get("message", "")
                    )
                elif result.get("success"):
                    # Both gates passed — record risk gate pass + paper trade creation
                    update_approval_audit(
                        _audit_conn,
                        audit_id,
                        risk_gate={"result": result.get("risk_gate", "APPROVED")},
                        gate="risk_gate",
                        gate_passed=True,
                    )
                    append_approval_audit_event(_audit_conn, audit_id, "risk_gate", "passed")
                    update_approval_audit(
                        _audit_conn,
                        audit_id,
                        paper_trade={
                            "paper_trade_id": result.get("paper_trade_id"),
                            "entry": result.get("entry"),
                            "stop": result.get("stop"),
                            "target": result.get("target"),
                            "shares": result.get("shares"),
                        },
                        gate="paper_trade",
                        gate_passed=True,
                    )
                    append_approval_audit_event(
                        _audit_conn,
                        audit_id,
                        "paper_trade_created",
                        "ok",
                        message=f"Paper trade #{result.get('paper_trade_id')} created",
                    )
                else:
                    # Generic failure (e.g., trade creation failed)
                    finalize_approval_audit(
                        _audit_conn, audit_id, "failed_trade_creation", result.get("message", "Approval failed")
                    )

            # Store research packet metadata on the paper trade
            if result.get("success") and result.get("paper_trade_id") and rp:
                try:
                    votes = _db_query(
                        """
                        SELECT json_object_agg(agent_name, json_build_object('vote', vote, 'confidence', confidence))
                        FROM proposal_agent_reviews WHERE proposal_id = %s
                    """,
                        [int(pid)],
                        fetch="one",
                    )
                    _db_query(
                        """
                        UPDATE paper_trades SET
                            research_packet_id = (SELECT id FROM proposal_research_packets WHERE proposal_id = %s LIMIT 1),
                            decision_state = %s,
                            confidence_score = %s,
                            agent_votes = %s,
                            backtest_quality = (SELECT backtest_quality FROM proposal_backtest_snapshots WHERE proposal_id = %s LIMIT 1),
                            approval_mode = %s
                        WHERE id = %s
                    """,
                        [
                            int(pid),
                            ds if rp else None,
                            rp.get("confidence_score") if rp else None,
                            json.dumps(votes.get("json_object_agg") if votes else None),
                            int(pid),
                            approval_mode,
                            result["paper_trade_id"],
                        ],
                    )
                except Exception:
                    pass

            # Get updated status
            new_status = None
            try:
                _ns = _db_query("SELECT status FROM paper_trade_proposals WHERE id=%s", [int(pid)], fetch="one")
                new_status = _ns.get("status") if _ns else None
            except Exception:
                pass

            # ── INSTANT EXECUTION: paper submit only when not routed to Schwab/Fidelity ──
            alpaca_result = None
            _route_key = str((_prop_snap.get("intended_broker") or _prop_snap.get("target_account") or "")).lower()
            _broker_routed = _route_key.startswith("schwab") or _route_key.startswith("fidelity")
            if result.get("success") and result.get("paper_trade_id") and not _broker_routed:
                try:
                    from proposal_paper_submitter import submit_paper
                    from session13_db import get_conn as _get_sub_conn

                    _sub_conn = _get_sub_conn()
                    if _sub_conn:
                        alpaca_result = submit_paper(_sub_conn, int(pid), dry_run=False)
                        _sub_conn.close()
                        if alpaca_result and alpaca_result.get("status") == "submitted":
                            print(f"  [instant-exec] {body.get('proposal_id')}: Alpaca paper order submitted")
                except Exception as _alpaca_err:
                    alpaca_result = {"status": "failed", "error": str(_alpaca_err)}
                    print(f"  [instant-exec] Alpaca submit failed: {_alpaca_err}")

            # ── AUDIT: Record Alpaca submission and finalize ──
            if _audit_conn and audit_id:
                if alpaca_result:
                    alp_ok = alpaca_result.get("status") == "submitted"
                    update_approval_audit(
                        _audit_conn,
                        audit_id,
                        alpaca_response=alpaca_result,
                        gate="alpaca_submission",
                        gate_passed=alp_ok,
                    )
                    append_approval_audit_event(
                        _audit_conn,
                        audit_id,
                        "alpaca_submission",
                        "submitted" if alp_ok else "failed",
                        message=str(alpaca_result.get("status", "")),
                    )
                if result.get("success"):
                    final_status = (
                        "approved_paper_submitted"
                        if (alpaca_result and alpaca_result.get("status") == "submitted")
                        else "approved_pending_submission"
                    )
                    finalize_approval_audit(_audit_conn, audit_id, final_status, result.get("message", "Approved"))

            # Build approval_audit response
            _audit_resp = {"audit_id": audit_id, "status": "unknown", "audit_created": audit_id is not None}
            if _audit_conn and audit_id:
                try:
                    _ar = _db_query(
                        "SELECT approval_status, gate_sequence FROM paper_proposal_approval_audit WHERE id=%s",
                        [audit_id],
                        fetch="one",
                    )
                    if _ar:
                        _audit_resp["status"] = _ar.get("approval_status", "unknown")
                        _audit_resp["gate_sequence"] = _ar.get("gate_sequence", [])
                except Exception:
                    pass
            if _audit_conn:
                try:
                    _audit_conn.close()
                except Exception:
                    pass

            return 200 if result.get("success") else 400, {
                "ok": result.get("success", False),
                "proposal_id": int(pid),
                "old_status": "PENDING",
                "new_status": new_status or "APPROVED",
                "message": result.get(
                    "message", "Approved for paper test" if result.get("success") else "Approval failed"
                ),
                "paper_trade_id": result.get("paper_trade_id"),
                "blockers": result.get("blockers", []),
                "proposal_freshness": _proposal_freshness,
                "market_session_policy": _session_policy,
                "market_revalidation": result.get("market_revalidation"),
                "approval_audit": _audit_resp,
                "alpaca_submission": alpaca_result,
                "data": result,
            }
        except Exception as e:
            # ── AUDIT: Record unexpected error fail-closed ──
            if _audit_conn and audit_id:
                try:
                    finalize_approval_audit(_audit_conn, audit_id, "error_fail_closed", str(e)[:500])
                    append_approval_audit_event(_audit_conn, audit_id, "error", "fail_closed", message=str(e)[:500])
                except Exception:
                    pass
            if _audit_conn:
                try:
                    _audit_conn.close()
                except Exception:
                    pass
            return 500, {
                "ok": False,
                "error": str(e),
                "message": str(e),
                "approval_audit": {
                    "audit_id": audit_id,
                    "status": "error_fail_closed",
                    "audit_created": audit_id is not None,
                },
            }

