    # Session 25: Pipeline health master
    if method == "GET" and base_path == "/api/v2/pipeline-health-master":
        try:
            from datetime import datetime as _dt, timezone as _tz

            STAGE_REGISTRY = {
                "data_collection": [
                    ("finviz_screener_runner", "Finviz Screener", 6),
                    ("social_ingest", "Social Ingest", 24),
                    ("news_ingestion", "News Ingestion", 6),
                    ("fred_data_ingest", "FRED Data", 24),
                    ("sec_data_ingest", "SEC Data", 24),
                ],
                "enrichment": [
                    ("finviz_enrichment", "Finviz Enrichment", 6),
                    # catalyst_enrichment removed — library module called by continuous_runner/daily_incubator_refresh
                    ("symbol_enrichment", "Symbol Enrichment", 12),
                    ("rag_indexer", "RAG Indexer", 8),
                ],
                "scoring": [
                    ("trade_ai_orchestrator", "Orchestrator", 3),
                    ("indicator_engine", "Indicators", 24),
                    ("premarket_watcher", "Premarket", 1),
                    ("agent_router", "Agent Router", 24),
                ],
                "intelligence": [
                    ("process_watchlist_agent_jobs", "Agent Jobs", 0.25),
                    ("agent_watchlist_engine", "Watchlist Engine", 24),
                    ("cio_decision_engine", "CIO Engine", 24),
                    ("pipeline_watchdog", "Watchdog", 0.083),
                ],
                "proposals": [
                    ("weekly_incubator_builder", "Incubator Builder", 168),
                    ("daily_incubator_refresh", "Incubator Refresh", 24),
                    ("incubator_rolloff_engine", "Rolloff Engine", 24),
                    ("incubator_proposal_promoter", "Proposal Promoter", 12),
                    ("proposal_enrichment_loop", "Enrichment Loop", 0.083),
                    ("proposal_lifecycle", "Lifecycle", 0.5),
                ],
                "execution": [
                    ("risk_gate", "Risk Gate", 0),
                    # alpaca_paper, broker_reconciliation, execution_quality removed — no standalone scripts
                ],
                "overnight": [
                    ("overnight_batch", "Overnight Batch", 24),
                    ("agent_outcome_scorer", "Outcome Scorer", 24),
                    ("strategy_weekly_review", "Weekly Review", 168),
                    # overnight_batch_embeddings removed — no standalone script
                ],
            }
            GROUP_LABELS = {
                "data_collection": ("Data Collection", "6-7 AM M-F"),
                "enrichment": ("Enrichment", "7-8 AM M-F"),
                "scoring": ("Scoring", "8-9 AM M-F"),
                "intelligence": ("Intelligence", "Continuous"),
                "proposals": ("Proposal Pipeline", "The bridge"),
                "execution": ("Execution", "Market hours"),
                "overnight": ("Overnight", "8 PM - 6 AM"),
            }
            now = _dt.now(tz=_tz.utc)
            groups = []
            total_stages = 0
            healthy = 0
            warnings = 0
            critical = 0
            never_run = 0
            latest_run_ts = None
            for group_id, stages in STAGE_REGISTRY.items():
                label, desc = GROUP_LABELS[group_id]
                stage_list = []
                for script_name, display, cadence_h in stages:
                    total_stages += 1
                    # Check both pipeline_runs (new telemetry) and pipeline_stage_runs (old orchestrator)
                    row = _db_query(
                        """
                        SELECT status, started_at, finished_at as completed_at,
                               (summary->>'rows_produced')::int as rows_processed,
                               duration_seconds as duration_sec,
                               summary->>'errors' as error_message
                        FROM pipeline_runs WHERE pipeline_key=%s ORDER BY started_at DESC LIMIT 1
                    """,
                        [script_name],
                        fetch="one",
                    )
                    if not row or not row.get("started_at"):
                        row = (
                            _db_query(
                                """
                            SELECT status, started_at, finished_at as completed_at,
                                   NULL::int as rows_processed,
                                   duration_seconds as duration_sec,
                                   error_message
                            FROM pipeline_stage_runs WHERE stage_key=%s ORDER BY started_at DESC LIMIT 1
                        """,
                                [script_name],
                                fetch="one",
                            )
                            or row
                        )
                    last_run_at = None
                    last_status = None
                    rows_processed = 0
                    duration_sec = None
                    error_msg = None
                    minutes_ago = None
                    if row:
                        last_run_at = _json_clean(row.get("started_at"))
                        last_status = row.get("status")
                        rows_processed = row.get("rows_processed") or 0
                        duration_sec = _json_clean(row.get("duration_sec"))
                        error_msg = row.get("error_message")
                        if row.get("started_at"):
                            td = now - row["started_at"]
                            minutes_ago = int(td.total_seconds() / 60)
                            if latest_run_ts is None or row["started_at"] > latest_run_ts:
                                latest_run_ts = row["started_at"]
                    # Fallback: check log file mtime for scripts without DB telemetry
                    if last_run_at is None:
                        _log_path = PROJECT_ROOT / "logs" / f"{script_name}.log"
                        if _log_path.exists():
                            _log_mtime = _dt.fromtimestamp(_log_path.stat().st_mtime, tz=_tz.utc)
                            last_run_at = _json_clean(_log_mtime)
                            last_status = "completed"  # log exists = script ran
                            minutes_ago = int((now - _log_mtime).total_seconds() / 60)
                            if latest_run_ts is None or _log_mtime > latest_run_ts:
                                latest_run_ts = _log_mtime

                    # Weekend awareness
                    import pytz as _ptz

                    _et_now = _dt.now(_ptz.timezone("US/Eastern"))
                    _is_weekend = _et_now.weekday() >= 5

                    # Derive color (calendar-aware)
                    if last_status == "running":
                        color = "blue"
                    elif last_status == "test_artifact":
                        color = "amber"
                        warnings += 1
                    elif last_status == "failed":
                        color = "red"
                        critical += 1
                    elif last_run_at is None:
                        # Never-run is never healthy — mark as gray/amber
                        never_run += 1
                        if cadence_h > 0 and cadence_h < 168:
                            color = "amber"
                            warnings += 1
                        else:
                            color = "gray"
                    elif cadence_h == 0:
                        color = "green" if last_status == "success" else "red"
                        if color == "green":
                            healthy += 1
                        else:
                            critical += 1
                    else:
                        hours_since = (minutes_ago or 99999) / 60
                        # On weekends, relax thresholds (most stages don't run)
                        _mult = 4 if _is_weekend else 2
                        _warn_mult = 3 if _is_weekend else 1.5
                        if hours_since > cadence_h * _mult:
                            color = "red" if not _is_weekend else "amber"
                            if color == "red":
                                critical += 1
                            else:
                                warnings += 1
                        elif hours_since > cadence_h * _warn_mult:
                            color = "amber"
                            warnings += 1
                        else:
                            color = "green"
                            healthy += 1
                    # PIPE-OPS-2: Add owner metadata
                    _owner = {}
                    try:
                        from pipeline_stage_owner_map import get_stage_owner

                        _owner = get_stage_owner(script_name) or {}
                    except ImportError:
                        pass

                    # Never-run subtype
                    _nr_subtype = None
                    if last_run_at is None:
                        if not _owner.get("owning_script"):
                            _nr_subtype = "never_run_owner_unknown"
                        elif _owner.get("safe_dry_run_cmd") is None and script_name in (
                            "risk_gate",
                            "tradeai_automated",
                        ):
                            _nr_subtype = "never_run_on_demand"
                        elif cadence_h >= 168:
                            _nr_subtype = "never_run_on_demand"
                        else:
                            _nr_subtype = "never_run_telemetry_missing"

                    # Recommended action
                    _action = _owner.get("operator_next_action", "Review stage configuration")
                    if color == "green":
                        _action = "No action needed"
                    elif _nr_subtype == "never_run_on_demand":
                        _action = _owner.get("operator_next_action", "On-demand — no daily action expected")

                    stage_list.append(
                        {
                            "id": script_name,
                            "label": display,
                            "status_color": color,
                            "last_run_at": last_run_at,
                            "last_status": last_status,
                            "rows_processed": rows_processed,
                            "duration_sec": duration_sec,
                            "error_message": error_msg,
                            "cadence_h": cadence_h,
                            "minutes_ago": minutes_ago,
                            "owner_script": _owner.get("owning_script"),
                            "owner_wrapper": _owner.get("owning_wrapper"),
                            "cron_pattern": _owner.get("cron_pattern"),
                            "log_paths": _owner.get("log_paths", []),
                            "output_tables": _owner.get("output_tables", []),
                            "failure_hint": _owner.get("failure_hint"),
                            "recommended_action": _action,
                            "never_run_subtype": _nr_subtype,
                            "warning_reason": (
                                "Test artifact — last run was manual test"
                                if last_status == "test_artifact"
                                else "Weekly schedule — next run per cron"
                                if color == "amber" and cadence_h >= 168
                                else "On-demand — runs when triggered"
                                if cadence_h == 0
                                else f"Stale — last ran {minutes_ago // 60}h ago (expected every {cadence_h}h)"
                                if color == "amber" and minutes_ago and minutes_ago > cadence_h * 60
                                else None
                            ),
                            "safe_dry_run_cmd": _owner.get("safe_dry_run_cmd"),
                        }
                    )
                groups.append(
                    {
                        "id": group_id,
                        "label": label,
                        "description": desc,
                        "stages": stage_list,
                    }
                )
            return 200, {
                "ok": True,
                "summary": {
                    "healthy": healthy,
                    "warnings": warnings,
                    "critical": critical,
                    "total_stages": total_stages,
                    "never_run": never_run,
                    "last_full_cycle": latest_run_ts.strftime("%I:%M %p") if latest_run_ts else "No runs recorded",
                },
                "groups": groups,
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path.startswith("/api/v2/journal/trade-detail/"):

        def _deep_clean(obj):
            if isinstance(obj, Decimal):
                return float(obj)
            if hasattr(obj, "isoformat"):
                return obj.isoformat()
            if isinstance(obj, dict):
                return {k: _deep_clean(v) for k, v in obj.items()}
            if isinstance(obj, (list, tuple)):
                return [_deep_clean(i) for i in obj]
            if isinstance(obj, bytes):
                return obj.decode("utf-8", errors="replace")
            return obj

        try:
            _td_id = int(base_path.rsplit("/", 1)[-1])
            _td = _db_query("SELECT * FROM paper_trades WHERE id = %s", [_td_id], fetch="one")
            if not _td:
                return 404, {"ok": False, "error": "Trade not found"}
            _td_key = f"paper-{_td['symbol']}-{_td_id}"
            _td_review = _db_query("SELECT * FROM journal_trade_reviews WHERE trade_key = %s", [_td_key], fetch="one")
            _td_thesis = _db_query(
                "SELECT * FROM trade_thesis_outcomes WHERE paper_trade_id = %s", [_td_id], fetch="one"
            )
            _td_events = (
                _db_query(
                    "SELECT agent_name, event_type, event_summary, payload, created_at FROM agent_curation_events WHERE paper_trade_id = %s ORDER BY created_at",
                    [_td_id],
                )
                or []
            )
            _td_analysis = _db_query(
                "SELECT model_used, summary, worked_reasons, failed_reasons, lessons, suggested_rule_changes, confidence, created_at FROM paper_trade_analysis WHERE paper_trade_id = %s ORDER BY created_at DESC LIMIT 1",
                [_td_id],
                fetch="one",
            )
            _td_risk = (
                _db_query(
                    "SELECT action_type, old_value, new_value, trigger_price, trigger_reason, created_at FROM paper_trade_risk_actions WHERE paper_trade_id = %s ORDER BY created_at",
                    [_td_id],
                )
                or []
            )
            _td_alerts = (
                _db_query(
                    "SELECT alert_type, severity, title, message, created_at FROM open_trade_alerts WHERE paper_trade_id = %s ORDER BY created_at",
                    [_td_id],
                )
                or []
            )
            _td_proposal = None
            if _td.get("proposal_id"):
                _td_proposal = _db_query(
                    "SELECT id, symbol, strategy_id, proposed_entry, proposed_stop, proposed_target1, proposed_shares, signal_score, signal_grade, catalyst, catalyst_verified, execution_eligibility_status, execution_eligibility_reason, live_price_at_execution, created_at FROM paper_trade_proposals WHERE id = %s",
                    [_td.get("proposal_id")],
                    fetch="one",
                )
            # Timing classification
            _td_tod = _td_dow = None
            _td_et = _td.get("entry_time")
            if _td_et:
                try:
                    import zoneinfo as _zi

                    _et_obj = (
                        _td_et
                        if hasattr(_td_et, "hour")
                        else __import__("datetime").datetime.fromisoformat(str(_td_et))
                    )
                    _et_loc = _et_obj.astimezone(_zi.ZoneInfo("America/New_York"))
                    _h = _et_loc.hour
                    _td_tod = (
                        "pre_market"
                        if _h < 9
                        else "open"
                        if _h < 10
                        else "midday"
                        if _h < 14
                        else "close"
                        if _h < 16
                        else "after_hours"
                    )
                    _td_dow = _et_loc.strftime("%A")
                except Exception:
                    pass
            _td_hold = _td.get("hold_time_min")
            if not _td_hold and _td_et and _td.get("closed_at"):
                try:
                    _td_hold = (
                        int((_td["closed_at"] - _td_et).total_seconds() / 60) if hasattr(_td_et, "timestamp") else None
                    )
                except Exception:
                    pass
            _entry_p = float(_td.get("entry_price") or 0)
            _stop_p = float(_td.get("stop_loss") or 0)
            _tgt_p = float(_td.get("target_1") or 0)
            _plan_e = float(_td.get("planned_entry") or _entry_p)
            _slip = round(_entry_p - _plan_e, 4) if _plan_e else None
            _itype = "scalp" if (_td_hold or 999) < 60 else "day" if (_td_hold or 999) < 480 else "swing"
            return 200, _deep_clean(
                {
                    "ok": True,
                    "trade": dict(_td),
                    "classification": {
                        "direction": "long",
                        "strategy": _td.get("strategy_id"),
                        "setup": _td.get("setup_type") or _td.get("strategy_id"),
                        "intended_type": _itype,
                        "time_of_day": _td_tod,
                        "day_of_week": _td_dow,
                        "market_regime": _td.get("market_regime"),
                    },
                    "timing": {"entry_time": _td_et, "exit_time": _td.get("closed_at"), "hold_minutes": _td_hold},
                    "technicals_at_entry": {
                        "vix": _td.get("vix_at_entry"),
                        "rvol": _td.get("rvol_at_entry"),
                        "score": _td.get("score_at_entry"),
                        "signal_grade": _td.get("signal_grade"),
                        "catalyst": _td.get("catalyst_at_entry"),
                        "catalyst_verified": _td.get("catalyst_verified"),
                        "float_m": _td.get("float_m_at_entry"),
                        "intel_readiness": _td.get("intel_readiness"),
                    },
                    "risk_execution": {
                        "planned_entry": _plan_e,
                        "actual_entry": _entry_p,
                        "slippage": _slip,
                        "stop": _stop_p,
                        "target": _tgt_p,
                        "exit_price": float(_td.get("exit_price") or 0),
                        "pnl": float(_td.get("pnl") or 0),
                        "r_multiple": _td.get("r_multiple"),
                        "mae": _td.get("max_adverse_excursion"),
                        "mfe": _td.get("max_favorable_excursion"),
                        "exit_reason": _td.get("exit_reason"),
                        "outcome_verdict": _td.get("outcome_verdict"),
                        "risk_params_at_fill": _td.get("risk_params_at_fill"),
                    },
                    "narrative": {
                        "journal_review": dict(_td_review) if _td_review else None,
                        "thesis_outcome": dict(_td_thesis) if _td_thesis else None,
                        "llm_analysis": dict(_td_analysis) if _td_analysis else None,
                    },
                    "agent_critiques": [dict(e) for e in _td_events],
                    "multi_tier_reviews": [
                        dict(r)
                        for r in (
                            _db_query(
                                "SELECT tier, model_used, review_text, agent_commentaries, created_at FROM paper_trade_multi_reviews WHERE paper_trade_id = %s ORDER BY created_at",
                                [_td_id],
                            )
                            or []
                        )
                    ],
                    "risk_actions": [dict(a) for a in _td_risk],
                    "alerts": [dict(a) for a in _td_alerts],
                    "proposal": dict(_td_proposal) if _td_proposal else None,
                }
            )
        except Exception as e:
            import traceback

            traceback.print_exc()
            return 500, {"ok": False, "error": str(e)}

    if base_path in ("/api/v2/automated-journal", "/api/v2/paper-journal"):
        try:
            trades = (
                _db_query("""
                SELECT id, symbol, strategy_id, setup_type, signal_grade, score_at_entry,
                       account, opened_via, automation_source, broker_order_id, broker_status,
                       broker, client_order_id, take_profit_price, stop_loss_price,
                       entry_price, exit_price, current_price, shares, stop_loss, target_1,
                       dollar_risk, pnl, unrealized_pnl, r_multiple, pnl_pct,
                       status, outcome_verdict, exit_reason, catalyst_at_entry, catalyst_verified,
                       risk_gate_result, entry_time, exit_time, created_at, closed_at, proposal_id,
                       post_trade_analyzed, iris_curated, aegis_summarized, submitted_at, filled_at,
                       updated_at, last_synced_at
                FROM paper_trades
                ORDER BY created_at DESC LIMIT 200
            """)
                or []
            )
            # Filter: only show broker-confirmed open trades
            open_t = [
                t
                for t in trades
                if t.get("status") in ("open",) and (t.get("filled_at") or t.get("broker_status") == "filled")
            ]
            closed_t = [
                t
                for t in trades
                if t.get("status") == "closed"
                and not (t.get("close_reason") or "").startswith("phantom")
                and not (t.get("close_reason") or "").startswith("Orphan")
                and not (t.get("exit_reason") or "").startswith("phantom")
                and not (t.get("exit_reason") or "").startswith("order_never_filled")
            ]
            # Win rate: only count real trades (non-zero PnL)
            real_closed = [t for t in closed_t if (t.get("pnl") or 0) != 0]
            wins = sum(1 for t in real_closed if (t.get("pnl") or 0) > 0)
            losses = sum(1 for t in real_closed if (t.get("pnl") or 0) < 0)
            total_pnl = sum(float(t.get("pnl") or 0) for t in closed_t)
            wr = round(wins / len(real_closed), 3) if real_closed else None
            # Compute last-updated timestamp from most recent trade update
            _last_updated = None
            for _t in trades:
                for _ts_key in ("updated_at", "last_synced_at", "closed_at", "created_at"):
                    _ts = _t.get(_ts_key)
                    if _ts and (not _last_updated or str(_ts) > str(_last_updated)):
                        _last_updated = _ts
            return 200, {
                "ok": True,
                "last_updated_at": _json_clean(_last_updated),
                "stats": {
                    "closed": len(closed_t),
                    "open": len(open_t),
                    "wins": wins,
                    "losses": losses,
                    "win_rate": wr,
                    "total_pnl": round(total_pnl, 2),
                    "real_trade_count": len(real_closed),
                },
                "trades": [{k: _json_clean(v) for k, v in t.items()} for t in trades],
                "open_trades": [{k: _json_clean(v) for k, v in t.items()} for t in open_t],
                "closed_trades": [{k: _json_clean(v) for k, v in t.items()} for t in closed_t],
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Open Trades Intelligence ──
    if base_path == "/api/v2/open-trades":
        try:
            raw = (
                _db_query("""
                SELECT id, symbol, strategy_id, shares,
                       entry_price, current_price, stop_loss, target_1,
                       unrealized_pnl, pnl, r_multiple,
                       created_at, broker_order_id, broker_status,
                       catalyst_at_entry, score_at_entry,
                       updated_at, last_synced_at
                FROM paper_trades WHERE status = 'open'
                ORDER BY created_at DESC
            """)
                or []
            )
            trail_recs = {}
            _tr = (
                _db_query("""
                SELECT strategy_id,
                       MODE() WITHIN GROUP (ORDER BY recommendation) as rec,
                       ROUND(AVG(high_water_pct_gain)::numeric, 1) as max_pot,
                       ROUND(AVG(CASE WHEN optimal_trail_pct IS NOT NULL
                                     THEN optimal_trail_pnl - fixed_pnl_pct ELSE 0
                                END)::numeric, 1) as improvement,
                       ROUND(AVG(optimal_trail_pct)::numeric, 0) as optimal_pct
                FROM trailing_stop_analysis GROUP BY strategy_id
            """)
                or []
            )
            for r in _tr:
                trail_recs[r["strategy_id"]] = r

            # Technicals — reuse the same caches the holdings page uses (RSI zone, fib levels)
            ec = _load_json(STATE_DIR / "ticker_enrichment_cache.json") or {}
            ts = _load_json(STATE_DIR / "technical_snapshot.json") or {}

            trades = []
            for t in raw:
                entry = float(t.get("entry_price") or 0)
                cur = float(t.get("current_price") or entry)
                stop = float(t.get("stop_loss") or 0)
                tgt = float(t.get("target_1") or 0)
                shares = int(t.get("shares") or 0)
                _pnl = float(t.get("unrealized_pnl") or t.get("pnl") or 0)
                risk = abs(entry - stop) if entry and stop else 1
                r_m = round((cur - entry) / risk, 2) if risk else None
                rr = round((tgt - entry) / risk, 2) if risk and tgt else None

                tr = trail_recs.get(t.get("strategy_id"), {})
                rec = tr.get("rec", "keep_fixed") or "keep_fixed"
                if rec.startswith("use_trail"):
                    trail_advice = f"Consider {float(tr.get('optimal_pct', 5)):.0f}% trailing stop (+{float(tr.get('improvement', 0)):.1f}% vs fixed)"
                else:
                    trail_advice = f"Keep fixed stop (avg max potential +{float(tr.get('max_pot', 0)):.1f}%)"

                flags = []
                if _pnl < 0:
                    flags.append("below_entry")
                if cur and stop and (cur - stop) / cur < 0.02:
                    flags.append("near_stop")
                if r_m and r_m < -0.5:
                    flags.append("losing_momentum")
                if r_m and r_m > 0.8:
                    flags.append("consider_partial_exit")

                # Technicals (RSI zone + fib) for this symbol, from the shared caches
                _sym = t["symbol"]
                _ec = ec.get(_sym, {}) if isinstance(ec.get(_sym), dict) else {}
                _ts = ts.get(_sym, {}) if isinstance(ts.get(_sym), dict) else {}
                _rsi = _ec.get("rsi") if _ec.get("rsi") is not None else _ts.get("rsi")
                _rsi_status = _ec.get("rsi_status") or _ts.get("rsi_status")
                if not _rsi_status and _rsi is not None:
                    try:
                        _rv = float(_rsi)
                        _rsi_status = "oversold" if _rv <= 30 else "overbought" if _rv >= 70 else "neutral"
                    except Exception:
                        pass
                _hi = (
                    _ec.get("pct_from_52w_high")
                    if _ec.get("pct_from_52w_high") is not None
                    else _ts.get("pct_from_52w_high")
                )
                _lo = (
                    _ec.get("pct_from_52w_low")
                    if _ec.get("pct_from_52w_low") is not None
                    else _ts.get("pct_from_52w_low")
                )
                _fib = _fib_analysis(cur, _hi, _lo) if (_hi is not None or _lo is not None) else None

                trades.append(
                    {
                        "id": t["id"],
                        "symbol": t["symbol"],
                        "strategy_id": t.get("strategy_id"),
                        "shares": shares,
                        "entry_price": entry,
                        "current_price": cur,
                        "stop_loss": stop,
                        "target_1": tgt,
                        "pnl": round(_pnl, 2),
                        "pnl_pct": round((cur - entry) / entry * 100, 2) if entry else 0,
                        "r_multiple": r_m,
                        "rr_ratio": rr,
                        "dist_to_stop_pct": round((stop - cur) / cur * 100, 2) if cur else None,
                        "dist_to_stop_usd": round((stop - cur) * shares, 2) if cur else None,
                        "dist_to_target_pct": round((tgt - cur) / cur * 100, 2) if cur and tgt else None,
                        "dist_to_target_usd": round((tgt - cur) * shares, 2) if cur and tgt and shares else None,
                        "risk_flags": flags,
                        "trail_recommendation": rec,
                        "trail_advice": trail_advice,
                        "opened_at": str(t.get("created_at") or ""),
                        "catalyst": t.get("catalyst_at_entry"),
                        "rsi": _rsi,
                        "rsi_status": _rsi_status,
                        "pct_52w_high": _hi,
                        "pct_52w_low": _lo,
                        "fib": _fib,
                    }
                )
            # Most recent update timestamp from open trades
            _ot_updated = None
            for _t in raw:
                for _tk in ("updated_at", "last_synced_at", "created_at"):
                    _tv = _t.get(_tk)
                    if _tv and (not _ot_updated or str(_tv) > str(_ot_updated)):
                        _ot_updated = _tv
            return 200, {
                "ok": True,
                "data": {
                    "trades": trades,
                    "count": len(trades),
                    "total_unrealized_pnl": round(sum(x["pnl"] for x in trades), 2),
                    "last_updated_at": _json_clean(_ot_updated),
                },
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Trade Intelligence Aggregator (Phase 3, Session 42) ──
    if base_path.startswith("/api/v2/trade/") and base_path.endswith("/intelligence"):
        _tid_str = base_path[len("/api/v2/trade/") : -len("/intelligence")].strip("/")
        if _tid_str.isdigit():
            try:
                _tid = int(_tid_str)
                # 1. Core trade
                _trade = _db_query("SELECT * FROM paper_trades WHERE id=%s", [_tid], fetch="one")
                if not _trade:
                    return 404, {"ok": False, "error": f"Trade {_tid} not found"}
                _sym = _trade["symbol"]

                # 2. Linked proposal
                _prop = None
                if _trade.get("proposal_id"):
                    _prop = _db_query(
                        "SELECT * FROM paper_trade_proposals WHERE id=%s", [_trade["proposal_id"]], fetch="one"
                    )

                # 3. Agent reviews for this proposal (exclude empty stubs)
                _reviews = []
                if _trade.get("proposal_id"):
                    _reviews = (
                        _db_query(
                            """
                        SELECT agent_name, vote, confidence, summary, concerns, payload, reviewed_at, status
                        FROM proposal_agent_reviews
                        WHERE proposal_id=%s AND (vote IS NOT NULL OR summary IS NOT NULL AND summary != '')
                        ORDER BY created_at
                    """,
                            [_trade["proposal_id"]],
                        )
                        or []
                    )

                # 4. Watchlist agent narratives for this symbol
                # Try closest to proposal time (7-day window), fall back to most recent
                _narratives = []
                _prop_time = (_prop or {}).get("created_at")
                if _prop_time:
                    _narratives = (
                        _db_query(
                            """
                        SELECT DISTINCT ON (agent) agent, recommendation, confidence, summary,
                               LEFT(full_narrative, 800) as narrative_preview, model_used, created_at
                        FROM watchlist_agent_results
                        WHERE symbol=%s AND created_at BETWEEN %s - INTERVAL '7 days' AND %s + INTERVAL '1 day'
                        ORDER BY agent, ABS(EXTRACT(EPOCH FROM (created_at - %s)))
                    """,
                            [_sym, _prop_time, _prop_time, _prop_time],
                        )
                        or []
                    )
                if not _narratives:
                    _narratives = (
                        _db_query(
                            """
                        SELECT DISTINCT ON (agent) agent, recommendation, confidence, summary,
                               LEFT(full_narrative, 800) as narrative_preview, model_used, created_at
                        FROM watchlist_agent_results
                        WHERE symbol=%s
                        ORDER BY agent, created_at DESC
                    """,
                            [_sym],
                        )
                        or []
                    )

                # 5. Competing strategies (all proposals for same symbol within 24h)
                _competing = []
                if _prop:
                    _competing = (
                        _db_query(
                            """
                        SELECT id, strategy_id, signal_score, signal_grade,
                               critic_confidence, status, paper_submit_state,
                               is_top_pick, rank_among_peers
                        FROM paper_trade_proposals
                        WHERE symbol=%s
                          AND ABS(EXTRACT(EPOCH FROM (created_at - %s))) < 86400
                        ORDER BY COALESCE(rank_among_peers, 999), COALESCE(signal_score, 0) DESC
                    """,
                            [_sym, _prop["created_at"]],
                        )
                        or []
                    )

                # 6. Post-trade thesis outcome
                _thesis = _db_query(
                    """
                    SELECT thesis_result, actual_r, invalidation_hit,
                           max_favorable_excursion_pct, max_adverse_excursion_pct,
                           thesis_followed, exit_reason, review_payload
                    FROM trade_thesis_outcomes WHERE paper_trade_id=%s
                """,
                    [_tid],
                    fetch="one",
                )

                # 7. Post-trade price analysis (new table, may not exist yet)
                _price_analysis = None
                try:
                    _price_analysis = _db_query(
                        """
                        SELECT * FROM post_trade_price_analysis WHERE trade_id=%s
                    """,
                        [_tid],
                        fetch="one",
                    )
                except Exception:
                    pass

                # 8. Prior outcomes context (Fix 6 block)
                _prior_ctx = ""
                try:
                    from agent_collab import get_symbol_history_context, get_strategy_performance_context
                    from session13_db import get_conn as _get_intel_conn

                    _iconn = _get_intel_conn()
                    _prior_ctx = get_symbol_history_context(_sym, _iconn, days=30)
                    _strat_ctx = get_strategy_performance_context(_trade.get("strategy_id", ""), _iconn, days=30)
                    _iconn.close()
                    if _strat_ctx:
                        _prior_ctx = (_prior_ctx or "") + "\n" + _strat_ctx
                except Exception:
                    pass

                _clean = lambda rows: [{k: _json_clean(v) for k, v in r.items()} for r in rows] if rows else []

                return 200, {
                    "ok": True,
                    "data": {
                        "trade": {k: _json_clean(v) for k, v in _trade.items()},
                        "proposal": {k: _json_clean(v) for k, v in _prop.items()} if _prop else None,
                        "agent_reasoning": {
                            "reviews": _clean(_reviews),
                            "narratives": _clean(_narratives),
                        },
                        "competing_strategies": _clean(_competing),
                        "post_trade": {
                            "thesis": {k: _json_clean(v) for k, v in _thesis.items()} if _thesis else None,
                            "price_analysis": {k: _json_clean(v) for k, v in _price_analysis.items()}
                            if _price_analysis
                            else None,
                        },
                        "prior_outcomes_context": _prior_ctx,
                    },
                }
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

    # ── Morning Brief (Session A-3.5) ──────────────────────────────────────
    if base_path == "/api/v2/morning-brief":
        try:
            from datetime import datetime as _dt, timezone as _tz, timedelta as _td

            _now = _dt.now(_tz.utc)
            _since = (_now - _td(hours=15)).isoformat()  # ~5 PM yesterday

            # 1. Holdings guard
            _hg = {"ok": False, "portfolio_value": 0, "threshold": 1_000_000}
            try:
                _hj = _load_json(STATE_DIR / "holdings.json") or {}
                _hv = _hj.get("portfolio_totals", {}).get("total_value", 0)
                _hg = {"ok": _hv > 1_000_000, "portfolio_value": round(_hv, 2), "threshold": 1_000_000}
            except Exception:
                pass

            # 2. Paper account
            _pa = {"equity": 0, "open_positions": 0, "cash": 0, "heat_pct": 0}
            try:
                _paper_size = 100000.0
                _open = (
                    _db_query(
                        "SELECT COUNT(*) as cnt, COALESCE(SUM(dollar_risk),0) as risk FROM paper_trades WHERE status='open'",
                        fetch="one",
                    )
                    or {}
                )
                _pa["open_positions"] = _open.get("cnt", 0)
                _pa["heat_pct"] = round(float(_open.get("risk", 0)) / _paper_size, 4) if _paper_size > 0 else 0
                try:
                    import requests as _rq

                    # Read keys from .env file directly (server env may not have os.getenv working in this scope)
                    _env_kv = {}
                    for _el in (PROJECT_ROOT / ".env").read_text().splitlines():
                        if "=" in _el and not _el.startswith("#"):
                            _ek2, _ev2 = _el.split("=", 1)
                            _env_kv[_ek2.strip()] = _ev2.strip()
                    _ak = _env_kv.get("ALPACA_API_KEY", "")
                    _asec = _env_kv.get("ALPACA_SECRET_KEY", "")
                    if _ak and _asec:
                        _r = _rq.get(
                            "https://paper-api.alpaca.markets/v2/account",
                            headers={"APCA-API-KEY-ID": _ak, "APCA-API-SECRET-KEY": _asec},
                            timeout=5,
                        )
                        if _r.ok:
                            _acct = _r.json()
                            _pa["equity"] = round(float(_acct.get("equity", 0)), 2)
                            _pa["cash"] = round(float(_acct.get("cash", 0)), 2)
                        else:
                            _pa["_error"] = f"alpaca_http_{_r.status_code}"
                    else:
                        _pa["_error"] = "alpaca_keys_missing"
                except Exception as _e:
                    _pa["_error"] = str(_e)[:100]
            except Exception:
                pass  # paper_account defaults to zeros if fetch fails

            # 3. Overnight activity
            _oa = {
                "since": _since,
                "proposals_created": 0,
                "proposals_approved": 0,
                "trades_opened": 0,
                "trades_closed": 0,
                "risk_gate_blocks": {},
            }
            try:
                _pc = (
                    _db_query(
                        "SELECT COUNT(*) as c FROM paper_trade_proposals WHERE created_at > %s", [_since], fetch="one"
                    )
                    or {}
                )
                _oa["proposals_created"] = _pc.get("c", 0)
                _ap = (
                    _db_query(
                        "SELECT COUNT(*) as c FROM paper_trade_proposals WHERE approved_at > %s", [_since], fetch="one"
                    )
                    or {}
                )
                _oa["proposals_approved"] = _ap.get("c", 0)
                _to = (
                    _db_query("SELECT COUNT(*) as c FROM paper_trades WHERE created_at > %s", [_since], fetch="one")
                    or {}
                )
                _oa["trades_opened"] = _to.get("c", 0)
                _tc = (
                    _db_query("SELECT COUNT(*) as c FROM paper_trades WHERE closed_at > %s", [_since], fetch="one")
                    or {}
                )
                _oa["trades_closed"] = _tc.get("c", 0)
                _rgb = (
                    _db_query(
                        """SELECT reason_codes::text as r, COUNT(*) as c FROM audit_log
                    WHERE event_type LIKE 'BLOCKED_%%' AND created_at > %s
                    GROUP BY reason_codes::text""",
                        [_since],
                    )
                    or []
                )
                _blocks = {}
                for _b in _rgb:
                    _rt = str(_b.get("r", ""))
                    if "HEAT" in _rt:
                        _blocks["H1_heat"] = _blocks.get("H1_heat", 0) + _b.get("c", 0)
                    elif "CONCENTRATION" in _rt:
                        _blocks["H2_concentration"] = _blocks.get("H2_concentration", 0) + _b.get("c", 0)
                    elif "SECTOR" in _rt:
                        _blocks["H3_sector"] = _blocks.get("H3_sector", 0) + _b.get("c", 0)
                    else:
                        _blocks["other"] = _blocks.get("other", 0) + _b.get("c", 0)
                _oa["risk_gate_blocks"] = _blocks
            except Exception:
                pass

            # 4. Strategy health
            _sh = {"total_active": 0, "newly_activated": 0, "stuck_strategies": []}
            try:
                _act = (
                    _db_query(
                        "SELECT COUNT(DISTINCT strategy_id) as c FROM paper_trades WHERE status='open' OR closed_at > NOW() - INTERVAL '14 days'",
                        fetch="one",
                    )
                    or {}
                )
                _sh["total_active"] = _act.get("c", 0)
                _na = _db_query("SELECT COUNT(*) as c FROM strategy_activations", fetch="one") or {}
                _sh["newly_activated"] = _na.get("c", 0)
                _stuck = (
                    _db_query("""SELECT sa.strategy_id FROM strategy_activations sa
                    WHERE NOT EXISTS (SELECT 1 FROM paper_trade_proposals p WHERE p.strategy_id = sa.strategy_id AND p.created_at > sa.activated_at)
                    AND sa.activated_at < NOW() - INTERVAL '3 days'""")
                    or []
                )
                _sh["stuck_strategies"] = [s["strategy_id"] for s in _stuck]
            except Exception:
                pass

            # 5. Closed trades 24h
            _ct = []
            try:
                _rows = (
                    _db_query("""SELECT pt.symbol, pt.strategy_id, pt.pnl, pt.outcome_verdict, pt.exit_reason,
                    pta.stop_too_tight, LEFT(pta.lesson_text, 150) as lesson
                    FROM paper_trades pt LEFT JOIN post_trade_price_analysis pta ON pta.trade_id = pt.id
                    WHERE pt.closed_at > NOW() - INTERVAL '24 hours' AND pt.lifecycle_state = 'closed'
                    ORDER BY pt.closed_at DESC""")
                    or []
                )
                _ct = [{k: _json_clean(v) for k, v in r.items()} for r in _rows]
            except Exception:
                pass

            # 6. Alerts 24h
            _al = {"urgent": 0, "digest": 0, "dashboard_only": 0}
            try:
                _ac = (
                    _db_query("""SELECT tier, COUNT(*) as c FROM alert_dispatch_log
                    WHERE created_at > NOW() - INTERVAL '24 hours'
                    GROUP BY tier""")
                    or []
                )
                for _a in _ac:
                    _t = str(_a.get("tier", "")).lower()
                    if "urgent" in _t:
                        _al["urgent"] = _a.get("c", 0)
                    elif "digest" in _t:
                        _al["digest"] = _a.get("c", 0)
                    else:
                        _al["dashboard_only"] = _al.get("dashboard_only", 0) + _a.get("c", 0)
            except Exception:
                pass

            # 7. Action items
            _items = []
            try:
                # A) Stuck strategies
                for _s in _sh.get("stuck_strategies", []):
                    _items.append(
                        {
                            "severity": "warning",
                            "code": "STUCK_STRATEGY",
                            "message": f"{_s}: 0 proposals since activation, 3+ days idle",
                        }
                    )
                # B) Stop pattern
                _sp = (
                    _db_query("""SELECT strategy_id,
                    ROUND(100.0 * COUNT(*) FILTER (WHERE stop_too_tight) / NULLIF(COUNT(*), 0), 0) as pct
                    FROM post_trade_price_analysis GROUP BY strategy_id
                    HAVING COUNT(*) >= 3 AND COUNT(*) FILTER (WHERE stop_too_tight) * 100.0 / COUNT(*) > 50""")
                    or []
                )
                for _s in _sp:
                    _items.append(
                        {
                            "severity": "info",
                            "code": "STOP_PATTERN",
                            "message": f"{_s['strategy_id']} stop_too_tight at {_s['pct']}%",
                        }
                    )
                # C) Heat approaching
                if _pa.get("heat_pct", 0) > 0.045:
                    _items.append(
                        {
                            "severity": "warning",
                            "code": "HEAT_APPROACHING",
                            "message": f"Heat at {_pa['heat_pct']:.1%}, approaching 6% hard limit",
                        }
                    )
            except Exception:
                pass

            _ai_crit = None
            try:
                import journal_trade_in_view as _tiv_mb

                _ai_crit = _tiv_mb.ai_critique_insights(days=14)
                for _bul in (_ai_crit.get("coaching_bullets") or [])[:2]:
                    _items.append({"severity": "info", "code": "AI_CRITIQUE_PATTERN", "message": _bul})
                if (_ai_crit.get("stale_count") or 0) > 0:
                    _items.append(
                        {
                            "severity": "warning",
                            "code": "AI_CRITIQUE_STALE",
                            "message": f"{_ai_crit['stale_count']} trade critiques stale after tag edits — regenerate in Trade Detail",
                        }
                    )
            except Exception:
                pass

            return 200, {
                "ok": True,
                "data": {
                    "generated_at": _now.isoformat(),
                    "holdings_guard": _hg,
                    "paper_account": _pa,
                    "overnight_activity": _oa,
                    "strategy_health": _sh,
                    "closed_trades_24h": _ct,
                    "alerts_24h": _al,
                    "action_items": _items,
                    "ai_critique_insights": _ai_crit,
                },
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Strategy Analytics Dashboard ─────────────────────────────────────────
    if base_path.startswith("/api/v2/strategy-analytics/"):
        _panel = base_path[len("/api/v2/strategy-analytics/") :].strip("/")

        # 1. Scoreboard
        if _panel == "scoreboard":
            try:
                rows = (
                    _db_query("""
                    SELECT strategy_id,
                        COUNT(*) FILTER (WHERE status='closed') as trades,
                        COUNT(*) FILTER (WHERE status='closed' AND pnl > 0) as wins,
                        COUNT(*) FILTER (WHERE status='closed' AND pnl <= 0) as losses,
                        ROUND(AVG(r_multiple) FILTER (WHERE status='closed')::numeric, 2) as avg_r,
                        ROUND(SUM(pnl) FILTER (WHERE status='closed')::numeric, 2) as total_pnl,
                        ROUND(AVG(EXTRACT(EPOCH FROM (closed_at - filled_at)) / 3600) FILTER (WHERE status='closed' AND closed_at IS NOT NULL AND filled_at IS NOT NULL)::numeric, 1) as avg_hold_hours,
                        ROUND((COALESCE(SUM(pnl) FILTER (WHERE status='closed' AND pnl > 0), 0) / NULLIF(ABS(COALESCE(SUM(pnl) FILTER (WHERE status='closed' AND pnl < 0), 0)), 0))::numeric, 2) as profit_factor
                    FROM paper_trades
                    GROUP BY strategy_id
                    ORDER BY strategy_id
                """)
                    or []
                )
                out = []
                for r in rows:
                    t = int(r.get("trades") or 0)
                    w = int(r.get("wins") or 0)
                    wr = round(w / t, 4) if t > 0 else 0
                    if t == 0:
                        status = "INACTIVE"
                    elif t < 5:
                        status = "TOO_FEW"
                    elif wr > 0.50:
                        status = "WORKING"
                    elif wr >= 0.30:
                        status = "TUNING"
                    else:
                        status = "NOT_WORKING"
                    # Handle profit_factor edge cases
                    pf = _json_clean(r.get("profit_factor"))
                    if pf is None and t > 0:
                        pf = float("inf") if w == t else 0.0  # all wins = inf, all losses = 0
                    out.append(
                        {
                            "strategy_id": r["strategy_id"],
                            "trades": t,
                            "wins": w,
                            "losses": int(r.get("losses") or 0),
                            "win_rate": round(wr, 4),
                            "profit_factor": pf if pf != float("inf") else 999.0,
                            "avg_hold_hours": _json_clean(r.get("avg_hold_hours")),
                            "avg_r": _json_clean(r.get("avg_r")),
                            "total_pnl": _json_clean(r.get("total_pnl")),
                            "status": status,
                        }
                    )
                return 200, {"ok": True, "data": out}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        # 2. Hold-times
        if _panel == "hold-times":
            try:
                STRATEGY_HOLD_NORMS = {
                    "gap_and_go": {"min": 0.1, "norm": 2, "max": 8},
                    "momentum_scalp": {"min": 0.1, "norm": 1, "max": 4},
                    "swing_breakout": {"min": 12, "norm": 48, "max": 120},
                    "swing_trade": {"min": 12, "norm": 72, "max": 240},
                    "earnings_catalyst": {"min": 1, "norm": 24, "max": 72},
                    "earnings_pre_buildup": {"min": 24, "norm": 120, "max": 336},
                    "earnings_post_momentum": {"min": 1, "norm": 24, "max": 120},
                    "fib_retracement_bounce": {"min": 4, "norm": 48, "max": 168},
                    "covered_call_income": {"min": 168, "norm": 504, "max": 1080},
                    "core_growth_compounder": {"min": 720, "norm": 2160, "max": 8760},
                    "dividend_growth_compounder": {"min": 720, "norm": 2160, "max": 8760},
                    "speculative_growth": {"min": 24, "norm": 168, "max": 720},
                    "recovery_watch": {"min": 24, "norm": 168, "max": 720},
                    "sector_rotation": {"min": 168, "norm": 720, "max": 2160},
                    "defense_thesis": {"min": 168, "norm": 720, "max": 2160},
                    "tax_loss_harvest": {"min": 24, "norm": 168, "max": 720},
                }
                rows = (
                    _db_query("""
                    SELECT strategy_id,
                        ROUND(AVG(EXTRACT(EPOCH FROM (closed_at - filled_at)) / 3600)::numeric, 1) as avg_hold_hours,
                        ROUND(MIN(EXTRACT(EPOCH FROM (closed_at - filled_at)) / 3600)::numeric, 1) as min_hold_hours,
                        ROUND(MAX(EXTRACT(EPOCH FROM (closed_at - filled_at)) / 3600)::numeric, 1) as max_hold_hours,
                        COUNT(*) as closed_trades
                    FROM paper_trades
                    WHERE status='closed' AND closed_at IS NOT NULL AND filled_at IS NOT NULL
                    GROUP BY strategy_id
                    ORDER BY strategy_id
                """)
                    or []
                )
                out = []
                for r in rows:
                    sid = r["strategy_id"]
                    avg_h = float(r.get("avg_hold_hours") or 0)
                    norms = STRATEGY_HOLD_NORMS.get(sid)
                    if norms:
                        if avg_h < norms["min"]:
                            verdict = "TOO_SHORT"
                        elif avg_h > norms["max"]:
                            verdict = "TOO_LONG"
                        else:
                            verdict = "APPROPRIATE"
                    else:
                        verdict = "NO_NORM"
                    out.append(
                        {
                            "strategy_id": sid,
                            "avg_hold_hours": _json_clean(r.get("avg_hold_hours")),
                            "min_hold_hours": _json_clean(r.get("min_hold_hours")),
                            "max_hold_hours": _json_clean(r.get("max_hold_hours")),
                            "closed_trades": int(r.get("closed_trades") or 0),
                            "norms": norms,
                            "verdict": verdict,
                        }
                    )
                return 200, {"ok": True, "data": out}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        # 3. Exit-reasons
        if _panel == "exit-reasons":
            try:
                rows = (
                    _db_query("""
                    SELECT strategy_id, exit_reason, COUNT(*) as cnt
                    FROM paper_trades
                    WHERE status='closed' AND exit_reason IS NOT NULL
                    GROUP BY strategy_id, exit_reason
                    ORDER BY strategy_id, cnt DESC
                """)
                    or []
                )
                # Group by strategy
                grouped = {}
                for r in rows:
                    sid = r["strategy_id"]
                    if sid not in grouped:
                        grouped[sid] = []
                    grouped[sid].append(
                        {
                            "exit_reason": r["exit_reason"],
                            "count": int(r.get("cnt") or 0),
                        }
                    )
                return 200, {"ok": True, "data": grouped}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        # 4. Stop-quality
        if _panel == "stop-quality":
            try:
                rows = (
                    _db_query("""
                    SELECT pt.strategy_id,
                        COUNT(*) as analyzed_trades,
                        ROUND(100.0 * COUNT(*) FILTER (WHERE pa.stop_too_tight = true) / NULLIF(COUNT(*), 0), 1) as pct_stop_too_tight,
                        ROUND(100.0 * COUNT(*) FILTER (WHERE pa.would_have_recovered = true) / NULLIF(COUNT(*), 0), 1) as pct_would_have_recovered,
                        ROUND(100.0 * COUNT(*) FILTER (WHERE pa.held_too_short = true) / NULLIF(COUNT(*), 0), 1) as pct_held_too_short
                    FROM post_trade_price_analysis pa
                    JOIN paper_trades pt ON pt.id = pa.trade_id
                    GROUP BY pt.strategy_id
                    ORDER BY pt.strategy_id
                """)
                    or []
                )
                out = [{k: _json_clean(v) for k, v in r.items()} for r in rows]
                return 200, {"ok": True, "data": out}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        # 5. Finviz-health
        if _panel == "finviz-health":
            try:
                health = (
                    _db_query(
                        """
                    SELECT
                        COUNT(*) as total_rows,
                        COUNT(DISTINCT symbol) as unique_symbols,
                        COUNT(DISTINCT scanned_at::date) as days_of_history,
                        COUNT(*) FILTER (WHERE scanned_at::date = CURRENT_DATE) as rows_today,
                        ROUND(COUNT(*) FILTER (WHERE scanned_at >= CURRENT_DATE - INTERVAL '7 days')::numeric / 7, 0) as avg_rows_7d
                    FROM trade_ai_scans
                """,
                        fetch="one",
                    )
                    or {}
                )
                return 200, {"ok": True, "data": {k: _json_clean(v) for k, v in health.items()}}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        # 6. Inactive-strategies
        if _panel == "inactive-strategies":
            try:
                strat_dir = PROJECT_ROOT / "config" / "strategies"
                yaml_strategies = []
                if strat_dir.is_dir():
                    for f in sorted(strat_dir.iterdir()):
                        if f.suffix in (".yaml", ".yml") and f.stem not in (
                            "recommendation_schema",
                            "shared_risk_rules",
                            "strategy_schema",
                        ):
                            yaml_strategies.append(f.stem)
                active_rows = (
                    _db_query("""
                    SELECT DISTINCT strategy_id FROM paper_trades
                """)
                    or []
                )
                active_ids = {r["strategy_id"] for r in active_rows}
                inactive = []
                for sid in yaml_strategies:
                    if sid not in active_ids:
                        # Check proposals
                        prop = (
                            _db_query(
                                """
                            SELECT COUNT(*) as candidates_7d
                            FROM paper_trade_proposals
                            WHERE strategy_id = %s AND created_at >= CURRENT_DATE - INTERVAL '7 days'
                        """,
                                [sid],
                                fetch="one",
                            )
                            or {}
                        )
                        inactive.append(
                            {
                                "strategy_id": sid,
                                "trades": 0,
                                "candidates_7d": int(prop.get("candidates_7d") or 0),
                            }
                        )
                return 200, {"ok": True, "data": inactive}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        # 7. Lesson-patterns
        if _panel == "lesson-patterns":
            try:
                lessons = (
                    _db_query("""
                    SELECT pa.trade_id, pt.strategy_id, pt.symbol, pa.lesson_text, pa.analyzed_at
                    FROM post_trade_price_analysis pa
                    JOIN paper_trades pt ON pt.id = pa.trade_id
                    WHERE pa.lesson_text IS NOT NULL AND pa.lesson_text != ''
                      AND pa.lesson_text NOT LIKE 'Lesson generation failed%%'
                    ORDER BY pa.analyzed_at DESC
                    LIMIT 50
                """)
                    or []
                )
                KEYWORDS = ["tight stop", "premature exit", "inverted stop", "hold longer"]
                keyword_counts = {kw: 0 for kw in KEYWORDS}
                for les in lessons:
                    txt = (les.get("lesson_text") or "").lower()
                    for kw in KEYWORDS:
                        if kw in txt:
                            keyword_counts[kw] += 1
                out_lessons = [{k: _json_clean(v) for k, v in r.items()} for r in lessons]
                return 200, {
                    "ok": True,
                    "data": {
                        "recent_lessons": out_lessons,
                        "keyword_counts": keyword_counts,
                    },
                }
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        if _panel == "newly-activated":
            try:
                # Use fresh connection — strategy_activations may have been created after server started
                import psycopg2 as _pg2, psycopg2.extras as _pge2

                _dbpw2 = ""
                for _el2 in (PROJECT_ROOT / ".env").read_text().splitlines():
                    if _el2.startswith("DB_PASSWORD="):
                        _dbpw2 = _el2.split("=", 1)[1].strip()
                        break
                _nc2 = _pg2.connect(host="127.0.0.1", dbname="trade_ai", user="trade_ai", password=_dbpw2)
                _nc2.autocommit = True
                _cur2 = _nc2.cursor(cursor_factory=_pge2.RealDictCursor)
                _cur2.execute(
                    "SELECT strategy_id, activated_at, activated_by, pre_activation_defect FROM strategy_activations ORDER BY activated_at DESC"
                )
                _sa_rows = _cur2.fetchall()
                out = []
                for r in _sa_rows:
                    sid = r["strategy_id"]
                    _at = r["activated_at"]
                    days = 0
                    if _at:
                        try:
                            _at_utc = _at.astimezone(_tz.utc) if _at.tzinfo else _at.replace(tzinfo=_tz.utc)
                            days = max(0, int((_dt.now(_tz.utc) - _at_utc).total_seconds() / 86400))
                        except Exception:
                            pass
                    _cur2.execute("SELECT COUNT(*) as c FROM paper_trade_proposals WHERE strategy_id=%s", [sid])
                    props = _cur2.fetchone()["c"]
                    _cur2.execute("SELECT COUNT(*) as c FROM paper_trades WHERE strategy_id=%s", [sid])
                    trades = _cur2.fetchone()["c"]
                    status = (
                        "TOO_EARLY"
                        if days < 1
                        else "ACTIVE"
                        if trades > 0
                        else "PROPOSED_NO_TRADES"
                        if props > 0
                        else "RETIRE_CANDIDATE"
                        if days >= 7
                        else "DORMANT"
                    )
                    out.append(
                        {
                            "strategy_id": sid,
                            "activated_at": _json_clean(_at),
                            "activated_by": r.get("activated_by"),
                            "days_since": days,
                            "proposals_since": props,
                            "trades_since": trades,
                            "status": status,
                        }
                    )
                _nc2.close()
                return 200, {"ok": True, "data": out}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        # ── Screener Config CRUD ──
        if _panel == "screeners":
            if method == "GET":
                try:
                    _raw = (
                        _db_query("""SELECT id, display_name, description, group_name, strategy_class,
                        strategies, finviz_url, run_windows, status, enabled, quality_gates,
                        last_run_at, last_result_count, change_log, created_at, updated_at
                        FROM screener_config ORDER BY group_name, display_name""")
                        or []
                    )
                    rows = []
                    for r in _raw:
                        row = dict(r)
                        for k in ("last_run_at", "created_at", "updated_at"):
                            if row.get(k) and hasattr(row[k], "isoformat"):
                                row[k] = row[k].isoformat()
                        rows.append(row)
                    # Strategy coverage gap analysis
                    ALL_STRATEGIES = [
                        "momentum_scalp",
                        "gap_and_go",
                        "swing_trade",
                        "swing_breakout",
                        "earnings_catalyst",
                        "earnings_post_momentum",
                        "speculative_growth",
                        "fib_retracement_bounce",
                        "recovery_watch",
                        "sector_rotation",
                        "dividend_growth_compounder",
                        "income_add",
                        "covered_call_income",
                        "high_yield_income_bdc",
                        "reit_income",
                        "bond_income",
                        "defense_thesis",
                        "core_growth_compounder",
                        "international_dividend",
                        "core_index",
                    ]
                    covered = set()
                    for r in rows:
                        for s in r.get("strategies") or []:
                            covered.add(s)
                    gaps = [s for s in ALL_STRATEGIES if s not in covered]
                    multi = {}
                    for r in rows:
                        for s in r.get("strategies") or []:
                            multi.setdefault(s, []).append(r["id"])
                    multi_mapped = {s: ids for s, ids in multi.items() if len(ids) > 1}
                    return 200, {
                        "ok": True,
                        "data": {
                            "screeners": rows,
                            "total": len(rows),
                            "strategy_coverage": {
                                "total_strategies": len(ALL_STRATEGIES),
                                "covered": len(covered),
                                "gaps": gaps,
                                "gap_count": len(gaps),
                                "multi_mapped": multi_mapped,
                            },
                        },
                    }
                except Exception as e:
                    return 500, {"ok": False, "error": str(e)}

            if method == "POST":
                try:
                    b = body or {}
                    sid = b.get("id")
                    if not sid:
                        return 400, {"ok": False, "error": "id required"}
                    change_entry = json.dumps(
                        [
                            {
                                "date": datetime.now().strftime("%Y-%m-%d %H:%M"),
                                "action": "created",
                                "note": b.get("change_note", "Created via dashboard"),
                            }
                        ]
                    )
                    _db_query(
                        """INSERT INTO screener_config
                        (id, display_name, description, group_name, strategy_class,
                         strategies, finviz_url, run_windows, status, enabled, quality_gates, change_log)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        [
                            sid,
                            b.get("display_name", sid),
                            b.get("description", ""),
                            b.get("group_name", ""),
                            b.get("strategy_class", ""),
                            b.get("strategies", []),
                            b.get("finviz_url", ""),
                            b.get("run_windows", []),
                            b.get("status", "active"),
                            b.get("enabled", True),
                            json.dumps(b.get("quality_gates", {})),
                            change_entry,
                        ],
                    )
                    return 200, {"ok": True, "message": f"Screener '{sid}' created"}
                except Exception as e:
                    return 500, {"ok": False, "error": str(e)}

        if _panel.startswith("screeners/") and method == "PUT":
            try:
                sid = _panel.split("/", 1)[1]
                b = body or {}
                sets, params = ["updated_at = NOW()"], []
                for fld in ("display_name", "description", "group_name", "strategy_class", "finviz_url", "status"):
                    if fld in b:
                        sets.append(f"{fld} = %s")
                        params.append(b[fld])
                for fld in ("strategies", "run_windows"):
                    if fld in b:
                        sets.append(f"{fld} = %s")
                        params.append(b[fld])
                if "enabled" in b:
                    sets.append("enabled = %s")
                    params.append(b["enabled"])
                if "quality_gates" in b:
                    sets.append("quality_gates = %s::jsonb")
                    params.append(json.dumps(b["quality_gates"]))
                # Append change log entry
                note = b.get("change_note", "Updated via dashboard")
                sets.append("change_log = change_log || %s::jsonb")
                params.append(
                    json.dumps([{"date": datetime.now().strftime("%Y-%m-%d %H:%M"), "action": "updated", "note": note}])
                )
                params.append(sid)
                _db_query(f"UPDATE screener_config SET {', '.join(sets)} WHERE id = %s", params)
                return 200, {"ok": True, "message": f"Screener '{sid}' updated"}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        if _panel.startswith("screeners/") and method == "DELETE":
            try:
                sid = _panel.split("/", 1)[1]
                _db_query(
                    "UPDATE screener_config SET status='deleted', enabled=false, updated_at=NOW(), change_log = change_log || %s::jsonb WHERE id=%s",
                    [
                        json.dumps(
                            [
                                {
                                    "date": datetime.now().strftime("%Y-%m-%d %H:%M"),
                                    "action": "deleted",
                                    "note": "Soft-deleted via dashboard",
                                }
                            ]
                        ),
                        sid,
                    ],
                )
                return 200, {"ok": True, "message": f"Screener '{sid}' disabled"}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)}

        return 404, {"ok": False, "error": f"Unknown strategy-analytics panel: {_panel}"}

    if base_path == "/api/v2/automated-trade-journal":
        try:
            _acct_raw = (query or {}).get("account")
            if isinstance(_acct_raw, list):
                _acct_raw = _acct_raw[0] if _acct_raw else None
            _acct = _acct_raw  # None means all accounts
            _date_from = (query or {}).get("date_from")
            _date_to = (query or {}).get("date_to")
            _where_parts = ["status IN ('open', 'closed')"]
            _params = []
            if _acct:
                _where_parts.append("account = %s")
                _params.append(_acct)
            if _date_from:
                _where_parts.append("created_at >= %s::timestamptz")
                _params.append(_date_from)
            if _date_to:
                _where_parts.append("created_at <= %s::timestamptz")
                _params.append(_date_to)
            _where = " AND ".join(_where_parts)
            trades = (
                _db_query(
                    f"""
                SELECT id, symbol, strategy_id, account, entry_price, exit_price,
                       current_price, shares, stop_loss, target_1, target_2, dollar_risk, dollar_size,
                       COALESCE(pnl, unrealized_pnl) as pnl, unrealized_pnl, r_multiple, pnl_pct,
                       status, outcome_verdict, exit_reason,
                       market_regime, vix_at_entry,
                       catalyst_at_entry, catalyst_verified, intel_readiness,
                       score_at_entry, rvol_at_entry, float_m_at_entry,
                       risk_gate_result, risk_gate_reason_codes,
                       max_favorable_excursion, max_adverse_excursion,
                       planned_entry,
                       COALESCE(entry_slippage, eq.slippage_pct) AS entry_slippage,
                       eq.fill_quality AS entry_fill_quality,
                       planned_stop,
                       COALESCE(stop_slippage,
                                CASE WHEN exit_reason ILIKE '%%stop%%' AND exit_price IS NOT NULL
                                          AND COALESCE(stop_loss, 0) <> 0
                                     THEN ROUND((exit_price - stop_loss)::numeric, 4) END) AS stop_slippage,
                       opened_via, closed_via, logged_by, notes,
                       broker_order_id, broker_status, order_type, broker, client_order_id,
                       bracket_order, take_profit_price, stop_loss_price,
                       submitted_at, filled_at, close_requested_at, close_reason, close_order_id,
                       hold_time_min, proposal_id,
                       post_trade_analyzed, iris_curated, aegis_summarized,
                       entry_time, closed_at, created_at, updated_at
                FROM paper_trades
                LEFT JOIN LATERAL (
                    SELECT slippage_pct, fill_quality FROM paper_execution_quality
                    WHERE paper_trade_id = paper_trades.id
                    ORDER BY created_at DESC LIMIT 1
                ) eq ON TRUE
                WHERE {_where}
                  AND NOT (status = 'open' AND filled_at IS NULL
                           AND broker_status NOT IN ('filled')
                           AND close_reason IS NULL)
                ORDER BY CASE WHEN status='open' THEN 0 ELSE 1 END, created_at DESC
                LIMIT 100
            """,
                    _params,
                )
                or []
            )
            # Fetch full lifecycle events per trade
            _trade_ids = [t["id"] for t in trades if t.get("id")]
            events_by_trade = {}
            if _trade_ids:
                _events = (
                    _db_query(
                        """
                    SELECT paper_trade_id, agent_name, event_type, event_summary,
                           payload, created_at
                    FROM agent_curation_events
                    WHERE paper_trade_id = ANY(%s)
                    ORDER BY created_at ASC
                """,
                        [_trade_ids],
                    )
                    or []
                )
                for ev in _events:
                    tid = ev["paper_trade_id"]
                    events_by_trade.setdefault(tid, []).append({k: _json_clean(v) for k, v in ev.items()})
            # Fetch alerts per trade
            alerts_by_trade = {}
            if _trade_ids:
                _trade_alerts = (
                    _db_query(
                        """
                    SELECT paper_trade_id, alert_type, severity, title, message,
                           data, created_at
                    FROM open_trade_alerts
                    WHERE paper_trade_id = ANY(%s)
                    ORDER BY created_at ASC
                """,
                        [_trade_ids],
                    )
                    or []
                )
                for al in _trade_alerts:
                    tid = al["paper_trade_id"]
                    alerts_by_trade.setdefault(tid, []).append({k: _json_clean(v) for k, v in al.items()})
            # Fetch journal reviews
            reviews_by_symbol = {}
            _syms = list({t["symbol"] for t in trades if t.get("symbol")})
            if _syms:
                _reviews = (
                    _db_query(
                        """
                    SELECT trade_key, symbol, setup_family, setup_name, timeframe,
                           direction, entry_type, exit_type, market_regime, catalyst_type,
                           planned_r, realized_r, followed_plan, well_executed,
                           execution_quality_score, sizing_quality_score, risk_management_score,
                           confidence_before, stress_level,
                           mistake_tags, strength_tags,
                           lesson_learned, review_notes, coach_notes,
                           entry_signals, exit_signals, setup_types,
                           payload, closed_date
                    FROM journal_trade_reviews
                    WHERE symbol = ANY(%s)
                    ORDER BY closed_date DESC
                """,
                        [_syms],
                    )
                    or []
                )
                for rv in _reviews:
                    reviews_by_symbol.setdefault(rv["symbol"], []).append({k: _json_clean(v) for k, v in rv.items()})
            # Fetch Alpaca real-time data for open trades
            _alpaca_live = {}
            try:
                import os, requests as _req

                _akey = os.getenv("ALPACA_API_KEY", "")
                _asec = os.getenv("ALPACA_SECRET_KEY", "")
                if _akey and os.getenv("ENABLE_ALPACA_PAPER", "false").lower() == "true":
                    _hdrs = {"APCA-API-KEY-ID": _akey, "APCA-API-SECRET-KEY": _asec}
                    _pos_resp = _req.get("https://paper-api.alpaca.markets/v2/positions", headers=_hdrs, timeout=5)
                    if _pos_resp.status_code == 200:
                        for _p in _pos_resp.json():
                            _alpaca_live[_p["symbol"]] = {
                                "alpaca_qty": int(float(_p.get("qty", 0))),
                                "alpaca_avg_entry": float(_p.get("avg_entry_price", 0)),
                                "alpaca_current_price": float(_p.get("current_price", 0)),
                                "alpaca_market_value": float(_p.get("market_value", 0)),
                                "alpaca_cost_basis": float(_p.get("cost_basis", 0)),
                                "alpaca_unrealized_pl": float(_p.get("unrealized_pl", 0)),
                                "alpaca_unrealized_plpc": float(_p.get("unrealized_plpc", 0)),
                                "alpaca_intraday_pl": float(_p.get("unrealized_intraday_pl", 0)),
                                "alpaca_intraday_plpc": float(_p.get("unrealized_intraday_plpc", 0)),
                                "alpaca_lastday_price": float(_p.get("lastday_price", 0)),
                                "alpaca_change_today": float(_p.get("change_today", 0)),
                                "alpaca_side": _p.get("side", "long"),
                            }
                    _ord_resp = _req.get(
                        "https://paper-api.alpaca.markets/v2/orders?status=open", headers=_hdrs, timeout=5
                    )
                    if _ord_resp.status_code == 200:
                        for _o in _ord_resp.json():
                            _sym = _o["symbol"]
                            if _sym not in _alpaca_live:
                                _alpaca_live[_sym] = {}
                            _alpaca_live[_sym].setdefault("alpaca_orders", []).append(
                                {
                                    "order_id": _o["id"],
                                    "type": _o.get("type"),
                                    "side": _o.get("side"),
                                    "stop_price": _o.get("stop_price"),
                                    "limit_price": _o.get("limit_price"),
                                    "status": _o.get("status"),
                                    "qty": _o.get("qty"),
                                }
                            )
            except Exception:
                pass
            # Build enriched response
            enriched = []
            for t in trades:
                td = {k: _json_clean(v) for k, v in t.items()}
                td["execution_log"] = events_by_trade.get(t["id"], [])
                td["alerts"] = alerts_by_trade.get(t["id"], [])
                td["journal_reviews"] = reviews_by_symbol.get(t["symbol"], [])
                # Merge Alpaca real-time
                if t["symbol"] in _alpaca_live and t.get("status") == "open":
                    td["alpaca"] = _alpaca_live[t["symbol"]]
                # trade_key for backtest-grade linkage (closed trades)
                _cd = (str(t.get("closed_at") or "")[:10]) if t.get("status") == "closed" else ""
                td["trade_key"] = f"{t.get('symbol', '')}:{t.get('account', '')}:{_cd}"
                enriched.append(td)
            # Enrich closed paper trades with entry/exit grades (join on trade_key)
            _attach_backtest_grades(enriched)
            _open = [t for t in enriched if t.get("status") == "open"]
            _closed = [t for t in enriched if t.get("status") == "closed"]
            # Analytics — only count real trades (non-zero PnL) for win rate
            _real_closed = [t for t in _closed if (t.get("pnl") or 0) != 0]
            _wins = sum(1 for t in _real_closed if (t.get("pnl") or 0) > 0)
            _losses = sum(1 for t in _real_closed if (t.get("pnl") or 0) < 0)
            _total_pnl = round(sum(float(t.get("pnl") or 0) for t in _closed), 2)
            _unrealized = round(sum(float(t.get("unrealized_pnl") or 0) for t in _open), 2)
            _avg_r = round(sum(float(t.get("r_multiple") or 0) for t in _real_closed) / max(len(_real_closed), 1), 2)
            _by_strategy = {}
            for t in _closed:
                s = t.get("strategy_id", "unknown")
                _by_strategy.setdefault(s, {"count": 0, "pnl": 0, "wins": 0})
                _by_strategy[s]["count"] += 1
                _by_strategy[s]["pnl"] += float(t.get("pnl") or 0)
                if (t.get("pnl") or 0) > 0:
                    _by_strategy[s]["wins"] += 1
            return 200, {
                "ok": True,
                "account": _acct,
                "trades": enriched,
                "open": _open,
                "closed": _closed,
                "summary": {
                    "open_count": len(_open),
                    "closed_count": len(_closed),
                    "total_pnl": _total_pnl,
                    "unrealized_pnl": _unrealized,
                    "wins": _wins,
                    "losses": _losses,
                    "win_rate": round(_wins / max(len(_real_closed), 1) * 100, 1),
                    "real_trade_count": len(_real_closed),
                    "avg_r": _avg_r,
                    "by_strategy": [
                        {**v, "strategy": k, "win_rate": round(v["wins"] / max(v["count"], 1) * 100, 1)}
                        for k, v in _by_strategy.items()
                    ],
                },
                "alpaca_connected": bool(_alpaca_live),
                "integrity_warnings": _journal_integrity_warnings(),
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/automated-journal-analytics":
        try:
            _acct_raw2 = (query or {}).get("account")
            if isinstance(_acct_raw2, list):
                _acct_raw2 = _acct_raw2[0] if _acct_raw2 else None
            _acct = _acct_raw2  # None means all accounts
            # Build account filter for analytics
            _ana_where = "status = 'closed' AND closed_at IS NOT NULL"
            _ana_params = []
            if _acct:
                _ana_where += " AND account = %s"
                _ana_params.append(_acct)
            # Daily P&L for calendar heatmap + equity curve
            _daily = (
                _db_query(
                    f"""
                SELECT closed_at::date as trade_date,
                       COUNT(*) as trades,
                       SUM(CASE WHEN pnl > 0 THEN 1 ELSE 0 END) as wins,
                       SUM(CASE WHEN pnl < 0 THEN 1 ELSE 0 END) as losses,
                       ROUND(SUM(pnl)::numeric, 2) as daily_pnl,
                       ROUND(AVG(pnl)::numeric, 2) as avg_pnl,
                       ROUND(AVG(r_multiple)::numeric, 2) as avg_r
                FROM paper_trades
                WHERE {_ana_where}
                GROUP BY closed_at::date
                ORDER BY closed_at::date
            """,
                    _ana_params,
                )
                or []
            )
            # Monthly summary
            _monthly = (
                _db_query(
                    f"""
                SELECT TO_CHAR(closed_at, 'YYYY-MM') as month,
                       COUNT(*) as trades,
                       SUM(CASE WHEN pnl > 0 THEN 1 ELSE 0 END) as wins,
                       SUM(CASE WHEN pnl < 0 THEN 1 ELSE 0 END) as losses,
                       ROUND(SUM(pnl)::numeric, 2) as total_pnl,
                       ROUND(AVG(pnl)::numeric, 2) as avg_pnl,
                       ROUND(AVG(r_multiple)::numeric, 2) as avg_r,
                       ROUND(MAX(pnl)::numeric, 2) as best_trade,
                       ROUND(MIN(pnl)::numeric, 2) as worst_trade
                FROM paper_trades
                WHERE {_ana_where}
                GROUP BY TO_CHAR(closed_at, 'YYYY-MM')
                ORDER BY month
            """,
                    _ana_params,
                )
                or []
            )
            # Weekly summary
            _weekly = (
                _db_query(
                    f"""
                SELECT TO_CHAR(date_trunc('week', closed_at), 'YYYY-MM-DD') as week_start,
                       COUNT(*) as trades,
                       SUM(CASE WHEN pnl > 0 THEN 1 ELSE 0 END) as wins,
                       ROUND(SUM(pnl)::numeric, 2) as total_pnl,
                       ROUND(AVG(r_multiple)::numeric, 2) as avg_r
                FROM paper_trades
                WHERE {_ana_where}
                GROUP BY date_trunc('week', closed_at)
                ORDER BY week_start
            """,
                    _ana_params,
                )
                or []
            )
            # Build equity curve (cumulative P&L)
            _cumulative = 0
            _equity_curve = []
            for d in _daily:
                _cumulative += float(d.get("daily_pnl") or 0)
                _equity_curve.append(
                    {
                        "date": str(d["trade_date"]),
                        "daily_pnl": float(d.get("daily_pnl") or 0),
                        "cumulative_pnl": round(_cumulative, 2),
                        "trades": d.get("trades", 0),
                        "wins": d.get("wins", 0),
                        "losses": d.get("losses", 0),
                    }
                )
            # Unrealized equity (open positions)
            _open_pnl = (
                _db_query(
                    """
                SELECT ROUND(SUM(unrealized_pnl)::numeric, 2) as total
                FROM paper_trades WHERE account = %s AND status = 'open'
            """,
                    [_acct],
                    fetch="one",
                )
                or {}
            )
            return 200, {
                "ok": True,
                "account": _acct,
                "daily": [{k: _json_clean(v) for k, v in d.items()} for d in _daily],
                "equity_curve": _equity_curve,
                "monthly": [{k: _json_clean(v) for k, v in m.items()} for m in _monthly],
                "weekly": [{k: _json_clean(v) for k, v in w.items()} for w in _weekly],
                "current_equity": round(_cumulative + float(_open_pnl.get("total") or 0), 2),
                "realized_total": round(_cumulative, 2),
                "unrealized_total": float(_open_pnl.get("total") or 0),
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/paper-automation-performance":
        try:
            by_source = (
                _db_query("""
                SELECT COALESCE(opened_via, 'unknown') as source,
                    COUNT(*) FILTER (WHERE status='closed') as closed,
                    COUNT(*) FILTER (WHERE status='closed' AND pnl > 0) as wins,
                    ROUND(SUM(pnl) FILTER (WHERE status='closed')::numeric, 2) as pnl
                FROM paper_trades GROUP BY opened_via
            """)
                or []
            )
            overall = (
                _db_query(
                    """
                SELECT COUNT(*) FILTER (WHERE status='closed') as closed_trades,
                    COUNT(*) FILTER (WHERE status='closed' AND pnl > 0) as wins,
                    ROUND(SUM(pnl) FILTER (WHERE status='closed')::numeric, 2) as total_pnl
                FROM paper_trades
            """,
                    fetch="one",
                )
                or {}
            )
            tc = overall.get("closed_trades") or 0
            w = overall.get("wins") or 0
            overall["win_rate"] = round(w / tc, 3) if tc > 0 else None
            return 200, {
                "ok": True,
                "overall": {k: _json_clean(v) for k, v in overall.items()},
                "by_opened_via": [{k: _json_clean(v) for k, v in r.items()} for r in by_source],
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

