    if base_path == "/api/v2/backtesting/filter-options" and method == "GET":
        try:
            # Strategies from actual backtest trades
            _strategies = (
                _db_query(
                    "SELECT DISTINCT strategy_id FROM strategy_backtest_trades WHERE strategy_id IS NOT NULL ORDER BY strategy_id"
                )
                or []
            )
            _strategy_list = [s["strategy_id"] for s in _strategies if s.get("strategy_id")]
            # Date range from backtest trades
            # Date range: use both backtest trades (signal_time) and closed paper_trades (exit_time)
            _bt_dates = (
                _db_query(
                    """
                SELECT MIN(d) as min_date, MAX(d) as max_date FROM (
                    SELECT COALESCE(entry_time, signal_time)::date as d FROM strategy_backtest_trades WHERE COALESCE(entry_time, signal_time) IS NOT NULL
                    UNION ALL
                    SELECT exit_time::date as d FROM paper_trades WHERE exit_time IS NOT NULL
                ) combined
            """,
                    fetch="one",
                )
                or {}
            )
            # Run IDs
            _runs = _db_query("SELECT DISTINCT run_id FROM strategy_backtest_runs ORDER BY run_id DESC LIMIT 50") or []
            _run_list = [r["run_id"] for r in _runs if r.get("run_id")]
            # Run types
            _run_types = (
                _db_query(
                    "SELECT DISTINCT run_type FROM strategy_backtest_runs WHERE run_type IS NOT NULL ORDER BY run_type"
                )
                or []
            )
            _run_type_list = [r["run_type"] for r in _run_types if r.get("run_type")]
            # Brokers/accounts from actual backtest trades data + accounts table
            _bt_brokers = (
                _db_query(
                    "SELECT DISTINCT broker FROM strategy_backtest_trades WHERE broker IS NOT NULL ORDER BY broker"
                )
                or []
            )
            _acct_brokers = (
                _db_query("SELECT DISTINCT broker FROM accounts WHERE broker IS NOT NULL ORDER BY broker") or []
            )
            _broker_set = sorted(
                set(b["broker"] for b in _bt_brokers if b.get("broker"))
                | set(b["broker"] for b in _acct_brokers if b.get("broker"))
            )
            _broker_list = _broker_set
            # Accounts: union of backtest trades + accounts table
            _bt_accts = (
                _db_query(
                    "SELECT DISTINCT account, broker FROM strategy_backtest_trades WHERE account IS NOT NULL ORDER BY broker, account"
                )
                or []
            )
            _acct_tbl = _db_query("SELECT account_label, broker FROM accounts ORDER BY broker, account_label") or []
            _ba_set = {}
            for a in _bt_accts:
                if a.get("account"):
                    _ba_set[a["account"]] = a.get("broker", "")
            for a in _acct_tbl:
                if a.get("account_label") and a["account_label"] not in _ba_set:
                    _ba_set[a["account_label"]] = a.get("broker", "")
            _acct_list = sorted(_ba_set.keys())
            _broker_accounts = [
                {"broker": v, "account_label": k} for k, v in sorted(_ba_set.items(), key=lambda x: (x[1], x[0]))
            ]
            # Data quality: check what percentage of backtest trades have dates
            _total = _db_query("SELECT COUNT(*) as c FROM strategy_backtest_trades", fetch="one")
            _with_dates = _db_query(
                "SELECT COUNT(*) as c FROM strategy_backtest_trades WHERE COALESCE(entry_time, signal_time) IS NOT NULL",
                fetch="one",
            )
            _pct = round(100 * (_with_dates["c"] if _with_dates else 0) / max((_total["c"] if _total else 1), 1), 1)
            _gaps = []
            if _pct < 100:
                _gaps.append(f"{100 - _pct:.0f}% of backtest trades missing entry_time — excluded from date filters")
            if _pct < 100:
                pass  # date gap already added above
            # Broker/account mapped from trade_transactions (Schwab) and paper_trades (Alpaca)
            _unmapped = _db_query(
                "SELECT COUNT(*) as c FROM strategy_backtest_trades WHERE broker IS NULL", fetch="one"
            )
            _unmapped_n = _unmapped["c"] if _unmapped else 0
            if _unmapped_n > 0:
                _gaps.append(
                    f"{_unmapped_n} champion/hypothetical rows have no broker mapping — expected for simulations, not missing real trades"
                )
            return 200, {
                "ok": True,
                "data": {
                    "strategies": _strategy_list,
                    "run_ids": _run_list,
                    "run_types": _run_type_list,
                    "brokers": _broker_list,
                    "accounts": _acct_list,
                    "broker_accounts": _broker_accounts,
                    "minDate": str(_bt_dates.get("min_date") or ""),
                    "maxDate": str(_bt_dates.get("max_date") or ""),
                    "data_quality_gaps": _gaps,
                },
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

