    if base_path == "/api/v2/lifecycle/journal-learning-summary" and method == "GET":
        try:
            import datetime as _dt_jl, os as _os_jl

            _jl_ghost = {
                "duplicate_submit_race",
                "cancelled_never_submitted_to_broker",
                "bogus_duplicate_no_exit_price",
                "duplicate_of_22",
                "orphan_duplicate_from_partial_fill_race",
                "order_canceled_by_alpaca",
                "phantom_never_filled",
                "tos_paper_counterpart_closed",
                "closed_on_different_trade_id",
                "duplicate_unsubmitted_to_broker",
            }
            _jl_open = _db_query(
                "SELECT count(*) as c FROM paper_trades WHERE exit_time IS NULL AND (exit_reason IS NULL OR exit_reason='')"
            ) or [{"c": 0}]
            _jl_closed_all = (
                _db_query(
                    "SELECT id, symbol, strategy_id, entry_price, exit_price, pnl, exit_reason FROM paper_trades WHERE exit_time IS NOT NULL OR (exit_reason IS NOT NULL AND exit_reason!='')"
                )
                or []
            )
            _jl_clean = [r for r in _jl_closed_all if (r.get("exit_reason") or "") not in _jl_ghost]
            _jl_traces = len(_db_query("SELECT 1 FROM lifecycle_trace") or [])
            _jl_traced = len(_db_query("SELECT 1 FROM lifecycle_trace WHERE paper_trade_id IS NOT NULL") or [])
            _jl_tca = len(_db_query("SELECT 1 FROM paper_execution_quality") or [])
            _jl_stop_audit = len(_db_query("SELECT 1 FROM lifecycle_events WHERE stage='stop_change'") or [])
            _jl_dedup = len(_db_query("SELECT 1 FROM proposal_dedup_audit") or [])
            _jl_missed = len(
                _db_query(
                    "SELECT 1 FROM paper_trade_proposals p WHERE p.signal_decision IS NULL AND NOT EXISTS (SELECT 1 FROM paper_trades t WHERE t.symbol=p.symbol AND t.strategy_id=p.strategy_id AND (t.exit_time IS NULL AND (t.exit_reason IS NULL OR t.exit_reason='')))"
                )
                or []
            )

            # Strategy summary
            from collections import defaultdict as _dd_jl

            _jl_strats = _dd_jl(lambda: {"trades": 0, "wins": 0, "total_pnl": 0.0, "r_sum": 0.0})
            for t in _jl_clean:
                sid = t.get("strategy_id") or "unknown"
                _jl_strats[sid]["trades"] += 1
                pnl = float(t["pnl"]) if t.get("pnl") else 0
                _jl_strats[sid]["total_pnl"] += pnl
                if pnl > 0:
                    _jl_strats[sid]["wins"] += 1

            # Include strategy_backtest_trades (all historical trades including V, AXTI, etc.)
            _jl_bt = (
                _db_query(
                    "SELECT symbol, strategy_id, entry_price, exit_price, pnl, r_multiple, exit_reason FROM strategy_backtest_trades"
                )
                or []
            )
            _jl_bt_count = len(_jl_bt)
            _jl_bt_symbols = len(set(r.get("symbol") for r in _jl_bt))
            for t in _jl_bt:
                sid = t.get("strategy_id") or "backtest_unknown"
                _jl_strats[sid]["trades"] += 1
                pnl = float(t["pnl"]) if t.get("pnl") else 0
                _jl_strats[sid]["total_pnl"] += pnl
                if pnl > 0:
                    _jl_strats[sid]["wins"] += 1

            # Rebuild strategy summary with backtest trades included
            _jl_strat_summary = []
            for sid, s in _jl_strats.items():
                _jl_strat_summary.append(
                    {
                        "strategy_id": sid,
                        "strategy_family": {
                            "momentum_scalp": "momentum",
                            "gap_and_go": "momentum",
                            "swing_breakout": "swing",
                            "swing_trade": "swing",
                            "earnings_catalyst": "swing",
                            "dividend_growth_compounder": "income",
                            "reit_income": "income",
                        }.get(sid, "other"),
                        "closed_trade_count": s["trades"],
                        "win_rate": round(s["wins"] / s["trades"], 3) if s["trades"] else 0,
                        "total_pnl": round(s["total_pnl"], 2),
                    }
                )

            _jl_gaps = []
            if _jl_traces - _jl_traced > 0:
                _jl_gaps.append({"gap": "untraced_trades", "count": _jl_traces - _jl_traced})
            if _jl_tca < len(_jl_clean):
                _jl_gaps.append({"gap": "missing_tca", "count": len(_jl_clean) - _jl_tca})
            if _jl_bt_count > 0:
                _jl_gaps.append(
                    {
                        "gap": "backtest_trades_not_in_paper_trades",
                        "count": _jl_bt_count,
                        "note": f"{_jl_bt_symbols} symbols in backtest history (V, AXTI, etc.) not tracked in paper_trades",
                    }
                )

            return 200, {
                "ok": True,
                "data": {
                    "generated_at": _dt_jl.datetime.now(_dt_jl.timezone.utc).isoformat(),
                    "open_trade_count": _jl_open[0]["c"],
                    "closed_trade_count": len(_jl_closed_all),
                    "clean_closed_count": len(_jl_clean),
                    "ghost_count": len(_jl_closed_all) - len(_jl_clean),
                    "backtest_trade_count": _jl_bt_count,
                    "backtest_symbol_count": _jl_bt_symbols,
                    "lifecycle_trace_count": _jl_traces,
                    "traced_closed_trade_count": _jl_traced,
                    "execution_quality_count": _jl_tca,
                    "stop_audit_event_count": _jl_stop_audit,
                    "missed_proposal_count": _jl_missed,
                    "duplicate_groups": _jl_dedup,
                    "duplicate_contamination_status": "clean"
                    if not any(
                        r.get("exit_reason") == "duplicate_submit_race" and not r.get("exit_time")
                        for r in _jl_closed_all
                    )
                    else "contaminated",
                    "strategy_summary": sorted(_jl_strat_summary, key=lambda x: -x["closed_trade_count"]),
                    "data_quality_gaps": _jl_gaps,
                    "safety": {
                        "read_only_endpoint": True,
                        "orders_placed": "NONE",
                        "paper_trades_updated": "NONE",
                        "alpaca_mode": _os_jl.environ.get("ALPACA_MODE", "unknown"),
                    },
                },
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

