    if base_path == "/api/v2/atm/execution-timing-health" and method == "GET":
        try:
            import datetime as _dt_et, os as _os_et

            _et_trades = (
                _db_query("""
                SELECT id AS paper_trade_id, symbol, strategy_id, account,
                       order_submitted_at, order_filled_at, entry_price, stop_loss
                FROM paper_trades
                WHERE entry_price IS NOT NULL
                ORDER BY id DESC LIMIT 50
            """)
                or []
            )
            _et_recs = []
            for t in _et_trades:
                _sub = t.get("order_submitted_at")
                _fill = t.get("order_filled_at")
                _ttf = None
                if _sub and _fill:
                    try:
                        _ttf = round((_fill - _sub).total_seconds(), 2)
                    except Exception:
                        pass
                _missing = []
                if not _sub:
                    _missing.append("order_submitted_at")
                if not _fill:
                    _missing.append("order_filled_at")
                _et_recs.append(
                    {
                        "paper_trade_id": t["paper_trade_id"],
                        "symbol": t["symbol"],
                        "strategy_id": t.get("strategy_id"),
                        "account": t.get("account"),
                        "order_submitted_at": str(_sub) if _sub else None,
                        "order_filled_at": str(_fill) if _fill else None,
                        "time_to_fill_seconds": _ttf,
                        "fill_price": float(t["entry_price"]) if t.get("entry_price") else None,
                        "missing_fields": _missing,
                    }
                )
            _has_sub = sum(1 for r in _et_recs if r["order_submitted_at"])
            _has_fill = sum(1 for r in _et_recs if r["order_filled_at"])
            return 200, {
                "ok": True,
                "data": {
                    "generated_at": _dt_et.datetime.now(_dt_et.timezone.utc).isoformat(),
                    "total_recent_trades": len(_et_recs),
                    "order_submitted_populated": _has_sub,
                    "order_filled_populated": _has_fill,
                    "missing_order_submitted_count": len(_et_recs) - _has_sub,
                    "missing_order_filled_count": len(_et_recs) - _has_fill,
                    "records": _et_recs,
                    "safety": {
                        "read_only_endpoint": True,
                        "orders_placed": "NONE",
                        "stops_modified": "NONE",
                        "alpaca_mode": _os_et.environ.get("ALPACA_MODE", "unknown"),
                    },
                },
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Lifecycle Trace v3.1 ─────────────────────────────────────────────
    if base_path == "/api/v2/lifecycle/trace-summary" and method == "GET":
        try:
            _lt_total = len(_db_query("SELECT 1 FROM lifecycle_trace") or [])
            _lt_with_sig = len(_db_query("SELECT 1 FROM lifecycle_trace WHERE signal_id IS NOT NULL") or [])
            _lt_with_prop = len(_db_query("SELECT 1 FROM lifecycle_trace WHERE proposal_id IS NOT NULL") or [])
            _lt_with_trade = len(_db_query("SELECT 1 FROM lifecycle_trace WHERE paper_trade_id IS NOT NULL") or [])
            _lt_dedup = len(_db_query("SELECT 1 FROM proposal_dedup_audit") or [])
            _lt_dedup_total = sum(
                r.get("duplicate_count", 0)
                for r in (_db_query("SELECT duplicate_count FROM proposal_dedup_audit") or [])
            )
            _lt_events = (
                _db_query("SELECT stage, count(*) as c FROM lifecycle_trace_events GROUP BY stage ORDER BY c DESC")
                or []
            )
            _lt_recent = (
                _db_query(
                    "SELECT trace_id, stage, event_type, source_table, source_id, status, event_time FROM lifecycle_trace_events ORDER BY event_time DESC LIMIT 20"
                )
                or []
            )
            return 200, {
                "ok": True,
                "data": {
                    "total_traces": _lt_total,
                    "signals_linked": _lt_with_sig,
                    "proposals_linked": _lt_with_prop,
                    "trades_linked": _lt_with_trade,
                    "missing_signal_count": _lt_total - _lt_with_sig,
                    "missing_proposal_count": _lt_total - _lt_with_prop,
                    "duplicate_proposal_groups": _lt_dedup,
                    "duplicate_proposal_count": _lt_dedup_total,
                    "events_by_stage": {r["stage"]: r["c"] for r in _lt_events},
                    "latest_events": [{k: _json_clean(v) for k, v in e.items()} for e in _lt_recent],
                    "safety": {"read_only": True},
                },
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/atm/proposal-dedup" and method == "GET":
        try:
            _pd_groups = (
                _db_query("""SELECT duplicate_key, symbol, strategy_id, canonical_proposal_id,
                                            duplicate_proposal_ids, duplicate_count, recommended_action
                                     FROM proposal_dedup_audit ORDER BY duplicate_count DESC""")
                or []
            )
            return 200, {
                "ok": True,
                "data": {
                    "groups": [{k: _json_clean(v) for k, v in g.items()} for g in _pd_groups],
                    "total_groups": len(_pd_groups),
                    "total_duplicate_proposals": sum(g.get("duplicate_count", 0) for g in _pd_groups),
                    "safety": {"read_only": True, "proposals_modified": "NONE"},
                },
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── ATM Proposal Hygiene ───────────────────────────────────────────
    if base_path == "/api/v2/atm/proposal-hygiene" and method == "GET":
        try:
            import datetime as _dt_ph, os as _os_ph
            from collections import Counter as _C_ph, defaultdict as _dd_ph

            _ph_stale_h = 168  # 7 days

            _ph_proposals = (
                _db_query("""
                SELECT id, symbol, strategy_id, signal_score, signal_decision,
                       source_signal_id, created_at, updated_at, proposed_entry,
                       proposed_stop, proposed_target1, proposed_shares, proposed_account,
                       status
                FROM paper_trade_proposals
                ORDER BY COALESCE(updated_at, created_at) DESC NULLS LAST LIMIT 250
            """)
                or []
            )

            _ph_open = (
                _db_query("""
                SELECT id AS paper_trade_id, symbol, strategy_id, account
                FROM paper_trades WHERE exit_time IS NULL AND (exit_reason IS NULL OR exit_reason='')
            """)
                or []
            )

            _ph_open_keys = set(f"{(r.get('symbol') or '').upper()}|{r.get('strategy_id') or ''}" for r in _ph_open)
            _ph_now = _dt_ph.datetime.now(_dt_ph.timezone.utc)

            def _ph_age(ca):
                if not ca:
                    return None
                if isinstance(ca, str):
                    try:
                        ca = _dt_ph.datetime.fromisoformat(ca.replace("Z", "+00:00"))
                    except:
                        return None
                if isinstance(ca, _dt_ph.datetime):
                    if ca.tzinfo is None:
                        ca = ca.replace(tzinfo=_dt_ph.timezone.utc)
                    return round((_ph_now - ca).total_seconds() / 3600, 2)
                return None

            _ph_dup = _C_ph(f"{(r.get('symbol') or '').upper()}|{r.get('strategy_id') or ''}" for r in _ph_proposals)
            _ph_records = []
            for r in _ph_proposals:
                sym = (r.get("symbol") or "").upper()
                sid = r.get("strategy_id") or ""
                key = f"{sym}|{sid}"
                age = _ph_age(r.get("created_at"))
                raw_status = (r.get("status") or "").strip().upper()
                signal_dec = r.get("signal_decision") or ""
                linked = key in _ph_open_keys

                if raw_status in ("EXPIRED",):
                    cls, reason = "expired", "Already expired"
                elif raw_status in ("REJECTED", "RISK_BLOCKED"):
                    cls, reason = "rejected", f"Status: {raw_status}"
                elif linked:
                    cls, reason = "linked_to_open_trade", "Linked to open trade"
                elif _ph_dup.get(key, 0) > 1:
                    cls, reason = "duplicate_candidate", "Duplicate symbol/strategy"
                elif not r.get("id") or not r.get("created_at"):
                    cls, reason = "missing_metadata", "Missing proposal ID or created_at"
                elif age is not None and age <= _ph_stale_h:
                    cls, reason = "recent_pipeline_window", "Within normal pipeline window"
                elif age is not None and age > _ph_stale_h:
                    cls, reason = "stale_needs_review", f"Older than {_ph_stale_h}h threshold"
                else:
                    cls, reason = "unknown", "Insufficient data to classify"

                _ph_records.append(
                    {
                        "proposal_id": r.get("id"),
                        "symbol": sym or "Missing symbol",
                        "strategy_id": sid or "Missing strategy",
                        "status": raw_status or "Missing status",
                        "signal_decision": signal_dec,
                        "created_at": str(r.get("created_at") or ""),
                        "age_hours": age,
                        "score": float(r.get("signal_score")) if r.get("signal_score") else None,
                        "proposed_entry": float(r["proposed_entry"]) if r.get("proposed_entry") else None,
                        "proposed_stop": float(r["proposed_stop"]) if r.get("proposed_stop") else None,
                        "linked_open_trade": linked,
                        "classification": cls,
                        "reason": reason,
                        "stale": cls == "stale_needs_review",
                    }
                )

            _ph_groups = _dd_ph(int)
            for rec in _ph_records:
                _ph_groups[rec["classification"]] += 1

            return 200, {
                "ok": True,
                "data": {
                    "total_count": len(_ph_records),
                    "recent_count": _ph_groups.get("recent_pipeline_window", 0),
                    "stale_count": _ph_groups.get("stale_needs_review", 0),
                    "needs_review_count": _ph_groups.get("stale_needs_review", 0)
                    + _ph_groups.get("missing_metadata", 0)
                    + _ph_groups.get("duplicate_candidate", 0)
                    + _ph_groups.get("unknown", 0),
                    "linked_open_trade_count": _ph_groups.get("linked_to_open_trade", 0),
                    "duplicate_count": _ph_groups.get("duplicate_candidate", 0),
                    "blocked_count": _ph_groups.get("blocked_by_risk", 0),
                    "expired_count": _ph_groups.get("expired", 0),
                    "records": _ph_records,
                    "safety": {
                        "read_only_endpoint": True,
                        "proposals_modified": "NONE",
                        "alpaca_mode": _os_ph.environ.get("ALPACA_MODE", "unknown"),
                    },
                },
            }
        except Exception as e:
            return 500, {"ok": False, "status": "error", "error": str(e)}

    # ── ATM Execution Readiness ──────────────────────────────────────
    if base_path == "/api/v2/atm/execution-readiness" and method == "GET":
        try:
            import datetime as _dt_er, os as _os_er

            _atm = (
                _db_query(
                    "SELECT mode, paused_until, pause_reason, last_evaluated_at, last_enrichment_at FROM atm_state ORDER BY id DESC LIMIT 1",
                    fetch="one",
                )
                or {}
            )
            _pending = (
                _db_query("SELECT COUNT(*) as c FROM paper_trade_proposals WHERE status = 'PENDING'", fetch="one") or {}
            )
            _approved_not_linked = (
                _db_query(
                    "SELECT COUNT(*) as c FROM paper_trade_proposals WHERE status = 'APPROVED_FOR_PAPER_TEST' AND paper_trade_id IS NULL",
                    fetch="one",
                )
                or {}
            )
            _latest_proposal = (
                _db_query("SELECT created_at FROM paper_trade_proposals ORDER BY created_at DESC LIMIT 1", fetch="one")
                or {}
            )
            _latest_trade = (
                _db_query("SELECT created_at FROM paper_trades ORDER BY created_at DESC LIMIT 1", fetch="one") or {}
            )
            _recent_decisions = (
                _db_query("""
                SELECT decision, rejection_reasons, symbol, decided_at
                FROM atm_decision_log WHERE decided_at > NOW() - INTERVAL '24 hours'
                ORDER BY decided_at DESC LIMIT 20
            """)
                or []
            )
            # Top block reasons
            _reasons = {}
            for d in _recent_decisions:
                rr = d.get("rejection_reasons") or []
                if isinstance(rr, str):
                    try:
                        import json as _j

                        rr = _j.loads(rr)
                    except:
                        rr = []
                for r in rr:
                    g = r.get("gate", "unknown") if isinstance(r, dict) else str(r)
                    _reasons[g] = _reasons.get(g, 0) + 1
            _top_reasons = sorted(_reasons.items(), key=lambda x: -x[1])[:5]
            _alpaca = _os_er.environ.get("ALPACA_MODE", "unknown")
            _llm_dis = _os_er.environ.get("LLM_DISABLE_LIVE_EXECUTION", "unknown")
            return 200, {
                "ok": True,
                "data": {
                    "atm_mode": _atm.get("mode", "unknown"),
                    "paused_until": _json_clean(_atm.get("paused_until")),
                    "pause_reason": _atm.get("pause_reason"),
                    "alpaca_mode": _alpaca,
                    "llm_disable_live_execution": _llm_dis,
                    "pending_proposals": _pending.get("c", 0),
                    "approved_not_submitted": _approved_not_linked.get("c", 0),
                    "latest_proposal": _json_clean(_latest_proposal.get("created_at")),
                    "latest_paper_trade": _json_clean(_latest_trade.get("created_at")),
                    "last_atm_evaluation": _json_clean(_atm.get("last_evaluated_at")),
                    "last_enrichment": _json_clean(_atm.get("last_enrichment_at")),
                    "recent_decisions_24h": len(_recent_decisions),
                    "top_block_reasons": [{"gate": g, "count": c} for g, c in _top_reasons],
                    "can_submit_now": _alpaca == "paper" and _atm.get("mode") == "active" and _pending.get("c", 0) > 0,
                    "status_summary": "No pending proposals"
                    if _pending.get("c", 0) == 0
                    else f"{_pending.get('c', 0)} pending, ATM {_atm.get('mode', 'unknown')}",
                },
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── ATM Reconciliation Health ──────────────────────────────────────
    if base_path == "/api/v2/atm/reconciliation-health" and method == "GET":
        try:
            import datetime as _dt_rh, os as _os_rh
            from pathlib import Path as _P_rh

            def _rh_safe_iso(v):
                if v is None:
                    return None
                if isinstance(v, _dt_rh.datetime):
                    return v.astimezone(_dt_rh.timezone.utc).replace(microsecond=0).isoformat()
                return str(v)

            _rh_latest = _db_query(
                """
                SELECT run_id, started_at, completed_at, mode, journal_source,
                       db_open_count, journal_open_count, matched_count, mismatch_count,
                       duplicate_count, mirror_account_count, missing_identifier_count, status
                FROM atm_position_reconciliation_runs ORDER BY started_at DESC LIMIT 1
            """,
                fetch="one",
            )

            if not _rh_latest:
                # JSON fallback
                _rh_path = PROJECT_ROOT / "logs" / "atm_position_reconciliation" / "latest.json"
                if _rh_path.exists():
                    import json as _rh_j

                    _rh_latest = _rh_j.loads(_rh_path.read_text())

            if not _rh_latest:
                return 200, {
                    "ok": True,
                    "status": "no_data",
                    "status_label": "No reconciliation run data yet.",
                    "db_open_count": 0,
                    "journal_open_count": 0,
                    "matched_count": 0,
                    "mismatch_count": 0,
                    "cron_fresh": False,
                    "safety": {"read_only_endpoint": True, "audit_only_mode": True},
                }

            _rh_completed = _rh_latest.get("completed_at") or _rh_latest.get("started_at")
            if isinstance(_rh_completed, str):
                try:
                    _rh_completed = _dt_rh.datetime.fromisoformat(_rh_completed.replace("Z", "+00:00"))
                except:
                    _rh_completed = None
            if _rh_completed and _rh_completed.tzinfo is None:
                _rh_completed = _rh_completed.replace(tzinfo=_dt_rh.timezone.utc)

            _rh_now = _dt_rh.datetime.now(_dt_rh.timezone.utc)
            _rh_age = round((_rh_now - _rh_completed).total_seconds() / 60, 1) if _rh_completed else None
            _rh_mm = int(_rh_latest.get("mismatch_count") or 0)
            _rh_db = int(_rh_latest.get("db_open_count") or 0)
            _rh_jo = int(_rh_latest.get("journal_open_count") or 0)
            _rh_ma = int(_rh_latest.get("matched_count") or 0)

            _rh_thresh = 30 if (_rh_now.weekday() < 5 and 13 <= _rh_now.hour <= 22) else 1440
            _rh_fresh = bool(_rh_age is not None and _rh_age <= _rh_thresh)

            if _rh_mm > 0:
                _rh_status, _rh_label = "mismatch", f"{_rh_mm} reconciliation mismatch(es)"
            elif _rh_db == _rh_jo == _rh_ma:
                _rh_status, _rh_label = "healthy", "DB-open matches journal-open"
            elif _rh_age and _rh_age > _rh_thresh:
                _rh_status, _rh_label = "stale", f"Latest run {_rh_age}m old (threshold {_rh_thresh}m)"
            else:
                _rh_status, _rh_label = "warning", "Counts not perfectly aligned"

            _rh_items = []
            _rh_rid = _rh_latest.get("run_id")
            if _rh_rid:
                _rh_items = (
                    _db_query(
                        """
                    SELECT paper_trade_id, symbol, strategy_id, account, classification, severity, reason
                    FROM atm_position_reconciliation_items WHERE run_id=%s ORDER BY severity DESC, symbol
                """,
                        [_rh_rid],
                    )
                    or []
                )

            return 200, {
                "ok": True,
                "status": _rh_status,
                "status_label": _rh_label,
                "last_run_id": _rh_rid,
                "last_run_at": _rh_safe_iso(_rh_completed),
                "age_minutes": _rh_age,
                "cron_fresh": _rh_fresh,
                "mode": _rh_latest.get("mode") or "audit_only",
                "journal_source": _rh_latest.get("journal_source"),
                "db_open_count": _rh_db,
                "journal_open_count": _rh_jo,
                "matched_count": _rh_ma,
                "mismatch_count": _rh_mm,
                "unresolved_items": [i for i in _rh_items if (i.get("classification") or "") != "matched_open"],
                "latest_items": [{k: _json_clean(v) for k, v in i.items()} for i in _rh_items],
                "safety": {
                    "read_only_endpoint": True,
                    "audit_only_mode": True,
                    "alpaca_mode": _os_rh.environ.get("ALPACA_MODE", "unknown"),
                    "llm_disable": _os_rh.environ.get("LLM_DISABLE_LIVE_EXECUTION", "unknown"),
                },
            }
        except Exception as e:
            return 500, {"ok": False, "status": "error", "error": str(e)}

    if base_path == "/api/v2/atm/close-preview" and method == "GET":
        try:
            _cp_tid = int((query or {}).get("paper_trade_id", 0))
            if not _cp_tid:
                return 400, {"ok": False, "error": "paper_trade_id required"}

            _cp_trade = _db_query("SELECT * FROM paper_trades WHERE id=%s", (_cp_tid,), fetch="one")
            if not _cp_trade:
                return 404, {"ok": False, "error": f"Trade {_cp_tid} not found"}

            from strategy_trailing_policy import get_trailing_policy as _gtp_cp

            _cp_pol = _gtp_cp(_cp_trade.get("strategy_id", ""))
            _cp_tsc = _cp_pol.get("time_stop", {})

            import os as _cp_os

            _cp_alpaca = _cp_os.environ.get("ALPACA_MODE", "paper")
            _cp_disable = _cp_os.environ.get("LLM_DISABLE_LIVE_EXECUTION", "true")
            _cp_acct = _cp_trade.get("account", "")
            _cp_open = not _cp_trade.get("exit_time") and not _cp_trade.get("exit_reason")
            _cp_qty = float(_cp_trade.get("shares") or 0)
            _cp_entry = float(_cp_trade["entry_price"]) if _cp_trade.get("entry_price") else None
            _cp_stop = float(_cp_trade["stop_loss"]) if _cp_trade.get("stop_loss") else None

            # Existing close actions today
            _cp_existing = _db_query(
                """SELECT 1 FROM atm_close_actions
                WHERE paper_trade_id=%s AND action='submit_paper_close_order'
                AND created_at::date=CURRENT_DATE""",
                (_cp_tid,),
            )

            _cp_gates = {
                "alpaca_mode_paper": _cp_alpaca == "paper",
                "live_execution_disabled": str(_cp_disable).lower() == "true",
                "account_is_paper": "paper" in _cp_acct.lower() if _cp_acct else False,
                "position_is_open": _cp_open,
                "quantity_positive": _cp_qty > 0,
                "no_close_submitted_today": not _cp_existing,
            }
            _cp_can_submit = all(_cp_gates.values())
            _cp_blocked = [k for k, v in _cp_gates.items() if not v]

            _cp_est_exit = _cp_entry  # conservative: use entry as estimate
            _cp_est_pnl = 0.0
            _cp_est_pnl_pct = 0.0
            if _cp_entry and _cp_qty:
                _cp_est_pnl = round((_cp_est_exit - _cp_entry) * _cp_qty, 2)
                _cp_est_pnl_pct = round(((_cp_est_exit / _cp_entry) - 1) * 100, 2) if _cp_entry else 0

            _cp_stop_impl = "Stop order should be cancelled after close" if _cp_stop else "No stop to cancel"

            return 200, {
                "ok": True,
                "data": {
                    "paper_trade_id": _cp_tid,
                    "symbol": _cp_trade["symbol"],
                    "strategy_id": _cp_trade.get("strategy_id"),
                    "strategy_family": _cp_pol.get("family", "unknown"),
                    "account": _cp_acct,
                    "side": "sell",
                    "quantity": _cp_qty,
                    "entry_price": _cp_entry,
                    "estimated_exit_price": _cp_est_exit,
                    "estimated_pnl": _cp_est_pnl,
                    "estimated_pnl_pct": _cp_est_pnl_pct,
                    "db_stop": _cp_stop,
                    "stop_implication": _cp_stop_impl,
                    "time_stop_type": _cp_tsc.get("type", "unknown"),
                    "close_reason": "operator_manual_close_review",
                    "safety_gates": _cp_gates,
                    "can_submit_paper_close": _cp_can_submit,
                    "cannot_submit_reasons": _cp_blocked,
                    "confirmation_required": "SUBMIT PAPER CLOSE ONLY",
                },
            }
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/atm/close-action" and method == "POST":
        try:
            import hashlib as _ca_hash, datetime as _ca_dt, os as _ca_os

            _ca_dangerous = {"execute", "quantity", "price", "broker_order", "order_type", "limit_price"}
            if body and any(k in _ca_dangerous for k in body.keys()):
                return 400, {"ok": False, "error": "Raw execution fields not allowed."}

            _ca_tid = (body or {}).get("paper_trade_id")
            _ca_sym = (body or {}).get("symbol", "")
            _ca_action = (body or {}).get("action", "")
            _ca_confirm = (body or {}).get("confirmation_text", "")
            _ca_note = (body or {}).get("operator_note", "")
            _ca_preview = (body or {}).get("close_preview_id")

            _ca_allowed = {
                "mark_closed_outside_system",
                "submit_paper_close_order",
                "cancel_close_preview",
                "keep_open_after_preview",
            }
            if _ca_action not in _ca_allowed:
                return 400, {"ok": False, "error": f"Invalid action. Allowed: {', '.join(sorted(_ca_allowed))}"}
            if not _ca_tid or not _ca_sym:
                return 400, {"ok": False, "error": "paper_trade_id and symbol required"}

            _ca_id = f"ca-{_ca_hash.sha256(f'{_ca_sym}:{_ca_tid}:{_ca_dt.datetime.now().isoformat()}'.encode()).hexdigest()[:12]}"
            _ca_status = "recorded"
            _ca_broker_id = None
            _ca_error = None

            if _ca_action == "submit_paper_close_order":
                if _ca_confirm != "SUBMIT PAPER CLOSE ONLY":
                    return 400, {"ok": False, "error": "Confirmation text must be exactly: SUBMIT PAPER CLOSE ONLY"}
                if _ca_os.environ.get("ALPACA_MODE", "") != "paper":
                    return 400, {"ok": False, "error": "ALPACA_MODE is not paper. Cannot submit."}
                if str(_ca_os.environ.get("LLM_DISABLE_LIVE_EXECUTION", "")).lower() != "true":
                    return 400, {"ok": False, "error": "LLM_DISABLE_LIVE_EXECUTION is not true."}

                # Get trade details from DB
                _ca_trade = _db_query("SELECT * FROM paper_trades WHERE id=%s", (_ca_tid,), fetch="one")
                if not _ca_trade:
                    return 404, {"ok": False, "error": f"Trade {_ca_tid} not found"}
                if _ca_trade.get("exit_time") or (_ca_trade.get("exit_reason") and _ca_trade["exit_reason"] != ""):
                    return 400, {"ok": False, "error": "Position already closed or has exit reason"}
                if _ca_trade["symbol"] != _ca_sym:
                    return 400, {"ok": False, "error": "Symbol mismatch"}
                if "paper" not in (_ca_trade.get("account") or "").lower():
                    return 400, {"ok": False, "error": "Not a paper account"}

                # Submit paper close via Alpaca adapter
                try:
                    from alpaca_paper_adapter import close_position as _close_pos

                    _ca_qty = int(_ca_trade.get("shares") or 0)
                    _ca_result = _close_pos(_ca_sym, _ca_qty)
                    _ca_broker_id = _ca_result.get("order_id") if isinstance(_ca_result, dict) else str(_ca_result)
                    _ca_status = "submitted"
                except Exception as _ca_e:
                    _ca_error = str(_ca_e)[:500]
                    _ca_status = "submit_failed"

            elif _ca_action == "mark_closed_outside_system":
                _ca_status = "external_close_marked"

            # Record the action
            _ca_conn = None
            try:
                from db_adapter import _get_conn as _gc_ca

                _ca_conn = _gc_ca()
                _cur = _ca_conn.cursor()
                _cur.execute(
                    """INSERT INTO atm_close_actions
                    (close_action_id, operator, close_preview_id, lifecycle_id, paper_trade_id,
                     symbol, action, action_status, safety_confirmation, broker_order_id, error)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                    [
                        _ca_id,
                        "john",
                        _ca_preview,
                        (body or {}).get("lifecycle_id"),
                        _ca_tid,
                        _ca_sym,
                        _ca_action,
                        _ca_status,
                        _ca_confirm,
                        _ca_broker_id,
                        _ca_error,
                    ],
                )
                _ca_conn.commit()

                # Lifecycle event
                try:
                    _cur.execute(
                        """INSERT INTO lifecycle_events
                        (lifecycle_id, stage, event_type, status, symbol, strategy_id,
                         paper_trade_id, source_script, payload)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        [
                            (body or {}).get("lifecycle_id") or f"ca-{_ca_tid}",
                            "close_review",
                            _ca_action,
                            _ca_status,
                            _ca_sym,
                            (body or {}).get("strategy_id"),
                            _ca_tid,
                            "api_v2.py",
                            __import__("json").dumps({"action": _ca_action, "status": _ca_status}),
                        ],
                    )
                    _ca_conn.commit()
                except Exception:
                    try:
                        _ca_conn.rollback()
                    except:
                        pass
            finally:
                if _ca_conn:
                    try:
                        _ca_conn.close()
                    except:
                        pass

            _ca_msg = {
                "mark_closed_outside_system": "External close marked. No order was placed.",
                "submit_paper_close_order": f"Paper close order submitted. Broker ID: {_ca_broker_id}"
                if _ca_status == "submitted"
                else f"Submit failed: {_ca_error}",
                "cancel_close_preview": "Close preview cancelled. No order was placed.",
                "keep_open_after_preview": "Decision recorded: keep open. No order was placed.",
            }

            return 200, {
                "ok": True,
                "data": {
                    "close_action_id": _ca_id,
                    "action": _ca_action,
                    "action_status": _ca_status,
                    "broker_order_id": _ca_broker_id,
                    "error": _ca_error,
                    "safety_message": _ca_msg.get(_ca_action, "Action recorded."),
                    "no_live_trading_confirmation": True,
                },
            }
        except Exception as e:
            import traceback

            traceback.print_exc()
